window.HSK_DATA["3"] = [{"id":"安排","hanzi":"安排","pinyin":"ānpái","meaning_vi":"sắp xếp, bố trí","explanation":"安 (yên ổn) + 排 (xếp hàng). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📅","examples":[{"type":"basic","zh":"我来安排时间。","pinyin":"Wǒ lái ānpái shíjiān.","vi":"Để tôi sắp xếp thời gian."},{"type":"simple","zh":"公司已经安排王经理下周去上海出差。","pinyin":"Gōngsī yǐjīng ānpái Wáng jīnglǐ xiàzhōu qù Shànghǎi chūchāi.","vi":"Công ty đã sắp xếp giám đốc Vương tuần sau đi Thượng Hải công tác."},{"type":"compound","zh":"虽然这次旅游的行程安排得很紧，但是大家都玩得非常开心。","pinyin":"Suīrán zhè cì lǚyóu de xíngchéng ānpái de hěn jǐn, dànshì dàjiā dōu wán de fēicháng kāixīn.","vi":"Tuy lịch trình chuyến du lịch lần này sắp xếp rất dày nhưng ai nấy đều chơi vô cùng vui vẻ."}],"related":[{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"排队","pinyin":"páiduì","vi":"Xếp hàng"},{"hanzi":"计划","pinyin":"jìhuà","vi":"Kế hoạch"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"}]},{"id":"帮忙","hanzi":"帮忙","pinyin":"bāngmáng","meaning_vi":"giúp đỡ, giúp một tay","explanation":"帮 (giúp) + 忙 (bận). Động từ ly hợp (帮个忙 - giúp một việc).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"你能帮个忙吗？","pinyin":"Nǐ néng bāng ge máng ma?","vi":"Bạn có thể giúp một tay không?"},{"type":"simple","zh":"搬家的时候，很多好朋友都主动过来帮忙。","pinyin":"Bānjiā de shíhou, hěn duō hǎopéngyou dōu zhǔdòng guòlái bāngmáng.","vi":"Lúc chuyển nhà, rất nhiều bạn thân đều chủ động qua giúp đỡ."},{"type":"compound","zh":"虽然他自己工作也很忙，但是只要朋友开口请他帮忙，他从来不拒绝。","pinyin":"Suīrán tā zìjǐ gōngzuò yě hěn máng, dànshì zhǐyào péngyou kāikǒu qǐng tā bāngmáng, tā cóngláibú jùjué.","vi":"Tuy bản thân anh ấy công việc cũng rất bận nhưng chỉ cần bạn bè mở lời nhờ giúp đỡ thì anh ấy không bao giờ từ chối."}],"related":[{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"帮","pinyin":"bāng","vi":"Giúp"},{"hanzi":"忙","pinyin":"máng","vi":"Bận"},{"hanzi":"热心","pinyin":"rèxīn","vi":"Nhiệt tình"},{"hanzi":"感谢","pinyin":"gǎnxiè","vi":"Cảm tạ"}],"traditional":"幫忙"},{"id":"饱","hanzi":"饱","pinyin":"bǎo","meaning_vi":"no","explanation":"Bộ thực 饣+ 包. Đối nghĩa với 饿 (đói).","hsk_level":3,"tags":["tinh-tu","an-uong"],"image":"😋","examples":[{"type":"basic","zh":"我已经吃饱了。","pinyin":"Wǒ yǐjīng chībǎo le.","vi":"Tôi đã ăn no rồi."},{"type":"simple","zh":"今天妈妈做的饺子特别香，我一口气吃得饱饱的。","pinyin":"Jīntiān māma zuò de jiǎozi tèbié xiāng, wǒ yìkǒuqì chī de bǎo bǎo de.","vi":"Hôm nay sủi cảo mẹ làm đặc biệt thơm ngon, tôi ăn một mạch no căng bụng."},{"type":"compound","zh":"晚上睡觉前不要吃得太饱，否则不仅影响睡眠，还对胃不好。","pinyin":"Wǎnshang shuìjiào qián bú yào chī de tài bǎo, fǒuzé bùjǐn yǐngxiǎng shuìmián, hái duì wèi bù hǎo.","vi":"Buổi tối trước khi đi ngủ đừng ăn quá no, nếu không chẳng những ảnh hưởng giấc ngủ mà còn hại dạ dày."}],"related":[{"hanzi":"饿","pinyin":"è","vi":"Đói"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"Ăn cơm"},{"hanzi":"吃","pinyin":"chī","vi":"Ăn"},{"hanzi":"满","pinyin":"mǎn","vi":"Đầy"},{"hanzi":"包子","pinyin":"bāozi","vi":"Bánh bao"}],"traditional":"飽"},{"id":"比较","hanzi":"比较","pinyin":"bǐjiào","meaning_vi":"tương đối, khá; so sánh","explanation":"比 (so) + 较 (đối chiếu). Thường làm phó từ đứng trước tính từ.","hsk_level":3,"tags":["pho-tu","dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"今天天气比较冷。","pinyin":"Jīntiān tiānqì bǐjiào lěng.","vi":"Hôm nay thời tiết tương đối lạnh."},{"type":"simple","zh":"我觉得这家饭店的菜味道比较清淡，很适合老人和孩子。","pinyin":"Wǒ juéde zhè jiā fàndiàn de cài wèidào bǐjiào qīngdàn, hěn shìhé lǎorén hé háizi.","vi":"Tôi cảm thấy hương vị món ăn của nhà hàng này khá thanh đạm, rất hợp với người già và trẻ nhỏ."},{"type":"compound","zh":"相比坐公共汽车，我比较喜欢坐地铁上班，因为地铁既准时又不会堵车。","pinyin":"Xiāngbǐ zuò gōnggòngqìchē, wǒ bǐjiào xǐhuan zuò dìtiě shàngbān, yīnwèi dìtiě jì zhǔnshí yòu bú huì dǔchē.","vi":"So với đi xe buýt, tôi thích đi tàu điện ngầm đi làm hơn vì tàu điện ngầm vừa đúng giờ lại không tắc đường."}],"related":[{"hanzi":"比","pinyin":"bǐ","vi":"So với"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"较","pinyin":"jiào","vi":"So sánh"},{"hanzi":"挺","pinyin":"tǐng","vi":"Khá là"},{"hanzi":"非常","pinyin":"fēicháng","vi":"Vô cùng"}],"traditional":"比較"},{"id":"比赛","hanzi":"比赛","pinyin":"bǐsài","meaning_vi":"thi đấu, trận đấu","explanation":"比 (so tài) + 赛 (thi đua). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"明天有足球比赛。","pinyin":"Míngtiān yǒu zúqiú bǐsài.","vi":"Ngày mai có trận đấu bóng đá."},{"type":"simple","zh":"我们班的同学正在积极准备下个月的汉语演讲比赛。","pinyin":"Wǒmen bān de tóngxué zhèngzài jījí zhǔnbèi xiàgeyuè de Hànyǔ yǎnjiǎng bǐsài.","vi":"Các bạn học lớp chúng tôi đang tích cực chuẩn bị cho cuộc thi hùng biện tiếng Trung tháng sau."},{"type":"compound","zh":"虽然我们队在今天的篮球比赛中输了，但是大家在场上的表现非常精彩。","pinyin":"Suīrán wǒmen duì zài jīntiān de lánqiú bǐsài zhōng shū le, dànshì dàjiā zài chǎng shang de biǎoxiàn fēicháng jīngcǎi.","vi":"Tuy đội chúng tôi đã thua trong trận bóng rổ hôm nay nhưng màn thể hiện trên sân của mọi người vô cùng xuất sắc."}],"related":[{"hanzi":"比较","pinyin":"bǐjiào","vi":"So sánh"},{"hanzi":"比","pinyin":"bǐ","vi":"So với"},{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"},{"hanzi":"赢","pinyin":"yíng","vi":"Thắng"},{"hanzi":"输","pinyin":"shū","vi":"Thua"}],"traditional":"比賽"},{"id":"表示","hanzi":"表示","pinyin":"biǎoshì","meaning_vi":"biểu thị, bày tỏ","explanation":"表 (bên ngoài) + 示 (cho thấy).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"他表示同意。","pinyin":"Tā biǎoshì tóngyì.","vi":"Anh ấy bày tỏ sự đồng ý."},{"type":"simple","zh":"全班同学送给王老师一束鲜花，表示对老师的感谢。","pinyin":"Quánbān tóngxué sònggěi Wáng lǎoshī yí shù xiānhuā, biǎoshì duì lǎoshī de gǎnxiè.","vi":"Cả lớp tặng thầy Vương một bó hoa tươi để bày tỏ lòng biết ơn đối với thầy."},{"type":"compound","zh":"虽然他没有说话，但是他点了点头，表示同意。","pinyin":"Suīrán tā méiyǒu shuōhuà, dànshì tā diǎnle diǎntóu, biǎoshì tóngyì.","vi":"Tuy anh ấy không nói gì nhưng đã gật đầu tỏ ý đồng ý."}],"related":[{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"Biểu diễn"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"},{"hanzi":"手表","pinyin":"shǒubiǎo","vi":"Đồng hồ"},{"hanzi":"表达","pinyin":"biǎodá","vi":"Biểu đạt"},{"hanzi":"意思","pinyin":"yìsi","vi":"Ý nghĩa"}]},{"id":"表演","hanzi":"表演","pinyin":"biǎoyǎn","meaning_vi":"biểu diễn","explanation":"表 (thể hiện) + 演 (diễn xuất). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"她的表演很精彩。","pinyin":"Tā de biǎoyǎn hěn jīngcǎi.","vi":"Màn biểu diễn của cô ấy rất đặc sắc."},{"type":"simple","zh":"春节联欢晚会上，留学生们表演了一个有趣的中文小品。","pinyin":"Chūnjiéliánhuānwǎnhuì shang, liúxuéshengmen biǎoyǎnle yí ge yǒuqù de Zhōngwén xiǎopǐn.","vi":"Tại đêm hội mừng xuân, các du học sinh đã biểu diễn một tiểu phẩm tiếng Trung rất thú vị."},{"type":"compound","zh":"因为她从小就学习跳舞，所以在舞台上的每一次表演都显得非常自信。","pinyin":"Yīnwèi tā cóngxiǎo jiù xuéxí tiàowǔ, suǒyǐ zài wǔtái shang de měi yí cì biǎoyǎn dōu xiǎnde fēicháng zìxìn.","vi":"Vì từ nhỏ cô ấy đã học múa nên mỗi lần biểu diễn trên sân khấu đều tỏ ra vô cùng tự tin."}],"related":[{"hanzi":"表示","pinyin":"biǎoshì","vi":"Biểu thị"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"Biểu diễn"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"Diễn viên"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"Đặc sắc"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"Khán giả"}]},{"id":"表扬","hanzi":"表扬","pinyin":"biǎoyáng","meaning_vi":"khen ngợi, biểu dương","explanation":"表 (nêu lên) + 扬 (ca ngợi). Đối nghĩa với 批评 (phê bình).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"老师表扬了我。","pinyin":"Lǎoshī biǎoyángle wǒ.","vi":"Thầy giáo đã khen ngợi tôi."},{"type":"simple","zh":"因为小明主动把捡到的钱包交给了警察，所以受到了学校的表扬。","pinyin":"Yīnwèi xiǎo míng zhǔdòng bǎ jiǎn dào de qiánbāo jiāogěile jǐngchá, suǒyǐ shòudàole xuéxiào de biǎoyáng.","vi":"Vì Tiểu Minh chủ động nộp chiếc ví nhặt được cho cảnh sát nên đã nhận được lời khen ngợi của nhà trường."},{"type":"compound","zh":"孩子取得进步的时候，父母应该多给予表扬和鼓励，少一些批评。","pinyin":"Háizi qǔdé jìnbù de shíhou, fùmǔ yīnggāi duō jǐyǔ biǎoyáng hé gǔlì, shǎo yìxiē pīpíng.","vi":"Khi trẻ đạt được tiến bộ, bố mẹ nên khen ngợi và khích lệ nhiều hơn, bớt phê bình lại."}],"related":[{"hanzi":"批评","pinyin":"pīpíng","vi":"Phê bình"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"Khích lệ"},{"hanzi":"表示","pinyin":"biǎoshì","vi":"Biểu thị"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"优秀","pinyin":"yōuxiù","vi":"Xuất sắc"}],"traditional":"表揚"},{"id":"批评","hanzi":"批评","pinyin":"pīpíng","meaning_vi":"phê bình, chỉ trích","explanation":"批 (phê duyệt) + 评 (bình luận). Đối nghĩa với 表扬 (khen ngợi).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"经理批评了他。","pinyin":"Jīnglǐ pīpíngle tā.","vi":"Giám đốc đã phê bình anh ấy."},{"type":"simple","zh":"因为经常上班迟到，小李今天早上被部门经理批评了一顿。","pinyin":"Yīnwèi jīngcháng shàngbān chídào, xiǎo Lǐ jīntiān zǎoshang bèi bùmén jīnglǐ pīpíngle yí dùn.","vi":"Vì thường xuyên đi làm muộn, sáng nay Tiểu Lý đã bị trưởng phòng phê bình một trận."},{"type":"compound","zh":"虽然老师的批评听起来有点儿严厉，但是其实都是为了我们好。","pinyin":"Suīrán lǎoshī de pīpíng tīngqǐlái yǒudiǎnr yánlì, dànshì qíshí dōu shì wèile wǒmen hǎo.","vi":"Tuy lời phê bình của thầy giáo nghe có vẻ hơi nghiêm khắc nhưng thực ra đều là muốn tốt cho chúng ta."}],"related":[{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"},{"hanzi":"评论","pinyin":"pínglùn","vi":"Bình luận"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"严格","pinyin":"yángé","vi":"Nghiêm khắc"},{"hanzi":"接受","pinyin":"jiēshòu","vi":"Tiếp nhận"}],"traditional":"批評"},{"id":"参观","hanzi":"参观","pinyin":"cānguān","meaning_vi":"tham quan","explanation":"参 (tham dự) + 观 (ngắm nhìn). Dùng cho bảo tàng, nhà máy, trường học.","hsk_level":3,"tags":["dong-tu","du-lich"],"image":"🏛️","examples":[{"type":"basic","zh":"我们去参观博物馆。","pinyin":"Wǒmen qù cānguān bówùguǎn.","vi":"Chúng tôi đi tham quan bảo tàng."},{"type":"simple","zh":"昨天下午学校组织留学生去参观了北京故宫和长城。","pinyin":"Zuótiān xiàwǔ xuéxiào zǔzhī liúxuésheng qù cānguānle Běijīng gùgōng hé Chángchéng.","vi":"Chiều hôm qua nhà trường đã tổ chức cho du học sinh đi tham quan Cố Cung Bắc Kinh và Vạn Lý Trường Thành."},{"type":"compound","zh":"在参观图书馆的时候，大家一定要保持安静，不要大声说话和拍照。","pinyin":"Zài cānguān túshūguǎn de shíhou, dàjiā yídìngyào bǎochí ānjìng, bú yào dàshēng shuōhuà hé pāizhào.","vi":"Khi tham quan thư viện, mọi người nhất định phải giữ yên lặng, đừng nói chuyện lớn tiếng và chụp ảnh."}],"related":[{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"Khán giả"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"历史","pinyin":"lìshǐ","vi":"Lịch sử"},{"hanzi":"展览","pinyin":"zhǎnlǎn","vi":"Triển lãm"}],"traditional":"參觀"},{"id":"查","hanzi":"查","pinyin":"chá","meaning_vi":"tra, kiểm tra, tìm","explanation":"Bộ mộc 木 + 且. Dùng trong 查词典 (tra từ điển), 查资料 (tìm tài liệu).","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"🔎","examples":[{"type":"basic","zh":"我查一下词典。","pinyin":"Wǒ chá yíxià cídiǎn.","vi":"Tôi tra từ điển một chút."},{"type":"simple","zh":"遇到不认识的生词时，他总是先自己查词典，然后再问老师。","pinyin":"Yùdào bú rènshi de shēngcí shí, tā zǒngshì xiān zìjǐ chá cídiǎn, ránhòu zài wèn lǎoshī.","vi":"Khi gặp từ mới không biết, cậu ấy luôn tự tra từ điển trước rồi sau đó mới hỏi thầy giáo."},{"type":"compound","zh":"我已经帮你查清楚了，明天上午九点有一班飞往北京的航班。","pinyin":"Wǒ yǐjīng bāng nǐ chá qīngchu le, míngtiān shàngwǔ jiǔ diǎn yǒu yì bān fēiwǎng Běijīng de hángbān.","vi":"Tôi đã tra giúp bạn rõ ràng rồi, 9 giờ sáng mai có một chuyến bay đi Bắc Kinh."}],"related":[{"hanzi":"检查","pinyin":"jiǎnchá","vi":"Kiểm tra"},{"hanzi":"调查","pinyin":"diàochá","vi":"Điều tra"},{"hanzi":"词典","pinyin":"cídiǎn","vi":"Từ điển"},{"hanzi":"警察","pinyin":"jǐngchá","vi":"Cảnh sát"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"}]},{"id":"尝","hanzi":"尝","pinyin":"cháng","meaning_vi":"nếm, nếm thử","explanation":"Dùng khi thử hương vị món ăn (尝一口 - nếm một miếng).","hsk_level":3,"tags":["dong-tu","an-uong"],"image":"👅","examples":[{"type":"basic","zh":"你尝尝这个菜。","pinyin":"Nǐ cháng chang zhè ge cài.","vi":"Bạn nếm thử món này xem."},{"type":"simple","zh":"这是我第一次做的红烧肉，你快拿筷子尝一尝味道怎么样。","pinyin":"Zhè shì wǒ dìyīcì zuò de hóngshāoròu, nǐ kuài ná kuàizi cháng yi cháng wèidào zěnmeyàng.","vi":"Đây là món thịt kho tàu lần đầu tiên tôi làm, bạn mau cầm đũa nếm thử xem hương vị thế nào."},{"type":"compound","zh":"来到北京旅游，一定要去尝尝正宗的北京烤鸭和老北京小吃。","pinyin":"Láidào Běijīng lǚyóu, yídìngyào qù cháng chang zhèngzōng de Běijīngkǎoyā hé lǎoběijīng xiǎochī.","vi":"Đến Bắc Kinh du lịch thì nhất định phải đi nếm thử vịt quay Bắc Kinh chính hiệu và đồ ăn vặt Bắc Kinh xưa."}],"related":[{"hanzi":"味道","pinyin":"wèidào","vi":"Mùi vị"},{"hanzi":"好吃","pinyin":"hǎochī","vi":"Ngon"},{"hanzi":"试","pinyin":"shì","vi":"Thử"},{"hanzi":"菜","pinyin":"cài","vi":"Món ăn"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"}],"traditional":"嘗"},{"id":"超过","hanzi":"超过","pinyin":"chāoguò","meaning_vi":"vượt qua, quá","explanation":"超 (vượt) + 过 (qua). Dùng cho số lượng, tốc độ hoặc trình độ.","hsk_level":3,"tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"他的成绩超过了我。","pinyin":"Tā de chéngjì chāoguòle wǒ.","vi":"Thành tích của anh ấy đã vượt qua tôi."},{"type":"simple","zh":"我们班的留学生人数已经超过了三十个人。","pinyin":"Wǒmen bān de liúxuésheng rénshù yǐjīng chāoguòle sānshí ge rén.","vi":"Số lượng du học sinh lớp chúng tôi đã vượt quá 30 người rồi."},{"type":"compound","zh":"因为行李箱的重量超过了规定标准，所以他在机场交了超重费。","pinyin":"Yīnwèi xínglixiāng de zhòngliàng chāoguòle guīdìng biāozhǔn, suǒyǐ tā zài jīchǎng jiāole chāozhòng fèi.","vi":"Vì trọng lượng vali vượt quá tiêu chuẩn quy định nên anh ấy đã phải đóng phí quá cước ở sân bay."}],"related":[{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"过","pinyin":"guo","vi":"Qua/Từng"},{"hanzi":"经过","pinyin":"jīngguò","vi":"Đi qua"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"数量","pinyin":"shùliàng","vi":"Số lượng"}],"traditional":"超過"},{"id":"成功","hanzi":"成功","pinyin":"chénggōng","meaning_vi":"thành công","explanation":"成 (hoàn thành) + 功 (công lao). Đối nghĩa với 失败 (thất bại).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"🎉","examples":[{"type":"basic","zh":"祝你成功！","pinyin":"Zhù nǐ chénggōng!","vi":"Chúc bạn thành công!"},{"type":"simple","zh":"经过三年的不懈努力，他的新公司终于取得了巨大的成功。","pinyin":"Jīngguò sān nián de búxiè nǔlì, tā de xīn gōngsī zhōngyú qǔ déle jùdà de chénggōng.","vi":"Trải qua ba năm nỗ lực không ngừng nghỉ, công ty mới của anh ấy cuối cùng đã gặt hái thành công rực rỡ."},{"type":"compound","zh":"失败是成功之母，只要我们从错误中吸取经验，就一定能获得成功。","pinyin":"Shībài shì chénggōng zhī mǔ, zhǐyào wǒmen cóng cuòwù zhōng xīqǔ jīngyàn, jiù yídìng néng huòdé chénggōng.","vi":"Thất bại là mẹ thành công, chỉ cần chúng ta rút ra kinh nghiệm từ sai lầm thì nhất định sẽ giành được thành công."}],"related":[{"hanzi":"失败","pinyin":"shībài","vi":"Thất bại"},{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"成为","pinyin":"chéngwéi","vi":"Trở thành"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"}]},{"id":"失败","hanzi":"失败","pinyin":"shībài","meaning_vi":"thất bại, thua cuộc","explanation":"失 (mất) + 败 (thua). Đối nghĩa với 成功 (thành công).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"他不害怕失败。","pinyin":"Tā bú hàipà shībài.","vi":"Anh ấy không sợ thất bại."},{"type":"simple","zh":"虽然这次实验失败了，但是大家并没有灰心，而是重新开始研究。","pinyin":"Suīrán zhè cì shíyàn shībài le, dànshì dàjiā bìng méiyǒu huīxīn, érshì chóngxīn kāishǐ yánjiū.","vi":"Tuy thí nghiệm lần này thất bại nhưng mọi người không hề nản lòng mà bắt đầu nghiên cứu lại từ đầu."},{"type":"compound","zh":"面对困难和失败的时候，保持冷静和自信比什么都重要。","pinyin":"Miànduì kùnnan hé shībài de shíhou, bǎochí lěngjìng hé zìxìn bǐ shénme dōu zhòngyào.","vi":"Khi đối mặt với khó khăn và thất bại, giữ được sự bình tĩnh và tự tin quan trọng hơn bất cứ điều gì."}],"related":[{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"失望","pinyin":"shīwàng","vi":"Thất vọng"},{"hanzi":"输","pinyin":"shū","vi":"Thua"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"Kinh nghiệm"}],"traditional":"失敗"},{"id":"成为","hanzi":"成为","pinyin":"chéngwéi","meaning_vi":"trở thành","explanation":"成 (thành) + 为 (là).","hsk_level":3,"tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"我想成为一名老师。","pinyin":"Wǒ xiǎng chéngwéi yì míng lǎoshī.","vi":"Tôi muốn trở thành một giáo viên."},{"type":"simple","zh":"大学毕业以后，他通过努力终于成为了一名优秀的律师。","pinyin":"Dàxué bìyè yǐhòu, tā tōngguò nǔlì zhōngyú chéng wéile yì míng yōuxiù de lǜshī.","vi":"Sau khi tốt nghiệp đại học, nhờ nỗ lực anh ấy cuối cùng đã trở thành một luật sư xuất sắc."},{"type":"compound","zh":"因为我们有共同的爱好和理想，所以我们很快就成为了无话不谈的好朋友。","pinyin":"Yīnwèi wǒmen yǒu gòngtóng de àihào hé lǐxiǎng, suǒyǐ wǒmen hěn kuài jiù chéngwéi lewú huà bù tán de hǎopéngyou.","vi":"Vì chúng tôi có chung sở thích và lý tưởng nên chẳng mấy chốc đã trở thành bạn thân không gì không nói."}],"related":[{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"},{"hanzi":"为","pinyin":"wèi","vi":"Là/Vì"},{"hanzi":"变成","pinyin":"biànchéng","vi":"Biến thành"},{"hanzi":"理想","pinyin":"lǐxiǎng","vi":"Lý tưởng"}],"traditional":"成為"},{"id":"乘坐","hanzi":"乘坐","pinyin":"chéngzuò","meaning_vi":"đi, ngồi (phương tiện giao thông)","explanation":"乘 (cưỡi/đi) + 坐 (ngồi). Dùng trang trọng hơn 坐.","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🚆","examples":[{"type":"basic","zh":"请按顺序乘坐电梯。","pinyin":"Qǐng àn shùnxù chéngzuò diàntī.","vi":"Xin hãy đi thang máy theo thứ tự."},{"type":"simple","zh":"现在越来越多的市民选择乘坐地铁和公共汽车上下班。","pinyin":"Xiànzài yuèláiyuè duō de shìmín xuǎnzé chéngzuò dìtiě hé gōnggòngqìchē shàngxiàbān.","vi":"Hiện nay ngày càng có nhiều người dân chọn đi tàu điện ngầm và xe buýt để đi làm và tan làm."},{"type":"compound","zh":"乘坐飞机出国旅行时，请提前两个小时到达机场办理登机手续。","pinyin":"Chéngzuò fēijī chūguó lǚxíng shí, qǐng tíqián liǎng ge xiǎoshí dàodá jīchǎng bànlǐ dēngjī shǒuxù.","vi":"Khi đi máy bay du lịch nước ngoài, xin vui lòng đến sân bay trước hai tiếng để làm thủ tục lên máy bay."}],"related":[{"hanzi":"坐","pinyin":"zuò","vi":"Ngồi/Đi"},{"hanzi":"乘客","pinyin":"chéngkè","vi":"Hành khách"},{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"飞机","pinyin":"fēijī","vi":"Máy bay"},{"hanzi":"火车","pinyin":"huǒchē","vi":"Tàu hỏa"}]},{"id":"吃惊","hanzi":"吃惊","pinyin":"chījīng","meaning_vi":"kinh ngạc, giật mình","explanation":"吃 (chịu/gặp) + 惊 (hoảng hốt). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"这个消息让我很吃惊。","pinyin":"Zhè ge xiāoxi ràng wǒ hěn chījīng.","vi":"Tin tức này khiến tôi rất kinh ngạc."},{"type":"simple","zh":"听到他要辞职去环游世界的决定，所有同事都感到非常吃惊。","pinyin":"Tīngdào tā yào cízhí qù huányóu shìjiè de juédìng, suǒyǒu tóngshì dōu gǎndào fēicháng chījīng.","vi":"Nghe tin anh ấy quyết định nghỉ việc để đi du lịch vòng quanh thế giới, tất cả đồng nghiệp đều cảm thấy vô cùng kinh ngạc."},{"type":"compound","zh":"虽然他只学了一年汉语，但是说得像中国人一样流利，真让人吃惊。","pinyin":"Suīrán tā zhǐ xuéle yì nián Hànyǔ, dànshì shuō de xiàng Zhōngguórén yíyàng liúlì, zhēn ràng rén chījīng.","vi":"Tuy anh ấy mới học tiếng Trung một năm nhưng nói trôi chảy như người Trung Quốc, thật khiến người ta kinh ngạc."}],"related":[{"hanzi":"惊讶","pinyin":"jīngyà","vi":"Kinh ngạc"},{"hanzi":"吃","pinyin":"chī","vi":"Ăn"},{"hanzi":"消息","pinyin":"xiāoxi","vi":"Tin tức"},{"hanzi":"突然","pinyin":"tūrán","vi":"Đột nhiên"},{"hanzi":"竟然","pinyin":"jìngrán","vi":"Không ngờ lại"}],"traditional":"吃驚"},{"id":"出现","hanzi":"出现","pinyin":"chūxiàn","meaning_vi":"xuất hiện","explanation":"出 (ra) + 现 (hiện). Đối nghĩa với 消失 (biến mất).","hsk_level":3,"tags":["dong-tu"],"image":"✨","examples":[{"type":"basic","zh":"天空中出现了彩虹。","pinyin":"Tiānkōng zhōng chūxiànle cǎihóng.","vi":"Trên bầu trời xuất hiện cầu vồng."},{"type":"simple","zh":"雨停了以后，太阳从云层后面慢慢地出现了。","pinyin":"Yǔ tíngle yǐhòu, tàiyáng cóng yúncéng hòumiàn mànmàn de chūxiàn le.","vi":"Sau khi tạnh mưa, mặt trời từ phía sau tầng mây từ từ xuất hiện."},{"type":"compound","zh":"如果电脑在使用过程中突然出现故障，请及时联系技术人员修理。","pinyin":"Rúguǒ diànnǎo zài shǐyòng guòchéng zhōng tūrán chūxiàn gùzhàng, qǐng jíshí liánxì jìshù rényuán xiūlǐ.","vi":"Nếu máy tính trong quá trình sử dụng đột nhiên xuất hiện sự cố, xin hãy liên hệ ngay với nhân viên kỹ thuật để sửa chữa."}],"related":[{"hanzi":"发现","pinyin":"fāxiàn","vi":"Phát hiện"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"出","pinyin":"chū","vi":"Ra"},{"hanzi":"消失","pinyin":"xiāoshī","vi":"Biến mất"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"Tình huống"}],"traditional":"出現"},{"id":"出发","hanzi":"出发","pinyin":"chūfā","meaning_vi":"xuất phát, lên đường","explanation":"出 (ra) + 发 (phát động/khởi hành).","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🛫","examples":[{"type":"basic","zh":"我们明天早上八点出发。","pinyin":"Wǒmen míngtiān zǎoshang bā diǎn chūfā.","vi":"8 giờ sáng mai chúng ta xuất phát."},{"type":"simple","zh":"为了避开早高峰堵车，爸爸决定明天早上六点就开车出发。","pinyin":"Wèile bìkāi zǎogāofēng dǔchē, bàba juédìng míngtiān zǎoshang liù diǎn jiù kāichē chūfā.","vi":"Để tránh tắc đường giờ cao điểm buổi sáng, bố quyết định sáng mai 6 giờ đã lái xe xuất phát."},{"type":"compound","zh":"出发以前，大家一定要再次检查一遍护照、机票和手机是否都带齐了。","pinyin":"Chūfā yǐqián, dàjiā yídìngyào zàicì jiǎnchá yíbiàn hùzhào, jīpiào hé shǒujī shìfǒu dōu dài qí le.","vi":"Trước khi lên đường, mọi người nhất định phải kiểm tra lại một lần nữa xem hộ chiếu, vé máy bay và điện thoại đã mang đủ chưa."}],"related":[{"hanzi":"到达","pinyin":"dàodá","vi":"Đến nơi"},{"hanzi":"离开","pinyin":"líkāi","vi":"Rời khỏi"},{"hanzi":"发现","pinyin":"fāxiàn","vi":"Phát hiện"},{"hanzi":"出","pinyin":"chū","vi":"Ra"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"}],"traditional":"出發"},{"id":"处理","hanzi":"处理","pinyin":"chǔlǐ","meaning_vi":"xử lý, giải quyết","explanation":"处 (đối phó) + 理 (sắp xếp).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"我正在处理这件事。","pinyin":"Wǒ zhèngzài chǔlǐ zhè jiàn shì.","vi":"Tôi đang xử lý việc này."},{"type":"simple","zh":"李经理工作能力很强，总是能又快又好地处理各种复杂问题。","pinyin":"Lǐ jīnglǐ gōngzuò nénglì hěn qiáng, zǒngshì néng yòu kuài yòu hǎo de chǔlǐ gèzhǒng fùzá wèntí.","vi":"Giám đốc Lý năng lực làm việc rất giỏi, luôn có thể xử lý nhanh và tốt mọi vấn đề phức tạp."},{"type":"compound","zh":"因为今天公司里有很多紧急文件需要处理，所以我晚上可能要加班。","pinyin":"Yīnwèi jīntiān gōngsī lǐ yǒu hěn duō jǐnjí wénjiàn xūyào chǔlǐ, suǒyǐ wǒ wǎnshang kěnéng yào jiābān.","vi":"Vì hôm nay trong công ty có nhiều tài liệu khẩn cấp cần xử lý nên tối nay tôi có lẽ phải tăng ca."}],"related":[{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"},{"hanzi":"修理","pinyin":"xiūlǐ","vi":"Sửa chữa"},{"hanzi":"事情","pinyin":"shìqing","vi":"Sự việc"},{"hanzi":"问题","pinyin":"wèntí","vi":"Vấn đề"}],"traditional":"處理"},{"id":"传播","hanzi":"传播","pinyin":"chuánbō","meaning_vi":"truyền bá, lan truyền","explanation":"传 (truyền) + 播 (gieo rắc/phát sóng).","hsk_level":3,"tags":["dong-tu"],"image":"📡","examples":[{"type":"basic","zh":"互联网传播信息很快。","pinyin":"Hùliánwǎng chuánbō xìnxī hěn kuài.","vi":"Internet lan truyền thông tin rất nhanh."},{"type":"simple","zh":"很多外国留学生都希望把优秀的中国传统文化传播到世界各地。","pinyin":"Hěn duō wàiguó liúxuésheng dōu xīwàng bǎ yōuxiù de Zhōngguó chuántǒng wénhuà chuánbō dào shìjiè gèdì.","vi":"Nhiều du học sinh nước ngoài đều hy vọng truyền bá văn hóa truyền thống tốt đẹp của Trung Quốc ra khắp thế giới."},{"type":"compound","zh":"随着智能手机的普及，新闻和知识在网络上的传播速度越来越快。","pinyin":"Suízhe zhìnéng shǒujī de pǔjí, xīnwén hé zhīshi zài wǎngluò shang de chuánbō sùdù yuèláiyuè kuài.","vi":"Cùng với sự phổ cập của điện thoại thông minh, tốc độ lan truyền tin tức và kiến thức trên mạng ngày càng nhanh."}],"related":[{"hanzi":"广播","pinyin":"guǎngbō","vi":"Phát thanh"},{"hanzi":"传染","pinyin":"chuánrǎn","vi":"Lây nhiễm"},{"hanzi":"传统","pinyin":"chuántǒng","vi":"Truyền thống"},{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"文化","pinyin":"wénhuà","vi":"Văn hóa"}],"traditional":"傳播"},{"id":"传染","hanzi":"传染","pinyin":"chuánrǎn","meaning_vi":"lây nhiễm, truyền nhiễm","explanation":"传 (truyền) + 染 (nhiễm).","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"😷","examples":[{"type":"basic","zh":"这种感冒很容易传染。","pinyin":"Zhè zhǒng gǎnmào hěn róngyì chuánrǎn.","vi":"Loại cảm cúm này rất dễ lây nhiễm."},{"type":"simple","zh":"冬天是流感高发季节，在人多的地方戴口罩可以预防疾病传染。","pinyin":"Dōngtiān shì liúgǎn gāofā jìjié, zài rén duō de dìfang dài kǒuzhào kěyǐ yùfáng jíbìng chuánrǎn.","vi":"Mùa đông là mùa cúm bùng phát mạnh, đeo khẩu trang ở nơi đông người có thể phòng ngừa bệnh lây lan."},{"type":"compound","zh":"因为弟弟得了传染性感冒，所以医生建议他先在家休息几天不要去上学。","pinyin":"Yīnwèi dìdi déle chuánrǎnxìng gǎnmào, suǒyǐ yīshēng jiànyì tā xiān zài jiā xiūxi jǐtiān bú yào qù shàngxué.","vi":"Vì em trai bị cảm cúm lây nhiễm nên bác sĩ khuyên bé nghỉ ngơi ở nhà mấy ngày đừng đi học vội."}],"related":[{"hanzi":"传播","pinyin":"chuánbō","vi":"Truyền bá"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"Ô nhiễm"},{"hanzi":"感冒","pinyin":"gǎnmào","vi":"Cảm cúm"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"}],"traditional":"傳染"},{"id":"打扰","hanzi":"打扰","pinyin":"dǎrǎo","meaning_vi":"làm phiền, quấy rầy","explanation":"打 + 扰 (quấy nhiễu). Câu lịch sự: 打扰一下 (Xin làm phiền một chút).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"对不起，打扰一下。","pinyin":"Duìbuqǐ, dǎrǎo yíxià.","vi":"Xin lỗi, xin làm phiền một chút."},{"type":"simple","zh":"王老师正在办公室里准备明天的讲义，我们最好不要去打扰他。","pinyin":"Wáng lǎoshī zhèngzài bàngōngshì lǐ zhǔnbèi míngtiān de jiǎngyì, wǒmen zuìhǎo bú yào qù dǎrǎo tā.","vi":"Thầy Vương đang ở trong văn phòng chuẩn bị bài giảng cho ngày mai, tốt nhất chúng ta đừng vào làm phiền thầy."},{"type":"compound","zh":"在图书馆里看书时，大家应该把手机调成静音，以免打扰到别人学习。","pinyin":"Zài túshūguǎn lǐ kànshū shí, dàjiā yīnggāi bǎshǒu jī tiáo chéng jìngyīn, yǐmiǎn dǎrǎo dào biérén xuéxí.","vi":"Lúc đọc sách trong thư viện, mọi người nên để điện thoại chế độ im lặng để tránh làm phiền người khác học tập."}],"related":[{"hanzi":"麻烦","pinyin":"máfan","vi":"Làm phiền"},{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"Xin lỗi"},{"hanzi":"打","pinyin":"dǎ","vi":"Đánh/Gọi"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"请问","pinyin":"qǐngwèn","vi":"Xin hỏi"}],"traditional":"打擾"},{"id":"打印","hanzi":"打印","pinyin":"dǎyìn","meaning_vi":"in, in ấn","explanation":"打 (đánh/gõ) + 印 (in dấu).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"🖨️","examples":[{"type":"basic","zh":"请帮我打印这份文件。","pinyin":"Qǐng bāng wǒ dǎyìn zhè fèn wénjiàn.","vi":"Xin giúp tôi in tài liệu này."},{"type":"simple","zh":"明天开会要用的表格和资料我已经全部打印好了。","pinyin":"Míngtiān kāi huìyào yòng de biǎogé hé zīliào wǒ yǐjīng quánbù dǎyìn hǎo le.","vi":"Biểu mẫu và tài liệu cần dùng cho cuộc họp ngày mai tôi đã in xong hết rồi."},{"type":"compound","zh":"因为办公室的打印机突然没有纸了，所以我只好去楼下的打印店打印。","pinyin":"Yīnwèi bàngōngshì de dǎyìnjī tūrán méiyǒu zhǐ le, suǒyǐ wǒ zhǐhǎo qù lóuxià de dǎyìn diàn dǎyìn.","vi":"Vì máy in của văn phòng đột nhiên hết giấy nên tôi đành xuống tiệm in dưới lầu để in."}],"related":[{"hanzi":"印象","pinyin":"yìnxiàng","vi":"Ấn tượng"},{"hanzi":"打","pinyin":"dǎ","vi":"Đánh/Gõ"},{"hanzi":"复印","pinyin":"fùyìn","vi":"Photo"},{"hanzi":"材料","pinyin":"cáiliào","vi":"Tài liệu"},{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"Văn phòng"}]},{"id":"打招呼","hanzi":"打招呼","pinyin":"dǎzhāohu","meaning_vi":"chào hỏi","explanation":"打 + 招呼 (vẫy gọi/chào). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"👋","examples":[{"type":"basic","zh":"他笑着跟我打招呼。","pinyin":"Tā xiàozhe gēn wǒ dǎzhāohu.","vi":"Anh ấy mỉm cười chào hỏi tôi."},{"type":"simple","zh":"每次在小区里遇到邻居，妈妈都会热情地和他们打招呼。","pinyin":"Měi cì zài xiǎoqū lǐ yùdào línjū, māma dōuhuì rèqíng dehé tāmen dǎzhāohu.","vi":"Mỗi lần gặp hàng xóm trong khu chung cư, mẹ đều niềm nở chào hỏi họ."},{"type":"compound","zh":"因为今天早上他赶时间去机场，所以没来得及跟大家打招呼就走了。","pinyin":"Yīnwèi jīntiān zǎoshang tā gǎnshíjiān qù jīchǎng, suǒyǐ méi láidejí gēn dàjiā dǎzhāohu jiù zǒu le.","vi":"Vì sáng nay anh ấy vội ra sân bay nên không kịp chào hỏi mọi người đã đi rồi."}],"related":[{"hanzi":"招聘","pinyin":"zhāopìn","vi":"Tuyển dụng"},{"hanzi":"你好","pinyin":"nǐhǎo","vi":"Xin chào"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"},{"hanzi":"邻居","pinyin":"línjū","vi":"Hàng xóm"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}]},{"id":"打折","hanzi":"打折","pinyin":"dǎzhé","meaning_vi":"giảm giá, chiết khấu","explanation":"打 + 折 (gập/giảm). Ví dụ: 打八折 (giảm còn 80%, tức giảm 20%).","hsk_level":3,"tags":["dong-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这家商店正在打折。","pinyin":"Zhè jiā shāngdiàn zhèngzài dǎzhé.","vi":"Cửa hàng này đang giảm giá."},{"type":"simple","zh":"国庆节期间，市中心的大商场里很多品牌衣服都在打八折。","pinyin":"Guóqìngjié qījiān, shìzhōngxīn de dà shāngchǎng lǐ hěn duō pǐnpái yīfu dōu zài dǎ bā zhé.","vi":"Trong dịp Quốc khánh, nhiều quần áo hàng hiệu trong trung tâm thương mại lớn ở trung tâm thành phố đều giảm giá 20%."},{"type":"compound","zh":"虽然这双皮鞋平时卖得很贵，但是今天刚好赶上商店打折，便宜了一半。","pinyin":"Suīrán zhè shuāng píxié píngshí mài de hěn guì, dànshì jīntiān gānghǎo gǎnshàng shāngdiàn dǎzhé, piányile yíbàn.","vi":"Tuy đôi giày da này ngày thường bán rất đắt nhưng hôm nay vừa hay gặp dịp cửa hàng giảm giá nên rẻ đi một nửa."}],"related":[{"hanzi":"便宜","pinyin":"piányi","vi":"Rẻ"},{"hanzi":"价格","pinyin":"jiàgé","vi":"Giá cả"},{"hanzi":"商店","pinyin":"shāngdiàn","vi":"Cửa hàng"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"购物","pinyin":"gòuwù","vi":"Mua sắm"}]},{"id":"打针","hanzi":"打针","pinyin":"dǎzhēn","meaning_vi":"tiêm, chích thuốc","explanation":"打 + 针 (cây kim). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"💉","examples":[{"type":"basic","zh":"小孩子都害怕打针。","pinyin":"Xiǎoháizi dōu hàipà dǎzhēn.","vi":"Trẻ con đều sợ tiêm thuốc."},{"type":"simple","zh":"他发烧烧到了三十九度，医生说光吃药不行，必须打针。","pinyin":"Tā fāshāo shāodàole sān shíjiǔ dù, yīshēng shuō guāng chīyào bù xíng, bìxū dǎzhēn.","vi":"Anh ấy sốt lên tới 39 độ, bác sĩ nói chỉ uống thuốc thôi không được, bắt buộc phải tiêm."},{"type":"compound","zh":"虽然打针的时候有点儿疼，但是打完针以后他的烧很快就退下来了。","pinyin":"Suīrán dǎzhēn de shíhou yǒudiǎnr téng, dànshì dǎ wán zhēn yǐhòu tā de shāo hěn kuài jiù tuì xiàlái le.","vi":"Tuy lúc tiêm hơi đau một chút nhưng tiêm xong cơn sốt của anh ấy đã hạ xuống rất nhanh."}],"related":[{"hanzi":"发烧","pinyin":"fāshāo","vi":"Phát sốt"},{"hanzi":"吃药","pinyin":"chīyào","vi":"Uống thuốc"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"},{"hanzi":"医生","pinyin":"yīshēng","vi":"Bác sĩ"},{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"}],"traditional":"打針"},{"id":"打扮","hanzi":"打扮","pinyin":"dǎban","meaning_vi":"trang điểm, ăn diện","explanation":"打 + 扮 (hóa trang/ăn mặc).","hsk_level":3,"tags":["dong-tu","trang-phuc"],"image":"💄","examples":[{"type":"basic","zh":"她今天打扮得很漂亮。","pinyin":"Tā jīntiān dǎban de hěn piàoliang.","vi":"Hôm nay cô ấy trang điểm rất đẹp."},{"type":"simple","zh":"为了参加好朋友的婚礼，姐姐一大早就起床开始认真打扮自己。","pinyin":"Wèile cānjiā hǎopéngyou de hūnlǐ, jiějie yídàzǎo jiù qǐchuáng kāishǐ rènzhēn dǎban zìjǐ.","vi":"Để tham dự đám cưới của bạn thân, chị gái đã thức dậy từ sáng sớm để bắt đầu chăm chút ăn diện."},{"type":"compound","zh":"春节前夕，家家户户都会把房间打扫干净，并挂上红灯笼打扮一番。","pinyin":"Chūnjié qiánxī, jiājiāhùhù dōuhuì bǎ fángjiān dǎsǎo gānjìng, bìng guà shàng hóngdēnglong dǎban yìfān.","vi":"Trước thềm Tết Nguyên đán, nhà nhà đều dọn dẹp phòng ốc sạch sẽ và treo đèn lồng đỏ trang trí."}],"related":[{"hanzi":"漂亮","pinyin":"piàoliang","vi":"Xinh đẹp"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"镜子","pinyin":"jìngzi","vi":"Cái gương"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"Kết hôn"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"Tụ họp"}]},{"id":"道歉","hanzi":"道歉","pinyin":"dàoqiàn","meaning_vi":"xin lỗi, tạ lỗi","explanation":"道 (nói) + 歉 (lỗi). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"他向我道歉了。","pinyin":"Tā xiàng wǒ dàoqiàn le.","vi":"Anh ấy đã xin lỗi tôi rồi."},{"type":"simple","zh":"既然是你不小心弄坏了同学的笔记本，就应该主动向他道歉。","pinyin":"Jìrán shì nǐ bù xiǎoxīn nòng huàile tóngxué de bǐjìběn, jiù yīnggāi zhǔ dòngxiàng tā dàoqiàn.","vi":"Vì là bạn vô tình làm hỏng cuốn sổ tay của bạn học nên phải chủ động xin lỗi cậu ấy."},{"type":"compound","zh":"虽然他已经诚恳地向我道歉了，但是这件事还是让我心里有点儿难过。","pinyin":"Suīrán tā yǐjīng chéngkěn de xiàng wǒ dàoqiàn le, dànshì zhè jiàn shì háishi ràng wǒ xīnlǐ yǒudiǎnr nánguò.","vi":"Tuy anh ấy đã thành khẩn xin lỗi tôi rồi nhưng chuyện này vẫn khiến trong lòng tôi hơi buồn."}],"related":[{"hanzi":"对不起","pinyin":"duìbuqǐ","vi":"Xin lỗi"},{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"Áy náy"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"Tha thứ"},{"hanzi":"误会","pinyin":"wùhuì","vi":"Hiểu lầm"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"}]},{"id":"得意","hanzi":"得意","pinyin":"déyì","meaning_vi":"đắc ý, tự hào, hả hê","explanation":"得 (đạt được) + 意 (ý muốn).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😏","examples":[{"type":"basic","zh":"他考了第一名，很得意。","pinyin":"Tā kǎole dìyīmíng, hěn déyì.","vi":"Cậu ấy thi đứng nhất, rất đắc ý."},{"type":"simple","zh":"看到自己画的画得到了老师的称赞，小男孩脸上露出了得意的笑容。","pinyin":"Kàndào zìjǐ huà de huà dédàole lǎoshī de chēngzàn, xiǎo nánhái liǎn shang lùchūle déyì de xiàoróng.","vi":"Thấy bức tranh mình vẽ nhận được lời khen của thầy giáo, cậu bé nở nụ cười đầy tự hào."},{"type":"compound","zh":"取得一点儿好成绩的时候千万不要太得意，否则很容易因为粗心而退步。","pinyin":"Qǔdé yìdiǎnr hǎo chéngjì de shíhou qiānwàn bú yào tài déyì, fǒuzé hěn róngyì yīnwèi cūxīn ér tuìbù.","vi":"Khi đạt được chút thành tích tốt tuyệt đối đừng quá tự mãn, nếu không sẽ rất dễ thụt lùi vì bất cẩn."}],"related":[{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"Tự hào/Kiêu ngạo"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"}]},{"id":"登机","hanzi":"登机","pinyin":"dēngjī","meaning_vi":"lên máy bay","explanation":"登 (bước lên) + 机 (máy bay). Cụm: 登机牌 (thẻ lên máy bay).","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🛫","examples":[{"type":"basic","zh":"现在开始登机了。","pinyin":"Xiànzài kāishǐ dēngjī le.","vi":"Bây giờ bắt đầu lên máy bay rồi."},{"type":"simple","zh":"请乘坐本次航班的旅客携带好登机牌和护照，到十号登机口登机。","pinyin":"Qǐng chéngzuò běn cì hángbān de lǚkè xiédài hǎo dēngjīpái hé hùzhào, dào shí hào dēngjīkǒu dēngjī.","vi":"Xin mời hành khách đi chuyến bay này mang theo thẻ lên máy bay và hộ chiếu đến cửa lên máy bay số 10."},{"type":"compound","zh":"因为今天机场的人特别多，排队安检花了很长时间，差点儿耽误了登机。","pinyin":"Yīnwèi jīntiān jīchǎng de rén tèbié duō, páiduì ānjiǎn huāle hěn cháng shíjiān, chàdiǎnr dānwule dēngjī.","vi":"Vì hôm nay sân bay đông người đặc biệt, xếp hàng kiểm tra an ninh mất rất nhiều thời gian, suýt nữa thì lỡ giờ lên máy bay."}],"related":[{"hanzi":"飞机","pinyin":"fēijī","vi":"Máy bay"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"航班","pinyin":"hángbān","vi":"Chuyến bay"},{"hanzi":"护照","pinyin":"hùzhào","vi":"Hộ chiếu"},{"hanzi":"起飞","pinyin":"qǐfēi","vi":"Cất cánh"}],"traditional":"登機"},{"id":"掉","hanzi":"掉","pinyin":"diào","meaning_vi":"rơi, rụng, mất","explanation":"Bộ tài gảy 扌+ 卓. Thường làm bổ ngữ kết quả (忘掉了, 丢掉了).","hsk_level":3,"tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"我的钥匙掉在地上了。","pinyin":"Wǒ de yàoshi diào zài dìshang le.","vi":"Chìa khóa của tôi rơi xuống đất rồi."},{"type":"simple","zh":"秋天刮大风的时候，树上的黄叶子一片一片地掉了下来。","pinyin":"Qiūtiān guā dàfēng de shíhou, shù shang de huáng yèzi yípiàn yipiàn de diàole xiàlái.","vi":"Mùa thu khi gió lớn thổi qua, những chiếc lá vàng trên cây từng chiếc từng chiếc rơi rụng xuống."},{"type":"compound","zh":"因为刚才跑步跑得太快，他口袋里的手机不小心掉出来了。","pinyin":"Yīnwèi gāngcái pǎobù pǎo de tài kuài, tā kǒudài lǐ de shǒujī bù xiǎoxīn diào chūlái le.","vi":"Vì vừa nãy chạy bộ nhanh quá nên chiếc điện thoại trong túi áo anh ấy vô tình rơi ra ngoài."}],"related":[{"hanzi":"丢","pinyin":"diū","vi":"Mất"},{"hanzi":"坏","pinyin":"huài","vi":"Hỏng"},{"hanzi":"叶子","pinyin":"yèzi","vi":"Lá cây"},{"hanzi":"钥匙","pinyin":"yàoshi","vi":"Chìa khóa"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"Cẩn thận"}]},{"id":"丢","hanzi":"丢","pinyin":"diū","meaning_vi":"mất, đánh mất, vứt","explanation":"Đối nghĩa với 找到 (tìm thấy).","hsk_level":3,"tags":["dong-tu"],"image":"❓","examples":[{"type":"basic","zh":"我的钱包丢了。","pinyin":"Wǒ de qiánbāo diū le.","vi":"Ví tiền của tôi bị mất rồi."},{"type":"simple","zh":"他昨天在地铁上不小心把新买的手机弄丢了，心里非常着急。","pinyin":"Tā zuótiān zài dìtiě shang bù xiǎoxīn bǎ xīn mǎi de shǒujī nòngdiū le, xīnlǐ fēicháng zháojí.","vi":"Hôm qua anh ấy vô tình làm mất chiếc điện thoại mới mua trên tàu điện ngầm, trong lòng vô cùng lo lắng."},{"type":"compound","zh":"如果把垃圾随便乱丢在地上，不仅影响城市美观，还会污染环境。","pinyin":"Rúguǒ bǎ lājī suíbiàn luàndiū zài dìshang, bùjǐn yǐngxiǎng chéngshì měiguān, hái huì wūrǎn huánjìng.","vi":"Nếu vứt rác bừa bãi xuống đất, không những ảnh hưởng mỹ quan đô thị mà còn gây ô nhiễm môi trường."}],"related":[{"hanzi":"掉","pinyin":"diào","vi":"Rơi"},{"hanzi":"找","pinyin":"zhǎo","vi":"Tìm"},{"hanzi":"扔","pinyin":"rēng","vi":"Vứt"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"},{"hanzi":"着急","pinyin":"zháojí","vi":"Lo lắng"}],"traditional":"丟"},{"id":"堵车","hanzi":"堵车","pinyin":"dǔchē","meaning_vi":"tắc đường, kẹt xe","explanation":"堵 (chặn lại) + 车 (xe). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"今天早上路上堵车。","pinyin":"Jīntiān zǎoshang lùshang dǔchē.","vi":"Sáng nay trên đường tắc xe."},{"type":"simple","zh":"每天早上八点和下午六点是这个城市最容易堵车的时候。","pinyin":"Měitiān zǎoshang bā diǎn hé xiàwǔ liù diǎn shì zhè ge chéngshì zuì róngyì dǔchē de shíhou.","vi":"8 giờ sáng và 6 giờ chiều hằng ngày là thời điểm thành phố này dễ tắc đường nhất."},{"type":"compound","zh":"因为前面发生了交通事故，路上堵车堵了一个多小时，所以我上班迟到了。","pinyin":"Yīnwèi qiánmiàn fāshēngle jiāotōng shìgù, lùshang dǔchē dǔle yí ge duō xiǎoshí, suǒyǐ wǒ shàngbān chídào le.","vi":"Vì phía trước xảy ra tai nạn giao thông, đường tắc hơn một tiếng đồng hồ nên tôi đã đi làm muộn."}],"related":[{"hanzi":"车","pinyin":"chē","vi":"Xe"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"Giao thông"},{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"迟到","pinyin":"chídào","vi":"Đến muộn"},{"hanzi":"路","pinyin":"lù","vi":"Con đường"}],"traditional":"堵車"},{"id":"锻炼","hanzi":"锻炼","pinyin":"duànliàn","meaning_vi":"rèn luyện, tập luyện","explanation":"锻 (rèn sắt) + 炼 (luyện kim). Dùng cho 锻炼身体 (rèn luyện sức khỏe).","hsk_level":3,"tags":["dong-tu","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"爸爸每天早上都锻炼身体。","pinyin":"Bàba měitiān zǎo Shangdōu duànliàn shēntǐ.","vi":"Bố mỗi sáng đều rèn luyện sức khỏe."},{"type":"simple","zh":"爷爷虽然已经七十多岁了，但是每天都坚持去公园锻炼身体。","pinyin":"Yéye suīrán yǐjīng qīshí duō suì le, dànshì měitiān dōu jiānchí qù gōngyuán duànliàn shēntǐ.","vi":"Ông nội tuy đã hơn 70 tuổi rồi nhưng ngày nào cũng kiên trì ra công viên tập thể dục."},{"type":"compound","zh":"只要每天抽出半个小时锻炼身体，不仅能增强体质，还能减轻工作压力。","pinyin":"Zhǐyào měitiān chōuchū bàn ge xiǎoshí duànliàn shēntǐ, bùjǐn néng zēngqiáng tǐzhì, hái néng jiǎnqīng gōngzuò yālì.","vi":"Chỉ cần mỗi ngày dành ra nửa tiếng rèn luyện sức khỏe thì không những tăng cường thể chất mà còn giảm bớt áp lực công việc."}],"related":[{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"Cơ thể"},{"hanzi":"跑步","pinyin":"pǎobù","vi":"Chạy bộ"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"Kiên trì"}],"traditional":"鍛煉"},{"id":"发展","hanzi":"发展","pinyin":"fāzhǎn","meaning_vi":"phát triển","explanation":"发 (phát ra) + 展 (mở rộng). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","danh-tu"],"image":"📈","examples":[{"type":"basic","zh":"中国经济发展很快。","pinyin":"Zhōngguó jīngjì fāzhǎn hěn kuài.","vi":"Kinh tế Trung Quốc phát triển rất nhanh."},{"type":"simple","zh":"随着科学技术的发展，人们的生活变得越来越方便和舒适。","pinyin":"Suízhe kēxué jìshù de fāzhǎn, rénmen de shēnghuó biànde yuèláiyuè fāngbiàn hé shūshì.","vi":"Cùng với sự phát triển của khoa học kỹ thuật, cuộc sống của con người trở nên ngày càng tiện lợi và thoải mái."},{"type":"compound","zh":"虽然这个城市这几年发展得非常快，但是当地人依然很好地保护了自然环境。","pinyin":"Suīrán zhè ge chéngshì zhè jǐ nián fāzhǎn de fēicháng kuài, dànshì dāngdìrén yīrán hěn hǎo de bǎohùle zìrán huánjìng.","vi":"Tuy thành phố này mấy năm nay phát triển vô cùng nhanh nhưng người dân địa phương vẫn bảo vệ môi trường tự nhiên rất tốt."}],"related":[{"hanzi":"变化","pinyin":"biànhuà","vi":"Thay đổi"},{"hanzi":"经济","pinyin":"jīngjì","vi":"Kinh tế"},{"hanzi":"技术","pinyin":"jìshù","vi":"Kỹ thuật"},{"hanzi":"社会","pinyin":"shèhuì","vi":"Xã hội"},{"hanzi":"发生","pinyin":"fāshēng","vi":"Phát sinh"}],"traditional":"發展"},{"id":"发生","hanzi":"发生","pinyin":"fāshēng","meaning_vi":"xảy ra, phát sinh","explanation":"发 (nảy ra) + 生 (sinh ra). Thường dùng cho sự việc, biến cố.","hsk_level":3,"tags":["dong-tu"],"image":"⚡","examples":[{"type":"basic","zh":"前面发生了什么事？","pinyin":"Qiánmiàn fāshēngle shénmeshì?","vi":"Phía trước đã xảy ra chuyện gì vậy?"},{"type":"simple","zh":"这几年我的家乡发生了翻天覆地的变化，盖了很多高楼。","pinyin":"Zhè jǐ nián wǒ de jiāxiāng fāshēngle fāntiānfùdì de biànhuà, gàile hěn duō gāolóu.","vi":"Mấy năm nay quê hương tôi đã xảy ra những thay đổi to lớn, xây dựng rất nhiều nhà cao tầng."},{"type":"compound","zh":"遇到突发情况的时候不要慌张，先弄清楚到底发生了什么事情再想办法。","pinyin":"Yùdào tūfā qíngkuàng de shíhou bú yào huāngzhāng, xiān nòng qīngchu dàodǐ fāshēngle shénme shìqing zài xiǎngbànfǎ.","vi":"Khi gặp tình huống bất ngờ đừng hoảng hốt, hãy làm rõ rốt cuộc đã xảy ra chuyện gì rồi mới nghĩ cách."}],"related":[{"hanzi":"发现","pinyin":"fāxiàn","vi":"Phát hiện"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"},{"hanzi":"变化","pinyin":"biànhuà","vi":"Thay đổi"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"Tình huống"}],"traditional":"發生"},{"id":"发烧","hanzi":"发烧","pinyin":"fāshāo","meaning_vi":"bị sốt, phát sốt","explanation":"发 (phát ra) + 烧 (đốt nóng). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"弟弟生病发烧了。","pinyin":"Dìdi shēngbìng fāshāo le.","vi":"Em trai bị ốm phát sốt rồi."},{"type":"simple","zh":"他昨天晚上淋了雨，今天早上起床觉得头疼，还发烧了。","pinyin":"Tā zuótiān wǎnshang línle yǔ, jīntiān zǎoshang qǐchuáng juéde tóuténg, hái fāshāo le.","vi":"Tối hôm qua cậu ấy bị dính mưa, sáng nay thức dậy thấy đau đầu và còn bị sốt nữa."},{"type":"compound","zh":"如果你发烧超过三十八度五，就应该马上去医院检查，不要自己乱吃药。","pinyin":"Rúguǒ nǐ fāshāo chāoguò sānshí bādù wǔ, jiù yīnggāi mǎshàng qù yīyuàn jiǎnchá, bú yào zìjǐ luàn chīyào.","vi":"Nếu bạn sốt quá 38,5 độ thì nên lập tức đi bệnh viện kiểm tra, đừng tự ý uống thuốc bừa bãi."}],"related":[{"hanzi":"感冒","pinyin":"gǎnmào","vi":"Cảm cúm"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"打针","pinyin":"dǎzhēn","vi":"Tiêm"},{"hanzi":"温度","pinyin":"wēndù","vi":"Nhiệt độ"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"}],"traditional":"發燒"},{"id":"翻译","hanzi":"翻译","pinyin":"fānyì","meaning_vi":"phiên dịch, dịch thuật","explanation":"翻 (lật/chuyển) + 译 (dịch). Vừa là động từ vừa là danh từ (người phiên dịch).","hsk_level":3,"tags":["dong-tu","ngon-ngu"],"image":"🌐","examples":[{"type":"basic","zh":"请把这句话翻译成中文。","pinyin":"Qǐng bǎ zhè jù huà fānyì chéng Zhōngwén.","vi":"Xin hãy dịch câu này sang tiếng Trung."},{"type":"simple","zh":"我姐姐汉语和英语都说得非常流利，她在一家国际公司当翻译。","pinyin":"Wǒ jiějie Hànyǔ hé Yīngyǔ dōu shuō de fēicháng liúlì, tā zài yìjiā Guójì gōngsī dāng fānyì.","vi":"Chị gái tôi nói tiếng Trung và tiếng Anh đều rất trôi chảy, chị ấy làm phiên dịch ở một công ty quốc tế."},{"type":"compound","zh":"虽然翻译软件现在很方便，但是要准确表达文化含义还是需要人工翻译。","pinyin":"Suīrán fānyì ruǎnjiàn xiànzài hěn fāngbiàn, dànshì yào zhǔnquè biǎodá wénhuà hányì háishi xūyào réngōng fānyì.","vi":"Tuy phần mềm dịch thuật hiện nay rất tiện nhưng để diễn đạt chính xác hàm ý văn hóa thì vẫn cần người dịch."}],"related":[{"hanzi":"语言","pinyin":"yǔyán","vi":"Ngôn ngữ"},{"hanzi":"汉语","pinyin":"Hànyǔ","vi":"Tiếng Trung"},{"hanzi":"英语","pinyin":"Yīngyǔ","vi":"Tiếng Anh"},{"hanzi":"流利","pinyin":"liúlì","vi":"Trôi chảy"},{"hanzi":"解释","pinyin":"jiěshì","vi":"Giải thích"}],"traditional":"翻譯"},{"id":"烦恼","hanzi":"烦恼","pinyin":"fánnǎo","meaning_vi":"phiền muộn, lo âu","explanation":"烦 (phiền) + 恼 (bực bội). Vừa là tính từ vừa là danh từ.","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😫","examples":[{"type":"basic","zh":"每个人都有自己的烦恼。","pinyin":"Měigerén dōu yǒu zìjǐ de fánnǎo.","vi":"Mỗi người đều có nỗi phiền muộn riêng của mình."},{"type":"simple","zh":"听听音乐、和朋友聊聊天，可以帮助我们忘记生活中的烦恼。","pinyin":"Tīng ting yīnyuè, hé péngyou liáo liaotiān, kěyǐ bāngzhù wǒmen wàngjì shēnghuó zhōng de fánnǎo.","vi":"Nghe chút âm nhạc, trò chuyện với bạn bè có thể giúp chúng ta quên đi phiền muộn trong cuộc sống."},{"type":"compound","zh":"虽然最近找工作的事让他很烦恼，但是他依然保持着积极乐观的态度。","pinyin":"Suīrán zuìjìn zhǎogōngzuò de shì ràng tā hěn fánnǎo, dànshì tā yīrán bǎochízhe jījí lèguān de tàidù.","vi":"Tuy dạo này chuyện tìm việc làm khiến anh ấy rất phiền muộn nhưng anh ấy vẫn giữ thái độ tích cực lạc quan."}],"related":[{"hanzi":"麻烦","pinyin":"máfan","vi":"Phiền phức"},{"hanzi":"难过","pinyin":"nánguò","vi":"Buồn bã"},{"hanzi":"担心","pinyin":"dānxīn","vi":"Lo lắng"},{"hanzi":"愉快","pinyin":"yúkuài","vi":"Vui vẻ"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"}],"traditional":"煩惱"},{"id":"反对","hanzi":"反对","pinyin":"fǎnduì","meaning_vi":"phản đối","explanation":"反 (ngược lại) + 对 (đối đầu). Đối nghĩa với 支持 (ủng hộ).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"👎","examples":[{"type":"basic","zh":"没有人反对这个计划。","pinyin":"Méiyǒu rén fǎnduì zhè ge jìhuà.","vi":"Không có ai phản đối kế hoạch này."},{"type":"simple","zh":"大家都觉得这个建议非常合理，所以没有任何人表示反对。","pinyin":"Dàjiā dōu juéde zhè ge jiànyì fēicháng hélǐ, suǒyǐ méiyǒu rènhé rén biǎoshì fǎnduì.","vi":"Mọi người đều thấy kiến nghị này rất hợp lý nên không có bất kỳ ai bày tỏ sự phản đối."},{"type":"compound","zh":"刚开始父母反对我一个人去国外留学，后来经过我的解释他们终于同意了。","pinyin":"Gāng kāishǐ fùmǔ fǎnduì wǒ yígerén qù guówài liúxué, hòulái jīngguò wǒ de jiěshì tāmen zhōngyú tóngyì le.","vi":"Ban đầu bố mẹ phản đối tôi đi du học nước ngoài một mình, sau đó qua lời giải thích của tôi thì bố mẹ cuối cùng cũng đồng ý."}],"related":[{"hanzi":"支持","pinyin":"zhīchí","vi":"Ủng hộ"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"相反","pinyin":"xiāngfǎn","vi":"Trái ngược"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"}],"traditional":"反對"},{"id":"支持","hanzi":"支持","pinyin":"zhīchí","meaning_vi":"ủng hộ, hỗ trợ","explanation":"支 (chống đỡ) + 持 (giữ vững). Đối nghĩa với 反对 (phản đối).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"👍","examples":[{"type":"basic","zh":"我非常支持你的决定。","pinyin":"Wǒ fēicháng zhīchí nǐ de juédìng.","vi":"Tôi vô cùng ủng hộ quyết định của bạn."},{"type":"simple","zh":"无论我做什么选择，爸爸妈妈和好朋友们都会在背后支持我。","pinyin":"Wúlùn wǒ zuò shénme xuǎnzé, bàba māma héhǎo péngyoumen dōuhuì zài bèihòu zhīchí wǒ.","vi":"Dù tôi đưa ra lựa chọn nào, bố mẹ và bạn thân đều luôn ủng hộ phía sau tôi."},{"type":"compound","zh":"感谢所有观众朋友一直以来的支持和鼓励，我们会继续努力拍出更好的电影。","pinyin":"Gǎnxiè suǒyǒu guānzhòng péngyou yìzhí yǐlái de zhīchí hé gǔlì, wǒmen huì jìxù nǔlì pāichū gèng hǎo de diànyǐng.","vi":"Cảm ơn sự ủng hộ và khích lệ từ trước tới nay của tất cả khán giả, chúng tôi sẽ tiếp tục nỗ lực làm ra những bộ phim hay hơn."}],"related":[{"hanzi":"反对","pinyin":"fǎnduì","vi":"Phản đối"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"Khích lệ"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"Kiên trì"}]},{"id":"放弃","hanzi":"放弃","pinyin":"fàngqì","meaning_vi":"từ bỏ, bỏ cuộc","explanation":"放 (thả ra) + 弃 (vứt bỏ).","hsk_level":3,"tags":["dong-tu"],"image":"🏳️","examples":[{"type":"basic","zh":"遇到困难不要轻易放弃。","pinyin":"Yùdào kùnnan bú yào qīngyì fàngqì.","vi":"Gặp khó khăn đừng dễ dàng từ bỏ."},{"type":"simple","zh":"虽然汉字很难学，但是他从来没有想过要放弃学习汉语。","pinyin":"Suīrán hànzì hěn nán xué, dànshì tā cónglái méiyǒu xiǎngguo yào fàngqì xuéxí Hànyǔ.","vi":"Tuy chữ Hán rất khó học nhưng anh ấy chưa bao giờ nghĩ tới việc từ bỏ học tiếng Trung."},{"type":"compound","zh":"只要我们坚持自己的理想不放弃，总有一天会看到成功的希望。","pinyin":"Zhǐyào wǒmen jiānchí zìjǐ de lǐxiǎng bú fàngqì, zǒngyǒu yì tiān huì kàndào chénggōng de xīwàng.","vi":"Chỉ cần chúng ta kiên trì lý tưởng của bản thân không bỏ cuộc thì sẽ có ngày nhìn thấy hy vọng thành công."}],"related":[{"hanzi":"坚持","pinyin":"jiānchí","vi":"Kiên trì"},{"hanzi":"放","pinyin":"fàng","vi":"Thả/Đặt"},{"hanzi":"失败","pinyin":"shībài","vi":"Thất bại"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"}],"traditional":"放棄"},{"id":"放松","hanzi":"放松","pinyin":"fàngsōng","meaning_vi":"thư giãn, thả lỏng","explanation":"放 (thả) + 松 (lỏng/thoải mái).","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"周末应该好好放松一下。","pinyin":"Zhōumò yīnggāi hǎohǎo fàngsōng yíxià.","vi":"Cuối tuần nên thư giãn một chút."},{"type":"simple","zh":"考试结束以后，同学们一起去公园散步聊天，心情放松了很多。","pinyin":"Kǎoshì jiéshù yǐhòu, tóngxuémen yìqǐ qù gōngyuán sànbù liáotiān, xīnqíng fàngsōngle hěn duō.","vi":"Sau khi kỳ thi kết thúc, các bạn học cùng nhau đi dạo trò chuyện ở công viên, tâm trạng thư giãn hơn nhiều."},{"type":"compound","zh":"平时工作压力大的时候，听听轻音乐或者做做运动都是很好的放松方式。","pinyin":"Píngshí gōngzuò yālì dà de shíhou, tīng ting qīngyīnyuè huòzhě zuò zuo yùndòng dōu shì hěn hǎo de fàngsōng fāngshì.","vi":"Bình thường khi áp lực công việc lớn, nghe chút nhạc nhẹ hoặc tập thể dục đều là những cách thư giãn rất tốt."}],"related":[{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"Căng thẳng"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"Nhẹ nhàng"},{"hanzi":"休息","pinyin":"xiūxi","vi":"Nghỉ ngơi"},{"hanzi":"压力","pinyin":"yālì","vi":"Áp lực"},{"hanzi":"放","pinyin":"fàng","vi":"Thả"}],"traditional":"放鬆"},{"id":"符合","hanzi":"符合","pinyin":"fúhé","meaning_vi":"phù hợp với, khớp với","explanation":"符 (dấu hiệu khớp nhau) + 合 (hợp lại).","hsk_level":3,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"这个条件很符合我的要求。","pinyin":"Zhè ge tiáojiàn hěn fúhé wǒ de yāoqiú.","vi":"Điều kiện này rất phù hợp với yêu cầu của tôi."},{"type":"simple","zh":"他不仅专业成绩优秀，而且汉语流利，完全符合公司的招聘标准。","pinyin":"Tā bùjǐn zhuānyè chéngjì yōuxiù, érqiě Hànyǔ liúlì, wánquán fúhé gōngsī de zhāopìn biāozhǔn.","vi":"Anh ấy không chỉ thành tích chuyên ngành xuất sắc mà tiếng Trung còn trôi chảy, hoàn toàn đáp ứng tiêu chuẩn tuyển dụng của công ty."},{"type":"compound","zh":"我们在选择职业的时候，不仅要考虑工资待遇，还要看是否符合自己的兴趣。","pinyin":"Wǒmen zài xuǎnzé zhíyè de shíhou, bùjǐn yào kǎolǜ gōngzī dàiyù, hái yào kàn shìfǒu fúhé zìjǐ de xìngqù.","vi":"Khi lựa chọn nghề nghiệp, chúng ta không chỉ cần cân nhắc lương thưởng mà còn phải xem có phù hợp với sở thích của mình không."}],"related":[{"hanzi":"适合","pinyin":"shìhé","vi":"Thích hợp"},{"hanzi":"合适","pinyin":"héshì","vi":"Vừa vặn"},{"hanzi":"合作","pinyin":"hézuò","vi":"Hợp tác"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"条件","pinyin":"tiáojiàn","vi":"Điều kiện"}]},{"id":"付款","hanzi":"付款","pinyin":"fùkuǎn","meaning_vi":"thanh toán, trả tiền","explanation":"付 (giao trả) + 款 (khoản tiền).","hsk_level":3,"tags":["dong-tu","mua-sam"],"image":"💳","examples":[{"type":"basic","zh":"请问在哪里付款？","pinyin":"Qǐngwèn zài nǎlǐ fùkuǎn?","vi":"Xin hỏi thanh toán tiền ở đâu ạ?"},{"type":"simple","zh":"现在在中国超市购物，大家习惯用手机扫码付款，非常方便。","pinyin":"Xiànzài zài Zhōngguó chāoshì gòuwù, dàjiā xí guànyòng shǒujī sǎomǎ fùkuǎn, fēicháng fāngbiàn.","vi":"Hiện nay khi mua sắm ở siêu thị Trung Quốc, mọi người quen dùng điện thoại quét mã thanh toán, vô cùng tiện lợi."},{"type":"compound","zh":"在网上买东西付款之前，一定要仔细检查一遍收货地址和商品数量。","pinyin":"Zài wǎngshang mǎidōngxi fùkuǎn zhīqián, yídìngyào zǐxì jiǎnchá yíbiàn shōuhuò dìzhǐ hé shāngpǐn shùliàng.","vi":"Trước khi thanh toán mua hàng trên mạng, nhất định phải kiểm tra kỹ lại địa chỉ nhận hàng và số lượng sản phẩm."}],"related":[{"hanzi":"现金","pinyin":"xiànjīn","vi":"Tiền mặt"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"购物","pinyin":"gòuwù","vi":"Mua sắm"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"价格","pinyin":"jiàgé","vi":"Giá cả"}]},{"id":"负责","hanzi":"负责","pinyin":"fùzé","meaning_vi":"phụ trách, chịu trách nhiệm","explanation":"负 (gánh vác) + 责 (trách nhiệm).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"我负责这个项目。","pinyin":"Wǒ fùzé zhè ge xiàngmù.","vi":"Tôi phụ trách dự án này."},{"type":"simple","zh":"王老师不仅教学经验丰富，而且对每一位学生都非常认真负责。","pinyin":"Wáng lǎoshī bùjǐn jiāoxué jīngyàn fēngfù, érqiě duì měi yí wèi xuésheng dōu fēicháng rènzhēn fùzé.","vi":"Thầy Vương không chỉ giàu kinh nghiệm giảng dạy mà đối với mỗi học sinh đều vô cùng tận tâm có trách nhiệm."},{"type":"compound","zh":"因为李经理最近去外地出差了，所以部门里的日常工作暂时由我负责。","pinyin":"Yīnwèi Lǐ jīnglǐ zuìjìn qù wàidì chūchāi le, suǒyǐ bùmén lǐ de rìcháng gōngzuò zànshí yóu wǒ fùzé.","vi":"Vì giám đốc Lý dạo này đi công tác xa nên công việc hằng ngày trong phòng tạm thời do tôi phụ trách."}],"related":[{"hanzi":"责任","pinyin":"zérèn","vi":"Trách nhiệm"},{"hanzi":"任务","pinyin":"rènwu","vi":"Nhiệm vụ"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"}],"traditional":"負責"},{"id":"改变","hanzi":"改变","pinyin":"gǎibiàn","meaning_vi":"thay đổi, cải biến","explanation":"改 (sửa đổi) + 变 (biến hóa). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"他改变了自己的看法。","pinyin":"Tā gǎibiànle zìjǐ de kànfǎ.","vi":"Anh ấy đã thay đổi cách nhìn của mình."},{"type":"simple","zh":"来到中国留学以后，我的生活习惯和性格都发生了一些积极的改变。","pinyin":"Láidào Zhōngguó liúxué yǐhòu, wǒ de shēnghuó xíguàn hé xìnggé dōu fāshēngle yìxiē jījí de gǎibiàn.","vi":"Sau khi đến Trung Quốc du học, thói quen sinh hoạt và tính cách của tôi đều có những thay đổi tích cực."},{"type":"compound","zh":"虽然我们不能改变天气，但是我们可以改变自己的心情，每天保持微笑。","pinyin":"Suīrán wǒmen bù néng gǎibiàn tiānqì, dànshì wǒmen kěyǐ gǎibiàn zìjǐ de xīnqíng, měitiān bǎochí wēixiào.","vi":"Tuy chúng ta không thể thay đổi thời tiết nhưng chúng ta có thể thay đổi tâm trạng của mình và giữ nụ cười mỗi ngày."}],"related":[{"hanzi":"变化","pinyin":"biànhuà","vi":"Biến hóa"},{"hanzi":"修改","pinyin":"xiūgǎi","vi":"Sửa đổi"},{"hanzi":"改善","pinyin":"gǎishàn","vi":"Cải thiện"},{"hanzi":"看法","pinyin":"kànfǎ","vi":"Cách nhìn"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"}],"traditional":"改變"},{"id":"干杯","hanzi":"干杯","pinyin":"gānbēi","meaning_vi":"cạn ly, nâng cốc","explanation":"干 (cạn khô) + 杯 (cốc). Dùng khi chúc rượu/nước trên bàn tiệc.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🥂","examples":[{"type":"basic","zh":"为了我们的友谊，干杯！","pinyin":"Wèile wǒmen de yǒuyì, gānbēi!","vi":"Vì tình bạn của chúng ta, cạn ly!"},{"type":"simple","zh":"新年聚会上，大家纷纷举起酒杯，互相祝福新年快乐并一起干杯。","pinyin":"Xīnnián jùhuì shang, dàjiā fēnfēn jǔqǐ jiǔbēi, hùxiāng zhùfú xīnnián kuàilè bìng yìqǐ gānbēi.","vi":"Tại bữa tiệc năm mới, mọi người cùng nâng cốc chúc nhau năm mới vui vẻ và cạn ly."},{"type":"compound","zh":"虽然我不会喝酒，但是为了表达对大家的感谢，我用果汁代替酒跟大家干杯。","pinyin":"Suīrán wǒ bú huì hējiǔ, dànshì wèile biǎodá duì dàjiā de gǎnxiè, wǒ yòng guǒzhī dàitì jiǔ gēn dàjiā gānbēi.","vi":"Tuy tôi không biết uống rượu nhưng để bày tỏ lòng cảm ơn tới mọi người, tôi dùng nước trái cây thay rượu cạn ly cùng mọi người."}],"related":[{"hanzi":"杯子","pinyin":"bēizi","vi":"Cái cốc"},{"hanzi":"杯","pinyin":"bēi","vi":"Cốc/Ly"},{"hanzi":"啤酒","pinyin":"píjiǔ","vi":"Bia"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"Đồ uống"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"Tụ họp"}],"traditional":"乾杯"},{"id":"赶","hanzi":"赶","pinyin":"gǎn","meaning_vi":"đuổi theo; vội, gấp (cho kịp)","explanation":"Bộ tẩu 走 + 干. Dùng trong 赶时间 (vội thời gian), 赶上 (đuổi kịp).","hsk_level":3,"tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"快点儿，我要赶火车！","pinyin":"Kuàidiǎnr, wǒ yào gǎn huǒchē!","vi":"Nhanh lên, tôi phải đi cho kịp chuyến tàu!"},{"type":"simple","zh":"因为起床晚了，他连早饭都没来得及吃就急忙赶去公司上班。","pinyin":"Yīnwèi qǐchuáng wǎn le, tā lián zǎofàn dōu méi láidejí chī jiù jímáng gǎn qù gōngsī shàngbān.","vi":"Vì thức dậy muộn, anh ấy đến cả bữa sáng cũng không kịp ăn đã vội vàng chạy tới công ty làm việc."},{"type":"compound","zh":"幸好我们提前出发了，在飞机起飞前二十分钟终于赶到了登机口。","pinyin":"Xìnghǎo wǒmen tíqián chūfā le, zài fēijī qǐfēi qián èrshí fēnzhōng zhōngyú gǎndàole dēngjīkǒu.","vi":"May mà chúng tôi xuất phát sớm, cuối cùng đã kịp tới cửa lên máy bay trước khi máy bay cất cánh 20 phút."}],"related":[{"hanzi":"赶紧","pinyin":"gǎnjǐn","vi":"Khẩn trương"},{"hanzi":"来得及","pinyin":"láidejí","vi":"Kịp"},{"hanzi":"来不及","pinyin":"láibují","vi":"Không kịp"},{"hanzi":"着急","pinyin":"zháojí","vi":"Vội vàng"},{"hanzi":"快","pinyin":"kuài","vi":"Nhanh"}],"traditional":"趕"},{"id":"敢","hanzi":"敢","pinyin":"gǎn","meaning_vi":"dám","explanation":"Động từ năng nguyện đứng trước động từ khác (不敢说 - không dám nói).","hsk_level":3,"tags":["dong-tu"],"image":"🦁","examples":[{"type":"basic","zh":"我不敢一个人走夜路。","pinyin":"Wǒ bù gǎn yígerén zǒu yè lù.","vi":"Tôi không dám đi đường đêm một mình."},{"type":"simple","zh":"刚开始学汉语的时候，他因为怕说错，总是不敢开口跟中国人说话。","pinyin":"Gāng kāishǐ xué Hànyǔ de shíhou, tā yīnwèi pà shuō cuò, zǒngshì bù gǎn kāikǒu gēn Zhōngguórén shuōhuà.","vi":"Lúc mới bắt đầu học tiếng Trung, vì sợ nói sai nên anh ấy luôn không dám mở miệng nói chuyện với người Trung Quốc."},{"type":"compound","zh":"只要你勇敢地迈出第一步，敢于尝试新事物，就会发现自己比想象中更优秀。","pinyin":"Zhǐyào nǐ yǒnggǎn de màichū dìyībù, gǎnyú chángshì xīn shìwù, jiù huì fāxiàn zìjǐ bǐ xiǎngxiàng zhōng gèng yōuxiù.","vi":"Chỉ cần bạn dũng cảm bước ra bước đầu tiên, dám thử thách những điều mới mẻ thì sẽ thấy bản thân giỏi hơn mình tưởng."}],"related":[{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"Dũng cảm"},{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"},{"hanzi":"能","pinyin":"néng","vi":"Có thể"},{"hanzi":"会","pinyin":"huì","vi":"Biết/Sẽ"},{"hanzi":"尝试","pinyin":"chángshì","vi":"Thử sức"}]},{"id":"感谢","hanzi":"感谢","pinyin":"gǎnxiè","meaning_vi":"cảm tạ, biết ơn","explanation":"感 (cảm nhận) + 谢 (cảm ơn). Trang trọng hơn 谢谢.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"非常感谢您的帮助！","pinyin":"Fēicháng gǎnxiè nín de bāngzhù!","vi":"Vô cùng cảm ơn sự giúp đỡ của ngài!"},{"type":"simple","zh":"在这次比赛中取得好成绩，我首先要感谢老师对我的悉心指导。","pinyin":"Zài zhè cì bǐsài zhōng qǔdé hǎo chéngjì, wǒ shǒuxiān yào gǎnxiè lǎoshī duì wǒ de xīxīn zhǐdǎo.","vi":"Đạt được thành tích tốt trong cuộc thi lần này, trước tiên tôi muốn cảm ơn sự hướng dẫn tận tình của thầy giáo."},{"type":"compound","zh":"虽然我们只是做了力所能及的小事，但是老人依然拉着我们的手再三表示感谢。","pinyin":"Suīrán wǒmen zhǐshì zuòle lìsuǒnéngjí de xiǎoshì, dànshì lǎorén yīrán lāzhe wǒmen de shǒu zàisān biǎoshì gǎnxiè.","vi":"Tuy chúng tôi chỉ làm việc nhỏ trong khả năng nhưng cụ già vẫn nắm tay chúng tôi cảm ơn hết lần này đến lần khác."}],"related":[{"hanzi":"谢谢","pinyin":"xièxie","vi":"Cảm ơn"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"Cảm động"},{"hanzi":"表示","pinyin":"biǎoshì","vi":"Bày tỏ"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"感謝"},{"id":"感冒","hanzi":"感冒","pinyin":"gǎnmào","meaning_vi":"cảm cúm, bị cảm","explanation":"感 (cảm nhiễm) + 冒 (bốc ra). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"🤧","examples":[{"type":"basic","zh":"我昨天着凉感冒了。","pinyin":"Wǒ zuótiān zháoliáng gǎnmào le.","vi":"Hôm qua tôi bị nhiễm lạnh cảm cúm rồi."},{"type":"simple","zh":"最近天气变化很大，早晚很冷，大家一定要注意保暖，别感冒了。","pinyin":"Zuìjìn tiānqì biànhuà hěn dà, zǎowǎn hěn lěng, dàjiā yídìngyào zhùyì bǎonuǎn, bié gǎnmào le.","vi":"Dạo này thời tiết thay đổi lớn, sáng tối rất lạnh, mọi người nhất định phải chú ý giữ ấm, đừng để bị cảm cúm."},{"type":"compound","zh":"虽然只是普通的感冒，但是也要多喝温开水、多休息，这样才能好得快。","pinyin":"Suīrán zhǐshì pǔtōng de gǎnmào, dànshì yě yào duō hē wēn kāishuǐ, duō xiūxi, zhèyàng cáinéng hǎo de kuài.","vi":"Tuy chỉ là cảm cúm thông thường nhưng cũng phải uống nhiều nước ấm và nghỉ ngơi nhiều thì mới nhanh khỏi."}],"related":[{"hanzi":"发烧","pinyin":"fāshāo","vi":"Phát sốt"},{"hanzi":"咳嗽","pinyin":"késou","vi":"Ho"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"吃药","pinyin":"chīyào","vi":"Uống thuốc"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"}]},{"id":"挂","hanzi":"挂","pinyin":"guà","meaning_vi":"treo; cúp (máy điện thoại)","explanation":"Bộ tài gảy 扌+ 卦. Dùng cho 挂画 (treo tranh), 挂电话 (cúp điện thoại).","hsk_level":3,"tags":["dong-tu"],"image":"🖼️","examples":[{"type":"basic","zh":"墙上挂着一张中国地图。","pinyin":"Qiáng shang guàzhe yì zhāng Zhōngguó dìtú.","vi":"Trên tường đang treo một tấm bản đồ Trung Quốc."},{"type":"simple","zh":"他刚说完“再见”，就匆忙地把电话挂断了。","pinyin":"Tā gāng shuō wán \"zàijiàn\", jiù cōngmáng de bǎ diànhuà guàduàn le.","vi":"Anh ấy vừa nói xong câu “tạm biệt” liền vội vàng cúp máy điện thoại."},{"type":"compound","zh":"过春节的时候，人们喜欢在门口挂上大红灯笼，显得既喜庆又热闹。","pinyin":"Guò Chūnjié de shíhou, rénmen xǐhuan zài ménkǒu guà shàng dàhóng dēnglong, xiǎnde jì xǐqìng yòu rènao.","vi":"Vào dịp Tết Nguyên đán, mọi người thích treo đèn lồng đỏ lớn trước cửa, trông vừa vui mừng vừa náo nhiệt."}],"related":[{"hanzi":"放","pinyin":"fàng","vi":"Đặt/Để"},{"hanzi":"电话","pinyin":"diànhuà","vi":"Điện thoại"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"照片","pinyin":"zhàopiàn","vi":"Bức ảnh"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"}],"traditional":"掛"},{"id":"管理","hanzi":"管理","pinyin":"guǎnlǐ","meaning_vi":"quản lý","explanation":"管 (cai quản) + 理 (sắp xếp). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"他负责管理这家公司。","pinyin":"Tā fùzé guǎnlǐ zhè jiā gōngsī.","vi":"Anh ấy phụ trách quản lý công ty này."},{"type":"simple","zh":"大学毕业以后，他在一家国际酒店学习酒店管理经验。","pinyin":"Dàxué bìyè yǐhòu, tā zài yìjiā Guójì jiǔdiàn xuéxí jiǔdiàn guǎnlǐ jīngyàn.","vi":"Sau khi tốt nghiệp đại học, anh ấy học hỏi kinh nghiệm quản lý khách sạn tại một khách sạn quốc tế."},{"type":"compound","zh":"一个优秀的管理者不仅要有专业知识，还要懂得如何与同事沟通合作。","pinyin":"Yí ge yōuxiù de guǎnlǐ zhě bùjǐn yàoyǒu zhuānyè zhīshi, hái yào dǒngde rúhé yǔ tóngshì gōutōng hézuò.","vi":"Một người quản lý xuất sắc không chỉ cần có kiến thức chuyên môn mà còn phải biết cách giao tiếp và hợp tác với đồng nghiệp."}],"related":[{"hanzi":"处理","pinyin":"chǔlǐ","vi":"Xử lý"},{"hanzi":"负责","pinyin":"fùzé","vi":"Phụ trách"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"经理","pinyin":"jīnglǐ","vi":"Giám đốc"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"}]},{"id":"广播","hanzi":"广播","pinyin":"guǎngbō","meaning_vi":"phát thanh, đài phát thanh","explanation":"广 (rộng) + 播 (phát sóng).","hsk_level":3,"tags":["danh-tu","cong-nghe"],"image":"📻","examples":[{"type":"basic","zh":"爷爷喜欢听广播。","pinyin":"Yéye xǐhuan tīng guǎngbō.","vi":"Ông nội thích nghe đài phát thanh."},{"type":"simple","zh":"每天早上吃早饭的时候，爸爸都会打开收音机听新闻广播。","pinyin":"Měitiān zǎoshang chī zǎofàn de shíhou, bàba dōuhuì dǎkāi shōuyīnjī tīng xīnwén guǎngbō.","vi":"Mỗi sáng lúc ăn bữa sáng, bố đều bật đài lên nghe bản tin phát thanh."},{"type":"compound","zh":"多听中文广播不仅可以了解最新消息，还能帮助我们练习标准的普通话发音。","pinyin":"Duō tīng Zhōngwén guǎngbō bùjǐn kěyǐ liǎojiě zuì xīn xiāoxi, hái néng bāngzhù wǒmen liànxí biāozhǔn de pǔtōnghuà fāyīn.","vi":"Nghe nhiều đài phát thanh tiếng Trung không những nắm bắt được tin tức mới nhất mà còn giúp chúng ta luyện phát âm tiếng phổ thông chuẩn."}],"related":[{"hanzi":"传播","pinyin":"chuánbō","vi":"Truyền bá"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"Tin tức"},{"hanzi":"听","pinyin":"tīng","vi":"Nghe"},{"hanzi":"普通话","pinyin":"pǔtōnghuà","vi":"Tiếng phổ thông"},{"hanzi":"电视","pinyin":"diànshì","vi":"Tivi"}],"traditional":"廣播"},{"id":"逛","hanzi":"逛","pinyin":"guàng","meaning_vi":"dạo, đi dạo (phố/chợ)","explanation":"Bộ quai xước 辶 + 狂. Dùng trong 逛街 (dạo phố), 逛超市 (dạo siêu thị).","hsk_level":3,"tags":["dong-tu","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"周末我喜欢和朋友逛街。","pinyin":"Zhōumò wǒ xǐhuan hé péngyou guàngjiē.","vi":"Cuối tuần tôi thích đi dạo phố với bạn bè."},{"type":"simple","zh":"妈妈每天下午下班以后都会去家附近的超市逛一逛，买些新鲜蔬菜。","pinyin":"Māma měitiān xiàwǔ xiàbān yǐhòu dōuhuì qù jiā fùjìn de chāoshì guàng yi guàng, mǎi xiē xīnxiān shūcài.","vi":"Mẹ mỗi chiều sau khi tan làm đều ghé siêu thị gần nhà dạo một vòng, mua một ít rau tươi."},{"type":"compound","zh":"虽然我们昨天逛了整整一下午的商场，但是因为衣服太贵，所以什么也没买。","pinyin":"Suīrán wǒmen zuótiān guàngle zhěngzhěng yī xiàwǔ de shāngchǎng, dànshì yīnwèi yīfu tài guì, suǒyǐ shénme yě méi mǎi.","vi":"Tuy hôm qua chúng tôi dạo trung tâm thương mại suốt cả buổi chiều nhưng vì quần áo đắt quá nên chẳng mua gì cả."}],"related":[{"hanzi":"购物","pinyin":"gòuwù","vi":"Mua sắm"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"商店","pinyin":"shāngdiàn","vi":"Cửa hàng"},{"hanzi":"散步","pinyin":"sànbù","vi":"Đi dạo"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"}]},{"id":"规定","hanzi":"规定","pinyin":"guīdìng","meaning_vi":"quy định","explanation":"规 (quy tắc) + 定 (xác định). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","danh-tu"],"image":"📜","examples":[{"type":"basic","zh":"学校有严格的规定。","pinyin":"Xuéxiào yǒu yángé de guīdìng.","vi":"Nhà trường có quy định nghiêm ngặt."},{"type":"simple","zh":"图书馆规定读者不能把饮料和零食带进阅览室里面。","pinyin":"Túshūguǎn guīdìng dúzhě bù néng bǎ yǐnliào hé língshí dài jìn yuèlǎnshì lǐmiàn.","vi":"Thư viện quy định độc giả không được mang đồ uống và đồ ăn vặt vào trong phòng đọc."},{"type":"compound","zh":"无论是开车还是骑自行车，每个人都必须严格遵守交通规则和规定。","pinyin":"Wúlùn shì kāichē háishi qí zìxíngchē, měigerén dōu bìxū yángé zūnshǒu jiāotōng guīzé hé guīdìng.","vi":"Dù là lái ô tô hay đi xe đạp, mọi người đều bắt buộc phải tuân thủ nghiêm ngặt luật lệ và quy định giao thông."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"Pháp luật"},{"hanzi":"严格","pinyin":"yángé","vi":"Nghiêm ngặt"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"}],"traditional":"規定"},{"id":"害羞","hanzi":"害羞","pinyin":"hàixiū","meaning_vi":"xấu hổ, ngại ngùng","explanation":"害 (mắc phải) + 羞 (thẹn thùng).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"这个小女孩很害羞。","pinyin":"Zhè ge xiǎo nǚhái hěn hàixiū.","vi":"Cô bé này rất hay ngại ngùng."},{"type":"simple","zh":"每次在很多人面前发言的时候，她都会觉得有点儿害羞。","pinyin":"Měi cì zài hěn duō rén miànqián fāyán de shíhou, tā dōuhuì juéde yǒudiǎnr hàixiū.","vi":"Mỗi lần phát biểu trước mặt nhiều người, cô ấy đều cảm thấy hơi ngại ngùng một chút."},{"type":"compound","zh":"学外语的时候千万不要害羞，只有大胆地开口和别人交流才能进步。","pinyin":"Xué wàiyǔ de shíhou qiānwàn bú yào hàixiū, zhǐyǒu dàdǎn de kāikǒu hé biérén jiāoliú cáinéng jìnbù.","vi":"Khi học ngoại ngữ tuyệt đối đừng rụt rè ngại ngùng, chỉ có mạnh dạn mở miệng giao tiếp với người khác mới tiến bộ được."}],"related":[{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"},{"hanzi":"脸","pinyin":"liǎn","vi":"Khuôn mặt"},{"hanzi":"红","pinyin":"hóng","vi":"Đỏ"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"Dũng cảm"},{"hanzi":"自信","pinyin":"zìxìn","vi":"Tự tin"}]},{"id":"合作","hanzi":"合作","pinyin":"hézuò","meaning_vi":"hợp tác","explanation":"合 (hợp lại) + 作 (làm việc).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"祝我们合作愉快！","pinyin":"Zhù wǒmen hézuò yúkuài!","vi":"Chúc chúng ta hợp tác vui vẻ!"},{"type":"simple","zh":"我们两家公司已经合作很多年了，彼此之间非常信任。","pinyin":"Wǒmen liǎng jiā gōngsī yǐjīng hézuò hěn duōnián le, bǐcǐ zhījiān fēicháng xìnrèn.","vi":"Hai công ty chúng tôi đã hợp tác nhiều năm rồi, đôi bên vô cùng tin tưởng lẫn nhau."},{"type":"compound","zh":"在现代社会中，很多复杂的工作任务都需要团队成员互相合作才能完成。","pinyin":"Zài xiàndài shèhuì zhōng, hěn duō fùzá de gōngzuò rènwu dōu xūyào tuánduì chéngyuán hùxiāng hézuò cáinéng wánchéng.","vi":"Trong xã hội hiện đại, nhiều nhiệm vụ công việc phức tạp đều cần các thành viên trong nhóm hợp tác với nhau mới hoàn thành được."}],"related":[{"hanzi":"工作","pinyin":"gōngzuò","vi":"Làm việc"},{"hanzi":"符合","pinyin":"fúhé","vi":"Phù hợp"},{"hanzi":"合适","pinyin":"héshì","vi":"Thích hợp"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"愉快","pinyin":"yúkuài","vi":"Vui vẻ"}]},{"id":"合适","hanzi":"合适","pinyin":"héshì","meaning_vi":"thích hợp, vừa vặn","explanation":"合 (hợp) + 适 (vừa ý). Dùng cho quần áo, thời gian, công việc.","hsk_level":3,"tags":["tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"这双鞋很合适。","pinyin":"Zhè shuāng xié hěn héshì.","vi":"Đôi giày này rất vừa vặn."},{"type":"simple","zh":"这件衬衫你穿着大小正合适。","pinyin":"Zhè jiàn chènshān nǐ chuānzhe dàxiǎo zhèng héshì.","vi":"Chiếc áo sơ mi này bạn mặc vừa đúng cỡ."},{"type":"compound","zh":"如果你觉得明天上午九点见面不太合适，我们可以改到下午三点。","pinyin":"Rúguǒ nǐ juéde míngtiān shàngwǔ jiǔ diǎn jiànmiàn bú tài héshì, wǒmen kěyǐ gǎi dào xiàwǔ sān diǎn.","vi":"Nếu bạn thấy gặp mặt lúc 9 giờ sáng mai không tiện lắm thì chúng ta có thể đổi sang 3 giờ chiều."}],"related":[{"hanzi":"适合","pinyin":"shìhé","vi":"Thích hợp"},{"hanzi":"符合","pinyin":"fúhé","vi":"Phù hợp"},{"hanzi":"舒服","pinyin":"shūfu","vi":"Thoải mái"},{"hanzi":"正好","pinyin":"zhènghǎo","vi":"Vừa vặn"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"}],"traditional":"合適"},{"id":"后悔","hanzi":"后悔","pinyin":"hòuhuǐ","meaning_vi":"hối hận, ân hận","explanation":"后 (về sau) + 悔 (ăn năn).","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"我一点儿也不后悔。","pinyin":"Wǒ yìdiǎnr yě bú hòuhuǐ.","vi":"Tôi không hối hận chút nào cả."},{"type":"simple","zh":"昨天没买那件打折的漂亮大衣，回家以后她觉得非常后悔。","pinyin":"Zuótiān méi mǎi nà jiàn dǎzhé de piàoliang dàyī, huíjiā yǐhòu tā juéde fēicháng hòuhuǐ.","vi":"Hôm qua không mua chiếc áo khoác đẹp đang giảm giá đó, về nhà xong cô ấy cảm thấy vô cùng hối tiếc."},{"type":"compound","zh":"年轻的时候应该多努力学习知识，千万不要等到老了以后才后悔。","pinyin":"Niánqīng de shíhou yīnggāi duō nǔlì xuéxí zhīshi, qiānwàn bú yào děngdào lǎole yǐhòu cái hòuhuǐ.","vi":"Khi còn trẻ nên chăm chỉ học tập kiến thức, đừng bao giờ đợi đến lúc về già rồi mới hối hận."}],"related":[{"hanzi":"后来","pinyin":"hòulái","vi":"Sau này"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau khi"},{"hanzi":"难过","pinyin":"nánguò","vi":"Buồn bã"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"}],"traditional":"後悔"},{"id":"怀疑","hanzi":"怀疑","pinyin":"huáiyí","meaning_vi":"nghi ngờ, hoài nghi","explanation":"怀 (ôm giữ trong lòng) + 疑 (ngờ vực). Đối nghĩa với 相信 (tin tưởng).","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"🤨","examples":[{"type":"basic","zh":"我从不怀疑他的能力。","pinyin":"Wǒ cóng bù huáiyí tā de nénglì.","vi":"Tôi chưa bao giờ nghi ngờ năng lực của anh ấy."},{"type":"simple","zh":"警察怀疑他说了假话。","pinyin":"Jǐngchá huáiyí tā shuōle jiǎhuà.","vi":"Cảnh sát nghi ngờ anh ta nói dối."},{"type":"compound","zh":"朋友之间最重要的是互相信任，如果总是互相怀疑，友谊就很难长久。","pinyin":"Péngyou zhījiān zuì zhòngyào de shì hùxiāng xìnrèn, rúguǒ zǒngshì hùxiāng huáiyí, yǒuyì jiù hěn nán chángjiǔ.","vi":"Giữa bạn bè với nhau quan trọng nhất là tin tưởng lẫn nhau, nếu cứ luôn nghi ngờ nhau thì tình bạn khó mà bền lâu."}],"related":[{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"以为","pinyin":"yǐwéi","vi":"Tưởng rằng"},{"hanzi":"认为","pinyin":"rènwéi","vi":"Cho rằng"},{"hanzi":"误会","pinyin":"wùhuì","vi":"Hiểu lầm"},{"hanzi":"友谊","pinyin":"yǒuyì","vi":"Tình bạn"}],"traditional":"懷疑"},{"id":"回忆","hanzi":"回忆","pinyin":"huíyì","meaning_vi":"hồi ức, nhớ lại","explanation":"回 (quay lại) + 忆 (nhớ). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"💭","examples":[{"type":"basic","zh":"这是一段美好的回忆。","pinyin":"Zhè shì yí duàn měihǎo de huíyì.","vi":"Đây là một quãng hồi ức tươi đẹp."},{"type":"simple","zh":"看着大学毕业时的老照片，我们常常回忆起当年一起学习的快乐时光。","pinyin":"Kànzhe dàxué bìyè shí de lǎo zhàopiàn, wǒmen chángcháng huíyì qǐ dāngnián yìqǐ xuéxí de kuàilè shíguāng.","vi":"Nhìn những tấm ảnh cũ hồi tốt nghiệp đại học, chúng tôi thường nhớ lại quãng thời gian vui vẻ cùng học tập năm xưa."},{"type":"compound","zh":"虽然在中国留学的日子已经结束了，但是那段经历永远留在我的回忆里。","pinyin":"Suīrán zài Zhōngguó liúxué de rìzi yǐjīng jiéshù le, dànshì nà duàn jīnglì yǒngyuǎn liú zài wǒ de huíyì lǐ.","vi":"Tuy những ngày tháng du học ở Trung Quốc đã kết thúc nhưng trải nghiệm đó sẽ mãi đọng lại trong ký ức của tôi."}],"related":[{"hanzi":"记得","pinyin":"jìde","vi":"Nhớ"},{"hanzi":"忘记","pinyin":"wàngjì","vi":"Quên"},{"hanzi":"回家","pinyin":"huíjiā","vi":"Về nhà"},{"hanzi":"经历","pinyin":"jīnglì","vi":"Trải qua"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"}],"traditional":"回憶"},{"id":"活动","hanzi":"活动","pinyin":"huódòng","meaning_vi":"hoạt động","explanation":"活 (sống động) + 动 (chuyển động). Vừa là danh từ vừa là động từ.","hsk_level":3,"tags":["danh-tu","dong-tu"],"image":"🎪","examples":[{"type":"basic","zh":"学校周末有文化活动。","pinyin":"Xuéxiào zhōumò yǒu wénhuà huódòng.","vi":"Cuối tuần trường có hoạt động văn hóa."},{"type":"simple","zh":"长期坐在电脑前工作的人，应该每隔一个小时站起来活动一下身体。","pinyin":"Chángqī zuò zài diànnǎo qián gōngzuò de rén, yīnggāi měigé yí ge xiǎoshí zhànqǐlái huódòng yíxià shēntǐ.","vi":"Người ngồi làm việc lâu trước máy tính nên cứ cách một tiếng lại đứng dậy vận động cơ thể một chút."},{"type":"compound","zh":"通过参加各种社团活动，留学生们不仅锻炼了汉语，还结交了很多中国朋友。","pinyin":"Tōngguò cānjiā gèzhǒng shètuán huódòng, liúxuéshengmen bùjǐn duànliànle Hànyǔ, hái jiéjiāole hěn duō Zhōngguó péngyou.","vi":"Thông qua việc tham gia các hoạt động câu lạc bộ, du học sinh không những rèn luyện tiếng Trung mà còn kết bạn với nhiều người Trung Quốc."}],"related":[{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"活泼","pinyin":"huópō","vi":"Hoạt bát"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"Tổ chức"}],"traditional":"活動"},{"id":"获得","hanzi":"获得","pinyin":"huòdé","meaning_vi":"giành được, thu được","explanation":"获 (thu hoạch) + 得 (đạt được).","hsk_level":3,"tags":["dong-tu"],"image":"🏅","examples":[{"type":"basic","zh":"他获得了比赛第一名。","pinyin":"Tā huòdéle bǐsài dìyīmíng.","vi":"Anh ấy đã giành được giải nhất cuộc thi."},{"type":"simple","zh":"因为成绩非常优秀，他今年获得了学校颁发的留学生奖学金。","pinyin":"Yīnwèi chéngjì fēicháng yōuxiù, tā jīnnián huòdéle xuéxiào bānfā de liúxuésheng jiǎngxuéjīn.","vi":"Vì thành tích vô cùng xuất sắc, năm nay anh ấy đã nhận được học bổng du học sinh do nhà trường trao tặng."},{"type":"compound","zh":"在生活中，只有付出辛勤的汗水和努力，才能真正获得别人的尊重。","pinyin":"Zài shēnghuó zhōng, zhǐyǒu fùchū xīnqín de hànshuǐ hé nǔlì, cáinéng zhēnzhèng huòdé biérén de zūnzhòng.","vi":"Trong cuộc sống, chỉ có bỏ ra mồ hôi công sức và sự nỗ lực mới thực sự giành được sự tôn trọng của người khác."}],"related":[{"hanzi":"得到","pinyin":"dédào","vi":"Nhận được"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"奖学金","pinyin":"jiǎngxuéjīn","vi":"Học bổng"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"}],"traditional":"獲得"},{"id":"寄","hanzi":"寄","pinyin":"jì","meaning_vi":"gửi (thư/bưu phẩm)","explanation":"Bộ miên 宀 + 奇. Dùng cho 寄信 (gửi thư), 寄快递 (gửi chuyển phát nhanh).","hsk_level":3,"tags":["dong-tu"],"image":"📮","examples":[{"type":"basic","zh":"我去邮局寄信。","pinyin":"Wǒqù yóujú jì xìn.","vi":"Tôi đi bưu điện gửi thư."},{"type":"simple","zh":"妈妈昨天从老家给我寄了一大箱新鲜的苹果和特产。","pinyin":"Māma zuótiān cóng lǎojiā gěi wǒ jìle yí dà xiāng xīnxiān de píngguǒ hé tèchǎn.","vi":"Hôm qua mẹ đã gửi cho tôi từ quê lên một thùng lớn táo tươi và đặc sản."},{"type":"compound","zh":"现在用快递寄东西非常方便，一般两天左右就能送到收件人手里。","pinyin":"Xiànzài yòng kuàidì jì dōngxi fēicháng fāngbiàn, yìbān liǎng tiān zuǒyòu jiù néng sòng dào shōujiànrén shǒulǐ.","vi":"Hiện nay gửi đồ bằng chuyển phát nhanh vô cùng tiện lợi, thường khoảng hai ngày là giao tới tận tay người nhận."}],"related":[{"hanzi":"邮局","pinyin":"yóujú","vi":"Bưu điện"},{"hanzi":"信封","pinyin":"xìnfēng","vi":"Phong bì thư"},{"hanzi":"送","pinyin":"sòng","vi":"Gửi/Giao"},{"hanzi":"收","pinyin":"shōu","vi":"Nhận"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"}]},{"id":"加班","hanzi":"加班","pinyin":"jiābān","meaning_vi":"tăng ca, làm thêm giờ","explanation":"加 (thêm) + 班 (ca làm việc). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"爸爸今天晚上要加班。","pinyin":"Bàba jīntiān wǎnshang yào jiābān.","vi":"Tối nay bố phải tăng ca."},{"type":"simple","zh":"因为月底公司要总结财务报表，所以会计们这几天都在加班。","pinyin":"Yīnwèi yuèdǐ gōngsī yào zǒngjié cáiwù bàobiǎo, suǒyǐ kuàijìmen zhèjǐtiān dōu zài jiābān.","vi":"Vì cuối tháng công ty phải tổng kết báo cáo tài chính nên các nhân viên kế toán mấy ngày nay đều đang tăng ca."},{"type":"compound","zh":"虽然这个星期天天加班非常辛苦，但是月底拿到奖金的时候大家都很开心。","pinyin":"Suīrán zhè ge xīngqī tiāntiān jiābān fēicháng xīnkǔ, dànshì yuèdǐ nádào jiǎngjīn de shíhou dàjiā dōu hěn kāixīn.","vi":"Tuy tuần này ngày nào cũng tăng ca rất vất vả nhưng cuối tháng lúc nhận tiền thưởng ai nấy đều rất vui."}],"related":[{"hanzi":"上班","pinyin":"shàngbān","vi":"Đi làm"},{"hanzi":"下班","pinyin":"xiàbān","vi":"Tan làm"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Làm việc"},{"hanzi":"加班费","pinyin":"jiābānfèi","vi":"Tiền tăng ca"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"Vất vả"}]},{"id":"加油","hanzi":"加油","pinyin":"jiāyóu","meaning_vi":"cố lên; đổ xăng","explanation":"加 (thêm) + 油 (dầu/xăng).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"⛽","examples":[{"type":"basic","zh":"我们一起加油吧！","pinyin":"Wǒmen yìqǐ jiāyóu ba!","vi":"Chúng ta cùng cố lên nhé!"},{"type":"simple","zh":"车快没油了，我们得在前面那个加油站停下来加点儿油。","pinyin":"Chē kuài méi yóu le, wǒmen děi zài qiánmiàn nà ge jiāyóuzhàn tíngxiàlái jiā diǎnr yóu.","vi":"Xe sắp hết xăng rồi, chúng ta phải dừng lại ở trạm xăng phía trước để đổ thêm chút xăng."},{"type":"compound","zh":"比赛的时候，同学们站在跑道旁边大声喊“加油”，给了运动员很大力量。","pinyin":"Bǐsài de shíhou, tóngxuémen zhàn zài pǎodào pángbiān dàshēng hǎn \"jiāyóu\", gěile yùndòngyuán hěn dà lìliàng.","vi":"Lúc thi đấu, các bạn học đứng bên đường chạy hét lớn “cố lên”, tiếp thêm sức mạnh rất lớn cho vận động viên."}],"related":[{"hanzi":"加油站","pinyin":"jiāyóuzhàn","vi":"Trạm xăng"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"Khích lệ"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"}]},{"id":"坚持","hanzi":"坚持","pinyin":"jiānchí","meaning_vi":"kiên trì","explanation":"坚 (vững chắc) + 持 (giữ gìn).","hsk_level":3,"tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"他每天都坚持跑步。","pinyin":"Tā měitiān dōu jiānchí pǎobù.","vi":"Ngày nào anh ấy cũng kiên trì chạy bộ."},{"type":"simple","zh":"学习汉语最重要的是每天坚持练习，不能三天打鱼两天晒网。","pinyin":"Xuéxí Hànyǔ zuì zhòngyào de shì měitiān jiānchí liànxí, bù néng sān tiān dǎyú liǎng tiān shài wǎng.","vi":"Học tiếng Trung quan trọng nhất là kiên trì luyện tập mỗi ngày, không thể bữa đực bữa cái."},{"type":"compound","zh":"虽然减肥的过程非常辛苦，但是只要坚持健康饮食和运动就一定能瘦下来。","pinyin":"Suīrán jiǎnféi de guòchéng fēicháng xīnkǔ, dànshì zhǐyào jiānchí jiànkāng yǐnshí hé yùndòng jiù yídìng néng shòu xiàlái.","vi":"Tuy quá trình giảm cân vô cùng vất vả nhưng chỉ cần kiên trì ăn uống lành mạnh và tập thể dục thì nhất định sẽ gầy đi."}],"related":[{"hanzi":"放弃","pinyin":"fàngqì","vi":"Từ bỏ"},{"hanzi":"支持","pinyin":"zhīchí","vi":"Ủng hộ"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"一直","pinyin":"yìzhí","vi":"Suốt/Luôn"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"}],"traditional":"堅持"},{"id":"减肥","hanzi":"减肥","pinyin":"jiǎnféi","meaning_vi":"giảm cân","explanation":"减 (bớt đi) + 肥 (béo/mỡ). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"🥗","examples":[{"type":"basic","zh":"姐姐正在减肥。","pinyin":"Jiějie zhèngzài jiǎnféi.","vi":"Chị gái đang giảm cân."},{"type":"simple","zh":"为了夏天能穿上漂亮的裙子，她最近开始每天晚上去健身房减肥。","pinyin":"Wèile xiàtiān néng chuānshàng piàoliang de qúnzi, tā zuìjìn kāishǐ měitiān wǎnshang qù jiànshēnfáng jiǎnféi.","vi":"Để mùa hè có thể mặc váy đẹp, dạo này cô ấy bắt đầu tối nào cũng đến phòng gym giảm cân."},{"type":"compound","zh":"科学的减肥方法是少吃高热量食物并坚持运动，而不是盲目节食。","pinyin":"Kēxué de jiǎnféi fāngfǎ shì shǎo chī gāorèliàng shíwù bìng jiānchí yùndòng, ér bú shì mángmù jiéshí.","vi":"Phương pháp giảm cân khoa học là ăn ít thực phẩm nhiều calo và kiên trì vận động, chứ không phải nhịn ăn mù quáng."}],"related":[{"hanzi":"胖","pinyin":"pàng","vi":"Béo"},{"hanzi":"瘦","pinyin":"shòu","vi":"Gầy"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"Giảm bớt"},{"hanzi":"锻炼","pinyin":"duànliàn","vi":"Rèn luyện"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"}],"traditional":"減肥"},{"id":"减少","hanzi":"减少","pinyin":"jiǎnshǎo","meaning_vi":"giảm bớt, cắt giảm","explanation":"减 (giảm) + 少 (ít). Đối nghĩa với 增加 (tăng thêm).","hsk_level":3,"tags":["dong-tu"],"image":"📉","examples":[{"type":"basic","zh":"我们要减少浪费。","pinyin":"Wǒmen yào jiǎnshǎo làngfèi.","vi":"Chúng ta phải giảm bớt lãng phí."},{"type":"simple","zh":"随着手机支付的普及，用现金的人减少了很多。","pinyin":"Suízhe shǒujī zhīfù de pǔjí, yòng xiànjīn de rén jiǎnshǎole hěn duō.","vi":"Cùng với sự phổ biến của thanh toán bằng điện thoại, người dùng tiền mặt đã giảm đi rất nhiều."},{"type":"compound","zh":"多坐地铁和公共汽车不仅能节省交通费用，还能减少城市空气污染。","pinyin":"Duō zuò dìtiě hé gōnggòngqìchē bùjǐn néng jiéshěng jiāotōng fèiyòng, hái néng jiǎnshǎo chéngshì kōngqì wūrǎn.","vi":"Đi tàu điện ngầm và xe buýt nhiều hơn không những tiết kiệm chi phí đi lại mà còn giảm thiểu ô nhiễm không khí đô thị."}],"related":[{"hanzi":"增加","pinyin":"zēngjiā","vi":"Tăng thêm"},{"hanzi":"少","pinyin":"shǎo","vi":"Ít"},{"hanzi":"减肥","pinyin":"jiǎnféi","vi":"Giảm cân"},{"hanzi":"降低","pinyin":"jiàngdī","vi":"Hạ thấp"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"}],"traditional":"減少"},{"id":"增加","hanzi":"增加","pinyin":"zēngjiā","meaning_vi":"tăng thêm, gia tăng","explanation":"增 (tăng) + 加 (thêm). Đối nghĩa với 减少 (giảm bớt).","hsk_level":3,"tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"学生人数增加了。","pinyin":"Xuésheng rénshù zēngjiā le.","vi":"Số lượng học sinh đã tăng lên rồi."},{"type":"simple","zh":"多阅读课外书籍可以帮助我们扩大知识面，增加词汇量。","pinyin":"Duō yuèdú kèwài shūjí kěyǐ bāngzhù wǒmen kuòdà zhīshimiàn, zēngjiā cíhuìliàng.","vi":"Đọc nhiều sách ngoài giờ học có thể giúp chúng ta mở rộng kiến thức và tăng vốn từ vựng."},{"type":"compound","zh":"虽然今年公司的运营成本有所增加，但是整体收入依然比去年高出很多。","pinyin":"Suīrán jīnnián gōngsī de yùnyíng chéngběn yǒusuǒ zēngjiā, dànshì zhěngtǐ shōurù yīrán bǐ qùnián gāochū hěn duō.","vi":"Tuy năm nay chi phí vận hành của công ty có tăng lên đôi chút nhưng tổng doanh thu vẫn cao hơn năm ngoái rất nhiều."}],"related":[{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"Giảm bớt"},{"hanzi":"加","pinyin":"jiā","vi":"Thêm"},{"hanzi":"加班","pinyin":"jiābān","vi":"Tăng ca"},{"hanzi":"多","pinyin":"duō","vi":"Nhiều"},{"hanzi":"提高","pinyin":"tígāo","vi":"Nâng cao"}]},{"id":"建议","hanzi":"建议","pinyin":"jiànyì","meaning_vi":"đề nghị, khuyên; lời khuyên, kiến nghị","explanation":"建 (nêu ra) + 议 (bàn bạc). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💡","examples":[{"type":"basic","zh":"谢谢你的好建议。","pinyin":"Xièxie nǐ de hǎo jiànyì.","vi":"Cảm ơn lời khuyên hay của bạn."},{"type":"simple","zh":"医生建议他每天晚饭后散步半个小时，这样对消化非常有好处。","pinyin":"Yīshēng jiànyì tā měitiān wǎnfàn hòu sànbù bàn ge xiǎoshí, zhèyàng duìxiāo huà fēicháng yǒu hǎochu.","vi":"Bác sĩ khuyên anh ấy mỗi ngày sau bữa tối nên đi dạo nửa tiếng, như vậy rất tốt cho tiêu hóa."},{"type":"compound","zh":"如果你不知道怎么提高听力，我建议你每天坚持听半个小时中文广播。","pinyin":"Rúguǒ nǐ bù zhīdao zěnme tígāo tīnglì, wǒ jiànyì nǐ měitiān jiānchí tīng bàn ge xiǎoshí Zhōngwén guǎngbō.","vi":"Nếu bạn không biết làm thế nào để nâng cao khả năng nghe, tôi khuyên bạn mỗi ngày kiên trì nghe đài tiếng Trung nửa tiếng."}],"related":[{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"主意","pinyin":"zhǔyi","vi":"Chủ ý"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"Thảo luận"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"Biện pháp"}],"traditional":"建議"},{"id":"将来","hanzi":"将来","pinyin":"jiānglái","meaning_vi":"tương lai, sau này","explanation":"将 (sắp) + 来 (tới). Danh từ chỉ thời gian.","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"🔮","examples":[{"type":"basic","zh":"你将来想做什么工作？","pinyin":"Nǐ jiānglái xiǎng zuò shénme gōngzuò?","vi":"Tương lai bạn muốn làm công việc gì?"},{"type":"simple","zh":"我妹妹非常喜欢画画，她希望将来能成为一名优秀的服装设计师。","pinyin":"Wǒ mèimei fēicháng xǐhuan huàhuà, tā xīwàng jiānglái néng chéngwéi yì míng yōuxiù de fúzhuāng shèjìshī.","vi":"Em gái tôi vô cùng thích vẽ tranh, bé hy vọng tương lai có thể trở thành một nhà thiết kế thời trang giỏi."},{"type":"compound","zh":"现在认真学好每一门专业课，就是为了将来在社会上拥有更强的竞争力。","pinyin":"Xiànzài rènzhēn xuéhǎo měi yì mén zhuānyè kè, jiùshì wèile jiānglái zài shèhuì shang yōngyǒu gèng qiáng de jìngzhēnglì.","vi":"Bây giờ chăm chỉ học tốt từng môn chuyên ngành chính là để tương lai có năng lực cạnh tranh mạnh mẽ hơn ngoài xã hội."}],"related":[{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau này"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"理想","pinyin":"lǐxiǎng","vi":"Lý tưởng"},{"hanzi":"希望","pinyin":"xīwàng","vi":"Hy vọng"}],"traditional":"將來"},{"id":"交流","hanzi":"交流","pinyin":"jiāoliú","meaning_vi":"giao lưu, trao đổi","explanation":"交 (qua lại) + 流 (chảy/trôi).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"我们要多跟中国人交流。","pinyin":"Wǒmen yào duō gēn Zhōngguórén jiāoliú.","vi":"Chúng ta phải giao lưu nhiều hơn với người Trung Quốc."},{"type":"simple","zh":"语言是人与人之间沟通和交流的重要桥梁。","pinyin":"Yǔyán shì rén yǔ rén zhījiān gōutōng hé jiāoliú de zhòngyào qiáoliáng.","vi":"Ngôn ngữ là cây cầu quan trọng để giao tiếp và trao đổi giữa người với người."},{"type":"compound","zh":"虽然我们来自不同的文化背景，但是在交流的过程中发现大家有很多共同点。","pinyin":"Suīrán wǒmen láizì bùtóng de wénhuà bèijǐng, dànshì zài jiāoliú de guòchéng zhōng fāxiàn dàjiā yǒu hěn duō gòngtóngdiǎn.","vi":"Tuy chúng tôi đến từ những nền tảng văn hóa khác nhau nhưng trong quá trình giao lưu nhận thấy mọi người có rất nhiều điểm chung."}],"related":[{"hanzi":"交","pinyin":"jiāo","vi":"Giao/Nộp"},{"hanzi":"流利","pinyin":"liúlì","vi":"Trôi chảy"},{"hanzi":"沟通","pinyin":"gōutōng","vi":"Giao tiếp"},{"hanzi":"语言","pinyin":"yǔyán","vi":"Ngôn ngữ"},{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"}]},{"id":"交","hanzi":"交","pinyin":"jiāo","meaning_vi":"nộp, giao; kết (bạn)","explanation":"Dùng trong 交作业 (nộp bài tập), 交朋友 (kết bạn).","hsk_level":3,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"请大家交作业。","pinyin":"Qǐng dàjiā jiāo zuòyè.","vi":"Xin mọi người nộp bài tập."},{"type":"simple","zh":"来到中国大学以后，我很快就在班里交到了几个热情的中国朋友。","pinyin":"Láidào Zhōngguó dàxué yǐhòu, wǒ hěn kuài jiù zài bān lǐ jiāo dàole jǐ ge rèqíng de Zhōngguó péngyou.","vi":"Sau khi vào đại học Trung Quốc, tôi đã nhanh chóng kết giao được vài người bạn Trung Quốc nhiệt tình trong lớp."},{"type":"compound","zh":"每个月月底之前，租客必须按时把下个月的房租交给房东。","pinyin":"Měi geyuè yuèdǐ zhīqián, zūkè bìxū ànshí bǎ xiàgeyuè de fángzū jiāogěi fángdōng.","vi":"Trước cuối mỗi tháng, người thuê nhà bắt buộc phải nộp tiền thuê nhà tháng sau cho chủ nhà đúng hạn."}],"related":[{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"Giao thông"},{"hanzi":"作业","pinyin":"zuòyè","vi":"Bài tập"},{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"},{"hanzi":"房东","pinyin":"fángdōng","vi":"Chủ nhà"}]},{"id":"接受","hanzi":"接受","pinyin":"jiēshòu","meaning_vi":"tiếp nhận, chấp nhận","explanation":"接 (đón nhận) + 受 (nhận lấy). Đối nghĩa với 拒绝 (từ chối).","hsk_level":3,"tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"我接受你的建议。","pinyin":"Wǒ jiēshòu nǐ de jiànyì.","vi":"Tôi chấp nhận lời khuyên của bạn."},{"type":"simple","zh":"他非常谦虚，总是能够虚心接受别人提出的批评和意见。","pinyin":"Tā fēicháng qiānxū, zǒngshì nénggòu xūxīn jiēshòu biérén tíchū de pīpíng hé yìjiàn.","vi":"Anh ấy vô cùng khiêm tốn, luôn có thể cầu thị tiếp thu lời phê bình và ý kiến của người khác."},{"type":"compound","zh":"虽然刚到国外生活时有很多不习惯的地方，但是他很快就接受并适应了新环境。","pinyin":"Suīrán gāng dào guówài shēnghuó shí yǒu hěn duō bù xíguàn de dìfang, dànshì tā hěn kuài jiù jiēshòu bìng shìyìngle xīn huánjìng.","vi":"Tuy lúc mới sang nước ngoài sinh sống có nhiều điều chưa quen nhưng anh ấy đã nhanh chóng đón nhận và thích nghi với môi trường mới."}],"related":[{"hanzi":"拒绝","pinyin":"jùjué","vi":"Từ chối"},{"hanzi":"受到","pinyin":"shòudào","vi":"Nhận được"},{"hanzi":"接着","pinyin":"jiēzhe","vi":"Tiếp theo"},{"hanzi":"直接","pinyin":"zhíjiē","vi":"Trực tiếp"},{"hanzi":"建议","pinyin":"jiànyì","vi":"Đề nghị"}]},{"id":"拒绝","hanzi":"拒绝","pinyin":"jùjué","meaning_vi":"từ chối, khước từ","explanation":"拒 (chống lại) + 绝 (dứt khoát). Đối nghĩa với 接受 (chấp nhận).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🙅","examples":[{"type":"basic","zh":"他拒绝了我的邀请。","pinyin":"Tā jùjuéle wǒ de yāoqǐng.","vi":"Anh ấy đã từ chối lời mời của tôi."},{"type":"simple","zh":"因为周末已经安排好要陪父母去医院体检，所以我只好拒绝了同学的聚会邀请。","pinyin":"Yīnwèi zhōumò yǐjīng ānpái hǎo yào péi fùmǔ qù yīyuàn tǐjiǎn, suǒyǐ wǒ zhǐhǎo jùjuéle tóngxué de jùhuì yāoqǐng.","vi":"Vì cuối tuần đã sắp xếp đưa bố mẹ đi bệnh viện khám sức khỏe nên tôi đành từ chối lời mời tụ họp của bạn học."},{"type":"compound","zh":"学会礼貌地拒绝不合理的要求，也是职场中一项非常重要的沟通能力。","pinyin":"Xuéhuì lǐmào de jù juébù hélǐ de yāoqiú, yě shì zhíchǎng zhōng yí xiàng fēicháng zhòngyào de gōutōng nénglì.","vi":"Học cách từ chối một cách lịch sự những yêu cầu không hợp lý cũng là một kỹ năng giao tiếp vô cùng quan trọng nơi công sở."}],"related":[{"hanzi":"接受","pinyin":"jiēshòu","vi":"Tiếp nhận"},{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"Mời"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"},{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"Xin lỗi"},{"hanzi":"反对","pinyin":"fǎnduì","vi":"Phản đối"}],"traditional":"拒絕"},{"id":"节约","hanzi":"节约","pinyin":"jiéyuē","meaning_vi":"tiết kiệm","explanation":"节 (tiết chế) + 约 (ràng buộc). Đối nghĩa với 浪费 (lãng phí).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"💰","examples":[{"type":"basic","zh":"我们要节约用水。","pinyin":"Wǒmen yào jiéyuē yòng shuǐ.","vi":"Chúng ta phải tiết kiệm nước."},{"type":"simple","zh":"水资源非常宝贵，大家平时洗手以后一定要记得关紧水龙头，节约用水。","pinyin":"Shuǐzīyuán fēicháng bǎoguì, dàjiā píngshí xǐshǒu yǐhòu yídìngyào jìde guānjǐn shuǐlóngtóu, jiéyuē yòng shuǐ.","vi":"Tài nguyên nước vô cùng quý giá, mọi người bình thường rửa tay xong nhất định phải nhớ khóa chặt vòi nước để tiết kiệm nước."},{"type":"compound","zh":"节约是一种传统美德，无论是粮食、水电还是时间，我们都不应该随便浪费。","pinyin":"Jiéyuē shì yì zhǒng chuántǒng měidé, wúlùn shì liángshi, shuǐdiàn háishi shíjiān, wǒmen dōu bù yīnggāi suíbiàn làngfèi.","vi":"Tiết kiệm là một mỹ đức truyền thống, dù là lương thực, điện nước hay thời gian, chúng ta đều không nên lãng phí bừa bãi."}],"related":[{"hanzi":"浪费","pinyin":"làngfèi","vi":"Lãng phí"},{"hanzi":"省","pinyin":"shěng","vi":"Tiết kiệm"},{"hanzi":"大约","pinyin":"dàyuē","vi":"Khoảng chừng"},{"hanzi":"约会","pinyin":"yuēhuì","vi":"Hẹn hòu"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"}],"traditional":"節約"},{"id":"浪费","hanzi":"浪费","pinyin":"làngfèi","meaning_vi":"lãng phí","explanation":"浪 (bừa bãi) + 费 (tiêu tốn). Đối nghĩa với 节约 (tiết kiệm).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"💸","examples":[{"type":"basic","zh":"不要浪费粮食和时间。","pinyin":"Bú yào làngfèi liángshi hé shíjiān.","vi":"Đừng lãng phí lương thực và thời gian."},{"type":"simple","zh":"在饭店点菜的时候要根据人数适量点餐，吃不完打包带走，不要浪费。","pinyin":"Zài fàndiàn diǎncài de shíhou yào gēnjù rénshù shìliàng diǎncān, chī bù wán dǎbāo dàizǒu, bú yào làngfèi.","vi":"Khi gọi món ở nhà hàng cần gọi lượng vừa đủ theo số người, ăn không hết thì gói mang về, đừng lãng phí."},{"type":"compound","zh":"时间对每个人来说都是最宝贵的财富，把时间花在无聊的事情上就是最大的浪费。","pinyin":"Shíjiān duì měigerén lái shuō dōu shì zuì bǎoguì de cáifù, bǎ shíjiān huā zài wúliáo de shìqing shang jiùshì zuì dà de làngfèi.","vi":"Thời gian đối với mỗi người đều là tài sản quý giá nhất, dành thời gian vào những việc vô bổ chính là sự lãng phí lớn nhất."}],"related":[{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"},{"hanzi":"浪漫","pinyin":"làngmàn","vi":"Lãng mạn"},{"hanzi":"免费","pinyin":"miǎnfèi","vi":"Miễn phí"},{"hanzi":"花钱","pinyin":"huāqián","vi":"Tiêu tiền"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"}],"traditional":"浪費"},{"id":"解释","hanzi":"解释","pinyin":"jiěshì","meaning_vi":"giải thích","explanation":"解 (tháo gỡ) + 释 (làm sáng tỏ).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"请听我解释一下。","pinyin":"Qǐng tīng wǒ jiěshì yíxià.","vi":"Xin hãy nghe tôi giải thích một chút."},{"type":"simple","zh":"王老师用几个简单的例子，把这条复杂的语法规则解释得非常清楚。","pinyin":"Wáng lǎoshī yòng jǐ ge jiǎndān de lìzi, bǎ zhè tiáo fùzá de yǔfǎ guīzé jiěshì de fēicháng qīngchu.","vi":"Thầy Vương đã dùng vài ví dụ đơn giản để giải thích quy tắc ngữ pháp phức tạp này một cách vô cùng rõ ràng."},{"type":"compound","zh":"既然你们之间只是因为沟通不够才产生了误会，那就当面解释清楚吧。","pinyin":"Jìrán nǐmen zhījiān zhǐshì yīnwèi gōutōng búgòu cái chǎnshēngle wùhuì, nà jiù dāngmiàn jiěshì qīngchu ba.","vi":"Vì giữa hai người chỉ là do giao tiếp chưa đủ nên mới nảy sinh hiểu lầm, vậy thì hãy giải thích rõ ràng trực tiếp đi."}],"related":[{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"Thấu hiểu"},{"hanzi":"了解","pinyin":"liǎojiě","vi":"Tìm hiểu"},{"hanzi":"误会","pinyin":"wùhuì","vi":"Hiểu lầm"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"}],"traditional":"解釋"},{"id":"尽管","hanzi":"尽管","pinyin":"jǐnguǎn","meaning_vi":"mặc dù, cứ việc","explanation":"Liên từ nhượng bộ (mặc dù) hoặc phó từ (cứ tự nhiên làm).","hsk_level":3,"tags":["lien-tu","pho-tu"],"image":"↔️","examples":[{"type":"basic","zh":"尽管很累，他还在坚持。","pinyin":"Jǐnguǎn hěn lèi, tā hái zài jiānchí.","vi":"Mặc dù rất mệt, anh ấy vẫn đang kiên trì."},{"type":"simple","zh":"你有什么想法尽管说出来，大家一起商量讨论，不用客气。","pinyin":"Nǐ yǒu shénme xiǎngfǎ jǐnguǎn shuō chūlái, dàjiā yìqǐ shāngliang tǎolùn, bú yòng kèqi.","vi":"Bạn có suy nghĩ gì cứ việc nói ra, mọi người cùng nhau bàn bạc thảo luận, đừng khách sáo."},{"type":"compound","zh":"尽管今天外面刮着大风、下着大雨，但是他依然准时赶到了公司上班。","pinyin":"Jǐnguǎn jīntiān wàimiàn guāzhe dàfēng, xiàzhe dàyǔ, dànshì tā yīrán zhǔnshí gǎndàole gōngsī shàngbān.","vi":"Mặc dù hôm nay bên ngoài gió to mưa lớn nhưng anh ấy vẫn đến công ty làm việc đúng giờ."}],"related":[{"hanzi":"虽然","pinyin":"suīrán","vi":"Tuy rằng"},{"hanzi":"不管","pinyin":"bùguǎn","vi":"Bất kể"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"},{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"仍然","pinyin":"réngrán","vi":"Vẫn"}],"traditional":"儘管"},{"id":"进行","hanzi":"进行","pinyin":"jìnxíng","meaning_vi":"tiến hành","explanation":"进 (tiến lên) + 行 (thực hiện).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"▶️","examples":[{"type":"basic","zh":"会议正在顺利进行。","pinyin":"Huìyì zhèngzài shùnlì jìnxíng.","vi":"Cuộc họp đang diễn ra thuận lợi."},{"type":"simple","zh":"下个星期五上午九点，我们将在大礼堂进行汉语水平模拟考试。","pinyin":"Xiàge Xīngqīwǔ shàngwǔ jiǔ diǎn, wǒmen jiāng zài dà lǐtáng jìnxíng Hànyǔ shuǐpíng mónǐ kǎoshì.","vi":"9 giờ sáng thứ Sáu tuần sau, chúng tôi sẽ tiến hành thi thử năng lực Hán ngữ tại hội trường lớn."},{"type":"compound","zh":"为了确保产品符合国际标准，工程师们正在对新设备进行全面检查。","pinyin":"Wèile quèbǎo chǎnpǐn fúhé Guójì biāozhǔn, gōngchéngshīmen zhèngzài duì xīn shèbèi jìnxíng quánmiàn jiǎnchá.","vi":"Để đảm bảo sản phẩm đạt tiêu chuẩn quốc tế, các kỹ sư đang tiến hành kiểm tra toàn diện thiết bị mới."}],"related":[{"hanzi":"举行","pinyin":"jǔxíng","vi":"Tổ chức"},{"hanzi":"流行","pinyin":"liúxíng","vi":"Thịnh hành"},{"hanzi":"进","pinyin":"jìn","vi":"Vào/Tiến"},{"hanzi":"行","pinyin":"xíng","vi":"Đi/Được"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"}],"traditional":"進行"},{"id":"禁止","hanzi":"禁止","pinyin":"jìnzhǐ","meaning_vi":"cấm, nghiêm cấm","explanation":"禁 (ngăn cấm) + 止 (dừng lại).","hsk_level":3,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"图书馆里禁止大声说话。","pinyin":"Túshūguǎn lǐ jìnzhǐ dàshēng shuōhuà.","vi":"Trong thư viện cấm nói chuyện lớn tiếng."},{"type":"simple","zh":"加油站里禁止抽烟。","pinyin":"Jiāyóuzhàn lǐ jìnzhǐ chōuyān.","vi":"Trong trạm xăng cấm hút thuốc."},{"type":"compound","zh":"虽然这条马路很宽，但是因为正在修路，所以目前禁止一切汽车通行。","pinyin":"Suīrán zhè tiáo mǎlù hěn kuān, dànshì yīnwèi zhèngzài xiūlù, suǒyǐ mùqián jìnzhǐ yíqiè qìchē tōngxíng.","vi":"Tuy con đường này rất rộng nhưng vì đang sửa đường nên hiện tại cấm mọi xe ô tô lưu thông."}],"related":[{"hanzi":"抽烟","pinyin":"chōuyān","vi":"Hút thuốc"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"规定","pinyin":"guīdìng","vi":"Quy định"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"Cho phép"},{"hanzi":"停","pinyin":"tíng","vi":"Dừng"}]},{"id":"经验","hanzi":"经验","pinyin":"jīngyàn","meaning_vi":"kinh nghiệm","explanation":"经 (trải qua) + 验 (kiểm chứng). Danh từ.","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"🧠","examples":[{"type":"basic","zh":"他有丰富的教学经验。","pinyin":"Tā yǒu fēngfù de jiāoxué jīngyàn.","vi":"Thầy ấy có kinh nghiệm giảng dạy phong phú."},{"type":"simple","zh":"王医生在医院工作了二十多年，在治疗感冒发烧方面非常有经验。","pinyin":"Wáng yīshēng zài yīyuàn gōngzuòle èrshí duōnián, zài zhìliáo gǎnmào fāshāo fāngmiàn fēicháng yǒu jīngyàn.","vi":"Bác sĩ Vương đã làm việc ở bệnh viện hơn 20 năm, vô cùng giàu kinh nghiệm trong việc điều trị cảm sốt."},{"type":"compound","zh":"虽然刚毕业的大学生缺乏工作经验，但是他们学习能力强、充满热情。","pinyin":"Suīrán gāng bìyè de dàxuésheng quēfá gōngzuò jīngyàn, dànshì tāmen xuéxí nénglì qiáng, chōngmǎn rèqíng.","vi":"Tuy sinh viên mới tốt nghiệp thiếu kinh nghiệm làm việc nhưng họ có khả năng học hỏi nhanh và tràn đầy nhiệt huyết."}],"related":[{"hanzi":"经历","pinyin":"jīnglì","vi":"Trải qua"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"积累","pinyin":"jīlěi","vi":"Tích lũy"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"Phong phú"},{"hanzi":"能力","pinyin":"nénglì","vi":"Năng lực"}],"traditional":"經驗"},{"id":"精彩","hanzi":"精彩","pinyin":"jīngcǎi","meaning_vi":"đặc sắc, xuất sắc","explanation":"精 (tinh túy) + 彩 (rực rỡ). Dùng khen trận đấu, tiết mục biểu diễn.","hsk_level":3,"tags":["tinh-tu","giai-tri"],"image":"🌟","examples":[{"type":"basic","zh":"昨晚的足球比赛太精彩了！","pinyin":"Zuówǎn de zúqiú bǐsài tài jīngcǎi le!","vi":"Trận bóng đá tối qua đặc sắc quá đi!"},{"type":"simple","zh":"演员们在舞台上的表演非常精彩，赢得了全场观众的热烈掌声。","pinyin":"Yǎnyuánmen zài wǔtái shang de biǎoyǎn fēicháng jīngcǎi, yíng déle quánchǎng guānzhòng de rèliè zhǎngshēng.","vi":"Màn biểu diễn của các diễn viên trên sân khấu vô cùng xuất sắc, giành được tràng pháo tay nồng nhiệt của toàn thể khán giả."},{"type":"compound","zh":"虽然这本书我已经读过好几遍了，但是每次读到精彩的部分还是觉得很感动。","pinyin":"Suīrán zhè běn shū wǒ yǐjīng dúguo hǎojǐ biàn le, dànshì měi cì dú dào jīngcǎi de bùfen háishi juéde hěn gǎndòng.","vi":"Tuy quyển sách này tôi đã đọc qua mấy lượt rồi nhưng mỗi lần đọc đến đoạn đặc sắc vẫn cảm thấy rất xúc động."}],"related":[{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"Biểu diễn"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"Buổi diễn"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"Khán giả"},{"hanzi":"精神","pinyin":"jīngshén","vi":"Tinh thần"}]},{"id":"举办","hanzi":"举办","pinyin":"jǔbàn","meaning_vi":"tổ chức, cử hành","explanation":"举 (nâng lên/nêu ra) + 办 (làm).","hsk_level":3,"tags":["dong-tu"],"image":"🎪","examples":[{"type":"basic","zh":"北京举办过奥运会。","pinyin":"Běijīng jǔbànguo Àoyùnhuì.","vi":"Bắc Kinh đã từng tổ chức Thế vận hội Olympic."},{"type":"simple","zh":"我们学校每年秋天都会举办一次国际文化节，各国留学生都会参加。","pinyin":"Wǒmen xuéxiào měinián qiūtiān dōuhuì jǔbàn yí cì Guójì wénhuà jié, gèguó liúxuésheng dōuhuì cānjiā.","vi":"Trường chúng tôi mùa thu hằng năm đều tổ chức một lần Lễ hội Văn hóa Quốc tế, du học sinh các nước đều tham gia."},{"type":"compound","zh":"为了庆祝公司成立十周年，经理决定下个月在五星级宾馆举办一场大型晚会。","pinyin":"Wèile qìngzhù gōngsī chénglì shí zhōunián, jīnglǐ juédìng xiàgeyuè zài wǔxīngjí bīnguǎn jǔbàn yì chǎng dàxíng wǎnhuì.","vi":"Để kỷ niệm 10 năm thành lập công ty, giám đốc quyết định tháng sau tổ chức một buổi dạ tiệc lớn tại khách sạn 5 sao."}],"related":[{"hanzi":"举行","pinyin":"jǔxíng","vi":"Tiến hành"},{"hanzi":"举","pinyin":"jǔ","vi":"Giơ/Nêu"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"Biện pháp"},{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"Văn phòng"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"}],"traditional":"舉辦"},{"id":"举行","hanzi":"举行","pinyin":"jǔxíng","meaning_vi":"tiến hành, tổ chức (hội nghị/thi đấu)","explanation":"举 + 行 (thực hiện).","hsk_level":3,"tags":["dong-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"会议在三楼举行。","pinyin":"Huìyì zài sān lóu jǔxíng.","vi":"Cuộc họp được tổ chức ở tầng 3."},{"type":"simple","zh":"一年一度的汉语桥比赛将于明天上午在大学体育馆正式举行。","pinyin":"Yì nián yídù de hànyǔqiáo bǐsài jiāng yú míngtiān shàngwǔ zài dàxué tǐyùguǎn zhèngshì jǔxíng.","vi":"Cuộc thi Nhịp cầu Hán ngữ thường niên sẽ chính thức diễn ra vào sáng mai tại nhà thi đấu đại học."},{"type":"compound","zh":"虽然今天外面下着小雨，但是学校的秋季运动会依然按原计划如期举行。","pinyin":"Suīrán jīntiān wàimiàn xiàzhe xiǎoyǔ, dànshì xuéxiào de qiūjì yùndònghuì yīrán àn yuán jìhuà rúqī jǔxíng.","vi":"Tuy hôm nay bên ngoài có mưa nhỏ nhưng hội thao mùa thu của trường vẫn diễn ra đúng lịch trình như kế hoạch ban đầu."}],"related":[{"hanzi":"举办","pinyin":"jǔbàn","vi":"Tổ chức"},{"hanzi":"进行","pinyin":"jìnxíng","vi":"Tiến hành"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"正式","pinyin":"zhèngshì","vi":"Chính thức"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"}],"traditional":"舉行"},{"id":"开玩笑","hanzi":"开玩笑","pinyin":"kāiwánxiào","meaning_vi":"nói đùa, đùa giỡn","explanation":"开 + 玩笑 (trò đùa). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"😜","examples":[{"type":"basic","zh":"别生气，我只是开玩笑。","pinyin":"Bié shēngqì, wǒ zhǐshì kāiwánxiào.","vi":"Đừng giận, tôi chỉ nói đùa thôi mà."},{"type":"simple","zh":"小王性格非常幽默，平时在办公室里经常喜欢跟同事们开玩笑。","pinyin":"Xiǎo Wáng xìnggé fēicháng yōumò, píngshí zài bàngōngshì lǐ jīngcháng xǐhuan gēn tóngshìmen kāiwánxiào.","vi":"Tiểu Vương tính cách vô cùng hài hước, bình thường ở văn phòng rất hay thích nói đùa với đồng nghiệp."},{"type":"compound","zh":"虽然朋友之间偶尔开玩笑可以增加快乐，但是也要注意分寸，不要伤害别人。","pinyin":"Suīrán péngyou zhījiān ǒu'ěr kāiwánxiào kěyǐ zēngjiā kuàilè, dànshì yě yào zhùyì fēncun, bú yào shānghài biérén.","vi":"Tuy giữa bạn bè thỉnh thoảng trêu đùa có thể tăng thêm niềm vui nhưng cũng cần chú ý chừng mực, đừng làm tổn thương người khác."}],"related":[{"hanzi":"笑话","pinyin":"xiàohua","vi":"Truyện cười"},{"hanzi":"笑","pinyin":"xiào","vi":"Cười"},{"hanzi":"玩","pinyin":"wán","vi":"Chơi"},{"hanzi":"幽默","pinyin":"yōumò","vi":"Hài hước"},{"hanzi":"生气","pinyin":"shēngqì","vi":"Tức giận"}],"traditional":"開玩笑"},{"id":"看法","hanzi":"看法","pinyin":"kànfǎ","meaning_vi":"cách nhìn, quan điểm","explanation":"看 (nhìn nhận) + 法 (phương pháp).","hsk_level":3,"tags":["danh-tu","nhan-thuc"],"image":"👁️","examples":[{"type":"basic","zh":"每个人都有不同的看法。","pinyin":"Měigerén dōu yǒu bùtóng de kànfǎ.","vi":"Mỗi người đều có cách nhìn nhận khác nhau."},{"type":"simple","zh":"关于如何在网上高效学习汉语这个问题，同学们在讨论会上发表了各自的看法。","pinyin":"Guānyú rúhé zài wǎngshang gāoxiào xuéxí Hànyǔ zhè ge wèntí, tóngxuémen zài tǎolùnhuì shang fābiǎole gèzì de kànfǎ.","vi":"Về vấn đề làm thế nào để học tiếng Trung hiệu quả trên mạng, các bạn học đã phát biểu quan điểm riêng tại buổi thảo luận."},{"type":"compound","zh":"虽然我们两人在某些事情上的看法不完全相同，但是这并不影响我们的友谊。","pinyin":"Suīrán wǒmen liǎng rén zài mǒuxiē shìqing shang de kànfǎ bù wánquán xiāngtóng, dànshì zhè bìngbù yǐngxiǎng wǒmen de yǒuyì.","vi":"Tuy quan điểm của hai chúng tôi về một số việc không hoàn toàn giống nhau nhưng điều đó không hề ảnh hưởng đến tình bạn của chúng tôi."}],"related":[{"hanzi":"办法","pinyin":"bànfǎ","vi":"Biện pháp"},{"hanzi":"语法","pinyin":"yǔfǎ","vi":"Ngữ pháp"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"认为","pinyin":"rènwéi","vi":"Cho rằng"},{"hanzi":"看","pinyin":"kàn","vi":"Nhìn"}]},{"id":"考虑","hanzi":"考虑","pinyin":"kǎolǜ","meaning_vi":"suy nghĩ, cân nhắc","explanation":"考 (xem xét) + 虑 (lo toan).","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"这个问题我需要考虑一下。","pinyin":"Zhè ge wèntí wǒ xūyào kǎolǜ yíxià.","vi":"Vấn đề này tôi cần suy nghĩ một chút."},{"type":"simple","zh":"买房子是一件大事，我们必须把交通、环境和价格等因素都考虑进去。","pinyin":"Mǎi fángzi shì yí jiàn dàshì, wǒmen bìxū bǎ jiāotōng, huánjìng hé jiàgé děng yīnsù dōu kǎolǜ jìnqù.","vi":"Mua nhà là một việc lớn, chúng ta bắt buộc phải cân nhắc cả các yếu tố như giao thông, môi trường và giá cả."},{"type":"compound","zh":"虽然那家公司开出的工资很高，但是考虑到离家太远，他最后还是拒绝了。","pinyin":"Suīrán nà jiā gōngsī kāi chū de gōngzī hěn gāo, dànshì kǎolǜ dào lí jiā tài yuǎn, tā zuìhòu háishi jùjué le.","vi":"Tuy mức lương công ty đó đưa ra rất cao nhưng xét thấy cách nhà quá xa nên cuối cùng anh ấy vẫn từ chối."}],"related":[{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"思考","pinyin":"sīkǎo","vi":"Suy nghĩ"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"},{"hanzi":"想","pinyin":"xiǎng","vi":"Nghĩ"}],"traditional":"考慮"},{"id":"科学","hanzi":"科学","pinyin":"kēxué","meaning_vi":"khoa học","explanation":"科 (môn/ngành) + 学 (học thuật). Vừa là danh từ vừa là tính từ.","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"科学改变了我们的生活。","pinyin":"Kēxué gǎibiànle wǒmen de shēnghuó.","vi":"Khoa học đã thay đổi cuộc sống của chúng ta."},{"type":"simple","zh":"只有采用科学的学习方法，才能在最短的时间内取得最好的学习效果。","pinyin":"Zhǐyǒu cǎiyòng kēxué de xuéxí fāngfǎ, cáinéng zài zuì duǎn de shíjiān nèi qǔdé zuìhǎo de xuéxí xiàoguǒ.","vi":"Chỉ có áp dụng phương pháp học tập khoa học mới có thể đạt được hiệu quả học tập tốt nhất trong thời gian ngắn nhất."},{"type":"compound","zh":"随着现代科学技术的发展，人类已经能够把卫星和宇航员送到太空去了。","pinyin":"Suízhe xiàndài kēxué jìshù de fāzhǎn, rénlèi yǐjīng nénggòu bǎ wèixīng hé yǔhángyuán sòng dào tàikōng qù le.","vi":"Cùng với sự phát triển của khoa học kỹ thuật hiện đại, loài người đã có thể đưa vệ tinh và phi hành gia lên vũ trụ."}],"related":[{"hanzi":"技术","pinyin":"jìshù","vi":"Kỹ thuật"},{"hanzi":"研究","pinyin":"yánjiū","vi":"Nghiên cứu"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"},{"hanzi":"科目","pinyin":"kēmù","vi":"Môn học"}],"traditional":"科學"},{"id":"咳嗽","hanzi":"咳嗽","pinyin":"késou","meaning_vi":"ho","explanation":"Cả hai chữ đều có bộ khẩu 口 (miệng).","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"😷","examples":[{"type":"basic","zh":"他感冒了，一直咳嗽。","pinyin":"Tā gǎnmào le, yìzhí késou.","vi":"Anh ấy bị cảm cúm rồi, cứ ho suốt."},{"type":"simple","zh":"因为空气太干燥，加上昨天着了凉，所以我今天嗓子疼得一直咳嗽。","pinyin":"Yīnwèi kōngqì tài gānzào, jiāshang zuótiānzháo le liáng, suǒyǐ wǒ jīntiān sǎngziténg de yìzhí késou.","vi":"Vì không khí quá hanh khô, cộng thêm hôm qua bị nhiễm lạnh nên hôm nay cổ họng tôi đau đến mức ho liên tục."},{"type":"compound","zh":"医生说他咳嗽得比较严重，建议他这段时间不要抽烟，也不要吃辛辣的食物。","pinyin":"Yīshēng shuō tā késou de bǐjiào yánzhòng, jiànyì tā zhè duàn shíjiān bú yào chōuyān, yě bú yào chī xīnlà de shíwù.","vi":"Bác sĩ nói anh ấy ho tương đối nặng, khuyên thời gian này đừng hút thuốc và cũng đừng ăn đồ cay nóng."}],"related":[{"hanzi":"感冒","pinyin":"gǎnmào","vi":"Cảm cúm"},{"hanzi":"发烧","pinyin":"fāshāo","vi":"Phát sốt"},{"hanzi":"抽烟","pinyin":"chōuyān","vi":"Hút thuốc"},{"hanzi":"吃药","pinyin":"chīyào","vi":"Uống thuốc"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"}]},{"id":"可怜","hanzi":"可怜","pinyin":"kělián","meaning_vi":"đáng thương, tội nghiệp","explanation":"可 (đáng) + 怜 (thương xót).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"这只小狗真可怜。","pinyin":"Zhè zhī xiǎogǒu zhēn kělián.","vi":"Chú chó nhỏ này thật đáng thương."},{"type":"simple","zh":"外面下着大雨，那只迷路的小猫浑身湿透地躲在屋檐下，看起来特别可怜。","pinyin":"Wàimiàn xiàzhe dàyǔ, nà zhī mílù de xiǎomāo húnshēn shītòu de duǒ zài wūyán xià, kànqǐlái tèbié kělián.","vi":"Bên ngoài mưa lớn, chú mèo con bị lạc đường ướt sũng cả người nấp dưới mái hiên, trông đặc biệt đáng thương."},{"type":"compound","zh":"虽然这个小女孩从小失去了父母，很可怜，但是她依然非常坚强和乐观。","pinyin":"Suīrán zhè ge xiǎo nǚhái cóngxiǎo shīqùle fùmǔ, hěn kělián, dànshì tā yīrán fēicháng jiānqiáng hé lèguān.","vi":"Tuy cô bé này mất bố mẹ từ nhỏ, rất đáng thương nhưng em vẫn vô cùng kiên cường và lạc quan."}],"related":[{"hanzi":"可惜","pinyin":"kěxī","vi":"Đáng tiếc"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"Đáng yêu"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"Đồng cảm"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"难过","pinyin":"nánguò","vi":"Buồn bã"}],"traditional":"可憐"},{"id":"肯定","hanzi":"肯定","pinyin":"kěndìng","meaning_vi":"khẳng định, chắc chắn","explanation":"肯 (đồng ý) + 定 (chắc chắn).","hsk_level":3,"tags":["pho-tu","dong-tu"],"image":"💯","examples":[{"type":"basic","zh":"他肯定会来的。","pinyin":"Tā kěndìng huì lái de.","vi":"Anh ấy chắc chắn sẽ đến."},{"type":"simple","zh":"既然他已经答应了要帮忙，明天上午九点就肯定会准时到达。","pinyin":"Jìrán tā yǐjīng dāyingle yào bāngmáng, míngtiān shàngwǔ jiǔ diǎn jiù kěndìng huì zhǔnshí dàodá.","vi":"Vì anh ấy đã nhận lời giúp đỡ rồi thì 9 giờ sáng mai chắc chắn sẽ có mặt đúng giờ."},{"type":"compound","zh":"只要你把基础语法和生词掌握扎实了，这次考试肯定能取得优秀的成绩。","pinyin":"Zhǐyào nǐ bǎ jīchǔ yǔfǎ hé shēngcí zhǎngwò zhāshi le, zhè cì kǎoshì kěndìng néng qǔdé yōuxiù de chéngjì.","vi":"Chỉ cần bạn nắm vững ngữ pháp cơ bản và từ mới thì kỳ thi lần này chắc chắn sẽ đạt thành tích xuất sắc."}],"related":[{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có thể"},{"hanzi":"确实","pinyin":"quèshí","vi":"Quả thực"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"}]},{"id":"恐怕","hanzi":"恐怕","pinyin":"kǒngpà","meaning_vi":"e rằng, sợ rằng","explanation":"恐 (sợ) + 怕 (e ngại). Dùng để dự đoán điều không mong muốn.","hsk_level":3,"tags":["pho-tu"],"image":"😟","examples":[{"type":"basic","zh":"今天下午恐怕要下雨。","pinyin":"Jīntiān xiàwǔ kǒngpà yào xiàyǔ.","vi":"Chiều nay e rằng trời sắp mưa."},{"type":"simple","zh":"现在已经八点半了，路上又堵车，我们九点以前恐怕赶不到机场了。","pinyin":"Xiànzài yǐjīng bā diǎn bàn le, lùshang yòu dǔchē, wǒmen jiǔ diǎn yǐqián kǒngpà gǎn búdào jīchǎng le.","vi":"Bây giờ đã 8 giờ rưỡi rồi, trên đường lại tắc xe, e rằng trước 9 giờ chúng ta không kịp ra tới sân bay mất."},{"type":"compound","zh":"虽然我很想参加你们周末的聚会，但是因为要加班，恐怕去不了了。","pinyin":"Suīrán wǒ hěn xiǎng cānjiā nǐmen zhōumò de jùhuì, dànshì yīnwèi yào jiābān, kǒngpà qù bù liǎole.","vi":"Tuy tôi rất muốn tham gia buổi tụ họp cuối tuần của các bạn nhưng vì phải tăng ca nên e rằng không đi được rồi."}],"related":[{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có lẽ"},{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"担心","pinyin":"dānxīn","vi":"Lo lắng"},{"hanzi":"来不及","pinyin":"láibují","vi":"Không kịp"}]},{"id":"拉","hanzi":"拉","pinyin":"lā","meaning_vi":"kéo, lôi","explanation":"Bộ tài gảy 扌+ 立. Đối nghĩa với 推 (đẩy).","hsk_level":3,"tags":["dong-tu"],"image":"🪢","examples":[{"type":"basic","zh":"妈妈拉着孩子的手。","pinyin":"Māma lāzhe háizi de shǒu.","vi":"Mẹ đang nắm lấy tay của con."},{"type":"simple","zh":"过马路的时候，爸爸总是紧紧地拉着弟弟的手，注意来往的车辆。","pinyin":"Guòmǎlù de shíhou, bàba zǒngshì jǐnjǐn de lāzhe dìdi de shǒu, zhùyì láiwǎng de chēliàng.","vi":"Khi qua đường, bố luôn nắm chặt tay em trai và chú ý xe cộ qua lại."},{"type":"compound","zh":"门上写着“推”而不是“拉”，所以你要用力往外推才能把门打开。","pinyin":"Mén shang xiě zhe \"tuī\" ér bú shì \"lā\", suǒyǐ nǐ yào yònglì wǎng wàituī cáinéng bǎ mén dǎkāi.","vi":"Trên cửa viết chữ “Đẩy” chứ không phải “Kéo”, vì vậy bạn phải dùng sức đẩy ra ngoài mới mở được cửa."}],"related":[{"hanzi":"推","pinyin":"tuī","vi":"Đẩy"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm"},{"hanzi":"手","pinyin":"shǒu","vi":"Tay"},{"hanzi":"门","pinyin":"mén","vi":"Cửa"},{"hanzi":"垃圾桶","pinyin":"lājītǒng","vi":"Thùng rác"}]},{"id":"推","hanzi":"推","pinyin":"tuī","meaning_vi":"đẩy; tiến cử, đề cử","explanation":"Bộ tài gảy 扌+ 隹. Đối nghĩa với 拉 (kéo).","hsk_level":3,"tags":["dong-tu"],"image":"👐","examples":[{"type":"basic","zh":"请往外推门。","pinyin":"Qǐng wǎng wàituī mén.","vi":"Xin hãy đẩy cửa ra ngoài."},{"type":"simple","zh":"他的自行车在半路上坏了，只好一路推着自行车走回家。","pinyin":"Tā de zìxíngchē zài bànlù shang huàile, zhǐhǎo yílù tuīzhe zìxíngchē zǒu huíjiā.","vi":"Xe đạp của anh ấy bị hỏng giữa đường, đành phải dắt bộ xe đạp suốt quãng đường về nhà."},{"type":"compound","zh":"因为车坏了，所以我们几个人一起下车推车。","pinyin":"Yīnwèi chē huàile, suǒyǐ wǒmen jǐ ge rén yìqǐ xiàchē tuīchē.","vi":"Vì xe bị hỏng nên mấy người chúng tôi cùng xuống xe đẩy xe."}],"related":[{"hanzi":"拉","pinyin":"lā","vi":"Kéo"},{"hanzi":"推迟","pinyin":"tuīchí","vi":"Hoãn lại"},{"hanzi":"门","pinyin":"mén","vi":"Cửa"},{"hanzi":"开","pinyin":"kāi","vi":"Mở"},{"hanzi":"自行车","pinyin":"zìxíngchē","vi":"Xe đạp"}]},{"id":"来不及","hanzi":"来不及","pinyin":"láibují","meaning_vi":"không kịp","explanation":"来 + 不 + 及 (đạt tới). Đối nghĩa với 来得及 (kịp).","hsk_level":3,"tags":["dong-tu"],"image":"⏰","examples":[{"type":"basic","zh":"快走吧，不然来不及了！","pinyin":"Kuài zǒu ba, bùrán láibují le!","vi":"Mau đi thôi, nếu không sẽ không kịp mất!"},{"type":"simple","zh":"今天早上起床太晚，连早饭都来不及吃我就跑去赶地铁了。","pinyin":"Jīntiān zǎoshang qǐchuáng tài wǎn, lián zǎofàn dōu láibují chī wǒ jiù pǎo qù gǎn dìtiě le.","vi":"Sáng nay thức dậy muộn quá, đến cả bữa sáng cũng không kịp ăn tôi đã chạy đi bắt tàu điện ngầm rồi."},{"type":"compound","zh":"电影还有五分钟就要开场了，现在才买票进去恐怕已经来不及了。","pinyin":"Diànyǐng háiyǒu wǔ fēnzhōng jiùyào kāichǎng le, xiànzài cái mǎipiào jìnqù kǒngpà yǐjīng láibují le.","vi":"Phim còn 5 phút nữa là chiếu rồi, bây giờ mới mua vé vào e rằng đã không kịp nữa rồi."}],"related":[{"hanzi":"来得及","pinyin":"láidejí","vi":"Kịp"},{"hanzi":"赶","pinyin":"gǎn","vi":"Kịp/Vội"},{"hanzi":"迟到","pinyin":"chídào","vi":"Đến muộn"},{"hanzi":"及时","pinyin":"jíshí","vi":"Kịp thời"},{"hanzi":"着急","pinyin":"zháojí","vi":"Sốt ruột"}],"traditional":"來不及"},{"id":"来得及","hanzi":"来得及","pinyin":"láidejí","meaning_vi":"kịp, còn kịp","explanation":"来 + 得 + 及. Đối nghĩa với 来不及 (không kịp).","hsk_level":3,"tags":["dong-tu"],"image":"⏱️","examples":[{"type":"basic","zh":"别着急，时间还来得及。","pinyin":"Biézháojí, shíjiān hái láidejí.","vi":"Đừng vội, thời gian vẫn còn kịp."},{"type":"simple","zh":"火车十点半才开，现在才九点，我们去吃碗面条完全来得及。","pinyin":"Huǒchē shí diǎn bàn cái kāi, xiànzài cái jiǔ diǎn, wǒmen qù chī wǎn miàntiáo wánquán láidejí.","vi":"10 giờ rưỡi tàu hỏa mới chạy, bây giờ mới 9 giờ, chúng ta đi ăn bát mì hoàn toàn còn kịp."},{"type":"compound","zh":"虽然距离考试只剩下最后一个月了，但是只要从现在开始认真复习就还来得及。","pinyin":"Suīrán jùlí kǎoshì zhǐ shèngxià zuìhòu yí geyuè le, dànshì zhǐyào cóng xiànzài kāishǐ rènzhēn fùxí jiù hái láidejí.","vi":"Tuy chỉ còn lại một tháng cuối cùng nữa là tới kỳ thi nhưng chỉ cần bắt đầu ôn tập nghiêm túc từ bây giờ thì vẫn kịp."}],"related":[{"hanzi":"来不及","pinyin":"láibují","vi":"Không kịp"},{"hanzi":"及时","pinyin":"jíshí","vi":"Kịp thời"},{"hanzi":"赶","pinyin":"gǎn","vi":"Kịp"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"提前","pinyin":"tíqián","vi":"Trước thời hạn"}],"traditional":"來得及"},{"id":"来自","hanzi":"来自","pinyin":"láizì","meaning_vi":"đến từ","explanation":"来 (đến) + 自 (từ).","hsk_level":3,"tags":["dong-tu"],"image":"🌍","examples":[{"type":"basic","zh":"他来自越南河内。","pinyin":"Tā láizì Yuènán Hénèi.","vi":"Anh ấy đến từ Hà Nội, Việt Nam."},{"type":"simple","zh":"我们大学每年都会招收来自世界五十多个国家的外国留学生。","pinyin":"Wǒmen dàxué měinián dōuhuì zhāoshōu láizì shìjiè wǔshí duōge guójiā de wàiguó liúxuésheng.","vi":"Trường đại học của chúng tôi hằng năm đều tuyển sinh du học sinh nước ngoài đến từ hơn 50 quốc gia trên thế giới."},{"type":"compound","zh":"虽然班里的同学们来自不同的国家，但是大家在一起学习生活得非常愉快。","pinyin":"Suīrán bān lǐ de tóngxuémen láizì bùtóng de guójiā, dànshì dàjiā zài yìqǐ xuéxí shēnghuó de fēicháng yúkuài.","vi":"Tuy các bạn học trong lớp đến từ nhiều quốc gia khác nhau nhưng mọi người cùng nhau học tập và sinh hoạt vô cùng vui vẻ."}],"related":[{"hanzi":"来","pinyin":"lái","vi":"Đến"},{"hanzi":"自己","pinyin":"zìjǐ","vi":"Tự mình"},{"hanzi":"从","pinyin":"cóng","vi":"Từ"},{"hanzi":"国家","pinyin":"guójiā","vi":"Quốc gia"},{"hanzi":"留学生","pinyin":"liúxuésheng","vi":"Du học sinh"}],"traditional":"來自"},{"id":"懒","hanzi":"懒","pinyin":"lǎn","meaning_vi":"lười, lười biếng","explanation":"Bộ tâm đứng 忄+ 赖. Đối nghĩa với 勤快 (chăm chỉ).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🦥","examples":[{"type":"basic","zh":"这只小猫真懒。","pinyin":"Zhè zhī xiǎomāo zhēn lǎn.","vi":"Chú mèo nhỏ này lười thật đấy."},{"type":"simple","zh":"冬天天气太冷，他周末总是懒得起床，喜欢躺在被窝里看小说。","pinyin":"Dōngtiān tiānqì tài lěng, tā zhōumò zǒngshì lǎnde qǐchuáng, xǐhuan tǎng zài bèi wō lǐ kàn xiǎoshuō.","vi":"Mùa đông thời tiết lạnh quá, cuối tuần cậu ấy luôn lười dậy, thích nằm trong chăn đọc tiểu thuyết."},{"type":"compound","zh":"学习外语最怕懒惰，如果每天懒得背生词和练习听力，水平就很难提高。","pinyin":"Xuéxí wàiyǔ zuì pà lǎnduò, rúguǒ měitiān lǎnde bèi shēngcí hé liànxí tīnglì, shuǐpíng jiù hěn nán tígāo.","vi":"Học ngoại ngữ sợ nhất là lười biếng, nếu mỗi ngày lười học thuộc từ mới và luyện nghe thì trình độ rất khó nâng cao."}],"related":[{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Chăm chỉ"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Ngủ"},{"hanzi":"躺","pinyin":"tǎng","vi":"Nằm"},{"hanzi":"猫","pinyin":"māo","vi":"Con mèo"}],"traditional":"懶"},{"id":"理发","hanzi":"理发","pinyin":"lǐfà","meaning_vi":"cắt tóc","explanation":"理 (sửa sang) + 发 (tóc). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","sinh-hoat"],"image":"💇","examples":[{"type":"basic","zh":"我今天下午去理发。","pinyin":"Wǒ jīntiān xiàwǔ qù lǐfà.","vi":"Chiều nay tôi đi cắt tóc."},{"type":"simple","zh":"哥哥的头发太长了，妈妈让他周末去学校旁边的理发店理发。","pinyin":"Gēge de tóufa tài cháng le, māma ràng tā zhōumò qù xuéxiào pángbiān de lǐfàdiàn lǐfà.","vi":"Tóc của anh trai dài quá rồi, mẹ bảo anh cuối tuần ra tiệm cắt tóc bên cạnh trường cắt tóc."},{"type":"compound","zh":"因为春节前夕去理发店理发的人特别多，所以我们最好提前预约。","pinyin":"Yīnwèi Chūnjié qiánxī qù lǐfàdiàn lǐfà de rén tèbié duō, suǒyǐ wǒmen zuìhǎo tíqián yùyuē.","vi":"Vì dịp giáp Tết người đi tiệm cắt tóc đặc biệt đông nên tốt nhất chúng ta đặt lịch trước."}],"related":[{"hanzi":"头发","pinyin":"tóufa","vi":"Tóc"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Chỉnh lý"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"},{"hanzi":"长","pinyin":"cháng","vi":"Dài"},{"hanzi":"短","pinyin":"duǎn","vi":"Ngắn"}],"traditional":"理髮"},{"id":"理解","hanzi":"理解","pinyin":"lǐjiě","meaning_vi":"hiểu, thấu hiểu, lý giải","explanation":"理 (lý lẽ) + 解 (hiểu rõ).","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"我很理解你的心情。","pinyin":"Wǒ hěn lǐjiě nǐ de xīnqíng.","vi":"Tôi rất thấu hiểu tâm trạng của bạn."},{"type":"simple","zh":"通过阅读这篇文章，我深刻地理解了作者想要表达的思想感情。","pinyin":"Tōngguò yuèdú zhè piān wénzhāng, wǒ shēnkè de lǐjiěle zuòzhě xiǎngyào biǎodá de sīxiǎng gǎnqíng.","vi":"Thông qua việc đọc bài văn này, tôi đã thấu hiểu sâu sắc tư tưởng tình cảm mà tác giả muốn truyền đạt."},{"type":"compound","zh":"家人和朋友之间只有多沟通、换位思考，才能真正互相理解、减少误会。","pinyin":"Jiārén hé péngyou zhījiān zhǐyǒu duō gōutōng, huànwèisīkǎo, cáinéng zhēnzhèng hùxiāng lǐjiě, jiǎnshǎo wùhuì.","vi":"Giữa người thân và bạn bè chỉ có giao tiếp nhiều, đặt mình vào vị trí người khác mới có thể thực sự thấu hiểu và giảm hiểu lầm."}],"related":[{"hanzi":"了解","pinyin":"liǎojiě","vi":"Hiểu rõ"},{"hanzi":"解释","pinyin":"jiěshì","vi":"Giải thích"},{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"},{"hanzi":"明白","pinyin":"míngbai","vi":"Hiểu rõ"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"Đồng cảm"}]},{"id":"理想","hanzi":"理想","pinyin":"lǐxiǎng","meaning_vi":"lý tưởng","explanation":"理 (lý trí) + 想 (ước muốn). Vừa là danh từ vừa là tính từ.","hsk_level":3,"tags":["danh-tu","tinh-tu"],"image":"🌠","examples":[{"type":"basic","zh":"每个人都有自己的理想。","pinyin":"Měigerén dōu yǒu zìjǐ de lǐxiǎng.","vi":"Mỗi người đều có lý tưởng của riêng mình."},{"type":"simple","zh":"这套房子不仅交通方便、环境安静，而且价格也很理想。","pinyin":"Zhè tào fángzi bùjǐn jiāotōng fāngbiàn, huánjìng ānjìng, érqiě jiàgé yě hěn lǐxiǎng.","vi":"Căn nhà này không những giao thông thuận tiện, môi trường yên tĩnh mà giá cả cũng rất lý tưởng."},{"type":"compound","zh":"为了实现将来当一名外交官的理想，他每天都在刻苦学习外语。","pinyin":"Wèile shíxiàn jiānglái dāng yì míng wàijiāoguān de lǐxiǎng, tā měitiān dōu zài kèkǔ xuéxí wàiyǔ.","vi":"Để thực hiện lý tưởng tương lai làm một nhà ngoại giao, ngày nào anh ấy cũng chăm chỉ học ngoại ngữ."}],"related":[{"hanzi":"梦想","pinyin":"mèngxiǎng","vi":"Ước mơ"},{"hanzi":"希望","pinyin":"xīwàng","vi":"Hy vọng"},{"hanzi":"将来","pinyin":"jiānglái","vi":"Tương lai"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"Thấu hiểu"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"Mục tiêu"}]},{"id":"联系","hanzi":"联系","pinyin":"liánxì","meaning_vi":"liên hệ, liên lạc","explanation":"联 (nối liền) + 系 (buộc lại).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"📱","examples":[{"type":"basic","zh":"我们经常保持联系。","pinyin":"Wǒmen jīngcháng bǎochí liánxì.","vi":"Chúng tôi thường xuyên giữ liên lạc."},{"type":"simple","zh":"大学毕业以后，虽然大家去了不同的城市，但是依然经常用微信联系。","pinyin":"Dàxué bìyè yǐhòu, suīrán dàjiā qùle bùtóng de chéngshì, dànshì yīrán jīngcháng yòng Wēixìn liánxì.","vi":"Sau khi tốt nghiệp đại học, tuy mọi người đến các thành phố khác nhau nhưng vẫn thường xuyên liên lạc qua WeChat."},{"type":"compound","zh":"如果你在机场找不到接站的人，请马上打这个手机号码跟我联系。","pinyin":"Rúguǒ nǐ zài jīchǎng zhǎobúdào jiē zhàn de rén, qǐng mǎshàng dǎ zhè ge shǒujī hàomǎ gēn wǒ liánxì.","vi":"Nếu ở sân bay bạn không tìm thấy người đón thì xin gọi ngay số điện thoại này để liên hệ với tôi."}],"related":[{"hanzi":"关系","pinyin":"guānxi","vi":"Quan hệ"},{"hanzi":"连","pinyin":"lián","vi":"Nối liền"},{"hanzi":"电话","pinyin":"diànhuà","vi":"Điện thoại"},{"hanzi":"手机","pinyin":"shǒujī","vi":"Di động"},{"hanzi":"通知","pinyin":"tōngzhī","vi":"Thông báo"}],"traditional":"聯繫"},{"id":"凉","hanzi":"凉","pinyin":"liáng","meaning_vi":"mát, nguội","explanation":"Bộ băng 冫+ 京.","hsk_level":3,"tags":["tinh-tu"],"image":"🧊","examples":[{"type":"basic","zh":"天气变凉了，多穿点儿。","pinyin":"Tiānqì biàn liáng le, duō chuān diǎnr.","vi":"Trời trở mát rồi, mặc thêm áo vào."},{"type":"simple","zh":"这碗面条放得太久已经变凉了，我帮你拿去热一下再吃吧。","pinyin":"Zhè wǎn miàntiáo fàng de tài jiǔ yǐjīng biàn liáng le, wǒ bāng nǐ ná qù rè yíxià zài chī ba.","vi":"Bát mì này để lâu quá đã nguội rồi, để tôi mang đi hâm nóng lại giúp bạn rồi hãy ăn nhé."},{"type":"compound","zh":"秋天到了，早晚的空气明显变凉，出门时最好带一件薄外套。","pinyin":"Qiūtiān dào le, zǎowǎn de kōngqì míngxiǎn biàn liáng, chūmén shí zuìhǎo dài yí jiàn báo wàitào.","vi":"Mùa thu đến rồi, không khí sáng tối mát lạnh rõ rệt, khi ra ngoài tốt nhất mang theo một chiếc áo khoác mỏng."}],"related":[{"hanzi":"凉快","pinyin":"liángkuai","vi":"Mát mẻ"},{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"Ấm áp"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"}],"traditional":"涼"},{"id":"流利","hanzi":"流利","pinyin":"liúlì","meaning_vi":"trôi chảy, lưu loát","explanation":"流 (chảy) + 利 (trơn tru). Dùng khen khả năng nói ngoại ngữ.","hsk_level":3,"tags":["tinh-tu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"他说得一口流利的汉语。","pinyin":"Tā shuō de yìkǒu liúlì de Hànyǔ.","vi":"Anh ấy nói tiếng Trung vô cùng trôi chảy."},{"type":"simple","zh":"那位外国留学生不仅汉语说得非常流利，而且还会唱很多中文歌。","pinyin":"Nà wèi wàiguó liúxuésheng bùjǐn Hànyǔ shuō de fēicháng liúlì, érqiě hái huì chàng hěn duō Zhōngwén gē.","vi":"Du học sinh nước ngoài đó không những nói tiếng Trung vô cùng trôi chảy mà còn biết hát nhiều bài hát tiếng Trung."},{"type":"compound","zh":"想要说出一口流利的外语，唯一的秘诀就是多听、多模仿、多开口练习。","pinyin":"Xiǎngyào shuōchū yìkǒu liúlì de wàiyǔ, wéiyī de mìjué jiùshì duō tīng, duō mófǎng, duō kāikǒu liànxí.","vi":"Muốn nói được ngoại ngữ trôi chảy, bí quyết duy nhất là nghe nhiều, bắt chước nhiều và mở miệng luyện tập nhiều."}],"related":[{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"流行","pinyin":"liúxíng","vi":"Thịnh hành"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"Thuận lợi"},{"hanzi":"语言","pinyin":"yǔyán","vi":"Ngôn ngữ"},{"hanzi":"普通话","pinyin":"pǔtōnghuà","vi":"Tiếng phổ thông"}]},{"id":"流行","hanzi":"流行","pinyin":"liúxíng","meaning_vi":"thịnh hành, phổ biến, mốt","explanation":"流 (lan truyền) + 行 (đi).","hsk_level":3,"tags":["tinh-tu","dong-tu"],"image":"🔥","examples":[{"type":"basic","zh":"这首歌现在很流行。","pinyin":"Zhè shǒu gē xiànzài hěn liúxíng.","vi":"Bài hát này hiện nay rất thịnh hành."},{"type":"simple","zh":"现在中国年轻人中间非常流行用手机看短视频和网上购物。","pinyin":"Xiànzài Zhōngguó niánqīngrén zhōngjiān fēicháng liúxíng yòng shǒujī kàn duǎnshìpín hé wǎngshang gòuwù.","vi":"Hiện nay trong giới trẻ Trung Quốc vô cùng thịnh hành việc dùng điện thoại xem video ngắn và mua sắm trực tuyến."},{"type":"compound","zh":"虽然每年的流行服装款式都在变化，但是简单大方的衣服永远不会过时。","pinyin":"Suīrán měinián de liúxíng fúzhuāng kuǎnshì dōu zài biànhuà, dànshì jiǎndān dàfāng de yīfu yǒngyuǎn bú huì guòshí.","vi":"Tuy kiểu dáng trang phục thịnh hành mỗi năm đều thay đổi nhưng quần áo đơn giản thanh lịch thì không bao giờ lỗi mốt."}],"related":[{"hanzi":"流利","pinyin":"liúlì","vi":"Trôi chảy"},{"hanzi":"进行","pinyin":"jìnxíng","vi":"Tiến hành"},{"hanzi":"流行病","pinyin":"liúxíngbìng","vi":"Bệnh dịch"},{"hanzi":"时尚","pinyin":"shíshàng","vi":"Thời trang"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"Trẻ tuổi"}]},{"id":"留","hanzi":"留","pinyin":"liú","meaning_vi":"ở lại, lưu lại, giữ lại","explanation":"Dùng trong 留学 (du học), 留下 (ở lại).","hsk_level":3,"tags":["dong-tu"],"image":"🏠","examples":[{"type":"basic","zh":"请把你的电话号码留给我。","pinyin":"Qǐng bǎ nǐ de diànhuà hàomǎ liúgěi wǒ.","vi":"Xin hãy để lại số điện thoại của bạn cho tôi."},{"type":"simple","zh":"他大学毕业以后决定留在这座美丽的城市继续发展自己的事业。","pinyin":"Tā dàxué bìyè yǐhòu juédìng liú zài zhè zuò měilì de chéngshì jìxù fāzhǎn zìjǐ de shìyè.","vi":"Sau khi tốt nghiệp đại học, anh ấy quyết định ở lại thành phố xinh đẹp này để tiếp tục phát triển sự nghiệp."},{"type":"compound","zh":"虽然我们在北京只停留了短短三天，但是长城和故宫给我们留下了深刻印象。","pinyin":"Suīrán wǒmen zài Běijīng zhǐ tíngliúle duǎn duǎn sān tiān, dànshì Chángchéng hé gùgōng gěi wǒmen liúxiàle shēnkè yìnxiàng.","vi":"Tuy chúng tôi chỉ lưu lại Bắc Kinh vỏn vẹn 3 ngày nhưng Vạn Lý Trường Thành và Cố Cung đã để lại ấn tượng sâu sắc."}],"related":[{"hanzi":"留学","pinyin":"liúxué","vi":"Du học"},{"hanzi":"留学生","pinyin":"liúxuésheng","vi":"Du học sinh"},{"hanzi":"留下","pinyin":"liúxià","vi":"Để lại"},{"hanzi":"离开","pinyin":"líkāi","vi":"Rời khỏi"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"Ấn tượng"}]},{"id":"留学","hanzi":"留学","pinyin":"liúxué","meaning_vi":"du học","explanation":"留 (lưu lại) + 学 (học tập). Cụm: 留学生 (du học sinh).","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"我哥哥在中国留学。","pinyin":"Wǒ gēge zài Zhōngguó liúxué.","vi":"Anh trai tôi đang du học ở Trung Quốc."},{"type":"simple","zh":"他去年获得了中国政府奖学金，现在正在北京大学留学。","pinyin":"Tā qùnián huòdéle Zhōngguó zhèngfǔ jiǎngxuéjīn, xiànzài zhèngzài Běijīngdàxué liúxué.","vi":"Năm ngoái anh ấy giành được học bổng Chính phủ Trung Quốc, hiện đang du học tại Đại học Bắc Kinh."},{"type":"compound","zh":"出国留学不仅可以学到先进的专业知识，还能锻炼我们独立生活的能力。","pinyin":"Chūguó liúxué bùjǐn kěyǐ xuédào xiānjìn de zhuānyè zhīshi, hái néng duànliàn wǒmen dúlì shēnghuó de nénglì.","vi":"Đi du học nước ngoài không chỉ học được kiến thức chuyên ngành tiên tiến mà còn rèn luyện khả năng sống tự lập của chúng ta."}],"related":[{"hanzi":"留","pinyin":"liú","vi":"Ở lại"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"学生","pinyin":"xuésheng","vi":"Học sinh"},{"hanzi":"大学","pinyin":"dàxué","vi":"Đại học"},{"hanzi":"外国","pinyin":"wàiguó","vi":"Nước ngoài"}],"traditional":"留學"},{"id":"律师","hanzi":"律师","pinyin":"lǜshī","meaning_vi":"luật sư","explanation":"律 (pháp luật) + 师 (thầy/chuyên gia).","hsk_level":3,"tags":["danh-tu","nghe-nghiep"],"image":"⚖️","examples":[{"type":"basic","zh":"王先生是一名律师。","pinyin":"Wáng xiānsheng shì yì míng lǜshī.","vi":"Ông Vương là một luật sư."},{"type":"simple","zh":"遇到复杂的商业合同问题时，最好请专业律师帮忙审查一下。","pinyin":"Yùdào fùzá de shāngyè hétong wèntí shí, zuìhǎo qǐng zhuānyè lǜshī bāngmáng shěnchá yíxià.","vi":"Khi gặp các vấn đề hợp đồng thương mại phức tạp, tốt nhất nên nhờ luật sư chuyên nghiệp xem xét giúp."},{"type":"compound","zh":"因为她从小就喜欢辩论而且记忆力很好，所以大学毕业后成为了一名律师。","pinyin":"Yīnwèi tā cóngxiǎo jiù xǐhuan biànlùn érqiě jìyìlì hěn hǎo, suǒyǐ dàxué bìyè hòu chéng wéile yì míng lǜshī.","vi":"Vì từ nhỏ cô ấy đã thích tranh luận và có trí nhớ rất tốt nên sau khi tốt nghiệp đại học đã trở thành luật sư."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"Pháp luật"},{"hanzi":"老师","pinyin":"lǎoshī","vi":"Giáo viên"},{"hanzi":"医生","pinyin":"yīshēng","vi":"Bác sĩ"},{"hanzi":"职业","pinyin":"zhíyè","vi":"Nghề nghiệp"},{"hanzi":"专业","pinyin":"zhuānyè","vi":"Chuyên ngành"}],"traditional":"律師"},{"id":"乱","hanzi":"乱","pinyin":"luàn","meaning_vi":"lộn xộn, bừa bộn, loạn","explanation":"Đối nghĩa với 整齐 (ngăn nắp).","hsk_level":3,"tags":["tinh-tu"],"image":"🌪️","examples":[{"type":"basic","zh":"房间里很乱，快收拾吧。","pinyin":"Fángjiān lǐ hěn luàn, kuài shōushi ba.","vi":"Trong phòng bừa bộn quá, mau dọn dẹp đi."},{"type":"simple","zh":"弟弟把玩具和图画书扔得满地都是，把客厅弄得乱七八糟的。","pinyin":"Dìdi bǎ wánjù hé túhuà shū rēng de mǎndì dōu shì, bǎ kètīng nòng de luànqībāzāo de.","vi":"Em trai vứt đồ chơi và sách tranh đầy dưới sàn, làm phòng khách bừa bộn lung tung."},{"type":"compound","zh":"在公共场所大家应该自觉排队，千万不要乱挤乱插队，要注意礼貌。","pinyin":"Zài gōnggòngchǎngsuǒ dàjiā yīnggāi zìjué páiduì, qiānwàn bú yào luàn jǐ luàn chāduì, yào zhùyì lǐmào.","vi":"Ở nơi công cộng mọi người nên tự giác xếp hàng, tuyệt đối đừng chen lấn xô đẩy bừa bãi, phải giữ lịch sự."}],"related":[{"hanzi":"整齐","pinyin":"zhěngqí","vi":"Ngăn nắp"},{"hanzi":"收拾","pinyin":"shōushi","vi":"Dọn dẹp"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"扔","pinyin":"rēng","vi":"Vứt"}],"traditional":"亂"},{"id":"麻烦","hanzi":"麻烦","pinyin":"máfan","meaning_vi":"phiền phức, làm phiền","explanation":"麻 + 烦 (phiền toái). Vừa là tính từ vừa là động từ.","hsk_level":3,"tags":["tinh-tu","dong-tu"],"image":"😓","examples":[{"type":"basic","zh":"真不好意思，麻烦你了！","pinyin":"Zhēn bù hǎoyìsi, máfan nǐ le!","vi":"Thật ngại quá, làm phiền bạn rồi!"},{"type":"simple","zh":"自己做饭虽然有点儿麻烦，但是既卫生又省钱，还很健康。","pinyin":"Zìjǐ zuòfàn suīrán yǒudiǎnr máfan, dànshì jì wèishēng yòu shěngqián, hái hěn jiànkāng.","vi":"Tự nấu cơm tuy hơi phiền phức một chút nhưng vừa vệ sinh vừa tiết kiệm tiền lại rất lành mạnh."},{"type":"compound","zh":"请问，能麻烦您帮我把这份重要文件转交给王经理吗？非常感谢！","pinyin":"Qǐngwèn, néng máfan nín bāng wǒ bǎ zhè fèn zhòngyào wénjiàn zhuǎnjiāo gěi Wáng jīnglǐ ma? fēicháng gǎnxiè!","vi":"Xin hỏi, có thể phiền ngài chuyển giúp tôi tài liệu quan trọng này cho giám đốc Vương được không ạ? Vô cùng cảm ơn!"}],"related":[{"hanzi":"打扰","pinyin":"dǎrǎo","vi":"Làm phiền"},{"hanzi":"烦恼","pinyin":"fánnǎo","vi":"Phiền muộn"},{"hanzi":"帮忙","pinyin":"bāngmáng","vi":"Giúp đỡ"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"Đơn giản"},{"hanzi":"复杂","pinyin":"fùzá","vi":"Phức tạp"}],"traditional":"麻煩"},{"id":"马虎","hanzi":"马虎","pinyin":"mǎhu","meaning_vi":"qua loa, cẩu thả","explanation":"马 (ngựa) + 虎 (hổ). Đối nghĩa với 认真 / 仔细 (cẩn thận).","hsk_level":3,"tags":["tinh-tu"],"image":"🙈","examples":[{"type":"basic","zh":"他做作业太马虎了。","pinyin":"Tā zuò zuòyè tài mǎhu le.","vi":"Cậu ấy làm bài tập cẩu thả quá."},{"type":"simple","zh":"这次数学考试他因为太马虎，看错了两个数字，白白丢了十分。","pinyin":"Zhè cì shùxué kǎoshì tā yīnwèi tài mǎhu, kàncuòle liǎng ge shùzì, báibái diūle shífēn.","vi":"Kỳ thi toán lần này vì quá cẩu thả, nhìn nhầm hai con số nên cậu ấy mất oan 10 điểm."},{"type":"compound","zh":"做任何工作都必须认真仔细，如果马马虎虎的话，很容易出大错误。","pinyin":"Zuò rènhé gōngzuò dōu bìxū rènzhēn zǐxì, rúguǒ mǎ mǎhu hu dehuà, hěn róngyì chū dà cuòwù.","vi":"Làm bất cứ công việc gì cũng bắt buộc phải nghiêm túc cẩn thận, nếu qua loa đại khái thì rất dễ mắc sai lầm lớn."}],"related":[{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"},{"hanzi":"仔细","pinyin":"zǐxì","vi":"Cẩn thận"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"Kiểm tra"}],"traditional":"馬虎"},{"id":"满足","hanzi":"满足","pinyin":"mǎnzú","meaning_vi":"hài lòng, thỏa mãn; đáp ứng (nhu cầu)","explanation":"满 (đầy) + 足 (đủ).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"😊","examples":[{"type":"basic","zh":"我对现在的生活很满足。","pinyin":"Wǒ duì xiànzài de shēnghuó hěn mǎnzú.","vi":"Tôi rất hài lòng với cuộc sống hiện tại."},{"type":"simple","zh":"这家大型超市商品种类齐全，能够满足附近居民的各种日常需求。","pinyin":"Zhè jiā dàxíng chāoshì shāngpǐn zhǒnglèi qíquán, nénggòu mǎnzú fùjìn jūmín de gèzhǒng rìcháng xūqiú.","vi":"Siêu thị lớn này chủng loại hàng hóa đầy đủ, có thể đáp ứng mọi nhu cầu sinh hoạt hằng ngày của cư dân lân cận."},{"type":"compound","zh":"做人应该懂得知足常乐，但同时在学习上又不能轻易满足于现状。","pinyin":"Zuòrén yīnggāi dǒngde zhīzúchánglè, dàn tóngshí zài xuéxí shàng yòu bù néng qīngyì mǎnzú yú xiànzhuàng.","vi":"Làm người nên biết hài lòng với những gì mình có nhưng đồng thời trong học tập lại không được dễ dàng thỏa mãn với hiện tại."}],"related":[{"hanzi":"满意","pinyin":"mǎnyì","vi":"Hài lòng"},{"hanzi":"满","pinyin":"mǎn","vi":"Đầy"},{"hanzi":"足球","pinyin":"zúqiú","vi":"Bóng đá"},{"hanzi":"够","pinyin":"gòu","vi":"Đủ"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"}],"traditional":"滿足"},{"id":"迷路","hanzi":"迷路","pinyin":"mílù","meaning_vi":"lạc đường","explanation":"迷 (mê muội/lạc) + 路 (con đường). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🧭","examples":[{"type":"basic","zh":"他在大城市里迷路了。","pinyin":"Tā zài Dàchéng shìlǐ mílù le.","vi":"Anh ấy bị lạc đường trong thành phố lớn."},{"type":"simple","zh":"因为这是我第一次来北京，所以刚出火车站就差点儿迷路了。","pinyin":"Yīnwèi zhè shì wǒ dìyīcì lái Běijīng, suǒyǐ gāng chū huǒchēzhàn jiù chàdiǎnr mílù le.","vi":"Vì đây là lần đầu tiên tôi đến Bắc Kinh nên vừa ra khỏi ga tàu hỏa đã suýt nữa thì lạc đường."},{"type":"compound","zh":"现在出门旅游有了手机电子地图，即使去陌生的地方也不容易迷路了。","pinyin":"Xiànzài chūmén lǚyóu yǒule shǒujī diànzǐ dìtú, jíshǐ qù mòshēng de dìfang yě bù róngyì mílù le.","vi":"Hiện nay đi du lịch có bản đồ điện tử trên điện thoại rồi, cho dù đến nơi xa lạ cũng không dễ bị lạc đường nữa."}],"related":[{"hanzi":"路","pinyin":"lù","vi":"Con đường"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"找","pinyin":"zhǎo","vi":"Tìm"},{"hanzi":"警察","pinyin":"jǐngchá","vi":"Cảnh sát"}]},{"id":"免费","hanzi":"免费","pinyin":"miǎnfèi","meaning_vi":"miễn phí","explanation":"免 (miễn trừ) + 费 (chi phí).","hsk_level":3,"tags":["dong-tu","mua-sam"],"image":"🆓","examples":[{"type":"basic","zh":"这个公园对老人免费。","pinyin":"Zhè ge gōngyuán duì lǎorén miǎnfèi.","vi":"Công viên này miễn phí cho người cao tuổi."},{"type":"simple","zh":"现在很多城市的博物馆和图书馆都向公众免费开放。","pinyin":"Xiànzài hěn duō chéngshì de bówùguǎn hé túshūguǎn dōu xiàng gōngzhòng miǎnfèikāifàng.","vi":"Hiện nay bảo tàng và thư viện ở nhiều thành phố đều mở cửa miễn phí cho công chúng."},{"type":"compound","zh":"只要在这家超市购物满两百元，就可以享受免费送货上门的服务。","pinyin":"Zhǐyào zài zhè jiā chāoshì gòuwù mǎn liǎng bǎi yuán, jiù kěyǐ xiǎngshòu miǎnfèi sònghuò shàngmén de fúwù.","vi":"Chỉ cần mua sắm tại siêu thị này đủ 200 tệ là có thể hưởng dịch vụ giao hàng tận nhà miễn phí."}],"related":[{"hanzi":"浪费","pinyin":"làngfèi","vi":"Lãng phí"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"便宜","pinyin":"piányi","vi":"Rẻ"},{"hanzi":"价格","pinyin":"jiàgé","vi":"Giá cả"},{"hanzi":"服务","pinyin":"fúwù","vi":"Phục vụ"}],"traditional":"免費"},{"id":"秒","hanzi":"秒","pinyin":"miǎo","meaning_vi":"giây","explanation":"Bộ hòa 禾 + 少. Đơn vị thời gian nhỏ hơn phút (分).","hsk_level":3,"tags":["luong-tu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"一分钟有六十秒。","pinyin":"Yì fēnzhōng yǒu liùshí miǎo.","vi":"Một phút có sáu mươi giây."},{"type":"simple","zh":"他在校运会一百米短跑比赛中只用了十一秒就跑到了终点。","pinyin":"Tā zài xiàoyùnhuì yī bǎimǐ duǎnpǎo bǐsài zhōng zhǐ yòngle shíyī miǎo jiù pǎo dàole zhōngdiǎn.","vi":"Cậu ấy chỉ mất 11 giây đã chạy tới đích trong cuộc thi chạy nước rút 100 mét tại hội thao trường."},{"type":"compound","zh":"时间非常宝贵，我们要珍惜每一分每一秒，努力学习科学文化知识。","pinyin":"Shíjiān fēicháng bǎoguì, wǒmen yào zhēnxī měi yì fēn měi yì miǎo, nǔlì xuéxí kēxué wénhuà zhīshi.","vi":"Thời gian vô cùng quý giá, chúng ta phải trân trọng từng phút từng giây, nỗ lực học tập kiến thức khoa học văn hóa."}],"related":[{"hanzi":"分","pinyin":"fēn","vi":"Phút"},{"hanzi":"分钟","pinyin":"fēnzhōng","vi":"Phút"},{"hanzi":"小时","pinyin":"xiǎoshí","vi":"Tiếng đồng hồ"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"手表","pinyin":"shǒubiǎo","vi":"Đồng hồ"}]},{"id":"民族","hanzi":"民族","pinyin":"mínzú","meaning_vi":"dân tộc","explanation":"民 (nhân dân) + 族 (tộc người).","hsk_level":3,"tags":["danh-tu","van-hoa"],"image":"🌏","examples":[{"type":"basic","zh":"中国有五十六个民族。","pinyin":"Zhōng guóyǒu wǔ shíliù ge mínzú.","vi":"Trung Quốc có 56 dân tộc."},{"type":"simple","zh":"每个民族都有自己独特的服装、饮食习惯和传统节日。","pinyin":"Měi ge mínzú dōu yǒu zìjǐ dútè de fúzhuāng, yǐnshí xíguàn hé chuántǒng jiérì.","vi":"Mỗi dân tộc đều có trang phục, thói quen ăn uống và lễ hội truyền thống độc đáo riêng."},{"type":"compound","zh":"晚会上，少数民族的同学们穿着漂亮的民族服装跳起了欢快的舞蹈。","pinyin":"Wǎnhuì shang, shǎoshù mínzú de tóngxuémen chuānzhe piàoliang de mínzú fúzhuāng tiào qǐle huānkuài de wǔdǎo.","vi":"Tại đêm hội, các bạn học dân tộc thiểu số mặc trang phục dân tộc xinh đẹp cùng nhau nhảy những điệu múa vui tươi."}],"related":[{"hanzi":"人民","pinyin":"rénmín","vi":"Nhân dân"},{"hanzi":"国家","pinyin":"guójiā","vi":"Quốc gia"},{"hanzi":"文化","pinyin":"wénhuà","vi":"Văn hóa"},{"hanzi":"传统","pinyin":"chuántǒng","vi":"Truyền thống"},{"hanzi":"节日","pinyin":"jiérì","vi":"Ngày lễ"}]},{"id":"母亲","hanzi":"母亲","pinyin":"mǔqīn","meaning_vi":"mẹ (trang trọng)","explanation":"母 (mẹ) + 亲 (thân thích). Đối ứng với 父亲 (cha).","hsk_level":3,"tags":["danh-tu","gia-dinh"],"image":"👩","examples":[{"type":"basic","zh":"我非常爱我的母亲。","pinyin":"Wǒ fēicháng ài wǒ de mǔqīn.","vi":"Tôi vô cùng yêu mẹ của tôi."},{"type":"simple","zh":"每年五月的第二个星期日是母亲节，很多人都会给妈妈送花。","pinyin":"Měinián Wǔyuè de dì'èr ge Xīngqīrì shì Mǔqīnjié, hěn duō rén dōuhuì gěi māma sòng huā.","vi":"Chủ nhật thứ hai của tháng 5 hằng năm là Ngày của Mẹ, nhiều người đều tặng hoa cho mẹ."},{"type":"compound","zh":"母亲不仅给了我们生命，而且在我们成长的过程中付出了无数心血。","pinyin":"Mǔqīn bùjǐn gěile wǒmen shēngmìng, érqiě zài wǒmen chéngzhǎng de guòchéng zhōng fùchūle wúshù xīnxuè.","vi":"Người mẹ không chỉ ban cho chúng ta sự sống mà còn bỏ ra biết bao tâm huyết trong quá trình trưởng thành của chúng ta."}],"related":[{"hanzi":"父亲","pinyin":"fùqīn","vi":"Cha"},{"hanzi":"妈妈","pinyin":"māma","vi":"Mẹ"},{"hanzi":"父母","pinyin":"fùmǔ","vi":"Bố mẹ"},{"hanzi":"亲戚","pinyin":"qīnqi","vi":"Họ hàng"},{"hanzi":"家人","pinyin":"jiārén","vi":"Người nhà"}],"traditional":"母親"},{"id":"父亲","hanzi":"父亲","pinyin":"fùqīn","meaning_vi":"cha, bố (trang trọng)","explanation":"父 (cha) + 亲 (thân thích). Đối ứng với 母亲 (mẹ).","hsk_level":3,"tags":["danh-tu","gia-dinh"],"image":"👨","examples":[{"type":"basic","zh":"我的父亲是一名医生。","pinyin":"Wǒ de fùqīn shì yì míng yīshēng.","vi":"Cha tôi là một bác sĩ."},{"type":"simple","zh":"虽然父亲平时工作非常忙碌，但是他每天都会抽时间关心我的学习。","pinyin":"Suīrán fùqīn píngshí gōngzuò fēicháng mánglù, dànshì tā měitiān dōuhuì chōushíjiān guānxīn wǒ de xuéxí.","vi":"Tuy bình thường cha làm việc vô cùng bận rộn nhưng ngày nào ông cũng dành thời gian quan tâm đến việc học của tôi."},{"type":"compound","zh":"在父亲的影响下，我从小就养成了喜欢阅读和坚持锻炼的好习惯。","pinyin":"Zài fùqīn de yǐngxiǎng xià, wǒ cóngxiǎo jiù yǎngchéngle xǐhuan yuèdú hé jiānchí duànliàn de hǎo xíguàn.","vi":"Dưới sự ảnh hưởng của cha, từ nhỏ tôi đã hình thành thói quen tốt là thích đọc sách và kiên trì tập thể dục."}],"related":[{"hanzi":"母亲","pinyin":"mǔqīn","vi":"Mẹ"},{"hanzi":"爸爸","pinyin":"bàba","vi":"Bố"},{"hanzi":"父母","pinyin":"fùmǔ","vi":"Bố mẹ"},{"hanzi":"亲戚","pinyin":"qīnqi","vi":"Họ hàng"},{"hanzi":"男人","pinyin":"nánrén","vi":"Đàn ông"}],"traditional":"父親"},{"id":"目的","hanzi":"目的","pinyin":"mùdì","meaning_vi":"mục đích","explanation":"目 (mắt nhìn) + 的 (đích ngắm).","hsk_level":3,"tags":["danh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"你去中国的目的是什么？","pinyin":"Nǐ qù Zhōngguó de mùdì shì shénme?","vi":"Mục đích bạn đi Trung Quốc là gì?"},{"type":"simple","zh":"我这次去北京旅游的主要目的是参观长城、故宫和品尝烤鸭。","pinyin":"Wǒ zhè cì qù Běijīng lǚyóu de zhǔyào mùdì shì cānguān Chángchéng, gùgōng hé pǐncháng kǎoyā.","vi":"Mục đích chính của chuyến du lịch Bắc Kinh lần này của tôi là tham quan Vạn Lý Trường Thành, Cố Cung và thưởng thức vịt quay."},{"type":"compound","zh":"做任何事情之前都要先明确自己的目的，这样才能找到最有效的方法。","pinyin":"Zuò rènhé shìqing zhīqián dōu yào xiān míngquè zìjǐ de mùdì, zhèyàng cáinéng zhǎodào zuì yǒuxiào de fāngfǎ.","vi":"Trước khi làm bất cứ việc gì đều phải xác định rõ mục đích của mình, như vậy mới tìm được phương pháp hiệu quả nhất."}],"related":[{"hanzi":"目标","pinyin":"mùbiāo","vi":"Mục tiêu"},{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"为了","pinyin":"wèile","vi":"Để/Vì"},{"hanzi":"计划","pinyin":"jìhuà","vi":"Kế hoạch"}]},{"id":"耐心","hanzi":"耐心","pinyin":"nàixīn","meaning_vi":"kiên nhẫn","explanation":"耐 (chịu đựng) + 心 (tâm trí). Vừa là tính từ vừa là danh từ.","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🧘","examples":[{"type":"basic","zh":"王老师对学生很有耐心。","pinyin":"Wáng lǎoshī duì xuésheng hěn yǒu nàixīn.","vi":"Thầy Vương rất kiên nhẫn với học sinh."},{"type":"simple","zh":"教小孩子学习写字需要极大的耐心，不能轻易发脾气。","pinyin":"Jiāo xiǎoháizi xuéxí xiězì xūyào jídà de nàixīn, bù néng qīngyì fāpíqi.","vi":"Dạy trẻ nhỏ học viết chữ cần sự kiên nhẫn cực kỳ lớn, không thể dễ dàng nổi nóng."},{"type":"compound","zh":"不管我们问多少遍，王老师总是耐心地一遍又一遍给我们解释清楚。","pinyin":"Bùguǎn wǒmen wèn duōshao biàn, Wáng lǎoshī zǒngshì nàixīn de yíbiàn yòu yíbiàn gěi wǒmen jiěshì qīngchu.","vi":"Bất kể chúng tôi hỏi bao nhiêu lần, thầy Vương luôn kiên nhẫn giải thích rõ ràng hết lần này đến lần khác."}],"related":[{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"脾气","pinyin":"píqi","vi":"Tính khí"},{"hanzi":"着急","pinyin":"zháojí","vi":"Sốt ruột"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"}]},{"id":"难道","hanzi":"难道","pinyin":"nándào","meaning_vi":"chẳng lẽ, lẽ nào","explanation":"Phó từ dùng trong câu hỏi tu từ để nhấn mạnh sự ngạc nhiên.","hsk_level":3,"tags":["pho-tu","nghi-van"],"image":"🤨","examples":[{"type":"basic","zh":"难道你不知道这件事吗？","pinyin":"Nándào nǐ bù zhīdao zhè jiàn shì ma?","vi":"Chẳng lẽ bạn không biết chuyện này sao?"},{"type":"simple","zh":"外面阳光这么好，你难道不打算出去散散步吗？","pinyin":"Wàimiàn yángguāng zhème hǎo, nǐ nándào bù dǎsuàn chūqù sàn sanbù ma?","vi":"Bên ngoài nắng đẹp thế này, chẳng lẽ bạn không định ra ngoài đi dạo một chút sao?"},{"type":"compound","zh":"考试成绩都出来了，难道你还没去网站上查一下自己的分数吗？","pinyin":"Kǎoshì chéngjì dōu chūlái le, nándào nǐ hái méi qù wǎngzhàn shang chá yíxià zìjǐ de fēnshù ma?","vi":"Điểm thi đã có hết rồi, lẽ nào bạn vẫn chưa lên trang web tra điểm số của mình sao?"}],"related":[{"hanzi":"难","pinyin":"nán","vi":"Khó"},{"hanzi":"知道","pinyin":"zhīdao","vi":"Biết"},{"hanzi":"味道","pinyin":"wèidào","vi":"Mùi vị"},{"hanzi":"难道说","pinyin":"nándàoshuō","vi":"Lẽ nào nói"},{"hanzi":"怎么","pinyin":"zěnme","vi":"Sao lại"}],"traditional":"難道"},{"id":"内容","hanzi":"内容","pinyin":"nèiróng","meaning_vi":"nội dung","explanation":"内 (bên trong) + 容 (chứa đựng).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"这本书的内容很丰富。","pinyin":"Zhè běn shū de nèiróng hěn fēngfù.","vi":"Nội dung của quyển sách này rất phong phú."},{"type":"simple","zh":"今天的会议内容非常重要，请大家认真做好笔记。","pinyin":"Jīntiān de huìyì nèiróng fēicháng zhòngyào, qǐng dàjiā rènzhēn zuò hǎo bǐjì.","vi":"Nội dung cuộc họp hôm nay vô cùng quan trọng, xin mọi người nghiêm túc ghi chép đầy đủ."},{"type":"compound","zh":"虽然这部电影的名字很普通，但是里面的故事情节和内容却非常精彩。","pinyin":"Suīrán zhè bù diànyǐng de míngzi hěn pǔtōng, dànshì lǐmiàn de gùshi qíngjié hé nèiróng què fēicháng jīngcǎi.","vi":"Tuy tên của bộ phim này rất bình thường nhưng tình tiết câu chuyện và nội dung bên trong lại vô cùng đặc sắc."}],"related":[{"hanzi":"内","pinyin":"nèi","vi":"Bên trong"},{"hanzi":"容易","pinyin":"róngyì","vi":"Dễ dàng"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"Bài văn"},{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"Phong phú"}],"traditional":"內容"},{"id":"能力","hanzi":"能力","pinyin":"nénglì","meaning_vi":"năng lực, khả năng","explanation":"能 (có thể) + 力 (sức lực).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"他的工作能力很强。","pinyin":"Tā de gōngzuò nénglì hěn qiáng.","vi":"Năng lực làm việc của anh ấy rất giỏi."},{"type":"simple","zh":"参加社会实践活动可以有效提高大学生的沟通能力和解决问题的能力。","pinyin":"Cānjiā shèhuì shíjiàn huódòng kěyǐ yǒuxiào tígāo dàxuésheng de gōutōng nénglì hé jiějué wèntí de nénglì.","vi":"Tham gia các hoạt động thực tiễn xã hội có thể nâng cao hiệu quả kỹ năng giao tiếp và giải quyết vấn đề của sinh viên."},{"type":"compound","zh":"只要我们平时多读书、多思考，就一定能不断提高自己的综合能力。","pinyin":"Zhǐyào wǒmen píngshí duō dúshū, duō sīkǎo, jiù yídìng néng búduàn tígāo zìjǐ de zōnghé nénglì.","vi":"Chỉ cần bình thường chúng ta đọc sách nhiều, suy nghĩ nhiều thì nhất định sẽ không ngừng nâng cao năng lực tổng hợp."}],"related":[{"hanzi":"能","pinyin":"néng","vi":"Có thể"},{"hanzi":"力气","pinyin":"lìqi","vi":"Sức lực"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"Trình độ"},{"hanzi":"优秀","pinyin":"yōuxiù","vi":"Xuất sắc"}]},{"id":"年龄","hanzi":"年龄","pinyin":"niánlíng","meaning_vi":"tuổi tác, độ tuổi","explanation":"年 (năm) + 龄 (tuổi).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"🎂","examples":[{"type":"basic","zh":"请问您的年龄是多少？","pinyin":"Qǐngwèn nín de niánlíng shì duōshao?","vi":"Xin hỏi tuổi của ngài là bao nhiêu ạ?"},{"type":"simple","zh":"虽然他们两个人年龄相差十岁，但是在一起聊天却非常投缘。","pinyin":"Suīrán tāmen liǎng ge rén niánlíng xiāngchà shí suì, dànshì zài yìqǐ liáotiān què fēicháng tóuyuán.","vi":"Tuy hai người họ cách nhau 10 tuổi nhưng trò chuyện cùng nhau lại vô cùng hợp ý."},{"type":"compound","zh":"在求职招聘时，很多公司更看重的是个人的工作能力，而不是年龄大小。","pinyin":"Zài qiúzhí zhāopìn shí, hěn duō gōngsī gèng kànzhòng de shì gèrén de gōngzuò nénglì, ér bú shì niánlíng dàxiǎo.","vi":"Khi tuyển dụng việc làm, nhiều công ty coi trọng năng lực làm việc của cá nhân hơn là tuổi tác lớn nhỏ."}],"related":[{"hanzi":"年","pinyin":"nián","vi":"Năm"},{"hanzi":"岁","pinyin":"suì","vi":"Tuổi"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"Trẻ tuổi"},{"hanzi":"老","pinyin":"lǎo","vi":"Già"},{"hanzi":"多大","pinyin":"duōdà","vi":"Bao nhiêu tuổi"}],"traditional":"年齡"},{"id":"弄","hanzi":"弄","pinyin":"nòng","meaning_vi":"làm, nghịch, xử lý","explanation":"Động từ khẩu ngữ đa nghĩa (弄坏 - làm hỏng, 弄清楚 - làm rõ).","hsk_level":3,"tags":["dong-tu"],"image":"🔧","examples":[{"type":"basic","zh":"别把衣服弄脏了。","pinyin":"Bié bǎ yīfu nòngzāng le.","vi":"Đừng làm bẩn quần áo đấy."},{"type":"simple","zh":"我不小心把水杯碰倒了，把桌子上的文件全都弄湿了。","pinyin":"Wǒ bù xiǎoxīn bǎ shuǐbēi pèngdǎo le, bǎ zhuōzi shang de wénjiàn quándōu nòng shī le.","vi":"Tôi vô tình làm đổ cốc nước, làm ướt hết sạch tài liệu trên bàn."},{"type":"compound","zh":"遇到不明白的事情一定要先弄清楚原因，千万不要随便乱猜。","pinyin":"Yùdào bù míngbai de shìqing yídìngyào xiān nòng qīngchu yuányīn, qiānwàn bú yào suíbiàn luàn cāi.","vi":"Gặp chuyện chưa hiểu rõ nhất định phải làm rõ nguyên nhân trước, tuyệt đối đừng đoán bừa."}],"related":[{"hanzi":"做","pinyin":"zuò","vi":"Làm"},{"hanzi":"搞","pinyin":"gǎo","vi":"Làm/Xử lý"},{"hanzi":"脏","pinyin":"zāng","vi":"Bẩn"},{"hanzi":"坏","pinyin":"huài","vi":"Hỏng"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"}]},{"id":"暖气","hanzi":"暖气","pinyin":"nuǎnqì","meaning_vi":"hệ thống sưởi, hơi ấm","explanation":"暖 (ấm) + 气 (khí).","hsk_level":3,"tags":["danh-tu","nha-cua"],"image":"♨️","examples":[{"type":"basic","zh":"北京的冬天房间里有暖气。","pinyin":"Běijīng de dōngtiān fángjiān lǐ yǒu nuǎnqì.","vi":"Mùa đông ở Bắc Kinh trong phòng có hệ thống sưởi."},{"type":"simple","zh":"每年十一月中旬，北京的各个小区和学校就会开始供暖气。","pinyin":"Měinián Shíyīyuè zhōngxún, Běijīng de gège xiǎoqū hé xuéxiào jiù huì kāishǐ gōng nuǎnqì.","vi":"Vào trung tuần tháng 11 hằng năm, các khu dân cư và trường học ở Bắc Kinh sẽ bắt đầu cấp hơi sưởi."},{"type":"compound","zh":"因为房间里开着暖气非常干燥，所以我晚上睡觉前总要喝一杯温水。","pinyin":"Yīnwèi fángjiān lǐ kāizhe nuǎnqì fēicháng gānzào, suǒyǐ wǒ wǎnshang shuìjiào qián zǒngyào hē yì bēi wēn shuǐ.","vi":"Vì trong phòng bật lò sưởi rất khô hanh nên tối nào trước khi đi ngủ tôi cũng uống một cốc nước ấm."}],"related":[{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"Ấm áp"},{"hanzi":"空调","pinyin":"kōngtiáo","vi":"Điều hòa"},{"hanzi":"冬天","pinyin":"dōngtiān","vi":"Mùa đông"},{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"干燥","pinyin":"gānzào","vi":"Khô hanh"}],"traditional":"暖氣"},{"id":"偶尔","hanzi":"偶尔","pinyin":"ǒu'ěr","meaning_vi":"thỉnh thoảng, đôi khi","explanation":"偶 (ngẫu nhiên) + 尔. Tần suất thấp hơn 经常.","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"我偶尔去电影院看电影。","pinyin":"Wǒ ǒu'ěr qù diànyǐngyuàn kàndiànyǐng.","vi":"Thỉnh thoảng tôi đi rạp chiếu phim xem phim."},{"type":"simple","zh":"我平时一般都在家里自己做饭，只有周末偶尔去饭店换换口味。","pinyin":"Wǒ píngshí yìbān dōu zài jiālǐ zìjǐ zuòfàn, zhǐyǒu zhōumò ǒu'ěr qù fàndiàn huàn huan kǒuwèi.","vi":"Ngày thường tôi thường tự nấu cơm ở nhà, chỉ cuối tuần thỉnh thoảng ra nhà hàng đổi khẩu vị."},{"type":"compound","zh":"虽然他现在搬到另一个城市工作了，但是我们偶尔还是会打电话联系。","pinyin":"Suīrán tā xiànzài bān dào lìngyí ge chéngshì gōngzuò le, dànshì wǒmen ǒu'ěr háishi huì dǎdiànhuà liánxì.","vi":"Tuy bây giờ anh ấy đã chuyển sang thành phố khác làm việc nhưng thỉnh thoảng chúng tôi vẫn gọi điện liên lạc."}],"related":[{"hanzi":"有时","pinyin":"yǒushí","vi":"Có lúc"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"Luôn luôn"},{"hanzi":"平时","pinyin":"píngshí","vi":"Bình thường"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"Ngẫu nhiên"}],"traditional":"偶爾"},{"id":"排队","hanzi":"排队","pinyin":"páiduì","meaning_vi":"xếp hàng","explanation":"排 (sắp xếp) + 队 (đội ngũ). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🚶‍♂️","examples":[{"type":"basic","zh":"大家请按顺序排队。","pinyin":"Dàjiā qǐng àn shùnxù páiduì.","vi":"Mọi người xin hãy xếp hàng theo thứ tự."},{"type":"simple","zh":"这家有名的烤鸭店每天中午门口都有很多人在排队等座位。","pinyin":"Zhè jiā yǒumíng de kǎoyā diàn měitiān zhōngwǔ ménkǒu dōu yǒu hěn duō rén zài páiduì děng zuòwèi.","vi":"Quán vịt quay nổi tiếng này trưa nào trước cửa cũng có rất nhiều người xếp hàng đợi bàn."},{"type":"compound","zh":"在公共汽车站或者超市付款时自觉排队，是一个人有礼貌的表现。","pinyin":"Zài gōnggòng qìchēzhàn huòzhě chāoshì fùkuǎn shí zìjué páiduì, shì yígerén yǒulǐmào de biǎoxiàn.","vi":"Tự giác xếp hàng ở trạm xe buýt hoặc khi thanh toán ở siêu thị là biểu hiện của một người lịch sự."}],"related":[{"hanzi":"排列","pinyin":"páiliè","vi":"Sắp xếp"},{"hanzi":"安排","pinyin":"ānpái","vi":"Bố trí"},{"hanzi":"顺序","pinyin":"shùnxù","vi":"Thứ tự"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"},{"hanzi":"等","pinyin":"děng","vi":"Đợi"}],"traditional":"排隊"},{"id":"排列","hanzi":"排列","pinyin":"páiliè","meaning_vi":"sắp xếp, xếp đặt","explanation":"排 + 列 (hàng lối).","hsk_level":3,"tags":["dong-tu"],"image":"📊","examples":[{"type":"basic","zh":"书架上的书排列得很整齐。","pinyin":"Shūjià shang de shū páiliè de hěn zhěngqí.","vi":"Sách trên giá được sắp xếp rất ngăn nắp."},{"type":"simple","zh":"同学们按照从矮到高的顺序在操场上排列成了四排。","pinyin":"Tóngxuémen ànzhào cóng ǎi dào gāo de shùnxù zài cāochǎng shang páiliè chéngle sì pái.","vi":"Các bạn học xếp thành bốn hàng trên sân vận động theo thứ tự từ thấp đến cao."},{"type":"compound","zh":"这本汉语词典里的所有词语都是严格按照拼音字母顺序排列的。","pinyin":"Zhè běn Hànyǔ cídiǎn lǐ de suǒyǒu cíyǔ dōu shì yángé ànzhào pīnyīn zìmǔ shùnxù páiliè de.","vi":"Tất cả từ ngữ trong quyển từ điển tiếng Trung này đều được sắp xếp nghiêm ngặt theo thứ tự chữ cái Pinyin."}],"related":[{"hanzi":"排队","pinyin":"páiduì","vi":"Xếp hàng"},{"hanzi":"安排","pinyin":"ānpái","vi":"Sắp xếp"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Chỉnh lý"},{"hanzi":"顺序","pinyin":"shùnxù","vi":"Thứ tự"},{"hanzi":"整齐","pinyin":"zhěngqí","vi":"Ngăn nắp"}]},{"id":"判断","hanzi":"判断","pinyin":"pànduàn","meaning_vi":"phán đoán, đánh giá","explanation":"判 (phân xử) + 断 (quyết định). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"⚖️","examples":[{"type":"basic","zh":"你的判断完全正确。","pinyin":"Nǐ de pànduàn wánquán zhèngquè.","vi":"Phán đoán của bạn hoàn toàn chính xác."},{"type":"simple","zh":"我们不能只凭第一印象就轻易判断一个人的好坏。","pinyin":"Wǒmen bù néng zhǐ píng dìyīyìnxiàng jiù qīngyì pànduàn yígerén de hǎohuài.","vi":"Chúng ta không thể chỉ dựa vào ấn tượng đầu tiên mà dễ dàng đánh giá tốt xấu của một người."},{"type":"compound","zh":"在做阅读理解填空题时，我们要根据上下文的意思来判断应该填哪个词。","pinyin":"Zài zuò yuèdú lǐjiě tiánkòng tí shí, wǒmen yào gēnjù shàngxiàwén de yìsi lái pànduàn yīnggāi tián nǎ ge cí.","vi":"Khi làm bài tập điền từ đọc hiểu, chúng ta cần dựa vào ý nghĩa ngữ cảnh để phán đoán xem nên điền từ nào."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"认为","pinyin":"rènwéi","vi":"Cho rằng"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"Ấn tượng"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"猜","pinyin":"cāi","vi":"Đoán"}],"traditional":"判斷"},{"id":"陪","hanzi":"陪","pinyin":"péi","meaning_vi":"cùng, bầu bạn, tiếp (khách)","explanation":"Bộ phụ 阝+ 咅. Dùng trong 陪朋友 (đi cùng bạn).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"👫","examples":[{"type":"basic","zh":"周末我陪妈妈去逛街。","pinyin":"Zhōumò wǒ péi māma qù guàngjiē.","vi":"Cuối tuần tôi đi dạo phố cùng mẹ."},{"type":"simple","zh":"今天下午我陪刚来中国的越南同学去银行办了一张银行卡。","pinyin":"Jīntiān xiàwǔ wǒ péi gāng lái Zhōngguó de Yuènán tóngxué qù yínháng bànle yì zhāng yínhángkǎ.","vi":"Chiều nay tôi đã đi cùng bạn học Việt Nam mới sang Trung Quốc tới ngân hàng làm một chiếc thẻ ngân hàng."},{"type":"compound","zh":"虽然爸爸平时工作非常忙，但是每个星期天他都会尽量在家陪孩子玩。","pinyin":"Suīrán bàba píngshí gōngzuò fēicháng máng, dànshì měi ge Xīngqītiān tā dōuhuì jǐnliàng zài jiā péi háizi wán.","vi":"Tuy bình thường bố làm việc vô cùng bận nhưng Chủ nhật nào bố cũng cố gắng ở nhà chơi cùng con."}],"related":[{"hanzi":"跟","pinyin":"gēn","vi":"Cùng với"},{"hanzi":"一起","pinyin":"yìqǐ","vi":"Cùng nhau"},{"hanzi":"照顾","pinyin":"zhàogu","vi":"Chăm sóc"},{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"},{"hanzi":"家人","pinyin":"jiārén","vi":"Người nhà"}]},{"id":"皮肤","hanzi":"皮肤","pinyin":"pífū","meaning_vi":"da, làn da","explanation":"皮 (da) + 肤 (da thịt).","hsk_level":3,"tags":["danh-tu","co-the"],"image":"🧴","examples":[{"type":"basic","zh":"她的皮肤很白很光滑。","pinyin":"Tā de pífū hěn bái hěn guānghuá.","vi":"Làn da của cô ấy rất trắng và mịn màng."},{"type":"simple","zh":"夏天的太阳紫外线很强，出门前涂点防晒霜可以保护皮肤。","pinyin":"Xiàtiān de tàiyáng zǐwàixiàn hěn qiáng, chū ménqián tú diǎn fángshàishuāng kěyǐ bǎohù pífū.","vi":"Tia cực tím mặt trời mùa hè rất mạnh, thoa chút kem chống nắng trước khi ra ngoài có thể bảo vệ da."},{"type":"compound","zh":"每天多喝水、多吃新鲜水果和蔬菜，对保养皮肤和身体健康都非常有好处。","pinyin":"Měitiān duō hēshuǐ, duō chī xīnxiān shuǐguǒ hé shūcài, duì bǎoyǎng pífū hé shēntǐ jiànkāng dōu fēicháng yǒu hǎochu.","vi":"Mỗi ngày uống nhiều nước, ăn nhiều trái cây tươi và rau xanh rất có lợi cho việc dưỡng da và sức khỏe."}],"related":[{"hanzi":"橡皮","pinyin":"xiàngpí","vi":"Cục tẩy"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"Cơ thể"},{"hanzi":"干燥","pinyin":"gānzào","vi":"Khô hanh"},{"hanzi":"太阳","pinyin":"tàiyáng","vi":"Mặt trời"}],"traditional":"皮膚"},{"id":"脾气","hanzi":"脾气","pinyin":"píqi","meaning_vi":"tính khí, tính nết","explanation":"脾 (tỳ tạng) + 气 (khí chất).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"😤","examples":[{"type":"basic","zh":"他的脾气很好，从不生气。","pinyin":"Tā de píqi hěn hǎo, cóng bù shēngqì.","vi":"Tính nết của anh ấy rất tốt, chưa bao giờ nổi giận."},{"type":"simple","zh":"王老师性格温和、脾气很好，无论学生犯了什么错都会耐心教导。","pinyin":"Wáng lǎoshī xìnggé wēnhé, píqi hěn hǎo, wúlùn xuésheng fànle shénme cuò dōuhuì nàixīn jiàodǎo.","vi":"Thầy Vương tính tình ôn hòa, tính khí rất tốt, dù học sinh mắc lỗi gì cũng kiên nhẫn chỉ bảo."},{"type":"compound","zh":"遇到不顺心的事情时，我们要学会控制自己的脾气，冷静地和别人沟通。","pinyin":"Yùdào bú shùnxīn de shìqing shí, wǒmen yào xuéhuì kòngzhì zìjǐ de píqi, lěngjìng dehé biérén gōutōng.","vi":"Khi gặp chuyện không như ý, chúng ta phải học cách kiểm soát tính nóng nảy của mình và bình tĩnh trao đổi với người khác."}],"related":[{"hanzi":"性格","pinyin":"xìnggé","vi":"Tính cách"},{"hanzi":"生气","pinyin":"shēngqì","vi":"Tức giận"},{"hanzi":"耐心","pinyin":"nàixīn","vi":"Kiên nhẫn"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"Bình tĩnh"}],"traditional":"脾氣"},{"id":"篇","hanzi":"篇","pinyin":"piān","meaning_vi":"bài, thiên (lượng từ)","explanation":"Bộ trúc ⺮+ 扁. Lượng từ cho bài văn, bài báo (一篇文章).","hsk_level":3,"tags":["luong-tu","hoc-tap"],"image":"📃","examples":[{"type":"basic","zh":"我写完这篇文章了。","pinyin":"Wǒ xiěwán zhè piān wénzhāng le.","vi":"Tôi đã viết xong bài văn này rồi."},{"type":"simple","zh":"今天报纸上的那篇关于环境保护的文章写得非常深刻。","pinyin":"Jīntiān bàozhǐ shang de nà piān guānyú huánjìngbǎohù de wénzhāng xiě de fēicháng shēnkè.","vi":"Bài báo về bảo vệ môi trường trên tờ báo hôm nay viết vô cùng sâu sắc."},{"type":"compound","zh":"虽然这篇文章里有一些生词我不认识，但是读完以后我还是明白了主要意思。","pinyin":"Suīrán zhè piān wénzhāng lǐ yǒuyìxiē shēngcí wǒ bú rènshi, dànshì dú wán yǐhòu wǒ háishi míngbaile zhǔyào yìsi.","vi":"Tuy trong bài văn này có một số từ mới tôi không biết nhưng đọc xong tôi vẫn hiểu được ý chính."}],"related":[{"hanzi":"文章","pinyin":"wénzhāng","vi":"Bài văn"},{"hanzi":"页","pinyin":"yè","vi":"Trang"},{"hanzi":"本","pinyin":"běn","vi":"Quyển"},{"hanzi":"写","pinyin":"xiě","vi":"Viết"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"Đọc hiểu"}]},{"id":"骗","hanzi":"骗","pinyin":"piàn","meaning_vi":"lừa, lừa dối","explanation":"Bộ mã 马 + 扁.","hsk_level":3,"tags":["dong-tu"],"image":"🤥","examples":[{"type":"basic","zh":"他从来不骗人。","pinyin":"Tā cóngláibú piànrén.","vi":"Anh ấy chưa bao giờ lừa dối ai."},{"type":"simple","zh":"诚实守信是做人的基本原则，我们绝对不能撒谎骗人。","pinyin":"Chéngshí shǒuxìn shì zuòrén de jīběn yuánzé, wǒmen juéduì bù néng sāhuǎng piànrén.","vi":"Thành thật giữ chữ tín là nguyên tắc cơ bản của làm người, chúng ta tuyệt đối không được nói dối lừa người."},{"type":"compound","zh":"接到陌生电话要求转账时，一定要保持警惕，千万别被骗子骗了。","pinyin":"Jiēdào mòshēng diànhuà yāoqiú zhuǎnzhàng shí, yídìngyào bǎochí jǐngtì, qiānwàn bié bèi piànzi piàn le.","vi":"Khi nhận được cuộc gọi lạ yêu cầu chuyển khoản, nhất định phải cảnh giác, tuyệt đối đừng để kẻ lừa đảo lừa mất."}],"related":[{"hanzi":"诚实","pinyin":"chéngshí","vi":"Thành thật"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"假","pinyin":"jiǎ","vi":"Giả"},{"hanzi":"笑话","pinyin":"xiàohua","vi":"Truyện cười"}],"traditional":"騙"},{"id":"乒乓球","hanzi":"乒乓球","pinyin":"pīngpāngqiú","meaning_vi":"bóng bàn","explanation":"Từ tượng thanh tiếng bóng bàn nảy + 球 (quả bóng).","hsk_level":3,"tags":["danh-tu","the-thao"],"image":"🏓","examples":[{"type":"basic","zh":"中国人很喜欢打乒乓球。","pinyin":"Zhōngguórén hěn xǐhuan dǎ pīngpāngqiú.","vi":"Người Trung Quốc rất thích chơi bóng bàn."},{"type":"simple","zh":"乒乓球是中国的国球，很多学校和公园里都有乒乓球桌。","pinyin":"Pīngpāngqiú shì Zhōngguó de guó qiú, hěn duō xuéxiào hé gōngyuán lǐ dōu yǒu pīngpāngqiú zhuō.","vi":"Bóng bàn là quốc cầu của Trung Quốc, nhiều trường học và công viên đều có bàn bóng bàn."},{"type":"compound","zh":"虽然我刚开始学打乒乓球不久，但是每天下课后都跟同学一起练习。","pinyin":"Suīrán wǒ gāng kāishǐ xué dǎ pīngpāngqiú bùjiǔ, dànshì měitiān xiàkè hòu dōu gēn tóngxué yìqǐ liànxí.","vi":"Tuy tôi mới bắt đầu học chơi bóng bàn chưa lâu nhưng ngày nào tan học cũng luyện tập cùng bạn học."}],"related":[{"hanzi":"羽毛球","pinyin":"yǔmáoqiú","vi":"Cầu lông"},{"hanzi":"网球","pinyin":"wǎngqiú","vi":"Quần vợt"},{"hanzi":"打篮球","pinyin":"dǎlánqiú","vi":"Chơi bóng rổ"},{"hanzi":"踢足球","pinyin":"tīzúqiú","vi":"Đá bóng"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Thể thao"}]},{"id":"平时","hanzi":"平时","pinyin":"píngshí","meaning_vi":"bình thường, ngày thường","explanation":"平 (bình thường) + 时 (lúc).","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"他平时学习很努力。","pinyin":"Tā píngshí xuéxí hěn nǔlì.","vi":"Ngày thường cậu ấy học tập rất chăm chỉ."},{"type":"simple","zh":"我平时工作比较忙，只有周末才有时间陪家人去公园散步。","pinyin":"Wǒ píngshí gōngzuò bǐjiào máng, zhǐyǒu zhōumò cái yǒu shíjiān péi jiārén qù gōngyuán sànbù.","vi":"Ngày thường công việc của tôi tương đối bận, chỉ cuối tuần mới có thời gian đi dạo công viên cùng gia đình."},{"type":"compound","zh":"只要平时把基础知识学扎实，考试之前就不用熬夜临时抱佛脚了。","pinyin":"Zhǐyào píngshí bǎ jīchǔ zhīshi xué zhāshi, kǎoshì zhīqián jiù bú yòng áoyè línshí bàofójiǎo le.","vi":"Chỉ cần ngày thường học chắc kiến thức cơ bản thì trước kỳ thi sẽ không phải thức đêm học nhồi nhét nữa."}],"related":[{"hanzi":"水平","pinyin":"shuǐpíng","vi":"Trình độ"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"一般","pinyin":"yìbān","vi":"Bình thường"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"周末","pinyin":"zhōumò","vi":"Cuối tuần"}],"traditional":"平時"},{"id":"破","hanzi":"破","pinyin":"pò","meaning_vi":"rách, vỡ, hỏng","explanation":"Bộ thạch 石 + 皮.","hsk_level":3,"tags":["tinh-tu","dong-tu"],"image":"💔","examples":[{"type":"basic","zh":"这件旧衣服破了。","pinyin":"Zhè jiàn jiù yīfu pò le.","vi":"Chiếc áo cũ này bị rách rồi."},{"type":"simple","zh":"那个塑料袋装的东西太重，刚走到半路就突然破了。","pinyin":"Nà ge sùliàodài zhuāng de dōngxi tài zhòng, gāng zǒu dào bànlù jiù tūrán pò le.","vi":"Chiếc túi ni lông đó đựng đồ nặng quá, vừa đi được nửa đường đã đột nhiên bị rách."},{"type":"compound","zh":"虽然这双运动鞋已经穿破了，但是因为是爸爸送的礼物，他一直舍不得扔。","pinyin":"Suīrán zhè shuāng yùndòngxié yǐjīng chuānpò le, dànshì yīnwèi shì bàba sòng de lǐwù, tā yìzhí shěbude rēng.","vi":"Tuy đôi giày thể thao này đã đi rách rồi nhưng vì là quà bố tặng nên cậu ấy vẫn không nỡ vứt đi."}],"related":[{"hanzi":"坏","pinyin":"huài","vi":"Hỏng"},{"hanzi":"旧","pinyin":"jiù","vi":"Cũ"},{"hanzi":"扔","pinyin":"rēng","vi":"Vứt"},{"hanzi":"塑料袋","pinyin":"sùliàodài","vi":"Túi ni lông"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"}]},{"id":"普遍","hanzi":"普遍","pinyin":"pǔbiàn","meaning_vi":"phổ biến, rộng khắp","explanation":"普 (rộng) + 遍 (khắp nơi).","hsk_level":3,"tags":["tinh-tu"],"image":"🌐","examples":[{"type":"basic","zh":"这种现象很普遍。","pinyin":"Zhè zhǒng xiànxiàng hěn pǔbiàn.","vi":"Hiện tượng này rất phổ biến."},{"type":"simple","zh":"现在中国大城市里使用手机支付已经变得非常普遍了。","pinyin":"Xiànzài Zhōngguó Dàchéng shìlǐ shǐyòng shǒujī zhīfù yǐjīng biànde fēicháng pǔbiàn le.","vi":"Hiện nay ở các thành phố lớn của Trung Quốc, việc sử dụng thanh toán di động đã trở nên vô cùng phổ biến."},{"type":"compound","zh":"大家普遍认为，学习一门外语最好的方法就是多听、多说、多在生活中使用。","pinyin":"Dàjiā pǔbiàn rènwéi, xuéxí yì mén wàiyǔ zuìhǎo de fāngfǎ jiùshì duō tīng, duō shuō, duō zài shēnghuó zhōng shǐyòng.","vi":"Mọi người đều cho rằng phương pháp tốt nhất để học một ngoại ngữ là nghe nhiều, nói nhiều và sử dụng nhiều trong cuộc sống."}],"related":[{"hanzi":"普通话","pinyin":"pǔtōnghuà","vi":"Tiếng phổ thông"},{"hanzi":"遍","pinyin":"biàn","vi":"Khắp/Lượt"},{"hanzi":"流行","pinyin":"liúxíng","vi":"Thịnh hành"},{"hanzi":"一般","pinyin":"yìbān","vi":"Thông thường"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"Bình thường"}]},{"id":"普通话","hanzi":"普通话","pinyin":"pǔtōnghuà","meaning_vi":"tiếng phổ thông (Trung Quốc)","explanation":"普通 (phổ thông) + 话 (tiếng nói).","hsk_level":3,"tags":["danh-tu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"他的普通话说得很标准。","pinyin":"Tā de pǔtōng huàshuō de hěn biāozhǔn.","vi":"Tiếng phổ thông của anh ấy nói rất chuẩn."},{"type":"simple","zh":"普通话是中国的通用语言，学会普通话去中国哪里旅游都很方便。","pinyin":"Pǔtōnghuà shì Zhōngguó de tōngyòng yǔyán, xuéhuì pǔtōnghuà qù Zhōngguó nǎlǐ lǚyóu dōu hěn fāngbiàn.","vi":"Tiếng phổ thông là ngôn ngữ phổ biến của Trung Quốc, học tốt tiếng phổ thông thì đi du lịch bất cứ đâu ở Trung Quốc cũng rất tiện."},{"type":"compound","zh":"虽然中国各地有不同的方言，但是学校和电视台都统一使用标准普通话。","pinyin":"Suīrán Zhōngguó gèdì yǒu bùtóng de fāngyán, dànshì xuéxiào hé diànshìtái dōu tǒngyī shǐyòng biāozhǔn pǔtōnghuà.","vi":"Tuy các địa phương Trung Quốc có tiếng địa phương khác nhau nhưng trường học và đài truyền hình đều thống nhất dùng tiếng phổ thông chuẩn."}],"related":[{"hanzi":"汉语","pinyin":"Hànyǔ","vi":"Tiếng Hán"},{"hanzi":"中文","pinyin":"Zhōngwén","vi":"Tiếng Trung"},{"hanzi":"语言","pinyin":"yǔyán","vi":"Ngôn ngữ"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"流利","pinyin":"liúlì","vi":"Trôi chảy"}],"traditional":"普通話"},{"id":"其次","hanzi":"其次","pinyin":"qícì","meaning_vi":"tiếp theo, thứ hai là","explanation":"其 (đó) + 次 (thứ tự). Thường đi sau 首先 (trước tiên).","hsk_level":3,"tags":["lien-tu"],"image":"2️⃣","examples":[{"type":"basic","zh":"首先要有兴趣，其次要努力。","pinyin":"Shǒuxiān yàoyǒu xìngqù, qí cìyào nǔlì.","vi":"Trước tiên phải có hứng thú, tiếp theo là phải nỗ lực."},{"type":"simple","zh":"找工作的时候，我首先看重的是发展空间，其次才是工资高低。","pinyin":"Zhǎogōngzuò de shíhou, wǒ shǒuxiān kànzhòng de shì fāzhǎn kōngjiān, qícì cái shì gōngzī gāodī.","vi":"Khi tìm việc làm, điều đầu tiên tôi coi trọng là cơ hội phát triển, tiếp theo mới là mức lương cao thấp."},{"type":"compound","zh":"学好汉语首先要掌握正确的发音，其次要不断积累词汇和练习阅读。","pinyin":"Xuéhǎo Hànyǔ shǒuxiān yào zhǎngwò zhèngquè de fāyīn, qí cìyào búduàn jīlěi cíhuì hé liànxí yuèdú.","vi":"Học giỏi tiếng Trung trước tiên phải nắm vững phát âm chuẩn, tiếp theo phải không ngừng tích lũy từ vựng và luyện đọc."}],"related":[{"hanzi":"首先","pinyin":"shǒuxiān","vi":"Trước tiên"},{"hanzi":"其中","pinyin":"qízhōng","vi":"Trong đó"},{"hanzi":"其实","pinyin":"qíshí","vi":"Thực ra"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"顺序","pinyin":"shùnxù","vi":"Thứ tự"}]},{"id":"首先","hanzi":"首先","pinyin":"shǒuxiān","meaning_vi":"đầu tiên, trước tiên","explanation":"首 (đầu) + 先 (trước). Thường đi với 其次 hoặc 然后.","hsk_level":3,"tags":["pho-tu","lien-tu"],"image":"1️⃣","examples":[{"type":"basic","zh":"首先，欢迎大家的到来！","pinyin":"Shǒuxiān, huānyíng dàjiā de dàolái!","vi":"Đầu tiên, chào mừng sự có mặt của mọi người!"},{"type":"simple","zh":"每天早上来到办公室，我首先会把桌子整理干净，然后开始一天的工作。","pinyin":"Měitiān zǎoshang láidào bàngōngshì, wǒ shǒuxiān huì bǎ zhuōzi zhěnglǐ gānjìng, ránhòu kāishǐ yì tiān de gōngzuò.","vi":"Mỗi sáng đến văn phòng, việc đầu tiên tôi làm là dọn bàn sạch sẽ rồi mới bắt đầu công việc một ngày."},{"type":"compound","zh":"要想在比赛中取得好成绩，首先必须保持自信，其次要发挥出平时的水平。","pinyin":"Yào xiǎng zài bǐsài zhōng qǔdé hǎo chéngjì, shǒuxiān bìxū bǎochí zìxìn, qí cìyào fāhuī chū píngshí de shuǐpíng.","vi":"Muốn đạt thành tích tốt trong cuộc thi, trước tiên bắt buộc phải giữ tự tin, tiếp theo là phát huy được phong độ ngày thường."}],"related":[{"hanzi":"其次","pinyin":"qícì","vi":"Tiếp theo"},{"hanzi":"首都","pinyin":"shǒudū","vi":"Thủ đô"},{"hanzi":"先","pinyin":"xiān","vi":"Trước"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"开始","pinyin":"kāishǐ","vi":"Bắt đầu"}]},{"id":"其中","hanzi":"其中","pinyin":"qízhōng","meaning_vi":"trong đó, trong số đó","explanation":"其 (đó) + 中 (ở giữa).","hsk_level":3,"tags":["dai-tu"],"image":"🎯","examples":[{"type":"basic","zh":"这里有十本书，其中三本是我的。","pinyin":"Zhèlǐ yǒu shí běn shū, qízhōng sān běn shì wǒ de.","vi":"Ở đây có 10 quyển sách, trong đó 3 quyển là của tôi."},{"type":"simple","zh":"我们班一共有二十名学生，其中有一半来自亚洲国家。","pinyin":"Wǒmen bān yí gòngyǒu èrshí míng xuésheng, qízhōng yǒu yíbàn láizì Yàzhōu guójiā.","vi":"Lớp chúng tôi có tổng cộng 20 học sinh, trong số đó một nửa đến từ các nước châu Á."},{"type":"compound","zh":"昨天妈妈买了苹果、香蕉和葡萄等很多水果，其中我最喜欢吃红葡萄。","pinyin":"Zuótiān māma mǎile píngguǒ, xiāngjiāo hé pútao děng hěn duō shuǐguǒ, qízhōng wǒ zuì xǐhuan chī hóng pútao.","vi":"Hôm qua mẹ đã mua nhiều trái cây như táo, chuối và nho, trong đó tôi thích ăn nhất là nho đỏ."}],"related":[{"hanzi":"其次","pinyin":"qícì","vi":"Tiếp theo"},{"hanzi":"其实","pinyin":"qíshí","vi":"Thực ra"},{"hanzi":"中间","pinyin":"zhōngjiān","vi":"Ở giữa"},{"hanzi":"部分","pinyin":"bùfen","vi":"Bộ phận"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"}]},{"id":"起飞","hanzi":"起飞","pinyin":"qǐfēi","meaning_vi":"cất cánh (máy bay)","explanation":"起 (bay lên) + 飞 (bay).","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🛫","examples":[{"type":"basic","zh":"飞机马上就要起飞了。","pinyin":"Fēijī mǎshàng jiùyào qǐfēi le.","vi":"Máy bay sắp cất cánh ngay bây giờ rồi."},{"type":"simple","zh":"飞机起飞和降落的时候，乘客必须系好安全带并关闭手机。","pinyin":"Fēijī qǐfēi hé jiàngluò de shíhou, chéngkè bìxū jì hǎo ānquándài bìng guānbì shǒujī.","vi":"Lúc máy bay cất cánh và hạ cánh, hành khách bắt buộc phải thắt dây an toàn và tắt điện thoại."},{"type":"compound","zh":"因为今天北京机场有大雾，所以很多上午起飞的航班都不得不推迟了。","pinyin":"Yīnwèi jīntiān Běijīng jīchǎng yǒu dàwù, suǒyǐ hěn duō shàngwǔ qǐfēi de hángbān dōu bùdébù tuīchí le.","vi":"Vì hôm nay sân bay Bắc Kinh có sương mù dày đặc nên nhiều chuyến bay cất cánh buổi sáng đành phải hoãn lại."}],"related":[{"hanzi":"飞机","pinyin":"fēijī","vi":"Máy bay"},{"hanzi":"登机","pinyin":"dēngjī","vi":"Lên máy bay"},{"hanzi":"航班","pinyin":"hángbān","vi":"Chuyến bay"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"到达","pinyin":"dàodá","vi":"Đến nơi"}],"traditional":"起飛"},{"id":"起来","hanzi":"起来","pinyin":"qǐlái","meaning_vi":"đứng dậy, ngồi dậy; thức dậy; (bổ ngữ) lên, bắt đầu","explanation":"Động từ hoặc bổ ngữ xu hướng (站起来 - đứng dậy).","hsk_level":3,"tags":["dong-tu"],"image":"⬆️","examples":[{"type":"basic","zh":"请大家站起来。","pinyin":"Qǐng dàjiā zhànqǐlái.","vi":"Xin mời mọi người đứng dậy."},{"type":"simple","zh":"听到这个幽默的笑话，全班同学都忍不住大笑起来。","pinyin":"Tīngdào zhè ge yōumò de xiàohua, quánbān tóngxué dōu rěnbúzhù dàxiào qǐlái.","vi":"Nghe xong câu chuyện cười hài hước này, cả lớp đều không nhịn được bật cười lớn."},{"type":"compound","zh":"这件衣服虽然挂在店里看起来很普通，但是穿在身上却特别漂亮。","pinyin":"Zhè jiàn yīfu suīrán guà zài diàn lǐ kànqǐlái hěn pǔtōng, dànshì chuān zài shēnshang què tèbié piàoliang.","vi":"Chiếc áo này tuy treo trong tiệm trông rất bình thường nhưng mặc lên người lại đặc biệt đẹp."}],"related":[{"hanzi":"起床","pinyin":"qǐchuáng","vi":"Thức dậy"},{"hanzi":"起飞","pinyin":"qǐfēi","vi":"Cất cánh"},{"hanzi":"引起","pinyin":"yǐnqǐ","vi":"Gây ra"},{"hanzi":"站","pinyin":"zhàn","vi":"Đứng"},{"hanzi":"来","pinyin":"lái","vi":"Đến"}],"traditional":"起來"},{"id":"气候","hanzi":"气候","pinyin":"qìhòu","meaning_vi":"khí hậu","explanation":"气 (khí) + 候 (thời tiết).","hsk_level":3,"tags":["danh-tu","thoi-tiet"],"image":"🌤️","examples":[{"type":"basic","zh":"这里的气候很舒服。","pinyin":"Zhèlǐ de qìhòu hěn shūfu.","vi":"Khí hậu ở đây rất dễ chịu."},{"type":"simple","zh":"中国南方和北方的气候差别很大，南方湿润温暖，北方干燥寒冷。","pinyin":"Zhōngguó nánfāng hé běifāng de qìhòu chābié hěn dà, nánfāng shīrùn wēnnuǎn, běifāng gānzào hánlěng.","vi":"Khí hậu miền Nam và miền Bắc Trung Quốc khác biệt rất lớn, miền Nam ẩm ướt ấm áp, miền Bắc khô hanh lạnh giá."},{"type":"compound","zh":"刚来北京留学的时候，因为不适应这里干燥的气候，他经常流鼻血。","pinyin":"Gāng lái Běijīng liúxué de shíhou, yīnwèi bú shìyìng zhèlǐ gānzào de qìhòu, tā jīngcháng liúbíxuè.","vi":"Lúc mới đến Bắc Kinh du học, vì chưa thích nghi với khí hậu khô hanh ở đây nên cậu ấy hay bị chảy máu cam."}],"related":[{"hanzi":"天气","pinyin":"tiānqì","vi":"Thời tiết"},{"hanzi":"温度","pinyin":"wēndù","vi":"Nhiệt độ"},{"hanzi":"季节","pinyin":"jìjié","vi":"Mùa"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"适应","pinyin":"shìyìng","vi":"Thích nghi"}],"traditional":"氣候"},{"id":"千万","hanzi":"千万","pinyin":"qiānwàn","meaning_vi":"nhất định, tuyệt đối (phải/đừng)","explanation":"千 (nghìn) + 万 (vạn). Phó từ nhấn mạnh lời khuyên/cảnh báo.","hsk_level":3,"tags":["pho-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"出门千万别忘了带钥匙。","pinyin":"Chūmén qiānwàn bié wàngle dài yàoshi.","vi":"Ra khỏi nhà tuyệt đối đừng quên mang chìa khóa."},{"type":"simple","zh":"开车在高速公路上行驶时，千万不要超速，一定要注意交通安全。","pinyin":"Kāichē zài gāosùgōnglù shangxíng shǐ shí, qiānwàn bú yào chāosù, yídìngyào zhùyì jiāotōng ānquán.","vi":"Lái xe chạy trên đường cao tốc, tuyệt đối đừng chạy quá tốc độ, nhất định phải chú ý an toàn giao thông."},{"type":"compound","zh":"虽然这次考试成绩不太理想，但是你千万不要灰心，下次继续努力就行。","pinyin":"Suīrán zhè cì kǎoshì chéngjì bú tài lǐxiǎng, dànshì nǐ qiānwàn bú yào huīxīn, xiàcì jìxù nǔlì jiù xíng.","vi":"Tuy điểm thi lần này không được lý tưởng lắm nhưng bạn tuyệt đối đừng nản lòng, lần sau tiếp tục cố gắng là được."}],"related":[{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"必须","pinyin":"bìxū","vi":"Bắt buộc"},{"hanzi":"千","pinyin":"qiān","vi":"Nghìn"},{"hanzi":"别","pinyin":"bié","vi":"Đừng"},{"hanzi":"注意","pinyin":"zhùyì","vi":"Chú ý"}],"traditional":"千萬"},{"id":"签证","hanzi":"签证","pinyin":"qiānzhèng","meaning_vi":"thị thực, visa","explanation":"签 (ký) + 证 (chứng nhận).","hsk_level":3,"tags":["danh-tu","du-lich"],"image":"🛂","examples":[{"type":"basic","zh":"我已经办好中国签证了。","pinyin":"Wǒ yǐjīng bànhǎo Zhōngguó qiānzhèng le.","vi":"Tôi đã làm xong visa Trung Quốc rồi."},{"type":"simple","zh":"出国留学或者旅游之前，必须提前准备好护照和有效签证。","pinyin":"Chūguó liúxué huòzhě lǚyóu zhīqián, bìxū tíqián zhǔnbèihǎo hùzhào hé yǒuxiào qiānzhèng.","vi":"Trước khi đi du học hoặc du lịch nước ngoài, bắt buộc phải chuẩn bị trước hộ chiếu và thị thực còn hiệu lực."},{"type":"compound","zh":"因为下个月要去北京参加学术会议，所以我今天上午去大使馆申请签证了。","pinyin":"Yīnwèi xiàgeyuè yào qù Běijīng cānjiā xuéshù huìyì, suǒyǐ wǒ jīntiān shàngwǔ qù dàshǐguǎn shēnqǐng qiānzhèng le.","vi":"Vì tháng sau phải đi Bắc Kinh dự hội nghị học thuật nên sáng nay tôi đã đến đại sứ quán xin visa rồi."}],"related":[{"hanzi":"护照","pinyin":"hùzhào","vi":"Hộ chiếu"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"Chứng minh"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"Xin/Nộp đơn"},{"hanzi":"留学","pinyin":"liúxué","vi":"Du học"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"}],"traditional":"簽證"},{"id":"敲","hanzi":"敲","pinyin":"qiāo","meaning_vi":"gõ (cửa)","explanation":"高 + 攴. Cụm: 敲门 (gõ cửa).","hsk_level":3,"tags":["dong-tu"],"image":"🚪","examples":[{"type":"basic","zh":"有人在敲门。","pinyin":"Yǒurén zài qiāomén.","vi":"Có người đang gõ cửa."},{"type":"simple","zh":"进老师办公室或者别人房间以前，应该先礼貌地敲敲门。","pinyin":"Jìn lǎoshī bàngōngshì huòzhě biérén fángjiān yǐqián, yīnggāi xiān lǐmào de qiāo qiaomén.","vi":"Trước khi bước vào văn phòng thầy giáo hoặc phòng người khác, nên lịch sự gõ cửa trước."},{"type":"compound","zh":"刚才我在房间里戴着耳机听音乐，所以外面有人敲门我完全没听见。","pinyin":"Gāngcái wǒ zài fángjiān lǐ dàizhe ěrjī tīng yīnyuè, suǒyǐ wàimiàn yǒurén qiāomén wǒ wánquán méi tīngjiàn.","vi":"Vừa nãy tôi ở trong phòng đeo tai nghe nghe nhạc nên bên ngoài có người gõ cửa tôi hoàn toàn không nghe thấy."}],"related":[{"hanzi":"门","pinyin":"mén","vi":"Cửa"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"},{"hanzi":"打扰","pinyin":"dǎrǎo","vi":"Làm phiền"},{"hanzi":"进","pinyin":"jìn","vi":"Vào"},{"hanzi":"开","pinyin":"kāi","vi":"Mở"}]},{"id":"桥","hanzi":"桥","pinyin":"qiáo","meaning_vi":"cây cầu","explanation":"Bộ mộc 木 + 乔.","hsk_level":3,"tags":["danh-tu","dia-diem","giao-thong"],"image":"🌉","examples":[{"type":"basic","zh":"河上有一座石桥。","pinyin":"Hé shang yǒu yí zuò shí qiáo.","vi":"Trên sông có một cây cầu đá."},{"type":"simple","zh":"北京的卢沟桥历史非常悠久，每天都有很多游客去那里参观。","pinyin":"Běijīng de Lúgōuqiáo lìshǐ fēicháng yōujiǔ, měitiān dōu yǒu hěn duō yóukè qù nàlǐ cānguān.","vi":"Cầu Lư Câu ở Bắc Kinh có lịch sử vô cùng lâu đời, ngày nào cũng có nhiều du khách đến đó tham quan."},{"type":"compound","zh":"这座新建的跨海大桥不仅方便了人们的交通，还成了城市的一道美丽风景。","pinyin":"Zhè zuò xīnjiàn de kuà hǎi Dàqiáo bùjǐn fāngbiànle rénmen de jiāotōng, hái chéngle chéngshì de yídào měilì fēngjǐng.","vi":"Cây cầu vượt biển mới xây này không những giúp việc đi lại của người dân thuận tiện mà còn trở thành một cảnh đẹp của thành phố."}],"related":[{"hanzi":"河","pinyin":"hé","vi":"Sông"},{"hanzi":"海","pinyin":"hǎi","vi":"Biển"},{"hanzi":"座","pinyin":"zuò","vi":"Tòa/Cây (lượng từ)"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"Giao thông"},{"hanzi":"路","pinyin":"lù","vi":"Con đường"}],"traditional":"橋"},{"id":"巧克力","hanzi":"巧克力","pinyin":"qiǎokèlì","meaning_vi":"sô cô la","explanation":"Từ phiên âm tiếng Anh 'chocolate'.","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍫","examples":[{"type":"basic","zh":"妹妹喜欢吃巧克力。","pinyin":"Mèimei xǐhuan chī qiǎokèlì.","vi":"Em gái thích ăn sô cô la."},{"type":"simple","zh":"情人节的时候，很多年轻人都会买一盒精美的巧克力送给爱人。","pinyin":"Qíngrénjié de shíhou, hěn duō niánqīngrén dōuhuì mǎi yì hé jīngměi de qiǎokèlì sònggěi àirén.","vi":"Vào ngày lễ Tình nhân, nhiều bạn trẻ đều mua một hộp sô cô la tinh tế tặng cho người yêu."},{"type":"compound","zh":"虽然黑巧克力味道有点儿苦，但是它比牛奶巧克力更健康、不容易让人发胖。","pinyin":"Suīrán hēi qiǎokèlì wèidào yǒudiǎnr kǔ, dànshì tā bǐ niúnǎi qiǎokèlì gèng jiànkāng, bù róngyì ràng rén fāpàng.","vi":"Tuy sô cô la đen vị hơi đắng một chút nhưng nó lành mạnh hơn sô cô la sữa và không dễ làm người ta béo lên."}],"related":[{"hanzi":"糖","pinyin":"táng","vi":"Đường/Kẹo"},{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng"},{"hanzi":"蛋糕","pinyin":"dàngāo","vi":"Bánh kem"},{"hanzi":"礼物","pinyin":"lǐwù","vi":"Quà tặng"}]},{"id":"亲戚","hanzi":"亲戚","pinyin":"qīnqi","meaning_vi":"họ hàng, người thân","explanation":"亲 (thân) + 戚 (họ hàng).","hsk_level":3,"tags":["danh-tu","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"春节我们要去拜访亲戚。","pinyin":"Chūnjié wǒmen yào qù bàifǎng qīnqi.","vi":"Dịp Tết chúng tôi phải đi thăm hỏi họ hàng."},{"type":"simple","zh":"每年过年的时候，爸爸妈妈都会带着我和弟弟回老家看望亲戚。","pinyin":"Měinián guònián de shíhou, bàba māma dōuhuì dàizhe wǒ hé dìdi huílǎojiā kànwàng qīnqi.","vi":"Mỗi năm dịp Tết, bố mẹ đều dẫn tôi và em trai về quê thăm hỏi họ hàng."},{"type":"compound","zh":"虽然平时大家各自在不同的城市忙工作，但是一到节日亲戚们就会聚在一起。","pinyin":"Suīrán píngshí dàjiā gèzì zài bùtóng de chéngshì máng gōngzuò, dànshì yí dào jiérì qīnqimen jiù huì jù zài yìqǐ.","vi":"Tuy ngày thường mỗi người bận rộn công việc ở một thành phố khác nhau nhưng hễ đến ngày lễ là họ hàng lại tụ họp bên nhau."}],"related":[{"hanzi":"母亲","pinyin":"mǔqīn","vi":"Mẹ"},{"hanzi":"父亲","pinyin":"fùqīn","vi":"Cha"},{"hanzi":"家人","pinyin":"jiārén","vi":"Người nhà"},{"hanzi":"阿姨","pinyin":"āyí","vi":"Dì/Cô"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"}],"traditional":"親戚"},{"id":"轻","hanzi":"轻","pinyin":"qīng","meaning_vi":"nhẹ","explanation":"Bộ xa 车 + 圣. Đối nghĩa với 重 (nặng).","hsk_level":3,"tags":["tinh-tu"],"image":"🪶","examples":[{"type":"basic","zh":"这个箱子很轻。","pinyin":"Zhè ge xiāngzi hěn qīng.","vi":"Cái thùng này rất nhẹ."},{"type":"simple","zh":"这台新买的笔记本电脑非常轻薄，每天背在书包里一点儿也不累。","pinyin":"Zhè tái xīn mǎi de bǐjìběn diànnǎo fēicháng qīngbáo, měitiān bēi zài shūbāo lǐ yìdiǎnr yě bú lèi.","vi":"Chiếc máy tính xách tay mới mua này vô cùng mỏng nhẹ, ngày nào đeo trong cặp sách cũng chẳng mệt chút nào."},{"type":"compound","zh":"图书馆里大家都在安静地看书，你走路的时候脚步要放轻一点儿。","pinyin":"Túshūguǎn lǐ dàjiā dōu zài ānjìng de kànshū, nǐ zǒulù de shíhou jiǎobù yào fàng qīng yìdiǎnr.","vi":"Trong thư viện mọi người đều đang yên lặng đọc sách, lúc đi lại bạn hãy bước nhẹ chân một chút."}],"related":[{"hanzi":"重","pinyin":"zhòng","vi":"Nặng"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"Nhẹ nhàng"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"Trẻ tuổi"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"}],"traditional":"輕"},{"id":"重","hanzi":"重","pinyin":"zhòng","meaning_vi":"nặng; nặng nề, nghiêm trọng","explanation":"Đối nghĩa với 轻 (nhẹ).","hsk_level":3,"tags":["tinh-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"这个行李箱太重了。","pinyin":"Zhè ge xínglixiāng tài zhòng le.","vi":"Chiếc vali hành lý này nặng quá."},{"type":"simple","zh":"箱子里装满了书和厚衣服，非常重，我一个人根本搬不动。","pinyin":"Xiāngzi lǐ zhuāngmǎnle shū hé hòu yīfu, fēicháng zhòng, wǒ yígerén gēnběn bān búdòng.","vi":"Trong thùng đựng đầy sách vở và quần áo dày, rất nặng, một mình tôi hoàn toàn không bê nổi."},{"type":"compound","zh":"虽然学习工作任务很重，但是只要合理安排时间，就能顺利完成。","pinyin":"Suīrán xuéxí gōngzuò rènwu hěn zhòng, dànshì zhǐyào hélǐ ānpái shíjiān, jiù néng shùnlì wánchéng.","vi":"Tuy nhiệm vụ học tập và công việc rất nặng nề nhưng chỉ cần sắp xếp thời gian hợp lý thì sẽ hoàn thành suôn sẻ."}],"related":[{"hanzi":"轻","pinyin":"qīng","vi":"Nhẹ"},{"hanzi":"重要","pinyin":"zhòngyào","vi":"Quan trọng"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"Trọng điểm"},{"hanzi":"严重","pinyin":"yánzhòng","vi":"Nghiêm trọng"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"}]},{"id":"轻松","hanzi":"轻松","pinyin":"qīngsōng","meaning_vi":"nhẹ nhàng, thư thái","explanation":"轻 (nhẹ) + 松 (thoải mái).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"考完试以后我感觉很轻松。","pinyin":"Kǎowán shì yǐhòu wǒ gǎnjué hěn qīngsōng.","vi":"Thi xong rồi tôi cảm thấy rất nhẹ nhõm."},{"type":"simple","zh":"王老师的课气氛非常轻松愉快，同学们在笑声中学到了很多知识。","pinyin":"Wáng lǎoshī de kè qìfēn fēicháng qīngsōng yúkuài, tóngxuémen zài xiàoshēng zhōng xuédàole hěn duō zhīshi.","vi":"Không khí tiết học của thầy Vương vô cùng nhẹ nhàng vui vẻ, các bạn học tiếp thu được nhiều kiến thức trong tiếng cười."},{"type":"compound","zh":"虽然这件事情表面上看起来很轻松，但是真正做起来其实需要很多耐心。","pinyin":"Suīrán zhè jiàn shìqing biǎomiànshang kànqǐlái hěn qīngsōng, dànshì zhēnzhèng zuò qǐlái qíshí xūyào hěn duō nàixīn.","vi":"Tuy việc này bề ngoài trông có vẻ rất nhẹ nhàng nhưng khi bắt tay vào làm thực sự lại cần rất nhiều kiên nhẫn."}],"related":[{"hanzi":"轻","pinyin":"qīng","vi":"Nhẹ"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"Thư giãn"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"Căng thẳng"},{"hanzi":"压力","pinyin":"yālì","vi":"Áp lực"},{"hanzi":"愉快","pinyin":"yúkuài","vi":"Vui vẻ"}],"traditional":"輕鬆"},{"id":"情况","hanzi":"情况","pinyin":"qíngkuàng","meaning_vi":"tình hình, tình huống","explanation":"情 (tình) + 况 (trạng thái).","hsk_level":3,"tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"请你介绍一下具体情况。","pinyin":"Qǐng nǐ jièshào yíxià jùtǐ qíngkuàng.","vi":"Xin bạn giới thiệu một chút về tình hình cụ thể."},{"type":"simple","zh":"医生仔细询问了病人的身体情况以后，才给他开了感冒药。","pinyin":"Yīshēng zǐxì xúnwènle bìngrén de shēntǐ qíngkuàng yǐhòu, cái gěi tā kāile gǎnmàoyào.","vi":"Sau khi hỏi kỹ tình trạng sức khỏe của bệnh nhân, bác sĩ mới kê thuốc cảm cúm cho anh ấy."},{"type":"compound","zh":"正常情况下，我们每天下午五点半下班，遇到特殊情况才会加班。","pinyin":"Zhèngcháng qíngkuàng xià, wǒmen měitiān xiàwǔ wǔ diǎn bàn xiàbān, yùdào tèshū qíngkuàng cái huì jiābān.","vi":"Trong tình huống bình thường, mỗi chiều 5 giờ rưỡi chúng tôi tan làm, gặp tình huống đặc biệt mới tăng ca."}],"related":[{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"Đồng cảm"},{"hanzi":"发生","pinyin":"fāshēng","vi":"Xảy ra"},{"hanzi":"了解","pinyin":"liǎojiě","vi":"Tìm hiểu"}],"traditional":"情況"},{"id":"穷","hanzi":"穷","pinyin":"qióng","meaning_vi":"nghèo","explanation":"Bộ huyệt 穴 + 力. Đối nghĩa với 富 (giàu).","hsk_level":3,"tags":["tinh-tu"],"image":"💸","examples":[{"type":"basic","zh":"他虽然穷，但是很善良。","pinyin":"Tā suīrán qióng, dànshì hěn shànliáng.","vi":"Anh ấy tuy nghèo nhưng rất lương thiện."},{"type":"simple","zh":"以前这个山村非常穷，现在通过发展旅游业，村民们都富起来了。","pinyin":"Yǐqián zhè ge shāncūn fēicháng qióng, xiànzài tōngguò fāzhǎn lǚyóuyè, cūnmínmen dōu fù qǐlái le.","vi":"Trước đây ngôi làng miền núi này rất nghèo, hiện nay nhờ phát triển du lịch, người dân đều đã giàu lên rồi."},{"type":"compound","zh":"只要我们有双手和智慧，不怕吃苦努力工作，就一定能改变贫穷的生活。","pinyin":"Zhǐyào wǒmen yǒu shuāngshǒu hé zhìhuì, bú pà chīkǔ nǔlì gōngzuò, jiù yídìng néng gǎibiàn pínqióng de shēnghuó.","vi":"Chỉ cần chúng ta có đôi tay và trí tuệ, không ngại gian khổ chăm chỉ làm việc thì nhất định sẽ thay đổi được cuộc sống nghèo khó."}],"related":[{"hanzi":"富","pinyin":"fù","vi":"Giàu có"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"改变","pinyin":"gǎibiàn","vi":"Thay đổi"}],"traditional":"窮"},{"id":"富","hanzi":"富","pinyin":"fù","meaning_vi":"giàu, giàu có","explanation":"Bộ miên 宀 + 畐. Đối nghĩa với 穷 (nghèo).","hsk_level":3,"tags":["tinh-tu"],"image":"💎","examples":[{"type":"basic","zh":"这个国家很富。","pinyin":"Zhè ge guójiā hěn fù.","vi":"Đất nước này rất giàu có."},{"type":"simple","zh":"经过几十年的改革开放，越来越多的中国家庭过上了富裕的生活。","pinyin":"Jīngguò jǐ shí nián de gǎigékāifàng, yuèláiyuè duō de Zhōngguó jiātíngguò shàngle fùyù de shēnghuó.","vi":"Trải qua mấy chục năm cải cách mở cửa, ngày càng có nhiều gia đình Trung Quốc có cuộc sống giàu có sung túc."},{"type":"compound","zh":"真正的富有不仅是物质上的充足，更重要的是精神和知识上的丰富。","pinyin":"Zhēnzhèng de fùyǒu bùjǐn shì wùzhì shang de chōngzú, gèng zhòngyào de shì jīngshén hé zhīshi shang de fēngfù.","vi":"Sự giàu có thực sự không chỉ là đầy đủ về vật chất mà quan trọng hơn là sự phong phú về tinh thần và tri thức."}],"related":[{"hanzi":"穷","pinyin":"qióng","vi":"Nghèo"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"Phong phú"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"经济","pinyin":"jīngjì","vi":"Kinh tế"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"}]},{"id":"区别","hanzi":"区别","pinyin":"qūbié","meaning_vi":"sự khác biệt, phân biệt","explanation":"区 (phân chia) + 别 (khác). Vừa là danh từ vừa là động từ.","hsk_level":3,"tags":["danh-tu","dong-tu"],"image":"🔀","examples":[{"type":"basic","zh":"这两个词有什么区别？","pinyin":"Zhè liǎng ge cí yǒu shénme qūbié?","vi":"Hai từ này có sự khác biệt gì?"},{"type":"simple","zh":"很多外国学生分不清楚“认识”和“知道”这两个动词在使用上的区别。","pinyin":"Hěn duō wài guóxué shengfēn bù qīngchu “rènshi” hé “zhīdao” zhè liǎng ge dòngcí zài shǐyòng shang de qūbié.","vi":"Nhiều học sinh nước ngoài không phân biệt rõ sự khác nhau về cách dùng giữa hai động từ “认识” và “知道”."},{"type":"compound","zh":"虽然双胞胎姐妹长得很像，但是只要仔细观察，还是能看出她们之间的区别。","pinyin":"Suīrán shuāngbāotāi jiěmèi zhǎngde hěn xiàng, dànshì zhǐyào zǐxì guānchá, háishi néng kànchū tāmen zhījiān de qūbié.","vi":"Tuy hai chị em sinh đôi trông rất giống nhau nhưng chỉ cần quan sát kỹ thì vẫn nhận ra sự khác biệt giữa họ."}],"related":[{"hanzi":"不同","pinyin":"bùtóng","vi":"Khác nhau"},{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Giống nhau"},{"hanzi":"特别","pinyin":"tèbié","vi":"Đặc biệt"},{"hanzi":"郊区","pinyin":"jiāoqū","vi":"Ngoại ô"},{"hanzi":"比较","pinyin":"bǐjiào","vi":"So sánh"}],"traditional":"區別"},{"id":"取","hanzi":"取","pinyin":"qǔ","meaning_vi":"lấy, rút (tiền)","explanation":"耳 + 又. Dùng trong 取钱 (rút tiền), 取快递 (lấy hàng chuyển phát).","hsk_level":3,"tags":["dong-tu"],"image":"🏧","examples":[{"type":"basic","zh":"我去银行取钱。","pinyin":"Wǒqù yínháng qǔqián.","vi":"Tôi đi ngân hàng rút tiền."},{"type":"simple","zh":"下班回家的路上，我顺便去小区门口的快递站取了我的包裹。","pinyin":"Xiàbān huíjiā de lùshang, wǒ shùnbiàn qù xiǎoqū ménkǒu de kuàidì zhàn qǔle wǒ de bāoguǒ.","vi":"Trên đường tan làm về nhà, tôi tiện thể ghé trạm chuyển phát nhanh cổng khu chung cư lấy bưu kiện của mình."},{"type":"compound","zh":"去自动取款机取钱的时候，一定要注意周围环境安全，保护好自己的密码。","pinyin":"Qù zìdòng qǔkuǎnjī qǔqián de shíhou, yídìngyào zhùyì zhōuwéi huánjìng ānquán, bǎohù hǎo zìjǐ de mìmǎ.","vi":"Khi đi rút tiền ở cây ATM, nhất định phải chú ý an toàn xung quanh và bảo mật kỹ mật khẩu của mình."}],"related":[{"hanzi":"存","pinyin":"cún","vi":"Gửi (tiền)"},{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"},{"hanzi":"现金","pinyin":"xiànjīn","vi":"Tiền mặt"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm/Lấy"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"Mật khẩu"}]},{"id":"全部","hanzi":"全部","pinyin":"quánbù","meaning_vi":"toàn bộ, tất cả","explanation":"全 (đầy đủ) + 部 (phần).","hsk_level":3,"tags":["danh-tu","pho-tu"],"image":"🌐","examples":[{"type":"basic","zh":"我全部都明白了。","pinyin":"Wǒ quánbù dōu míngbai le.","vi":"Tôi đã hiểu hết toàn bộ rồi."},{"type":"simple","zh":"今天的汉语作业不多，我只用了半个小时就全部做完了。","pinyin":"Jīntiān de Hànyǔ zuòyè bù duō, wǒ zhǐ yòngle bàn ge xiǎoshí jiù quánbù zuò wánle.","vi":"Bài tập tiếng Trung hôm nay không nhiều, tôi chỉ mất nửa tiếng là làm xong toàn bộ."},{"type":"compound","zh":"因为明天要搬新家，所以全家人今天把家具和行李全部打包好了。","pinyin":"Yīnwèi míngtiān yào bān xīn jiā, suǒyǐ quán jiārén jīntiān bǎ jiājù hé xíngli quánbù dǎbāo hǎo le.","vi":"Vì ngày mai phải chuyển sang nhà mới nên hôm nay cả nhà đã đóng gói xong toàn bộ đồ đạc và hành lý."}],"related":[{"hanzi":"所有","pinyin":"suǒyǒu","vi":"Tất cả"},{"hanzi":"部分","pinyin":"bùfen","vi":"Bộ phận"},{"hanzi":"完全","pinyin":"wánquán","vi":"Hoàn toàn"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"都","pinyin":"dōu","vi":"Đều"}]},{"id":"缺点","hanzi":"缺点","pinyin":"quēdiǎn","meaning_vi":"khuyết điểm, nhược điểm","explanation":"缺 (thiếu) + 点 (điểm). Đối nghĩa với 优点 (ưu điểm).","hsk_level":3,"tags":["danh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"每个人都有缺点。","pinyin":"Měigerén dōu yǒu quēdiǎn.","vi":"Mỗi người đều có khuyết điểm."},{"type":"simple","zh":"他做事情非常认真，唯一的缺点就是有时候太粗心，容易忘带东西。","pinyin":"Tā zuò shìqing fēicháng rènzhēn, wéiyī de quēdiǎn jiùshì yǒushíhou tài cūxīn, róngyì wàng dài dōngxi.","vi":"Anh ấy làm việc vô cùng nghiêm túc, khuyết điểm duy nhất là đôi khi hơi bất cẩn, dễ quên mang đồ."},{"type":"compound","zh":"我们不仅要看到自己的优点，更要勇敢地面对并改正自己的缺点。","pinyin":"Wǒmen bùjǐn yào kàndào zìjǐ de yōudiǎn, gèng yào yǒnggǎn de miànduì bìng gǎizhèng zìjǐ de quēdiǎn.","vi":"Chúng ta không chỉ cần nhìn thấy ưu điểm của bản thân mà còn phải dũng cảm đối mặt và sửa chữa khuyết điểm của mình."}],"related":[{"hanzi":"优点","pinyin":"yōudiǎn","vi":"Ưu điểm"},{"hanzi":"特点","pinyin":"tèdiǎn","vi":"Đặc điểm"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"Trọng điểm"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"}],"traditional":"缺點"},{"id":"优点","hanzi":"优点","pinyin":"yōudiǎn","meaning_vi":"ưu điểm, điểm mạnh","explanation":"优 (tốt/giỏi) + 点 (điểm). Đối nghĩa với 缺点 (khuyết điểm).","hsk_level":3,"tags":["danh-tu"],"image":"⭐","examples":[{"type":"basic","zh":"他有很多优点。","pinyin":"Tā yǒu hěn duō yōudiǎn.","vi":"Anh ấy có rất nhiều ưu điểm."},{"type":"simple","zh":"小李最大的优点就是性格热情开朗，无论遇到什么困难都很乐观。","pinyin":"Xiǎo Lǐ zuì dà de yōudiǎn jiùshì xìnggé rèqíng kāilǎng, wúlùn yùdào shénme kùnnan dōu hěn lèguān.","vi":"Ưu điểm lớn nhất của Tiểu Lý chính là tính cách nhiệt tình cởi mở, bất kể gặp khó khăn gì cũng rất lạc quan."},{"type":"compound","zh":"在团队合作中，如果每个人都能发挥自己的优点，工作效率就会大大提高。","pinyin":"Zài tuánduì hézuò zhōng, rúguǒ měigerén dōu néng fāhuī zìjǐ de yōudiǎn, gōngzuò xiàolǜ jiù huì dàdà tígāo.","vi":"Trong làm việc nhóm, nếu mỗi người đều phát huy được ưu điểm của mình thì hiệu suất công việc sẽ tăng lên đáng kể."}],"related":[{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"Khuyết điểm"},{"hanzi":"优秀","pinyin":"yōuxiù","vi":"Xuất sắc"},{"hanzi":"特点","pinyin":"tèdiǎn","vi":"Đặc điểm"},{"hanzi":"合作","pinyin":"hézuò","vi":"Hợp tác"},{"hanzi":"能力","pinyin":"nénglì","vi":"Năng lực"}],"traditional":"優點"},{"id":"却","hanzi":"却","pinyin":"què","meaning_vi":"lại, nhưng lại","explanation":"Phó từ biểu thị sự chuyển ngoặt, đứng sau chủ ngữ.","hsk_level":3,"tags":["pho-tu"],"image":"↩️","examples":[{"type":"basic","zh":"他虽然很忙，却每天坚持运动。","pinyin":"Tā suīrán hěn máng, què měitiān jiānchí yùndòng.","vi":"Anh ấy tuy rất bận nhưng ngày nào cũng kiên trì vận động."},{"type":"simple","zh":"这道菜看起来很普通，吃起来味道却非常鲜美，让人回味无穷。","pinyin":"Zhè dào cài kànqǐlái hěn pǔtōng, chī qǐlái wèidào què fēicháng xiānměi, ràng rén huíwèiwúqióng.","vi":"Món ăn này trông rất bình thường nhưng ăn vào hương vị lại vô cùng tươi ngon, khiến người ta nhớ mãi không quên."},{"type":"compound","zh":"虽然外面下着鹅毛大雪，但是房间里因为开着暖气，却显得非常温暖。","pinyin":"Suīrán wàimiàn xiàzhe émáo Dàxuě, dànshì fángjiān lǐ yīnwèi kāizhe nuǎnqì, què xiǎnde fēicháng wēnnuǎn.","vi":"Tuy bên ngoài đang có tuyết rơi dày đặc nhưng trong phòng vì bật hệ thống sưởi nên lại vô cùng ấm áp."}],"related":[{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"然而","pinyin":"rán'ér","vi":"Tuy nhiên"},{"hanzi":"虽然","pinyin":"suīrán","vi":"Tuy rằng"},{"hanzi":"可是","pinyin":"kěshì","vi":"Nhưng mà"},{"hanzi":"不过","pinyin":"búguò","vi":"Tuy nhiên"}],"traditional":"卻"},{"id":"确实","hanzi":"确实","pinyin":"quèshí","meaning_vi":"quả thực, đúng là","explanation":"确 (chắc chắn) + 实 (thực tế).","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"✔️","examples":[{"type":"basic","zh":"这个办法确实很有效。","pinyin":"Zhè ge bànfǎ quèshí hěn yǒuxiào.","vi":"Cách này quả thực rất hiệu quả."},{"type":"simple","zh":"今天北京的风确实很大，出门的时候吹得人眼睛都睁不开。","pinyin":"Jīntiān Běijīng de fēng quèshí hěn dà, chūmén de shíhou chuī de rén yǎnjing dōu zhēng bù kāi.","vi":"Hôm nay gió ở Bắc Kinh quả thực rất to, lúc ra ngoài gió thổi khiến người ta không mở nổi mắt."},{"type":"compound","zh":"虽然学习汉语初期确实会遇到很多困难，但是坚持下来以后就会觉得越来越有趣。","pinyin":"Suīrán xuéxí Hànyǔ chūqī quèshí huì yùdào hěn duō kùnnan, dànshì jiānchí xiàlái yǐhòu jiù huì juéde yuèláiyuè yǒuqù.","vi":"Tuy giai đoạn đầu học tiếng Trung quả thực sẽ gặp nhiều khó khăn nhưng kiên trì vượt qua rồi sẽ thấy ngày càng thú vị."}],"related":[{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"实际","pinyin":"shíjì","vi":"Thực tế"},{"hanzi":"实在","pinyin":"shízài","vi":"Thật sự"},{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"Khẳng định"}],"traditional":"確實"},{"id":"然而","hanzi":"然而","pinyin":"rán'ér","meaning_vi":"tuy nhiên, nhưng mà","explanation":"Liên từ chuyển ngoặt dùng nhiều trong văn viết.","hsk_level":3,"tags":["lien-tu"],"image":"↩️","examples":[{"type":"basic","zh":"他很努力，然而结果并不理想。","pinyin":"Tā hěn nǔlì, rán'ér jiéguǒ bìngbù lǐxiǎng.","vi":"Anh ấy rất nỗ lực, tuy nhiên kết quả không được lý tưởng."},{"type":"simple","zh":"很多人以为学好外语只需要背单词，然而多听多说才是关键。","pinyin":"Hěn duō rén yǐwéi xuéhǎo wàiyǔ zhǐ xūyào bèi dāncí, rán'ér duō tīng duō shuō cái shì guānjiàn.","vi":"Nhiều người cứ tưởng học giỏi ngoại ngữ chỉ cần học thuộc từ mới, tuy nhiên nghe nhiều nói nhiều mới là mấu chốt."},{"type":"compound","zh":"虽然这家店的位置非常偏僻，然而因为菜做得地道，每天依然座无虚席。","pinyin":"Suīrán zhè jiā diàn de wèizhi fēicháng piānpì, rán'ér yīnwèi cài zuò de dìdao, měitiān yīrán zuòwúxūxí.","vi":"Tuy vị trí quán này rất hẻo lánh, tuy nhiên vì món ăn nấu chuẩn vị nên ngày nào cũng kín chỗ."}],"related":[{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"却","pinyin":"què","vi":"Lại"},{"hanzi":"仍然","pinyin":"réngrán","vi":"Vẫn"},{"hanzi":"突然","pinyin":"tūrán","vi":"Đột nhiên"},{"hanzi":"不过","pinyin":"búguò","vi":"Tuy nhiên"}]},{"id":"任何","hanzi":"任何","pinyin":"rènhé","meaning_vi":"bất kỳ, bất cứ","explanation":"任 (tùy ý) + 何 (nào).","hsk_level":3,"tags":["dai-tu"],"image":"🔄","examples":[{"type":"basic","zh":"任何人都应该遵守法律。","pinyin":"Rènhé rén dōu yīnggāi zūnshǒu fǎlǜ.","vi":"Bất kỳ ai cũng đều phải tuân thủ pháp luật."},{"type":"simple","zh":"不管遇到任何困难，我们都要保持冷静，勇敢地去面对和解决。","pinyin":"Bùguǎn yùdào rènhé kùnnan, wǒmen dōu yào bǎochí lěngjìng, yǒnggǎn de qù miànduì hé jiějué.","vi":"Bất kể gặp phải bất kỳ khó khăn nào, chúng ta đều phải giữ bình tĩnh, dũng cảm đối mặt và giải quyết."},{"type":"compound","zh":"在图书馆里看书时，大家不要发出任何声音，以免影响别人学习。","pinyin":"Zài túshūguǎn lǐ kànshū shí, dàjiā bú yào fāchū rènhé shēngyīn, yǐmiǎn yǐngxiǎng biérén xuéxí.","vi":"Lúc đọc sách trong thư viện, mọi người đừng phát ra bất kỳ tiếng động nào để tránh ảnh hưởng người khác học tập."}],"related":[{"hanzi":"任务","pinyin":"rènwu","vi":"Nhiệm vụ"},{"hanzi":"责任","pinyin":"zérèn","vi":"Trách nhiệm"},{"hanzi":"所有","pinyin":"suǒyǒu","vi":"Tất cả"},{"hanzi":"一切","pinyin":"yíqiè","vi":"Mọi thứ"},{"hanzi":"都","pinyin":"dōu","vi":"Đều"}]},{"id":"任务","hanzi":"任务","pinyin":"rènwu","meaning_vi":"nhiệm vụ","explanation":"任 (đảm nhiệm) + 务 (công việc).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"我们按时完成了任务。","pinyin":"Wǒmen ànshí wánchéngle rènwu.","vi":"Chúng tôi đã hoàn thành nhiệm vụ đúng hạn."},{"type":"simple","zh":"今天经理给每个同事都安排了具体的工作任务，大家都在认真准备。","pinyin":"Jīntiān jīnglǐ gěi měi ge tóngshì dōu ānpáile jùtǐ de gōngzuò rènwu, dàjiā dōu zài rènzhēn zhǔnbèi.","vi":"Hôm nay giám đốc đã phân công nhiệm vụ công việc cụ thể cho từng đồng nghiệp, mọi người đều đang nghiêm túc chuẩn bị."},{"type":"compound","zh":"虽然这次调研任务时间紧、难度大，但是我们团队有信心顺利完成。","pinyin":"Suīrán zhè cì diàoyán rènwu shíjiān jǐn, nándù dà, dànshì wǒmen tuánduì yǒu xìnxīn shùnlì wánchéng.","vi":"Tuy nhiệm vụ khảo sát lần này thời gian gấp, độ khó cao nhưng nhóm chúng tôi tự tin sẽ hoàn thành suôn sẻ."}],"related":[{"hanzi":"责任","pinyin":"zérèn","vi":"Trách nhiệm"},{"hanzi":"负责","pinyin":"fùzé","vi":"Phụ trách"},{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"安排","pinyin":"ānpái","vi":"Sắp xếp"}],"traditional":"任務"},{"id":"扔","hanzi":"扔","pinyin":"rēng","meaning_vi":"ném, vứt, bỏ","explanation":"Bộ tài gảy 扌+ 乃. Cụm: 扔垃圾 (vứt rác).","hsk_level":3,"tags":["dong-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"请把垃圾扔进垃圾桶里。","pinyin":"Qǐng bǎ lājī rēng jìn lājītǒng lǐ.","vi":"Xin hãy vứt rác vào trong thùng rác."},{"type":"simple","zh":"这件旧外套虽然款式有点儿老，但是还很暖和，别随便扔掉。","pinyin":"Zhè jiàn jiù wàitào suīrán kuǎnshì yǒudiǎnr lǎo, dànshì hái hěn nuǎnhuo, bié suíbiàn rēngdiào.","vi":"Chiếc áo khoác cũ này tuy kiểu dáng hơi lỗi thời một chút nhưng vẫn rất ấm áp, đừng vứt đi bừa bãi."},{"type":"compound","zh":"为了保护公园的美丽环境，游客们都自觉把用过的塑料袋扔进垃圾桶。","pinyin":"Wèile bǎohù gōngyuán de měilì huánjìng, yóukèmen dōu zìjué bǎ yòngguo de sùliàodài rēng jìn lājītǒng.","vi":"Để bảo vệ môi trường xinh đẹp của công viên, du khách đều tự giác vứt túi ni lông đã dùng vào thùng rác."}],"related":[{"hanzi":"垃圾桶","pinyin":"lājītǒng","vi":"Thùng rác"},{"hanzi":"丢","pinyin":"diū","vi":"Mất/Vứt"},{"hanzi":"掉","pinyin":"diào","vi":"Rơi"},{"hanzi":"破","pinyin":"pò","vi":"Rách/Vỡ"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"}]},{"id":"仍然","hanzi":"仍然","pinyin":"réngrán","meaning_vi":"vẫn, vẫn cứ","explanation":"仍 (vẫn) + 然. Trang trọng hơn 还是 / 还.","hsk_level":3,"tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"虽然下雨了，他仍然坚持跑步。","pinyin":"Suīrán xiàyǔ le, tā réngrán jiānchí pǎobù.","vi":"Tuy trời mưa rồi nhưng anh ấy vẫn kiên trì chạy bộ."},{"type":"simple","zh":"毕业十年以后，他仍然清楚地记得当年大学老师教过的每一句话。","pinyin":"Bìyè shí nián yǐhòu, tā réngrán qīngchu de jìde dāngnián dàxué lǎoshī jiāoguo de měi yíjùhuà.","vi":"10 năm sau khi tốt nghiệp, anh ấy vẫn nhớ rõ từng câu từng chữ thầy giáo đại học đã dạy năm xưa."},{"type":"compound","zh":"尽管现在电子书非常流行，但是仍然有很多人喜欢捧着纸质书阅读。","pinyin":"Jǐnguǎn xiànzài diànzǐshū fēicháng liúxíng, dànshì réngrán yǒu hěn duō rén xǐhuan pěngzhe zhǐzhìshū yuèdú.","vi":"Mặc dù sách điện tử hiện nay rất thịnh hành nhưng vẫn có rất nhiều người thích cầm sách giấy để đọc."}],"related":[{"hanzi":"还是","pinyin":"háishi","vi":"Vẫn là"},{"hanzi":"还","pinyin":"hái","vi":"Vẫn"},{"hanzi":"依然","pinyin":"yīrán","vi":"Vẫn cứ"},{"hanzi":"然而","pinyin":"rán'ér","vi":"Tuy nhiên"},{"hanzi":"虽然","pinyin":"suīrán","vi":"Tuy rằng"}]},{"id":"日记","hanzi":"日记","pinyin":"rìjì","meaning_vi":"nhật ký","explanation":"日 (ngày) + 记 (ghi chép). Cụm: 写日记 (viết nhật ký).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"📓","examples":[{"type":"basic","zh":"我每天晚上都写日记。","pinyin":"Wǒ měitiān wǎnshang dōu xiě rìjì.","vi":"Mỗi tối tôi đều viết nhật ký."},{"type":"simple","zh":"用汉语写日记是提高中文写作水平和积累生词的好方法。","pinyin":"Yòng Hànyǔ xiě rìjì shì tígāo Zhōngwén xiězuò shuǐ pínghé jīlěi shēngcí de hǎo fāngfǎ.","vi":"Viết nhật ký bằng tiếng Trung là phương pháp hay để nâng cao trình độ viết và tích lũy từ mới."},{"type":"compound","zh":"虽然每天工作很忙，但是她依然坚持在日记本上记录生活中的点点滴滴。","pinyin":"Suīrán měitiān gōngzuò hěn máng, dànshì tā yīrán jiānchí zài rìjìběn shang jìlù shēnghuó zhōng de diǎndiǎn Dīdī.","vi":"Tuy mỗi ngày làm việc rất bận nhưng cô ấy vẫn kiên trì ghi lại từng khoảnh khắc trong cuộc sống vào cuốn sổ nhật ký."}],"related":[{"hanzi":"记得","pinyin":"jìde","vi":"Nhớ"},{"hanzi":"记者","pinyin":"jìzhě","vi":"Nhà báo"},{"hanzi":"笔记本","pinyin":"bǐjìběn","vi":"Sổ tay"},{"hanzi":"写","pinyin":"xiě","vi":"Viết"},{"hanzi":"日","pinyin":"rì","vi":"Ngày"}],"traditional":"日記"},{"id":"入口","hanzi":"入口","pinyin":"rùkǒu","meaning_vi":"lối vào, cửa vào","explanation":"入 (vào) + 口 (cửa). Đối nghĩa với 出口 (lối ra).","hsk_level":3,"tags":["danh-tu","dia-diem"],"image":"🚪","examples":[{"type":"basic","zh":"地铁站的入口在前面。","pinyin":"Dìtiězhàn de rùkǒu zài qiánmiàn.","vi":"Lối vào ga tàu điện ngầm ở phía trước."},{"type":"simple","zh":"公园的入口处种满了五颜六色的鲜花，吸引了很多游客拍照。","pinyin":"Gōngyuán de rùkǒu chù zhòng mǎnle wǔyánliùsè de xiānhuā, xīyǐnle hěn duō yóukè pāizhào.","vi":"Khu vực lối vào công viên trồng đầy hoa tươi đủ màu sắc, thu hút rất nhiều du khách chụp ảnh."},{"type":"compound","zh":"因为周末逛商场的人太多，所以商场入口处排起了长长的队伍。","pinyin":"Yīnwèi zhōumò guàng shāngchǎng de rén tài duō, suǒyǐ shāngchǎng rùkǒu chù pái qǐle cháng cháng de duìwu.","vi":"Vì cuối tuần người đi dạo trung tâm thương mại đông quá nên khu vực lối vào xếp thành hàng dài."}],"related":[{"hanzi":"出口","pinyin":"chūkǒu","vi":"Lối ra"},{"hanzi":"进入","pinyin":"jìnrù","vi":"Bước vào"},{"hanzi":"门口","pinyin":"ménkǒu","vi":"Cổng/Cửa"},{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"公园","pinyin":"gōngyuán","vi":"Công viên"}]},{"id":"出口","hanzi":"出口","pinyin":"chūkǒu","meaning_vi":"lối ra; xuất khẩu","explanation":"出 (ra) + 口 (cửa). Đối nghĩa với 入口 (lối vào).","hsk_level":3,"tags":["danh-tu","dong-tu","dia-diem"],"image":"🚪","examples":[{"type":"basic","zh":"请从右边这个出口出去。","pinyin":"Qǐng cóng yòubiān zhè ge chūkǒu chūqù.","vi":"Xin hãy đi ra từ lối ra bên phải này."},{"type":"simple","zh":"火车站一共有四个出口，我们在北广场的二号出口见面吧。","pinyin":"Huǒchēzhàn yí gòngyǒu sì ge chūkǒu, wǒmen zài běi guǎngchǎng de èrhào chūkǒu jiànmiàn ba.","vi":"Ga tàu hỏa có tất cả 4 lối ra, chúng ta gặp nhau ở lối ra số 2 quảng trường phía Bắc nhé."},{"type":"compound","zh":"除了满足国内市场需求以外，这家工厂生产的服装还大量出口到欧洲。","pinyin":"Chúle mǎnzú guónèi shìchǎng xūqiú yǐwài, zhè jiā gōngchǎng shēngchǎn de fúzhuāng hái dàliàng chūkǒu dào Ōuzhōu.","vi":"Ngoài việc đáp ứng nhu cầu thị trường trong nước, quần áo do nhà máy này sản xuất còn xuất khẩu số lượng lớn sang châu Âu."}],"related":[{"hanzi":"入口","pinyin":"rùkǒu","vi":"Lối vào"},{"hanzi":"出","pinyin":"chū","vi":"Ra"},{"hanzi":"出发","pinyin":"chūfā","vi":"Xuất phát"},{"hanzi":"火车站","pinyin":"huǒchēzhàn","vi":"Ga tàu hỏa"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"}]},{"id":"森林","hanzi":"森林","pinyin":"sēnlín","meaning_vi":"rừng rậm","explanation":"Ba chữ 木 (cây) hợp thành 森 + hai chữ 木 thành 林 → rừng cây rậm rạp.","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"森林里有很多大树和动物。","pinyin":"Sēnlín lǐ yǒu hěn duōdà shù hé dòngwù.","vi":"Trong rừng rậm có rất nhiều cây to và động vật."},{"type":"simple","zh":"森林被称为“地球之肺”，对净化空气和保护生态环境起着重要作用。","pinyin":"Sēnlín bèi chēngwéi “dìqiú zhī fèi”, duì jìnghuà kōngqì hé bǎohù shēngtài huánjìng qǐzhe zhòngyào zuòyòng.","vi":"Rừng rậm được ví như “lá phổi của Trái Đất”, đóng vai trò quan trọng trong việc thanh lọc không khí và bảo vệ môi trường sinh thái."},{"type":"compound","zh":"夏天去森林公园避暑非常凉快，到处都是绿油油的树木和清新的空气。","pinyin":"Xiàtiān qù sēnlín gōngyuán bìshǔ fēicháng liángkuai, dàochù dōu shì lǜyóuyóu de shùmù hé qīngxīn de kōngqì.","vi":"Mùa hè đi công viên rừng tránh nóng vô cùng mát mẻ, khắp nơi đều là cây cối xanh mướt và không khí trong lành."}],"related":[{"hanzi":"树","pinyin":"shù","vi":"Cây"},{"hanzi":"植物","pinyin":"zhíwù","vi":"Thực vật"},{"hanzi":"自然","pinyin":"zìrán","vi":"Tự nhiên"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"}]},{"id":"沙发","hanzi":"沙发","pinyin":"shāfā","meaning_vi":"ghế sô pha","explanation":"Từ phiên âm tiếng Anh 'sofa'.","hsk_level":3,"tags":["danh-tu","do-vat","nha-cua"],"image":"🛋️","examples":[{"type":"basic","zh":"爷爷正坐在沙发上看报纸。","pinyin":"Yéye zhèng zuò zài shāfā shang kàn bàozhǐ.","vi":"Ông nội đang ngồi trên ghế sô pha đọc báo."},{"type":"simple","zh":"我们家客厅里新买了一套柔软舒适的布艺沙发。","pinyin":"Wǒmen jiā kètīng lǐ xīn mǎile yítào róuruǎn shūshì de bù yì shāfā.","vi":"Phòng khách nhà tôi mới mua một bộ ghế sô pha vải mềm mại êm ái."},{"type":"compound","zh":"下班回到家以后，躺在柔软的沙发上听一会儿音乐，一天的疲劳都消失了。","pinyin":"Xiàbān huí dàojiā yǐhòu, tǎng zài róuruǎn de shāfā shang tīng yíhuìr yīnyuè, yì tiān de píláo dōu xiāoshī le.","vi":"Sau khi tan làm về nhà, nằm trên chiếc ghế sô pha êm ái nghe một chút nhạc là mọi mệt mỏi cả ngày đều tan biến."}],"related":[{"hanzi":"客厅","pinyin":"kètīng","vi":"Phòng khách"},{"hanzi":"家具","pinyin":"jiājù","vi":"Đồ nội thất"},{"hanzi":"椅子","pinyin":"yǐzi","vi":"Cái ghế"},{"hanzi":"桌子","pinyin":"zhuōzi","vi":"Cái bàn"},{"hanzi":"舒服","pinyin":"shūfu","vi":"Thoải mái"}],"traditional":"沙發"},{"id":"伤心","hanzi":"伤心","pinyin":"shāngxīn","meaning_vi":"đau lòng, buồn bã","explanation":"伤 (tổn thương) + 心 (trái tim).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"听到这个消息她很伤心。","pinyin":"Tīngdào zhè ge xiāoxi tā hěn shāngxīn.","vi":"Nghe tin này cô ấy rất đau lòng."},{"type":"simple","zh":"小女孩最心爱的玩具熊丢了，她坐在沙发上伤心地哭了起来。","pinyin":"Xiǎo nǚhái zuì xīn'ài de wánjù xióng diū le, tā zuò zài shāfā shang shāngxīn de kūle qǐlái.","vi":"Con gấu bông yêu thích nhất của cô bé bị mất rồi, bé ngồi trên ghế sô pha khóc nức nở đau lòng."},{"type":"compound","zh":"虽然这次比赛没有拿到奖牌让人很伤心，但是朋友们都在耐心地安慰他。","pinyin":"Suīrán zhè cì bǐsài méiyǒu nádào jiǎngpái ràng rén hěn shāngxīn, dànshì péngyoumen dōu zài nàixīn de ānwèi tā.","vi":"Tuy cuộc thi lần này không giành được huy chương khiến người ta rất buồn nhưng bạn bè đều đang kiên nhẫn an ủi cậu ấy."}],"related":[{"hanzi":"难过","pinyin":"nánguò","vi":"Buồn bã"},{"hanzi":"哭","pinyin":"kū","vi":"Khóc"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"Đồng cảm"}],"traditional":"傷心"},{"id":"商量","hanzi":"商量","pinyin":"shāngliang","meaning_vi":"thương lượng, bàn bạc","explanation":"商 (bàn) + 量 (cân nhắc).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"这件事我们再商量一下。","pinyin":"Zhè jiàn shì wǒmen zài shāngliang yíxià.","vi":"Việc này chúng ta bàn bạc thêm một chút."},{"type":"simple","zh":"关于暑假去哪里旅游的计划，全家人昨天晚上一起商量了半天。","pinyin":"Guānyú shǔjià qù nǎlǐ lǚyóu de jìhuà, quán jiārén zuótiān wǎnshang yìqǐ shāngliangle bàn tiān.","vi":"Về kế hoạch kỳ nghỉ hè đi du lịch ở đâu, tối qua cả nhà đã cùng nhau bàn bạc suốt nửa buổi."},{"type":"compound","zh":"在做出重要决定之前，最好先和父母或者有经验的朋友商量一下。","pinyin":"Zài zuòchū zhòngyào juédìng zhīqián, zuìhǎo xiān hé fùmǔ huòzhě yǒu jīngyàn de péngyou shāngliang yíxià.","vi":"Trước khi đưa ra quyết định quan trọng, tốt nhất nên bàn bạc trước với bố mẹ hoặc bạn bè có kinh nghiệm."}],"related":[{"hanzi":"讨论","pinyin":"tǎolùn","vi":"Thảo luận"},{"hanzi":"商店","pinyin":"shāngdiàn","vi":"Cửa hàng"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"建议","pinyin":"jiànyì","vi":"Đề nghị"}]},{"id":"稍微","hanzi":"稍微","pinyin":"shāowēi","meaning_vi":"một chút, hơi","explanation":"稍 (một ít) + 微 (nhỏ bé). Phó từ đứng trước tính từ hoặc động từ.","hsk_level":3,"tags":["pho-tu"],"image":"🤏","examples":[{"type":"basic","zh":"请你稍微等我一下。","pinyin":"Qǐng nǐ shāowēi děng wǒ yíxià.","vi":"Xin bạn đợi tôi một chút."},{"type":"simple","zh":"这件衣服稍微有点儿大，里面再穿一件毛衣正好合适。","pinyin":"Zhè jiàn yīfu shāowēi yǒudiǎnr dà, lǐmiàn zài chuān yí jiàn máoyī zhènghǎo héshì.","vi":"Chiếc áo này hơi rộng một chút, mặc thêm một chiếc áo len bên trong là vừa vặn."},{"type":"compound","zh":"老师说话的速度稍微放慢了一点儿，这样班里的留学生都能听清楚了。","pinyin":"Lǎoshī shuōhuà de sùdù shāowēi fàngmànle yìdiǎnr, zhèyàng bān lǐ de liúxuésheng dōu néng tīng qīngchu le.","vi":"Tốc độ nói của thầy giáo chậm lại một chút, nhờ vậy du học sinh trong lớp đều nghe rõ hết."}],"related":[{"hanzi":"一点儿","pinyin":"yìdiǎnr","vi":"Một chút"},{"hanzi":"比较","pinyin":"bǐjiào","vi":"Tương đối"},{"hanzi":"挺","pinyin":"tǐng","vi":"Khá là"},{"hanzi":"慢","pinyin":"màn","vi":"Chậm"},{"hanzi":"等","pinyin":"děng","vi":"Đợi"}]},{"id":"勺子","hanzi":"勺子","pinyin":"sháozi","meaning_vi":"cái thìa, cái muỗng","explanation":"勺 + hậu tố 子.","hsk_level":3,"tags":["danh-tu","do-vat","an-uong"],"image":"🥄","examples":[{"type":"basic","zh":"喝汤要用勺子。","pinyin":"Hē tāng yào yòng sháozi.","vi":"Uống canh phải dùng thìa."},{"type":"simple","zh":"桌子上有碗、筷子和勺子，你想用哪个就自己拿吧。","pinyin":"Zhuōzi shang yǒu wǎn, kuàizi hé sháozi, nǐ xiǎng yòng nǎ ge jiù zìjǐ ná ba.","vi":"Trên bàn có bát, đũa và thìa, bạn muốn dùng cái nào thì cứ tự lấy nhé."},{"type":"compound","zh":"虽然很多外国人还不太会用筷子，但是用勺子喝汤和吃饭非常方便。","pinyin":"Suīrán hěn duō wàiguórén hái bú tài huì yòng kuàizi, dànshì yòng sháozi hē tāng hé chīfàn fēicháng fāngbiàn.","vi":"Tuy nhiều người nước ngoài vẫn chưa biết dùng đũa lắm nhưng dùng thìa uống canh và ăn cơm thì rất tiện."}],"related":[{"hanzi":"筷子","pinyin":"kuàizi","vi":"Đôi đũa"},{"hanzi":"碗","pinyin":"wǎn","vi":"Cái bát"},{"hanzi":"刀","pinyin":"dāo","vi":"Con dao"},{"hanzi":"汤","pinyin":"tāng","vi":"Canh"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"Ăn cơm"}]},{"id":"社会","hanzi":"社会","pinyin":"shèhuì","meaning_vi":"xã hội","explanation":"社 (tổ chức) + 会 (tập hợp).","hsk_level":3,"tags":["danh-tu"],"image":"🏙️","examples":[{"type":"basic","zh":"大学是一个小社会。","pinyin":"Dàxué shì yí ge xiǎo shèhuì.","vi":"Trường đại học là một xã hội thu nhỏ."},{"type":"simple","zh":"大学生在假期多参加社会实践活动，对将来找工作很有帮助。","pinyin":"Dàxuésheng zài jiàqī duō cānjiā shèhuì shíjiàn huódòng, duì jiānglái zhǎogōngzuò hěn yǒubāngzhù.","vi":"Sinh viên đại học trong kỳ nghỉ tham gia nhiều hoạt động thực tiễn xã hội sẽ rất có ích cho việc tìm việc sau này."},{"type":"compound","zh":"随着现代社会的发展，人们对环境保护和健康生活的重视程度越来越高。","pinyin":"Suízhe xiàndài shèhuì de fāzhǎn, rénmen duì huánjìngbǎohù hé jiànkāng shēnghuó de zhòngshì chéngdù yuèláiyuè gāo.","vi":"Cùng với sự phát triển của xã hội hiện đại, mức độ coi trọng của con người đối với bảo vệ môi trường và sống khỏe ngày càng cao."}],"related":[{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"经济","pinyin":"jīngjì","vi":"Kinh tế"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"},{"hanzi":"人类","pinyin":"rénlèi","vi":"Loài người"}],"traditional":"社會"},{"id":"申请","hanzi":"申请","pinyin":"shēnqǐng","meaning_vi":"xin, nộp đơn xin","explanation":"申 (trình bày) + 请 (thỉnh cầu). Dùng cho 申请工作, 申请奖学金.","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📝","examples":[{"type":"basic","zh":"我想申请去中国留学。","pinyin":"Wǒ xiǎng shēnqǐng qù Zhōngguó liúxué.","vi":"Tôi muốn nộp đơn xin đi Trung Quốc du học."},{"type":"simple","zh":"他已经把申请奖学金所需要的全部材料都交给了学校办公室。","pinyin":"Tā yǐjīng bǎ shēnqǐng jiǎngxuéjīn suǒ xūyào de quánbù cáiliào dōu jiāogěile xuéxiào bàngōngshì.","vi":"Anh ấy đã nộp toàn bộ tài liệu cần thiết để xin học bổng cho văn phòng nhà trường rồi."},{"type":"compound","zh":"因为这家国际公司的招聘条件比较高，所以申请这个职位的人必须精通双语。","pinyin":"Yīnwèi zhè jiā Guójì gōngsī de zhāopìn tiáojiàn bǐjiào gāo, suǒyǐ shēnqǐng zhè ge zhíwèi de rén bìxū jīngtōng shuāngyǔ.","vi":"Vì điều kiện tuyển dụng của công ty quốc tế này tương đối cao nên người ứng tuyển vị trí này bắt buộc phải thông thạo song ngữ."}],"related":[{"hanzi":"请","pinyin":"qǐng","vi":"Xin/Mời"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"Visa"},{"hanzi":"应聘","pinyin":"yìngpìn","vi":"Ứng tuyển"},{"hanzi":"材料","pinyin":"cáiliào","vi":"Tài liệu"},{"hanzi":"留学","pinyin":"liúxué","vi":"Du học"}],"traditional":"申請"},{"id":"深","hanzi":"深","pinyin":"shēn","meaning_vi":"sâu; đậm (màu); khuya (đêm)","explanation":"Bộ thủy 氵+ 罙. Đối nghĩa với 浅 (nông/nhạt).","hsk_level":3,"tags":["tinh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"这条河的水很深。","pinyin":"Zhè tiáo hé de shuǐ hěn shēn.","vi":"Nước của con sông này rất sâu."},{"type":"simple","zh":"已经深夜十二点了，王老师书房里的灯依然亮着。","pinyin":"Yǐjīng shēnyè shí'èr diǎn le, Wáng lǎoshī shūfáng lǐ de dēng yīrán liàng zhe.","vi":"Đã 12 giờ đêm khuya rồi mà đèn trong phòng đọc sách của thầy Vương vẫn sáng."},{"type":"compound","zh":"虽然深颜色的衣服不容易脏，但是夏天穿会觉得很热。","pinyin":"Suīrán shēn yánsè de yīfu bù róngyì zāng, dànshì xiàtiān chuān huì juéde hěn rè.","vi":"Tuy quần áo màu đậm không dễ bẩn nhưng mặc vào mùa hè sẽ thấy rất nóng."}],"related":[{"hanzi":"河","pinyin":"hé","vi":"Sông"},{"hanzi":"海","pinyin":"hǎi","vi":"Biển"},{"hanzi":"浅","pinyin":"qiǎn","vi":"Nông/Nhạt"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"Ấn tượng"},{"hanzi":"颜色","pinyin":"yánsè","vi":"Màu sắc"}]},{"id":"甚至","hanzi":"甚至","pinyin":"shènzhì","meaning_vi":"thậm chí","explanation":"Phó từ nhấn mạnh ví dụ nổi bật hoặc cực đoan nhất.","hsk_level":3,"tags":["pho-tu","lien-tu"],"image":"❗","examples":[{"type":"basic","zh":"他忙得甚至连吃饭的时间都没有。","pinyin":"Tā máng de shènzhì lián chīfàn de shíjiān dōu méiyǒu.","vi":"Anh ấy bận đến mức thậm chí cả thời gian ăn cơm cũng không có."},{"type":"simple","zh":"这个小男孩非常聪明，甚至连很多大人不会写的汉字他都认识。","pinyin":"Zhè ge xiǎo nánhái fēicháng cōngming, shènzhì lián hěn duō dàrén bú huì xiě de hànzì tā dōu rènshi.","vi":"Cậu bé này vô cùng thông minh, thậm chí ngay cả nhiều chữ Hán người lớn không biết viết bé cũng nhận ra."},{"type":"compound","zh":"自从用了智能手机以后，很多人出门不带钱包，甚至连钥匙都可以不用带了。","pinyin":"Zìcóng yòngle zhìnéng shǒujī yǐhòu, hěn duō rén chūmén búdài qiánbāo, shènzhì lián yàoshi dōu kěyǐ bú yòng dài le.","vi":"Từ khi dùng điện thoại thông minh, nhiều người ra đường không mang ví tiền, thậm chí ngay cả chìa khóa cũng không cần mang nữa."}],"related":[{"hanzi":"连","pinyin":"lián","vi":"Ngay cả"},{"hanzi":"非常","pinyin":"fēicháng","vi":"Vô cùng"},{"hanzi":"十分","pinyin":"shífēn","vi":"Hết sức"},{"hanzi":"几乎","pinyin":"jīhū","vi":"Hầu như"},{"hanzi":"而且","pinyin":"érqiě","vi":"Mà còn"}]},{"id":"生活","hanzi":"生活","pinyin":"shēnghuó","meaning_vi":"cuộc sống, sinh hoạt","explanation":"生 (sinh tồn) + 活 (hoạt động). Vừa là danh từ vừa là động từ.","hsk_level":3,"tags":["danh-tu","dong-tu"],"image":"🏡","examples":[{"type":"basic","zh":"在北京的生活很愉快。","pinyin":"Zài Běijīng de shēnghuó hěn yúkuài.","vi":"Cuộc sống ở Bắc Kinh rất vui vẻ."},{"type":"simple","zh":"现在人们的生活水平提高了，越来越多人喜欢在假期出国旅游。","pinyin":"Xiànzài rénmen de shēnghuó shuǐpíng tígāo le, yuèláiyuè duō rén xǐhuan zài jiàqī chūguó lǚyóu.","vi":"Hiện nay mức sống của người dân đã nâng cao, ngày càng nhiều người thích đi du lịch nước ngoài vào kỳ nghỉ."},{"type":"compound","zh":"虽然刚开始来中国留学时生活上有些不习惯，但是现在已经完全适应了。","pinyin":"Suīrán gāng kāishǐ lái Zhōngguó liúxué shí shēnghuó shang yǒuxiē bù xíguàn, dànshì xiànzài yǐjīng wánquán shìyìng le.","vi":"Tuy lúc mới sang Trung Quốc du học sinh hoạt có chút chưa quen nhưng hiện tại đã hoàn toàn thích nghi rồi."}],"related":[{"hanzi":"生命","pinyin":"shēngmìng","vi":"Sinh mệnh"},{"hanzi":"生意","pinyin":"shēngyi","vi":"Kinh doanh"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"},{"hanzi":"活泼","pinyin":"huópō","vi":"Hoạt bát"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"}]},{"id":"生命","hanzi":"生命","pinyin":"shēngmìng","meaning_vi":"sinh mệnh, sự sống","explanation":"生 (sự sống) + 命 (mạng sống).","hsk_level":3,"tags":["danh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"水是生命之源。","pinyin":"Shuǐ shì shēngmìng zhī yuán.","vi":"Nước là cội nguồn của sự sống."},{"type":"simple","zh":"医生和护士每天都在医院里努力工作，挽救病人的生命。","pinyin":"Yīshēng hé hùshi měitiān dōu zài yīyuàn lǐ nǔlì gōngzuò, wǎnjiù bìngrén de shēngmìng.","vi":"Bác sĩ và y tá mỗi ngày đều nỗ lực làm việc trong bệnh viện để cứu sống sinh mệnh bệnh nhân."},{"type":"compound","zh":"生命只有一次，所以我们一定要珍惜健康、热爱生活、安全出行。","pinyin":"Shēngmìng zhǐ yǒuyícì, suǒyǐ wǒmen yídìngyào zhēnxī jiànkāng, rè'ài shēnghuó, ānquán chūxíng.","vi":"Sinh mệnh chỉ có một lần, vì vậy chúng ta nhất định phải trân trọng sức khỏe, yêu cuộc sống và đi lại an toàn."}],"related":[{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"},{"hanzi":"水","pinyin":"shuǐ","vi":"Nước"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"}]},{"id":"生意","hanzi":"生意","pinyin":"shēngyi","meaning_vi":"việc kinh doanh, buôn bán","explanation":"生 (nảy sinh) + 意 (ý định). Cụm: 做生意 (kinh doanh).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"这家饭店的生意很好。","pinyin":"Zhè jiā fàndiàn de shēngyi hěn hǎo.","vi":"Việc kinh doanh của nhà hàng này rất tốt."},{"type":"simple","zh":"我叔叔在市中心开了一家服装店，因为价格便宜，每天生意都很红火。","pinyin":"Wǒ shūshu zài shìzhōngxīn kāile yìjiā fúzhuāngdiàn, yīnwèi jiàgé piányi, měitiān shēngyi dōu hěn hónghuǒ.","vi":"Chú tôi mở một cửa hàng quần áo ở trung tâm thành phố, vì giá rẻ nên ngày nào buôn bán cũng đắt khách."},{"type":"compound","zh":"虽然做生意经常会遇到市场竞争的压力，但是只要诚信经营就能赢得顾客。","pinyin":"Suīrán zuòshēngyi jīngcháng huì yùdào shìchǎng jìngzhēng de yālì, dànshì zhǐyào chéngxìn jīngyíng jiù néng yíngdé gùkè.","vi":"Tuy làm kinh doanh thường gặp áp lực cạnh tranh thị trường nhưng chỉ cần kinh doanh chữ tín thì sẽ giành được khách hàng."}],"related":[{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"意思","pinyin":"yìsi","vi":"Ý nghĩa"},{"hanzi":"经济","pinyin":"jīngjì","vi":"Kinh tế"},{"hanzi":"顾客","pinyin":"gùkè","vi":"Khách hàng"},{"hanzi":"赚钱","pinyin":"zhuànqián","vi":"Kiếm tiền"}]},{"id":"省","hanzi":"省","pinyin":"shěng","meaning_vi":"tỉnh; tiết kiệm, đỡ tốn","explanation":"Vừa chỉ tỉnh thành vừa chỉ việc tiết kiệm (省钱 - tiết kiệm tiền).","hsk_level":3,"tags":["danh-tu","dong-tu","dia-diem"],"image":"🗺️","examples":[{"type":"basic","zh":"坐地铁比打车省钱。","pinyin":"Zuò dìtiě bǐ dǎchē shěngqián.","vi":"Đi tàu điện ngầm tiết kiệm tiền hơn đi taxi."},{"type":"simple","zh":"山东省位于中国东部沿海，那里有著名的泰山和孔子故里。","pinyin":"Shāndōngshěng wèiyú Zhōngguó Dōngbù yánhǎi, nàlǐ yǒu zhùmíng de Tàishān hé Kǒngzǐ gùlǐ.","vi":"Tỉnh Sơn Đông nằm ở vùng duyên hải phía Đông Trung Quốc, nơi đó có núi Thái Sơn nổi tiếng và quê hương Khổng Tử."},{"type":"compound","zh":"自己在家做饭不仅比去外面饭店吃省钱，而且还能保证食材新鲜卫生。","pinyin":"Zìjǐ zài jiā zuòfàn bùjǐn bǐ qù wàimiàn fàndiàn chī shěngqián, érqiě hái néng bǎozhèng shícái xīnxiān wèishēng.","vi":"Tự nấu ăn ở nhà không những tiết kiệm tiền hơn ra nhà hàng ăn mà còn đảm bảo nguyên liệu tươi ngon vệ sinh."}],"related":[{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"},{"hanzi":"省钱","pinyin":"shěngqián","vi":"Tiết kiệm tiền"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"},{"hanzi":"国家","pinyin":"guójiā","vi":"Quốc gia"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"}]},{"id":"剩","hanzi":"剩","pinyin":"shèng","meaning_vi":"thừa lại, còn lại","explanation":"乘 + 刂 (dao). Dùng cho thức ăn, tiền bạc hoặc thời gian còn dư.","hsk_level":3,"tags":["dong-tu"],"image":"🍽️","examples":[{"type":"basic","zh":"桌子上还剩两个苹果。","pinyin":"Zhuōzi shang hái shèng liǎng ge píngguǒ.","vi":"Trên bàn vẫn còn thừa hai quả táo."},{"type":"simple","zh":"距离期末考试只剩下两个星期了，同学们都在抓紧时间复习。","pinyin":"Jùlí qīmò kǎoshì zhǐ shèngxià liǎng ge xīngqī le, tóngxuémen dōu zài zhuājǐn shíjiān fùxí.","vi":"Chỉ còn lại hai tuần nữa là đến kỳ thi cuối kỳ rồi, các bạn học đều đang tranh thủ thời gian ôn tập."},{"type":"compound","zh":"如果饭店里点的菜吃不完还剩很多，我们可以让服务员帮忙打包带回家。","pinyin":"Rúguǒ fàndiàn lǐ diǎn de cài chī bù wán hái shèng hěn duō, wǒmen kěyǐ ràng fúwùyuán bāngmáng dǎbāo dài huíjiā.","vi":"Nếu món ăn gọi ở nhà hàng ăn không hết vẫn còn thừa nhiều, chúng ta có thể nhờ nhân viên phục vụ gói mang về nhà."}],"related":[{"hanzi":"浪费","pinyin":"làngfèi","vi":"Lãng phí"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"},{"hanzi":"留","pinyin":"liú","vi":"Để lại"},{"hanzi":"多","pinyin":"duō","vi":"Nhiều"},{"hanzi":"少","pinyin":"shǎo","vi":"Ít"}]},{"id":"失望","hanzi":"失望","pinyin":"shīwàng","meaning_vi":"thất vọng","explanation":"失 (mất) + 望 (hy vọng). Đối nghĩa với 希望 (hy vọng).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"我对这次成绩很失望。","pinyin":"Wǒ duì zhè cì chéngjì hěn shīwàng.","vi":"Tôi rất thất vọng với điểm số lần này."},{"type":"simple","zh":"因为下雨取消了周末的爬山计划，弟弟感到非常失望。","pinyin":"Yīnwèi xiàyǔ qǔxiāole zhōumò de páshān jìhuà, dìdi gǎndào fēicháng shīwàng.","vi":"Vì trời mưa nên kế hoạch leo núi cuối tuần bị hủy, em trai cảm thấy vô cùng thất vọng."},{"type":"compound","zh":"不管遇到什么挫折，我们都不能对生活感到失望，只要努力就还有机会。","pinyin":"Bùguǎn yùdào shénme cuòzhé, wǒmen dōu bù néng duì shēnghuó gǎndào shīwàng, zhǐyào nǔlì jiù háiyǒu jīhuì.","vi":"Bất kể gặp phải trắc trở gì, chúng ta đều không được thất vọng với cuộc sống, chỉ cần nỗ lực thì vẫn còn cơ hội."}],"related":[{"hanzi":"希望","pinyin":"xīwàng","vi":"Hy vọng"},{"hanzi":"失败","pinyin":"shībài","vi":"Thất bại"},{"hanzi":"伤心","pinyin":"shāngxīn","vi":"Đau lòng"},{"hanzi":"难过","pinyin":"nánguò","vi":"Buồn bã"},{"hanzi":"满意","pinyin":"mǎnyì","vi":"Hài lòng"}]},{"id":"师傅","hanzi":"师傅","pinyin":"shīfu","meaning_vi":"sư phụ, bác tài, thợ lành nghề","explanation":"师 (thầy) + 傅 (người dạy). Cách gọi tôn trọng bác tài xế hoặc thợ thủ công.","hsk_level":3,"tags":["danh-tu","con-nguoi","nghe-nghiep"],"image":"👷","examples":[{"type":"basic","zh":"师傅，请问去火车站怎么走？","pinyin":"Shīfu, qǐngwèn qùhuǒ chēzhàn zěnme zǒu?","vi":"Bác tài ơi, xin hỏi đi ga tàu hỏa đi đường nào ạ?"},{"type":"simple","zh":"这位修车师傅手艺非常好，只用了十分钟就把自行车修好了。","pinyin":"Zhè wèi xiūchē shīfu shǒuyì fēicháng hǎo, zhǐ yòngle shí fēnzhōng jiù bǎ zìxíngchē xiūhǎo le.","vi":"Bác thợ sửa xe này tay nghề rất giỏi, chỉ mất 10 phút đã sửa xong chiếc xe đạp."},{"type":"compound","zh":"在北方城市坐出租车时，大家习惯礼貌地称呼司机为“师傅”。","pinyin":"Zài běifāng chéngshì zuò chūzūchē shí, dàjiā xíguàn lǐmào de chēnghu sījī wéi “shīfu”.","vi":"Khi đi xe taxi ở các thành phố miền Bắc, mọi người quen gọi bác tài xế một cách lịch sự là “sư phụ”."}],"related":[{"hanzi":"老师","pinyin":"lǎoshī","vi":"Giáo viên"},{"hanzi":"司机","pinyin":"sījī","vi":"Tài xế"},{"hanzi":"修理","pinyin":"xiūlǐ","vi":"Sửa chữa"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"},{"hanzi":"大师","pinyin":"dàshī","vi":"Đại sư"}],"traditional":"師傅"},{"id":"十分","hanzi":"十分","pinyin":"shífēn","meaning_vi":"vô cùng, hết sức","explanation":"十 (mười) + 分 (phần) → trọn vẹn 10/10, đồng nghĩa với 非常.","hsk_level":3,"tags":["pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"今天天气十分晴朗。","pinyin":"Jīntiān tiānqì shífēn qínglǎng.","vi":"Hôm nay thời tiết vô cùng quang đãng."},{"type":"simple","zh":"王老师对我们的学习进步感到十分满意，经常在班里表扬大家。","pinyin":"Wáng lǎoshī duì wǒmen de xuéxí jìnbù gǎndào shífēn mǎnyì, jīngcháng zài bān lǐ biǎoyáng dàjiā.","vi":"Thầy Vương cảm thấy vô cùng hài lòng với sự tiến bộ trong học tập của chúng tôi, thường xuyên khen ngợi cả lớp."},{"type":"compound","zh":"虽然这篇文章的生词十分多，但是只要耐心查词典就能完全看懂。","pinyin":"Suīrán zhè piān wénzhāng de shēngcí shífēn duō, dànshì zhǐyào nàixīn chá cídiǎn jiù néng wánquán kàndǒng.","vi":"Tuy bài văn này có vô cùng nhiều từ mới nhưng chỉ cần kiên nhẫn tra từ điển là có thể đọc hiểu hoàn toàn."}],"related":[{"hanzi":"非常","pinyin":"fēicháng","vi":"Vô cùng"},{"hanzi":"十","pinyin":"shí","vi":"Mười"},{"hanzi":"分","pinyin":"fēn","vi":"Phần/Phút"},{"hanzi":"特别","pinyin":"tèbié","vi":"Đặc biệt"},{"hanzi":"完全","pinyin":"wánquán","vi":"Hoàn toàn"}]},{"id":"实际","hanzi":"实际","pinyin":"shíjì","meaning_vi":"thực tế","explanation":"实 (thật) + 际 (ranh giới/tình hình). Vừa là danh từ vừa là tính từ.","hsk_level":3,"tags":["danh-tu","tinh-tu"],"image":"📊","examples":[{"type":"basic","zh":"我们要从实际情况出发。","pinyin":"Wǒmen yào cóng shíjì qíngkuàng chūfā.","vi":"Chúng ta phải xuất phát từ tình hình thực tế."},{"type":"simple","zh":"学习语言不能只看书本，还要结合实际生活中的对话来练习。","pinyin":"Xuéxí yǔyán bù néng zhǐ kàn shūběn, hái yào jiéhé shíjì shēnghuó zhōng de duìhuà lái liànxí.","vi":"Học ngôn ngữ không thể chỉ nhìn sách vở, mà còn phải kết hợp với hội thoại trong đời sống thực tế để luyện tập."},{"type":"compound","zh":"虽然这个方案在理论上听起来很完美，但是在实际操作中却遇到了很多困难。","pinyin":"Suīrán zhè ge fāng'àn zài lǐlùn shang tīngqǐlái hěn wánměi, dànshì zài shíjì cāozuò zhōng què yùdàole hěn duō kùnnan.","vi":"Tuy phương án này nghe trên lý thuyết rất hoàn hảo nhưng khi thực hiện trong thực tế lại gặp nhiều khó khăn."}],"related":[{"hanzi":"实在","pinyin":"shízài","vi":"Thật sự"},{"hanzi":"国际","pinyin":"Guójì","vi":"Quốc tế"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"Tình huống"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"Thành thật"},{"hanzi":"现实","pinyin":"xiànshí","vi":"Hiện thực"}],"traditional":"實際"},{"id":"实在","hanzi":"实在","pinyin":"shízài","meaning_vi":"thật sự, quả thật; thật thà, chân thật","explanation":"实 (thật) + 在 (tồn tại).","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"✔️","examples":[{"type":"basic","zh":"今天的工作实在太多了。","pinyin":"Jīntiān de gōngzuò shízài tài duō le.","vi":"Công việc hôm nay thật sự quá nhiều rồi."},{"type":"simple","zh":"小李为人非常老实实在，大家都喜欢跟他交朋友。","pinyin":"Xiǎo Lǐ wéirén fēicháng lǎoshi shízài, dàjiā dōu xǐhuan gēn tā jiāopéngyou.","vi":"Tiểu Lý sống rất thật thà chân chất, ai cũng thích kết bạn với anh ấy."},{"type":"compound","zh":"因为昨天下雨路滑，我实在不敢骑自行车出门，只好坐地铁去上班。","pinyin":"Yīnwèi zuótiān xiàyǔ lù huá, wǒ shízài bù gǎn qí zìxíngchē chūmén, zhǐhǎo zuò dìtiě qù shàngbān.","vi":"Vì hôm qua trời mưa đường trơn, tôi thật sự không dám đạp xe ra ngoài nên đành đi tàu điện ngầm đi làm."}],"related":[{"hanzi":"实际","pinyin":"shíjì","vi":"Thực tế"},{"hanzi":"确实","pinyin":"quèshí","vi":"Quả thực"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"Thành thật"},{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"太","pinyin":"tài","vi":"Quá"}],"traditional":"實在"},{"id":"使","hanzi":"使","pinyin":"shǐ","meaning_vi":"khiến, làm cho; dùng, sử dụng","explanation":"Bộ nhân đứng 亻+ 吏. Dùng nhiều trong văn viết.","hsk_level":3,"tags":["dong-tu"],"image":"⚡","examples":[{"type":"basic","zh":"这个好消息使大家都很高兴。","pinyin":"Zhè ge hǎo xiāoxi shǐ dàjiā dōu hěn gāoxìng.","vi":"Tin tốt này khiến mọi người đều rất vui."},{"type":"simple","zh":"王老师幽默风趣的教学方式，使原本枯燥的语法课变得生动有趣。","pinyin":"Wáng lǎoshī yōumò fēngqù de jiāoxué fāngshì, shǐ yuánběn kūzào de yǔfǎ kè biànde shēngdòng yǒuqù.","vi":"Phương pháp giảng dạy hài hước dí dỏm của thầy Vương khiến tiết ngữ pháp vốn khô khan trở nên sinh động thú vị."},{"type":"compound","zh":"半年的努力锻炼不仅使他的体重减轻了，而且使他的精神状态也更好了。","pinyin":"Bàn nián de nǔlì duànliàn bùjǐn shǐ tā de tǐzhòng jiǎnqīng le, érqiě shǐ tā de jīngshén zhuàngtài yě gèng hǎo le.","vi":"Nửa năm chăm chỉ rèn luyện không những khiến anh ấy giảm cân mà còn khiến tinh thần anh ấy tốt hơn hẳn."}],"related":[{"hanzi":"使用","pinyin":"shǐyòng","vi":"Sử dụng"},{"hanzi":"让","pinyin":"ràng","vi":"Khiến/Bảo"},{"hanzi":"即使","pinyin":"jíshǐ","vi":"Cho dù"},{"hanzi":"叫","pinyin":"jiào","vi":"Bảo/Gọi"},{"hanzi":"大使馆","pinyin":"dàshǐguǎn","vi":"Đại sứ quán"}]},{"id":"使用","hanzi":"使用","pinyin":"shǐyòng","meaning_vi":"sử dụng","explanation":"使 (khiến) + 用 (dùng).","hsk_level":3,"tags":["dong-tu"],"image":"🛠️","examples":[{"type":"basic","zh":"你会使用这台新电脑吗？","pinyin":"Nǐ huì shǐyòng zhè tái xīn diànnǎo ma?","vi":"Bạn biết sử dụng chiếc máy tính mới này không?"},{"type":"simple","zh":"在图书馆里使用电脑时，请戴上耳机，不要影响周围的同学。","pinyin":"Zài túshūguǎn lǐ shǐyòng diànnǎo shí, qǐng dàishàng ěrjī, bú yào yǐngxiǎng zhōuwéi de tóngxué.","vi":"Khi sử dụng máy tính trong thư viện, xin hãy đeo tai nghe để không làm ảnh hưởng các bạn xung quanh."},{"type":"compound","zh":"为了减少白色污染，现在很多超市都鼓励顾客使用环保布袋代替塑料袋。","pinyin":"Wèile jiǎnshǎo báisè wūrǎn, xiànzài hěn duō chāoshì dōu gǔlì gùkè shǐyòng huánbǎo bùdài dàitì sùliàodài.","vi":"Để giảm thiểu ô nhiễm trắng, hiện nay nhiều siêu thị khuyến khích khách hàng dùng túi vải bảo vệ môi trường thay cho túi ni lông."}],"related":[{"hanzi":"使","pinyin":"shǐ","vi":"Khiến/Dùng"},{"hanzi":"用","pinyin":"yòng","vi":"Dùng"},{"hanzi":"作用","pinyin":"zuòyòng","vi":"Tác dụng"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"},{"hanzi":"说明","pinyin":"shuōmíng","vi":"Hướng dẫn"}]},{"id":"世纪","hanzi":"世纪","pinyin":"shìjì","meaning_vi":"thế kỷ","explanation":"世 (đời) + 纪 (kỷ nguyên). Ví dụ: 二十一世纪 (thế kỷ 21).","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"🌍","examples":[{"type":"basic","zh":"我们生活在二十一世纪。","pinyin":"Wǒmen shēnghuó zài èr shíyī shìjì.","vi":"Chúng ta đang sống ở thế kỷ 21."},{"type":"simple","zh":"进入二十一世纪以来，互联网和智能手机极大地改变了人们的生活方式。","pinyin":"Jìnrù èr shíyī shìjì yǐlái, Hùliánwǎng hé zhìnéng shǒujī jí dàde gǎibiànle rénmen de shēnghuó fāngshì.","vi":"Kể từ khi bước vào thế kỷ 21, Internet và điện thoại thông minh đã thay đổi mạnh mẽ lối sống của con người."},{"type":"compound","zh":"这座古老的石桥建于十八世纪，至今仍然保存得非常完好。","pinyin":"Zhè zuò gǔlǎo de shí qiáo jiàn yú shíbā shìjì, zhìjīn réngrán bǎocún de fēicháng wánhǎo.","vi":"Cây cầu đá cổ kính này được xây dựng vào thế kỷ 18, đến nay vẫn được bảo tồn vô cùng nguyên vẹn."}],"related":[{"hanzi":"世界","pinyin":"shìjiè","vi":"Thế giới"},{"hanzi":"纪念","pinyin":"jìniàn","vi":"Kỷ niệm"},{"hanzi":"历史","pinyin":"lìshǐ","vi":"Lịch sử"},{"hanzi":"年","pinyin":"nián","vi":"Năm"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"}],"traditional":"世紀"},{"id":"是否","hanzi":"是否","pinyin":"shìfǒu","meaning_vi":"có phải không, liệu có","explanation":"是 (phải) + 否 (không). Dùng trong văn viết tương đương 是不是.","hsk_level":3,"tags":["pho-tu","nghi-van"],"image":"❓","examples":[{"type":"basic","zh":"请确认一下信息是否正确。","pinyin":"Qǐng quèrèn yíxià xìnxī shìfǒu zhèngquè.","vi":"Xin hãy xác nhận lại một chút xem thông tin có chính xác không."},{"type":"simple","zh":"明天下午是否去公园爬山，还要看天气预报怎么说。","pinyin":"Míngtiān xiàwǔ shìfǒu qù gōngyuán páshān, hái yào kàn tiānqì yùbào zěnme shuō.","vi":"Chiều mai có đi công viên leo núi hay không vẫn còn phải xem dự báo thời tiết nói thế nào."},{"type":"compound","zh":"一个人能否取得成功，关键在于他是否具备坚持不懈的毅力和勇气。","pinyin":"Yígerén néngfǒu qǔdé chénggōng, guānjiàn zàiyú tā shìfǒu jùbèi jiānchíbúxiè de yìlì hé yǒngqì.","vi":"Một người có thể đạt được thành công hay không, mấu chốt nằm ở việc người đó có ý chí kiên trì bền bỉ và lòng dũng cảm hay không."}],"related":[{"hanzi":"否则","pinyin":"fǒuzé","vi":"Nếu không thì"},{"hanzi":"是不是","pinyin":"shìbushì","vi":"Có phải không"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"判断","pinyin":"pànduàn","vi":"Phán đoán"},{"hanzi":"符合","pinyin":"fúhé","vi":"Phù hợp"}]},{"id":"适合","hanzi":"适合","pinyin":"shìhé","meaning_vi":"thích hợp, phù hợp","explanation":"适 (vừa) + 合 (hợp). Thường đi với tân ngữ (适合我 - hợp với tôi).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"这件衣服很适合你。","pinyin":"Zhè jiàn yīfu hěn shìhé nǐ.","vi":"Bộ quần áo này rất hợp với bạn."},{"type":"simple","zh":"春天的北京气候温和，不冷也不热，最适合出门旅游了。","pinyin":"Chūntiān de Běijīng qìhòu wēnhé, bù lěng yě bú rè, zuì shìhé chūmén lǚyóu le.","vi":"Bắc Kinh vào mùa xuân khí hậu ôn hòa, không lạnh cũng không nóng, thích hợp nhất để đi du lịch."},{"type":"compound","zh":"每个人都有自己的特点，只有选择最适合自己的学习方法，才能事半功倍。","pinyin":"Měigerén dōu yǒu zìjǐ de tèdiǎn, zhǐyǒu xuǎnzé zuì shìhé zìjǐ de xuéxí fāngfǎ, cáinéng shìbàngōngbèi.","vi":"Mỗi người đều có đặc điểm riêng, chỉ có lựa chọn phương pháp học phù hợp nhất với bản thân mới đạt hiệu quả gấp đôi."}],"related":[{"hanzi":"合适","pinyin":"héshì","vi":"Thích hợp"},{"hanzi":"符合","pinyin":"fúhé","vi":"Phù hợp"},{"hanzi":"适应","pinyin":"shìyìng","vi":"Thích nghi"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"},{"hanzi":"舒服","pinyin":"shūfu","vi":"Thoải mái"}],"traditional":"適合"},{"id":"适应","hanzi":"适应","pinyin":"shìyìng","meaning_vi":"thích nghi, quen với","explanation":"适 (vừa) + 应 (đáp ứng). Dùng trong 适应新环境 (thích nghi môi trường mới).","hsk_level":3,"tags":["dong-tu"],"image":"🌱","examples":[{"type":"basic","zh":"我已经适应这里的生活了。","pinyin":"Wǒ yǐjīng shìyìng zhèlǐ de shēnghuó le.","vi":"Tôi đã thích nghi với cuộc sống ở đây rồi."},{"type":"simple","zh":"刚上大学一年级的新生，需要一段时间来适应集体宿舍的生活。","pinyin":"Gāng shàng dàxué yì niánjí de xīnshēng, xūyào yí duàn shíjiān lái shìyìng jítǐ sùshè de shēnghuó.","vi":"Tân sinh viên mới vào năm nhất đại học cần một khoảng thời gian để thích nghi với cuộc sống ký túc xá tập thể."},{"type":"compound","zh":"虽然北方的冬天非常寒冷干燥，但是他在北京住了两年以后已经完全适应了。","pinyin":"Suīrán běifāng de dōngtiān fēicháng hánlěng gānzào, dànshì tā zài Běijīng zhùle liǎng nián yǐhòu yǐjīng wánquán shìyìng le.","vi":"Tuy mùa đông miền Bắc vô cùng lạnh giá hanh khô nhưng sau khi sống ở Bắc Kinh hai năm thì anh ấy đã hoàn toàn thích nghi."}],"related":[{"hanzi":"适合","pinyin":"shìhé","vi":"Thích hợp"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"接受","pinyin":"jiēshòu","vi":"Tiếp nhận"}],"traditional":"適應"},{"id":"收","hanzi":"收","pinyin":"shōu","meaning_vi":"nhận, thu, cất","explanation":"Dùng cho 收到 (nhận được), 收拾 (dọn dẹp).","hsk_level":3,"tags":["dong-tu"],"image":"📥","examples":[{"type":"basic","zh":"我收到你的信了。","pinyin":"Wǒ shōudào nǐ de xìn le.","vi":"Tôi đã nhận được thư của bạn rồi."},{"type":"simple","zh":"昨天妈妈给我寄的生日礼物，我今天上午就已经收到了。","pinyin":"Zuótiān māma gěi wǒ jì de shēngrì lǐwù, wǒ jīntiān shàngwǔ jiù yǐjīng shōudào le.","vi":"Món quà sinh nhật mẹ gửi cho tôi hôm qua, sáng nay tôi đã nhận được rồi."},{"type":"compound","zh":"外面好像要下雨了，你快去阳台上把晾着的衣服收进来吧。","pinyin":"Wàimiàn hǎoxiàng yào xiàyǔ le, nǐ kuài qù yángtái shang bǎ liàngzhe de yīfu shōu jìnlái ba.","vi":"Bên ngoài hình như sắp mưa rồi, bạn mau ra ban công thu quần áo đang phơi vào nhà đi."}],"related":[{"hanzi":"收到","pinyin":"shōudào","vi":"Nhận được"},{"hanzi":"收入","pinyin":"shōurù","vi":"Thu nhập"},{"hanzi":"收拾","pinyin":"shōushi","vi":"Dọn dẹp"},{"hanzi":"寄","pinyin":"jì","vi":"Gửi"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm/Lấy"}]},{"id":"收入","hanzi":"收入","pinyin":"shōurù","meaning_vi":"thu nhập","explanation":"收 (thu về) + 入 (vào). Danh từ.","hsk_level":3,"tags":["danh-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"他现在的收入比以前高多了。","pinyin":"Tā xiànzài de shōurù bǐ yǐqián gāo duō le.","vi":"Thu nhập hiện tại của anh ấy cao hơn trước đây nhiều."},{"type":"simple","zh":"随着旅游业的发展，当地农民的家庭收入每年都在稳步增加。","pinyin":"Suízhe lǚyóuyè de fāzhǎn, dāngdì nóngmín de jiātíng shōurù měinián dōu zài wěnbù zēngjiā.","vi":"Cùng với sự phát triển của ngành du lịch, thu nhập gia đình của người nông dân địa phương hằng năm đều tăng trưởng ổn định."},{"type":"compound","zh":"虽然他现在这份工作的收入不算特别高，但是工作时间轻松，能学到很多东西。","pinyin":"Suīrán tā xiànzài zhè fèn gōngzuò de shōurù búsuàn tèbié gāo, dànshì gōngzuò shíjiān qīngsōng, néng xuédào hěn duō dōngxi.","vi":"Tuy thu nhập của công việc hiện tại không tính là quá cao nhưng thời gian làm việc nhẹ nhàng và học hỏi được nhiều điều."}],"related":[{"hanzi":"工资","pinyin":"gōngzī","vi":"Tiền lương"},{"hanzi":"收","pinyin":"shōu","vi":"Thu/Nhận"},{"hanzi":"赚钱","pinyin":"zhuànqián","vi":"Kiếm tiền"},{"hanzi":"经济","pinyin":"jīngjì","vi":"Kinh tế"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"Tăng thêm"}]},{"id":"收拾","hanzi":"收拾","pinyin":"shōushi","meaning_vi":"dọn dẹp, thu dọn","explanation":"收 (thu gom) + 拾 (nhặt nhạnh). Dùng trong 收拾房间 (dọn phòng).","hsk_level":3,"tags":["dong-tu","nha-cua"],"image":"🧹","examples":[{"type":"basic","zh":"我正在收拾房间。","pinyin":"Wǒ zhèngzài shōushi fángjiān.","vi":"Tôi đang dọn dẹp phòng."},{"type":"simple","zh":"明天一早就要出发去机场了，你今天晚上赶紧把行李箱收拾好。","pinyin":"Míngtiān yìzǎo jiùyào chūfā qù jīchǎng le, nǐ jīntiān wǎnshang gǎnjǐn bǎ xínglixiāng shōushi hǎo.","vi":"Sáng sớm mai đã phải xuất phát ra sân bay rồi, tối nay bạn khẩn trương thu dọn vali hành lý cho xong đi."},{"type":"compound","zh":"虽然妈妈每天下班回家都很累，但是她总是把客厅和厨房收拾得干干净净。","pinyin":"Suīrán māma měitiān xiàbān huíjiā dōu hěn lèi, dànshì tā zǒngshì bǎ kètīng hé chúfáng shōushi de gān gānjìng jìng.","vi":"Tuy mỗi ngày mẹ tan làm về nhà đều rất mệt nhưng mẹ luôn dọn dẹp phòng khách và nhà bếp sạch sẽ tinh tươm."}],"related":[{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"},{"hanzi":"收","pinyin":"shōu","vi":"Thu dọn"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"乱","pinyin":"luàn","vi":"Lộn xộn"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"}]},{"id":"首都","hanzi":"首都","pinyin":"shǒudū","meaning_vi":"thủ đô","explanation":"首 (đứng đầu) + 都 (kinh đô).","hsk_level":3,"tags":["danh-tu","dia-diem"],"image":"🏛️","examples":[{"type":"basic","zh":"北京是中国的首都。","pinyin":"Běijīng shì Zhōngguó de shǒudū.","vi":"Bắc Kinh là thủ đô của Trung Quốc."},{"type":"simple","zh":"河内是越南的首都，那里有着一千多年的悠久历史和文化。","pinyin":"Hénèi shì Yuènán de shǒudū, nàlǐ yǒuzhe yī qiān duōnián de yōujiǔ lìshǐ hé wénhuà.","vi":"Hà Nội là thủ đô của Việt Nam, nơi đó có lịch sử và văn hóa lâu đời hơn một nghìn năm."},{"type":"compound","zh":"作为中国的首都，北京不仅是政治和文化中心，也是一座现代化的国际大都市。","pinyin":"Zuòwéi Zhōngguó de shǒudū, Běijīng bùjǐn shì zhèngzhì hé wénhuà zhōngxīn, yě shì yí zuò xiàndàihuà de Guójì dàdūshì.","vi":"Là thủ đô của Trung Quốc, Bắc Kinh không chỉ là trung tâm chính trị và văn hóa mà còn là một đại đô thị quốc tế hiện đại."}],"related":[{"hanzi":"首先","pinyin":"shǒuxiān","vi":"Đầu tiên"},{"hanzi":"北京","pinyin":"Běijīng","vi":"Bắc Kinh"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"},{"hanzi":"国家","pinyin":"guójiā","vi":"Quốc gia"},{"hanzi":"都","pinyin":"dōu","vi":"Đều/Đô thị"}]},{"id":"受不了","hanzi":"受不了","pinyin":"shòubuliǎo","meaning_vi":"không chịu nổi","explanation":"受 (chịu đựng) + 不 + 了 (nổi).","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"😫","examples":[{"type":"basic","zh":"今天太热了，真受不了！","pinyin":"Jīntiān tài rè le, zhēn shòubuliǎo!","vi":"Hôm nay nóng quá, thật không chịu nổi!"},{"type":"simple","zh":"楼上装修的声音太大了，吵得我根本没法看书，简直受不了。","pinyin":"Lóushang zhuāngxiū de shēngyīn tài dà le, chǎo de wǒ gēnběn méifǎ kànshū, jiǎnzhí shòubuliǎo.","vi":"Tiếng sửa nhà trên tầng ồn quá, làm tôi chẳng thể nào đọc sách được, thật sự không chịu nổi."},{"type":"compound","zh":"虽然四川火锅非常好吃，但是对于一点儿辣也不能吃的人来说实在受不了。","pinyin":"Suīrán Sìchuān huǒguō fēicháng hǎochī, dànshì duìyú yìdiǎnr là yě bù néng chī de rén lái shuō shízài shòubuliǎo.","vi":"Tuy lẩu Tứ Xuyên vô cùng ngon nhưng đối với người không ăn được chút cay nào thì thật sự không chịu nổi."}],"related":[{"hanzi":"受到","pinyin":"shòudào","vi":"Nhận được"},{"hanzi":"接受","pinyin":"jiēshòu","vi":"Chấp nhận"},{"hanzi":"难受","pinyin":"nánshòu","vi":"Khó chịu"},{"hanzi":"吵","pinyin":"chǎo","vi":"Ồn ào"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"}]},{"id":"受到","hanzi":"受到","pinyin":"shòudào","meaning_vi":"nhận được, chịu phải","explanation":"受 (nhận) + 到 (được). Ví dụ: 受到表扬 (nhận được lời khen).","hsk_level":3,"tags":["dong-tu"],"image":"🎖️","examples":[{"type":"basic","zh":"他的表演受到了大家的欢迎。","pinyin":"Tā de biǎoyǎn shòudàole dàjiā de huānyíng.","vi":"Màn biểu diễn của anh ấy đã nhận được sự chào đón của mọi người."},{"type":"simple","zh":"因为工作认真负责，小张经常受到公司领导的表扬和奖励。","pinyin":"Yīnwèi gōngzuò rènzhēn fùzé, xiǎo Zhāng jīngcháng shòudào gōngsī lǐngdǎo de biǎoyáng hé jiǎnglì.","vi":"Vì làm việc nghiêm túc có trách nhiệm, Tiểu Trương thường xuyên nhận được lời khen ngợi và phần thưởng của lãnh đạo công ty."},{"type":"compound","zh":"这部新上映的电影不仅受到了年轻人的喜爱，连很多老人也看得非常感动。","pinyin":"Zhè bù xīn shàngyìng de diànyǐng bùjǐn shòudàole niánqīngrén de xǐ'ài, lián hěn duō lǎorén yě kàn de fēicháng gǎndòng.","vi":"Bộ phim mới công chiếu này không chỉ nhận được sự yêu mến của giới trẻ mà ngay cả nhiều người lớn tuổi xem cũng vô cùng cảm động."}],"related":[{"hanzi":"接受","pinyin":"jiēshòu","vi":"Tiếp nhận"},{"hanzi":"受不了","pinyin":"shòubuliǎo","vi":"Không chịu nổi"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"},{"hanzi":"欢迎","pinyin":"huānyíng","vi":"Hoan nghênh"},{"hanzi":"收到","pinyin":"shōudào","vi":"Nhận được"}]},{"id":"售货员","hanzi":"售货员","pinyin":"shòuhuòyuán","meaning_vi":"nhân viên bán hàng","explanation":"售货 (bán hàng) + 员 (nhân viên).","hsk_level":3,"tags":["danh-tu","nghe-nghiep","mua-sam"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"那位售货员很热情。","pinyin":"Nà wèi shòuhuòyuán hěn rèqíng.","vi":"Nhân viên bán hàng đó rất nhiệt tình."},{"type":"simple","zh":"超市里的售货员耐心地帮奶奶找到了她想要买的无糖饼干。","pinyin":"Chāoshì lǐ de shòuhuòyuán nàixīn de bāng nǎinai zhǎodàole tā xiǎngyào mǎi de wútáng bǐnggān.","vi":"Nhân viên bán hàng trong siêu thị kiên nhẫn giúp bà nội tìm được loại bánh quy không đường mà bà muốn mua."},{"type":"compound","zh":"因为这位售货员不仅态度亲切，而且对商品质量非常了解，所以很多顾客都找她买东西。","pinyin":"Yīnwèi zhè wèi shòuhuòyuán bùjǐn tàidù qīnqiè, érqiě duì shāngpǐn zhìliàng fēicháng liǎojiě, suǒyǐ hěn duō gùkè dōu zhǎo tā mǎidōngxi.","vi":"Vì nhân viên bán hàng này không chỉ thái độ thân thiện mà còn hiểu rất rõ chất lượng hàng hóa nên nhiều khách hàng đều tìm cô mua đồ."}],"related":[{"hanzi":"服务员","pinyin":"fúwùyuán","vi":"Nhân viên phục vụ"},{"hanzi":"商店","pinyin":"shāngdiàn","vi":"Cửa hàng"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"顾客","pinyin":"gùkè","vi":"Khách hàng"},{"hanzi":"卖","pinyin":"mài","vi":"Bán"}],"traditional":"售貨員"},{"id":"输","hanzi":"输","pinyin":"shū","meaning_vi":"thua","explanation":"Bộ xa 车 + 俞. Đối nghĩa với 赢 (thắng).","hsk_level":3,"tags":["dong-tu","the-thao"],"image":"🏳️","examples":[{"type":"basic","zh":"我们队今天输了比赛。","pinyin":"Wǒmen duì jīntiān shūle bǐsài.","vi":"Đội chúng tôi hôm nay đã thua trận đấu."},{"type":"simple","zh":"下棋的时候有赢就有输，最重要的是享受思考的过程。","pinyin":"Xiàqí de shíhou yǒu yíng jiù yǒu shū, zuì zhòngyào de shì xiǎngshòu sīkǎo de guòchéng.","vi":"Lúc chơi cờ có thắng thì có thua, quan trọng nhất là tận hưởng quá trình suy nghĩ."},{"type":"compound","zh":"虽然这次乒乓球比赛他输给了对手，但是他一点儿也不气馁，决定继续刻苦训练。","pinyin":"Suīrán zhè cì pīngpāngqiú bǐsài tā shūgěile duìshǒu, dànshì tā yìdiǎnr yě bú qìněi, juédìng jìxù kèkǔ xùnliàn.","vi":"Tuy trận thi đấu bóng bàn lần này anh ấy thua đối thủ nhưng anh ấy không hề nản chí mà quyết định tiếp tục khổ luyện."}],"related":[{"hanzi":"赢","pinyin":"yíng","vi":"Thắng"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"失败","pinyin":"shībài","vi":"Thất bại"},{"hanzi":"输入","pinyin":"shūrù","vi":"Nhập vào"},{"hanzi":"过程","pinyin":"guòchéng","vi":"Quá trình"}],"traditional":"輸"},{"id":"赢","hanzi":"赢","pinyin":"yíng","meaning_vi":"thắng, chiến thắng","explanation":"Đối nghĩa với 输 (thua).","hsk_level":3,"tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"他们赢了这场比赛。","pinyin":"Tāmen yíngle zhè chǎng bǐsài.","vi":"Họ đã thắng trận đấu này."},{"type":"simple","zh":"经过全队成员的默契配合，我们班终于赢得了这场篮球比赛的冠军。","pinyin":"Jīngguò quán duì chéngyuán de mòqì pèihé, wǒmen bān zhōngyú yíng déle zhè chǎng lánqiú bǐsài de guànjūn.","vi":"Nhờ sự phối hợp ăn ý của toàn đội, lớp chúng tôi cuối cùng đã giành chiến thắng chức vô địch trận bóng rổ này."},{"type":"compound","zh":"在商业竞争中，只有提供高质量的产品和优质的服务，才能真正赢得顾客的信任。","pinyin":"Zài shāngyè jìngzhēng zhōng, zhǐyǒu tígōng gāozhìliàng de chǎnpǐn hé yōuzhì de fúwù, cáinéng zhēnzhèng yíngdé gùkè de xìnrèn.","vi":"Trong cạnh tranh thương mại, chỉ có cung cấp sản phẩm chất lượng cao và dịch vụ tốt mới thực sự giành được niềm tin của khách hàng."}],"related":[{"hanzi":"输","pinyin":"shū","vi":"Thua"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"获得","pinyin":"huòdé","vi":"Giành được"},{"hanzi":"冠军","pinyin":"guànjūn","vi":"Quán quân"}],"traditional":"贏"},{"id":"熟悉","hanzi":"熟悉","pinyin":"shúxī","meaning_vi":"quen thuộc, nắm rõ","explanation":"熟 (chín/quen) + 悉 (biết rõ).","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"我对北京的路很熟悉。","pinyin":"Wǒ duì Běijīng de lù hěn shúxī.","vi":"Tôi rất quen thuộc đường sá Bắc Kinh."},{"type":"simple","zh":"他只用了一个星期就熟悉了新公司的工作环境。","pinyin":"Tā zhǐ yòngle yí ge xīngqī jiù shúxīle xīn gōngsī de gōngzuò huánjìng.","vi":"Anh ấy chỉ mất một tuần đã quen với môi trường làm việc của công ty mới."},{"type":"compound","zh":"虽然他刚来公司工作不到一个月，但是已经对所有的业务流程都非常熟悉了。","pinyin":"Suīrán tā gāng lái gōngsī gōngzuò búdào yí geyuè, dànshì yǐjīng duì suǒyǒu de yèwù liúchéng dōu fēicháng shúxī le.","vi":"Tuy anh ấy mới vào công ty làm việc chưa đầy một tháng nhưng đã nắm rất rõ toàn bộ quy trình nghiệp vụ rồi."}],"related":[{"hanzi":"认识","pinyin":"rènshi","vi":"Quen biết"},{"hanzi":"了解","pinyin":"liǎojiě","vi":"Hiểu rõ"},{"hanzi":"成熟","pinyin":"chéngshú","vi":"Chín chắn"},{"hanzi":"陌生","pinyin":"mòshēng","vi":"Xa lạ"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"}]},{"id":"数量","hanzi":"数量","pinyin":"shùliàng","meaning_vi":"số lượng","explanation":"数 (con số) + 量 (đo lường).","hsk_level":3,"tags":["danh-tu","so-luong"],"image":"🔢","examples":[{"type":"basic","zh":"这些苹果的数量不够。","pinyin":"Zhèxiē píngguǒ de shùliàng búgòu.","vi":"Số lượng táo này không đủ."},{"type":"simple","zh":"我们不仅要增加产品的生产数量，更要严格保证产品的质量。","pinyin":"Wǒmen bùjǐn yào zēngjiā chǎnpǐn de shēngchǎn shùliàng, gèng yào yángé bǎozhèng chǎnpǐn de zhìliàng.","vi":"Chúng ta không chỉ cần tăng số lượng sản xuất sản phẩm mà còn phải đảm bảo nghiêm ngặt chất lượng sản phẩm."},{"type":"compound","zh":"虽然他每天背诵的生词数量不算很多，但是因为坚持复习，所以记得特别牢固。","pinyin":"Suīrán tā měitiān bèisòng de shēngcí shùliàng búsuàn hěn duō, dànshì yīnwèi jiānchí fùxí, suǒyǐ jìde tèbié láogù.","vi":"Tuy số lượng từ mới cậu ấy học thuộc mỗi ngày không tính là nhiều nhưng vì kiên trì ôn tập nên nhớ rất chắc."}],"related":[{"hanzi":"数字","pinyin":"shùzì","vi":"Con số"},{"hanzi":"质量","pinyin":"zhìliàng","vi":"Chất lượng"},{"hanzi":"多少","pinyin":"duōshao","vi":"Bao nhiêu"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"Tăng thêm"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"Giảm bớt"}],"traditional":"數量"},{"id":"数字","hanzi":"数字","pinyin":"shùzì","meaning_vi":"con số, chữ số","explanation":"数 (số) + 字 (chữ).","hsk_level":3,"tags":["danh-tu","so-luong"],"image":"1️⃣","examples":[{"type":"basic","zh":"请写清楚这些数字。","pinyin":"Qǐng xiě qīngchu zhèxiē shùzì.","vi":"Xin hãy viết rõ những con số này."},{"type":"simple","zh":"中国人非常喜欢“八”和“六”这两个数字，因为它们代表着发财和顺利。","pinyin":"Zhōngguórén fēicháng xǐhuan “bā” hé “liù” zhè liǎng ge shùzì, yīnwèi tāmen dàibiǎozhe fācái hé shùnlì.","vi":"Người Trung Quốc vô cùng thích hai con số “8” và “6”, vì chúng tượng trưng cho phát tài và thuận lợi."},{"type":"compound","zh":"在填写银行表格时，每一个数字和字母都必须核对准确，不能有任何错误。","pinyin":"Zài tiánxiě yínháng biǎogé shí, měi yí ge shùzì hé zìmǔ dōu bìxū héduì zhǔnquè, bù néng yǒu rènhé cuòwù.","vi":"Khi điền biểu mẫu ngân hàng, từng con số và chữ cái đều phải đối chiếu chính xác, không được có bất kỳ sai sót nào."}],"related":[{"hanzi":"数量","pinyin":"shùliàng","vi":"Số lượng"},{"hanzi":"数学","pinyin":"shùxué","vi":"Toán học"},{"hanzi":"字","pinyin":"zì","vi":"Chữ"},{"hanzi":"号码","pinyin":"hàomǎ","vi":"Số hiệu"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"Chính xác"}],"traditional":"數字"},{"id":"顺便","hanzi":"顺便","pinyin":"shùnbiàn","meaning_vi":"tiện thể, nhân tiện","explanation":"顺 (thuận theo) + 便 (tiện lợi).","hsk_level":3,"tags":["pho-tu"],"image":"🚶","examples":[{"type":"basic","zh":"我下班顺便去超市买菜。","pinyin":"Wǒ xiàbān shùnbiàn qù chāoshì mǎicài.","vi":"Tôi tan làm tiện thể ghé siêu thị mua thức ăn."},{"type":"simple","zh":"你去邮局寄信的时候，能不能顺便帮我买几张邮票回来？","pinyin":"Nǐ qù yóujú jì xìn de shíhou, néng bu néng shùnbiàn bāng wǒ mǎi jǐ zhāng yóupiào huílái?","vi":"Lúc bạn đi bưu điện gửi thư, có thể tiện thể mua giúp tôi vài con tem mang về được không?"},{"type":"compound","zh":"因为今天下午要去大学附近办事，所以我顺便去图书馆还了上周借的书。","pinyin":"Yīnwèi jīntiān xiàwǔ yào qù dàxué fùjìn bànshì, suǒyǐ wǒ shùnbiàn qù túshūguǎn huán le shàngzhōu jiè de shū.","vi":"Vì chiều nay phải đi làm việc ở gần trường đại học nên tôi tiện đường ghé thư viện trả sách mượn tuần trước."}],"related":[{"hanzi":"顺利","pinyin":"shùnlì","vi":"Thuận lợi"},{"hanzi":"顺序","pinyin":"shùnxù","vi":"Thứ tự"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"},{"hanzi":"随便","pinyin":"suíbiàn","vi":"Tùy ý"},{"hanzi":"经过","pinyin":"jīngguò","vi":"Đi qua"}],"traditional":"順便"},{"id":"顺利","hanzi":"顺利","pinyin":"shùnlì","meaning_vi":"thuận lợi, suôn sẻ","explanation":"顺 (xuôi chiều) + 利 (trôi chảy).","hsk_level":3,"tags":["tinh-tu"],"image":"🍀","examples":[{"type":"basic","zh":"祝你一切顺利！","pinyin":"Zhù nǐ yíqiè shùnlì!","vi":"Chúc bạn mọi việc thuận lợi!"},{"type":"simple","zh":"在老师和同学们的共同努力下，这次文艺演出进行得非常顺利。","pinyin":"Zài lǎoshī hé tóngxuémen de gòngtóng nǔlì xià, zhè cì wényì yǎnchū jìnxíng de fēicháng shùnlì.","vi":"Dưới sự nỗ lực chung của thầy cô và các bạn học, buổi biểu diễn văn nghệ lần này diễn ra vô cùng suôn sẻ."},{"type":"compound","zh":"虽然准备出国签证的材料过程有点儿复杂，但是最终还是顺利拿到了签证。","pinyin":"Suīrán zhǔnbèi chūguó qiānzhèng de cáiliào guòchéng yǒudiǎnr fùzá, dànshì zuìzhōng háishi shùnlì nádàole qiānzhèng.","vi":"Tuy quá trình chuẩn bị hồ sơ xin visa ra nước ngoài hơi phức tạp nhưng cuối cùng vẫn lấy được visa thuận lợi."}],"related":[{"hanzi":"顺便","pinyin":"shùnbiàn","vi":"Tiện thể"},{"hanzi":"顺序","pinyin":"shùnxù","vi":"Thứ tự"},{"hanzi":"流利","pinyin":"liúlì","vi":"Trôi chảy"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"祝贺","pinyin":"zhùhè","vi":"Chúc mừng"}],"traditional":"順利"},{"id":"顺序","hanzi":"顺序","pinyin":"shùnxù","meaning_vi":"thứ tự, trình tự","explanation":"顺 (theo) + 序 (thứ bậc).","hsk_level":3,"tags":["danh-tu"],"image":"🔢","examples":[{"type":"basic","zh":"请按照顺序进入教室。","pinyin":"Qǐng ànzhào shùnxù jìnrù jiàoshì.","vi":"Xin hãy vào phòng học theo thứ tự."},{"type":"simple","zh":"写汉字的时候一定要注意笔画顺序，这样写出来的字才会好看。","pinyin":"Xiě hànzì de shíhou yídìngyào zhùyì bǐhuà shùnxù, zhèyàng xiě chūlái de zì cái huì hǎokàn.","vi":"Khi viết chữ Hán nhất định phải chú ý thứ tự nét bút, như vậy chữ viết ra mới đẹp."},{"type":"compound","zh":"比赛出场顺序是通过抽签决定的，我们班刚好抽到了第一个上台表演。","pinyin":"Bǐsài chūchǎng shùnxù shì tōngguò chōuqiān juédìng de, wǒmen bān gānghǎo chōu dàole dìyī ge shàngtái biǎoyǎn.","vi":"Thứ tự ra sân thi đấu được quyết định bằng bốc thăm, lớp chúng tôi vừa hay bốc trúng lượt biểu diễn đầu tiên."}],"related":[{"hanzi":"排队","pinyin":"páiduì","vi":"Xếp hàng"},{"hanzi":"排列","pinyin":"páiliè","vi":"Sắp xếp"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"Thuận lợi"},{"hanzi":"顺便","pinyin":"shùnbiàn","vi":"Tiện thể"},{"hanzi":"首先","pinyin":"shǒuxiān","vi":"Đầu tiên"}],"traditional":"順序"},{"id":"说明","hanzi":"说明","pinyin":"shuōmíng","meaning_vi":"giải thích, thuyết minh; chứng tỏ, cho thấy; bản hướng dẫn","explanation":"说 (nói) + 明 (rõ ràng).","hsk_level":3,"tags":["dong-tu","danh-tu"],"image":"📖","examples":[{"type":"basic","zh":"请你说明一下原因。","pinyin":"Qǐng nǐ shuōmíng yíxià yuányīn.","vi":"Xin bạn giải thích một chút về nguyên nhân."},{"type":"simple","zh":"使用新买的电器之前，最好先认真阅读一遍产品说明书。","pinyin":"Shǐyòng xīn mǎi de diànqì zhīqián, zuìhǎo xiān rènzhēn yuèdú yíbiàn chǎnpǐn shuōmíngshū.","vi":"Trước khi sử dụng thiết bị điện mới mua, tốt nhất nên đọc kỹ một lượt sách hướng dẫn sử dụng sản phẩm."},{"type":"compound","zh":"他这次考试能取得这么大的进步，充分说明了努力学习的重要性。","pinyin":"Tā zhè cì kǎoshì néng qǔdé zhème dà de jìnbù, chōngfèn shuōmíngle nǔlì xuéxí de zhòngyàoxìng.","vi":"Việc cậu ấy đạt được tiến bộ lớn như vậy trong kỳ thi lần này đã chứng minh đầy đủ tầm quan trọng của việc chăm chỉ học tập."}],"related":[{"hanzi":"解释","pinyin":"jiěshì","vi":"Giải thích"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"Chứng minh"},{"hanzi":"明白","pinyin":"míngbai","vi":"Rõ ràng"},{"hanzi":"说","pinyin":"shuō","vi":"Nói"},{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"}],"traditional":"說明"},{"id":"硕士","hanzi":"硕士","pinyin":"shuòshì","meaning_vi":"thạc sĩ","explanation":"硕 (to lớn) + 士 (học giả).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"我姐姐正在读硕士研究生。","pinyin":"Wǒ jiějie zhèngzài dú shuòshì yánjiūshēng.","vi":"Chị gái tôi đang học cao học thạc sĩ."},{"type":"simple","zh":"他大学毕业以后考上了北京大学的经济学硕士。","pinyin":"Tā dàxué bìyè yǐhòu kǎoshàngle Běijīngdàxué de jīngjìxué shuòshì.","vi":"Sau khi tốt nghiệp đại học, anh ấy đã thi đỗ thạc sĩ ngành kinh tế học của Đại học Bắc Kinh."},{"type":"compound","zh":"虽然攻读硕士学位需要写很多研究论文，但是她觉得这段学习经历非常充实。","pinyin":"Suīrán gōngdú shuòshì xuéwèi xūyào xiě hěn duō yánjiū lùnwén, dànshì tā juéde zhè duàn xuéxí jīnglì fēicháng chōngshí.","vi":"Tuy theo học bằng thạc sĩ phải viết nhiều luận văn nghiên cứu nhưng chị ấy cảm thấy quãng thời gian học tập này vô cùng bổ ích."}],"related":[{"hanzi":"博士","pinyin":"bóshì","vi":"Tiến sĩ"},{"hanzi":"大学","pinyin":"dàxué","vi":"Đại học"},{"hanzi":"研究","pinyin":"yánjiū","vi":"Nghiên cứu"},{"hanzi":"毕业","pinyin":"bìyè","vi":"Tốt nghiệp"},{"hanzi":"专业","pinyin":"zhuānyè","vi":"Chuyên ngành"}],"traditional":"碩士"},{"id":"死","hanzi":"死","pinyin":"sǐ","meaning_vi":"chết, qua đời","explanation":"Đối nghĩa với 活 (sống).","hsk_level":3,"tags":["dong-tu"],"image":"🥀","examples":[{"type":"basic","zh":"这盆花因为缺水死了。","pinyin":"Zhè pénhuā yīnwèi quēshuǐ sǐle.","vi":"Chậu hoa này chết vì thiếu nước rồi."},{"type":"simple","zh":"今天天气热死了，外面一点儿风也没有，我们还是吹空调吧。","pinyin":"Jīntiān tiānqì rè sǐle, wàimiàn yìdiǎnr fēng yě méiyǒu, wǒmen háishi chuī kōngtiáo ba.","vi":"Hôm nay thời tiết nóng chết đi được, bên ngoài không có chút gió nào, chúng ta bật điều hòa thôi."},{"type":"compound","zh":"虽然这个历史故事发生在一千多年前，但是故事里英雄的精神永远不会死。","pinyin":"Suīrán zhè ge lìshǐ gùshi fāshēng zài yī qiān duō niánqián, dànshì gùshi lǐ yīngxióng de jīngshén yǒngyuǎn bú huì sǐ.","vi":"Tuy câu chuyện lịch sử này xảy ra từ hơn một nghìn năm trước nhưng tinh thần của người anh hùng trong truyện sẽ không bao giờ tắt."}],"related":[{"hanzi":"生命","pinyin":"shēngmìng","vi":"Sinh mệnh"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"活","pinyin":"huó","vi":"Sống"},{"hanzi":"花","pinyin":"huā","vi":"Hoa"},{"hanzi":"植物","pinyin":"zhíwù","vi":"Thực vật"}]},{"id":"速度","hanzi":"速度","pinyin":"sùdù","meaning_vi":"tốc độ","explanation":"速 (nhanh) + 度 (mức độ).","hsk_level":3,"tags":["danh-tu","giao-thong"],"image":"⚡","examples":[{"type":"basic","zh":"高铁的速度非常快。","pinyin":"Gāotiě de sùdù fēicháng kuài.","vi":"Tốc độ của tàu cao tốc vô cùng nhanh."},{"type":"simple","zh":"王老师说话的速度不快不慢，非常适合我们这些汉语初学者。","pinyin":"Wáng lǎoshī shuōhuà de sùdù búkuài bú màn, fēicháng shìhé wǒmen zhèxiē Hànyǔ chūxuézhě.","vi":"Tốc độ nói của thầy Vương không nhanh không chậm, vô cùng thích hợp với những người mới học tiếng Trung như chúng tôi."},{"type":"compound","zh":"在高速公路上开车时，一定要控制好速度，千万不能超速。","pinyin":"Zài gāosùgōnglù shang kāichē shí, yídìngyào kòngzhì hǎo sùdù, qiānwàn bù néng chāosù.","vi":"Khi lái xe trên đường cao tốc, nhất định phải kiểm soát tốt tốc độ, tuyệt đối không được chạy quá tốc độ."}],"related":[{"hanzi":"高速公路","pinyin":"gāosùgōnglù","vi":"Đường cao tốc"},{"hanzi":"温度","pinyin":"wēndù","vi":"Nhiệt độ"},{"hanzi":"态度","pinyin":"tàidu","vi":"Thái độ"},{"hanzi":"快","pinyin":"kuài","vi":"Nhanh"},{"hanzi":"慢","pinyin":"màn","vi":"Chậm"}]},{"id":"塑料袋","hanzi":"塑料袋","pinyin":"sùliàodài","meaning_vi":"túi ni lông, túi nhựa","explanation":"塑料 (nhựa) + 袋 (cái túi).","hsk_level":3,"tags":["danh-tu","do-vat","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"请少用一次性塑料袋。","pinyin":"Qǐng shǎo yòng yícìxìng sùliàodài.","vi":"Xin hãy dùng ít túi ni lông dùng một lần."},{"type":"simple","zh":"现在去超市买东西，塑料袋都是需要另外花钱购买的。","pinyin":"Xiànzài qù chāoshì mǎidōngxi, sùliàodài dōu shì xūyào lìngwài huāqián gòumǎi de.","vi":"Hiện nay đi siêu thị mua đồ, túi ni lông đều phải tốn tiền mua riêng."},{"type":"compound","zh":"因为塑料袋在自然界中很难分解，所以为了保护环境，大家出门购物最好自带布袋。","pinyin":"Yīnwèi sùliàodài zài zìránjiè zhōng hěn nán fēnjiě, suǒyǐ wèile bǎohù huánjìng, dàjiā chūmén gòuwù zuìhǎo zìdài bùdài.","vi":"Vì túi ni lông rất khó phân hủy trong tự nhiên nên để bảo vệ môi trường, mọi người khi đi mua sắm tốt nhất nên tự mang túi vải."}],"related":[{"hanzi":"垃圾桶","pinyin":"lājītǒng","vi":"Thùng rác"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"Ô nhiễm"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"购物","pinyin":"gòuwù","vi":"Mua sắm"}]},{"id":"随便","hanzi":"随便","pinyin":"suíbiàn","meaning_vi":"tùy ý, tự nhiên, thoải mái","explanation":"随 (theo) + 便 (tiện).","hsk_level":3,"tags":["tinh-tu","pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"请坐，随便一点儿，别客气。","pinyin":"Qǐngzuò, suíbiàn yìdiǎnr, biékèqi.","vi":"Mời ngồi, cứ tự nhiên một chút, đừng khách sáo."},{"type":"simple","zh":"中午吃什么都可以，我比较随便，你来决定吧。","pinyin":"Zhōngwǔ chī shénme dōu kěyǐ, wǒ bǐjiào suíbiàn, nǐ lái juédìng ba.","vi":"Buổi trưa ăn gì cũng được, tôi khá dễ tính, bạn quyết định đi."},{"type":"compound","zh":"在图书馆里看书时，大家千万不要随便乱放看完的书，应该放回原处。","pinyin":"Zài túshūguǎn lǐ kànshū shí, dàjiā qiānwàn bú yào suíbiàn luàn fàng kàn wán de shū, yīnggāi fàng huí yuánchù.","vi":"Lúc đọc sách trong thư viện, mọi người tuyệt đối đừng đặt bừa sách đã đọc xong, nên trả lại đúng vị trí cũ."}],"related":[{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"},{"hanzi":"顺便","pinyin":"shùnbiàn","vi":"Tiện thể"},{"hanzi":"随着","pinyin":"suízhe","vi":"Cùng với"},{"hanzi":"自由","pinyin":"zìyóu","vi":"Tự do"},{"hanzi":"客气","pinyin":"kèqi","vi":"Khách sáo"}],"traditional":"隨便"},{"id":"随着","hanzi":"随着","pinyin":"suízhe","meaning_vi":"cùng với, theo đà","explanation":"随 (đi theo) + 着.","hsk_level":3,"tags":["gioi-tu"],"image":"🌊","examples":[{"type":"basic","zh":"随着时间的推移，一切都会变好。","pinyin":"Suízhe shíjiān de tuīyí, yíqiè dōuhuì biàn hǎo.","vi":"Cùng với sự trôi qua của thời gian, mọi thứ đều sẽ tốt đẹp lên."},{"type":"simple","zh":"随着年龄的增长，我越来越理解父母当年对我的严格要求了。","pinyin":"Suízhe niánlíng de zēngzhǎng, wǒ yuèláiyuè lǐjiě fùmǔ dāngnián duì wǒ de yángé yāoqiú le.","vi":"Cùng với sự tăng lên của tuổi tác, tôi ngày càng thấu hiểu những yêu cầu nghiêm khắc của bố mẹ dành cho mình năm xưa."},{"type":"compound","zh":"随着中国经济的快速发展，世界上学习汉语的外国人也越来越多。","pinyin":"Suízhe Zhōngguó jīngjì de kuàisù fāzhǎn, shìjiè shang xuéxí Hànyǔ de wàiguórén yě yuèláiyuè duō.","vi":"Cùng với sự phát triển nhanh chóng của kinh tế Trung Quốc, số người nước ngoài học tiếng Trung trên thế giới cũng ngày càng đông."}],"related":[{"hanzi":"随便","pinyin":"suíbiàn","vi":"Tùy ý"},{"hanzi":"着","pinyin":"zhe","vi":"Đang"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"},{"hanzi":"变化","pinyin":"biànhuà","vi":"Thay đổi"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"}],"traditional":"隨著"},{"id":"孙子","hanzi":"孙子","pinyin":"sūnzi","meaning_vi":"cháu nội (trai)","explanation":"孙 (cháu) + hậu tố 子.","hsk_level":3,"tags":["danh-tu","gia-dinh"],"image":"👦","examples":[{"type":"basic","zh":"爷爷非常疼爱他的小孙子。","pinyin":"Yéye fēicháng téng'ài tā de xiǎo sūnzi.","vi":"Ông nội vô cùng yêu thương đứa cháu nội nhỏ của mình."},{"type":"simple","zh":"每天下午放学以后，奶奶都会准时去小学门口接孙子回家。","pinyin":"Měitiān xiàwǔ fàngxué yǐhòu, nǎinai dōuhuì zhǔnshí qù xiǎoxué ménkǒu jiē sūnzi huíjiā.","vi":"Mỗi chiều sau khi tan học, bà nội đều đúng giờ ra cổng trường tiểu học đón cháu nội về nhà."},{"type":"compound","zh":"虽然爷爷年纪大了，但是只要一看到小孙子跑过来，他就会开心得笑出声来。","pinyin":"Suīrán yéye niánjì dà le, dànshì zhǐyào yí kàndào xiǎo sūnzi pǎo guòlái, tā jiù huì kāi xīnde xiào chūshēng lái.","vi":"Tuy ông nội tuổi đã cao nhưng chỉ cần nhìn thấy cháu nội chạy tới là ông lại vui mừng bật cười thành tiếng."}],"related":[{"hanzi":"爷爷","pinyin":"yéye","vi":"Ông nội"},{"hanzi":"奶奶","pinyin":"nǎinai","vi":"Bà nội"},{"hanzi":"儿子","pinyin":"érzi","vi":"Con trai"},{"hanzi":"孩子","pinyin":"háizi","vi":"Trẻ em"},{"hanzi":"家人","pinyin":"jiārén","vi":"Người nhà"}],"traditional":"孫子"},{"id":"所有","hanzi":"所有","pinyin":"suǒyǒu","meaning_vi":"tất cả, toàn bộ","explanation":"所 + 有 (có) → tất cả những gì hiện có.","hsk_level":3,"tags":["tinh-tu","dai-tu"],"image":"🌐","examples":[{"type":"basic","zh":"所有的学生都来了。","pinyin":"Suǒyǒu de xuésheng dōu lái le.","vi":"Tất cả học sinh đều đã đến rồi."},{"type":"simple","zh":"为了准备这次考试，他把课本里所有的生词和语法都复习了一遍。","pinyin":"Wèile zhǔnbèi zhè cì kǎoshì, tā bǎ kèběn lǐ suǒyǒu de shēngcí hé yǔfǎ dōu fùxíle yíbiàn.","vi":"Để chuẩn bị cho kỳ thi lần này, cậu ấy đã ôn lại một lượt toàn bộ từ mới và ngữ pháp trong sách giáo khoa."},{"type":"compound","zh":"虽然这个城市我并不是所有地方都去过，但是有名的景点我几乎都参观了。","pinyin":"Suīrán zhè ge chéngshì wǒ bìngbú shì suǒyǒu dìfang dōu qù guo, dànshì yǒumíng de jǐngdiǎn wǒ jīhū dōu cānguān le.","vi":"Tuy thành phố này không phải nơi nào tôi cũng từng đi qua nhưng các danh thắng nổi tiếng thì tôi hầu như đều đã tham quan."}],"related":[{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"一切","pinyin":"yíqiè","vi":"Mọi thứ"},{"hanzi":"有","pinyin":"yǒu","vi":"Có"},{"hanzi":"都","pinyin":"dōu","vi":"Đều"},{"hanzi":"厕所","pinyin":"cèsuǒ","vi":"Nhà vệ sinh"}]},{"id":"台","hanzi":"台","pinyin":"tái","meaning_vi":"chiếc, cái (lượng từ máy móc)","explanation":"Lượng từ cho tivi, máy tính, điều hòa (一台电脑).","hsk_level":3,"tags":["luong-tu","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"我买了一台新电脑。","pinyin":"Wǒ mǎile yì tái xīn diànnǎo.","vi":"Tôi đã mua một chiếc máy tính mới."},{"type":"simple","zh":"我们家客厅里放着一台五十寸的液晶电视，看电影特别清楚。","pinyin":"Wǒmen jiā kètīng lǐ fàngzhe yì tái wǔshí cùn de yèjīng diànshì, kàndiànyǐng tèbié qīngchu.","vi":"Phòng khách nhà tôi đặt một chiếc tivi màn hình tinh thể lỏng 50 inch, xem phim đặc biệt rõ nét."},{"type":"compound","zh":"虽然这台旧空调已经用了十多年了，但是制冷效果依然非常好。","pinyin":"Suīrán zhè tái jiù kōngtiáo yǐjīng yòngle shí duōnián le, dànshì zhìlěng xiàoguǒ yīrán fēicháng hǎo.","vi":"Tuy chiếc điều hòa cũ này đã dùng hơn mười năm rồi nhưng hiệu quả làm lạnh vẫn vô cùng tốt."}],"related":[{"hanzi":"电脑","pinyin":"diànnǎo","vi":"Máy tính"},{"hanzi":"电视","pinyin":"diànshì","vi":"Tivi"},{"hanzi":"空调","pinyin":"kōngtiáo","vi":"Điều hòa"},{"hanzi":"抬","pinyin":"tái","vi":"Khiêng/Ngẩng"},{"hanzi":"个","pinyin":"gè","vi":"Cái"}],"traditional":"臺"},{"id":"抬","hanzi":"抬","pinyin":"tái","meaning_vi":"ngẩng, khiêng, nhấc lên","explanation":"Bộ tài gảy 扌+ 台. Cụm: 抬头 (ngẩng đầu).","hsk_level":3,"tags":["dong-tu"],"image":"⬆️","examples":[{"type":"basic","zh":"请大家抬起头看黑板。","pinyin":"Qǐng dàjiā tái qǐtóu kàn hēibǎn.","vi":"Xin mọi người ngẩng đầu lên nhìn bảng đen."},{"type":"simple","zh":"这张实木桌子太重了，需要两个人一起用力才能抬得动。","pinyin":"Zhè zhāng shímù zhuōzi tài zhòng le, xūyào liǎng ge rén yìqǐ yònglì cáinéng tái de dòng.","vi":"Chiếc bàn gỗ thịt này nặng quá, cần hai người cùng dùng sức mới khiêng nổi."},{"type":"compound","zh":"他一边走路一边低头看手机，结果一抬头差点儿撞到了前面的大树上。","pinyin":"Tā yìbiān zǒulù yìbiān dītóu kàn shǒujī, jiéguǒ yì táitóu chàdiǎnr zhuàng dàole qiánmiàn de dà shù shang.","vi":"Anh ấy vừa đi bộ vừa cúi đầu xem điện thoại, kết quả vừa ngẩng đầu lên thì suýt va phải cái cây lớn phía trước."}],"related":[{"hanzi":"台","pinyin":"tái","vi":"Chiếc (lượng từ)"},{"hanzi":"搬","pinyin":"bān","vi":"Chuyển/Bê"},{"hanzi":"拉","pinyin":"lā","vi":"Kéo"},{"hanzi":"推","pinyin":"tuī","vi":"Đẩy"},{"hanzi":"头","pinyin":"tóu","vi":"Đầu"}]},{"id":"态度","hanzi":"态度","pinyin":"tàidu","meaning_vi":"thái độ","explanation":"态 (dáng vẻ) + 度 (mức độ).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"他的学习态度很认真。","pinyin":"Tā de xuéxí tàidu hěn rènzhēn.","vi":"Thái độ học tập của cậu ấy rất nghiêm túc."},{"type":"simple","zh":"这家饭店的服务员对待每一位客人的态度都非常热情周到。","pinyin":"Zhè jiā fàndiàn de fúwùyuán duìdài měi yí wèi kèrén de tàidu dōu fēicháng rèqíng zhōudào.","vi":"Thái độ của nhân viên phục vụ nhà hàng này đối với mỗi vị khách đều vô cùng niềm nở chu đáo."},{"type":"compound","zh":"遇到困难时，积极乐观的态度往往比单纯的能力更能帮助我们走出困境。","pinyin":"Yùdào kùnnan shí, jījí lèguān de tàidu wǎngwǎng bǐ dānchún de nénglì gèng néng bāngzhù wǒmen zǒuchū kùnjìng.","vi":"Khi gặp khó khăn, thái độ tích cực lạc quan thường giúp chúng ta vượt qua nghịch cảnh tốt hơn cả năng lực đơn thuần."}],"related":[{"hanzi":"温度","pinyin":"wēndù","vi":"Nhiệt độ"},{"hanzi":"速度","pinyin":"sùdù","vi":"Tốc độ"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"服务员","pinyin":"fúwùyuán","vi":"Phục vụ"}],"traditional":"態度"},{"id":"谈","hanzi":"谈","pinyin":"tán","meaning_vi":"nói chuyện, bàn bạc, đàm luận","explanation":"Bộ ngôn 讠+ 炎. Cụm: 谈话 (nói chuyện).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"我们坐下来慢慢谈吧。","pinyin":"Wǒmen zuò xiàlái mànmàn tán ba.","vi":"Chúng ta ngồi xuống từ từ nói chuyện nhé."},{"type":"simple","zh":"经理正在会议室里跟几位重要客户谈明年的合作计划。","pinyin":"Jīnglǐ zhèngzài huìyìshì lǐ gēn jǐ wèi zhòngyào kèhù tán míngnián de hézuò jìhuà.","vi":"Giám đốc đang trong phòng họp bàn bạc kế hoạch hợp tác năm sau với vài khách hàng quan trọng."},{"type":"compound","zh":"因为我们俩有很多共同的爱好，所以每次见面都有谈不完的话题。","pinyin":"Yīnwèi wǒmen liǎ yǒu hěn duō gòngtóng de àihào, suǒyǐ měi cì jiànmiàn dōu yǒu tán bù wán de huàtí.","vi":"Vì hai đứa chúng tôi có nhiều sở thích chung nên mỗi lần gặp mặt đều có những chủ đề nói mãi không hết."}],"related":[{"hanzi":"说话","pinyin":"shuōhuà","vi":"Nói chuyện"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"Trò chuyện"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"Thảo luận"},{"hanzi":"商量","pinyin":"shāngliang","vi":"Bàn bạc"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"}],"traditional":"談"},{"id":"弹钢琴","hanzi":"弹钢琴","pinyin":"tángāngqín","meaning_vi":"chơi đàn piano","explanation":"弹 (gảy/đánh đàn) + 钢琴 (đàn dương cầm).","hsk_level":3,"tags":["dong-tu","giai-tri"],"image":"🎹","examples":[{"type":"basic","zh":"妹妹每天都练习弹钢琴。","pinyin":"Mèimei měitiān dōu liànxí tángāngqín.","vi":"Em gái ngày nào cũng luyện tập chơi đàn piano."},{"type":"simple","zh":"她从五岁开始学习弹钢琴，现在已经能演奏很多世界名曲了。","pinyin":"Tā cóng wǔ suì kāishǐ xuéxí tángāngqín, xiànzài yǐjīng néng yǎnzòu hěn duō shìjiè míngqǔ le.","vi":"Cô ấy bắt đầu học chơi đàn piano từ năm 5 tuổi, hiện tại đã có thể biểu diễn nhiều bản nhạc nổi tiếng thế giới."},{"type":"compound","zh":"虽然每天练习弹钢琴很辛苦，但是当美妙的音乐响起时，她觉得一切都值得。","pinyin":"Suīrán měitiān liànxí tángāngqín hěn xīnkǔ, dànshì dāng měimiào de yīnyuè xiǎngqǐ shí, tā juéde yíqiè dōu zhíde.","vi":"Tuy mỗi ngày luyện tập chơi đàn piano rất vất vả nhưng khi tiếng nhạc du dương vang lên, cô ấy thấy mọi thứ đều xứng đáng."}],"related":[{"hanzi":"音乐","pinyin":"yīnyuè","vi":"Âm nhạc"},{"hanzi":"唱歌","pinyin":"chànggē","vi":"Ca hát"},{"hanzi":"跳舞","pinyin":"tiàowǔ","vi":"Nhảy múa"},{"hanzi":"艺术","pinyin":"yìshù","vi":"Nghệ thuật"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"}],"traditional":"彈鋼琴"},{"id":"汤","hanzi":"汤","pinyin":"tāng","meaning_vi":"canh, súp","explanation":"Bộ thủy 氵+ 易.","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"妈妈做的西红柿鸡蛋汤很好喝。","pinyin":"Māma zuò de xīhóngshì jīdàn tāng hěn hǎohē.","vi":"Món canh trứng cà chua mẹ nấu rất ngon."},{"type":"simple","zh":"中国南方人吃饭的时候，习惯先喝一碗热汤再开始吃菜。","pinyin":"Zhōngguó nánfāng rén chīfàn de shíhou, xíguàn xiān hē yì wǎn rè tāng zài kāishǐ chī cài.","vi":"Người miền Nam Trung Quốc khi ăn cơm có thói quen uống một bát canh nóng trước rồi mới bắt đầu ăn thức ăn."},{"type":"compound","zh":"外面天气这么冷，回家以后喝上一碗热乎乎的鸡汤，浑身立刻就暖和了。","pinyin":"Wàimiàn tiānqì zhème lěng, huíjiā yǐhòu hē shàng yì wǎn rèhūhū de jītāng, húnshēn lìkè jiù nuǎnhuo le.","vi":"Thời tiết bên ngoài lạnh thế này, về đến nhà húp một bát canh gà nóng hổi là cả người ấm áp lên ngay."}],"related":[{"hanzi":"勺子","pinyin":"sháozi","vi":"Cái thìa"},{"hanzi":"碗","pinyin":"wǎn","vi":"Cái bát"},{"hanzi":"菜","pinyin":"cài","vi":"Món ăn"},{"hanzi":"西红柿","pinyin":"xīhóngshì","vi":"Cà chua"},{"hanzi":"喝","pinyin":"hē","vi":"Uống"}],"traditional":"湯"},{"id":"糖","hanzi":"糖","pinyin":"táng","meaning_vi":"đường; kẹo","explanation":"Bộ mễ 米 (gạo/ngũ cốc) + 唐.","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍬","examples":[{"type":"basic","zh":"我喝咖啡不喜欢放糖。","pinyin":"Wǒ hē kāfēi bù xǐhuan fàng táng.","vi":"Tôi uống cà phê không thích cho đường."},{"type":"simple","zh":"过春节的时候，家家户户的桌子上都会摆满各种各样的糖果和点心。","pinyin":"Guò Chūnjié de shíhou, jiājiāhùhù de zhuōzi shang dōuhuì bǎimǎn gèzhǒng gèyàng de tángguǒ hé diǎnxin.","vi":"Dịp Tết Nguyên đán, trên bàn nhà nào cũng bày đầy đủ các loại bánh kẹo và điểm tâm."},{"type":"compound","zh":"虽然小孩子都喜欢吃糖，但是吃太多糖很容易蛀牙。","pinyin":"Suīrán xiǎoháizi dōu xǐhuan chī táng, dànshì chī tài duōtáng hěn róngyì zhùyá.","vi":"Tuy trẻ con đều thích ăn kẹo nhưng ăn quá nhiều kẹo rất dễ bị sâu răng."}],"related":[{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"盐","pinyin":"yán","vi":"Muối"},{"hanzi":"巧克力","pinyin":"qiǎokèlì","vi":"Sô cô la"},{"hanzi":"饼干","pinyin":"bǐnggān","vi":"Bánh quy"},{"hanzi":"蛋糕","pinyin":"dàngāo","vi":"Bánh kem"}]},{"id":"躺","hanzi":"躺","pinyin":"tǎng","meaning_vi":"nằm","explanation":"Bộ thân 身 + 尚.","hsk_level":3,"tags":["dong-tu","sinh-hoat"],"image":"🛌","examples":[{"type":"basic","zh":"他累得躺在床上睡着了。","pinyin":"Tā lèi de tǎng zài chuáng shang shuìzháo le.","vi":"Anh ấy mệt đến mức nằm trên giường ngủ thiếp đi rồi."},{"type":"simple","zh":"周末下午的时候，我最喜欢躺在客厅的沙发上看一本有趣的小说。","pinyin":"Zhōumò xiàwǔ de shíhou, wǒ zuì xǐhuan tǎng zài kètīng de shāfā shang kàn yì běn yǒuqù de xiǎoshuō.","vi":"Vào chiều cuối tuần, tôi thích nhất là nằm trên ghế sô pha phòng khách đọc một quyển tiểu thuyết thú vị."},{"type":"compound","zh":"医生建议大家不要躺在床上看书或者玩手机，那样对眼睛和颈椎都很不好。","pinyin":"Yīshēng jiànyì dàjiā bú yào tǎng zài chuáng shang kànshū huòzhě wán shǒujī, nàyàng duì yǎnjing hé jǐngzhuī dōu hěn bù hǎo.","vi":"Bác sĩ khuyên mọi người đừng nằm trên giường đọc sách hay chơi điện thoại, như vậy rất hại cho mắt và đốt sống cổ."}],"related":[{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Ngủ"},{"hanzi":"坐","pinyin":"zuò","vi":"Ngồi"},{"hanzi":"站","pinyin":"zhàn","vi":"Đứng"},{"hanzi":"沙发","pinyin":"shāfā","vi":"Ghế sô pha"},{"hanzi":"休息","pinyin":"xiūxi","vi":"Nghỉ ngơi"}]},{"id":"趟","hanzi":"趟","pinyin":"tàng","meaning_vi":"chuyến, lần (lượng từ)","explanation":"Bộ tẩu 走 + 尚. Lượng từ cho việc đi lại (去一趟北京).","hsk_level":3,"tags":["luong-tu","giao-thong"],"image":"🚆","examples":[{"type":"basic","zh":"我去年去了一趟北京。","pinyin":"Wǒ qùnián qùle yí tàng Běijīng.","vi":"Năm ngoái tôi đã đi một chuyến Bắc Kinh."},{"type":"simple","zh":"麻烦你跑一趟办公室，帮我把这份表格交给王老师。","pinyin":"Máfan nǐ pǎo yí tàng bàngōngshì, bāng wǒ bǎ zhè fèn biǎogé jiāogěi Wáng lǎoshī.","vi":"Phiền bạn chạy một chuyến lên văn phòng, giúp tôi nộp biểu mẫu này cho thầy Vương."},{"type":"compound","zh":"因为忘记带护照了，所以我不得不打车回家取了一趟，差点儿误了飞机。","pinyin":"Yīnwèi wàngjì dài hùzhào le, suǒyǐ wǒ bùdébù dǎchē huíjiā qǔle yí tàng, chàdiǎnr wùle fēijī.","vi":"Vì quên mang hộ chiếu nên tôi đành phải bắt taxi về nhà lấy một chuyến, suýt nữa thì lỡ chuyến bay."}],"related":[{"hanzi":"次","pinyin":"cì","vi":"Lần"},{"hanzi":"遍","pinyin":"biàn","vi":"Lượt"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"出差","pinyin":"chūchāi","vi":"Đi công tác"},{"hanzi":"航班","pinyin":"hángbān","vi":"Chuyến bay"}]},{"id":"讨论","hanzi":"讨论","pinyin":"tǎolùn","meaning_vi":"thảo luận, bàn luận","explanation":"讨 (nghiên cứu) + 论 (bàn bạc).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"同学们正在讨论这个问题。","pinyin":"Tóngxuémen zhèngzài tǎolùn zhè ge wèntí.","vi":"Các bạn học đang thảo luận vấn đề này."},{"type":"simple","zh":"上口语课的时候，老师经常把大家分成几个小组进行话题讨论。","pinyin":"Shàng kǒuyǔ kè de shíhou, lǎoshī jīngcháng bǎ dàjiā fēnchéng jǐ ge xiǎozǔ jìnxíng huàtí tǎolùn.","vi":"Trong giờ học khẩu ngữ, thầy giáo thường chia mọi người thành vài nhóm nhỏ để thảo luận chủ đề."},{"type":"compound","zh":"经过大家两个小时的热烈讨论，我们终于找到了解决这个难题的最佳方案。","pinyin":"Jīngguò dàjiā liǎng ge xiǎoshí de rèliè tǎolùn, wǒmen zhōngyú zhǎodàole jiějué zhè ge nántí de zuì jiā fāng'àn.","vi":"Sau hai tiếng đồng hồ thảo luận sôi nổi của mọi người, chúng tôi cuối cùng đã tìm ra phương án tối ưu giải quyết bài toán khó này."}],"related":[{"hanzi":"商量","pinyin":"shāngliang","vi":"Bàn bạc"},{"hanzi":"谈","pinyin":"tán","vi":"Nói chuyện"},{"hanzi":"无论","pinyin":"wúlùn","vi":"Bất kể"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"问题","pinyin":"wèntí","vi":"Vấn đề"}],"traditional":"討論"},{"id":"讨厌","hanzi":"讨厌","pinyin":"tǎoyàn","meaning_vi":"ghét, chán ghét","explanation":"讨 + 厌 (chán). Đối nghĩa với 喜欢 (thích).","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"我最讨厌下雨天了。","pinyin":"Wǒ zuì tǎoyàn xià yǔtiān le.","vi":"Tôi ghét nhất là ngày trời mưa."},{"type":"simple","zh":"在公共场所大声说话或者乱扔垃圾的人，最让人讨厌。","pinyin":"Zài gōnggòngchǎngsuǒ dàshēng shuōhuà huòzhě luànrēng lājī de rén, zuì ràng rén tǎoyàn.","vi":"Những người nói chuyện ồn ào hoặc vứt rác bừa bãi ở nơi công cộng là đáng ghét nhất."},{"type":"compound","zh":"虽然以前我很讨厌吃苦瓜，但是知道它对健康有益以后也慢慢习惯吃了。","pinyin":"Suīrán yǐqián wǒ hěn tǎoyàn chīkǔ guā, dànshì zhīdao tā duì jiànkāng yǒuyì yǐhòu yě mànmàn xíguàn chī le.","vi":"Tuy trước đây tôi rất ghét ăn mướp đắng nhưng sau khi biết nó tốt cho sức khỏe thì cũng dần quen ăn rồi."}],"related":[{"hanzi":"喜欢","pinyin":"xǐhuan","vi":"Thích"},{"hanzi":"爱","pinyin":"ài","vi":"Yêu"},{"hanzi":"厌倦","pinyin":"yànjuàn","vi":"Chán ngán"},{"hanzi":"无聊","pinyin":"wúliáo","vi":"Nhàm chán"},{"hanzi":"生气","pinyin":"shēngqì","vi":"Tức giận"}],"traditional":"討厭"},{"id":"特点","hanzi":"特点","pinyin":"tèdiǎn","meaning_vi":"đặc điểm","explanation":"特 (đặc biệt) + 点 (điểm).","hsk_level":3,"tags":["danh-tu"],"image":"✨","examples":[{"type":"basic","zh":"每个季节都有自己的特点。","pinyin":"Měi ge jìjié dōu yǒu zìjǐ de tèdiǎn.","vi":"Mỗi mùa đều có đặc điểm riêng của mình."},{"type":"simple","zh":"中国各个地方的饮食文化都有各自鲜明的特点，比如川菜辣、粤菜清淡。","pinyin":"Zhōngguó gège dìfang de yǐnshí wénhuà dōu yǒu gèzì xiānmíng de tèdiǎn, bǐrú Chuāncài là, Yuècài qīngdàn.","vi":"Văn hóa ẩm thực từng vùng miền Trung Quốc đều có đặc điểm rõ nét riêng, ví dụ món Tứ Xuyên cay, món Quảng Đông thanh đạm."},{"type":"compound","zh":"写文章介绍一个人的时候，一定要抓住他最突出的性格特点来描写。","pinyin":"Xiě wénzhāng jièshào yígerén de shíhou, yídìngyào zhuāzhù tā zuì tūchū de xìnggé tèdiǎn lái miáoxiě.","vi":"Khi viết bài văn giới thiệu về một người, nhất định phải nắm bắt được đặc điểm tính cách nổi bật nhất của người đó để miêu tả."}],"related":[{"hanzi":"特别","pinyin":"tèbié","vi":"Đặc biệt"},{"hanzi":"优点","pinyin":"yōudiǎn","vi":"Ưu điểm"},{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"Khuyết điểm"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"Trọng điểm"},{"hanzi":"性格","pinyin":"xìnggé","vi":"Tính cách"}],"traditional":"特點"},{"id":"提","hanzi":"提","pinyin":"tí","meaning_vi":"xách, nhắc đến, nêu ra","explanation":"Bộ tài gảy 扌+ 是.","hsk_level":3,"tags":["dong-tu"],"image":"👜","examples":[{"type":"basic","zh":"他手里提着一个大箱子。","pinyin":"Tā shǒulǐ tízhe yí ge dà xiāngzi.","vi":"Trong tay anh ấy đang xách một cái thùng lớn."},{"type":"simple","zh":"上课的时候，老师鼓励大家积极举手提问题，不用害怕说错。","pinyin":"Shàngkè de shíhou, lǎoshī gǔlì dàjiā jījí jǔ shǒutí wèntí, bú yòng hàipà shuō cuò.","vi":"Trong giờ học, thầy giáo khuyến khích mọi người tích cực giơ tay đặt câu hỏi, không cần sợ nói sai."},{"type":"compound","zh":"既然他已经决定离开这里去外地发展了，我们就不要再提那件伤心事了。","pinyin":"Jìrán tā yǐjīng juédìng líkāi zhèlǐ qù wàidì fāzhǎn le, wǒmen jiù bú yào zài tí nà jiàn shāngxīnshì le.","vi":"Vì anh ấy đã quyết định rời khỏi đây để đi nơi khác phát triển rồi, chúng ta đừng nhắc lại chuyện buồn đó nữa."}],"related":[{"hanzi":"提高","pinyin":"tígāo","vi":"Nâng cao"},{"hanzi":"提供","pinyin":"tígōng","vi":"Cung cấp"},{"hanzi":"提前","pinyin":"tíqián","vi":"Trước thời hạn"},{"hanzi":"提醒","pinyin":"tíxǐng","vi":"Nhắc nhở"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm"}]},{"id":"提供","hanzi":"提供","pinyin":"tígōng","meaning_vi":"cung cấp","explanation":"提 (đưa ra) + 供 (cung ứng).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📦","examples":[{"type":"basic","zh":"图书馆免费提供学习资料。","pinyin":"Túshūguǎn miǎnfèi tígōng xuéxí zīliào.","vi":"Thư viện cung cấp miễn phí tài liệu học tập."},{"type":"simple","zh":"这家五星级宾馆为所有入住的客人提供免费早餐和机场接送服务。","pinyin":"Zhè jiā wǔxīngjí bīnguǎn wéi suǒyǒu rùzhù de kèrén tígōng miǎnfèi zǎocān hé jīchǎng jiēsòng fúwù.","vi":"Khách sạn 5 sao này cung cấp bữa sáng miễn phí và dịch vụ đưa đón sân bay cho tất cả khách lưu trú."},{"type":"compound","zh":"感谢学校为外国留学生提供了这么好的学习环境和丰富的奖学金机会。","pinyin":"Gǎnxiè xuéxiào wéi wàiguó liúxuésheng tígōngle zhème hǎo de xuéxí huánjìng hé fēngfù de jiǎngxuéjīn jīhuì.","vi":"Cảm ơn nhà trường đã cung cấp môi trường học tập tốt và cơ hội học bổng phong phú cho du học sinh nước ngoài."}],"related":[{"hanzi":"提","pinyin":"tí","vi":"Đưa ra"},{"hanzi":"供应","pinyin":"gōngyìng","vi":"Cung ứng"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"服务","pinyin":"fúwù","vi":"Phục vụ"},{"hanzi":"机会","pinyin":"jīhuì","vi":"Cơ hội"}]},{"id":"提前","hanzi":"提前","pinyin":"tíqián","meaning_vi":"trước thời hạn, sớm hơn dự kiến","explanation":"提 (đưa) + 前 (trước).","hsk_level":3,"tags":["dong-tu","thoi-gian"],"image":"⏪","examples":[{"type":"basic","zh":"会议提前十分钟开始了。","pinyin":"Huìyì tíqián shí fēnzhōng kāishǐ le.","vi":"Cuộc họp đã bắt đầu sớm hơn 10 phút."},{"type":"simple","zh":"因为春节期间火车票非常紧张，所以我们最好提前半个月在网上预订。","pinyin":"Yīnwèi Chūnjié qījiān huǒchēpiào fēicháng jǐnzhāng, suǒyǐ wǒmen zuìhǎo tíqián bàn geyuè zài wǎngshang yùdìng.","vi":"Vì dịp Tết vé tàu hỏa vô cùng khan hiếm nên tốt nhất chúng ta đặt trước trên mạng nửa tháng."},{"type":"compound","zh":"虽然今天早上路上有点儿堵车，但是因为我提前出发了，所以并没有迟到。","pinyin":"Suīrán jīntiān zǎoshang lùshang yǒudiǎnr dǔchē, dànshì yīnwèi wǒ tíqián chūfā le, suǒyǐ bìng méiyǒu chídào.","vi":"Tuy sáng nay trên đường hơi tắc xe nhưng vì tôi xuất phát sớm hơn dự kiến nên không hề bị muộn."}],"related":[{"hanzi":"推迟","pinyin":"tuīchí","vi":"Hoãn lại"},{"hanzi":"前","pinyin":"qián","vi":"Trước"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"提","pinyin":"tí","vi":"Nêu/Đưa"}]},{"id":"提醒","hanzi":"提醒","pinyin":"tíxǐng","meaning_vi":"nhắc nhở","explanation":"提 (nêu) + 醒 (tỉnh táo).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🔔","examples":[{"type":"basic","zh":"谢谢你的提醒！","pinyin":"Xièxie nǐ de tíxǐng!","vi":"Cảm ơn lời nhắc nhở của bạn!"},{"type":"simple","zh":"妈妈每天早上都会提醒我出门前检查好手机、钥匙和钱包。","pinyin":"Māma měitiān zǎoshang dōuhuì tíxǐng wǒ chū ménqián jiǎnchá hǎo shǒujī, yàoshi hé qiánbāo.","vi":"Mẹ mỗi sáng đều nhắc nhở tôi trước khi ra khỏi nhà kiểm tra kỹ điện thoại, chìa khóa và ví tiền."},{"type":"compound","zh":"幸亏你刚才及时提醒了我，不然我差点儿就忘记今天下午要开会了。","pinyin":"Xìngkuī nǐ gāngcái jíshí tíxǐngle wǒ, bùrán wǒ chàdiǎnr jiù wàngjì jīntiān xiàwǔ yào kāihuì le.","vi":"May mà vừa nãy bạn nhắc nhở tôi kịp thời, nếu không suýt nữa tôi đã quên mất chiều nay phải họp."}],"related":[{"hanzi":"醒","pinyin":"xǐng","vi":"Tỉnh giấc"},{"hanzi":"提","pinyin":"tí","vi":"Nhắc đến"},{"hanzi":"记得","pinyin":"jìde","vi":"Nhớ"},{"hanzi":"忘记","pinyin":"wàngjì","vi":"Quên"},{"hanzi":"注意","pinyin":"zhùyì","vi":"Chú ý"}]},{"id":"填空","hanzi":"填空","pinyin":"tiánkòng","meaning_vi":"điền vào chỗ trống","explanation":"填 (lấp đầy) + 空 (chỗ trống). Thuật ngữ trong bài thi.","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"请完成这些填空题。","pinyin":"Qǐng wánchéng zhèxiē tiánkòng tí.","vi":"Xin hãy hoàn thành những câu hỏi điền vào chỗ trống này."},{"type":"simple","zh":"做汉语阅读填空题时，不仅要看懂句子的意思，还要注意词语的搭配。","pinyin":"Zuò Hànyǔ yuèdú tiánkòng tí shí, bùjǐn yào kàndǒng jùzi de yìsi, hái yào zhùyì cíyǔ de dāpèi.","vi":"Khi làm bài tập đọc hiểu điền từ tiếng Trung, không chỉ cần hiểu nghĩa câu mà còn phải chú ý cách kết hợp từ ngữ."},{"type":"compound","zh":"虽然这次考试的填空题有点儿难，但是因为我平时练习得多，所以全都填对了。","pinyin":"Suīrán zhè cì kǎoshì de tiánkòng tí yǒudiǎnr nán, dànshì yīnwèi wǒ píngshí liànxí de duō, suǒyǐ quándōu tián duìle.","vi":"Tuy phần điền từ của kỳ thi lần này hơi khó nhưng vì ngày thường tôi luyện tập nhiều nên đều điền đúng hết."}],"related":[{"hanzi":"空","pinyin":"kōng","vi":"Trống rỗng"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"},{"hanzi":"答案","pinyin":"dá'àn","vi":"Đáp án"}]},{"id":"条件","hanzi":"条件","pinyin":"tiáojiàn","meaning_vi":"điều kiện","explanation":"条 (mục) + 件 (việc).","hsk_level":3,"tags":["danh-tu"],"image":"📋","examples":[{"type":"basic","zh":"这里的生活条件很好。","pinyin":"Zhèlǐ de shēnghuó tiáojiàn hěn hǎo.","vi":"Điều kiện sinh hoạt ở đây rất tốt."},{"type":"simple","zh":"现在农村的交通和教育条件比几十年前改善了很多。","pinyin":"Xiànzài nóngcūn de jiāotōng hé jiàoyù tiáojiàn bǐ jǐ shí niánqián gǎishànle hěn duō.","vi":"Hiện nay điều kiện giao thông và giáo dục ở nông thôn đã cải thiện hơn nhiều so với mấy chục năm trước."},{"type":"compound","zh":"只要你符合申请条件，就可以向学校提交资料申请明年的留学生奖学金。","pinyin":"Zhǐyào nǐ fúhé shēnqǐng tiáojiàn, jiù kěyǐ xiàng xuéxiào tíjiāo zīliào shēnqǐng míngnián de liúxuésheng jiǎngxuéjīn.","vi":"Chỉ cần bạn đáp ứng đủ điều kiện đăng ký thì có thể nộp hồ sơ cho nhà trường để xin học bổng du học sinh năm sau."}],"related":[{"hanzi":"符合","pinyin":"fúhé","vi":"Phù hợp"},{"hanzi":"要求","pinyin":"yāoqiú","vi":"Yêu cầu"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"面条","pinyin":"miàntiáo","vi":"Mì sợi"},{"hanzi":"件","pinyin":"jiàn","vi":"Việc/Chiếc"}],"traditional":"條件"},{"id":"停","hanzi":"停","pinyin":"tíng","meaning_vi":"dừng, đỗ (xe), ngừng","explanation":"Bộ nhân đứng 亻+ 亭.","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"🛑","examples":[{"type":"basic","zh":"外面雨已经停了。","pinyin":"Wàimiàn yǔ yǐjīng tíng le.","vi":"Bên ngoài mưa đã tạnh rồi."},{"type":"simple","zh":"马路边画有黄线的地方禁止停车，否则会被交通警察罚款。","pinyin":"Mǎ lùbiān huà yǒu huáng xiàn de dìfang jìnzhǐ tíngchē, fǒuzé huì bèi jiāotōng jǐngchá fákuǎn.","vi":"Những nơi kẻ vạch vàng bên vệ đường cấm đỗ xe, nếu không sẽ bị cảnh sát giao thông phạt tiền."},{"type":"compound","zh":"因为前方正在修路，所以这路公共汽车暂时停在下一个路口等乘客。","pinyin":"Yīnwèi qiánfāng zhèngzài xiūlù, suǒyǐ zhè lù gōnggòngqìchē zànshí tíng zài xiàyíge lùkǒu děng chéngkè.","vi":"Vì phía trước đang sửa đường nên tuyến xe buýt này tạm thời dừng ở ngã tư tiếp theo để đón hành khách."}],"related":[{"hanzi":"停止","pinyin":"tíngzhǐ","vi":"Ngừng lại"},{"hanzi":"停车场","pinyin":"tíngchēchǎng","vi":"Bãi đỗ xe"},{"hanzi":"车","pinyin":"chē","vi":"Xe"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"Cấm"},{"hanzi":"雨","pinyin":"yǔ","vi":"Mưa"}]},{"id":"挺","hanzi":"挺","pinyin":"tǐng","meaning_vi":"khá, rất (khẩu ngữ)","explanation":"Bộ tài gảy 扌+ 廷. Dùng trong cấu trúc 挺...的 (khá là...).","hsk_level":3,"tags":["pho-tu"],"image":"👍","examples":[{"type":"basic","zh":"我觉得这件衣服挺好看的。","pinyin":"Wǒ juéde zhè jiàn yīfu tǐng hǎokàn de.","vi":"Tôi thấy chiếc áo này khá là đẹp đấy."},{"type":"simple","zh":"虽然这家饭店地方不大，但是做的中国菜味道挺正宗的。","pinyin":"Suīrán zhè jiā fàndiàn dìfang búdà, dànshì zuò de Zhōngguócài wèidào tǐng zhèngzōng de.","vi":"Tuy nhà hàng này diện tích không lớn nhưng hương vị món ăn Trung Quốc nấu khá chuẩn vị."},{"type":"compound","zh":"他刚来中国不到半年，普通话就已经说得挺流利了，真让人佩服。","pinyin":"Tā gāng lái Zhōngguó búdào bàn nián, pǔtōnghuà jiù yǐjīng shuō de tǐng liúlì le, zhēn ràng rén pèifu.","vi":"Anh ấy mới đến Trung Quốc chưa đầy nửa năm mà tiếng phổ thông đã nói khá trôi chảy rồi, thật đáng khâm phục."}],"related":[{"hanzi":"比较","pinyin":"bǐjiào","vi":"Tương đối"},{"hanzi":"很","pinyin":"hěn","vi":"Rất"},{"hanzi":"非常","pinyin":"fēicháng","vi":"Vô cùng"},{"hanzi":"相当","pinyin":"xiāngdāng","vi":"Khá"},{"hanzi":"不错","pinyin":"búcuò","vi":"Khá tốt"}]},{"id":"通过","hanzi":"通过","pinyin":"tōngguò","meaning_vi":"thông qua, đi qua, thi đỗ","explanation":"通 (thông suốt) + 过 (qua).","hsk_level":3,"tags":["dong-tu","gioi-tu"],"image":"✅","examples":[{"type":"basic","zh":"我通过了HSK三级考试。","pinyin":"Wǒ tōng guò le HSK sān jí kǎo shì.","vi":"Tôi đã thi đỗ kỳ thi HSK cấp 3 rồi."},{"type":"simple","zh":"通过每天阅读中文报纸和听新闻广播，我的汉语水平提高了很多。","pinyin":"Tōngguò měitiān yuèdú Zhōngwén bàozhǐ hé tīng xīnwén guǎngbō, wǒ de Hànyǔ shuǐpíng tígāole hěn duō.","vi":"Thông qua việc đọc báo tiếng Trung và nghe đài tin tức mỗi ngày, trình độ tiếng Trung của tôi đã nâng cao rất nhiều."},{"type":"compound","zh":"只要你平时认真复习、多做练习题，就一定能够顺利通过这次期末考试。","pinyin":"Zhǐyào nǐ píngshí rènzhēn fùxí, duō zuò liànxí tí, jiù yídìng nénggòu shùnlì tōngguò zhè cì qīmò kǎoshì.","vi":"Chỉ cần ngày thường bạn chăm chỉ ôn tập và làm nhiều bài luyện tập thì nhất định sẽ thi đỗ kỳ thi cuối kỳ lần này."}],"related":[{"hanzi":"交通","pinyin":"jiāotōng","vi":"Giao thông"},{"hanzi":"经过","pinyin":"jīngguò","vi":"Đi qua"},{"hanzi":"过","pinyin":"guo","vi":"Qua"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"Thuận lợi"}],"traditional":"通過"},{"id":"通知","hanzi":"通知","pinyin":"tōngzhī","meaning_vi":"thông báo","explanation":"通 (truyền đạt) + 知 (biết). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","danh-tu"],"image":"📢","examples":[{"type":"basic","zh":"学校发了一个新通知。","pinyin":"Xuéxiào fāle yí ge xīn tōngzhī.","vi":"Nhà trường đã ra một thông báo mới."},{"type":"simple","zh":"请你马上打电话通知大家，明天上午的会议改在三楼会议室举行。","pinyin":"Qǐng nǐ mǎshàng dǎdiànhuà tōngzhī dàjiā, míngtiān shàngwǔ de huìyì gǎi zài sān lóu huìyìshì jǔxíng.","vi":"Xin bạn gọi điện thông báo ngay cho mọi người biết cuộc họp sáng mai đổi sang phòng họp tầng 3."},{"type":"compound","zh":"因为航班临时推迟了两个小时，所以航空公司已经发短信通知了所有乘客。","pinyin":"Yīnwèi hángbān línshí tuīchíle liǎng ge xiǎoshí, suǒyǐ hángkōng gōngsī yǐjīng fāduǎnxìn tōngzhīle suǒyǒu chéngkè.","vi":"Vì chuyến bay tạm thời lùi lại hai tiếng đồng hồ nên hãng hàng không đã nhắn tin thông báo cho toàn bộ hành khách."}],"related":[{"hanzi":"知道","pinyin":"zhīdao","vi":"Biết"},{"hanzi":"告诉","pinyin":"gàosu","vi":"Bảo/Nói cho"},{"hanzi":"消息","pinyin":"xiāoxi","vi":"Tin tức"},{"hanzi":"短信","pinyin":"duǎnxìn","vi":"Tin nhắn"},{"hanzi":"联系","pinyin":"liánxì","vi":"Liên hệ"}]},{"id":"同情","hanzi":"同情","pinyin":"tóngqíng","meaning_vi":"đồng cảm, thương cảm","explanation":"同 (cùng) + 情 (tình cảm).","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"大家都很同情他的遭遇。","pinyin":"Dàjiā dōu hěn tóngqíng tā de zāoyù.","vi":"Mọi người đều rất đồng cảm với hoàn cảnh của anh ấy."},{"type":"simple","zh":"看到路边那只受伤的小狗，善良的小女孩心里充满了同情。","pinyin":"Kàndào lùbiān nà zhī shòushāng de xiǎogǒu, shànliáng de xiǎo nǚhái xīnlǐ chōngmǎnle tóngqíng.","vi":"Nhìn thấy chú chó nhỏ bị thương bên đường, cô bé tốt bụng trào dâng lòng thương cảm."},{"type":"compound","zh":"虽然大家都很同情他丢了钱包的遭遇，但是更重要的还是赶紧帮他去警察局报案。","pinyin":"Suīrán dàjiā dōu hěn tóngqíng tā diūle qiánbāo de zāoyù, dànshì gèng zhòngyào de háishi gǎnjǐn bāng tā qù jǐngchájú bào'àn.","vi":"Tuy mọi người đều rất thông cảm với việc anh ấy bị mất ví nhưng quan trọng hơn vẫn là mau giúp anh tới đồn cảnh sát trình báo."}],"related":[{"hanzi":"可怜","pinyin":"kělián","vi":"Đáng thương"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"Thấu hiểu"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"}]},{"id":"同时","hanzi":"同时","pinyin":"tóngshí","meaning_vi":"đồng thời, cùng lúc","explanation":"同 (cùng) + 时 (thời điểm).","hsk_level":3,"tags":["lien-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"我们不能同时做两件事。","pinyin":"Wǒmen bù néng tóngshí zuò liǎng jiàn shì.","vi":"Chúng ta không thể làm hai việc cùng một lúc."},{"type":"simple","zh":"学习汉语的时候，我们要在提高听力水平的同时，加强口语表达练习。","pinyin":"Xuéxí Hànyǔ de shíhou, wǒmen yào zài tígāo tīnglì shuǐpíng de tóngshí, jiāqiáng kǒuyǔ biǎodá liànxí.","vi":"Khi học tiếng Trung, song song với việc nâng cao trình độ nghe, chúng ta cần tăng cường luyện tập diễn đạt khẩu ngữ."},{"type":"compound","zh":"发展经济虽然非常重要，但是与此同时我们也必须保护好自然环境。","pinyin":"Fāzhǎn jīngjì suīrán fēicháng zhòngyào, dànshì yǔcǐtóngshí wǒmen yě bìxū bǎohù hǎo zìrán huánjìng.","vi":"Tuy phát triển kinh tế vô cùng quan trọng nhưng đồng thời chúng ta cũng bắt buộc phải bảo vệ tốt môi trường tự nhiên."}],"related":[{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"共同","pinyin":"gòngtóng","vi":"Chung"},{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Giống nhau"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"Đồng thời"},{"hanzi":"一边","pinyin":"yìbiān","vi":"Vừa... vừa..."}],"traditional":"同時"},{"id":"推迟","hanzi":"推迟","pinyin":"tuīchí","meaning_vi":"hoãn lại, lùi lại","explanation":"推 (đẩy) + 迟 (muộn). Đối nghĩa với 提前 (sớm hơn).","hsk_level":3,"tags":["dong-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"比赛因为下雨推迟了。","pinyin":"Bǐsài yīnwèi xiàyǔ tuīchí le.","vi":"Trận đấu bị hoãn lại vì trời mưa."},{"type":"simple","zh":"因为王经理今天要去外地出差，所以原定的部门会议推迟到了下周一。","pinyin":"Yīnwèi Wáng jīnglǐ jīntiān yào qù wàidì chūchāi, suǒyǐ yuándìng de bùmén huìyì tuī chídàole xià Zhōuyī.","vi":"Vì hôm nay giám đốc Vương phải đi công tác xa nên cuộc họp phòng ban dự kiến đã hoãn sang thứ Hai tuần sau."},{"type":"compound","zh":"虽然航班推迟了一个小时让人有点儿着急，但是为了飞行安全大家都能理解。","pinyin":"Suīrán hángbān tuīchíle yí ge xiǎoshí ràng rén yǒudiǎnr zháojí, dànshì wèile fēixíng ānquán dàjiā dōu néng lǐjiě.","vi":"Tuy chuyến bay bị lùi lại một tiếng khiến mọi người hơi sốt ruột nhưng vì an toàn bay ai nấy đều thông cảm."}],"related":[{"hanzi":"提前","pinyin":"tíqián","vi":"Trước thời hạn"},{"hanzi":"推","pinyin":"tuī","vi":"Đẩy"},{"hanzi":"迟到","pinyin":"chídào","vi":"Đến muộn"},{"hanzi":"取消","pinyin":"qǔxiāo","vi":"Hủy bỏ"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"}],"traditional":"推遲"},{"id":"脱","hanzi":"脱","pinyin":"tuō","meaning_vi":"cởi (quần áo/giày dép)","explanation":"Bộ nguyệt ⺼+ 兑. Đối nghĩa với 穿 (mặc).","hsk_level":3,"tags":["dong-tu","trang-phuc"],"image":"🧥","examples":[{"type":"basic","zh":"房间里很暖和，把外套脱了吧。","pinyin":"Fángjiān lǐ hěn nuǎnhuo, bǎ wàitào tuōle ba.","vi":"Trong phòng ấm lắm, cởi áo khoác ra đi."},{"type":"simple","zh":"日本人和韩国人习惯在进家门之前先把鞋子脱在门口。","pinyin":"Rìběnrén hé Hánguórén xíguàn zài jìn jiāmén zhīqián xiān bǎ xiézi tuō zài ménkǒu.","vi":"Người Nhật Bản và người Hàn Quốc có thói quen cởi giày để ở cửa trước khi bước vào nhà."},{"type":"compound","zh":"虽然今天出了太阳，但是春天的风还是有点儿凉，千万别急着脱厚衣服。","pinyin":"Suīrán jīntiān chūle tàiyáng, dànshì chūntiān de fēng háishi yǒudiǎnr liáng, qiānwàn bié jízhe tuō hòu yīfu.","vi":"Tuy hôm nay trời có nắng nhưng gió mùa xuân vẫn hơi se lạnh, tuyệt đối đừng vội cởi bỏ quần áo dày."}],"related":[{"hanzi":"穿","pinyin":"chuān","vi":"Mặc"},{"hanzi":"戴","pinyin":"dài","vi":"Đeo/Đội"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"鞋","pinyin":"xié","vi":"Giày"},{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"Ấm áp"}],"traditional":"脫"},{"id":"袜子","hanzi":"袜子","pinyin":"wàzi","meaning_vi":"tất, vớ","explanation":"袜 (miệt – bít tất; bộ y 衤 quần áo + 末 mạt gợi âm) + 子 (tử – hậu tố danh từ) → tất, vớ. Lượng từ 双: 一双袜子.","hsk_level":3,"tags":["danh-tu","trang-phuc"],"image":"🧦","examples":[{"type":"basic","zh":"我买了几双新袜子。","pinyin":"Wǒ mǎile jǐ shuāng xīn wàzi.","vi":"Tôi đã mua vài đôi tất mới."},{"type":"simple","zh":"冬天天气冷的时候，穿一双厚一点儿的棉袜子会觉得脚很暖和。","pinyin":"Dōngtiān tiānqì lěng de shíhou, chuān yì shuāng hòu yìdiǎnr de mián wàzi huì juéde jiǎo hěn nuǎnhuo.","vi":"Mùa đông lúc trời lạnh, đi một đôi tất cotton dày một chút sẽ cảm thấy bàn chân rất ấm áp."},{"type":"compound","zh":"弟弟每天晚上洗完澡以后，都会自己把换下来的袜子和衣服洗干净。","pinyin":"Dìdi měitiān wǎnshang xǐ wán zǎo yǐhòu, dōuhuì zìjǐ bǎ huàn xiàlái de wàzi hé yīfu xǐ gānjìng.","vi":"Em trai mỗi tối sau khi tắm xong đều tự giặt sạch tất và quần áo vừa thay ra."}],"related":[{"hanzi":"鞋","pinyin":"xié","vi":"Giày"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"衬衫","pinyin":"chènshān","vi":"Áo sơ mi"},{"hanzi":"穿","pinyin":"chuān","vi":"Mặc/Đi"},{"hanzi":"脚","pinyin":"jiǎo","vi":"Bàn chân"}],"traditional":"襪子"},{"id":"完全","hanzi":"完全","pinyin":"wánquán","meaning_vi":"hoàn toàn","explanation":"完 (trọn) + 全 (đầy đủ).","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"💯","examples":[{"type":"basic","zh":"我完全同意你的看法。","pinyin":"Wǒ wánquán tóngyì nǐ de kànfǎ.","vi":"Tôi hoàn toàn đồng ý với cách nhìn của bạn."},{"type":"simple","zh":"这两个汉字虽然长得很像，但是它们的读音和意思却完全不同。","pinyin":"Zhè liǎng ge hànzì suīrán zhǎngde hěn xiàng, dànshì tāmen de dúyīn hé yìsi què wánquán bùtóng.","vi":"Hai chữ Hán này tuy trông rất giống nhau nhưng cách đọc và ý nghĩa của chúng lại hoàn toàn khác nhau."},{"type":"compound","zh":"经过半年的努力适应，他现在已经完全习惯了北京的饮食和气候。","pinyin":"Jīng guòbàn nián de nǔlì shìyìng, tā xiànzài yǐjīng wánquán xíguànle Běijīng de yǐnshí hé qìhòu.","vi":"Trải qua nửa năm nỗ lực thích nghi, bây giờ anh ấy đã hoàn toàn quen với ẩm thực và khí hậu Bắc Kinh."}],"related":[{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"Khẳng định"},{"hanzi":"一样","pinyin":"yíyàng","vi":"Giống nhau"}]},{"id":"网球","hanzi":"网球","pinyin":"wǎngqiú","meaning_vi":"quần vợt, tennis","explanation":"网 (cái lưới) + 球 (quả bóng).","hsk_level":3,"tags":["danh-tu","the-thao"],"image":"🎾","examples":[{"type":"basic","zh":"周末我常和朋友打网球。","pinyin":"Zhōumò wǒ cháng hé péngyou dǎ wǎngqiú.","vi":"Cuối tuần tôi thường chơi quần vợt với bạn bè."},{"type":"simple","zh":"我们学校体育馆旁边新建了四个标准网球场，每天都有很多人去打球。","pinyin":"Wǒmen xuéxiào tǐyùguǎn pángbiān xīnjiànle sì ge biāozhǔn wǎngqiúchǎng, měitiān dōu yǒu hěn duō rén qù dǎqiú.","vi":"Bên cạnh nhà thi đấu trường tôi mới xây bốn sân quần vợt tiêu chuẩn, ngày nào cũng có nhiều người đến chơi."},{"type":"compound","zh":"虽然打网球需要很大的体力，但是每次出完汗以后都觉得特别轻松愉快。","pinyin":"Suīrán dǎ wǎngqiú xūyào hěn dà de tǐlì, dànshì měi cì chū wán hàn yǐhòu dōu juéde tèbié qīngsōng yúkuài.","vi":"Tuy chơi quần vợt đòi hỏi nhiều thể lực nhưng mỗi lần ra mồ hôi xong đều cảm thấy đặc biệt nhẹ nhõm vui vẻ."}],"related":[{"hanzi":"乒乓球","pinyin":"pīngpāngqiú","vi":"Bóng bàn"},{"hanzi":"羽毛球","pinyin":"yǔmáoqiú","vi":"Cầu lông"},{"hanzi":"打篮球","pinyin":"dǎlánqiú","vi":"Chơi bóng rổ"},{"hanzi":"踢足球","pinyin":"tīzúqiú","vi":"Đá bóng"},{"hanzi":"网站","pinyin":"wǎngzhàn","vi":"Trang web"}],"traditional":"網球"},{"id":"网站","hanzi":"网站","pinyin":"wǎngzhàn","meaning_vi":"trang web, website","explanation":"网 (mạng) + 站 (trạm).","hsk_level":3,"tags":["danh-tu","cong-nghe"],"image":"🌐","examples":[{"type":"basic","zh":"我经常在这个网站学习汉语。","pinyin":"Wǒ jīngcháng zài zhè ge wǎngzhàn xuéxí Hànyǔ.","vi":"Tôi thường xuyên học tiếng Trung trên trang web này."},{"type":"simple","zh":"这个旅游网站上不仅有详细的景点介绍，还可以直接预订机票和宾馆。","pinyin":"Zhè ge lǚyóu wǎngzhàn shang bùjǐn yǒu xiángxì de jǐngdiǎn jièshào, hái kěyǐ zhíjiē yùdìng jīpiào hé bīnguǎn.","vi":"Trên trang web du lịch này không chỉ có giới thiệu chi tiết các điểm tham quan mà còn có thể đặt trực tiếp vé máy bay và khách sạn."},{"type":"compound","zh":"在陌生的网站上填写个人密码和银行卡信息时，一定要注意网络安全。","pinyin":"Zài mòshēng de wǎngzhàn shang tiánxiě gèrén mìmǎ hé yínhángkǎ xìnxī shí, yídìngyào zhùyì wǎngluò'ānquán.","vi":"Khi điền mật khẩu cá nhân và thông tin thẻ ngân hàng trên trang web lạ, nhất định phải chú ý an toàn mạng."}],"related":[{"hanzi":"网球","pinyin":"wǎngqiú","vi":"Quần vợt"},{"hanzi":"火车站","pinyin":"huǒchēzhàn","vi":"Ga tàu"},{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"电脑","pinyin":"diànnǎo","vi":"Máy tính"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"Mật khẩu"}],"traditional":"網站"},{"id":"往往","hanzi":"往往","pinyin":"wǎngwǎng","meaning_vi":"thường thường (có tính quy luật)","explanation":"Lặp lại chữ 往. Chỉ sự việc thường xảy ra trong điều kiện nhất định.","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"🔁","examples":[{"type":"basic","zh":"周末超市里的人往往很多。","pinyin":"Zhōumò chāoshì lǐ de rén wǎngwǎng hěn duō.","vi":"Cuối tuần người trong siêu thị thường rất đông."},{"type":"simple","zh":"一个平时学习认真、基础扎实的学生，考试时往往能取得好成绩。","pinyin":"Yí ge píngshí xuéxí rènzhēn, jīchǔ zhāshi de xuésheng, kǎoshì shí wǎngwǎng néng qǔdé hǎo chéngjì.","vi":"Một học sinh ngày thường chăm chỉ học tập, nền tảng vững chắc thì khi thi cử thường đạt được thành tích tốt."},{"type":"compound","zh":"人们在遇到困难的时候，往往更容易发现谁才是自己真正的好朋友。","pinyin":"Rénmen zài yùdào kùnnan de shíhou, wǎngwǎng gèng róngyì fāxiàn shéi cái shì zìjǐ zhēnzhèng de hǎopéngyou.","vi":"Con người khi gặp khó khăn thường dễ nhận ra ai mới thực sự là người bạn tốt của mình."}],"related":[{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"Luôn luôn"},{"hanzi":"往","pinyin":"wǎng","vi":"Về phía"},{"hanzi":"一般","pinyin":"yìbān","vi":"Thông thường"},{"hanzi":"平时","pinyin":"píngshí","vi":"Bình thường"}]},{"id":"味道","hanzi":"味道","pinyin":"wèidào","meaning_vi":"mùi vị, hương vị","explanation":"味 (vị) + 道 (đường/lối).","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"这道菜的味道真好！","pinyin":"Zhè dào cài de wèidào zhēn hǎo!","vi":"Hương vị của món ăn này ngon thật đấy!"},{"type":"simple","zh":"妈妈做的红烧鱼不仅颜色好看，而且味道也非常鲜美。","pinyin":"Māma zuò de hóngshāo yú bùjǐn yánsè hǎokàn, érqiě wèidào yě fēicháng xiānměi.","vi":"Món cá kho mẹ nấu không những màu sắc đẹp mắt mà hương vị cũng vô cùng tươi ngon."},{"type":"compound","zh":"虽然这家小面馆环境很一般，但是因为牛肉面的味道特别正宗，每天都排长队。","pinyin":"Suīrán zhè jiā xiǎo miànguǎn huánjìng hěn yìbān, dànshì yīnwèi niúròumiàn de wèidào tèbié zhèngzōng, měitiān dōu pái chángduì.","vi":"Tuy quán mì nhỏ này không gian rất bình thường nhưng vì hương vị mì bò đặc biệt chuẩn vị nên ngày nào cũng xếp hàng dài."}],"related":[{"hanzi":"香","pinyin":"xiāng","vi":"Thơm"},{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"辣","pinyin":"là","vi":"Cay"},{"hanzi":"咸","pinyin":"xián","vi":"Mặn"},{"hanzi":"酸","pinyin":"suān","vi":"Chua"}]},{"id":"温度","hanzi":"温度","pinyin":"wēndù","meaning_vi":"nhiệt độ","explanation":"温 (ấm áp) + 度 (độ).","hsk_level":3,"tags":["danh-tu","thoi-tiet"],"image":"🌡️","examples":[{"type":"basic","zh":"今天室外的温度有三十度。","pinyin":"Jīntiān shìwài de wēndù yǒu sānshí dù.","vi":"Hôm nay nhiệt độ ngoài trời lên tới 30 độ."},{"type":"simple","zh":"夏天开空调的时候，把温度设置在二十六度左右既凉快又省电。","pinyin":"Xiàtiān kāi kōngtiáo de shíhou, bǎ wēndù shèzhì zài èr shíliù dù zuǒyòu jì liángkuai yòu shěngdiàn.","vi":"Mùa hè khi bật điều hòa, cài đặt nhiệt độ ở khoảng 26 độ vừa mát mẻ lại tiết kiệm điện."},{"type":"compound","zh":"因为昨天晚上突然下了一场大雪，所以今天早上的温度一下子降到了零下五度。","pinyin":"Yīnwèi zuótiān wǎnshang tūrán xiàle yì chǎng Dàxuě, suǒyǐ jīntiān zǎoshang de wēndù yíxiàzi jiàng dàole língxià wǔdù.","vi":"Vì tối qua đột nhiên có một trận tuyết lớn nên sáng nay nhiệt độ giảm đột ngột xuống âm 5 độ."}],"related":[{"hanzi":"态度","pinyin":"tàidu","vi":"Thái độ"},{"hanzi":"速度","pinyin":"sùdù","vi":"Tốc độ"},{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"Ấm áp"},{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"}],"traditional":"溫度"},{"id":"文章","hanzi":"文章","pinyin":"wénzhāng","meaning_vi":"bài văn, bài viết","explanation":"文 (văn tự) + 章 (chương/bài).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"这篇文章写得非常生动。","pinyin":"Zhè piān wénzhāng xiě de fēicháng shēngdòng.","vi":"Bài văn này viết vô cùng sinh động."},{"type":"simple","zh":"老师让我们回家以后认真阅读这篇文章，并回答后面的五个问题。","pinyin":"Lǎoshī ràng wǒmen huíjiā yǐhòu rènzhēn yuèdú zhè piān wénzhāng, bìng huídá hòumiàn de wǔ ge wèntí.","vi":"Thầy giáo bảo chúng tôi sau khi về nhà hãy đọc kỹ bài văn này và trả lời năm câu hỏi phía sau."},{"type":"compound","zh":"虽然这篇文章的篇幅比较长，但是语言幽默有趣，我一口气就读完了。","pinyin":"Suīrán zhè piān wénzhāng de piānfú bǐjiào cháng, dànshì yǔyán yōumò yǒuqù, wǒ yìkǒuqì jiùdú wánle.","vi":"Tuy độ dài bài văn này tương đối dài nhưng ngôn ngữ hài hước thú vị nên tôi đọc một mạch là xong."}],"related":[{"hanzi":"篇","pinyin":"piān","vi":"Bài (lượng từ)"},{"hanzi":"中文","pinyin":"Zhōngwén","vi":"Tiếng Trung"},{"hanzi":"内容","pinyin":"nèiróng","vi":"Nội dung"},{"hanzi":"作家","pinyin":"zuòjiā","vi":"Nhà văn"},{"hanzi":"作者","pinyin":"zuòzhě","vi":"Tác giả"}]},{"id":"污染","hanzi":"污染","pinyin":"wūrǎn","meaning_vi":"ô nhiễm","explanation":"污 (bẩn) + 染 (nhiễm). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","thien-nhien"],"image":"🏭","examples":[{"type":"basic","zh":"我们要减少空气污染。","pinyin":"Wǒmen yào jiǎnshǎo kōngqì wūrǎn.","vi":"Chúng ta phải giảm thiểu ô nhiễm không khí."},{"type":"simple","zh":"工厂排出的废水如果没有经过处理，就会严重污染周围的河流。","pinyin":"Gōngchǎng páichū de fèishuǐ rúguǒ méiyǒu jīngguò chǔlǐ, jiù huì yánzhòng wūrǎn zhōuwéi de héliú.","vi":"Nước thải từ nhà máy thải ra nếu không qua xử lý sẽ làm ô nhiễm nghiêm trọng các dòng sông xung quanh."},{"type":"compound","zh":"为了减少汽车尾气对环境的污染，越来越多的人开始选择骑自行车上班。","pinyin":"Wèile jiǎnshǎo qìchē wěiqì duì huánjìng de wūrǎn, yuèláiyuè duō de rén kāishǐ xuǎnzé qí zìxíngchē shàngbān.","vi":"Để giảm thiểu ô nhiễm môi trường do khí thải ô tô, ngày càng có nhiều người bắt đầu chọn đạp xe đi làm."}],"related":[{"hanzi":"传染","pinyin":"chuánrǎn","vi":"Lây nhiễm"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"空气","pinyin":"kōngqì","vi":"Không khí"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"}],"traditional":"汙染"},{"id":"无","hanzi":"无","pinyin":"wú","meaning_vi":"không có","explanation":"Dùng nhiều trong văn viết và từ ghép (无聊 - nhàm chán, 无论 - bất kể).","hsk_level":3,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"这里无人居住。","pinyin":"Zhèlǐ wúrén jūzhù.","vi":"Ở đây không có người sinh sống."},{"type":"simple","zh":"在学习科学知识的道路上，学无止境，我们必须永远保持谦虚。","pinyin":"Zài xuéxí kēxué zhīshi de dào lùshang, xuéwúzhǐjìng, wǒmen bìxū yǒngyuǎn bǎochí qiānxū.","vi":"Trên con đường học tập kiến thức khoa học, sự học là vô tận, chúng ta phải mãi giữ sự khiêm tốn."},{"type":"compound","zh":"虽然这种水果看起来不太好看，但是它对身体有益无害。","pinyin":"Suīrán zhè zhǒng shuǐguǒ kànqǐlái bú tài hǎokàn, dànshì tā duì shēntǐ yǒuyì wúhài.","vi":"Tuy loại quả này trông không đẹp mắt lắm nhưng nó chỉ có lợi chứ không có hại cho sức khỏe."}],"related":[{"hanzi":"无聊","pinyin":"wúliáo","vi":"Nhàm chán"},{"hanzi":"无论","pinyin":"wúlùn","vi":"Bất kể"},{"hanzi":"没有","pinyin":"méiyǒu","vi":"Không có"},{"hanzi":"无限","pinyin":"wúxiàn","vi":"Vô hạn"},{"hanzi":"无效","pinyin":"wúxiào","vi":"Vô hiệu"}],"traditional":"無"},{"id":"无聊","hanzi":"无聊","pinyin":"wúliáo","meaning_vi":"nhàm chán, buồn chán","explanation":"无 (không) + 聊 (trò chuyện/tựa vào).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😑","examples":[{"type":"basic","zh":"周末待在家里真无聊。","pinyin":"Zhōumò dāi zài jiālǐ zhēn wúliáo.","vi":"Cuối tuần ở nhà thật nhàm chán."},{"type":"simple","zh":"这个电影的故事情节太简单了，看了一半我就觉得非常无聊。","pinyin":"Zhè ge diànyǐng de gùshi qíngjié tài jiǎndān le, kànle yíbàn wǒ jiù juéde fēicháng wúliáo.","vi":"Tình tiết câu chuyện của bộ phim này đơn giản quá, xem được một nửa tôi đã thấy vô cùng nhàm chán."},{"type":"compound","zh":"如果你周末觉得无聊，可以去图书馆借几本好看的小说或者去公园散散步。","pinyin":"Rúguǒ nǐ zhōumò juéde wúliáo, kěyǐ qù túshūguǎn jiè jǐ běn hǎokàn de xiǎoshuō huòzhě qù gōngyuán sàn sanbù.","vi":"Nếu cuối tuần bạn thấy buồn chán thì có thể ra thư viện mượn vài cuốn tiểu thuyết hay hoặc đi dạo công viên."}],"related":[{"hanzi":"有趣","pinyin":"yǒuqù","vi":"Thú vị"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"Trò chuyện"},{"hanzi":"无","pinyin":"wú","vi":"Không có"},{"hanzi":"意思","pinyin":"yìsi","vi":"Ý nghĩa"},{"hanzi":"烦恼","pinyin":"fánnǎo","vi":"Phiền muộn"}],"traditional":"無聊"},{"id":"无论","hanzi":"无论","pinyin":"wúlùn","meaning_vi":"bất kể, dù cho","explanation":"无 (không) + 论 (bàn luận). Thường đi với 都 / 也.","hsk_level":3,"tags":["lien-tu"],"image":"🔄","examples":[{"type":"basic","zh":"无论刮风下雨，他都坚持跑步。","pinyin":"Wúlùn guāfēng xiàyǔ, tā dōu jiānchí pǎobù.","vi":"Bất kể gió mưa, anh ấy đều kiên trì chạy bộ."},{"type":"simple","zh":"无论做什么事情，只要认真坚持下去，就一定能看到收获。","pinyin":"Wúlùn zuò shénme shìqing, zhǐyào rènzhēn jiānchí xiàqù, jiù yídìng néng kàndào shōuhuò.","vi":"Bất kể làm việc gì, chỉ cần nghiêm túc kiên trì thực hiện thì nhất định sẽ thấy thành quả."},{"type":"compound","zh":"无论将来我走到世界的哪个角落，我都永远不会忘记我的母校和老师。","pinyin":"Wúlùn jiānglái wǒ zǒu dào shìjiè de nǎ ge jiǎoluò, wǒ dōu yǒngyuǎn bú huì wàngjì wǒ de mǔxiào hé lǎoshī.","vi":"Dù sau này tôi đi tới góc nào của thế giới, tôi cũng mãi mãi không bao giờ quên trường cũ và thầy cô."}],"related":[{"hanzi":"不管","pinyin":"bùguǎn","vi":"Bất kể"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"Thảo luận"},{"hanzi":"无","pinyin":"wú","vi":"Không"},{"hanzi":"任何","pinyin":"rènhé","vi":"Bất kỳ"},{"hanzi":"都","pinyin":"dōu","vi":"Đều"}],"traditional":"無論"},{"id":"误会","hanzi":"误会","pinyin":"wùhuì","meaning_vi":"hiểu lầm","explanation":"误 (sai lầm) + 会 (hiểu). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","danh-tu"],"image":"😕","examples":[{"type":"basic","zh":"对不起，我误会你了。","pinyin":"Duìbuqǐ, wǒ wùhuì nǐ le.","vi":"Xin lỗi, tôi đã hiểu lầm bạn rồi."},{"type":"simple","zh":"因为电话里信号不好没听清楚，结果造成了我们之间的误会。","pinyin":"Yīnwèi diànhuà lǐ xìnhào bù hǎo méi tīng qīngchu, jiéguǒ zào chéngle wǒmen zhījiān de wùhuì.","vi":"Vì sóng điện thoại kém nghe không rõ nên đã gây ra sự hiểu lầm giữa chúng tôi."},{"type":"compound","zh":"好朋友之间如果产生了误会，一定要及时当面解释清楚，不要放在心里。","pinyin":"Hǎopéngyou zhījiān rúguǒ chǎnshēngle wùhuì, yídìngyào jíshí dāngmiàn jiěshì qīngchu, bú yào fàng zài xīnlǐ.","vi":"Giữa bạn thân với nhau nếu nảy sinh hiểu lầm thì nhất định phải giải thích rõ ràng trực tiếp kịp thời, đừng để trong lòng."}],"related":[{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"Thấu hiểu"},{"hanzi":"解释","pinyin":"jiěshì","vi":"Giải thích"},{"hanzi":"道歉","pinyin":"dàoqiàn","vi":"Xin lỗi"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"Tha thứ"}],"traditional":"誤會"},{"id":"西红柿","hanzi":"西红柿","pinyin":"xīhóngshì","meaning_vi":"quả cà chua","explanation":"西 (phương Tây) + 红 (đỏ) + 柿 (quả hồng).","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍅","examples":[{"type":"basic","zh":"我喜欢吃西红柿炒鸡蛋。","pinyin":"Wǒ xǐhuan chī xīhóngshì chǎojīdàn.","vi":"Tôi thích ăn trứng xào cà chua."},{"type":"simple","zh":"西红柿不仅颜色鲜红漂亮，而且含有丰富的维生素，生吃熟吃都很好。","pinyin":"Xīhóngshì bùjǐn yánsè xiānhóng piàoliang, érqiě hányǒu fēngfù de wéishēngsù, shēngchī shú chī dōu hěn hǎo.","vi":"Cà chua không những màu sắc đỏ tươi đẹp mắt mà còn chứa nhiều vitamin, ăn sống hay nấu chín đều ngon."},{"type":"compound","zh":"虽然西红柿炒鸡蛋是一道非常普通的家常菜，但是几乎每个中国人都爱吃。","pinyin":"Suīrán xīhóngshì chǎojīdàn shì yídào fēicháng pǔtōng de jiāchángcài, dànshì jīhū měi gezhōng guórén dōu ài chī.","vi":"Tuy trứng xào cà chua là một món ăn gia đình rất bình thường nhưng hầu như người Trung Quốc nào cũng thích ăn."}],"related":[{"hanzi":"西瓜","pinyin":"xīguā","vi":"Dưa hấu"},{"hanzi":"鸡蛋","pinyin":"jīdàn","vi":"Trứng gà"},{"hanzi":"菜","pinyin":"cài","vi":"Món ăn/Rau"},{"hanzi":"汤","pinyin":"tāng","vi":"Canh"},{"hanzi":"红","pinyin":"hóng","vi":"Màu đỏ"}],"traditional":"西紅柿"},{"id":"吸引","hanzi":"吸引","pinyin":"xīyǐn","meaning_vi":"thu hút, hấp dẫn","explanation":"吸 (hút) + 引 (lôi kéo).","hsk_level":3,"tags":["dong-tu"],"image":"🧲","examples":[{"type":"basic","zh":"北京的风景吸引了很多游客。","pinyin":"Běijīng de fēngjǐng xīyǐnle hěn duō yóukè.","vi":"Phong cảnh Bắc Kinh đã thu hút rất nhiều du khách."},{"type":"simple","zh":"这本小说一开头就用悬念深深地吸引了所有读者的注意力。","pinyin":"Zhè běn xiǎoshuō yì kāitóu jiù yòng xuánniàn shēnshēn de xīyǐnle suǒyǒu dúzhě de zhùyìlì.","vi":"Cuốn tiểu thuyết này ngay từ đầu đã dùng sự hồi hộp thu hút sâu sắc sự chú ý của mọi độc giả."},{"type":"compound","zh":"这家新开的咖啡店不仅环境优雅，而且咖啡味道醇香，吸引了很多年轻人。","pinyin":"Zhè jiā xīn kāi de kāfēidiàn bùjǐn huánjìng yōuyǎ, érqiě kāfēi wèidào chún xiāng, xīyǐnle hěn duō niánqīngrén.","vi":"Quán cà phê mới mở này không những không gian trang nhã mà hương vị cà phê cũng thơm nồng, thu hút rất nhiều bạn trẻ."}],"related":[{"hanzi":"引起","pinyin":"yǐnqǐ","vi":"Gây ra/Thu hút"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"Hô hấp"},{"hanzi":"感兴趣","pinyin":"gǎnxìngqù","vi":"Hứng thú"},{"hanzi":"游客","pinyin":"yóukè","vi":"Du khách"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"Đặc sắc"}]},{"id":"现金","hanzi":"现金","pinyin":"xiànjīn","meaning_vi":"tiền mặt","explanation":"现 (hiện tại) + 金 (tiền/vàng).","hsk_level":3,"tags":["danh-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"请问这里可以付现金吗？","pinyin":"Qǐngwèn zhèlǐ kěyǐ fù xiànjīn ma?","vi":"Xin hỏi ở đây có thể trả tiền mặt không ạ?"},{"type":"simple","zh":"虽然现在手机支付很普及，但是出国旅游时还是应该带一些现金。","pinyin":"Suīrán xiànzài shǒujī zhīfù hěn pǔjí, dànshì chūguó lǚyóu shí háishi yīnggāi dài yìxiē xiànjīn.","vi":"Tuy hiện nay thanh toán di động rất phổ biến nhưng khi đi du lịch nước ngoài vẫn nên mang theo một ít tiền mặt."},{"type":"compound","zh":"因为这家小店的网络信号不好，手机无法扫码付款，所以我只好付了现金。","pinyin":"Yīnwèi zhè jiā xiǎodiàn de wǎngluò xìnhào bù hǎo, shǒujī wúfǎ sǎomǎ fùkuǎn, suǒyǐ wǒ zhǐhǎo fùle xiànjīn.","vi":"Vì sóng mạng của quán nhỏ này kém, điện thoại không thể quét mã thanh toán nên tôi đành trả bằng tiền mặt."}],"related":[{"hanzi":"付款","pinyin":"fùkuǎn","vi":"Thanh toán"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"},{"hanzi":"零钱","pinyin":"língqián","vi":"Tiền lẻ"},{"hanzi":"取","pinyin":"qǔ","vi":"Rút (tiền)"}],"traditional":"現金"},{"id":"羡慕","hanzi":"羡慕","pinyin":"xiànmù","meaning_vi":"ngưỡng mộ, ghen tị","explanation":"羡 (ao ước) + 慕 (mến mộ).","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"🤩","examples":[{"type":"basic","zh":"我真羡慕你的好记忆力。","pinyin":"Wǒ zhēn xiànmù nǐ de hǎo jìyìlì.","vi":"Tôi thật ngưỡng mộ trí nhớ tốt của bạn."},{"type":"simple","zh":"看到他能用流利的汉语和中国人自由交流，同学们都非常羡慕。","pinyin":"Kàndào tā néng yòng liúlì de Hànyǔ hé Zhōngguórén zìyóu jiāoliú, tóngxuémen dōu fēicháng xiànmù.","vi":"Thấy anh ấy có thể dùng tiếng Trung trôi chảy giao tiếp tự do với người Trung Quốc, các bạn học đều vô cùng ngưỡng mộ."},{"type":"compound","zh":"与其每天羡慕别人的好成绩，不如从现在开始脚踏实地地努力学习。","pinyin":"Yǔqí měitiān xiànmù biérén de hǎo chéngjì, bùrú cóng xiànzài kāishǐ jiǎotàshídì de nǔlì xuéxí.","vi":"Thay vì ngày nào cũng ngưỡng mộ thành tích tốt của người khác, chi bằng bắt đầu chăm chỉ học tập một cách thiết thực từ bây giờ."}],"related":[{"hanzi":"佩服","pinyin":"pèifu","vi":"Khâm phục"},{"hanzi":"喜欢","pinyin":"xǐhuan","vi":"Thích"},{"hanzi":"优秀","pinyin":"yōuxiù","vi":"Xuất sắc"},{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"Tự hào"},{"hanzi":"流利","pinyin":"liúlì","vi":"Trôi chảy"}],"traditional":"羨慕"},{"id":"相反","hanzi":"相反","pinyin":"xiāngfǎn","meaning_vi":"trái ngược, ngược lại","explanation":"相 (lẫn nhau) + 反 (ngược).","hsk_level":3,"tags":["tinh-tu","lien-tu"],"image":"🔄","examples":[{"type":"basic","zh":"他的看法跟我完全相反。","pinyin":"Tā de kànfǎ gēn wǒ wánquán xiāngfǎn.","vi":"Cách nhìn của anh ấy hoàn toàn trái ngược với tôi."},{"type":"simple","zh":"虽然他们是亲兄弟，但是性格却完全相反，哥哥安静，弟弟活泼。","pinyin":"Suīrán tāmen shì qīn xiōngdì, dànshì xìnggé què wánquán xiāngfǎn, gēge ānjìng, dìdi huópō.","vi":"Tuy họ là anh em ruột nhưng tính cách lại hoàn toàn trái ngược, anh trai trầm tính, em trai hoạt bát."},{"type":"compound","zh":"遇到失败时他从不灰心，相反，他总是能从失败中总结经验继续前进。","pinyin":"Yùdào shībài shí tā cóng bù huīxīn, xiāngfǎn, tā zǒngshì néng cóng shībài zhōng zǒngjié jīngyàn jìxù qiánjìn.","vi":"Khi gặp thất bại anh ấy không bao giờ nản lòng, ngược lại, anh ấy luôn rút ra kinh nghiệm từ thất bại để tiếp tục tiến lên."}],"related":[{"hanzi":"反对","pinyin":"fǎnduì","vi":"Phản đối"},{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Giống nhau"},{"hanzi":"不同","pinyin":"bùtóng","vi":"Khác nhau"},{"hanzi":"区别","pinyin":"qūbié","vi":"Khác biệt"},{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"}]},{"id":"香","hanzi":"香","pinyin":"xiāng","meaning_vi":"thơm; ngon (ăn ngon, ngủ say)","explanation":"Bộ hòa 禾 + 日.","hsk_level":3,"tags":["tinh-tu","an-uong"],"image":"🌸","examples":[{"type":"basic","zh":"妈妈做的菜真香啊！","pinyin":"Māma zuò de cài zhēn xiāng a!","vi":"Món ăn mẹ nấu thơm thật đấy!"},{"type":"simple","zh":"春天公园里的桃花和桂花都开了，空气中到处都是淡淡的花香。","pinyin":"Chūntiān gōngyuán lǐ de táohuā hé guìhuā dōu kāi le, kōngqì zhōng dàochù dōu shì dàndàn de huāxiāng.","vi":"Mùa xuân hoa đào và hoa quế trong công viên đều nở rộ, trong không khí khắp nơi đều thoang thoảng hương hoa."},{"type":"compound","zh":"因为白天爬山爬得太累了，所以昨天晚上我一躺到床上就睡得特别香。","pinyin":"Yīnwèi báitiān páshān pá de tài lèi le, suǒyǐ zuótiān wǎnshang wǒ yì tǎng dào chuáng shang jiù shuì de tèbié xiāng.","vi":"Vì ban ngày leo núi mệt quá nên tối qua vừa nằm xuống giường là tôi ngủ say sưa ngon giấc."}],"related":[{"hanzi":"香蕉","pinyin":"xiāngjiāo","vi":"Quả chuối"},{"hanzi":"味道","pinyin":"wèidào","vi":"Mùi vị"},{"hanzi":"好吃","pinyin":"hǎochī","vi":"Ngon"},{"hanzi":"花","pinyin":"huā","vi":"Hoa"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Ngủ"}]},{"id":"详细","hanzi":"详细","pinyin":"xiángxì","meaning_vi":"chi tiết, tỉ mỉ","explanation":"详 (rõ ràng) + 细 (nhỏ nhặt/cẩn thận).","hsk_level":3,"tags":["tinh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"请你详细地介绍一下。","pinyin":"Qǐng nǐ xiángxì de jièshào yíxià.","vi":"Xin bạn giới thiệu một cách chi tiết."},{"type":"simple","zh":"这份旅游攻略写得非常详细，把交通路线和门票价格都列出来了。","pinyin":"Zhè fèn lǚyóu gōnglüè xiě de fēicháng xiángxì, bǎ jiāotōng lùxiàn hé ménpiào jiàgé dōu liè chūlái le.","vi":"Bản cẩm nang du lịch này viết vô cùng chi tiết, liệt kê đầy đủ cả tuyến đường giao thông lẫn giá vé vào cửa."},{"type":"compound","zh":"虽然时间有点儿紧张，但是王老师还是耐心地给我们做了详细的解答。","pinyin":"Suīrán shíjiān yǒudiǎnr jǐnzhāng, dànshì Wáng lǎoshī háishi nàixīn de gěi wǒmen zuòle xiángxì de jiědá.","vi":"Tuy thời gian hơi eo hẹp nhưng thầy Vương vẫn kiên nhẫn giải đáp cặn kẽ cho chúng tôi."}],"related":[{"hanzi":"仔细","pinyin":"zǐxì","vi":"Cẩn thận"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"Đơn giản"},{"hanzi":"介绍","pinyin":"jièshào","vi":"Giới thiệu"},{"hanzi":"说明","pinyin":"shuōmíng","vi":"Giải thích"}],"traditional":"詳細"},{"id":"响","hanzi":"响","pinyin":"xiǎng","meaning_vi":"vang, kêu, to (âm thanh)","explanation":"Bộ khẩu 口 + 向.","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"🔔","examples":[{"type":"basic","zh":"下课铃声响了。","pinyin":"Xiàkè líng shēngxiǎng le.","vi":"Tiếng chuông tan học vang lên rồi."},{"type":"simple","zh":"刚才你的手机一直在桌子上响，可能是你妈妈打来的电话。","pinyin":"Gāngcái nǐ de shǒujī yìzhí zài zhuōzi shang xiǎng, kěnéng shì nǐ māma dǎ lái de diànhuà.","vi":"Vừa nãy điện thoại của bạn cứ reo liên tục trên bàn, có lẽ là mẹ bạn gọi tới đấy."},{"type":"compound","zh":"半夜里突然响起一阵雷声，把正在熟睡的小妹妹吓得哭了起来。","pinyin":"Bàn yèlǐ tūrán xiǎngqǐ yízhèn léishēng, bǎ zhèngzài shúshuì de xiǎomèimei xià de kūle qǐlái.","vi":"Nửa đêm đột nhiên vang lên một hồi tiếng sấm, làm em gái nhỏ đang ngủ say giật mình khóc òa lên."}],"related":[{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"Ảnh hưởng"},{"hanzi":"声音","pinyin":"shēngyīn","vi":"Âm thanh"},{"hanzi":"电话","pinyin":"diànhuà","vi":"Điện thoại"},{"hanzi":"下课","pinyin":"xiàkè","vi":"Tan học"},{"hanzi":"吵","pinyin":"chǎo","vi":"Ồn ào"}],"traditional":"響"},{"id":"橡皮","hanzi":"橡皮","pinyin":"xiàngpí","meaning_vi":"cục tẩy, gôm","explanation":"橡 (cây cao su) + 皮 (da/vỏ).","hsk_level":3,"tags":["danh-tu","hoc-tap","do-vat"],"image":"🧽","examples":[{"type":"basic","zh":"请借我用一下橡皮。","pinyin":"Qǐng jiè wǒ yòng yíxià xiàngpí.","vi":"Xin cho tôi mượn cục tẩy dùng một chút."},{"type":"simple","zh":"用铅笔写错字的时候，拿橡皮轻轻一擦就能擦得干干净净。","pinyin":"Yòng qiānbǐ xiě cuòzì de shíhou, ná xiàngpí qīngqīng yì cā jiù néng cā de gān gānjìng jìng.","vi":"Lúc dùng bút chì viết sai chữ, lấy cục tẩy lau nhẹ một cái là có thể xóa sạch bong."},{"type":"compound","zh":"妈妈给我买了一块草莓形状的香橡皮，放在文具盒里特别可爱。","pinyin":"Māma gěi wǒ mǎile yíkuài cǎoméi xíngzhuàng de xiāng xiàngpí, fàng zài wénjùhé lǐ tèbié kě'ài.","vi":"Mẹ mua cho tôi một cục tẩy thơm hình quả dâu tây, để trong hộp bút trông đặc biệt đáng yêu."}],"related":[{"hanzi":"皮肤","pinyin":"pífū","vi":"Da"},{"hanzi":"笔","pinyin":"bǐ","vi":"Bút"},{"hanzi":"擦","pinyin":"cā","vi":"Lau/Xóa"},{"hanzi":"本子","pinyin":"běnzi","vi":"Quyển vở"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"}]},{"id":"消息","hanzi":"消息","pinyin":"xiāoxi","meaning_vi":"tin tức, thông tin","explanation":"消 (tiêu tan) + 息 (tin tức).","hsk_level":3,"tags":["danh-tu"],"image":"📩","examples":[{"type":"basic","zh":"这是一个好消息！","pinyin":"Zhè shì yí ge hǎo xiāoxi!","vi":"Đây là một tin tốt!"},{"type":"simple","zh":"听到哥哥顺利考上研究生院的消息，全家人开心得不得了。","pinyin":"Tīngdào gēge shùnlì kǎoshàng yánjiūshēng yuàn de xiāoxi, quán jiārén kāi xīnde budéliǎo.","vi":"Nghe tin anh trai thi đỗ cao học một cách suôn sẻ, cả nhà vui mừng khôn xiết."},{"type":"compound","zh":"因为山里手机没有信号，所以我们已经有三天没有收到他的任何消息了。","pinyin":"Yīnwèi shān lǐ shǒujī méiyǒu xìnhào, suǒyǐ wǒmen yǐjīng yǒu sān tiān méiyǒu shōudào tā de rènhé xiāoxi le.","vi":"Vì trong núi điện thoại mất sóng nên chúng tôi đã ba ngày rồi không nhận được bất kỳ tin tức gì của anh ấy."}],"related":[{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"Tin tức"},{"hanzi":"休息","pinyin":"xiūxi","vi":"Nghỉ ngơi"},{"hanzi":"通知","pinyin":"tōngzhī","vi":"Thông báo"},{"hanzi":"吃惊","pinyin":"chījīng","vi":"Kinh ngạc"}]},{"id":"小吃","hanzi":"小吃","pinyin":"xiǎochī","meaning_vi":"đồ ăn vặt, món ăn nhẹ đặc sản","explanation":"小 (nhỏ) + 吃 (ăn).","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍢","examples":[{"type":"basic","zh":"北京有很多特色小吃。","pinyin":"Běijīng yǒu hěn duō tèsè xiǎochī.","vi":"Bắc Kinh có rất nhiều món ăn vặt đặc sắc."},{"type":"simple","zh":"晚上逛夜市的时候，我们可以品尝到全国各地的美味小吃。","pinyin":"Wǎnshang guàng yèshì de shíhou, wǒmen kěyǐ pǐncháng dào quánguó gèdì de měiwèi xiǎochī.","vi":"Buổi tối khi dạo chợ đêm, chúng ta có thể thưởng thức các món ăn vặt ngon miệng từ khắp mọi miền đất nước."},{"type":"compound","zh":"虽然这条胡同里的小吃价格都很便宜，但是味道却非常正宗地道。","pinyin":"Suīrán zhè tiáo hútòng lǐ de xiǎochī jiàgé dōu hěn piányi, dànshì wèidào què fēicháng zhèngzōng dìdao.","vi":"Tuy đồ ăn vặt trong con ngõ nhỏ này giá cả đều rất rẻ nhưng hương vị lại vô cùng chuẩn vị truyền thống."}],"related":[{"hanzi":"吃","pinyin":"chī","vi":"Ăn"},{"hanzi":"好吃","pinyin":"hǎochī","vi":"Ngon"},{"hanzi":"尝","pinyin":"cháng","vi":"Nếm"},{"hanzi":"菜","pinyin":"cài","vi":"Món ăn"},{"hanzi":"味道","pinyin":"wèidào","vi":"Mùi vị"}]},{"id":"小伙子","hanzi":"小伙子","pinyin":"xiǎohuǒzi","meaning_vi":"chàng trai trẻ, thanh niên","explanation":"小 (trẻ) + 伙子 (bạn trẻ).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"🧑","examples":[{"type":"basic","zh":"这个小伙子真热情！","pinyin":"Zhè ge xiǎohuǒzi zhēn rèqíng!","vi":"Chàng trai trẻ này nhiệt tình thật đấy!"},{"type":"simple","zh":"在公共汽车上，那位年轻的小伙子主动站起来给老奶奶让了座。","pinyin":"Zài gōnggòngqìchē shang, nà wèi niánqīng de xiǎohuǒzi zhǔdòng zhànqǐlái gěi lǎonǎinai ràngle zuò.","vi":"Trên xe buýt, chàng thanh niên trẻ tuổi đó chủ động đứng dậy nhường ghế cho bà cụ."},{"type":"compound","zh":"虽然这个小伙子刚参加工作不久，但是做起事来非常认真踏实。","pinyin":"Suīrán zhè ge xiǎohuǒzi gāng cānjiā gōngzuò bùjiǔ, dànshì zuò qǐ shì lái fēicháng rènzhēn tāshi.","vi":"Tuy chàng trai trẻ này mới đi làm chưa lâu nhưng làm việc rất nghiêm túc chắc chắn."}],"related":[{"hanzi":"年轻","pinyin":"niánqīng","vi":"Trẻ tuổi"},{"hanzi":"男孩","pinyin":"nánhái","vi":"Bé trai"},{"hanzi":"男人","pinyin":"nánrén","vi":"Đàn ông"},{"hanzi":"帅","pinyin":"shuài","vi":"Đẹp trai"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"小夥子"},{"id":"小说","hanzi":"小说","pinyin":"xiǎoshuō","meaning_vi":"tiểu thuyết","explanation":"小 (nhỏ) + 说 (kể chuyện).","hsk_level":3,"tags":["danh-tu","giai-tri"],"image":"📚","examples":[{"type":"basic","zh":"我喜欢看中国历史小说。","pinyin":"Wǒ xǐhuan kàn Zhōngguó lìshǐ xiǎoshuō.","vi":"Tôi thích đọc tiểu thuyết lịch sử Trung Quốc."},{"type":"simple","zh":"这本侦探小说情节非常精彩，我花了两个晚上就把它读完了。","pinyin":"Zhè běn zhēntàn xiǎoshuō qíngjié fēicháng jīngcǎi, wǒ huāle liǎng ge wǎnshang jiù bǎ tā dú wánle.","vi":"Cuốn tiểu thuyết trinh thám này tình tiết vô cùng đặc sắc, tôi mất hai buổi tối là đọc xong hết."},{"type":"compound","zh":"虽然看中文小说对留学生来说有一定难度，但是对提高阅读能力很有帮助。","pinyin":"Suīrán kàn Zhōngwén xiǎoshuō duì liúxué shenglái shuō yǒu yídìng nándù, dànshì duì tígāo yuèdú nénglì hěn yǒubāngzhù.","vi":"Tuy đọc tiểu thuyết tiếng Trung đối với du học sinh có độ khó nhất định nhưng lại giúp ích rất nhiều cho việc nâng cao kỹ năng đọc hiểu."}],"related":[{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"故事","pinyin":"gùshi","vi":"Câu chuyện"},{"hanzi":"作家","pinyin":"zuòjiā","vi":"Nhà văn"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"Đọc hiểu"},{"hanzi":"说","pinyin":"shuō","vi":"Nói/Kể"}],"traditional":"小說"},{"id":"笑话","hanzi":"笑话","pinyin":"xiàohua","meaning_vi":"truyện cười; chê cười","explanation":"笑 (cười) + 话 (lời nói). Vừa là danh từ vừa là động từ.","hsk_level":3,"tags":["danh-tu","dong-tu","giai-tri"],"image":"😂","examples":[{"type":"basic","zh":"他讲了一个有趣的笑话。","pinyin":"Tā jiǎngle yí ge yǒuqù de xiàohua.","vi":"Anh ấy đã kể một câu chuyện cười thú vị."},{"type":"simple","zh":"大家应该互相鼓励，千万不要因为别人说错话就笑话别人。","pinyin":"Dàjiā yīnggāi hùxiāng gǔlì, qiānwàn bú yào yīnwèi biérén shuō cuò huà jiù xiàohua biérén.","vi":"Mọi người nên khích lệ lẫn nhau, tuyệt đối đừng vì người khác nói sai mà chê cười họ."},{"type":"compound","zh":"王老师经常在课堂上穿插讲几个小笑话，让同学们在轻松的气氛中学习。","pinyin":"Wáng lǎoshī jīngcháng zài kètáng shang chuānchā jiǎng jǐ ge xiǎo xiàohua, ràng tóngxuémen zài qīngsōng de qìfēn zhōng xuéxí.","vi":"Thầy Vương thường xuyên lồng ghép kể vài mẩu truyện cười nhỏ trên lớp để các bạn học tiếp thu bài trong bầu không khí nhẹ nhàng."}],"related":[{"hanzi":"笑","pinyin":"xiào","vi":"Cười"},{"hanzi":"开玩笑","pinyin":"kāiwánxiào","vi":"Nói đùa"},{"hanzi":"幽默","pinyin":"yōumò","vi":"Hài hước"},{"hanzi":"有趣","pinyin":"yǒuqù","vi":"Thú vị"},{"hanzi":"说话","pinyin":"shuōhuà","vi":"Nói chuyện"}],"traditional":"笑話"},{"id":"效果","hanzi":"效果","pinyin":"xiàoguǒ","meaning_vi":"hiệu quả","explanation":"效 (công hiệu) + 果 (kết quả).","hsk_level":3,"tags":["danh-tu"],"image":"📈","examples":[{"type":"basic","zh":"这种学习方法效果很好。","pinyin":"Zhè zhǒng xuéxí fāngfǎ xiàoguǒ hěn hǎo.","vi":"Phương pháp học tập này hiệu quả rất tốt."},{"type":"simple","zh":"医生开的这种感冒药效果非常明显，吃了两次以后就不发烧了。","pinyin":"Yīshēng kāi de zhè zhǒng gǎnmàoyào xiàoguǒ fēicháng míngxiǎn, chīle liǎng cì yǐhòu jiù bù fāshāo le.","vi":"Loại thuốc cảm cúm bác sĩ kê này hiệu quả vô cùng rõ rệt, uống hai lần xong là hết sốt ngay."},{"type":"compound","zh":"只有把课堂上学到的语法知识运用到实际交流中，才能达到最好的学习效果。","pinyin":"Zhǐyǒu bǎ kètáng shang xuédào de yǔfǎ zhīshi yùnyòng dào shíjì jiāoliú zhōng, cáinéng dádào zuìhǎo de xuéxí xiàoguǒ.","vi":"Chỉ có vận dụng kiến thức ngữ pháp học trên lớp vào giao tiếp thực tế mới đạt được hiệu quả học tập tốt nhất."}],"related":[{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"果然","pinyin":"guǒrán","vi":"Quả nhiên"},{"hanzi":"有效","pinyin":"yǒuxiào","vi":"Hiệu quả"},{"hanzi":"作用","pinyin":"zuòyòng","vi":"Tác dụng"},{"hanzi":"方法","pinyin":"fāngfǎ","vi":"Phương pháp"}]},{"id":"心情","hanzi":"心情","pinyin":"xīnqíng","meaning_vi":"tâm trạng","explanation":"心 (trái tim) + 情 (tình cảm).","hsk_level":3,"tags":["danh-tu","cam-xuc"],"image":"💖","examples":[{"type":"basic","zh":"今天我的心情特别好。","pinyin":"Jīntiān wǒ de xīnqíng tèbié hǎo.","vi":"Hôm nay tâm trạng của tôi đặc biệt tốt."},{"type":"simple","zh":"天气晴朗的时候出去散散步、晒晒太阳，能让人的心情变得很愉快。","pinyin":"Tiānqì qínglǎng de shíhou chūqù sàn sanbù, shài shaitàiyáng, néng ràng rén de xīnqíng biànde hěn yúkuài.","vi":"Lúc trời quang mây tạnh ra ngoài đi dạo, tắm nắng có thể khiến tâm trạng con người trở nên vui vẻ."},{"type":"compound","zh":"虽然这次考试成绩不太理想，但是他很快调整好了心情，准备迎接下次挑战。","pinyin":"Suīrán zhè cì kǎoshì chéngjì bú tài lǐxiǎng, dànshì tā hěn kuài tiáozhěng hǎole xīnqíng, zhǔnbèi yíngjiē xiàcì tiǎozhàn.","vi":"Tuy điểm thi lần này chưa được như ý nhưng cậu ấy đã nhanh chóng điều chỉnh lại tâm trạng để chuẩn bị đón thử thách tiếp theo."}],"related":[{"hanzi":"情况","pinyin":"qíngkuàng","vi":"Tình huống"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"伤心","pinyin":"shāngxīn","vi":"Đau lòng"},{"hanzi":"愉快","pinyin":"yúkuài","vi":"Vui vẻ"},{"hanzi":"心","pinyin":"xīn","vi":"Trái tim"}]},{"id":"辛苦","hanzi":"辛苦","pinyin":"xīnkǔ","meaning_vi":"vất vả, cực nhọc","explanation":"辛 (cay đắng) + 苦 (khổ cực).","hsk_level":3,"tags":["tinh-tu"],"image":"😓","examples":[{"type":"basic","zh":"王老师，您辛苦了！","pinyin":"Wáng lǎoshī, nín xīnkǔ le!","vi":"Thầy Vương, thầy vất vả rồi ạ!"},{"type":"simple","zh":"爸爸每天早出晚归，工作非常辛苦。","pinyin":"Bàba měitiān zǎo chū wǎnguī, gōngzuò fēicháng xīnkǔ.","vi":"Bố ngày nào cũng đi sớm về khuya, làm việc vô cùng vất vả."},{"type":"compound","zh":"虽然爬山的过程非常辛苦，但是站在山顶看到日出的那一刻觉得一切都值了。","pinyin":"Suīrán páshān de guòchéng fēicháng xīnkǔ, dànshì zhàn zài shāndǐng kàndào rìchū de nà yíkè juéde yíqiè dōu zhí le.","vi":"Tuy quá trình leo núi vô cùng vất vả nhưng khoảnh khắc đứng trên đỉnh núi ngắm mặt trời mọc lại thấy mọi thứ đều xứng đáng."}],"related":[{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng/Khổ"},{"hanzi":"累","pinyin":"lèi","vi":"Mệt"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"感谢","pinyin":"gǎnxiè","vi":"Cảm tạ"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"}]},{"id":"信封","hanzi":"信封","pinyin":"xìnfēng","meaning_vi":"phong bì thư","explanation":"信 (thư) + 封 (niêm phong).","hsk_level":3,"tags":["danh-tu","do-vat"],"image":"✉️","examples":[{"type":"basic","zh":"请把信装进信封里。","pinyin":"Qǐng bǎ xìn zhuāng jìn xìnfēng lǐ.","vi":"Xin hãy bỏ lá thư vào trong phong bì."},{"type":"simple","zh":"寄信之前，必须在信封的左上角写清楚收信人的地址和邮政编码。","pinyin":"Jì xìn zhīqián, bìxū zài xìnfēng de zuǒshàng jiǎo xiě qīngchu shōu xìn rén de dìzhǐ hé yóuzhèng biānmǎ.","vi":"Trước khi gửi thư, bắt buộc phải viết rõ địa chỉ người nhận và mã bưu chính ở góc trên bên trái phong bì."},{"type":"compound","zh":"虽然现在大家都习惯发电子邮件，但是手写一封信装在信封里寄出显得更有心意。","pinyin":"Suīrán xiànzài dàjiā dōu xíguàn fā diànzǐ yóujiàn, dànshì shǒuxiě yì fēng xìn zhuāng zài xìn fēnglǐ jìchū xiǎnde gèng yǒu xīnyì.","vi":"Tuy hiện nay mọi người đều quen gửi email nhưng viết tay một lá thư bỏ vào phong bì gửi đi tỏ ra chân thành hơn nhiều."}],"related":[{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"寄","pinyin":"jì","vi":"Gửi"},{"hanzi":"邮局","pinyin":"yóujú","vi":"Bưu điện"},{"hanzi":"地址","pinyin":"dìzhǐ","vi":"Địa chỉ"},{"hanzi":"写","pinyin":"xiě","vi":"Viết"}]},{"id":"信息","hanzi":"信息","pinyin":"xìnxī","meaning_vi":"thông tin, tin nhắn","explanation":"信 (tin) + 息 (tin tức).","hsk_level":3,"tags":["danh-tu","cong-nghe"],"image":"📲","examples":[{"type":"basic","zh":"网上有很多有用的信息。","pinyin":"Wǎngshang yǒu hěn duō yǒuyòng de xìnxī.","vi":"Trên mạng có rất nhiều thông tin hữu ích."},{"type":"simple","zh":"这是一个信息时代，互联网让我们每天都能接触到世界各地的最新消息。","pinyin":"Zhè shì yí ge xìnxī shídài, Hùliánwǎng ràng wǒmen měitiān dōu néng jiēchù dào shìjiè gèdì de zuì xīn xiāoxi.","vi":"Đây là thời đại thông tin, Internet giúp chúng ta mỗi ngày đều tiếp cận được tin tức mới nhất khắp nơi trên thế giới."},{"type":"compound","zh":"在填写网络问卷调查时，一定要注意保护好自己的个人隐私信息。","pinyin":"Zài tiánxiě wǎngluò wènjuàndiàochá shí, yídìngyào zhùyì bǎohù hǎo zìjǐ de gèrén yǐnsī xìnxī.","vi":"Khi điền bảng khảo sát trực tuyến, nhất định phải chú ý bảo vệ thông tin riêng tư cá nhân của mình."}],"related":[{"hanzi":"消息","pinyin":"xiāoxi","vi":"Tin tức"},{"hanzi":"短信","pinyin":"duǎnxìn","vi":"Tin nhắn"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"网站","pinyin":"wǎngzhàn","vi":"Trang web"},{"hanzi":"传播","pinyin":"chuánbō","vi":"Truyền bá"}]},{"id":"信心","hanzi":"信心","pinyin":"xìnxīn","meaning_vi":"lòng tin, sự tự tin","explanation":"信 (tin tưởng) + 心 (trái tim).","hsk_level":3,"tags":["danh-tu","cam-xuc"],"image":"💪","examples":[{"type":"basic","zh":"我对自己充满信心。","pinyin":"Wǒ duì zìjǐ chōngmǎn xìnxīn.","vi":"Tôi tràn đầy tự tin vào bản thân mình."},{"type":"simple","zh":"在王老师的不断鼓励下，他终于找回了学习汉语的信心。","pinyin":"Zài Wáng lǎoshī de búduàn gǔlì xià, tā zhōngyú zhǎohuíle xuéxí Hànyǔ de xìnxīn.","vi":"Dưới sự khích lệ không ngừng của thầy Vương, cậu ấy cuối cùng đã tìm lại được sự tự tin khi học tiếng Trung."},{"type":"compound","zh":"只要我们做好了充分的准备，就应该充满信心地走进考场迎接挑战。","pinyin":"Zhǐyào wǒmen zuò hǎole chōngfèn de zhǔnbèi, jiù yīnggāi chōngmǎn xìnxīn de zǒujìn kǎochǎng yíngjiē tiǎozhàn.","vi":"Chỉ cần chúng ta đã chuẩn bị đầy đủ thì nên tự tin bước vào phòng thi đón nhận thử thách."}],"related":[{"hanzi":"自信","pinyin":"zìxìn","vi":"Tự tin"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"Khích lệ"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"}]},{"id":"兴奋","hanzi":"兴奋","pinyin":"xīngfèn","meaning_vi":"hưng phấn, phấn khích","explanation":"兴 (hứng khởi) + 奋 (phấn chấn).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"🤩","examples":[{"type":"basic","zh":"听到这个好消息，他兴奋极了。","pinyin":"Tīngdào zhè ge hǎo xiāoxi, tā xīngfèn jíle.","vi":"Nghe tin tốt này, anh ấy phấn khích vô cùng."},{"type":"simple","zh":"明天就要坐飞机去中国留学了，妹妹兴奋得晚上几乎睡不着觉。","pinyin":"Míngtiān jiùyào zuòfēijī qù Zhōngguó liúxué le, mèimei xīngfèn de wǎnshang jīhū shuìbùzháo jiào.","vi":"Ngày mai là bay sang Trung Quốc du học rồi, em gái phấn khích đến mức tối gần như không ngủ được."},{"type":"compound","zh":"当裁判宣布我们队赢得比赛冠军的那一刻，全场观众都兴奋地欢呼起来。","pinyin":"Dāng cáipàn xuānbù wǒmen duì yíngdé bǐsài guànjūn de nà yíkè, quánchǎng guānzhòng dōu xīngfèn de huānhū qǐlái.","vi":"Khoảnh khắc trọng tài tuyên bố đội chúng tôi giành chức vô địch, toàn thể khán giả đều reo hò phấn khích."}],"related":[{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"激动","pinyin":"jīdòng","vi":"Xúc động"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"Hồi hộp"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"}],"traditional":"興奮"},{"id":"行","hanzi":"行","pinyin":"xíng","meaning_vi":"đi; được, ổn; giỏi, cừ","explanation":"Vừa mang nghĩa đồng ý/được (行，没问题) vừa nghĩa là 'đi'.","hsk_level":3,"tags":["dong-tu","tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"行，就这么办吧！","pinyin":"Xíng, jiù zhème bàn ba!","vi":"Được, cứ làm như vậy đi!"},{"type":"simple","zh":"小王的汉语水平真行，跟中国人聊天完全没有任何障碍。","pinyin":"Xiǎo Wáng de Hànyǔ shuǐpíng zhēn xíng, gēn Zhōngguórén liáotiān wánquán méiyǒu rènhé zhàng'ài.","vi":"Trình độ tiếng Trung của Tiểu Vương giỏi thật đấy, trò chuyện với người Trung Quốc hoàn toàn không có trở ngại gì."},{"type":"compound","zh":"如果你明天没时间，后天去也行，反正我这几天都在家。","pinyin":"Rúguǒ nǐ míngtiān méi shíjiān, hòutiān qù yě xíng, fǎnzhèng wǒ zhèjǐtiān dōu zài jiā.","vi":"Nếu ngày mai bạn không có thời gian thì ngày kia đi cũng được, dù sao mấy hôm nay tôi đều ở nhà."}],"related":[{"hanzi":"可以","pinyin":"kěyǐ","vi":"Có thể"},{"hanzi":"进行","pinyin":"jìnxíng","vi":"Tiến hành"},{"hanzi":"流行","pinyin":"liúxíng","vi":"Thịnh hành"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"},{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"}]},{"id":"醒","hanzi":"醒","pinyin":"xǐng","meaning_vi":"tỉnh, tỉnh giấc","explanation":"Bộ dậu 酉 + 星.","hsk_level":3,"tags":["dong-tu","sinh-hoat"],"image":"⏰","examples":[{"type":"basic","zh":"我每天早上六点半就醒了。","pinyin":"Wǒ měitiān zǎoshang liù diǎn bàn jiù xǐng le.","vi":"Mỗi sáng 6 giờ rưỡi tôi đã tỉnh giấc rồi."},{"type":"simple","zh":"今天早上闹钟没响，我一觉醒来已经八点半了，上班差点儿迟到。","pinyin":"Jīntiān zǎoshang nàozhōng méi xiǎng, wǒ yí jiào xǐnglái yǐjīng bā diǎn bàn le, shàngbān chàdiǎnr chídào.","vi":"Sáng nay đồng hồ báo thức không kêu, tôi ngủ một giấc tỉnh dậy đã 8 giờ rưỡi rồi, suýt nữa thì đi làm muộn."},{"type":"compound","zh":"弟弟睡得很香，你说话声音小一点儿，别把他吵醒了。","pinyin":"Dìdi shuì de hěn xiāng, nǐ shuōhuà shēngyīn xiǎo yìdiǎnr, bié bǎ tā chǎoxǐng le.","vi":"Em trai đang ngủ rất ngon, bạn nói nhỏ tiếng một chút, đừng làm bé tỉnh giấc nhé."}],"related":[{"hanzi":"提醒","pinyin":"tíxǐng","vi":"Nhắc nhở"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Ngủ"},{"hanzi":"起床","pinyin":"qǐchuáng","vi":"Thức dậy"},{"hanzi":"梦","pinyin":"mèng","vi":"Giấc mơ"},{"hanzi":"困","pinyin":"kùn","vi":"Buồn ngủ"}]},{"id":"幸福","hanzi":"幸福","pinyin":"xìngfú","meaning_vi":"hạnh phúc","explanation":"幸 (may mắn) + 福 (phúc lành). Vừa là tính từ vừa là danh từ.","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"🥰","examples":[{"type":"basic","zh":"他们一家人生活得很幸福。","pinyin":"Tāmen yìjiārén shēnghuó de hěn xìngfú.","vi":"Cả gia đình họ sống rất hạnh phúc."},{"type":"simple","zh":"每天下班回家能吃到妈妈做的热饭菜，就是一种简单的幸福。","pinyin":"Měitiān xiàbān huíjiā néng chī dào māma zuò de rè fàncài, jiùshì yì zhǒng jiǎndān de xìngfú.","vi":"Mỗi ngày tan làm về nhà được ăn cơm nóng mẹ nấu chính là một niềm hạnh phúc giản dị."},{"type":"compound","zh":"真正的幸福不在于拥有多少财富，而在于拥有健康的身体和爱你的家人。","pinyin":"Zhēnzhèng de xìngfú bú zàiyú yōngyǒu duōshao cáifù, ér zàiyú yōngyǒu jiànkāng de shēntǐ hé ài nǐ de jiārén.","vi":"Hạnh phúc thực sự không nằm ở việc sở hữu bao nhiêu tiền bạc mà nằm ở việc có cơ thể khỏe mạnh và gia đình yêu thương mình."}],"related":[{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"幸运","pinyin":"xìngyùn","vi":"May mắn"},{"hanzi":"祝福","pinyin":"zhùfú","vi":"Chúc phúc"}]},{"id":"性别","hanzi":"性别","pinyin":"xìngbié","meaning_vi":"giới tính","explanation":"性 (tính chất) + 别 (phân biệt).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"⚧️","examples":[{"type":"basic","zh":"请在表格里填写姓名和性别。","pinyin":"Qǐng zài biǎogé lǐ tiánxiě xìngmíng hé xìngbié.","vi":"Xin hãy điền họ tên và giới tính vào biểu mẫu."},{"type":"simple","zh":"在填写个人简历时，通常需要注明姓名、性别、出生年月和联系方式。","pinyin":"Zài tiánxiě gèrén jiǎn lìshí, tōngcháng xūyào zhùmíng xìngmíng, xìngbié, chūshēng niányuè hé liánxì fāngshì.","vi":"Khi điền sơ yếu lý lịch cá nhân, thông thường cần ghi rõ họ tên, giới tính, ngày tháng năm sinh và thông tin liên hệ."},{"type":"compound","zh":"只要能力强，无论什么性别都可以申请这个职位。","pinyin":"Zhǐyào nénglì qiáng, wúlùn shénme xìngbié dōu kěyǐ shēnqǐng zhè ge zhíwèi.","vi":"Chỉ cần có năng lực, dù là giới tính nào cũng đều có thể ứng tuyển vị trí này."}],"related":[{"hanzi":"性格","pinyin":"xìnggé","vi":"Tính cách"},{"hanzi":"区别","pinyin":"qūbié","vi":"Khác biệt"},{"hanzi":"表格","pinyin":"biǎogé","vi":"Biểu mẫu"},{"hanzi":"男人","pinyin":"nánrén","vi":"Đàn ông"},{"hanzi":"女人","pinyin":"nǚrén","vi":"Phụ nữ"}],"traditional":"性別"},{"id":"性格","hanzi":"性格","pinyin":"xìnggé","meaning_vi":"tính cách","explanation":"性 (bản tính) + 格 (cách thức).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"她性格活泼开朗，很受欢迎。","pinyin":"Tā xìnggé huópō kāilǎng, hěn shòuhuānyíng.","vi":"Tính cách cô ấy hoạt bát cởi mở, rất được yêu mến."},{"type":"simple","zh":"虽然他们是双胞胎兄弟，但是两个人的性格却有很大的不同。","pinyin":"Suīrán tāmen shì shuāngbāotāi xiōngdì, dànshì liǎng ge rén de xìnggé què yǒu hěn dà de bùtóng.","vi":"Tuy họ là anh em sinh đôi nhưng tính cách của hai người lại có sự khác biệt rất lớn."},{"type":"compound","zh":"一个人只要保持积极热情的性格，无论走到哪里都能交到很多好朋友。","pinyin":"Yígerén zhǐyào bǎochí jījí rèqíng de xìnggé, wúlùn zǒu dào nǎlǐ dōu néng jiāo dào hěn duō hǎopéngyou.","vi":"Một người chỉ cần giữ tính cách tích cực nhiệt tình thì dù đi tới đâu cũng có thể kết giao được nhiều bạn tốt."}],"related":[{"hanzi":"性别","pinyin":"xìngbié","vi":"Giới tính"},{"hanzi":"脾气","pinyin":"píqi","vi":"Tính khí"},{"hanzi":"活泼","pinyin":"huópō","vi":"Hoạt bát"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"特点","pinyin":"tèdiǎn","vi":"Đặc điểm"}]},{"id":"修理","hanzi":"修理","pinyin":"xiūlǐ","meaning_vi":"sửa chữa","explanation":"修 (sửa) + 理 (chỉnh đốn).","hsk_level":3,"tags":["dong-tu"],"image":"🔧","examples":[{"type":"basic","zh":"爸爸正在修理自行车。","pinyin":"Bàba zhèngzài xiūlǐ zìxíngchē.","vi":"Bố đang sửa chữa xe đạp."},{"type":"simple","zh":"我的笔记本电脑昨天突然开不了机了，今天下午我得拿去电脑店修理。","pinyin":"Wǒ de bǐjìběn diànnǎo zuótiān tūrán kāi bùliǎo jī le, jīntiān xiàwǔ wǒ děi ná qù diànnǎo diàn xiūlǐ.","vi":"Chiếc máy tính xách tay của tôi hôm qua đột nhiên không bật lên được, chiều nay tôi phải mang ra tiệm máy tính sửa."},{"type":"compound","zh":"因为小区里的电梯正在进行定期检查和修理，所以大家今天只好走楼梯。","pinyin":"Yīnwèi xiǎoqū lǐ de diàntī zhèngzài jìnxíng dìngqī jiǎnchá hé xiūlǐ, suǒyǐ dàjiā jīntiān zhǐhǎo zǒu lóutī.","vi":"Vì thang máy trong khu chung cư đang tiến hành kiểm tra và sửa chữa định kỳ nên hôm nay mọi người đành đi thang bộ."}],"related":[{"hanzi":"坏","pinyin":"huài","vi":"Hỏng"},{"hanzi":"处理","pinyin":"chǔlǐ","vi":"Xử lý"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"},{"hanzi":"师傅","pinyin":"shīfu","vi":"Thợ lành nghề"},{"hanzi":"电脑","pinyin":"diànnǎo","vi":"Máy tính"}]},{"id":"许多","hanzi":"许多","pinyin":"xǔduō","meaning_vi":"rất nhiều","explanation":"许 + 多 (nhiều). Đồng nghĩa với 很多.","hsk_level":3,"tags":["tinh-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"公园里有许多人在散步。","pinyin":"Gōngyuán lǐ yǒu xǔduō rén zài sànbù.","vi":"Trong công viên có rất nhiều người đang đi dạo."},{"type":"simple","zh":"中国有许多名胜古迹，每年都吸引着成千上万的外国游客。","pinyin":"Zhōng guóyǒu xǔduō míngshènggǔjì, měinián dōu xīyǐnzhe chéngqiānshàngwàn de wàiguó yóukè.","vi":"Trung Quốc có rất nhiều danh lam thắng cảnh, hằng năm đều thu hút hàng vạn du khách nước ngoài."},{"type":"compound","zh":"通过阅读这本杂志，我学到了许多关于环境保护和健康生活的新知识。","pinyin":"Tōngguò yuèdú zhè běn zázhì, wǒ xuédàole xǔduō guānyú huánjìngbǎohù hé jiànkāng shēnghuó de xīn zhīshi.","vi":"Thông qua việc đọc cuốn tạp chí này, tôi đã học được rất nhiều kiến thức mới về bảo vệ môi trường và sống khỏe."}],"related":[{"hanzi":"很多","pinyin":"hěnduō","vi":"Rất nhiều"},{"hanzi":"也许","pinyin":"yěxǔ","vi":"Có lẽ"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"Cho phép"},{"hanzi":"数量","pinyin":"shùliàng","vi":"Số lượng"},{"hanzi":"多","pinyin":"duō","vi":"Nhiều"}],"traditional":"許多"},{"id":"学期","hanzi":"学期","pinyin":"xuéqī","meaning_vi":"học kỳ","explanation":"学 (học) + 期 (kỳ hạn).","hsk_level":3,"tags":["danh-tu","hoc-tap","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"新学期马上就要开始了。","pinyin":"Xīn xuéqī mǎshàng jiùyào kāishǐ le.","vi":"Học kỳ mới sắp bắt đầu ngay bây giờ rồi."},{"type":"simple","zh":"这个学期我选修了中国历史、书法和太极拳三门文化课。","pinyin":"Zhè ge xuéqī wǒ xuǎnxiūle Zhōngguó lìshǐ, shūfǎ hé tàijíquán Sānmén wénhuà kè.","vi":"Học kỳ này tôi đã đăng ký học ba môn văn hóa là lịch sử Trung Quốc, thư pháp và Thái Cực Quyền."},{"type":"compound","zh":"虽然这学期课程安排得很满，但是因为每门课都很有趣，所以我学得很开心。","pinyin":"Suīrán zhè xuéqī kèchéng ānpái de hěn mǎn, dànshì yīnwèi měi mén kè dōu hěn yǒuqù, suǒyǐ wǒ xué de hěn kāixīn.","vi":"Tuy học kỳ này lịch học sắp xếp rất kín nhưng vì môn nào cũng thú vị nên tôi học rất vui vẻ."}],"related":[{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"Trường học"},{"hanzi":"星期","pinyin":"xīngqī","vi":"Tuần"},{"hanzi":"寒假","pinyin":"hánjià","vi":"Kỳ nghỉ đông"},{"hanzi":"放暑假","pinyin":"fàngshǔjià","vi":"Nghỉ hè"}],"traditional":"學期"},{"id":"压力","hanzi":"压力","pinyin":"yālì","meaning_vi":"áp lực","explanation":"压 (đè nén) + 力 (sức lực).","hsk_level":3,"tags":["danh-tu","cam-xuc"],"image":"😫","examples":[{"type":"basic","zh":"最近他的工作压力很大。","pinyin":"Zuìjìn tā de gōngzuò yālì hěn dà.","vi":"Dạo này áp lực công việc của anh ấy rất lớn."},{"type":"simple","zh":"面对期末考试的压力，同学们每天都在图书馆认真复习功课。","pinyin":"Miànduì qīmò kǎoshì de yālì, tóngxuémen měitiān dōu zài túshūguǎn rènzhēn fùxí gōngkè.","vi":"Đối mặt với áp lực kỳ thi cuối kỳ, các bạn học ngày nào cũng chăm chỉ ôn bài ở thư viện."},{"type":"compound","zh":"当生活和工作压力大的时候，去公园跑跑步或者跟朋友聊聊天可以有效放松心情。","pinyin":"Dāng shēnghuó hé gōngzuò yālì dà de shíhou, qù gōngyuán pǎo paobù huòzhě gēn péngyou liáo liaotiān kěyǐ yǒuxiào fàngsōng xīnqíng.","vi":"Khi áp lực cuộc sống và công việc lớn, ra công viên chạy bộ hoặc trò chuyện với bạn bè có thể giải tỏa tâm trạng hiệu quả."}],"related":[{"hanzi":"力气","pinyin":"lìqi","vi":"Sức lực"},{"hanzi":"能力","pinyin":"nénglì","vi":"Năng lực"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"Căng thẳng"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"Thư giãn"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"Nhẹ nhàng"}],"traditional":"壓力"},{"id":"呀","hanzi":"呀","pinyin":"ya","meaning_vi":"a, à, nhỉ (trợ từ ngữ khí)","explanation":"Biến âm của 啊 khi đứng sau nguyên âm a, e, i, o, ü.","hsk_level":3,"tags":["tro-tu"],"image":"😮","examples":[{"type":"basic","zh":"快进来呀，外面冷！","pinyin":"Kuài jìnlái ya, wàimiàn lěng!","vi":"Mau vào đi, bên ngoài lạnh đấy!"},{"type":"simple","zh":"这件红色的裙子穿在你身上真漂亮呀，就像仙女一样！","pinyin":"Zhè jiàn hóngsè de qúnzi chuān zài nǐ shēnshang zhēn piàoliang ya, jiù xiàng xiānnǚ yíyàng!","vi":"Chiếc váy màu đỏ này mặc lên người bạn đẹp thật đấy, cứ như tiên nữ vậy!"},{"type":"compound","zh":"时间过得真快呀，一转眼我们都已经毕业离开大学五年了！","pinyin":"Shíjiān guòde zhēn kuài ya, yìzhuǎnyǎn wǒmen dōu yǐjīng bìyè líkāi dàxué wǔ nián le!","vi":"Thời gian trôi nhanh thật đấy, chớp mắt một cái chúng ta đều đã tốt nghiệp rời trường đại học 5 năm rồi!"}],"related":[{"hanzi":"啊","pinyin":"a","vi":"A/À"},{"hanzi":"吧","pinyin":"ba","vi":"Nhé/Đi"},{"hanzi":"呢","pinyin":"ne","vi":"Nhỉ"},{"hanzi":"吗","pinyin":"ma","vi":"Không"},{"hanzi":"真","pinyin":"zhēn","vi":"Thật"}]},{"id":"牙膏","hanzi":"牙膏","pinyin":"yágāo","meaning_vi":"kem đánh răng","explanation":"牙 (răng) + 膏 (thuốc mỡ/kem).","hsk_level":3,"tags":["danh-tu","do-vat","sinh-hoat"],"image":"🪥","examples":[{"type":"basic","zh":"超市里的牙膏正在打折。","pinyin":"Chāoshì lǐ de yágāo zhèngzài dǎzhé.","vi":"Kem đánh răng trong siêu thị đang giảm giá."},{"type":"simple","zh":"卫生间里的牙膏快用完了，我下班回家的路上顺便买一支。","pinyin":"Wèishēngjiān lǐ de yágāo kuài yòng wánle, wǒ xiàbān huíjiā de lùshang shùnbiàn mǎi yì zhī.","vi":"Kem đánh răng trong nhà vệ sinh sắp hết rồi, trên đường tan làm về nhà tôi tiện thể mua một tuýp."},{"type":"compound","zh":"出差或者旅游住宾馆时，很多环保型宾馆不再免费提供一次性牙刷和牙膏了。","pinyin":"Chūchāi huòzhě lǚyóu zhù bīnguǎn shí, hěn duō huánbǎoxíng bīnguǎn bú zài miǎnfèi tígōng yícìxìng yáshuā hé yágāo le.","vi":"Khi đi công tác hoặc du lịch ở khách sạn, nhiều khách sạn thân thiện môi trường không còn cung cấp miễn phí bàn chải và kem đánh răng dùng một lần nữa."}],"related":[{"hanzi":"刷牙","pinyin":"shuāyá","vi":"Đánh răng"},{"hanzi":"毛巾","pinyin":"máojīn","vi":"Khăn mặt"},{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"Nhà vệ sinh"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"洗","pinyin":"xǐ","vi":"Rửa"}]},{"id":"亚洲","hanzi":"亚洲","pinyin":"Yàzhōu","meaning_vi":"châu Á","explanation":"亚 (Á) + 洲 (châu lục).","hsk_level":3,"tags":["danh-tu","dia-danh"],"image":"🌏","examples":[{"type":"basic","zh":"中国和越南都在亚洲。","pinyin":"Zhōngguó hé Yuènán dōu zài Yàzhōu.","vi":"Trung Quốc và Việt Nam đều nằm ở châu Á."},{"type":"simple","zh":"亚洲是世界上面积最大、人口最多的一个大洲。","pinyin":"Yàzhōu shì shìjiè shang miànjī zuì dà, rénkǒu zuì duō de yí ge dàzhōu.","vi":"Châu Á là châu lục có diện tích lớn nhất và dân số đông nhất trên thế giới."},{"type":"compound","zh":"虽然亚洲各国的语言各不相同，但是很多国家在饮食和节日文化上都有相似之处。","pinyin":"Suīrán Yàzhōu gèguó de yǔyán gè bù xiāngtóng, dànshì hěn duō guójiā zài yǐnshí hé jiérì wénhuà Shangdōu yǒu xiāngsì zhī chù.","vi":"Tuy ngôn ngữ của các nước châu Á không giống nhau nhưng nhiều quốc gia có nét tương đồng về ẩm thực và văn hóa lễ hội."}],"related":[{"hanzi":"国家","pinyin":"guójiā","vi":"Quốc gia"},{"hanzi":"地球","pinyin":"dìqiú","vi":"Trái Đất"},{"hanzi":"国际","pinyin":"Guójì","vi":"Quốc tế"},{"hanzi":"中国","pinyin":"Zhōngguó","vi":"Trung Quốc"},{"hanzi":"越南","pinyin":"Yuènán","vi":"Việt Nam"}],"traditional":"亞洲"},{"id":"严格","hanzi":"严格","pinyin":"yángé","meaning_vi":"nghiêm khắc, nghiêm ngặt","explanation":"严 (nghiêm) + 格 (tiêu chuẩn).","hsk_level":3,"tags":["tinh-tu","hoc-tap"],"image":"🧐","examples":[{"type":"basic","zh":"王老师对学生要求很严格。","pinyin":"Wáng lǎoshī duì xuésheng yāoqiú hěn yángé.","vi":"Thầy Vương yêu cầu rất nghiêm khắc đối với học sinh."},{"type":"simple","zh":"这家工厂生产的每一件产品都必须经过严格的质量检查。","pinyin":"Zhè jiā gōngchǎng shēngchǎn de měi yí jiàn chǎnpǐn dōu bìxū jīngguò yángé de zhìliàng jiǎnchá.","vi":"Mỗi sản phẩm do nhà máy này sản xuất đều bắt buộc phải trải qua khâu kiểm tra chất lượng nghiêm ngặt."},{"type":"compound","zh":"虽然爸爸平时对我的学习要求非常严格，但是我知道他都是为了我的将来着想。","pinyin":"Suīrán bàba píngshí duì wǒ de xuéxí yāoqiú fēicháng yángé, dànshì wǒ zhīdao tā dōu shì wèile wǒ de jiānglái zhuóxiǎng.","vi":"Tuy bình thường bố yêu cầu rất nghiêm khắc về việc học của tôi nhưng tôi biết bố đều nghĩ cho tương lai của tôi."}],"related":[{"hanzi":"严重","pinyin":"yánzhòng","vi":"Nghiêm trọng"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"合格","pinyin":"hégé","vi":"Đạt chuẩn"},{"hanzi":"规定","pinyin":"guīdìng","vi":"Quy định"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"}],"traditional":"嚴格"},{"id":"严重","hanzi":"严重","pinyin":"yánzhòng","meaning_vi":"nghiêm trọng","explanation":"严 (nghiêm) + 重 (nặng nề).","hsk_level":3,"tags":["tinh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"他的感冒很严重，需要住院。","pinyin":"Tā de gǎnmào hěn yánzhòng, xūyào zhùyuàn.","vi":"Bệnh cảm cúm của anh ấy rất nặng, cần phải nhập viện."},{"type":"simple","zh":"早高峰的时候，这条高速公路上经常发生严重的堵车现象。","pinyin":"Zǎogāofēng de shíhou, zhè tiáo gāosùgōnglù shang jīngcháng fāshēng yánzhòng de dǔchē xiànxiàng.","vi":"Vào giờ cao điểm buổi sáng, trên tuyến đường cao tốc này thường xuyên xảy ra tình trạng tắc đường nghiêm trọng."},{"type":"compound","zh":"如果工厂继续向河里排放污水，将会对周围的生态环境造成严重的污染。","pinyin":"Rúguǒ gōngchǎng jìxù xiàng hé lǐ páifàng wūshuǐ, jiānghuì duì zhōuwéi de shēngtài huánjìng zàochéng yánzhòng de wūrǎn.","vi":"Nếu nhà máy tiếp tục xả nước thải xuống sông thì sẽ gây ô nhiễm nghiêm trọng cho môi trường sinh thái xung quanh."}],"related":[{"hanzi":"严格","pinyin":"yángé","vi":"Nghiêm khắc"},{"hanzi":"重","pinyin":"zhòng","vi":"Nặng"},{"hanzi":"厉害","pinyin":"lìhai","vi":"Dữ dội"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"Ô nhiễm"},{"hanzi":"问题","pinyin":"wèntí","vi":"Vấn đề"}],"traditional":"嚴重"},{"id":"研究","hanzi":"研究","pinyin":"yánjiū","meaning_vi":"nghiên cứu","explanation":"研 (mài giũa) + 究 (tìm tòi).","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"他正在研究中国历史。","pinyin":"Tā zhèngzài yánjiū Zhōngguó lìshǐ.","vi":"Anh ấy đang nghiên cứu lịch sử Trung Quốc."},{"type":"simple","zh":"我哥哥大学毕业以后考上了北京大学的研究生，专门研究环境保护技术。","pinyin":"Wǒ gēge dàxué bìyè yǐhòu kǎoshàngle Běijīngdàxué de yánjiūshēng, zhuānmén yánjiū huánjìngbǎohù jìshù.","vi":"Sau khi tốt nghiệp đại học, anh trai tôi thi đỗ nghiên cứu sinh Đại học Bắc Kinh, chuyên nghiên cứu công nghệ bảo vệ môi trường."},{"type":"compound","zh":"经过科学家们多年的深入研究，这种新药终于成功上市并治好了很多病人。","pinyin":"Jīngguò kēxuéjiāmen duōnián de shēnrù yánjiū, zhè zhǒng xīn yào zhōngyú chénggōng shàngshì bìng zhìhǎole hěn duō bìngrén.","vi":"Trải qua nhiều năm nghiên cứu chuyên sâu của các nhà khoa học, loại thuốc mới này cuối cùng đã ra mắt thành công và chữa khỏi cho nhiều bệnh nhân."}],"related":[{"hanzi":"硕士","pinyin":"shuòshì","vi":"Thạc sĩ"},{"hanzi":"博士","pinyin":"bóshì","vi":"Tiến sĩ"},{"hanzi":"科学","pinyin":"kēxué","vi":"Khoa học"},{"hanzi":"调查","pinyin":"diàochá","vi":"Điều tra"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"}]},{"id":"盐","hanzi":"盐","pinyin":"yán","meaning_vi":"muối","explanation":"Gia vị nấu ăn (食盐 - muối ăn).","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🧂","examples":[{"type":"basic","zh":"做菜的时候别放太多盐。","pinyin":"Zuòcài de shíhou bié fàng tài duō yán.","vi":"Khi nấu ăn đừng cho quá nhiều muối."},{"type":"simple","zh":"今天妈妈炒菜时不小心多放了一勺盐，结果菜吃起来有点儿咸。","pinyin":"Jīntiān māma chǎocài shí bù xiǎoxīn duōfàngle yì sháo yán, jiéguǒ cài chī qǐlái yǒudiǎnr xián.","vi":"Hôm nay lúc xào rau mẹ lỡ tay cho thêm một thìa muối, kết quả món ăn hơi mặn một chút."},{"type":"compound","zh":"医生建议高血压患者平时饮食一定要清淡，每天摄入的盐分不能超过标准。","pinyin":"Yīshēng jiànyì gāoxuèyā huànzhě píngshí yǐnshí yídìngyào qīngdàn, měitiān shèrù de yánfèn bù néng chāoguò biāozhǔn.","vi":"Bác sĩ khuyên bệnh nhân cao huyết áp bình thường ăn uống nhất định phải thanh đạm, lượng muối nạp vào mỗi ngày không được vượt quá tiêu chuẩn."}],"related":[{"hanzi":"咸","pinyin":"xián","vi":"Mặn"},{"hanzi":"糖","pinyin":"táng","vi":"Đường"},{"hanzi":"菜","pinyin":"cài","vi":"Món ăn"},{"hanzi":"味道","pinyin":"wèidào","vi":"Mùi vị"},{"hanzi":"做饭","pinyin":"zuòfàn","vi":"Nấu cơm"}],"traditional":"鹽"},{"id":"演出","hanzi":"演出","pinyin":"yǎnchū","meaning_vi":"biểu diễn, buổi biểu diễn","explanation":"演 (diễn) + 出 (ra).","hsk_level":3,"tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"今晚的文艺演出非常精彩。","pinyin":"Jīnwǎn de wényì yǎnchū fēicháng jīngcǎi.","vi":"Buổi biểu diễn văn nghệ tối nay vô cùng đặc sắc."},{"type":"simple","zh":"为了准备这次新年演出，演员们已经连续排练了好几个星期。","pinyin":"Wèile zhǔnbèi zhè cì xīnnián yǎnchū, yǎnyuánmen yǐjīng liánxù páiliànle hǎojǐ ge xīngqī.","vi":"Để chuẩn bị cho buổi diễn năm mới lần này, các diễn viên đã tập luyện liên tục mấy tuần liền."},{"type":"compound","zh":"虽然这场京剧演出的票价有点儿贵，但是因为有著名演员参加，票很快就卖完了。","pinyin":"Suīrán zhè chǎng Jīngjù yǎnchū de piàojià yǒudiǎnr guì, dànshì yīnwèi yǒu zhùmíng yǎnyuán cānjiā, piào hěn kuài jiù mài wánle.","vi":"Tuy giá vé buổi biểu diễn Kinh kịch này hơi đắt một chút nhưng vì có diễn viên nổi tiếng tham gia nên vé đã bán hết veo."}],"related":[{"hanzi":"演员","pinyin":"yǎnyuán","vi":"Diễn viên"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"Biểu diễn"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"Khán giả"},{"hanzi":"京剧","pinyin":"Jīngjù","vi":"Kinh kịch"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"Đặc sắc"}]},{"id":"演员","hanzi":"演员","pinyin":"yǎnyuán","meaning_vi":"diễn viên","explanation":"演 (diễn xuất) + 员 (nhân viên/người).","hsk_level":3,"tags":["danh-tu","nghe-nghiep","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"她是一位著名的电影演员。","pinyin":"Tā shì yí wèi zhùmíng de diànyǐng yǎnyuán.","vi":"Cô ấy là một diễn viên điện ảnh nổi tiếng."},{"type":"simple","zh":"这位年轻演员虽然出道时间不长，但是演技非常自然真实，深受观众喜爱。","pinyin":"Zhè wèi niánqīng yǎnyuán suīrán chūdào shíjiān bù cháng, dànshì yǎnjì fēicháng zìrán zhēnshí, shēnshòu guānzhòng xǐ'ài.","vi":"Diễn viên trẻ này tuy mới vào nghề chưa lâu nhưng diễn xuất vô cùng tự nhiên chân thực, được khán giả hết mực yêu mến."},{"type":"compound","zh":"为了演好这个历史人物，演员在电影开拍前阅读了大量相关的历史资料。","pinyin":"Wèile yǎn hǎo zhè ge lìshǐ rénwù, yǎnyuán zài diànyǐng kāipāi qián yuèdúle dàliàng xiāngguān de lìshǐ zīliào.","vi":"Để đóng tốt nhân vật lịch sử này, diễn viên đã đọc rất nhiều tài liệu lịch sử liên quan trước khi bộ phim bấm máy."}],"related":[{"hanzi":"演出","pinyin":"yǎnchū","vi":"Biểu diễn"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"Biểu diễn"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"Khán giả"},{"hanzi":"电影","pinyin":"diànyǐng","vi":"Phim"},{"hanzi":"艺术","pinyin":"yìshù","vi":"Nghệ thuật"}],"traditional":"演員"},{"id":"阳光","hanzi":"阳光","pinyin":"yángguāng","meaning_vi":"ánh nắng mặt trời","explanation":"阳 (mặt trời) + 光 (ánh sáng).","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"☀️","examples":[{"type":"basic","zh":"今天阳光明媚，天气真好。","pinyin":"Jīntiān yángguāng míngmèi, tiānqì zhēn hǎo.","vi":"Hôm nay ánh nắng rực rỡ, thời tiết đẹp thật đấy."},{"type":"simple","zh":"每天早上拉开窗帘，温暖的阳光照进房间里，让人觉得心情特别愉快。","pinyin":"Měitiān zǎoshang lākāi chuānglián, wēnnuǎn de yáng guāngzhào jìn fángjiān lǐ, ràng rén juéde xīnqíng tèbié yúkuài.","vi":"Mỗi sáng kéo rèm cửa ra, ánh nắng ấm áp chiếu vào trong phòng khiến tâm trạng con người trở nên đặc biệt vui vẻ."},{"type":"compound","zh":"植物的生长离不开阳光、空气和水，就像孩子的成长离不开父母的关爱一样。","pinyin":"Zhíwù de shēngzhǎng líbùkāi yángguāng, kōngqì hé shuǐ, jiù xiàng háizi de chéngzhǎng líbùkāi fùmǔ de guān'ài yíyàng.","vi":"Sự sinh trưởng của thực vật không thể thiếu ánh nắng, không khí và nước, cũng giống như sự trưởng thành của trẻ nhỏ không thể thiếu tình yêu thương của bố mẹ."}],"related":[{"hanzi":"太阳","pinyin":"tàiyáng","vi":"Mặt trời"},{"hanzi":"光","pinyin":"guāng","vi":"Ánh sáng"},{"hanzi":"晴天","pinyin":"qíngtiān","vi":"Ngày nắng"},{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"Ấm áp"},{"hanzi":"植物","pinyin":"zhíwù","vi":"Thực vật"}],"traditional":"陽光"},{"id":"养成","hanzi":"养成","pinyin":"yǎngchéng","meaning_vi":"hình thành, rèn luyện (thói quen)","explanation":"养 (nuôi dưỡng) + 成 (thành). Cụm: 养成好习惯.","hsk_level":3,"tags":["dong-tu"],"image":"🌱","examples":[{"type":"basic","zh":"我们要养成早睡早起的好习惯。","pinyin":"Wǒmen yào yǎngchéng zǎo shuì zǎoqǐ de hǎo xíguàn.","vi":"Chúng ta phải hình thành thói quen tốt là ngủ sớm dậy sớm."},{"type":"simple","zh":"每天坚持阅读半个小时，久而久之就能养成热爱读书的好习惯。","pinyin":"Měitiān jiānchí yuèdú bàn ge xiǎoshí, jiǔ ér jiǔzhī jiù néng yǎngchéng rè'ài dúshū de hǎo xíguàn.","vi":"Mỗi ngày kiên trì đọc sách nửa tiếng, lâu dần sẽ hình thành thói quen tốt yêu thích đọc sách."},{"type":"compound","zh":"从小培养孩子独立思考和自己收拾房间的能力，有助于他们养成良好的生活习惯。","pinyin":"Cóngxiǎo péiyǎng háizi dúlì sīkǎo hé zìjǐ shōushi fángjiān de nénglì, yǒuzhùyú tāmen yǎngchéng liánghǎo de shēnghuó xíguàn.","vi":"Rèn luyện cho trẻ khả năng tư duy độc lập và tự dọn phòng từ nhỏ sẽ giúp trẻ hình thành thói quen sinh hoạt tốt."}],"related":[{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"},{"hanzi":"成为","pinyin":"chéngwéi","vi":"Trở thành"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"培养","pinyin":"péiyǎng","vi":"Bồi dưỡng"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"Kiên trì"}],"traditional":"養成"},{"id":"样子","hanzi":"样子","pinyin":"yàngzi","meaning_vi":"dáng vẻ, kiểu dáng, bộ dạng","explanation":"样 (mẫu) + hậu tố 子.","hsk_level":3,"tags":["danh-tu"],"image":"👤","examples":[{"type":"basic","zh":"看他的样子好像很着急。","pinyin":"Kàn tā de yàngzi hǎoxiàng hěn zháojí.","vi":"Nhìn bộ dạng của anh ấy hình như đang rất vội."},{"type":"simple","zh":"天上飘来了这么多黑云，看样子今天下午肯定要下大雨了。","pinyin":"Tiānshang piāo láile zhème duō hēi yún, kànyàngzi jīntiān xiàwǔ kěndìng yào xià dàyǔ le.","vi":"Trên trời kéo đến nhiều mây đen thế này, xem chừng chiều nay chắc chắn trời sẽ mưa to rồi."},{"type":"compound","zh":"虽然我们已经十年没见面了，但是他说话和笑起来的样子跟大学时一模一样。","pinyin":"Suīrán wǒmen yǐjīng shí nián méi jiànmiàn le, dànshì tā shuōhuà hé xiào qǐlái de yàngzi gēn dàxué shí yìmúyíyàng.","vi":"Tuy chúng tôi đã 10 năm không gặp nhau nhưng dáng vẻ lúc anh ấy nói chuyện và mỉm cười vẫn giống hệt hồi đại học."}],"related":[{"hanzi":"一样","pinyin":"yíyàng","vi":"Giống nhau"},{"hanzi":"怎么样","pinyin":"zěnmeyàng","vi":"Thế nào"},{"hanzi":"好像","pinyin":"hǎoxiàng","vi":"Hình như"},{"hanzi":"态度","pinyin":"tàidu","vi":"Thái độ"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"Ấn tượng"}],"traditional":"樣子"},{"id":"邀请","hanzi":"邀请","pinyin":"yāoqǐng","meaning_vi":"mời, lời mời","explanation":"邀 (đón mời) + 请 (mời).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"谢谢你邀请我参加聚会。","pinyin":"Xièxie nǐ yāoqǐng wǒ cānjiā jùhuì.","vi":"Cảm ơn bạn đã mời tôi tham gia buổi tụ họp."},{"type":"simple","zh":"下个星期六是我的生日，我想邀请几位好朋友来家里一起吃晚饭。","pinyin":"Xiàge Xīngqīliù shì wǒ de shēngrì, wǒ xiǎng yāoqǐng jǐ wèi hǎopéngyou lái jiālǐ yìqǐ chī wǎnfàn.","vi":"Thứ Bảy tuần sau là sinh nhật tôi, tôi muốn mời vài người bạn thân đến nhà cùng ăn bữa tối."},{"type":"compound","zh":"我们学校邀请了一位著名的历史教授来为大家做一场精彩的学术讲座。","pinyin":"Wǒmen xuéxiào yāoqǐngle yí wèi zhùmíng de lìshǐ jiàoshòu lái wèi dàjiā zuò yì chǎng jīngcǎi de xuéshù jiǎngzuò.","vi":"Trường chúng tôi đã mời một vị giáo sư lịch sử nổi tiếng đến diễn thuyết một buổi chuyên đề đặc sắc cho mọi người."}],"related":[{"hanzi":"请","pinyin":"qǐng","vi":"Mời"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"Nộp đơn xin"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"Tụ họp"},{"hanzi":"拒绝","pinyin":"jùjué","vi":"Từ chối"},{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"}],"traditional":"邀請"},{"id":"要是","hanzi":"要是","pinyin":"yàoshi","meaning_vi":"nếu, nếu như","explanation":"Đồng nghĩa với 如果, dùng phổ biến trong văn nói.","hsk_level":3,"tags":["lien-tu"],"image":"❓","examples":[{"type":"basic","zh":"要是明天下雨，我们就不去爬山了。","pinyin":"Yàoshi míngtiān xiàyǔ, wǒmen jiù bú qù páshān le.","vi":"Nếu ngày mai trời mưa thì chúng ta sẽ không đi leo núi nữa."},{"type":"simple","zh":"要是你在学习汉语的过程中遇到不懂的问题，随时可以来问我。","pinyin":"Yàoshi nǐ zài xuéxí Hànyǔ de guòchéng zhōng yùdào bù dǒng de wèntí, suíshí kěyǐ lái wèn wǒ.","vi":"Nếu trong quá trình học tiếng Trung bạn gặp vấn đề không hiểu thì bất cứ lúc nào cũng có thể đến hỏi tôi."},{"type":"compound","zh":"出门之前一定要检查好随身物品，要是把护照弄丢了可就麻烦了。","pinyin":"Chūmén zhīqián yídìngyào jiǎnchá hǎo suíshēn wùpǐn, yàoshi bǎ hùzhào nòngdiūle kějiù máfan le.","vi":"Trước khi ra khỏi nhà nhất định phải kiểm tra kỹ đồ đạc mang theo, nếu làm mất hộ chiếu thì phiền phức to đấy."}],"related":[{"hanzi":"如果","pinyin":"rúguǒ","vi":"Nếu như"},{"hanzi":"只要","pinyin":"zhǐyào","vi":"Chỉ cần"},{"hanzi":"就","pinyin":"jiù","vi":"Thì/Liền"},{"hanzi":"要","pinyin":"yào","vi":"Muốn/Cần"},{"hanzi":"钥匙","pinyin":"yàoshi","vi":"Chìa khóa"}]},{"id":"钥匙","hanzi":"钥匙","pinyin":"yàoshi","meaning_vi":"chìa khóa","explanation":"钥 (thược – khóa) + 匙 (thi – cái thìa; ở đây đọc nhẹ shi) → chìa khóa. Lượng từ 把: 一把钥匙.","hsk_level":3,"tags":["danh-tu","do-vat","nha-cua"],"image":"🔑","examples":[{"type":"basic","zh":"我忘带房间钥匙了。","pinyin":"Wǒ wàng dài fángjiān yàoshi le.","vi":"Tôi quên mang chìa khóa phòng rồi."},{"type":"simple","zh":"我把家门钥匙放在书包里的小口袋里了，这样找起来很方便。","pinyin":"Wǒ bǎ jiāmén yàoshi fàng zài shūbāo lǐ de xiǎo kǒudài lǐ le, zhèyàng zhǎo qǐlái hěn fāngbiàn.","vi":"Tôi để chìa khóa cửa nhà vào ngăn túi nhỏ trong cặp sách, như vậy lúc tìm rất tiện."},{"type":"compound","zh":"因为今天早上出门太着急把钥匙锁在屋里了，所以我只好请开锁师傅来帮忙。","pinyin":"Yīnwèi jīntiān zǎoshang chūmén tài zháojí bǎ yàoshi suǒ zài wū lǐ le, suǒyǐ wǒ zhǐhǎo qǐng kāisuǒ shīfu lái bāngmáng.","vi":"Vì sáng nay ra khỏi nhà vội quá nên khóa luôn chìa khóa ở trong nhà, tôi đành phải gọi thợ mở khóa đến giúp."}],"related":[{"hanzi":"门","pinyin":"mén","vi":"Cửa"},{"hanzi":"锁","pinyin":"suǒ","vi":"Khóa"},{"hanzi":"开","pinyin":"kāi","vi":"Mở"},{"hanzi":"关","pinyin":"guān","vi":"Đóng"},{"hanzi":"丢","pinyin":"diū","vi":"Mất"}],"traditional":"鑰匙"},{"id":"也许","hanzi":"也许","pinyin":"yěxǔ","meaning_vi":"có lẽ, biết đâu","explanation":"也 (cũng) + 许 (cho phép/có thể).","hsk_level":3,"tags":["pho-tu"],"image":"🤔","examples":[{"type":"basic","zh":"他今天也许不会来了。","pinyin":"Tā jīntiān yěxǔ bú huì lái le.","vi":"Hôm nay có lẽ anh ấy sẽ không đến đâu."},{"type":"simple","zh":"天阴沉沉的，看样子下午也许会有一场阵雨，出门还是带把伞吧。","pinyin":"Tiān yīnchénchén de, kànyàngzi xiàwǔ yěxǔ huì yǒu yì chǎng zhènyǔ, chūmén háishi dài bǎ sǎn ba.","vi":"Trời âm u mây mù, xem chừng buổi chiều có lẽ sẽ có một trận mưa rào, ra ngoài vẫn nên mang theo ô đi."},{"type":"compound","zh":"虽然现在学写汉字觉得有点儿难，但是也许过几个月你就会爱上书法了。","pinyin":"Suīrán xiànzài xué xiě hànzì juéde yǒudiǎnr nán, dànshì yěxǔguò jǐ geyuè nǐ jiù huì àishàng shūfǎ le.","vi":"Tuy bây giờ học viết chữ Hán thấy hơi khó một chút nhưng biết đâu vài tháng nữa bạn lại mê thư pháp thì sao."}],"related":[{"hanzi":"可能","pinyin":"kěnéng","vi":"Có thể"},{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"许多","pinyin":"xǔduō","vi":"Rất nhiều"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"Cho phép"},{"hanzi":"也","pinyin":"yě","vi":"Cũng"}],"traditional":"也許"},{"id":"叶子","hanzi":"叶子","pinyin":"yèzi","meaning_vi":"chiếc lá, lá cây","explanation":"叶 (lá) + hậu tố 子.","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🍃","examples":[{"type":"basic","zh":"秋风吹落了树上的黄叶子。","pinyin":"Qiū fēng chuī luòle shù shang de huáng yèzi.","vi":"Gió thu thổi rụng những chiếc lá vàng trên cây."},{"type":"simple","zh":"春天来了，公园里的大树都长出了嫩绿的新叶子，显得生机勃勃。","pinyin":"Chūntiān lái le, gōngyuán lǐ de dà shù dōu zhǎngchūle nènlǜ de xīn yèzi, xiǎnde shēngjībóbó.","vi":"Mùa xuân đến rồi, cây to trong công viên đều mọc ra lá non xanh mướt, trông tràn đầy sức sống."},{"type":"compound","zh":"虽然这棵植物我已经每天浇水了，但是不知道为什么它的叶子还是变黄了。","pinyin":"Suīrán zhè kē zhíwù wǒ yǐjīng měitiān jiāoshuǐ le, dànshì bù zhīdao wèishénme tā de yèzi háishi biàn huángle.","vi":"Tuy cây cảnh này ngày nào tôi cũng tưới nước nhưng không biết tại sao lá của nó vẫn bị ngả vàng."}],"related":[{"hanzi":"树","pinyin":"shù","vi":"Cây"},{"hanzi":"花","pinyin":"huā","vi":"Hoa"},{"hanzi":"植物","pinyin":"zhíwù","vi":"Thực vật"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"绿","pinyin":"lǜ","vi":"Xanh lá"}],"traditional":"葉子"},{"id":"页","hanzi":"页","pinyin":"yè","meaning_vi":"trang (sách/vở)","explanation":"Lượng từ/danh từ chỉ trang sách (第一页 - trang 1).","hsk_level":3,"tags":["luong-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"请大家打开书第十页。","pinyin":"Qǐng dàjiā dǎkāi shū dì shí yè.","vi":"Xin mọi người mở sách trang thứ 10."},{"type":"simple","zh":"这本中文小说一共有三百多页，我已经看了将近两百页了。","pinyin":"Zhè běn Zhōngwén xiǎoshuō yí gòngyǒu sān bǎi duō yè, wǒ yǐjīng kànle jiāngjìn liǎng bǎi yè le.","vi":"Cuốn tiểu thuyết tiếng Trung này có tổng cộng hơn 300 trang, tôi đã đọc được gần 200 trang rồi."},{"type":"compound","zh":"因为这本书的最后一页不小心被撕破了，所以我不知道故事的结局是什么。","pinyin":"Yīnwèi zhè běn shū de zuìhòu yí yè bù xiǎoxīn bèi sīpò le, suǒyǐ wǒ bù zhīdao gùshi de jiéjú shì shénme.","vi":"Vì trang cuối cùng của quyển sách này vô tình bị xé rách nên tôi không biết kết cục câu chuyện ra sao."}],"related":[{"hanzi":"篇","pinyin":"piān","vi":"Bài (lượng từ)"},{"hanzi":"本","pinyin":"běn","vi":"Quyển"},{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"Đọc hiểu"},{"hanzi":"内容","pinyin":"nèiróng","vi":"Nội dung"}],"traditional":"頁"},{"id":"一切","hanzi":"一切","pinyin":"yíqiè","meaning_vi":"tất cả, mọi thứ","explanation":"一 + 切 (cắt/toàn bộ).","hsk_level":3,"tags":["dai-tu"],"image":"🌐","examples":[{"type":"basic","zh":"祝你在这里一切顺利！","pinyin":"Zhù nǐ zài zhèlǐ yíqiè shùnlì!","vi":"Chúc bạn ở đây mọi thứ thuận lợi!"},{"type":"simple","zh":"对我来说，全家人平平安安、健健康康比一切都重要。","pinyin":"Duì wǒ lái shuō, quán jiārén píngpíng ān'ān, jiàn jiànkāng kāng bǐ yíqiè dōu zhòngyào.","vi":"Đối với tôi, cả nhà bình an, khỏe mạnh quan trọng hơn tất cả."},{"type":"compound","zh":"虽然刚开始来中国留学时遇到了一些困难，但是现在一切都已经步入正轨了。","pinyin":"Suīrán gāng kāishǐ lái Zhōngguó liúxué shí yùdàole yìxiē kùnnan, dànshì xiànzài yíqiè dōu yǐjīng bùrù zhèngguǐ le.","vi":"Tuy lúc mới đến Trung Quốc du học có gặp đôi chút khó khăn nhưng hiện tại mọi thứ đều đã đi vào quỹ đạo ổn định."}],"related":[{"hanzi":"所有","pinyin":"suǒyǒu","vi":"Tất cả"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"一","pinyin":"yī","vi":"Một"},{"hanzi":"都","pinyin":"dōu","vi":"Đều"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"Thuận lợi"}]},{"id":"以","hanzi":"以","pinyin":"yǐ","meaning_vi":"lấy, dùng, bằng","explanation":"Giới từ dùng trong văn viết hoặc từ ghép (以为, 以后, 以前).","hsk_level":3,"tags":["gioi-tu"],"image":"📌","examples":[{"type":"basic","zh":"我们应该以认真负责的态度对待工作。","pinyin":"Wǒmen yīnggāi yǐ rènzhēn fùzé de tàidu duìdài gōngzuò.","vi":"Chúng ta nên đối xử với công việc bằng thái độ nghiêm túc có trách nhiệm."},{"type":"simple","zh":"中国以悠久的历史文化、美味的饮食和热情好客的人民而闻名世界。","pinyin":"Zhōngguó yǐ yōujiǔ de lìshǐ wénhuà, měiwèi de yǐnshí hé rèqíng hàokè de rénmín ér wénmíng shìjiè.","vi":"Trung Quốc nổi tiếng thế giới bởi lịch sử văn hóa lâu đời, ẩm thực ngon miệng và con người hiếu khách."},{"type":"compound","zh":"他以优秀的成绩考上了北京大学，因此全家人都为他感到骄傲。","pinyin":"Tā yǐ yōuxiù de chéngjì kǎoshàngle Běijīngdàxué, yīncǐ quán jiārén dōu wèi tā gǎndào jiāo'ào.","vi":"Cậu ấy đỗ vào Đại học Bắc Kinh với thành tích xuất sắc, vì vậy cả nhà đều tự hào về cậu."}],"related":[{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau này"},{"hanzi":"以为","pinyin":"yǐwéi","vi":"Tưởng rằng"},{"hanzi":"所以","pinyin":"suǒyǐ","vi":"Cho nên"},{"hanzi":"可以","pinyin":"kěyǐ","vi":"Có thể"}]},{"id":"艺术","hanzi":"艺术","pinyin":"yìshù","meaning_vi":"nghệ thuật","explanation":"艺 (tài nghệ) + 术 (kỹ thuật).","hsk_level":3,"tags":["danh-tu","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"京剧是中国传统的表演艺术。","pinyin":"Jīngjù shì Zhōngguó chuántǒng de biǎoyǎn yìshù.","vi":"Kinh kịch là nghệ thuật biểu diễn truyền thống của Trung Quốc."},{"type":"simple","zh":"我姐姐从小就喜欢画画和音乐，大学毕业后在一家艺术馆工作。","pinyin":"Wǒ jiějie cóngxiǎo jiù xǐhuan huàhuà hé yīnyuè, dàxué bìyè hòu zài yìjiā yìshùguǎn gōngzuò.","vi":"Chị gái tôi từ nhỏ đã thích vẽ tranh và âm nhạc, sau khi tốt nghiệp đại học làm việc tại một bảo tàng nghệ thuật."},{"type":"compound","zh":"虽然不同国家的艺术形式各不相同，但是人们对美好事物的追求是相通的。","pinyin":"Suīrán bùtóng guójiā de yìshù xíngshì gè bù xiāngtóng, dànshì rénmen duì měihǎo shìwù de zhuī qiúshì xiāngtōng de.","vi":"Tuy hình thức nghệ thuật của các quốc gia khác nhau không giống nhau nhưng sự theo đuổi cái đẹp của con người thì tương đồng."}],"related":[{"hanzi":"技术","pinyin":"jìshù","vi":"Kỹ thuật"},{"hanzi":"京剧","pinyin":"Jīngjù","vi":"Kinh kịch"},{"hanzi":"音乐","pinyin":"yīnyuè","vi":"Âm nhạc"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"Biểu diễn"},{"hanzi":"文化","pinyin":"wénhuà","vi":"Văn hóa"}],"traditional":"藝術"},{"id":"意见","hanzi":"意见","pinyin":"yìjiàn","meaning_vi":"ý kiến","explanation":"意 (ý nghĩ) + 见 (cách nhìn).","hsk_level":3,"tags":["danh-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"欢迎大家提出宝贵的意见。","pinyin":"Huānyíng dàjiā tíchū bǎoguì de yìjiàn.","vi":"Hoan nghênh mọi người đóng góp những ý kiến quý báu."},{"type":"simple","zh":"在开会讨论这个新计划时，同事们发表了很多不同的意见和建议。","pinyin":"Zài kāihuì tǎolùn zhè ge xīn jìhuà shí, tóngshìmen fābiǎole hěn duō bùtóng de yìjiàn hé jiànyì.","vi":"Khi họp thảo luận kế hoạch mới này, các đồng nghiệp đã phát biểu rất nhiều ý kiến và đề xuất khác nhau."},{"type":"compound","zh":"虽然在这个问题上我们的意见不太一致，但是经过商量最终达成了共识。","pinyin":"Suīrán zài zhè ge wèntí shang wǒmen de yìjiàn bú tài yízhì, dànshì jīngguò shāngliang zuìzhōng dáchéngle gòngshí.","vi":"Tuy về vấn đề này ý kiến của chúng tôi chưa thật sự thống nhất nhưng qua bàn bạc cuối cùng đã đạt được đồng thuận."}],"related":[{"hanzi":"建议","pinyin":"jiànyì","vi":"Đề nghị"},{"hanzi":"看法","pinyin":"kànfǎ","vi":"Cách nhìn"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"满意","pinyin":"mǎnyì","vi":"Hài lòng"},{"hanzi":"意思","pinyin":"yìsi","vi":"Ý nghĩa"}],"traditional":"意見"},{"id":"因此","hanzi":"因此","pinyin":"yīncǐ","meaning_vi":"do đó, vì vậy","explanation":"因 (nguyên nhân) + 此 (điều này). Trang trọng hơn 所以.","hsk_level":3,"tags":["lien-tu"],"image":"➡️","examples":[{"type":"basic","zh":"他生病了，因此没来上课。","pinyin":"Tā shēngbìng le, yīncǐ méi lái shàngkè.","vi":"Anh ấy bị ốm rồi, do đó không đến lớp."},{"type":"simple","zh":"北京的冬天非常干燥，因此每天多喝水和多吃水果对身体很有好处。","pinyin":"Běijīng de dōngtiān fēicháng gānzào, yīncǐ měitiān duō hēshuǐ hé duō chī shuǐguǒ duì shēntǐ hěn yǒu hǎochu.","vi":"Mùa đông ở Bắc Kinh vô cùng hanh khô, do đó mỗi ngày uống nhiều nước và ăn nhiều trái cây rất tốt cho sức khỏe."},{"type":"compound","zh":"这家饭店的菜不仅味道正宗，而且价格实惠，因此每天中午都能吸引大批顾客。","pinyin":"Zhè jiā fàndiàn de cài bùjǐn wèidào zhèngzōng, érqiě jiàgé shíhuì, yīncǐ měitiān zhōngwǔ dōu néng xīyǐn dàpī gùkè.","vi":"Món ăn của nhà hàng này không chỉ chuẩn vị mà giá cả lại phải chăng, do đó trưa nào cũng thu hút đông đảo khách hàng."}],"related":[{"hanzi":"所以","pinyin":"suǒyǐ","vi":"Cho nên"},{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"},{"hanzi":"于是","pinyin":"yúshì","vi":"Thế là"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"}]},{"id":"引起","hanzi":"引起","pinyin":"yǐnqǐ","meaning_vi":"gây ra, dẫn đến, thu hút","explanation":"引 (kéo) + 起 (nổi lên).","hsk_level":3,"tags":["dong-tu"],"image":"⚡","examples":[{"type":"basic","zh":"这件事引起了很多人的注意。","pinyin":"Zhè jiàn shì yǐnqǐle hěn duō rén de zhùyì.","vi":"Việc này đã thu hút sự chú ý của nhiều người."},{"type":"simple","zh":"不良的饮食习惯和经常熬夜，很容易引起胃病和身体免疫力下降。","pinyin":"Bùliáng de yǐnshí xíguàn hé jīngcháng áoyè, hěn róngyì yǐnqǐ wèibìng hé shēntǐ miǎnyìlì xiàjiàng.","vi":"Thói quen ăn uống không lành mạnh và thường xuyên thức khuya rất dễ gây ra bệnh dạ dày và suy giảm miễn dịch."},{"type":"compound","zh":"那位外国留学生在晚会上唱的一首京剧，引起了全场观众的浓厚兴趣。","pinyin":"Nà wèi wàiguó liúxuésheng zài wǎnhuì shang chàng de yì shǒu Jīngjù, yǐnqǐle quánchǎng guānzhòng de nónghòu xìngqù.","vi":"Bài Kinh kịch do du học sinh nước ngoài đó hát tại đêm hội đã khơi dậy sự hứng thú sâu sắc của toàn thể khán giả."}],"related":[{"hanzi":"吸引","pinyin":"xīyǐn","vi":"Thu hút"},{"hanzi":"起来","pinyin":"qǐlái","vi":"Nổi lên"},{"hanzi":"发生","pinyin":"fāshēng","vi":"Xảy ra"},{"hanzi":"注意","pinyin":"zhùyì","vi":"Chú ý"},{"hanzi":"兴趣","pinyin":"xìngqù","vi":"Hứng thú"}]},{"id":"印象","hanzi":"印象","pinyin":"yìnxiàng","meaning_vi":"ấn tượng","explanation":"印 (in dấu) + 象 (hình ảnh).","hsk_level":3,"tags":["danh-tu","cam-xuc"],"image":"🌟","examples":[{"type":"basic","zh":"北京给我留下了深刻的印象。","pinyin":"Běijīng gěi wǒ liúxiàle shēnkè de yìnxiàng.","vi":"Bắc Kinh đã để lại cho tôi ấn tượng sâu sắc."},{"type":"simple","zh":"第一次去面试的时候，穿得干净整齐可以给面试官留下良好的第一印象。","pinyin":"Dìyīcì qù miànshì de shíhou, chuān de gānjìng zhěngqí kěyǐ gěi miànshìguān liúxià liánghǎo de dìyīyìnxiàng.","vi":"Lần đầu đi phỏng vấn, ăn mặc sạch sẽ gọn gàng có thể để lại ấn tượng đầu tiên tốt đẹp cho nhà tuyển dụng."},{"type":"compound","zh":"虽然我只去过一次上海，但是那里繁华的夜景和热情的人们让我印象非常深刻。","pinyin":"Suīrán wǒ zhǐ qùguo yí cì Shànghǎi, dànshì nàlǐ fánhuá de yèjǐng hé rèqíng de rénmen ràng wǒ yìnxiàng fēicháng shēnkè.","vi":"Tuy tôi mới đi Thượng Hải có một lần nhưng cảnh đêm phồn hoa và con người nhiệt tình ở đó khiến tôi ấn tượng vô cùng sâu sắc."}],"related":[{"hanzi":"打印","pinyin":"dǎyìn","vi":"In ấn"},{"hanzi":"留","pinyin":"liú","vi":"Lưu lại"},{"hanzi":"深刻","pinyin":"shēnkè","vi":"Sâu sắc"},{"hanzi":"记忆","pinyin":"jìyì","vi":"Ký ức"},{"hanzi":"样子","pinyin":"yàngzi","vi":"Dáng vẻ"}]},{"id":"应聘","hanzi":"应聘","pinyin":"yìngpìn","meaning_vi":"ứng tuyển, xin việc","explanation":"应 (đáp ứng) + 聘 (tuyển dụng).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他去那家大公司应聘翻译。","pinyin":"Tā qù nà jiā dàgōngsī yìngpìn fānyì.","vi":"Anh ấy đến công ty lớn đó ứng tuyển vị trí phiên dịch."},{"type":"simple","zh":"明天上午我要去一家跨国企业应聘市场部经理的职位。","pinyin":"Míngtiān shàngwǔ wǒ yào qù yìjiā kuàguó qǐyè yìngpìn shìchǎng bù jīnglǐ de zhíwèi.","vi":"Sáng mai tôi phải đến một doanh nghiệp đa quốc gia ứng tuyển vị trí trưởng phòng marketing."},{"type":"compound","zh":"因为她的专业成绩优秀，而且能流利使用中英双语，所以成功应聘上了这家公司。","pinyin":"Yīnwèi tā de zhuānyè chéngjì yōuxiù, érqiě néng liúlì shǐyòng Zhōngyīng shuāngyǔ, suǒyǐ chénggōng yìngpìn shàngle zhè jiā gōngsī.","vi":"Vì thành tích chuyên ngành của cô ấy xuất sắc, lại sử dụng trôi chảy song ngữ Trung - Anh nên đã ứng tuyển thành công vào công ty này."}],"related":[{"hanzi":"招聘","pinyin":"zhāopìn","vi":"Tuyển dụng"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"Nộp đơn xin"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"职业","pinyin":"zhíyè","vi":"Nghề nghiệp"}],"traditional":"應聘"},{"id":"永远","hanzi":"永远","pinyin":"yǒngyuǎn","meaning_vi":"mãi mãi, vĩnh viễn","explanation":"永 (lâu dài) + 远 (xa xôi).","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"♾️","examples":[{"type":"basic","zh":"我永远不会忘记你的帮助。","pinyin":"Wǒ yǒngyuǎn bú huì wàngjì nǐ de bāngzhù.","vi":"Tôi mãi mãi sẽ không bao giờ quên sự giúp đỡ của bạn."},{"type":"simple","zh":"真挚的友谊不会因为距离的遥远而改变，它会永远留在我们心中。","pinyin":"Zhēnzhì de yǒuyì bú huì yīnwèi jùlí de yáoyuǎn ér gǎibiàn, tā huì yǒngyuǎn liú zài wǒmen xīnzhōng.","vi":"Tình bạn chân thành sẽ không thay đổi vì khoảng cách xa xôi, nó sẽ mãi đọng lại trong tim chúng ta."},{"type":"compound","zh":"虽然大学毕业后大家各奔东西，但是那段一起奋斗的青春岁月将永远值得回忆。","pinyin":"Suīrán dàxué bìyè hòu dàjiā gèbēndōngxī, dànshì nà duàn yìqǐ fèndòu de qīngchūn suìyuè jiāng yǒngyuǎn zhíde huíyì.","vi":"Tuy sau khi tốt nghiệp đại học mỗi người một ngả nhưng quãng thời gian thanh xuân cùng phấn đấu đó sẽ mãi mãi đáng để hồi tưởng."}],"related":[{"hanzi":"远","pinyin":"yuǎn","vi":"Xa"},{"hanzi":"从来","pinyin":"cónglái","vi":"Từ trước tới nay"},{"hanzi":"一直","pinyin":"yìzhí","vi":"Luôn luôn"},{"hanzi":"忘记","pinyin":"wàngjì","vi":"Quên"},{"hanzi":"回忆","pinyin":"huíyì","vi":"Hồi ức"}],"traditional":"永遠"},{"id":"勇敢","hanzi":"勇敢","pinyin":"yǒnggǎn","meaning_vi":"dũng cảm","explanation":"勇 (mạnh mẽ) + 敢 (dám).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🦁","examples":[{"type":"basic","zh":"我们要勇敢地面对困难。","pinyin":"Wǒmen yào yǒnggǎn de miànduì kùnnan.","vi":"Chúng ta phải dũng cảm đối mặt với khó khăn."},{"type":"simple","zh":"那个小男孩虽然只有七岁，但是在打针的时候非常勇敢，一点儿也没哭。","pinyin":"Nà ge xiǎo nánhái suīrán zhǐyǒu qī suì, dànshì zài dǎzhēn de shíhou fēicháng yǒnggǎn, yìdiǎnr yě méi kū.","vi":"Cậu bé đó tuy mới 7 tuổi nhưng lúc tiêm thuốc rất dũng cảm, không khóc chút nào."},{"type":"compound","zh":"学习外语的时候要勇敢地开口表达，不要因为害怕犯错误而保持沉默。","pinyin":"Xuéxí wàiyǔ de shíhou yào yǒnggǎn de kāikǒu biǎodá, bú yào yīnwèi hàipà fàn cuòwù ér bǎochí chénmò.","vi":"Khi học ngoại ngữ phải dũng cảm mở miệng diễn đạt, đừng vì sợ mắc lỗi mà giữ im lặng."}],"related":[{"hanzi":"敢","pinyin":"gǎn","vi":"Dám"},{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"Ngại ngùng"},{"hanzi":"困难","pinyin":"kùnnan","vi":"Khó khăn"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"Kiên trì"}]},{"id":"优秀","hanzi":"优秀","pinyin":"yōuxiù","meaning_vi":"ưu tú, xuất sắc","explanation":"优 (tốt) + 秀 (tinh túy).","hsk_level":3,"tags":["tinh-tu","hoc-tap"],"image":"🏅","examples":[{"type":"basic","zh":"她是一名非常优秀的学生。","pinyin":"Tā shì yì míng fēicháng yōuxiù de xuésheng.","vi":"Cô ấy là một học sinh vô cùng xuất sắc."},{"type":"simple","zh":"王老师不仅教学成绩突出，而且多次被评为全校最优秀的教师。","pinyin":"Wáng lǎoshī bùjǐn jiāoxué chéngjì tūchū, érqiě duōcì bèi píngwéi quán xiào zuì yōuxiù de jiàoshī.","vi":"Thầy Vương không chỉ có thành tích giảng dạy nổi bật mà còn nhiều lần được bình chọn là giáo viên xuất sắc nhất toàn trường."},{"type":"compound","zh":"要想成为一名优秀的翻译，不仅要精通外语，还要对本国文化有深入了解。","pinyin":"Yào xiǎng chéngwéi yì míng yōuxiù de fānyì, bùjǐn yào jīngtōng wàiyǔ, hái yào duì běnguó wénhuà yǒu shēnrù liǎojiě.","vi":"Muốn trở thành một phiên dịch viên xuất sắc, không chỉ phải thông thạo ngoại ngữ mà còn phải hiểu sâu sắc về văn hóa nước mình."}],"related":[{"hanzi":"优点","pinyin":"yōudiǎn","vi":"Ưu điểm"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"聪明","pinyin":"cōngming","vi":"Thông minh"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"}],"traditional":"優秀"},{"id":"幽默","hanzi":"幽默","pinyin":"yōumò","meaning_vi":"hài hước","explanation":"Từ phiên âm tiếng Anh 'humor'.","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"😄","examples":[{"type":"basic","zh":"王老师说话非常幽默。","pinyin":"Wáng lǎoshī shuōhuà fēicháng yōumò.","vi":"Thầy Vương nói chuyện vô cùng hài hước."},{"type":"simple","zh":"他是一个非常幽默的人，有他在的地方总是充满了欢声笑语。","pinyin":"Tā shì yí ge fēicháng yōumò de rén, yǒu tā zài de dìfang zǒngshì chōngmǎnle huānshēngxiàoyǔ.","vi":"Anh ấy là một người vô cùng hài hước, nơi nào có anh ấy là nơi đó luôn tràn ngập tiếng cười nói vui vẻ."},{"type":"compound","zh":"虽然这篇文章讲的是严肃的科学道理，但是作者用幽默的语言写得非常有趣。","pinyin":"Suīrán zhè piān wénzhāng jiǎng de shì yánsù de kēxué dàolǐ, dànshì zuòzhě yòng yōumò de yǔyán xiě de fēicháng yǒuqù.","vi":"Tuy bài văn này nói về đạo lý khoa học nghiêm túc nhưng tác giả đã dùng ngôn ngữ hài hước viết nên vô cùng thú vị."}],"related":[{"hanzi":"笑话","pinyin":"xiàohua","vi":"Truyện cười"},{"hanzi":"开玩笑","pinyin":"kāiwánxiào","vi":"Nói đùa"},{"hanzi":"有趣","pinyin":"yǒuqù","vi":"Thú vị"},{"hanzi":"性格","pinyin":"xìnggé","vi":"Tính cách"},{"hanzi":"笑","pinyin":"xiào","vi":"Cười"}]},{"id":"尤其","hanzi":"尤其","pinyin":"yóuqí","meaning_vi":"đặc biệt là, nhất là","explanation":"尤 (nổi bật) + 其 (đó). Phó từ nhấn mạnh.","hsk_level":3,"tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"我喜欢吃水果，尤其是西瓜。","pinyin":"Wǒ xǐhuan chī shuǐguǒ, yóuqíshì xīguā.","vi":"Tôi thích ăn trái cây, đặc biệt là dưa hấu."},{"type":"simple","zh":"中国的名胜古迹很多，尤其是北京的长城和西安的兵马俑最有名。","pinyin":"Zhōngguó de míngshènggǔjì hěn duō, yóuqíshì Běijīng de Chángchéng hé Xī'ān de bīngmǎyǒng zuì yǒumíng.","vi":"Danh lam thắng cảnh của Trung Quốc rất nhiều, đặc biệt là Vạn Lý Trường Thành ở Bắc Kinh và Đội quân Đất nung ở Tây An nổi tiếng nhất."},{"type":"compound","zh":"春天天气变化很快，早晚温差大，大家一定要注意保暖，尤其是老人和孩子。","pinyin":"Chūntiān tiānqì biànhuà hěn kuài, zǎowǎn wēnchā dà, dàjiā yídìngyào zhùyì bǎonuǎn, yóuqíshì lǎorén hé háizi.","vi":"Thời tiết mùa xuân thay đổi rất nhanh, chênh lệch nhiệt độ sáng tối lớn, mọi người nhất định phải chú ý giữ ấm, nhất là người già và trẻ nhỏ."}],"related":[{"hanzi":"特别","pinyin":"tèbié","vi":"Đặc biệt"},{"hanzi":"其中","pinyin":"qízhōng","vi":"Trong đó"},{"hanzi":"其次","pinyin":"qícì","vi":"Tiếp theo"},{"hanzi":"其实","pinyin":"qíshí","vi":"Thực ra"},{"hanzi":"最","pinyin":"zuì","vi":"Nhất"}]},{"id":"由","hanzi":"由","pinyin":"yóu","meaning_vi":"do, bởi, từ","explanation":"Giới từ chỉ người phụ trách hoặc nguyên nhân.","hsk_level":3,"tags":["gioi-tu"],"image":"👉","examples":[{"type":"basic","zh":"这次活动由王老师负责组织。","pinyin":"Zhè cì huódòng yóu Wáng lǎoshī fùzé zǔzhī.","vi":"Hoạt động lần này do thầy Vương phụ trách tổ chức."},{"type":"simple","zh":"明天的汉语演讲比赛将由我们班的两位同学担任主持人。","pinyin":"Míngtiān de Hànyǔ yǎnjiǎng bǐsài jiāng yóu wǒmen bān de liǎng wèi tóngxué dānrèn zhǔchírén.","vi":"Cuộc thi hùng biện tiếng Trung ngày mai sẽ do hai bạn học lớp chúng tôi đảm nhận vai trò người dẫn chương trình."},{"type":"compound","zh":"一家公司能否成功，往往不是由一个人决定的，而是由整个团队决定的。","pinyin":"Yìjiā gōngsī néngfǒu chénggōng, wǎngwǎng bú shì yóu yígerén juédìng de, érshì yóu zhěngge tuánduì juédìng de.","vi":"Một công ty có thành công hay không thường không phải do một người quyết định mà do cả tập thể quyết định."}],"related":[{"hanzi":"由于","pinyin":"yóuyú","vi":"Do/Bởi vì"},{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"},{"hanzi":"负责","pinyin":"fùzé","vi":"Phụ trách"},{"hanzi":"自由","pinyin":"zìyóu","vi":"Tự do"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"}]},{"id":"由于","hanzi":"由于","pinyin":"yóuyú","meaning_vi":"do, bởi vì","explanation":"由 + 于. Thường dùng ở vế đầu câu phức chỉ nguyên nhân.","hsk_level":3,"tags":["lien-tu","gioi-tu"],"image":"💡","examples":[{"type":"basic","zh":"由于下大雨，飞机推迟起飞了。","pinyin":"Yóuyú xià dàyǔ, fēijī tuīchí qǐfēi le.","vi":"Do trời mưa lớn nên máy bay đã hoãn cất cánh."},{"type":"simple","zh":"由于工作调动的原因，他下个月就要搬到上海去生活了。","pinyin":"Yóuyú gōngzuò diàodòng de yuányīn, tā xiàgeyuè jiùyào bān dào Shànghǎi qù shēnghuó le.","vi":"Do nguyên nhân điều chuyển công tác, tháng sau anh ấy sẽ chuyển tới Thượng Hải sinh sống."},{"type":"compound","zh":"由于平时缺乏体育锻炼，他每次爬楼梯爬到五楼就会觉得气喘吁吁。","pinyin":"Yóuyú píngshí quēfá tǐyù duànliàn, tā měi cì pá lóutī pá dào wǔ lóu jiù huì juéde qìchuǎnxūxū.","vi":"Do ngày thường thiếu rèn luyện thể thao nên mỗi lần leo cầu thang lên tầng 5 là anh ấy lại thấy thở hổn hển."}],"related":[{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"由","pinyin":"yóu","vi":"Do"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"Do đó"},{"hanzi":"所以","pinyin":"suǒyǐ","vi":"Cho nên"},{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"}],"traditional":"由於"},{"id":"邮局","hanzi":"邮局","pinyin":"yóujú","meaning_vi":"bưu điện","explanation":"邮 (bưu chính) + 局 (cục/cơ quan).","hsk_level":3,"tags":["danh-tu","dia-diem"],"image":"🏤","examples":[{"type":"basic","zh":"邮局就在银行旁边。","pinyin":"Yóujú jiù zài yínháng pángbiān.","vi":"Bưu điện nằm ngay bên cạnh ngân hàng."},{"type":"simple","zh":"明天上午我要去邮局给远在家乡的父母寄一些北京特产。","pinyin":"Míngtiān shàngwǔ wǒ yào qù yóujú gěi yuǎn zài jiāxiāng de fùmǔ jì yìxiē Běijīng tèchǎn.","vi":"Sáng mai tôi phải ra bưu điện gửi một ít đặc sản Bắc Kinh về cho bố mẹ ở quê nhà."},{"type":"compound","zh":"从学校门口往东走两百米，在十字路口的右边就能看到邮局。","pinyin":"Cóng xuéxiào ménkǒu wǎng dōng zǒu liǎng bǎimǐ, zài shízìlùkǒu de yòubiān jiù néng kàndào yóujú.","vi":"Từ cổng trường đi về hướng Đông 200 mét, ở bên phải ngã tư là có thể nhìn thấy bưu điện."}],"related":[{"hanzi":"寄","pinyin":"jì","vi":"Gửi"},{"hanzi":"信封","pinyin":"xìnfēng","vi":"Phong bì thư"},{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"},{"hanzi":"地址","pinyin":"dìzhǐ","vi":"Địa chỉ"},{"hanzi":"电子邮件","pinyin":"diànzǐyóujiàn","vi":"Email"}],"traditional":"郵局"},{"id":"友谊","hanzi":"友谊","pinyin":"yǒuyì","meaning_vi":"tình bạn, tình hữu nghị","explanation":"友 (bạn) + 谊 (tình nghĩa).","hsk_level":3,"tags":["danh-tu","giao-tiep"],"image":"👫","examples":[{"type":"basic","zh":"祝愿我们的友谊长存！","pinyin":"Zhùyuàn wǒmen de yǒuyì chángcún!","vi":"Chúc cho tình bạn của chúng ta mãi bền lâu!"},{"type":"simple","zh":"在大学四年的学习生活中，我收获了最宝贵的知识和真挚的友谊。","pinyin":"Zài dàxué sì nián de xuéxí shēnghuó zhōng, wǒ shōuhuòle zuì bǎoguì de zhīshi hé zhēnzhì de yǒuyì.","vi":"Trong bốn năm học tập và sinh hoạt đại học, tôi đã gặt hái được tri thức quý giá nhất và tình bạn chân thành."},{"type":"compound","zh":"虽然我们来自不同的国家，但是共同的爱好把我们紧紧联系在一起，结下了深厚的友谊。","pinyin":"Suīrán wǒmen láizì bùtóng de guójiā, dànshì gòngtóng de àihào bǎ wǒmen jǐnjǐn liánxì zài yìqǐ, jié xiàle shēnhòu de yǒuyì.","vi":"Tuy chúng tôi đến từ nhiều quốc gia khác nhau nhưng sở thích chung đã gắn kết chúng tôi lại và tạo nên tình bạn sâu sắc."}],"related":[{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"},{"hanzi":"友好","pinyin":"yǒuhǎo","vi":"Thân thiện"},{"hanzi":"干杯","pinyin":"gānbēi","vi":"Cạn ly"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"}],"traditional":"友誼"},{"id":"有趣","hanzi":"有趣","pinyin":"yǒuqù","meaning_vi":"thú vị, hay","explanation":"有 (có) + 趣 (hứng thú). Đồng nghĩa với 有意思.","hsk_level":3,"tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"王老师讲的故事非常有趣。","pinyin":"Wáng lǎoshī jiǎng de gùshi fēicháng yǒuqù.","vi":"Câu chuyện thầy Vương kể vô cùng thú vị."},{"type":"simple","zh":"汉字的演变历史非常有趣，了解字源能帮助我们更快地记住生词。","pinyin":"Hànzì de yǎnbiàn lìshǐ fēicháng yǒuqù, liǎojiě zìyuán néng bāngzhù wǒmen gèng kuài de jìzhu shēngcí.","vi":"Lịch sử biến đổi của chữ Hán rất thú vị, hiểu rõ nguồn gốc chữ giúp chúng ta nhớ từ mới nhanh hơn."},{"type":"compound","zh":"虽然这本书的封面看起来很旧，但是里面的内容却写得十分生动有趣。","pinyin":"Suīrán zhè běn shū de fēngmiàn kànqǐlái hěn jiù, dànshì lǐmiàn de nèiróng què xiě de shífēn shēngdòng yǒuqù.","vi":"Tuy bìa quyển sách này trông rất cũ nhưng nội dung bên trong lại được viết vô cùng sinh động thú vị."}],"related":[{"hanzi":"有意思","pinyin":"yǒuyìsi","vi":"Thú vị"},{"hanzi":"无聊","pinyin":"wúliáo","vi":"Nhàm chán"},{"hanzi":"幽默","pinyin":"yōumò","vi":"Hài hước"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"Đặc sắc"},{"hanzi":"故事","pinyin":"gùshi","vi":"Câu chuyện"}]},{"id":"于是","hanzi":"于是","pinyin":"yúshì","meaning_vi":"thế là, do đó","explanation":"于 + 是. Liên từ nối hai hành động kế tiếp nhau.","hsk_level":3,"tags":["lien-tu"],"image":"➡️","examples":[{"type":"basic","zh":"天突然下雨了，于是我们回家了。","pinyin":"Tiān tūrán xiàyǔ le, yúshì wǒmen huíjiā le.","vi":"Trời đột nhiên đổ mưa, thế là chúng tôi về nhà."},{"type":"simple","zh":"今天超市的水果都在打折，于是妈妈买了很多苹果和葡萄。","pinyin":"Jīntiān chāoshì de shuǐguǒ dōu zài dǎzhé, yúshì māma mǎile hěn duō píngguǒ hé pútao.","vi":"Hôm nay trái cây trong siêu thị đều giảm giá, thế là mẹ đã mua rất nhiều táo và nho."},{"type":"compound","zh":"他觉得自己最近有点儿发胖，于是决定从明天开始每天早上起床跑步。","pinyin":"Tā juéde zìjǐ zuìjìn yǒudiǎnr fāpàng, yúshì juédìng cóng míngtiān kāishǐ měitiān zǎoshang qǐchuáng pǎobù.","vi":"Anh ấy thấy dạo này mình hơi béo lên, thế là quyết định từ ngày mai mỗi sáng thức dậy chạy bộ."}],"related":[{"hanzi":"所以","pinyin":"suǒyǐ","vi":"Cho nên"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"由于","pinyin":"yóuyú","vi":"Do/Bởi vì"},{"hanzi":"对于","pinyin":"duìyú","vi":"Đối với"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"Do đó"}],"traditional":"於是"},{"id":"愉快","hanzi":"愉快","pinyin":"yúkuài","meaning_vi":"vui vẻ, khoan khoái","explanation":"愉 (vui) + 快 (sảng khoái).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😊","examples":[{"type":"basic","zh":"祝你周末愉快！","pinyin":"Zhù nǐ zhōumò yúkuài!","vi":"Chúc bạn cuối tuần vui vẻ!"},{"type":"simple","zh":"和好朋友们一起聊天喝茶，总能让人度过一段非常愉快的时光。","pinyin":"Héhǎo péngyoumen yìqǐ liáotiān hēchá, zǒngnéng ràng rén dùguò yí duàn fēicháng yúkuài de shíguāng.","vi":"Trò chuyện uống trà cùng bạn thân luôn giúp con người trải qua quãng thời gian vô cùng vui vẻ."},{"type":"compound","zh":"虽然这次去北京出差的任务很重，但是和合作伙伴相处得非常愉快。","pinyin":"Suīrán zhè cì qù Běijīng chūchāi de rènwu hěn zhòng, dànshì hé hézuò huǒbàn xiāngchǔ de fēicháng yúkuài.","vi":"Tuy nhiệm vụ chuyến công tác Bắc Kinh lần này rất nặng nhưng việc hợp tác với đối tác diễn ra vô cùng vui vẻ."}],"related":[{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"Nhẹ nhàng"},{"hanzi":"合作","pinyin":"hézuò","vi":"Hợp tác"}]},{"id":"与","hanzi":"与","pinyin":"yǔ","meaning_vi":"và, cùng với","explanation":"Liên từ/giới từ dùng trong văn viết thay cho 和 / 跟.","hsk_level":3,"tags":["lien-tu","gioi-tu"],"image":"🔗","examples":[{"type":"basic","zh":"人与自然应该和谐相处。","pinyin":"Rén yǔ zìrán yīnggāi héxié xiāngchǔ.","vi":"Con người và thiên nhiên nên chung sống hài hòa."},{"type":"simple","zh":"这份调查报告详细分析了经济发展与环境保护之间的密切关系。","pinyin":"Zhè fèn diàochá bàogào xiángxì fēnxīle jīngjì fāzhǎn yǔ huánjìngbǎohù zhījiān de mìqiè guānxi.","vi":"Bản báo cáo khảo sát này đã phân tích chi tiết mối quan hệ mật thiết giữa phát triển kinh tế và bảo vệ môi trường."},{"type":"compound","zh":"无论在学习还是工作中，学会与他人沟通合作都是取得成功的关键。","pinyin":"Wúlùn zài xuéxí háishi gōngzuò zhōng, xuéhuì yǔ tārén gōutōng hézuò dōu shì qǔdé chénggōng de guānjiàn.","vi":"Dù trong học tập hay công việc, học cách giao tiếp và hợp tác với người khác đều là chìa khóa dẫn đến thành công."}],"related":[{"hanzi":"和","pinyin":"hé","vi":"Và"},{"hanzi":"跟","pinyin":"gēn","vi":"Cùng với"},{"hanzi":"合作","pinyin":"hézuò","vi":"Hợp tác"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Giống nhau"}],"traditional":"與"},{"id":"羽毛球","hanzi":"羽毛球","pinyin":"yǔmáoqiú","meaning_vi":"cầu lông","explanation":"羽毛 (lông vũ) + 球 (quả bóng).","hsk_level":3,"tags":["danh-tu","the-thao"],"image":"🏸","examples":[{"type":"basic","zh":"我喜欢和同学打羽毛球。","pinyin":"Wǒ xǐhuan hé tóngxué dǎ yǔmáoqiú.","vi":"Tôi thích chơi cầu lông cùng bạn học."},{"type":"simple","zh":"每天下午下课以后，体育馆里都有很多学生在练习打羽毛球。","pinyin":"Měitiān xiàwǔ xiàkè yǐhòu, tǐyùguǎn lǐ dōu yǒu hěn duō xuésheng zài liànxí dǎ yǔmáoqiú.","vi":"Mỗi chiều sau khi tan học, trong nhà thi đấu đều có nhiều học sinh đang luyện tập đánh cầu lông."},{"type":"compound","zh":"因为室外刮大风的时候没法打羽毛球，所以我们周末一般去室内体育馆打。","pinyin":"Yīnwèi shìwài guā dàfēng de shíhou méifǎ dǎ yǔmáoqiú, suǒyǐ wǒmen zhōumò yìbān qù shìnèi tǐyùguǎn dǎ.","vi":"Vì lúc ngoài trời gió to không thể đánh cầu lông nên cuối tuần chúng tôi thường vào nhà thi đấu trong nhà chơi."}],"related":[{"hanzi":"乒乓球","pinyin":"pīngpāngqiú","vi":"Bóng bàn"},{"hanzi":"网球","pinyin":"wǎngqiú","vi":"Quần vợt"},{"hanzi":"打篮球","pinyin":"dǎlánqiú","vi":"Chơi bóng rổ"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Thể thao"},{"hanzi":"锻炼","pinyin":"duànliàn","vi":"Rèn luyện"}]},{"id":"语法","hanzi":"语法","pinyin":"yǔfǎ","meaning_vi":"ngữ pháp","explanation":"语 (ngôn ngữ) + 法 (quy tắc).","hsk_level":3,"tags":["danh-tu","hoc-tap","ngon-ngu"],"image":"📘","examples":[{"type":"basic","zh":"汉语语法其实很有规律。","pinyin":"Hànyǔ yǔfǎ qíshí hěn yǒuguīlǜ.","vi":"Ngữ pháp tiếng Trung thực ra rất có quy luật."},{"type":"simple","zh":"学好汉语不仅要积累丰富的词汇，还必须掌握基本的语法结构。","pinyin":"Xuéhǎo Hànyǔ bùjǐn yào jīlěi fēngfù de cíhuì, hái bìxū zhǎngwò jīběn de yǔfǎ jiégòu.","vi":"Học giỏi tiếng Trung không chỉ cần tích lũy từ vựng phong phú mà còn bắt buộc phải nắm vững cấu trúc ngữ pháp cơ bản."},{"type":"compound","zh":"虽然这条语法规则比较复杂，但是经过王老师的详细解释，大家都明白了。","pinyin":"Suīrán zhè tiáo yǔfǎ guīzé bǐjiào fùzá, dànshì jīngguò Wáng lǎoshī de xiángxì jiěshì, dàjiā dōu míngbai le.","vi":"Tuy quy tắc ngữ pháp này tương đối phức tạp nhưng qua lời giải thích cặn kẽ của thầy Vương thì mọi người đều hiểu rõ."}],"related":[{"hanzi":"语言","pinyin":"yǔyán","vi":"Ngôn ngữ"},{"hanzi":"词语","pinyin":"cíyǔ","vi":"Từ ngữ"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"Pháp luật"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"Biện pháp"},{"hanzi":"汉语","pinyin":"Hànyǔ","vi":"Tiếng Trung"}],"traditional":"語法"},{"id":"语言","hanzi":"语言","pinyin":"yǔyán","meaning_vi":"ngôn ngữ","explanation":"语 (lời nói) + 言 (ngôn từ).","hsk_level":3,"tags":["danh-tu","hoc-tap","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"汉语是一门非常美丽的语言。","pinyin":"Hànyǔ shì yì mén fēicháng měilì de yǔyán.","vi":"Tiếng Trung là một ngôn ngữ vô cùng tươi đẹp."},{"type":"simple","zh":"多学一门语言，就多了解一种文化。","pinyin":"Duō xué yì mén yǔyán, jiù duō liǎojiě yì zhǒng wénhuà.","vi":"Học thêm một ngôn ngữ là hiểu thêm một nền văn hóa."},{"type":"compound","zh":"虽然世界上有几千种不同的语言，但是微笑是全人类都能理解的共同语言。","pinyin":"Suīrán shìjiè shang yǒu jǐqiān zhǒng bùtóng de yǔyán, dànshì wēixiào shì quán rénlèi dōu néng lǐjiě de gòngtóng yǔyán.","vi":"Tuy trên thế giới có hàng nghìn ngôn ngữ khác nhau nhưng nụ cười là ngôn ngữ chung mà toàn nhân loại đều thấu hiểu."}],"related":[{"hanzi":"语法","pinyin":"yǔfǎ","vi":"Ngữ pháp"},{"hanzi":"词语","pinyin":"cíyǔ","vi":"Từ ngữ"},{"hanzi":"汉语","pinyin":"Hànyǔ","vi":"Tiếng Trung"},{"hanzi":"英语","pinyin":"Yīngyǔ","vi":"Tiếng Anh"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"}],"traditional":"語言"},{"id":"预习","hanzi":"预习","pinyin":"yùxí","meaning_vi":"chuẩn bị bài trước","explanation":"预 (trước) + 习 (học tập). Đối ứng với 复习 (ôn tập).","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"上课前要先预习生词。","pinyin":"Shàngkè qián yào xiān yùxí shēngcí.","vi":"Trước khi vào học phải chuẩn bị trước từ mới."},{"type":"simple","zh":"每天晚上睡觉前，我都会花半个小时预习明天要学的新课文。","pinyin":"Měitiān wǎnshang shuìjiào qián, wǒ dōuhuì huā bàn ge xiǎoshí yùxí míngtiān yào xué de xīn kèwén.","vi":"Mỗi tối trước khi đi ngủ, tôi đều dành nửa tiếng đồng hồ chuẩn bị trước bài khóa mới sẽ học ngày mai."},{"type":"compound","zh":"只要课前认真预习、课后及时复习，学习汉语就会变得越来越轻松。","pinyin":"Zhǐyào kè qián rènzhēn yùxí, kè hòu jíshí fùxí, xuéxí Hànyǔ jiù huì biànde yuèláiyuè qīngsōng.","vi":"Chỉ cần trước giờ học chuẩn bị bài kỹ lưỡng và sau giờ học ôn tập kịp thời thì việc học tiếng Trung sẽ ngày càng nhẹ nhàng."}],"related":[{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"课文","pinyin":"kèwén","vi":"Bài khóa"},{"hanzi":"上课","pinyin":"shàngkè","vi":"Lên lớp"}],"traditional":"預習"},{"id":"原来","hanzi":"原来","pinyin":"yuánlái","meaning_vi":"hóa ra; vốn, ban đầu","explanation":"原 (gốc) + 来 (đến). Vừa là phó từ vừa là tính từ.","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"💡","examples":[{"type":"basic","zh":"原来你也是越南人啊！","pinyin":"Yuánlái nǐ yě shì Yuènán rén a!","vi":"Hóa ra bạn cũng là người Việt Nam à!"},{"type":"simple","zh":"我找了半天眼镜，后来照镜子才发现原来眼镜就戴在自己头上。","pinyin":"Wǒ zhǎole bàn tiān yǎnjìng, hòulái zhàojìngzi cái fāxiàn yuánlái yǎnjìng jiù dài zài zìjǐ tóushang.","vi":"Tôi tìm kính mãi nửa ngày, sau soi gương mới phát hiện hóa ra kính đang đeo ngay trên đầu mình."},{"type":"compound","zh":"因为市中心正在修地铁，所以原来从这里经过的公共汽车现在都改道了。","pinyin":"Yīnwèi shìzhōngxīn zhèngzài xiū dìtiě, suǒyǐ yuánlái cóng zhèlǐ jīngguò de gōnggòngqìchē xiànzài dōu gǎidào le.","vi":"Vì trung tâm thành phố đang xây tàu điện ngầm nên các tuyến xe buýt vốn đi qua đây hiện giờ đều đã đổi lộ trình."}],"related":[{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"Tha thứ"},{"hanzi":"本来","pinyin":"běnlái","vi":"Vốn dĩ"},{"hanzi":"后来","pinyin":"hòulái","vi":"Sau này"},{"hanzi":"发现","pinyin":"fāxiàn","vi":"Phát hiện"}],"traditional":"原來"},{"id":"原谅","hanzi":"原谅","pinyin":"yuánliàng","meaning_vi":"tha thứ, thứ lỗi","explanation":"原 (khoan dung) + 谅 (thông cảm).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"请你原谅我这一次吧。","pinyin":"Qǐng nǐ yuánliàng wǒ zhè yí cì ba.","vi":"Xin bạn hãy tha thứ cho tôi lần này nhé."},{"type":"simple","zh":"既然他已经认识到了自己的错误并诚恳道歉，你就原谅他吧。","pinyin":"Jìrán tā yǐjīng rènshi dàole zìjǐ de cuòwù bìng chéngkěn dàoqiàn, nǐ jiù yuánliàng tā ba.","vi":"Vì anh ấy đã nhận ra sai lầm của mình và thành khẩn xin lỗi rồi, bạn hãy tha thứ cho anh ấy đi."},{"type":"compound","zh":"人与人之间相处难免会有摩擦，学会宽容和原谅别人才能拥有更多快乐。","pinyin":"Rén yǔ rén zhījiān xiāngchǔ nánmiǎn huì yǒu mócā, xuéhuì kuānróng hé yuánliàng biérén cáinéng yōngyǒu gèng duō kuàilè.","vi":"Con người chung sống với nhau khó tránh khỏi va chạm, học cách bao dung và tha thứ cho người khác mới có thể có nhiều niềm vui hơn."}],"related":[{"hanzi":"道歉","pinyin":"dàoqiàn","vi":"Xin lỗi"},{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"Áy náy"},{"hanzi":"误会","pinyin":"wùhuì","vi":"Hiểu lầm"},{"hanzi":"原来","pinyin":"yuánlái","vi":"Hóa ra"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"}],"traditional":"原諒"},{"id":"原因","hanzi":"原因","pinyin":"yuányīn","meaning_vi":"nguyên nhân","explanation":"原 (gốc rễ) + 因 (lý do). Đối ứng với 结果 (kết quả).","hsk_level":3,"tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"你知道这件事的原因吗？","pinyin":"Nǐ zhīdao zhè jiàn shì de yuányīn ma?","vi":"Bạn có biết nguyên nhân của việc này không?"},{"type":"simple","zh":"老师让我们仔细分析这次考试没考好的原因，以便下次改进。","pinyin":"Lǎoshī ràng wǒmen zǐxì fēnxī zhè cì kǎoshì méi kǎo hǎo de yuányīn, yǐbiàn xiàcì gǎijìn.","vi":"Thầy giáo bảo chúng tôi phân tích kỹ nguyên nhân kỳ thi lần này làm chưa tốt để lần sau cải thiện."},{"type":"compound","zh":"他汉语说得这么流利，主要原因是他每天都坚持跟中国人交流。","pinyin":"Tā Hànyǔ shuō de zhème liúlì, zhǔyào yuányīn shì tā měitiān dōu jiānchí gēn Zhōngguórén jiāoliú.","vi":"Anh ấy nói tiếng Trung trôi chảy như vậy, nguyên nhân chính là ngày nào anh ấy cũng kiên trì giao tiếp với người Trung Quốc."}],"related":[{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"Do đó"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"原来","pinyin":"yuánlái","vi":"Hóa ra"},{"hanzi":"目的","pinyin":"mùdì","vi":"Mục đích"}]},{"id":"约会","hanzi":"约会","pinyin":"yuēhuì","meaning_vi":"hẹn hò, cuộc hẹn","explanation":"约 (hẹn ước) + 会 (gặp gỡ). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💑","examples":[{"type":"basic","zh":"他今天晚上有个约会。","pinyin":"Tā jīntiān wǎnshang yǒu ge yuēhuì.","vi":"Tối nay anh ấy có một cuộc hẹn."},{"type":"simple","zh":"今天下午我和大学同学有个约会，我们要一起去电影院看新上映的电影。","pinyin":"Jīntiān xiàwǔ wǒ hé dàxué tóngxué yǒu ge yuēhuì, wǒmen yào yìqǐ qù diànyǐngyuàn kàn xīn shàngyìng de diànyǐng.","vi":"Chiều nay tôi có cuộc hẹn với bạn học đại học, chúng tôi sẽ cùng đi rạp xem bộ phim mới công chiếu."},{"type":"compound","zh":"不管是跟朋友聚会还是商务约会，提前十分钟到达都是非常礼貌的表现。","pinyin":"Bùguǎn shì gēn péngyou jùhuì háishi shāngwù yuēhuì, tíqián shí fēnzhōng dàodá dōu shì fēicháng lǐmào de biǎoxiàn.","vi":"Dù là tụ họp bạn bè hay hẹn gặp công việc, đến sớm trước 10 phút đều là biểu hiện rất lịch sự."}],"related":[{"hanzi":"聚会","pinyin":"jùhuì","vi":"Tụ họp"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"},{"hanzi":"大约","pinyin":"dàyuē","vi":"Khoảng chừng"},{"hanzi":"见面","pinyin":"jiànmiàn","vi":"Gặp mặt"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"}],"traditional":"約會"},{"id":"阅读","hanzi":"阅读","pinyin":"yuèdú","meaning_vi":"đọc, đọc hiểu","explanation":"阅 (xem) + 读 (đọc).","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"我每天都阅读中文报纸。","pinyin":"Wǒ měitiān dōu yuèdú Zhōngwén bàozhǐ.","vi":"Mỗi ngày tôi đều đọc báo tiếng Trung."},{"type":"simple","zh":"多阅读优秀的文学作品，不仅能丰富我们的知识，还能提高写作水平。","pinyin":"Duō yuèdú yōuxiù de wénxué zuòpǐn, bùjǐn néng fēngfù wǒmen de zhīshi, hái néng tígāo xiězuò shuǐpíng.","vi":"Đọc nhiều tác phẩm văn học xuất sắc không những làm phong phú kiến thức của chúng ta mà còn nâng cao trình độ viết."},{"type":"compound","zh":"在参加HSK考试时，合理分配阅读理解部分的答题时间非常关键。","pinyin":"Zài cān jiā HSK kǎo shì shí, hé lǐ fēn pèi yuè dú lǐ jiě bù fen de dá tí shí jiān fēi cháng guān jiàn.","vi":"Khi tham gia kỳ thi HSK, phân bổ hợp lý thời gian làm bài phần đọc hiểu là vô cùng mấu chốt."}],"related":[{"hanzi":"读","pinyin":"dú","vi":"Đọc"},{"hanzi":"看书","pinyin":"kànshū","vi":"Đọc sách"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"Bài văn"},{"hanzi":"小说","pinyin":"xiǎoshuō","vi":"Tiểu thuyết"},{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"Báo giấy"}],"traditional":"閱讀"},{"id":"允许","hanzi":"允许","pinyin":"yǔnxǔ","meaning_vi":"cho phép","explanation":"允 (đồng ý) + 许 (cho phép).","hsk_level":3,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"这里不允许抽烟。","pinyin":"Zhèlǐ bù yǔnxǔ chōuyān.","vi":"Ở đây không cho phép hút thuốc."},{"type":"simple","zh":"博物馆里面为了保护文物，是不允许游客使用闪光灯拍照的。","pinyin":"Bówùguǎn lǐmiàn wèile bǎohù wénwù, shì bù yǔnxǔ yóukè shǐyòng shǎnguāngdēng pāizhào de.","vi":"Bên trong bảo tàng để bảo vệ cổ vật thì không cho phép du khách dùng đèn flash chụp ảnh."},{"type":"compound","zh":"只要时间允许，每个周末我都会回家陪父母吃顿晚饭、聊聊天。","pinyin":"Zhǐyào shíjiān yǔnxǔ, měi ge zhōumò wǒ dōuhuì huíjiā péi fùmǔ chī dùn wǎnfàn, liáo liaotiān.","vi":"Chỉ cần thời gian cho phép, cuối tuần nào tôi cũng về nhà ăn bữa tối và trò chuyện cùng bố mẹ."}],"related":[{"hanzi":"也许","pinyin":"yěxǔ","vi":"Có lẽ"},{"hanzi":"许多","pinyin":"xǔduō","vi":"Rất nhiều"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"Cấm"},{"hanzi":"可以","pinyin":"kěyǐ","vi":"Có thể"}],"traditional":"允許"},{"id":"杂志","hanzi":"杂志","pinyin":"zázhì","meaning_vi":"tạp chí","explanation":"杂 (nhiều loại) + 志 (ghi chép).","hsk_level":3,"tags":["danh-tu","do-vat","hoc-tap"],"image":"📰","examples":[{"type":"basic","zh":"桌子上放着几本时尚杂志。","pinyin":"Zhuōzi shang fàngzhe jǐ běn shíshàng zázhì.","vi":"Trên bàn đang đặt vài cuốn tạp chí thời trang."},{"type":"simple","zh":"在机场候机室等飞机的时候，买一本有趣的杂志看可以打发时间。","pinyin":"Zài jīchǎng hòu jī shì děng fēijī de shíhou, mǎi yì běn yǒuqù de zázhì kàn kěyǐ dǎfa shíjiān.","vi":"Lúc đợi máy bay ở phòng chờ sân bay, mua một cuốn tạp chí thú vị đọc có thể giết thời gian."},{"type":"compound","zh":"这本杂志专门介绍世界各地的旅游风景和美食文化，深受读者欢迎。","pinyin":"Zhè běn zázhì zhuānmén jièshào shìjiè gèdì de lǚyóu fēngjǐng hé měishí wénhuà, shēnshòu dúzhě huānyíng.","vi":"Cuốn tạp chí này chuyên giới thiệu phong cảnh du lịch và văn hóa ẩm thực khắp thế giới, được độc giả hết mực yêu thích."}],"related":[{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"Báo giấy"},{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"小说","pinyin":"xiǎoshuō","vi":"Tiểu thuyết"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"Đọc hiểu"},{"hanzi":"图书馆","pinyin":"túshūguǎn","vi":"Thư viện"}],"traditional":"雜誌"},{"id":"咱们","hanzi":"咱们","pinyin":"zánmen","meaning_vi":"chúng ta (bao gồm cả người nghe)","explanation":"咱 + 们. Khẩu ngữ miền Bắc Trung Quốc.","hsk_level":3,"tags":["dai-tu"],"image":"👥","examples":[{"type":"basic","zh":"时间不早了，咱们走吧！","pinyin":"Shíjiān bù zǎo le, zánmen zǒu ba!","vi":"Thời gian không còn sớm nữa, chúng ta đi thôi!"},{"type":"simple","zh":"咱们俩认识这么多年了，有话直接说就行，千万别这么客气。","pinyin":"Zánmen liǎ rènshi zhème duōnián le, yǒu huà zhíjiē shuō jiù xíng, qiānwàn bié zhème kèqi.","vi":"Hai đứa mình quen nhau bao nhiêu năm rồi, có gì cứ nói thẳng là được, đừng khách sáo thế."},{"type":"compound","zh":"既然大家都同意这个周末去爬山，那咱们今天就去超市把食物准备好吧。","pinyin":"Jìrán dàjiā dōu tóngyì zhè ge zhōumò qù páshān, nà zánmen jīntiān jiù qù chāoshì bǎ shíwù zhǔnbèihǎo ba.","vi":"Vì mọi người đều đồng ý cuối tuần này đi leo núi, vậy hôm nay chúng ta đi siêu thị chuẩn bị sẵn đồ ăn đi."}],"related":[{"hanzi":"我们","pinyin":"wǒmen","vi":"Chúng tôi"},{"hanzi":"你们","pinyin":"nǐmen","vi":"Các bạn"},{"hanzi":"他们","pinyin":"tāmen","vi":"Họ"},{"hanzi":"一起","pinyin":"yìqǐ","vi":"Cùng nhau"},{"hanzi":"俩","pinyin":"liǎ","vi":"Hai người"}],"traditional":"咱們"},{"id":"暂时","hanzi":"暂时","pinyin":"zànshí","meaning_vi":"tạm thời","explanation":"暂 (tạm) + 时 (thời gian).","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"这个问题暂时还没解决。","pinyin":"Zhè ge wèntí zànshí hái méi jiějué.","vi":"Vấn đề này tạm thời vẫn chưa giải quyết được."},{"type":"simple","zh":"因为办公室的空调坏了，所以我们今天暂时搬到会议室去办公。","pinyin":"Yīnwèi bàngōngshì de kōngtiáo huàile, suǒyǐ wǒmen jīntiān zànshí bān dào huìyìshì qù bàngōng.","vi":"Vì điều hòa của văn phòng bị hỏng nên hôm nay chúng tôi tạm thời chuyển sang phòng họp làm việc."},{"type":"compound","zh":"虽然我目前暂时还找不到理想的工作，但是我相信只要继续努力就一定有机会。","pinyin":"Suīrán wǒ mùqián zànshí hái zhǎobúdào lǐxiǎng de gōngzuò, dànshì wǒ xiāngxìn zhǐyào jìxù nǔlì jiù yídìng yǒujī huì.","vi":"Tuy hiện tại tạm thời tôi vẫn chưa tìm được công việc lý tưởng nhưng tôi tin chỉ cần tiếp tục nỗ lực nhất định sẽ có cơ hội."}],"related":[{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"平时","pinyin":"píngshí","vi":"Bình thường"},{"hanzi":"同时","pinyin":"tóngshí","vi":"Đồng thời"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"马上","pinyin":"mǎshàng","vi":"Lập tức"}],"traditional":"暫時"},{"id":"脏","hanzi":"脏","pinyin":"zāng","meaning_vi":"bẩn, dơ","explanation":"Bộ nguyệt ⺼+ 庄. Đối nghĩa với 干净 (sạch sẽ).","hsk_level":3,"tags":["tinh-tu"],"image":"💩","examples":[{"type":"basic","zh":"这件白衬衫弄脏了。","pinyin":"Zhè jiàn bái chènshān nòngzāng le.","vi":"Chiếc áo sơ mi trắng này bị làm bẩn rồi."},{"type":"simple","zh":"小狗在雨后的泥地里跑了一圈，把爪子和毛全都弄脏了。","pinyin":"Xiǎogǒu zài yǔ hòu de ní dì lǐ pǎole yìquān, bǎ zhuǎzi hé máo quándōu nòngzāng le.","vi":"Chú chó nhỏ chạy một vòng trên bãi bùn sau mưa, làm bẩn hết cả chân lẫn lông."},{"type":"compound","zh":"因为刚打完篮球出了很多汗，衣服也脏了，所以我回家第一件事就是洗澡换衣服。","pinyin":"Yīnwèi gāng dǎ wán lánqiú chūle hěn duō hàn, yīfu yě zāng le, suǒyǐ wǒ huíjiā dìyī jiàn shì jiùshì xǐzǎo huànyīfu.","vi":"Vì vừa chơi bóng rổ xong ra nhiều mồ hôi và quần áo cũng bẩn nên việc đầu tiên về nhà của tôi là tắm rửa thay đồ."}],"related":[{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"乱","pinyin":"luàn","vi":"Lộn xộn"},{"hanzi":"洗","pinyin":"xǐ","vi":"Giặt/Rửa"},{"hanzi":"弄","pinyin":"nòng","vi":"Làm"},{"hanzi":"垃圾桶","pinyin":"lājītǒng","vi":"Thùng rác"}],"traditional":"髒"},{"id":"责任","hanzi":"责任","pinyin":"zérèn","meaning_vi":"trách nhiệm","explanation":"责 (bổn phận) + 任 (nhiệm vụ).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"🛡️","examples":[{"type":"basic","zh":"每个人都有自己的责任。","pinyin":"Měigerén dōu yǒu zìjǐ de zérèn.","vi":"Mỗi người đều có trách nhiệm của riêng mình."},{"type":"simple","zh":"王老师工作认真负责，对每一位学生的学习都尽到了最大的责任。","pinyin":"Wáng lǎoshī gōngzuò rènzhēn fùzé, duì měi yí wèi xuésheng de xuéxí dōu jìndàole zuì dà de zérèn.","vi":"Thầy Vương làm việc nghiêm túc có trách nhiệm, luôn tận tâm hết mình với việc học của từng học sinh."},{"type":"compound","zh":"保护地球环境不仅是政府的责任，也是我们每一个普通公民应尽的义务。","pinyin":"Bǎohù dìqiú huánjìng bùjǐn shì zhèngfǔ de zérèn, yě shì wǒmen měi yí ge pǔtōng gōngmín yīng jìn de yìwù.","vi":"Bảo vệ môi trường Trái Đất không chỉ là trách nhiệm của chính phủ mà còn là nghĩa vụ của mỗi công dân bình thường."}],"related":[{"hanzi":"负责","pinyin":"fùzé","vi":"Phụ trách"},{"hanzi":"任务","pinyin":"rènwu","vi":"Nhiệm vụ"},{"hanzi":"任何","pinyin":"rènhé","vi":"Bất kỳ"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"}],"traditional":"責任"},{"id":"占线","hanzi":"占线","pinyin":"zhànxiàn","meaning_vi":"máy bận (điện thoại)","explanation":"占 (chiếm giữ) + 线 (đường dây).","hsk_level":3,"tags":["dong-tu","cong-nghe"],"image":"📵","examples":[{"type":"basic","zh":"对不起，您拨打的电话正在占线。","pinyin":"Duìbuqǐ, nín bōdǎ de diànhuà zhèngzài zhànxiàn.","vi":"Xin lỗi, số điện thoại quý khách vừa gọi hiện đang bận."},{"type":"simple","zh":"我刚才连续给办公室打了三个电话，可是那边一直占线打不通。","pinyin":"Wǒ gāngcái liánxù gěi bàngōngshì dǎle sān ge diànhuà, kěshì nàbiān yìzhí zhànxiàn dǎbùtōng.","vi":"Vừa nãy tôi gọi liên tiếp ba cuộc tới văn phòng nhưng đầu dây bên kia cứ báo bận mãi không gọi được."},{"type":"compound","zh":"因为客服热线现在正处于高峰期，如果遇到占线，请您稍等几分钟再重新拨打。","pinyin":"Yīnwèi kèfú rèxiàn xiànzài zhèng chǔyú gāofēngqī, rúguǒ yùdào zhànxiàn, qǐng nín shāoděng jǐ fēnzhōng zài chóngxīn bōdǎ.","vi":"Vì đường dây nóng chăm sóc khách hàng đang giờ cao điểm nên nếu gặp máy bận, xin quý khách đợi vài phút rồi gọi lại."}],"related":[{"hanzi":"电话","pinyin":"diànhuà","vi":"Điện thoại"},{"hanzi":"打电话","pinyin":"dǎdiànhuà","vi":"Gọi điện"},{"hanzi":"联系","pinyin":"liánxì","vi":"Liên hệ"},{"hanzi":"挂","pinyin":"guà","vi":"Cúp máy"},{"hanzi":"忙","pinyin":"máng","vi":"Bận"}],"traditional":"占線"},{"id":"招聘","hanzi":"招聘","pinyin":"zhāopìn","meaning_vi":"tuyển dụng","explanation":"招 (mời gọi) + 聘 (thuê mướn).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📢","examples":[{"type":"basic","zh":"这家公司正在招聘翻译。","pinyin":"Zhè jiā gōngsī zhèngzài zhāopìn fānyì.","vi":"Công ty này đang tuyển dụng phiên dịch viên."},{"type":"simple","zh":"每年春天和秋天，大学体育馆里都会举办大型毕业生招聘会。","pinyin":"Měinián chūntiān hé qiūtiān, dàxué tǐyùguǎn lǐ dōuhuì jǔbàn dàxíng bìyèshēng zhāopìnhuì.","vi":"Mùa xuân và mùa thu hằng năm, trong nhà thi đấu đại học đều tổ chức ngày hội tuyển dụng sinh viên tốt nghiệp quy mô lớn."},{"type":"compound","zh":"因为公司业务不断扩大，所以人事部决定下个月再招聘五名有经验的工程师。","pinyin":"Yīnwèi gōngsī yèwù búduàn kuòdà, suǒyǐ rénshìbù juédìng xiàgeyuè zài zhāopìn wǔ míng yǒu jīngyàn de gōngchéngshī.","vi":"Vì nghiệp vụ công ty không ngừng mở rộng nên phòng nhân sự quyết định tháng sau tuyển thêm năm kỹ sư có kinh nghiệm."}],"related":[{"hanzi":"应聘","pinyin":"yìngpìn","vi":"Ứng tuyển"},{"hanzi":"打招呼","pinyin":"dǎzhāohu","vi":"Chào hỏi"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"条件","pinyin":"tiáojiàn","vi":"Điều kiện"}]},{"id":"照","hanzi":"照","pinyin":"zhào","meaning_vi":"chiếu, soi, chụp (ảnh)","explanation":"Dùng trong 照相 (chụp ảnh), 照镜子 (soi gương).","hsk_level":3,"tags":["dong-tu"],"image":"📸","examples":[{"type":"basic","zh":"我们一起照张相吧！","pinyin":"Wǒmen yìqǐ zhào zhāng xiàng ba!","vi":"Chúng ta cùng chụp một tấm ảnh nhé!"},{"type":"simple","zh":"出门之前，妈妈总喜欢站在客厅的大镜子前面照一照衣服整不整齐。","pinyin":"Chūmén zhīqián, māma zǒng xǐhuan zhàn zài kètīng de dà jìngzi qiánmiàn zhào yi zhào yīfu zhěng bu zhěngqí.","vi":"Trước khi ra khỏi nhà, mẹ luôn thích đứng trước chiếc gương lớn ở phòng khách soi xem quần áo đã chỉnh tề chưa."},{"type":"compound","zh":"虽然长城上的游客非常多，但是我们还是找了一个好角度照了很多漂亮的照片。","pinyin":"Suīrán Chángchéng shang de yóukè fēichángduō, dànshì wǒmen háishi zhǎole yí ge hǎo jiǎodù zhàole hěn duō piàoliang de zhàopiàn.","vi":"Tuy du khách trên Vạn Lý Trường Thành rất đông nhưng chúng tôi vẫn tìm được góc đẹp để chụp nhiều tấm ảnh xinh."}],"related":[{"hanzi":"照片","pinyin":"zhàopiàn","vi":"Bức ảnh"},{"hanzi":"照相机","pinyin":"zhàoxiàngjī","vi":"Máy ảnh"},{"hanzi":"照顾","pinyin":"zhàogu","vi":"Chăm sóc"},{"hanzi":"护照","pinyin":"hùzhào","vi":"Hộ chiếu"},{"hanzi":"镜子","pinyin":"jìngzi","vi":"Cái gương"}]},{"id":"真正","hanzi":"真正","pinyin":"zhēnzhèng","meaning_vi":"chân chính, thực sự","explanation":"真 (thật) + 正 (chính xác).","hsk_level":3,"tags":["tinh-tu","pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"他是我真正的好朋友。","pinyin":"Tā shì wǒ zhēnzhèng de hǎopéngyou.","vi":"Anh ấy là người bạn tốt thực sự của tôi."},{"type":"simple","zh":"只有亲身去中国生活一段时间，才能真正了解当地的风土人情。","pinyin":"Zhǐyǒu qīnshēn qù Zhōngguó shēnghuó yí duàn shíjiān, cáinéng zhēnzhèng liǎojiě dāngdì de fēngtǔrénqíng.","vi":"Chỉ có tự mình sang Trung Quốc sinh sống một thời gian mới có thể thực sự hiểu rõ phong tục tập quán địa phương."},{"type":"compound","zh":"在遇到困难的时候，真正关心你的人不会只说空话，而是会用实际行动帮助你。","pinyin":"Zài yùdào kùnnan de shíhou, zhēnzhèng guānxīn nǐ de rén bú huì zhǐ shuō kōnghuà, érshì huì yòng shíjì xíngdòng bāngzhù nǐ.","vi":"Khi gặp khó khăn, người thực sự quan tâm đến bạn sẽ không chỉ nói suông mà sẽ dùng hành động thực tế để giúp đỡ bạn."}],"related":[{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"Bình thường"},{"hanzi":"假","pinyin":"jiǎ","vi":"Giả"},{"hanzi":"确实","pinyin":"quèshí","vi":"Quả thực"}]},{"id":"整理","hanzi":"整理","pinyin":"zhěnglǐ","meaning_vi":"sắp xếp, chỉnh lý, dọn dẹp","explanation":"整 (gọn gàng) + 理 (sắp đặt).","hsk_level":3,"tags":["dong-tu"],"image":"🗂️","examples":[{"type":"basic","zh":"我正在整理学习资料。","pinyin":"Wǒ zhèngzài zhěnglǐ xuéxí zīliào.","vi":"Tôi đang sắp xếp lại tài liệu học tập."},{"type":"simple","zh":"每次上完课以后，我都会把笔记本上的重点语法整理一遍。","pinyin":"Měi cì shàng wán kè yǐhòu, wǒ dōuhuì bǎ bǐjìběn shang de zhòngdiǎn yǔfǎ zhěnglǐ yíbiàn.","vi":"Mỗi lần học xong, tôi đều hệ thống sắp xếp lại một lượt ngữ pháp trọng điểm trong sổ tay."},{"type":"compound","zh":"因为房间里的书和杂物太多了，所以我今天花了一整个下午才把它们整理干净。","pinyin":"Yīnwèi fángjiān lǐ de shū hé záwù tài duō le, suǒyǐ wǒ jīntiān huāle yì zhěngge xiàwǔ cái bǎ tāmen zhěnglǐ gānjìng.","vi":"Vì sách vở và đồ lặt vặt trong phòng nhiều quá nên hôm nay tôi mất trọn cả buổi chiều mới dọn dẹp gọn gàng xong."}],"related":[{"hanzi":"收拾","pinyin":"shōushi","vi":"Dọn dẹp"},{"hanzi":"排列","pinyin":"páiliè","vi":"Sắp xếp"},{"hanzi":"整齐","pinyin":"zhěngqí","vi":"Ngăn nắp"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"},{"hanzi":"理发","pinyin":"lǐfà","vi":"Cắt tóc"}]},{"id":"正常","hanzi":"正常","pinyin":"zhèngcháng","meaning_vi":"bình thường","explanation":"正 (đúng) + 常 (thường lệ).","hsk_level":3,"tags":["tinh-tu"],"image":"✔️","examples":[{"type":"basic","zh":"一切都很正常，别担心。","pinyin":"Yíqiè dōu hěn zhèngcháng, biédānxīn.","vi":"Mọi thứ đều rất bình thường, đừng lo lắng."},{"type":"simple","zh":"医生检查完以后说我的身体各项指标都很正常，只要注意多休息就行了。","pinyin":"Yīshēng jiǎnchá wán yǐhòu shuō wǒ de shēntǐ gè xiàng zhǐbiāo dōu hěn zhèngcháng, zhǐyào zhùyì duō xiūxi jiù xíng le.","vi":"Bác sĩ khám xong nói các chỉ số cơ thể của tôi đều rất bình thường, chỉ cần chú ý nghỉ ngơi nhiều là được."},{"type":"compound","zh":"虽然飞机因为大雾推迟了一个小时，但是现在天气转晴，航班已经恢复正常了。","pinyin":"Suīrán fēijī yīnwèi dàwù tuīchíle yí ge xiǎoshí, dànshì xiànzài tiānqì zhuǎn qíng, hángbān yǐjīng huīfù zhèngcháng le.","vi":"Tuy máy bay bị hoãn một tiếng vì sương mù dày nhưng hiện tại trời đã quang mây tạnh, các chuyến bay đã hoạt động bình thường trở lại."}],"related":[{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"正式","pinyin":"zhèngshì","vi":"Chính thức"},{"hanzi":"一般","pinyin":"yìbān","vi":"Bình thường"},{"hanzi":"平时","pinyin":"píngshí","vi":"Ngày thường"}]},{"id":"正好","hanzi":"正好","pinyin":"zhènghǎo","meaning_vi":"vừa vặn, đúng lúc, may quá","explanation":"正 (đúng) + 好 (tốt).","hsk_level":3,"tags":["tinh-tu","pho-tu"],"image":"🎯","examples":[{"type":"basic","zh":"这件衣服我穿正好。","pinyin":"Zhè jiàn yīfu wǒ chuān zhènghǎo.","vi":"Chiếc áo này tôi mặc vừa vặn luôn."},{"type":"simple","zh":"我正准备出门去找你，没想到你正好敲门进来了，真巧啊！","pinyin":"Wǒ zhèng zhǔnbèi chūmén qù zhǎo nǐ, méi xiǎngdào nǐ zhènghǎo qiāomén jìnlái le, zhēn qiǎo a!","vi":"Tôi đang định ra ngoài đi tìm bạn, không ngờ bạn vừa hay gõ cửa bước vào, trùng hợp thật đấy!"},{"type":"compound","zh":"这双运动鞋不仅颜色是我最喜欢的蓝色，而且尺码也正好合适，价格还打折。","pinyin":"Zhè shuāng yùndòngxié bùjǐn yánsè shì wǒ zuì xǐhuan de lánsè, érqiě chǐmǎ yě zhènghǎo héshì, jiàgé hái dǎzhé.","vi":"Đôi giày thể thao này không chỉ có màu xanh dương tôi thích nhất mà cỡ giày cũng vừa vặn luôn, giá lại còn đang giảm."}],"related":[{"hanzi":"刚好","pinyin":"gānghǎo","vi":"Vừa khéo"},{"hanzi":"合适","pinyin":"héshì","vi":"Thích hợp"},{"hanzi":"好","pinyin":"hǎo","vi":"Tốt"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"}]},{"id":"正确","hanzi":"正确","pinyin":"zhèngquè","meaning_vi":"chính xác, đúng đắn","explanation":"正 (đúng) + 确 (xác thực). Đối nghĩa với 错误 (sai lầm).","hsk_level":3,"tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"你的回答完全正确。","pinyin":"Nǐ de huídá wánquán zhèngquè.","vi":"Câu trả lời của bạn hoàn toàn chính xác."},{"type":"simple","zh":"学习写汉字的时候，从一开始就必须掌握正确的笔画顺序。","pinyin":"Xuéxí xiě hànzì de shíhou, cóng yì kāishǐ jiù bìxū zhǎngwò zhèngquè de bǐhuà shùnxù.","vi":"Khi học viết chữ Hán, ngay từ đầu đã phải nắm vững thứ tự nét bút chính xác."},{"type":"compound","zh":"只要我们坚持使用正确的学习方法，就一定能在短时间内提高汉语成绩。","pinyin":"Zhǐyào wǒmen jiānchí shǐyòng zhèngquè de xuéxí fāngfǎ, jiù yídìng néng zài duǎnshíjiān nèi tígāo Hànyǔ chéngjì.","vi":"Chỉ cần chúng ta kiên trì áp dụng phương pháp học tập đúng đắn thì nhất định sẽ nâng cao điểm số tiếng Trung trong thời gian ngắn."}],"related":[{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"Chính xác"},{"hanzi":"对","pinyin":"duì","vi":"Đúng"},{"hanzi":"确实","pinyin":"quèshí","vi":"Quả thực"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"Bình thường"}],"traditional":"正確"},{"id":"正式","hanzi":"正式","pinyin":"zhèngshì","meaning_vi":"chính thức","explanation":"正 (ngay ngắn) + 式 (nghi thức).","hsk_level":3,"tags":["tinh-tu"],"image":"👔","examples":[{"type":"basic","zh":"会议今天上午正式开始。","pinyin":"Huìyì jīntiān shàngwǔ zhèngshì kāishǐ.","vi":"Cuộc họp chính thức bắt đầu vào sáng nay."},{"type":"simple","zh":"参加重要面试或者商务谈判时，大家一般都会穿比较正式的西装。","pinyin":"Cānjiā zhòngyào miànshì huòzhě shāngwù tánpàn shí, dàjiā yìbān dōuhuì chuān bǐjiào zhèngshì de xīzhuāng.","vi":"Khi tham gia phỏng vấn quan trọng hoặc đàm phán thương mại, mọi người thường mặc vest trang trọng."},{"type":"compound","zh":"经过三个月的实习期考核以后，他下个月就要成为这家公司的正式员工了。","pinyin":"Jīngguò sān geyuè de shíxíqī kǎohé yǐhòu, tā xiàgeyuè jiùyào chéngwéi zhè jiā gōngsī de zhèngshì yuángōng le.","vi":"Sau khi vượt qua kỳ đánh giá thử việc ba tháng, tháng sau anh ấy sẽ trở thành nhân viên chính thức của công ty này."}],"related":[{"hanzi":"正常","pinyin":"zhèngcháng","vi":"Bình thường"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"形式","pinyin":"xíngshì","vi":"Hình thức"},{"hanzi":"举行","pinyin":"jǔxíng","vi":"Tổ chức"},{"hanzi":"严格","pinyin":"yángé","vi":"Nghiêm ngặt"}]},{"id":"证明","hanzi":"证明","pinyin":"zhèngmíng","meaning_vi":"chứng minh, giấy chứng nhận","explanation":"证 (bằng chứng) + 明 (rõ ràng).","hsk_level":3,"tags":["dong-tu","danh-tu"],"image":"📜","examples":[{"type":"basic","zh":"事实证明他是正确的。","pinyin":"Shìshí zhèngmíng tā shì zhèngquè de.","vi":"Thực tế chứng minh anh ấy đã đúng."},{"type":"simple","zh":"办理学生签证延期的时候，需要学校出具一份在读证明。","pinyin":"Bànlǐ xuésheng qiānzhèng yánqī de shíhou, xūyào xuéxiào chūjù yí fèn zài dú zhèngmíng.","vi":"Khi làm thủ tục gia hạn visa du học sinh, cần nhà trường cấp một giấy chứng nhận đang theo học."},{"type":"compound","zh":"虽然以前很多人怀疑他的能力，但是他用优秀的工作成绩证明了自己。","pinyin":"Suīrán yǐqián hěn duō rén huáiyí tā de nénglì, dànshì tāyòng yōuxiù de gōngzuò chéngjì zhèngmíngle zìjǐ.","vi":"Tuy trước đây nhiều người nghi ngờ năng lực của anh ấy nhưng anh ấy đã dùng thành tích công việc xuất sắc để chứng minh bản thân."}],"related":[{"hanzi":"说明","pinyin":"shuōmíng","vi":"Giải thích"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"Visa"},{"hanzi":"明白","pinyin":"míngbai","vi":"Rõ ràng"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"保证","pinyin":"bǎozhèng","vi":"Bảo đảm"}],"traditional":"證明"},{"id":"之","hanzi":"之","pinyin":"zhī","meaning_vi":"của (trợ từ văn viết)","explanation":"Dùng trong các cụm cố định như 之一 (một trong số), 之前 (trước khi), 之后 (sau khi).","hsk_level":3,"tags":["tro-tu"],"image":"📌","examples":[{"type":"basic","zh":"北京是世界上最著名的城市之一。","pinyin":"Běijīng shì shìjiè shang zuì zhùmíng de chéngshì zhīyī.","vi":"Bắc Kinh là một trong những thành phố nổi tiếng nhất trên thế giới."},{"type":"simple","zh":"出门旅游之前，我们应该提前查好目的地的天气预报和交通路线。","pinyin":"Chūmén lǚyóu zhīqián, wǒmen yīnggāi tíqián chá hǎo mùdìdì de tiānqì yùbào hé jiāotōng lùxiàn.","vi":"Trước khi ra ngoài đi du lịch, chúng ta nên tra trước dự báo thời tiết và tuyến đường giao thông của điểm đến."},{"type":"compound","zh":"总而言之，只要我们每天坚持认真练习，汉语水平就一定会不断提高。","pinyin":"Zǒng'éryánzhī, zhǐyào wǒmen měitiān jiānchí rènzhēn liànxí, Hànyǔ shuǐpíng jiù yídìng huì búduàn tígāo.","vi":"Nói tóm lại, chỉ cần mỗi ngày chúng ta kiên trì luyện tập nghiêm túc thì trình độ tiếng Trung nhất định sẽ không ngừng nâng cao."}],"related":[{"hanzi":"的","pinyin":"de","vi":"Của"},{"hanzi":"之前","pinyin":"zhīqián","vi":"Trước khi"},{"hanzi":"之后","pinyin":"zhīhòu","vi":"Sau khi"},{"hanzi":"之一","pinyin":"zhīyī","vi":"Một trong số"},{"hanzi":"生命","pinyin":"shēngmìng","vi":"Sinh mệnh"}]},{"id":"知识","hanzi":"知识","pinyin":"zhīshi","meaning_vi":"kiến thức, tri thức","explanation":"知 (biết) + 识 (hiểu biết).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"书本里有很多有用的知识。","pinyin":"Shūběn lǐ yǒu hěn duō yǒuyòng de zhīshi.","vi":"Trong sách vở có rất nhiều kiến thức hữu ích."},{"type":"simple","zh":"多阅读报纸、杂志和科学书籍，可以帮助我们不断丰富自己的知识。","pinyin":"Duō yuèdú bàozhǐ, zázhì hé kēxué shūjí, kěyǐ bāngzhù wǒmen búduàn fēngfù zìjǐ de zhīshi.","vi":"Đọc nhiều báo chí, tạp chí và sách khoa học có thể giúp chúng ta không ngừng làm phong phú vốn kiến thức của mình."},{"type":"compound","zh":"在学校里不仅要认真学习课本知识，还要积极参加社会实践锻炼能力。","pinyin":"Zài xuéxiào lǐ bùjǐn yào rènzhēn xuéxí kèběn zhīshi, hái yào jījí cānjiā shèhuì shíjiàn duànliàn nénglì.","vi":"Ở trường không chỉ phải chăm chỉ học kiến thức sách vở mà còn phải tích cực tham gia thực tiễn xã hội để rèn luyện kỹ năng."}],"related":[{"hanzi":"知道","pinyin":"zhīdao","vi":"Biết"},{"hanzi":"认识","pinyin":"rènshi","vi":"Nhận biết"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"科学","pinyin":"kēxué","vi":"Khoa học"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"Đọc hiểu"}],"traditional":"知識"},{"id":"直接","hanzi":"直接","pinyin":"zhíjiē","meaning_vi":"trực tiếp","explanation":"直 (thẳng) + 接 (tiếp xúc).","hsk_level":3,"tags":["tinh-tu","pho-tu"],"image":"➡️","examples":[{"type":"basic","zh":"下班以后我直接回家。","pinyin":"Xiàbān yǐhòu wǒ zhíjiē huíjiā.","vi":"Sau khi tan làm tôi về thẳng nhà luôn."},{"type":"simple","zh":"从这里坐二号线地铁不用换乘，可以直接到达火车站。","pinyin":"Cóng zhèlǐ zuò èrhào xiàn dìtiě bú yòng huànchéng, kěyǐ zhíjiē dàodá huǒchēzhàn.","vi":"Từ đây đi tàu điện ngầm tuyến số 2 không cần chuyển tuyến, có thể đi thẳng tới ga tàu hỏa."},{"type":"compound","zh":"如果你们之间有什么误会，最好当面直接沟通清楚，不要放在心里。","pinyin":"Rúguǒ nǐmen zhījiān yǒu shénme wùhuì, zuìhǎo dāngmiàn zhíjiē gōutōng qīngchu, bú yào fàng zài xīnlǐ.","vi":"Nếu giữa hai người có hiểu lầm gì thì tốt nhất nên trao đổi thẳng thắn trực tiếp cho rõ ràng, đừng giữ trong lòng."}],"related":[{"hanzi":"一直","pinyin":"yìzhí","vi":"Thẳng/Suốt"},{"hanzi":"接受","pinyin":"jiēshòu","vi":"Tiếp nhận"},{"hanzi":"接着","pinyin":"jiēzhe","vi":"Tiếp theo"},{"hanzi":"联系","pinyin":"liánxì","vi":"Liên hệ"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"Đơn giản"}]},{"id":"值得","hanzi":"值得","pinyin":"zhíde","meaning_vi":"đáng, xứng đáng","explanation":"值 (giá trị) + 得 (được). Ví dụ: 值得学习 (đáng học hỏi).","hsk_level":3,"tags":["dong-tu"],"image":"💎","examples":[{"type":"basic","zh":"这本书非常值得一看。","pinyin":"Zhè běn shū fēicháng zhíde yí kàn.","vi":"Quyển sách này vô cùng đáng để đọc thử."},{"type":"simple","zh":"北京的长城和故宫历史悠久、风景壮观，非常值得去参观。","pinyin":"Běijīng de Chángchéng hé gùgōng lìshǐ yōujiǔ, fēngjǐng zhuàngguān, fēicháng zhíde qù cānguān.","vi":"Vạn Lý Trường Thành và Cố Cung ở Bắc Kinh lịch sử lâu đời, phong cảnh hùng vĩ, rất đáng để đi tham quan."},{"type":"compound","zh":"虽然准备比赛的过程非常辛苦，但是看到大家取得这么好的成绩觉得一切都值得。","pinyin":"Suīrán zhǔnbèi bǐsài de guòchéng fēicháng xīnkǔ, dànshì kàndào dàjiā qǔdé zhème hǎo de chéngjì juéde yíqiè dōu zhíde.","vi":"Tuy quá trình chuẩn bị thi đấu vô cùng vất vả nhưng nhìn thấy mọi người đạt thành tích tốt như vậy lại thấy mọi thứ đều xứng đáng."}],"related":[{"hanzi":"价值","pinyin":"jiàzhí","vi":"Giá trị"},{"hanzi":"获得","pinyin":"huòdé","vi":"Giành được"},{"hanzi":"记得","pinyin":"jìde","vi":"Nhớ"},{"hanzi":"优秀","pinyin":"yōuxiù","vi":"Xuất sắc"},{"hanzi":"参观","pinyin":"cānguān","vi":"Tham quan"}]},{"id":"职业","hanzi":"职业","pinyin":"zhíyè","meaning_vi":"nghề nghiệp","explanation":"职 (chức vụ) + 业 (nghiệp).","hsk_level":3,"tags":["danh-tu","nghe-nghiep"],"image":"💼","examples":[{"type":"basic","zh":"教师是一个很受尊重的职业。","pinyin":"Jiàoshī shì yí ge hěn shòu zūnzhòng de zhíyè.","vi":"Giáo viên là một nghề nghiệp rất được tôn trọng."},{"type":"simple","zh":"大学毕业之前，很多学生都会认真考虑自己未来的职业发展方向。","pinyin":"Dàxué bìyè zhīqián, hěn duō xuésheng dōuhuì rènzhēn kǎolǜ zìjǐ wèilái de zhíyè fāzhǎn fāngxiàng.","vi":"Trước khi tốt nghiệp đại học, nhiều sinh viên đều nghiêm túc cân nhắc định hướng phát triển nghề nghiệp tương lai của mình."},{"type":"compound","zh":"无论从事哪一种职业，只要爱岗敬业、认真负责，都能为社会做出贡献。","pinyin":"Wúlùn cóngshì nǎ yì zhǒng zhíyè, zhǐyào ài gǎng jìngyè, rènzhēn fùzé, dōu néng wéi shèhuì zuòchū gòngxiàn.","vi":"Bất kể làm nghề nghiệp nào, chỉ cần yêu nghề tận tụy và có trách nhiệm thì đều có thể đóng góp cho xã hội."}],"related":[{"hanzi":"专业","pinyin":"zhuānyè","vi":"Chuyên ngành"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"毕业","pinyin":"bìyè","vi":"Tốt nghiệp"},{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"Tôn trọng"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"}],"traditional":"職業"},{"id":"植物","hanzi":"植物","pinyin":"zhíwù","meaning_vi":"thực vật, cây cối","explanation":"植 (trồng trọt) + 物 (vật thể).","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"妈妈在阳台上养了很多植物。","pinyin":"Māma zài yángtái shang yǎngle hěn duō zhíwù.","vi":"Mẹ trồng rất nhiều cây cảnh ở trên ban công."},{"type":"simple","zh":"周末的时候，爸爸带着我和妹妹去植物园认识了许多珍稀花草。","pinyin":"Zhōumò de shíhou, bàba dàizhe wǒ hé mèimei qù zhíwùyuán rènshile xǔduō zhēnxī huācǎo.","vi":"Vào cuối tuần, bố dẫn tôi và em gái đến vườn bách thảo nhận biết nhiều loài hoa cỏ quý hiếm."},{"type":"compound","zh":"绿色植物不仅可以美化家庭环境，还能吸收二氧化碳、释放新鲜氧气。","pinyin":"Lǜsè zhíwù bùjǐn kěyǐ měihuà jiātíng huánjìng, hái néng xīshōu èryǎnghuàtàn, shìfàng xīnxiān yǎngqì.","vi":"Cây xanh không những làm đẹp môi trường gia đình mà còn hấp thụ khí cacbonic và nhả ra khí oxy trong lành."}],"related":[{"hanzi":"动物","pinyin":"dòngwù","vi":"Động vật"},{"hanzi":"森林","pinyin":"sēnlín","vi":"Rừng rậm"},{"hanzi":"树","pinyin":"shù","vi":"Cây"},{"hanzi":"花","pinyin":"huā","vi":"Hoa"},{"hanzi":"叶子","pinyin":"yèzi","vi":"Lá cây"}]},{"id":"只好","hanzi":"只好","pinyin":"zhǐhǎo","meaning_vi":"đành phải","explanation":"只 (chỉ) + 好 (tốt/đành).","hsk_level":3,"tags":["pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"下雨了，我们只好待在家里。","pinyin":"Xiàyǔ le, wǒmen zhǐhǎo dāi zài jiālǐ.","vi":"Trời mưa rồi, chúng tôi đành phải ở trong nhà."},{"type":"simple","zh":"因为去北京的飞机票已经卖完了，所以我只好改坐高铁去。","pinyin":"Yīnwèi qù Běijīng de fēijīpiào yǐjīng mài wánle, suǒyǐ wǒ zhǐhǎo gǎi zuò gāotiě qù.","vi":"Vì vé máy bay đi Bắc Kinh đã bán hết rồi nên tôi đành phải đổi sang đi tàu cao tốc."},{"type":"compound","zh":"昨天晚上家里突然停电了，没办法看电脑，我只好早早地洗漱睡觉了。","pinyin":"Zuótiān wǎnshang jiālǐ tūrán tíngdiàn le, méi bànfǎ kàn diànnǎo, wǒ zhǐhǎo zǎo zǎo de xǐshù shuìjiào le.","vi":"Tối hôm qua nhà đột nhiên mất điện, không xem máy tính được nên tôi đành đi vệ sinh cá nhân rồi đi ngủ sớm."}],"related":[{"hanzi":"只要","pinyin":"zhǐyào","vi":"Chỉ cần"},{"hanzi":"最好","pinyin":"zuìhǎo","vi":"Tốt nhất"},{"hanzi":"不得不","pinyin":"bùdébù","vi":"Không thể không"},{"hanzi":"只","pinyin":"zhǐ","vi":"Chỉ"},{"hanzi":"好","pinyin":"hǎo","vi":"Tốt/Đành"}]},{"id":"只要","hanzi":"只要","pinyin":"zhǐyào","meaning_vi":"chỉ cần","explanation":"只 + 要 (cần). Thường đi cặp với 就 (只要...就... - chỉ cần... thì...).","hsk_level":3,"tags":["lien-tu"],"image":"🔑","examples":[{"type":"basic","zh":"只要努力，就一定能成功。","pinyin":"Zhǐyào nǔlì, jiù yídìng néng chénggōng.","vi":"Chỉ cần nỗ lực thì nhất định sẽ thành công."},{"type":"simple","zh":"只要每天坚持听半个小时中文广播，你的听力水平就会慢慢提高。","pinyin":"Zhǐyào měitiān jiānchí tīng bàn ge xiǎoshí Zhōngwén guǎngbō, nǐ de tīnglì shuǐpíng jiù huì mànmàn tígāo.","vi":"Chỉ cần mỗi ngày kiên trì nghe đài tiếng Trung nửa tiếng thì trình độ nghe của bạn sẽ dần nâng cao."},{"type":"compound","zh":"不管遇到什么困难，只要我们大家团结一致、互相帮助，就一定能克服。","pinyin":"Bùguǎn yùdào shénme kùnnan, zhǐyào wǒmen dàjiā tuánjié yízhì, hùxiāng bāngzhù, jiù yídìng néng kèfú.","vi":"Bất kể gặp khó khăn gì, chỉ cần tất cả chúng ta đoàn kết nhất trí và giúp đỡ lẫn nhau thì nhất định sẽ vượt qua."}],"related":[{"hanzi":"只好","pinyin":"zhǐhǎo","vi":"Đành phải"},{"hanzi":"只有","pinyin":"zhǐyǒu","vi":"Chỉ có"},{"hanzi":"如果","pinyin":"rúguǒ","vi":"Nếu như"},{"hanzi":"就","pinyin":"jiù","vi":"Thì/Liền"},{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"}]},{"id":"指","hanzi":"指","pinyin":"zhǐ","meaning_vi":"chỉ, trỏ; ngón tay","explanation":"Bộ tài gảy 扌+ 旨.","hsk_level":3,"tags":["dong-tu","co-the"],"image":"👆","examples":[{"type":"basic","zh":"他指着地图给我讲路线。","pinyin":"Tā zhǐzhe dìtú gěi wǒ jiǎng lùxiàn.","vi":"Anh ấy chỉ vào bản đồ giảng giải lộ trình cho tôi."},{"type":"simple","zh":"在公共场合用手指着别人说话是一种非常不礼貌的行为。","pinyin":"Zài gōnggòng chǎnghé yòng shǒuzhǐzhe biérén shuōhuà shì yì zhǒng fēicháng bù lǐmào de xíngwéi.","vi":"Ở nơi công cộng dùng ngón tay chỉ vào người khác khi nói chuyện là một hành vi rất bất lịch sự."},{"type":"compound","zh":"那位热情的交警叔叔指着前面的十字路口，详细地告诉了我去医院怎么走。","pinyin":"Nà wèi rèqíng de jiāojǐng shūshu zhǐzhe qiánmiàn de shízìlùkǒu, xiángxì de gàosule wǒqù yīyuàn zěnme zǒu.","vi":"Chú cảnh sát giao thông nhiệt tình đó chỉ về phía ngã tư đằng trước, hướng dẫn chi tiết cho tôi đường đi đến bệnh viện."}],"related":[{"hanzi":"手指","pinyin":"shǒuzhǐ","vi":"Ngón tay"},{"hanzi":"指导","pinyin":"zhǐdǎo","vi":"Chỉ đạo/Hướng dẫn"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"手","pinyin":"shǒu","vi":"Tay"}]},{"id":"至少","hanzi":"至少","pinyin":"zhìshǎo","meaning_vi":"ít nhất","explanation":"至 (tới) + 少 (ít).","hsk_level":3,"tags":["pho-tu"],"image":"🔢","examples":[{"type":"basic","zh":"从这里到机场至少要一个小时。","pinyin":"Cóng zhèlǐ dào jīchǎng zhìshǎo yào yí ge xiǎoshí.","vi":"Từ đây ra sân bay ít nhất mất một tiếng đồng hồ."},{"type":"simple","zh":"医生建议成年人每天至少要喝八杯水，这样才能保持身体水分充足。","pinyin":"Yīshēng jiànyì chéngniánrén měitiān zhìshǎo yào hē bā bēi shuǐ, zhèyàng cáinéng bǎochí shēntǐ shuǐfèn chōngzú.","vi":"Bác sĩ khuyên người trưởng thành mỗi ngày ít nhất phải uống 8 cốc nước, như vậy mới giữ cho cơ thể đủ nước."},{"type":"compound","zh":"虽然这篇文章我还没完全背下来，但是至少已经理解了它的全部意思。","pinyin":"Suīrán zhè piān wénzhāng wǒ hái méi wánquán bèi xiàlái, dànshì zhìshǎo yǐjīng lǐjiěle tā de quánbù yìsi.","vi":"Tuy bài văn này tôi vẫn chưa học thuộc lòng hoàn toàn nhưng ít nhất đã hiểu hết toàn bộ ý nghĩa của nó."}],"related":[{"hanzi":"甚至","pinyin":"shènzhì","vi":"Thậm chí"},{"hanzi":"少","pinyin":"shǎo","vi":"Ít"},{"hanzi":"最多","pinyin":"zuìduō","vi":"Nhiều nhất"},{"hanzi":"大约","pinyin":"dàyuē","vi":"Khoảng chừng"},{"hanzi":"大概","pinyin":"dàgài","vi":"Đại khái"}]},{"id":"质量","hanzi":"质量","pinyin":"zhìliàng","meaning_vi":"chất lượng","explanation":"质 (bản chất) + 量 (lượng).","hsk_level":3,"tags":["danh-tu","mua-sam"],"image":"⭐","examples":[{"type":"basic","zh":"这家商店的商品质量很好。","pinyin":"Zhè jiā shāngdiàn de shāngpǐn zhìliàng hěn hǎo.","vi":"Chất lượng hàng hóa của cửa hàng này rất tốt."},{"type":"simple","zh":"买衣服和鞋子的时候，不能只看价格便宜，更要注重产品的质量。","pinyin":"Mǎi yīfu hé xiézi de shíhou, bù néng zhǐ kàn jiàgé piányi, gèng yào zhùzhòng chǎnpǐn de zhìliàng.","vi":"Khi mua quần áo và giày dép, không thể chỉ nhìn giá rẻ mà càng phải chú trọng chất lượng sản phẩm."},{"type":"compound","zh":"因为这家工厂一直严格把控产品质量，所以他们的产品在国内外都很受欢迎。","pinyin":"Yīnwèi zhè jiā gōngchǎng yìzhí yángé bǎ kòng chǎnpǐn zhìliàng, suǒyǐ tāmen de chǎnpǐn zài guónèiwài dōu hěn shòuhuānyíng.","vi":"Vì nhà máy này luôn kiểm soát chặt chẽ chất lượng sản phẩm nên hàng hóa của họ rất được ưa chuộng cả trong và ngoài nước."}],"related":[{"hanzi":"数量","pinyin":"shùliàng","vi":"Số lượng"},{"hanzi":"重量","pinyin":"zhòngliàng","vi":"Trọng lượng"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"合格","pinyin":"hégé","vi":"Đạt chuẩn"},{"hanzi":"价格","pinyin":"jiàgé","vi":"Giá cả"}],"traditional":"質量"},{"id":"重点","hanzi":"重点","pinyin":"zhòngdiǎn","meaning_vi":"trọng điểm, điểm chính","explanation":"重 (quan trọng) + 点 (điểm).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🎯","examples":[{"type":"basic","zh":"请大家把这些重点记下来。","pinyin":"Qǐng dàjiā bǎ zhèxiē zhòngdiǎn jì xiàlái.","vi":"Xin mọi người hãy ghi chép lại những trọng điểm này."},{"type":"simple","zh":"复习考试的时候，我们要先掌握课本里的重点语法和核心词汇。","pinyin":"Fùxí kǎoshì de shíhou, wǒmen yào xiān zhǎngwò kèběn lǐ de zhòngdiǎn yǔfǎ hé héxīn cíhuì.","vi":"Khi ôn thi, trước tiên chúng ta phải nắm vững ngữ pháp trọng điểm và từ vựng cốt lõi trong sách giáo khoa."},{"type":"compound","zh":"王老师在讲课的时候总是条理清晰，把每节课的重点和难点都讲得很透彻。","pinyin":"Wáng lǎoshī zài jiǎngkè de shíhou zǒngshì tiáolǐ qīngxī, bǎ měi jié kè de zhòngdiǎn hé nándiǎn dōu jiǎng de hěn tòuchè.","vi":"Thầy Vương khi giảng bài luôn mạch lạc rõ ràng, giảng giải rất thấu đáo trọng điểm và điểm khó của từng tiết học."}],"related":[{"hanzi":"重要","pinyin":"zhòngyào","vi":"Quan trọng"},{"hanzi":"特点","pinyin":"tèdiǎn","vi":"Đặc điểm"},{"hanzi":"优点","pinyin":"yōudiǎn","vi":"Ưu điểm"},{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"Khuyết điểm"},{"hanzi":"重","pinyin":"zhòng","vi":"Trọng/Nặng"}],"traditional":"重點"},{"id":"重视","hanzi":"重视","pinyin":"zhòngshì","meaning_vi":"coi trọng, chú trọng","explanation":"重 (trọng) + 视 (nhìn nhận).","hsk_level":3,"tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"学校非常重视学生的安全。","pinyin":"Xuéxiào fēicháng zhòngshì xuésheng de ānquán.","vi":"Nhà trường vô cùng coi trọng sự an toàn của học sinh."},{"type":"simple","zh":"现在越来越多的年轻人开始重视健康饮食和规律的体育锻炼。","pinyin":"Xiànzài yuèláiyuè duō de niánqīngrén kāishǐ zhòngshì jiànkāng yǐnshí hé guīlǜ de tǐyù duànliàn.","vi":"Hiện nay ngày càng có nhiều người trẻ bắt đầu coi trọng ăn uống lành mạnh và tập luyện thể thao điều độ."},{"type":"compound","zh":"既然公司领导这么重视这个项目，我们就一定要齐心协力把它做到最好。","pinyin":"Jìrán gōngsī lǐngdǎo zhème zhòngshì zhè ge xiàngmù, wǒmen jiù yídìngyào qíxīnxiélì bǎ tā zuòdào zuìhǎo.","vi":"Vì lãnh đạo công ty coi trọng dự án này như vậy nên chúng ta nhất định phải đồng tâm hiệp lực làm cho thật tốt."}],"related":[{"hanzi":"重要","pinyin":"zhòngyào","vi":"Quan trọng"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"Trọng điểm"},{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"Tôn trọng"},{"hanzi":"电视","pinyin":"diànshì","vi":"Tivi"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"}],"traditional":"重視"},{"id":"周围","hanzi":"周围","pinyin":"zhōuwéi","meaning_vi":"xung quanh","explanation":"周 (vòng quanh) + 围 (bao bọc).","hsk_level":3,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"🔄","examples":[{"type":"basic","zh":"我们学校周围环境很安静。","pinyin":"Wǒmen xuéxiào zhōuwéi huánjìng hěn ānjìng.","vi":"Môi trường xung quanh trường học của chúng tôi rất yên tĩnh."},{"type":"simple","zh":"我家小区周围不仅有大型超市和医院，还有好几个漂亮的公园。","pinyin":"Wǒ jiā xiǎoqū zhōuwéi bùjǐn yǒu dàxíng chāoshì hé yīyuàn, háiyǒu hǎojǐ ge piàoliang de gōngyuán.","vi":"Xung quanh khu chung cư nhà tôi không chỉ có siêu thị lớn và bệnh viện mà còn có mấy công viên rất đẹp."},{"type":"compound","zh":"在陌生的环境里行走时，我们要时刻留意周围的交通情况，确保自身安全。","pinyin":"Zài mòshēng de huánjìng lǐ xíngzǒu shí, wǒmen yào shíkè liúyì zhōuwéi de jiāotōng qíngkuàng, quèbǎo zìshēn ānquán.","vi":"Khi đi lại ở môi trường xa lạ, chúng ta cần luôn để ý tình hình giao thông xung quanh để đảm bảo an toàn cho bản thân."}],"related":[{"hanzi":"附近","pinyin":"fùjìn","vi":"Lân cận"},{"hanzi":"旁边","pinyin":"pángbiān","vi":"Bên cạnh"},{"hanzi":"周末","pinyin":"zhōumò","vi":"Cuối tuần"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"}],"traditional":"周圍"},{"id":"主意","hanzi":"主意","pinyin":"zhǔyi","meaning_vi":"ý, ý tưởng, chủ ý","explanation":"主 (chính) + 意 (ý).","hsk_level":3,"tags":["danh-tu"],"image":"💡","examples":[{"type":"basic","zh":"这个主意真不错！","pinyin":"Zhè ge zhǔyi zhēn búcuò!","vi":"Ý tưởng này hay thật đấy!"},{"type":"simple","zh":"周末去郊区公园野餐的主意是小王提出来的，大家都觉得非常好。","pinyin":"Zhōumò qù jiāoqū gōngyuán yěcān de zhǔyi shì xiǎo Wáng tí chūlái de, dàjiā dōu juéde fēicháng hǎo.","vi":"Ý tưởng cuối tuần đi dã ngoại ở công viên ngoại ô là do Tiểu Vương đề xuất, mọi người đều thấy rất tuyệt."},{"type":"compound","zh":"如果你现在拿不定主意到底选哪个专业，不妨去听听王教授的建议。","pinyin":"Rúguǒ nǐ xiànzài ná búdìng zhǔyi dàodǐ xuǎn nǎ ge zhuānyè, bùfáng qù tīng ting Wáng jiàoshòu de jiànyì.","vi":"Nếu hiện tại bạn chưa quyết định được rốt cuộc nên chọn chuyên ngành nào thì chi bằng đi nghe lời khuyên của giáo sư Vương xem sao."}],"related":[{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"建议","pinyin":"jiànyì","vi":"Đề nghị"},{"hanzi":"注意","pinyin":"zhùyì","vi":"Chú ý"},{"hanzi":"主要","pinyin":"zhǔyào","vi":"Chủ yếu"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"Biện pháp"}]},{"id":"祝贺","hanzi":"祝贺","pinyin":"zhùhè","meaning_vi":"chúc mừng","explanation":"祝 (cầu chúc) + 贺 (mừng).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🎊","examples":[{"type":"basic","zh":"祝贺你取得好成绩！","pinyin":"Zhùhè nǐ qǔdé hǎo chéngjì!","vi":"Chúc mừng bạn đã đạt thành tích tốt!"},{"type":"simple","zh":"听到好朋友顺利通过博士论文答辩的消息，我们大家都向他表示祝贺。","pinyin":"Tīngdào hǎopéngyou shùnlì tōngguò bóshì lùnwén dábiàn de xiāoxi, wǒmen dàjiā dōu xiàng tā biǎoshì zhùhè.","vi":"Nghe tin bạn thân bảo vệ thành công luận án tiến sĩ, tất cả chúng tôi đều gửi lời chúc mừng tới anh ấy."},{"type":"compound","zh":"今天是你们公司成立十周年的大喜日子，我代表全体同事向你们表示热烈祝贺！","pinyin":"Jīntiān shì nǐmen gōngsī chénglì shí zhōunián de dàxǐ rìzi, wǒ dàibiǎo quántǐ tóngshì xiàng nǐmen biǎoshì rèliè zhùhè!","vi":"Hôm nay là ngày vui lớn kỷ niệm 10 năm thành lập công ty các bạn, tôi xin đại diện toàn thể đồng nghiệp nhiệt liệt chúc mừng!"}],"related":[{"hanzi":"祝","pinyin":"zhù","vi":"Chúc"},{"hanzi":"祝福","pinyin":"zhùfú","vi":"Chúc phúc"},{"hanzi":"庆祝","pinyin":"qìngzhù","vi":"Chúc mừng"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"}],"traditional":"祝賀"},{"id":"著名","hanzi":"著名","pinyin":"zhùmíng","meaning_vi":"nổi tiếng, trứ danh","explanation":"著 (nổi bật) + 名 (tên tuổi). Đồng nghĩa với 有名.","hsk_level":3,"tags":["tinh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"李白是中国著名的诗人。","pinyin":"Lǐbái shì Zhōngguó zhùmíng de shīrén.","vi":"Lý Bạch là nhà thơ nổi tiếng của Trung Quốc."},{"type":"simple","zh":"北京烤鸭是一道享誉世界的中国著名美食，几乎每个游客都会品尝。","pinyin":"Běijīngkǎoyā shì yídào xiǎngyù shìjiè de Zhōngguó zhùmíng měishí, jīhū měi ge yóukè dōuhuì pǐncháng.","vi":"Vịt quay Bắc Kinh là món ngon nổi tiếng thế giới của Trung Quốc, hầu như du khách nào cũng nếm thử."},{"type":"compound","zh":"虽然这座小城面积不大，但是因为出过许多著名作家而吸引了大量文学爱好者。","pinyin":"Suīrán zhè zuò xiǎochéng miànjī búdà, dànshì yīnwèi chūguo xǔduō zhùmíng zuòjiā ér xīyǐnle dàliàng wénxué àihàozhě.","vi":"Tuy thành phố nhỏ này diện tích không lớn nhưng vì từng sản sinh ra nhiều nhà văn nổi tiếng nên đã thu hút đông đảo người yêu văn học."}],"related":[{"hanzi":"有名","pinyin":"yǒumíng","vi":"Nổi tiếng"},{"hanzi":"名字","pinyin":"míngzi","vi":"Tên"},{"hanzi":"作家","pinyin":"zuòjiā","vi":"Nhà văn"},{"hanzi":"教授","pinyin":"jiàoshòu","vi":"Giáo sư"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"Diễn viên"}]},{"id":"专门","hanzi":"专门","pinyin":"zhuānmén","meaning_vi":"chuyên, chuyên biệt; riêng, cố ý (dành riêng)","explanation":"专 (chuyên) + 门 (ngành/cửa).","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"这是专门为你准备的礼物。","pinyin":"Zhè shì zhuānmén wèi nǐ zhǔnbèi de lǐwù.","vi":"Đây là món quà chuẩn bị dành riêng cho bạn."},{"type":"simple","zh":"这家书店专门出售各种外语学习词典和留学考试辅导书籍。","pinyin":"Zhè jiāshū diàn zhuānmén chūshòu gèzhǒng wàiyǔ xuéxí cídiǎn hé liúxué kǎoshì fǔdǎo shūjí.","vi":"Hiệu sách này chuyên bán các loại từ điển học ngoại ngữ và sách ôn luyện thi du học."},{"type":"compound","zh":"为了庆祝妈妈的生日，爸爸今天下午专门请假回家做了一桌丰盛的晚餐。","pinyin":"Wèile qìngzhù māma de shēngrì, bàba jīntiān xiàwǔ zhuānmén qǐngjià huíjiā zuòle yì zhuō fēngshèng de wǎncān.","vi":"Để mừng sinh nhật mẹ, chiều nay bố đã đặc biệt xin nghỉ phép về nhà nấu một bàn tiệc tối thịnh soạn."}],"related":[{"hanzi":"专业","pinyin":"zhuānyè","vi":"Chuyên ngành"},{"hanzi":"专家","pinyin":"zhuānjiā","vi":"Chuyên gia"},{"hanzi":"门","pinyin":"mén","vi":"Cửa/Ngành"},{"hanzi":"特别","pinyin":"tèbié","vi":"Đặc biệt"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"Chuẩn bị"}],"traditional":"專門"},{"id":"专业","hanzi":"专业","pinyin":"zhuānyè","meaning_vi":"chuyên ngành; chuyên nghiệp","explanation":"专 (chuyên – chuyên về một thứ) + 业 (nghiệp – nghề, việc học) → ngành học chuyên sâu; làm tính từ nghĩa là chuyên nghiệp. Ví dụ 你学什么专业？","hsk_level":3,"tags":["danh-tu","tinh-tu","hoc-tap","cong-viec"],"image":"🎓","examples":[{"type":"basic","zh":"你在大学学的是什么专业？","pinyin":"Nǐ zài dàxué xué de shì shénme zhuānyè?","vi":"Ở đại học bạn học chuyên ngành gì?"},{"type":"simple","zh":"我妹妹非常喜欢中国文化，所以她大学选择了汉语言文学专业。","pinyin":"Wǒ mèimei fēicháng xǐhuan Zhōngguó wénhuà, suǒyǐ tā dàxué xuǎnzéle hàn yǔyán wénxué zhuānyè.","vi":"Em gái tôi vô cùng thích văn hóa Trung Quốc nên ở đại học em ấy đã chọn chuyên ngành Ngôn ngữ và Văn học Hán."},{"type":"compound","zh":"这位修车师傅不仅态度热情，而且技术非常专业，很快就找出了故障原因。","pinyin":"Zhè wèi xiūchē shīfu bùjǐn tàidù rèqíng, érqiě jìshù fēicháng zhuānyè, hěn kuài jiù zhǎochūle gùzhàng yuányīn.","vi":"Bác thợ sửa xe này không chỉ thái độ nhiệt tình mà tay nghề cũng rất chuyên nghiệp, nhanh chóng tìm ra nguyên nhân hỏng hóc."}],"related":[{"hanzi":"专门","pinyin":"zhuānmén","vi":"Chuyên môn"},{"hanzi":"职业","pinyin":"zhíyè","vi":"Nghề nghiệp"},{"hanzi":"毕业","pinyin":"bìyè","vi":"Tốt nghiệp"},{"hanzi":"大学","pinyin":"dàxué","vi":"Đại học"},{"hanzi":"能力","pinyin":"nénglì","vi":"Năng lực"}],"traditional":"專業"},{"id":"转","hanzi":"转","pinyin":"zhuǎn","meaning_vi":"rẽ, chuyển, xoay","explanation":"Bộ xa 车 + 专. Dùng trong 转弯 (rẽ ngoặt), 转告 (chuyển lời).","hsk_level":3,"tags":["dong-tu"],"image":"↪️","examples":[{"type":"basic","zh":"前面十字路口请往左转。","pinyin":"Qiánmiàn shízìlùkǒu qǐng wǎng zuǒzhuǎn.","vi":"Ngã tư phía trước xin hãy rẽ sang trái."},{"type":"simple","zh":"昨天还下着冷雨，今天早上天气突然转晴，太阳也出来了。","pinyin":"Zuótiān hái xiàzhe lěng yǔ, jīntiān zǎoshang tiānqì tūrán zhuǎn qíng, tàiyáng yě chūlái le.","vi":"Hôm qua trời vẫn còn mưa lạnh, sáng nay thời tiết đột nhiên chuyển nắng và mặt trời cũng mọc rồi."},{"type":"compound","zh":"王老师现在正在教室里上课，你把文件留在这里，等他下课后我帮你转交给他。","pinyin":"Wáng lǎoshī xiànzài zhèngzài jiàoshì lǐ shàngkè, nǐ bǎ wénjiàn liú zài zhèlǐ, děng tā xiàkè hòu wǒ bāng nǐ zhuǎnjiāo gěi tā.","vi":"Thầy Vương hiện đang giảng bài trong lớp, bạn cứ để tài liệu ở đây, đợi thầy tan học tôi sẽ chuyển giúp cho thầy."}],"related":[{"hanzi":"转弯","pinyin":"zhuǎnwān","vi":"Rẽ ngoặt"},{"hanzi":"变化","pinyin":"biànhuà","vi":"Thay đổi"},{"hanzi":"晴","pinyin":"qíng","vi":"Nắng"},{"hanzi":"往","pinyin":"wǎng","vi":"Về phía"},{"hanzi":"交","pinyin":"jiāo","vi":"Giao"}],"traditional":"轉"},{"id":"赚","hanzi":"赚","pinyin":"zhuàn","meaning_vi":"kiếm (tiền)","explanation":"Bộ bối 贝 (tiền) + 兼. Cụm: 赚钱 (kiếm tiền).","hsk_level":3,"tags":["dong-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他做生意赚了很多钱。","pinyin":"Tā zuòshēngyi zhuànle hěn duō qián.","vi":"Anh ấy làm kinh doanh kiếm được rất nhiều tiền."},{"type":"simple","zh":"我哥哥大学毕业后开了一家网店，现在每个月都能赚不少钱。","pinyin":"Wǒ gēge dàxué bìyè hòu kāile yìjiā wǎngdiàn, xiànzài měi geyuè dōu néng zhuàn bùshǎo qián.","vi":"Anh trai tôi sau khi tốt nghiệp đại học đã mở một cửa hàng trực tuyến, hiện mỗi tháng đều kiếm được không ít tiền."},{"type":"compound","zh":"虽然赚钱改善生活很重要，但是我们千万不能为了赚钱而忽略了身体健康。","pinyin":"Suīrán zhuànqián gǎishàn shēnghuó hěn zhòngyào, dànshì wǒmen qiānwàn bù néng wèile zhuànqián ér hūlüèle shēntǐ jiànkāng.","vi":"Tuy kiếm tiền cải thiện cuộc sống rất quan trọng nhưng chúng ta tuyệt đối không được vì kiếm tiền mà lơ là sức khỏe."}],"related":[{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"生意","pinyin":"shēngyi","vi":"Kinh doanh"},{"hanzi":"工资","pinyin":"gōngzī","vi":"Tiền lương"},{"hanzi":"收入","pinyin":"shōurù","vi":"Thu nhập"},{"hanzi":"花钱","pinyin":"huāqián","vi":"Tiêu tiền"}],"traditional":"賺"},{"id":"准确","hanzi":"准确","pinyin":"zhǔnquè","meaning_vi":"chính xác","explanation":"准 (chuẩn) + 确 (đúng).","hsk_level":3,"tags":["tinh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"你的发音非常准确。","pinyin":"Nǐ de fāyīn fēicháng zhǔnquè.","vi":"Phát âm của bạn vô cùng chính xác."},{"type":"simple","zh":"为了保证新闻报道的真实性，记者在写稿前必须核对所有数据的准确性。","pinyin":"Wèile bǎozhèng xīnwén bàodào de zhēnshí xìng, jìzhě zài xiě gǎo qián bìxū héduì suǒyǒu shùjù de zhǔnquèxìng.","vi":"Để đảm bảo tính chân thực của bản tin, phóng viên trước khi viết bài bắt buộc phải đối chiếu độ chính xác của mọi số liệu."},{"type":"compound","zh":"虽然他学汉语的时间还不长，但是在对话中已经能够非常准确地使用生词了。","pinyin":"Suīrán tā xué Hànyǔ de shíjiān hái bù cháng, dànshì zài duìhuà zhōng yǐjīng nénggòu fēicháng zhǔnquè de shǐyòng shēngcí le.","vi":"Tuy thời gian anh ấy học tiếng Trung chưa lâu nhưng trong hội thoại đã có thể dùng từ mới một cách vô cùng chính xác."}],"related":[{"hanzi":"正确","pinyin":"zhèngquè","vi":"Đúng đắn"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"确实","pinyin":"quèshí","vi":"Quả thực"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"}],"traditional":"準確"},{"id":"准时","hanzi":"准时","pinyin":"zhǔnshí","meaning_vi":"đúng giờ","explanation":"准 (chuẩn) + 时 (giờ).","hsk_level":3,"tags":["tinh-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"火车准时到达了北京站。","pinyin":"Huǒchē zhǔnshí dàodále Běijīng zhàn.","vi":"Tàu hỏa đã đến ga Bắc Kinh đúng giờ."},{"type":"simple","zh":"小王是一个非常守信用的人，每次跟朋友约会都准时到达，从不迟到。","pinyin":"Xiǎo Wáng shì yí ge fēicháng shǒuxìnyòng de rén, měi cì gēn péngyou yuēhuì dōu zhǔnshí dàodá, cóng bù chídào.","vi":"Tiểu Vương là người rất giữ chữ tín, mỗi lần hẹn hò với bạn bè đều đến đúng giờ, chưa bao giờ đi muộn."},{"type":"compound","zh":"因为今天早上天气晴朗、交通顺畅，所以所有航班都按照计划准时起飞了。","pinyin":"Yīnwèi jīntiān zǎoshang tiānqì qínglǎng, jiāotōng shùnchàng, suǒyǐ suǒyǒu hángbān dōu ànzhào jìhuà zhǔnshí qǐfēi le.","vi":"Vì sáng nay thời tiết quang đãng, giao thông thông suốt nên tất cả chuyến bay đều cất cánh đúng giờ theo kế hoạch."}],"related":[{"hanzi":"准确","pinyin":"zhǔnquè","vi":"Chính xác"},{"hanzi":"迟到","pinyin":"chídào","vi":"Đến muộn"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"及时","pinyin":"jíshí","vi":"Kịp thời"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"Chuẩn bị"}],"traditional":"準時"},{"id":"仔细","hanzi":"仔细","pinyin":"zǐxì","meaning_vi":"cẩn thận, tỉ mỉ","explanation":"仔 + 细 (nhỏ nhặt/kỹ lưỡng).","hsk_level":3,"tags":["tinh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"做作业一定要仔细。","pinyin":"Zuò zuòyè yídìngyào zǐxì.","vi":"Làm bài tập nhất định phải cẩn thận."},{"type":"simple","zh":"老师让我们交卷之前再仔细检查一遍，看看有没有漏写的题目。","pinyin":"Lǎoshī ràng wǒmen jiāojuàn zhīqián zài zǐxì jiǎnchá yíbiàn, kànkan yǒuméiyǒu lòu xiě de tímù.","vi":"Thầy giáo bảo chúng tôi trước khi nộp bài hãy kiểm tra kỹ lại một lượt xem có câu nào viết sót không."},{"type":"compound","zh":"只要你仔细观察就会发现，很多汉字的偏旁都和它的意思有密切关系。","pinyin":"Zhǐyào nǐ zǐxì guānchá jiù huì fāxiàn, hěn duō hànzì de piānpáng dōu hé tā de yìsi yǒu mìqiè guānxi.","vi":"Chỉ cần bạn quan sát tỉ mỉ sẽ phát hiện ra rằng bộ thủ của nhiều chữ Hán đều có mối liên hệ mật thiết với ý nghĩa của nó."}],"related":[{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"马虎","pinyin":"mǎhu","vi":"Qua loa"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"},{"hanzi":"详细","pinyin":"xiángxì","vi":"Chi tiết"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"Kiểm tra"}],"traditional":"仔細"},{"id":"自然","hanzi":"自然","pinyin":"zìrán","meaning_vi":"tự nhiên, thiên nhiên","explanation":"自 (tự thân) + 然 (như vậy).","hsk_level":3,"tags":["danh-tu","tinh-tu"],"image":"🌿","examples":[{"type":"basic","zh":"我们要保护大自然。","pinyin":"Wǒmen yào bǎohù dàzìrán.","vi":"Chúng ta phải bảo vệ thiên nhiên."},{"type":"simple","zh":"这位年轻演员在舞台上的表演非常自然，一点儿也不显得紧张。","pinyin":"Zhè wèi niánqīng yǎnyuán zài wǔtái shang de biǎoyǎn fēicháng zìrán, yìdiǎnr yě bù xiǎnde jǐnzhāng.","vi":"Diễn xuất trên sân khấu của diễn viên trẻ này rất tự nhiên, không hề tỏ ra căng thẳng chút nào."},{"type":"compound","zh":"周末离开喧闹的城市，去森林公园里呼吸新鲜空气、亲近大自然让人特别放松。","pinyin":"Zhōumò líkāi xuānnào de chéngshì, qù sēnlín gōngyuán lǐ hūxī xīnxiān kōngqì, qīnjìn dàzìrán ràng rén tèbié fàngsōng.","vi":"Cuối tuần rời khỏi thành phố ồn ào, đến công viên rừng hít thở không khí trong lành và gần gũi thiên nhiên khiến người ta đặc biệt thư giãn."}],"related":[{"hanzi":"自己","pinyin":"zìjǐ","vi":"Tự mình"},{"hanzi":"当然","pinyin":"dāngrán","vi":"Đương nhiên"},{"hanzi":"森林","pinyin":"sēnlín","vi":"Rừng rậm"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"植物","pinyin":"zhíwù","vi":"Thực vật"}]},{"id":"自信","hanzi":"自信","pinyin":"zìxìn","meaning_vi":"tự tin","explanation":"自 (bản thân) + 信 (tin tưởng).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😎","examples":[{"type":"basic","zh":"她是一个非常自信的女孩。","pinyin":"Tā shì yí ge fēicháng zìxìn de nǚhái.","vi":"Cô ấy là một cô gái vô cùng tự tin."},{"type":"simple","zh":"站在演讲台上时，他声音洪亮、表情自然，显得非常自信。","pinyin":"Zhàn zài yǎn jiǎngtái shang shí, tā shēngyīn hóngliàng, biǎoqíng zìrán, xiǎnde fēicháng zìxìn.","vi":"Khi đứng trên bục diễn thuyết, giọng nói của anh ấy vang dội, biểu cảm tự nhiên, tỏ ra vô cùng tự tin."},{"type":"compound","zh":"只要平时积累了丰富的知识并做好充分准备，面对任何挑战我们都能充满自信。","pinyin":"Zhǐyào píngshí jīlěile fēngfù de zhīshi bìng zuò hǎo chōngfèn zhǔnbèi, miànduì rènhé tiǎozhàn wǒmen dōu néng chōngmǎn zìxìn.","vi":"Chỉ cần ngày thường tích lũy kiến thức phong phú và chuẩn bị đầy đủ thì trước mọi thử thách chúng ta đều có thể tràn đầy tự tin."}],"related":[{"hanzi":"信心","pinyin":"xìnxīn","vi":"Lòng tin"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"自己","pinyin":"zìjǐ","vi":"Bản thân"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"Ngại ngùng"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"Dũng cảm"}]},{"id":"总结","hanzi":"总结","pinyin":"zǒngjié","meaning_vi":"tổng kết","explanation":"总 (tổng hợp) + 结 (kết lại). Vừa là động từ vừa là danh từ.","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"我们今天总结一下学过的内容。","pinyin":"Wǒmen jīntiān zǒngjié yíxià xuéguo de nèiróng.","vi":"Hôm nay chúng ta tổng kết lại một chút nội dung đã học."},{"type":"simple","zh":"每个月月底，公司各部门都会开会总结这个月的工作。","pinyin":"Měi geyuè yuèdǐ, gōngsī gè bùmén dōuhuì kāihuì zǒngjié zhè geyuè de gōngzuò.","vi":"Cuối mỗi tháng, các phòng ban của công ty đều họp để tổng kết công việc trong tháng."},{"type":"compound","zh":"无论是成功还是失败，只要我们善于总结经验，就能在未来的道路上走得更远。","pinyin":"Wúlùn shì chénggōng háishi shībài, zhǐyào wǒmen shànyú zǒngjié jīngyàn, jiù néng zài wèilái de dào lùshang zǒu de gèng yuǎn.","vi":"Dù là thành công hay thất bại, chỉ cần chúng ta biết tổng kết kinh nghiệm thì sẽ tiến xa hơn trên con đường tương lai."}],"related":[{"hanzi":"总是","pinyin":"zǒngshì","vi":"Luôn luôn"},{"hanzi":"结束","pinyin":"jiéshù","vi":"Kết thúc"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"Kinh nghiệm"},{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"}],"traditional":"總結"},{"id":"租","hanzi":"租","pinyin":"zū","meaning_vi":"thuê","explanation":"Bộ hòa 禾 + 且. Dùng trong 租房子 (thuê nhà), 租车 (thuê xe).","hsk_level":3,"tags":["dong-tu","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"我在学校附近租了一套房子。","pinyin":"Wǒ zài xuéxiào fùjìn zūle yítào fángzi.","vi":"Tôi đã thuê một căn nhà ở gần trường học."},{"type":"simple","zh":"这套一室一厅的房子离地铁站只有五分钟路程，每个月房租两千元。","pinyin":"Zhè tào yí shì yì tīng de fángzi lí dìtiězhàn zhǐyǒu wǔ fēnzhōng lùchéng, měi geyuè fángzū liǎng qiān yuán.","vi":"Căn hộ một phòng ngủ một phòng khách này cách ga tàu điện ngầm chỉ 5 phút đi bộ, tiền thuê mỗi tháng 2.000 tệ."},{"type":"compound","zh":"去海边旅游的时候，我们租了两辆自行车沿着海岸线骑行，风景美极了。","pinyin":"Qù hǎibiān lǚyóu de shíhou, wǒmen zūle liǎng liàng zìxíngchē yánzhe hǎi'ànxiàn qíxíng, fēngjǐng měi jíle.","vi":"Lúc đi du lịch bờ biển, chúng tôi đã thuê hai chiếc xe đạp đạp dọc bờ biển, phong cảnh đẹp tuyệt vời."}],"related":[{"hanzi":"出租车","pinyin":"chūzūchē","vi":"Xe taxi"},{"hanzi":"房东","pinyin":"fángdōng","vi":"Chủ nhà"},{"hanzi":"房子","pinyin":"fángzi","vi":"Ngôi nhà"},{"hanzi":"借","pinyin":"jiè","vi":"Mượn"},{"hanzi":"搬","pinyin":"bān","vi":"Chuyển nhà"}]},{"id":"最好","hanzi":"最好","pinyin":"zuìhǎo","meaning_vi":"tốt nhất (nên)","explanation":"最 (nhất) + 好 (tốt). Phó từ đưa ra lời khuyên.","hsk_level":3,"tags":["pho-tu"],"image":"👍","examples":[{"type":"basic","zh":"外面冷，你最好多穿件衣服。","pinyin":"Wàimiàn lěng, nǐ zuìhǎo duō chuān jiàn yīfu.","vi":"Bên ngoài lạnh đấy, tốt nhất bạn nên mặc thêm chiếc áo."},{"type":"simple","zh":"明天上午八点有重要考试，你今天晚上最好十点以前就睡觉。","pinyin":"Míngtiān shàngwǔ bā diǎn yǒu zhòngyào kǎoshì, nǐ jīntiān wǎnshang zuìhǎo shí diǎn yǐqián jiù shuìjiào.","vi":"8 giờ sáng mai có kỳ thi quan trọng, tốt nhất tối nay bạn nên đi ngủ trước 10 giờ."},{"type":"compound","zh":"去热门城市旅游之前，最好提前在网上把机票和宾馆预订好，以免临时涨价。","pinyin":"Qù rèmén chéngshì lǚyóu zhīqián, zuìhǎo tíqián zài wǎngshang bǎ jīpiào hé bīnguǎn yùdìng hǎo, yǐmiǎn línshí zhǎngjià.","vi":"Trước khi đi du lịch các thành phố nổi tiếng, tốt nhất nên đặt trước vé máy bay và khách sạn trên mạng để tránh tăng giá đột xuất."}],"related":[{"hanzi":"最","pinyin":"zuì","vi":"Nhất"},{"hanzi":"好","pinyin":"hǎo","vi":"Tốt"},{"hanzi":"建议","pinyin":"jiànyì","vi":"Đề nghị"},{"hanzi":"应该","pinyin":"yīnggāi","vi":"Nên"},{"hanzi":"提前","pinyin":"tíqián","vi":"Trước thời hạn"}]},{"id":"尊重","hanzi":"尊重","pinyin":"zūnzhòng","meaning_vi":"tôn trọng","explanation":"尊 (kính trọng) + 重 (coi trọng).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"我们要尊重老人和老师。","pinyin":"Wǒmen yào zūnzhòng lǎorén hé lǎoshī.","vi":"Chúng ta phải tôn trọng người lớn tuổi và thầy cô giáo."},{"type":"simple","zh":"在国际交流中，尊重不同国家的文化习俗是建立友谊的基础。","pinyin":"Zài Guójì jiāoliú zhōng, zūnzhòng bùtóng guójiā de wénhuà xísú shì jiànlì yǒuyì de jīchǔ.","vi":"Trong giao lưu quốc tế, tôn trọng phong tục văn hóa của các quốc gia khác nhau là nền tảng để xây dựng tình hữu nghị."},{"type":"compound","zh":"只有学会尊重别人的意见和选择，我们才能赢得别人对自己的尊重。","pinyin":"Zhǐyǒu xuéhuì zūnzhòng biérén de yìjiàn hé xuǎnzé, wǒmen cáinéng yíngdé biérén duì zìjǐ de zūnzhòng.","vi":"Chỉ có học cách tôn trọng ý kiến và lựa chọn của người khác thì chúng ta mới giành được sự tôn trọng của họ dành cho mình."}],"related":[{"hanzi":"重视","pinyin":"zhòngshì","vi":"Coi trọng"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"Thấu hiểu"},{"hanzi":"赢","pinyin":"yíng","vi":"Giành được"},{"hanzi":"文化","pinyin":"wénhuà","vi":"Văn hóa"}]},{"id":"左右","hanzi":"左右","pinyin":"zuǒyòu","meaning_vi":"khoảng chừng, trái phải","explanation":"左 (trái) + 右 (phải). Đứng sau con số chỉ ước lượng (十点左右).","hsk_level":3,"tags":["danh-tu","so-luong","phuong-huong"],"image":"↔️","examples":[{"type":"basic","zh":"现在大概十点左右。","pinyin":"Xiànzài dàgài shí diǎn zuǒyòu.","vi":"Bây giờ khoảng chừng 10 giờ."},{"type":"simple","zh":"从我家坐地铁去市中心，路上一般需要三十分钟左右。","pinyin":"Cóng wǒ jiā zuò dìtiě qù shìzhōngxīn, lùshang yìbān xūyào sānshí fēnzhōng zuǒyòu.","vi":"Đi tàu điện ngầm từ nhà tôi tới trung tâm thành phố thường mất khoảng chừng 30 phút."},{"type":"compound","zh":"过马路的时候一定要先往左右两边看看有没有来往车辆，确保安全再走。","pinyin":"Guòmǎlù de shíhou yídìngyào xiān wǎng zuǒyòu liǎngbiān kànkan yǒuméiyǒu láiwǎng chēliàng, quèbǎo ānquán zài zǒu.","vi":"Khi sang đường nhất định phải nhìn hai bên trái phải xem có xe cộ qua lại không, đảm bảo an toàn rồi mới đi."}],"related":[{"hanzi":"大约","pinyin":"dàyuē","vi":"Ước chừng"},{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"左边","pinyin":"zuǒbiān","vi":"Bên trái"},{"hanzi":"右边","pinyin":"yòubiān","vi":"Bên phải"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"}]},{"id":"作家","hanzi":"作家","pinyin":"zuòjiā","meaning_vi":"nhà văn","explanation":"作 (sáng tác) + 家 (chuyên gia).","hsk_level":3,"tags":["danh-tu","nghe-nghiep"],"image":"✍️","examples":[{"type":"basic","zh":"他是一位著名的中国作家。","pinyin":"Tā shì yí wèi zhùmíng de Zhōngguó zuòjiā.","vi":"Ông ấy là một nhà văn nổi tiếng của Trung Quốc."},{"type":"simple","zh":"这位作家写了很多反映普通人日常生活的优秀长篇小说。","pinyin":"Zhè wèi zuòjiā xiěle hěn duō fǎnyìng pǔtōngrén rìcháng shēnghuó de yōuxiù chángpiān xiǎoshuō.","vi":"Nhà văn này đã viết rất nhiều tiểu thuyết dài tập xuất sắc phản ánh đời sống thường nhật của người dân bình thường."},{"type":"compound","zh":"因为她从小就热爱阅读和写作，所以长大后终于实现了当一名作家的理想。","pinyin":"Yīnwèi tā cóngxiǎo jiù rè'ài yuèdú hé xiězuò, suǒyǐ zhǎngdà hòu zhōngyú shíxiàn ledāng yì míng zuòjiā de lǐxiǎng.","vi":"Vì từ nhỏ cô ấy đã đam mê đọc sách và viết lách nên khi lớn lên cuối cùng đã thực hiện được lý tưởng làm nhà văn."}],"related":[{"hanzi":"作者","pinyin":"zuòzhě","vi":"Tác giả"},{"hanzi":"小说","pinyin":"xiǎoshuō","vi":"Tiểu thuyết"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"Bài văn"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"Nổi tiếng"},{"hanzi":"职业","pinyin":"zhíyè","vi":"Nghề nghiệp"}]},{"id":"作用","hanzi":"作用","pinyin":"zuòyòng","meaning_vi":"tác dụng","explanation":"作 (làm) + 用 (dùng).","hsk_level":3,"tags":["danh-tu"],"image":"⚙️","examples":[{"type":"basic","zh":"运动对健康有很大的作用。","pinyin":"Yùndòng duì jiànkāng yǒu hěn dà de zuòyòng.","vi":"Vận động có tác dụng rất lớn đối với sức khỏe."},{"type":"simple","zh":"森林在净化空气、保护水土和调节气候方面发挥着重要作用。","pinyin":"Sēnlín zài jìnghuà kōngqì, bǎohù shuǐtǔ hé tiáojié qìhòu fāngmiàn fāhuīzhe zhòngyào zuòyòng.","vi":"Rừng đóng vai trò quan trọng trong việc thanh lọc không khí, giữ đất giữ nước và điều hòa khí hậu."},{"type":"compound","zh":"虽然这本词典体积很小，但是在日常汉语学习中却起到了不可或缺的作用。","pinyin":"Suīrán zhè běn cídiǎn tǐjī hěn xiǎo, dànshì zài rìcháng Hànyǔ xuéxí zhōng què qǐdàole bùkě huòquē de zuòyòng.","vi":"Tuy cuốn từ điển này kích thước rất nhỏ nhưng trong việc học tiếng Trung hằng ngày lại phát huy tác dụng không thể thiếu."}],"related":[{"hanzi":"使用","pinyin":"shǐyòng","vi":"Sử dụng"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"Hiệu quả"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"重要","pinyin":"zhòngyào","vi":"Quan trọng"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"}]},{"id":"作者","hanzi":"作者","pinyin":"zuòzhě","meaning_vi":"tác giả","explanation":"作 (sáng tác) + 者 (người).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"你知道这本书的作者是谁吗？","pinyin":"Nǐ zhīdao zhè běn shū de zuòzhě shì shéi ma?","vi":"Bạn có biết tác giả của quyển sách này là ai không?"},{"type":"simple","zh":"这篇文章的作者用幽默风趣的语言讲述了自己在中国留学的趣事。","pinyin":"Zhè piān wénzhāng de zuòzhě yòng yōumò fēngqù de yǔyán jiǎngshùle zìjǐ zài Zhōngguó liúxué de qùshì.","vi":"Tác giả của bài văn này đã dùng ngôn ngữ hài hước dí dỏm kể lại những chuyện thú vị khi du học ở Trung Quốc."},{"type":"compound","zh":"虽然这本书出版于一百年前，但是作者在书中表达的思想至今依然很有意义。","pinyin":"Suīrán zhè běn shū chūbǎn yú yī bǎi niánqián, dànshì zuòzhě zài shū zhōng biǎodá de sīxiǎng zhìjīn yīrán hěn yǒuyìyì.","vi":"Tuy quyển sách này được xuất bản từ một trăm năm trước nhưng tư tưởng tác giả thể hiện trong sách đến nay vẫn rất có ý nghĩa."}],"related":[{"hanzi":"作家","pinyin":"zuòjiā","vi":"Nhà văn"},{"hanzi":"记者","pinyin":"jìzhě","vi":"Nhà báo"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"Bài văn"},{"hanzi":"小说","pinyin":"xiǎoshuō","vi":"Tiểu thuyết"},{"hanzi":"书","pinyin":"shū","vi":"Sách"}]},{"id":"座","hanzi":"座","pinyin":"zuò","meaning_vi":"tòa, ngọn (lượng từ)","explanation":"Lượng từ cho núi, cầu, tòa nhà (一座山, 一座桥).","hsk_level":3,"tags":["luong-tu","dia-diem"],"image":"⛰️","examples":[{"type":"basic","zh":"城市中心有一座大公园。","pinyin":"Chéngshì zhōngxīn yǒu yí zuò dàgōng yuán.","vi":"Trung tâm thành phố có một công viên lớn."},{"type":"simple","zh":"北京是一座既有古老历史文化、又充满现代气息的国际化大都市。","pinyin":"Běijīng shì yí zuò jìyǒu gǔlǎo lìshǐ wénhuà, yòu chōngmǎn xiàndài qìxī de guójìhuà dàdūshì.","vi":"Bắc Kinh là một đô thị quốc tế lớn vừa mang văn hóa lịch sử cổ kính vừa tràn ngập hơi thở hiện đại."},{"type":"compound","zh":"为了欣赏日出，我们凌晨四点就开始爬这座高山，终于在六点登上了山顶。","pinyin":"Wèile xīnshǎng rìchū, wǒmen língchén sì diǎn jiù kāishǐ pá zhè zuò gāoshān, zhōngyú zài liù diǎn dēngshàngle shāndǐng.","vi":"Để ngắm bình minh, chúng tôi bắt đầu leo ngọn núi cao này từ 4 giờ sáng và cuối cùng đã lên tới đỉnh núi lúc 6 giờ."}],"related":[{"hanzi":"座位","pinyin":"zuòwèi","vi":"Chỗ ngồi"},{"hanzi":"坐","pinyin":"zuò","vi":"Ngồi"},{"hanzi":"桥","pinyin":"qiáo","vi":"Cây cầu"},{"hanzi":"山","pinyin":"shān","vi":"Núi"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"}]},{"id":"座位","hanzi":"座位","pinyin":"zuòwèi","meaning_vi":"chỗ ngồi","explanation":"座 (ngồi) + 位 (vị trí).","hsk_level":3,"tags":["danh-tu","giao-thong"],"image":"💺","examples":[{"type":"basic","zh":"请问这里有空座位吗？","pinyin":"Qǐngwèn zhèlǐ yǒukòng zuòwèi ma?","vi":"Xin hỏi ở đây có chỗ ngồi trống không ạ?"},{"type":"simple","zh":"在公共汽车和地铁上，年轻人应该主动给老人和孕妇让座位。","pinyin":"Zài gōnggòngqìchē hé dìtiě shang, niánqīngrén yīnggāi zhǔdòng gěi lǎorén hé yùnfù ràng zuòwèi.","vi":"Trên xe buýt và tàu điện ngầm, người trẻ nên chủ động nhường ghế cho người già và phụ nữ mang thai."},{"type":"compound","zh":"因为周末看电影的人特别多，所以我们提前在网上选好了中间排的座位。","pinyin":"Yīnwèi zhōumò kàndiànyǐng de rén tèbié duō, suǒyǐ wǒmen tíqián zài wǎngshang xuǎn hǎole zhōngjiān pái de zuòwèi.","vi":"Vì cuối tuần người xem phim đặc biệt đông nên chúng tôi đã chọn trước chỗ ngồi hàng giữa trên mạng."}],"related":[{"hanzi":"座","pinyin":"zuò","vi":"Tòa (lượng từ)"},{"hanzi":"坐","pinyin":"zuò","vi":"Ngồi"},{"hanzi":"站","pinyin":"zhàn","vi":"Đứng"},{"hanzi":"空","pinyin":"kōng","vi":"Trống"},{"hanzi":"电影院","pinyin":"diànyǐngyuàn","vi":"Rạp chiếu phim"}]},{"id":"阿姨","hanzi":"阿姨","pinyin":"āyí","meaning_vi":"dì, cô (cách gọi phụ nữ trung niên)","explanation":"Cả hai chữ đều có bộ nữ 女.","hsk_level":3,"tags":["danh-tu","gia-dinh","con-nguoi"],"image":"👩","examples":[{"type":"basic","zh":"王阿姨每天早上都去买菜。","pinyin":"Wáng āyí měitiān zǎo Shangdōu qù mǎicài.","vi":"Cô Vương mỗi sáng đều đi mua thức ăn."},{"type":"simple","zh":"邻居张阿姨非常热情，经常把她自己做的点心拿来给我们品尝。","pinyin":"Línjū Zhāng āyí fēicháng rèqíng, jīngcháng bǎ tā zìjǐ zuò de diǎnxin nálái gěi wǒmen pǐncháng.","vi":"Cô Trương hàng xóm vô cùng nhiệt tình, thường xuyên mang bánh điểm tâm tự làm sang cho chúng tôi nếm thử."},{"type":"compound","zh":"在学校食堂打饭的时候，每次看到阿姨亲切的笑容，我都觉得心里暖暖的。","pinyin":"Zài xuéxiào shítáng dǎfàn de shíhou, měi cì kàndào āyí qīnqiè de xiàoróng, wǒ dōu juéde xīnlǐ Nuǎnnuǎn de.","vi":"Khi lấy cơm ở nhà ăn trường, mỗi lần thấy nụ cười thân thiện của cô nhân viên là tôi lại thấy ấm lòng."}],"related":[{"hanzi":"叔叔","pinyin":"shūshu","vi":"Chú"},{"hanzi":"亲戚","pinyin":"qīnqi","vi":"Họ hàng"},{"hanzi":"邻居","pinyin":"línjū","vi":"Hàng xóm"},{"hanzi":"姐姐","pinyin":"jiějie","vi":"Chị gái"},{"hanzi":"奶奶","pinyin":"nǎinai","vi":"Bà nội"}]},{"id":"爱好","hanzi":"爱好","pinyin":"àihào","meaning_vi":"sở thích","explanation":"爱 (yêu thích) + 好 (đọc hào - ham thích).","hsk_level":3,"tags":["danh-tu","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"我的爱好是看书和旅游。","pinyin":"Wǒ de àihào shì kànshū hé lǚyóu.","vi":"Sở thích của tôi là đọc sách và du lịch."},{"type":"simple","zh":"除了学习专业知识以外，培养一两项健康的兴趣爱好能让生活更丰富。","pinyin":"Chúle xuéxí zhuānyè zhīshi yǐwài, péiyǎng yī liǎng xiàng jiànkāng de xìngqù àihào néng ràng shēnghuó gèng fēngfù.","vi":"Ngoài việc học kiến thức chuyên ngành, rèn luyện một vài sở thích lành mạnh có thể làm cuộc sống phong phú hơn."},{"type":"compound","zh":"虽然我平时的工作压力比较大，但是周末打打羽毛球这个爱好帮我放松了很多。","pinyin":"Suīrán wǒ píngshí de gōngzuò yālì bǐjiào dà, dànshì zhōumò dǎ da yǔmáoqiú zhè ge àihào bāng wǒ fàngsōngle hěn duō.","vi":"Tuy ngày thường áp lực công việc của tôi khá lớn nhưng sở thích đánh cầu lông vào cuối tuần giúp tôi thư giãn rất nhiều."}],"related":[{"hanzi":"爱","pinyin":"ài","vi":"Yêu"},{"hanzi":"喜欢","pinyin":"xǐhuan","vi":"Thích"},{"hanzi":"兴趣","pinyin":"xìngqù","vi":"Hứng thú"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"},{"hanzi":"羽毛球","pinyin":"yǔmáoqiú","vi":"Cầu lông"}],"traditional":"愛好"},{"id":"把","hanzi":"把","pinyin":"bǎ","meaning_vi":"đem, lấy (giới từ câu chữ 把)","explanation":"Dùng trong câu chữ 把 để nhấn mạnh sự tác động lên tân ngữ.","hsk_level":3,"tags":["gioi-tu"],"image":"🤲","examples":[{"type":"basic","zh":"请把门关上。","pinyin":"Qǐng bǎ mén guānshang.","vi":"Xin hãy đóng cửa lại."},{"type":"simple","zh":"我已经把今天学过的生词和课文全都复习了一遍。","pinyin":"Wǒ yǐjīng bǎ jīntiān xuéguo de shēngcí hé kèwén quándōu fùxíle yíbiàn.","vi":"Tôi đã ôn lại hết một lượt toàn bộ từ mới và bài khóa học hôm nay rồi."},{"type":"compound","zh":"出门之前，别忘了把空调和电灯关掉，这样可以节约用电。","pinyin":"Chūmén zhīqián, bié wàngle bǎ kōngtiáo hé diàndēng guāndiào, zhèyàng kěyǐ jiéyuē yòng diàn.","vi":"Trước khi ra khỏi nhà, đừng quên tắt điều hòa và đèn điện, như vậy có thể tiết kiệm điện."}],"related":[{"hanzi":"被","pinyin":"bèi","vi":"Bị/Được"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm/Lấy"},{"hanzi":"放","pinyin":"fàng","vi":"Đặt/Để"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"},{"hanzi":"收拾","pinyin":"shōushi","vi":"Dọn dẹp"}]},{"id":"班","hanzi":"班","pinyin":"bān","meaning_vi":"lớp; ca (làm việc); chuyến (xe)","explanation":"Dùng cho 班级 (lớp học), 上班 (đi làm).","hsk_level":3,"tags":["danh-tu","hoc-tap","cong-viec"],"image":"🏫","examples":[{"type":"basic","zh":"我们班有二十五个同学。","pinyin":"Wǒmen bān yǒu èr shíwǔ ge tóngxué.","vi":"Lớp chúng tôi có 25 bạn học."},{"type":"simple","zh":"我们班的同学都很喜欢唱歌。","pinyin":"Wǒmen bān de tóngxué dōu hěn xǐhuan chànggē.","vi":"Các bạn trong lớp chúng tôi đều rất thích hát."},{"type":"compound","zh":"虽然我们班的同学来自不同的国家，但是大家团结友爱，就像一个大家庭一样。","pinyin":"Suīrán wǒmen bān de tóngxué láizì bùtóng de guójiā, dànshì dàjiā tuánjié yǒu'ài, jiù xiàng yí ge dàjiātíng yíyàng.","vi":"Tuy các bạn học lớp chúng tôi đến từ nhiều quốc gia khác nhau nhưng mọi người đoàn kết yêu thương nhau như một đại gia đình."}],"related":[{"hanzi":"上班","pinyin":"shàngbān","vi":"Đi làm"},{"hanzi":"下班","pinyin":"xiàbān","vi":"Tan làm"},{"hanzi":"加班","pinyin":"jiābān","vi":"Tăng ca"},{"hanzi":"航班","pinyin":"hángbān","vi":"Chuyến bay"},{"hanzi":"同学","pinyin":"tóngxué","vi":"Bạn học"}]},{"id":"办法","hanzi":"办法","pinyin":"bànfǎ","meaning_vi":"biện pháp, cách làm","explanation":"办 (làm) + 法 (phương pháp).","hsk_level":3,"tags":["danh-tu"],"image":"💡","examples":[{"type":"basic","zh":"我们一定能想到好办法。","pinyin":"Wǒmen yí dìngnéng xiǎngdào hǎo bànfǎ.","vi":"Chúng ta nhất định sẽ nghĩ ra cách hay."},{"type":"simple","zh":"遇到难题的时候不要轻易放弃，多动脑筋总能找到解决的办法。","pinyin":"Yùdào nántí de shíhou bú yào qīngyì fàngqì, duō dòngnǎojīn zǒngnéng zhǎodào jiějué de bànfǎ.","vi":"Khi gặp bài toán khó đừng dễ dàng bỏ cuộc, động não nhiều luôn tìm được cách giải quyết."},{"type":"compound","zh":"既然坐飞机去太贵、坐火车又太慢，那坐高铁就是最理想的办法了。","pinyin":"Jìrán zuòfēijī qù tài guì, zuò huǒchē yòu tài màn, nà zuò gāotiě jiùshì zuì lǐxiǎng de bànfǎ le.","vi":"Vì đi máy bay thì đắt quá mà đi tàu hỏa lại chậm quá, vậy đi tàu cao tốc chính là cách lý tưởng nhất."}],"related":[{"hanzi":"方法","pinyin":"fāngfǎ","vi":"Phương pháp"},{"hanzi":"看法","pinyin":"kànfǎ","vi":"Cách nhìn"},{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"Tổ chức"},{"hanzi":"主意","pinyin":"zhǔyi","vi":"Chủ ý"}],"traditional":"辦法"},{"id":"保证","hanzi":"保证","pinyin":"bǎozhèng","meaning_vi":"bảo đảm, cam đoan","explanation":"保 (giữ) + 证 (chứng thực).","hsk_level":3,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"我保证以后不再迟到了。","pinyin":"Wǒ bǎozhèng yǐhòu bú zài chídào le.","vi":"Tôi cam đoan sau này sẽ không đến muộn nữa."},{"type":"simple","zh":"每天保证八个小时的充足睡眠，第二天的学习和工作效率才会高。","pinyin":"Měitiān bǎozhèng bā ge xiǎoshí de chōngzú shuìmián, dì'èrtiān de xuéxí hé gōngzuò xiàolǜ cái huì gāo.","vi":"Mỗi ngày đảm bảo ngủ đủ 8 tiếng đồng hồ thì hiệu suất học tập và làm việc ngày hôm sau mới cao."},{"type":"compound","zh":"这家餐厅之所以深受顾客欢迎，是因为他们始终保证所有食材新鲜卫生。","pinyin":"Zhè jiā cāntīng zhīsuǒyǐ shēnshòu gùkè huānyíng, shì yīnwèi tāmen shǐzhōng bǎozhèng suǒyǒu shícái xīnxiān wèishēng.","vi":"Sở dĩ nhà hàng này được thực khách hết mực yêu thích là vì họ luôn đảm bảo mọi nguyên liệu tươi ngon vệ sinh."}],"related":[{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"Chứng minh"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"Visa"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"Khẳng định"},{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"}],"traditional":"保證"},{"id":"抱","hanzi":"抱","pinyin":"bào","meaning_vi":"ôm, bế","explanation":"Bộ tài gảy 扌+ 包.","hsk_level":3,"tags":["dong-tu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"妈妈轻轻地抱着小宝宝。","pinyin":"Māma qīngqīng de bàozhe xiǎo bǎobao.","vi":"Mẹ đang nhẹ nhàng bế em bé."},{"type":"simple","zh":"在机场分别的时候，两个好朋友紧紧地拥抱在一起，舍不得分开。","pinyin":"Zài jīchǎng fēnbié de shíhou, liǎng ge hǎopéngyou jǐnjǐn de yōngbào zài yìqǐ, shěbude fēnkāi.","vi":"Lúc chia tay ở sân bay, hai người bạn thân ôm chặt lấy nhau không nỡ rời xa."},{"type":"compound","zh":"桌子上的这摞书太重了，我一个人抱不动，你能过来帮我拿几本吗？","pinyin":"Zhuōzi shang de zhè luò shū tài zhòng le, wǒ yígerén bào búdòng, nǐ néng guòlái bāng wǒ ná jǐ běn ma?","vi":"Chồng sách trên bàn này nặng quá, một mình tôi ôm không nổi, bạn có thể lại đây cầm giúp tôi vài quyển không?"}],"related":[{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"Áy náy/Xin lỗi"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm"},{"hanzi":"抬","pinyin":"tái","vi":"Khiêng"},{"hanzi":"孩子","pinyin":"háizi","vi":"Trẻ con"},{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"}]},{"id":"抱歉","hanzi":"抱歉","pinyin":"bàoqiàn","meaning_vi":"xin lỗi, áy náy","explanation":"抱 (ôm giữ) + 歉 (lỗi). Trang trọng hơn 对不起.","hsk_level":3,"tags":["tinh-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"真抱歉，让你久等了。","pinyin":"Zhēn bàoqiàn, ràng nǐ jiǔděng le.","vi":"Thật xin lỗi, đã để bạn đợi lâu rồi."},{"type":"simple","zh":"非常抱歉，由于航班延误，我今天下午不能准时参加会议了。","pinyin":"Fēicháng bàoqiàn, yóuyú hángbān yánwù, wǒ jīntiān xiàwǔ bù néng zhǔnshí cānjiā huìyì le.","vi":"Vô cùng xin lỗi, do chuyến bay bị hoãn nên chiều nay tôi không thể tham dự cuộc họp đúng giờ được."},{"type":"compound","zh":"因为今天临时有急事要处理，所以很抱歉不能陪你一起去逛街了。","pinyin":"Yīnwèi jīntiān línshí yǒu jíshì yào chǔlǐ, suǒyǐ hěn bàoqiàn bù néng péi nǐ yìqǐ qù guàngjiē le.","vi":"Vì hôm nay đột xuất có việc gấp cần giải quyết nên rất xin lỗi không thể đi dạo phố cùng bạn được."}],"related":[{"hanzi":"道歉","pinyin":"dàoqiàn","vi":"Xin lỗi"},{"hanzi":"对不起","pinyin":"duìbuqǐ","vi":"Xin lỗi"},{"hanzi":"抱","pinyin":"bào","vi":"Ôm"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"Tha thứ"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"}]},{"id":"倍","hanzi":"倍","pinyin":"bèi","meaning_vi":"lần (gấp bội)","explanation":"Bộ nhân đứng 亻+ 咅. Ví dụ: 两倍 (gấp hai lần).","hsk_level":3,"tags":["luong-tu","so-luong"],"image":"✖️","examples":[{"type":"basic","zh":"十是五的两倍。","pinyin":"Shí shì wǔ de liǎngbèi.","vi":"Mười gấp hai lần năm."},{"type":"simple","zh":"随着交通条件的改善，现在坐高铁去北京的速度比以前快了好几倍。","pinyin":"Suízhe jiāotōng tiáojiàn de gǎishàn, xiànzài zuò gāotiě qù Běijīng de sùdù bǐ yǐqián kuàile hǎo jǐbèi.","vi":"Cùng với sự cải thiện của điều kiện giao thông, hiện nay đi tàu cao tốc tới Bắc Kinh nhanh hơn trước đây gấp mấy lần."},{"type":"compound","zh":"因为参加了培训，所以他现在的工资是以前的两倍。","pinyin":"Yīnwèi cānjiāle péixùn, suǒyǐ tā xiànzài de gōngzī shì yǐqián de liǎngbèi.","vi":"Vì đã tham gia khóa đào tạo nên lương bây giờ của anh ấy gấp hai lần trước đây."}],"related":[{"hanzi":"加倍","pinyin":"jiābèi","vi":"Gấp bội"},{"hanzi":"数量","pinyin":"shùliàng","vi":"Số lượng"},{"hanzi":"超过","pinyin":"chāoguò","vi":"Vượt qua"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"Tăng thêm"},{"hanzi":"比","pinyin":"bǐ","vi":"So với"}]},{"id":"本来","hanzi":"本来","pinyin":"běnlái","meaning_vi":"vốn dĩ, ban đầu","explanation":"本 (gốc) + 来 (đến).","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"📌","examples":[{"type":"basic","zh":"我本来今天要去北京的。","pinyin":"Wǒ běnlái jīntiān yào qù Běijīng de.","vi":"Vốn dĩ hôm nay tôi định đi Bắc Kinh đấy."},{"type":"simple","zh":"这本书本来就是图书馆的，看完以后应该按时还回去。","pinyin":"Zhè běn shū běnlái jiùshì túshūguǎn de, kàn wán yǐhòu yīnggāi ànshí huán huíqù.","vi":"Quyển sách này vốn dĩ là của thư viện, đọc xong phải trả lại đúng hạn."},{"type":"compound","zh":"我们本来计划周末去郊区爬山，可是天气预报说有暴雨，只好改期了。","pinyin":"Wǒmen běnlái jìhuà zhōumò qù jiāoqū páshān, kěshì tiānqì yùbào shuō yǒu bàoyǔ, zhǐhǎo gǎiqī le.","vi":"Chúng tôi vốn dự định cuối tuần đi leo núi ngoại ô nhưng dự báo thời tiết nói có mưa bão nên đành hoãn lại."}],"related":[{"hanzi":"原来","pinyin":"yuánlái","vi":"Vốn dĩ/Hóa ra"},{"hanzi":"本子","pinyin":"běnzi","vi":"Quyển vở"},{"hanzi":"本","pinyin":"běn","vi":"Quyển/Gốc"},{"hanzi":"计划","pinyin":"jìhuà","vi":"Kế hoạch"},{"hanzi":"可是","pinyin":"kěshì","vi":"Nhưng"}],"traditional":"本來"},{"id":"笨","hanzi":"笨","pinyin":"bèn","meaning_vi":"ngốc nghếch, vụng về","explanation":"Bộ trúc ⺮+ 本. Đối nghĩa với 聪明 (thông minh).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🙈","examples":[{"type":"basic","zh":"这只小熊看起来笨笨的，很可爱。","pinyin":"Zhè zhī xiǎo Xióng kànqǐlái bèn bèn de, hěn kě'ài.","vi":"Chú gấu nhỏ này trông ngố ngố, rất đáng yêu."},{"type":"simple","zh":"世上无难事，只怕有心人，其实没有人是真正笨的，只是努力不够。","pinyin":"Shìshang wú nán shì, zhǐpà yǒuxīnrén, qíshí méiyǒu rén shì zhēnzhèng bèn de, zhǐshì nǔlì búgòu.","vi":"Trên đời không có việc gì khó chỉ sợ lòng không bền, thực ra không ai thực sự ngốc cả, chỉ là nỗ lực chưa đủ mà thôi."},{"type":"compound","zh":"虽然他学东西有点儿笨，但是做事情非常认真，从不偷懒。","pinyin":"Suīrán tā xué dōngxi yǒudiǎnr bèn, dànshì zuò shìqing fēicháng rènzhēn, cóng bù tōulǎn.","vi":"Tuy cậu ấy tiếp thu hơi chậm một chút nhưng làm việc vô cùng nghiêm túc, chưa bao giờ lười biếng."}],"related":[{"hanzi":"聪明","pinyin":"cōngming","vi":"Thông minh"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Chăm chỉ"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"Đáng yêu"}]},{"id":"笔记本","hanzi":"笔记本","pinyin":"bǐjìběn","meaning_vi":"sổ tay; máy tính xách tay","explanation":"笔记 (ghi chép) + 本 (quyển).","hsk_level":3,"tags":["danh-tu","do-vat","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"我买了一台新笔记本电脑。","pinyin":"Wǒ mǎile yì tái xīn bǐjìběn diànnǎo.","vi":"Tôi đã mua một chiếc máy tính xách tay mới."},{"type":"simple","zh":"每次上课的时候，我都会在笔记本上认真记下老师讲的重点。","pinyin":"Měi cì shàngkè de shíhou, wǒ dōuhuì zài bǐjìběn shang rènzhēn jìxià lǎoshī jiǎng de zhòngdiǎn.","vi":"Mỗi lần lên lớp, tôi đều ghi chép cẩn thận những trọng điểm thầy giáo giảng vào sổ tay."},{"type":"compound","zh":"虽然笔记本电脑比台式电脑稍微贵一点儿，但是携带方便，随时随地都能办公。","pinyin":"Suīrán bǐjìběn diànnǎo bǐ táishì diànnǎo shāowēi guì yìdiǎnr, dànshì xiédài fāngbiàn, suíshísuídì dōu néng bàngōng.","vi":"Tuy laptop đắt hơn máy tính để bàn một chút nhưng mang theo tiện lợi, có thể làm việc mọi lúc mọi nơi."}],"related":[{"hanzi":"本子","pinyin":"běnzi","vi":"Quyển vở"},{"hanzi":"电脑","pinyin":"diànnǎo","vi":"Máy tính"},{"hanzi":"笔","pinyin":"bǐ","vi":"Bút"},{"hanzi":"日记","pinyin":"rìjì","vi":"Nhật ký"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"}],"traditional":"筆記本"},{"id":"毕业","hanzi":"毕业","pinyin":"bìyè","meaning_vi":"tốt nghiệp","explanation":"毕 (hoàn tất) + 业 (học nghiệp). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"我明年夏天大学毕业。","pinyin":"Wǒ míngnián xiàtiān dàxué bìyè.","vi":"Mùa hè năm sau tôi tốt nghiệp đại học."},{"type":"simple","zh":"大学毕业以后，他决定回到家乡当一名中学汉语老师。","pinyin":"Dàxué bìyè yǐhòu, tā juédìng huídào jiāxiāng dāng yì míng zhōngxué Hànyǔ lǎoshī.","vi":"Sau khi tốt nghiệp đại học, anh ấy quyết định trở về quê hương làm giáo viên tiếng Trung cấp hai."},{"type":"compound","zh":"虽然毕业以后大家要各自奔赴不同的工作岗位，但是我们的心永远连在一起。","pinyin":"Suīrán bìyè yǐhòu dàjiā yào gèzì bēnfù bùtóng de gōngzuò gǎngwèi, dànshì wǒmen de xīn yǒngyuǎn lián zài yìqǐ.","vi":"Tuy sau khi tốt nghiệp mọi người sẽ đi nhận những vị trí công việc khác nhau nhưng trái tim chúng ta mãi gắn kết bên nhau."}],"related":[{"hanzi":"专业","pinyin":"zhuānyè","vi":"Chuyên ngành"},{"hanzi":"职业","pinyin":"zhíyè","vi":"Nghề nghiệp"},{"hanzi":"大学","pinyin":"dàxué","vi":"Đại học"},{"hanzi":"硕士","pinyin":"shuòshì","vi":"Thạc sĩ"},{"hanzi":"博士","pinyin":"bóshì","vi":"Tiến sĩ"}],"traditional":"畢業"},{"id":"遍","hanzi":"遍","pinyin":"biàn","meaning_vi":"lần, lượt (lượng từ động tác)","explanation":"Lượng từ nhấn mạnh toàn bộ quá trình hành động (看一遍 - xem một lượt).","hsk_level":3,"tags":["luong-tu"],"image":"🔁","examples":[{"type":"basic","zh":"这本书我已经看了三遍了。","pinyin":"Zhè běn shū wǒ yǐjīng kànle sān biàn le.","vi":"Quyển sách này tôi đã đọc qua ba lượt rồi."},{"type":"simple","zh":"老师把刚才那个语法点又重新讲了一遍，这次大家都听懂了。","pinyin":"Lǎoshī bǎ gāngcái nà ge yǔfǎ diǎn yòu chóngxīn jiǎngle yíbiàn, zhè cì dàjiā dōu tīngdǒng le.","vi":"Thầy giáo đã giảng lại một lượt điểm ngữ pháp vừa nãy, lần này mọi người đều nghe hiểu hết."},{"type":"compound","zh":"好书不厌百回读，每读一遍都会有新的收获和更深的理解。","pinyin":"Hǎo shū búyàn bǎi huí dú, měi dú yíbiàn dōuhuì yǒu xīn de shōuhuò hé gèng shēn de lǐjiě.","vi":"Sách hay đọc trăm lần không chán, mỗi lần đọc lại đều có thu hoạch mới và sự thấu hiểu sâu sắc hơn."}],"related":[{"hanzi":"次","pinyin":"cì","vi":"Lần"},{"hanzi":"趟","pinyin":"tàng","vi":"Chuyến"},{"hanzi":"普遍","pinyin":"pǔbiàn","vi":"Phổ biến"},{"hanzi":"重新","pinyin":"chóngxīn","vi":"Làm lại"},{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"}]},{"id":"标准","hanzi":"标准","pinyin":"biāozhǔn","meaning_vi":"tiêu chuẩn, chuẩn xác","explanation":"标 (mốc) + 准 (chuẩn).","hsk_level":3,"tags":["danh-tu","tinh-tu"],"image":"📏","examples":[{"type":"basic","zh":"他的普通话发音非常标准。","pinyin":"Tā de pǔtōnghuà fāyīn fēicháng biāozhǔn.","vi":"Phát âm tiếng phổ thông của anh ấy vô cùng chuẩn xác."},{"type":"simple","zh":"这家医院的卫生环境和服务质量完全符合国家一级标准。","pinyin":"Zhè jiā yīyuàn de wèishēng huánjìng hé fúwù zhìliàng wánquán fúhé guójiā yìjí biāozhǔn.","vi":"Môi trường vệ sinh và chất lượng dịch vụ của bệnh viện này hoàn toàn đạt tiêu chuẩn cấp 1 quốc gia."},{"type":"compound","zh":"虽然不同人对幸福的标准各不相同，但是拥有健康的身体永远排在第一位。","pinyin":"Suīrán bù tóngrén duì xìngfú de biāozhǔn gè bù xiāngtóng, dànshì yōngyǒu jiànkāng de shēntǐ yǒngyuǎn pái zài dìyī wèi.","vi":"Tuy tiêu chuẩn hạnh phúc của mỗi người không giống nhau nhưng có một cơ thể khỏe mạnh luôn xếp ở vị trí số một."}],"related":[{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"Chuẩn bị"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"Chính xác"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"普通话","pinyin":"pǔtōnghuà","vi":"Tiếng phổ thông"},{"hanzi":"符合","pinyin":"fúhé","vi":"Phù hợp"}],"traditional":"標準"},{"id":"表格","hanzi":"表格","pinyin":"biǎogé","meaning_vi":"bảng biểu, biểu mẫu","explanation":"表 (bảng) + 格 (ô kẻ).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"请认真填写这张报名表格。","pinyin":"Qǐng rènzhēn tiánxiě zhè zhāng bàomíng biǎogé.","vi":"Xin hãy điền cẩn thận biểu mẫu đăng ký này."},{"type":"simple","zh":"申请留学签证时，必须按照要求用英文或中文准确填写申请表格。","pinyin":"Shēnqǐng liúxué qiānzhèng shí, bìxū ànzhào yāoqiú yòng Yīngwén huò Zhōngwén zhǔnquè tiánxiě shēnqǐng biǎogé.","vi":"Khi xin visa du học, bắt buộc phải điền chính xác mẫu đơn đăng ký bằng tiếng Anh hoặc tiếng Trung theo yêu cầu."},{"type":"compound","zh":"我把今年各季度的销售数据都整理成了一张清晰的表格，方便大家查看。","pinyin":"Wǒ bǎ jīnnián gè jìdù de xiāoshòu shùjù dōu zhěnglǐ chéngle yì zhāng qīngxī de biǎogé, fāngbiàn dàjiā chákàn.","vi":"Tôi đã tổng hợp số liệu bán hàng các quý năm nay thành một bảng biểu rõ ràng để mọi người tiện theo dõi."}],"related":[{"hanzi":"表示","pinyin":"biǎoshì","vi":"Biểu thị"},{"hanzi":"严格","pinyin":"yángé","vi":"Nghiêm ngặt"},{"hanzi":"填写","pinyin":"tiánxiě","vi":"Điền vào"},{"hanzi":"材料","pinyin":"cáiliào","vi":"Tài liệu"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"Xin/Nộp đơn"}]},{"id":"饼干","hanzi":"饼干","pinyin":"bǐnggān","meaning_vi":"bánh quy","explanation":"饼 (bánh) + 干 (khô).","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🍪","examples":[{"type":"basic","zh":"我买了一盒牛奶饼干。","pinyin":"Wǒ mǎile yì hé niúnǎi bǐnggān.","vi":"Tôi đã mua một hộp bánh quy sữa."},{"type":"simple","zh":"下午工作饿了的时候，吃几块苏打饼干可以暂时补充能量。","pinyin":"Xiàwǔ gōngzuò èle de shíhou, chī jǐ kuài sūdǎ bǐnggān kěyǐ zànshí bǔchōng néngliàng.","vi":"Buổi chiều làm việc lúc đói bụng, ăn vài chiếc bánh quy mặn có thể tạm thời bổ sung năng lượng."},{"type":"compound","zh":"为了爷爷的身体健康，妈妈特意去超市买了一盒无糖全麦饼干。","pinyin":"Wèile yéye de shēntǐ jiànkāng, māma tèyì qù chāoshì mǎile yì hé wútáng quánmài bǐnggān.","vi":"Vì sức khỏe của ông nội, mẹ đã đặc biệt ra siêu thị mua một hộp bánh quy nguyên cám không đường."}],"related":[{"hanzi":"面包","pinyin":"miànbāo","vi":"Bánh mì"},{"hanzi":"蛋糕","pinyin":"dàngāo","vi":"Bánh kem"},{"hanzi":"干燥","pinyin":"gānzào","vi":"Khô ráo"},{"hanzi":"零食","pinyin":"língshí","vi":"Đồ ăn vặt"},{"hanzi":"饿","pinyin":"è","vi":"Đói"}],"traditional":"餅乾"},{"id":"并且","hanzi":"并且","pinyin":"bìngqiě","meaning_vi":"và, đồng thời, hơn nữa","explanation":"并 + 且. Liên từ nối hai động từ hoặc tính từ.","hsk_level":3,"tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"他很聪明，并且非常努力。","pinyin":"Tā hěn cōngming, bìngqiě fēicháng nǔlì.","vi":"Cậu ấy rất thông minh, đồng thời vô cùng nỗ lực."},{"type":"simple","zh":"王老师不仅课讲得生动有趣，并且经常在课后耐心辅导留学生。","pinyin":"Wáng lǎoshī bùjǐn kè jiǎng de shēngdòng yǒuqù, bìngqiě jīngcháng zài kè hòu nàixīn fǔdǎo liúxuésheng.","vi":"Thầy Vương không chỉ giảng bài sinh động thú vị mà còn thường xuyên tận tình phụ đạo du học sinh sau giờ học."},{"type":"compound","zh":"我们必须认真调查实际情况，并且听取各方意见，然后才能做出正确决定。","pinyin":"Wǒmen bìxū rènzhēn diàochá shíjì qíngkuàng, bìngqiě tīngqǔ gèfāng yìjiàn, ránhòu cáinéng zuòchū zhèngquè juédìng.","vi":"Chúng ta bắt buộc phải điều tra kỹ tình hình thực tế và lắng nghe ý kiến các bên rồi mới có thể đưa ra quyết định đúng đắn."}],"related":[{"hanzi":"而且","pinyin":"érqiě","vi":"Mà còn"},{"hanzi":"同时","pinyin":"tóngshí","vi":"Đồng thời"},{"hanzi":"不仅","pinyin":"bùjǐn","vi":"Không chỉ"},{"hanzi":"不但","pinyin":"búdàn","vi":"Không những"},{"hanzi":"和","pinyin":"hé","vi":"Và"}],"traditional":"並且"},{"id":"博士","hanzi":"博士","pinyin":"bóshì","meaning_vi":"tiến sĩ","explanation":"博 (uyên bác) + 士 (học giả).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"我哥哥正在读工学博士。","pinyin":"Wǒ gēge zhèngzài dú gōngxué bóshì.","vi":"Anh trai tôi đang học tiến sĩ ngành kỹ thuật."},{"type":"simple","zh":"王教授指导的几名博士研究生今年夏天都顺利毕业了。","pinyin":"Wáng jiàoshòu zhǐdǎo de jǐ míng bóshì yánjiūshēng jīnnián xiàtiān dōu shùnlì bìyè le.","vi":"Mấy nghiên cứu sinh tiến sĩ do giáo sư Vương hướng dẫn mùa hè năm nay đều tốt nghiệp suôn sẻ."},{"type":"compound","zh":"虽然攻读博士学位的道路充满挑战，但是为了实现科研梦想他一直在坚持。","pinyin":"Suīrán gōngdú bóshì xuéwèi de dàolù chōngmǎn tiǎozhàn, dànshì wèile shíxiàn kēyán mèngxiǎng tā yìzhí zài jiānchí.","vi":"Tuy con đường chinh phục học vị tiến sĩ đầy rẫy thử thách nhưng để thực hiện ước mơ nghiên cứu khoa học anh ấy vẫn luôn kiên trì."}],"related":[{"hanzi":"硕士","pinyin":"shuòshì","vi":"Thạc sĩ"},{"hanzi":"教授","pinyin":"jiàoshòu","vi":"Giáo sư"},{"hanzi":"研究","pinyin":"yánjiū","vi":"Nghiên cứu"},{"hanzi":"毕业","pinyin":"bìyè","vi":"Tốt nghiệp"},{"hanzi":"大学","pinyin":"dàxué","vi":"Đại học"}]},{"id":"不但","hanzi":"不但","pinyin":"búdàn","meaning_vi":"không những","explanation":"不 (bất – không) + 但 (đãn – chỉ) → không chỉ, không những. Thường dùng trong cấu trúc 不但…而且/还/也… \"không những… mà còn…\".","hsk_level":3,"tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"他不但会说汉语，而且会写汉字。","pinyin":"Tā búdàn huì shuō Hànyǔ, érqiě huì xiě hànzì.","vi":"Anh ấy không những biết nói tiếng Trung mà còn biết viết chữ Hán."},{"type":"simple","zh":"这家超市的东西不但种类齐全，而且价格也非常便宜。","pinyin":"Zhè jiā chāoshì de dōngxi búdàn zhǒnglèi qíquán, érqiě jiàgé yě fēicháng piányi.","vi":"Đồ đạc của siêu thị này không những chủng loại đầy đủ mà giá cả cũng vô cùng rẻ."},{"type":"compound","zh":"每天坚持锻炼不但能增强身体素质，而且能帮助我们缓解学习压力。","pinyin":"Měitiān jiānchí duànliàn búdàn néng zēngqiáng shēntǐ sùzhì, érqiě néng bāngzhù wǒmen huǎnjiě xuéxí yālì.","vi":"Mỗi ngày kiên trì tập luyện không những nâng cao thể chất mà còn giúp chúng ta giảm bớt áp lực học tập."}],"related":[{"hanzi":"不仅","pinyin":"bùjǐn","vi":"Không chỉ"},{"hanzi":"而且","pinyin":"érqiě","vi":"Mà còn"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"Đồng thời"},{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"虽然","pinyin":"suīrán","vi":"Tuy rằng"}]},{"id":"不过","hanzi":"不过","pinyin":"búguò","meaning_vi":"nhưng, tuy nhiên, chỉ là","explanation":"不 + 过. Liên từ chuyển ngoặt nhẹ hơn 但是.","hsk_level":3,"tags":["lien-tu","pho-tu"],"image":"↩️","examples":[{"type":"basic","zh":"这件衣服很好看，不过有点儿贵。","pinyin":"Zhè jiàn yīfu hěn hǎokàn, búguò yǒudiǎnr guì.","vi":"Bộ quần áo này rất đẹp, nhưng hơi đắt một chút."},{"type":"simple","zh":"今天的天气预报说有小雨，不过现在太阳还高高挂在天上呢。","pinyin":"Jīntiān de tiānqì yùbào shuō yǒu xiǎoyǔ, búguò xiànzài tàiyáng hái gāo gāo guà zài tiānshang ne.","vi":"Dự báo thời tiết hôm nay nói có mưa nhỏ, nhưng hiện tại mặt trời vẫn treo cao trên bầu trời đấy."},{"type":"compound","zh":"虽然坐火车去北京需要十几个小时，不过沿途可以欣赏到很多美丽的风景。","pinyin":"Suīrán zuò huǒchē qù Běijīng xūyào shíjǐ ge xiǎoshí, búguò yántú kěyǐ xīnshǎng dào hěn duō měilì de fēngjǐng.","vi":"Tuy đi tàu hỏa tới Bắc Kinh mất mười mấy tiếng đồng hồ nhưng dọc đường có thể ngắm rất nhiều cảnh đẹp."}],"related":[{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"可是","pinyin":"kěshì","vi":"Nhưng mà"},{"hanzi":"然而","pinyin":"rán'ér","vi":"Tuy nhiên"},{"hanzi":"经过","pinyin":"jīngguò","vi":"Đi qua"},{"hanzi":"超过","pinyin":"chāoguò","vi":"Vượt qua"}],"traditional":"不過"},{"id":"不得不","hanzi":"不得不","pinyin":"bùdébù","meaning_vi":"không thể không, đành phải","explanation":"不 + 得 + 不. Nhấn mạnh sự bắt buộc khách quan.","hsk_level":3,"tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"下雨了，我们不得不回家。","pinyin":"Xiàyǔ le, wǒmen bùdébù huíjiā.","vi":"Trời mưa rồi, chúng tôi đành phải về nhà."},{"type":"simple","zh":"因为明天上午有重要考试，所以我今天晚上不得不熬夜复习。","pinyin":"Yīnwèi míngtiān shàngwǔ yǒu zhòngyào kǎoshì, suǒyǐ wǒ jīntiān wǎnshang bùdébù áoyè fùxí.","vi":"Vì sáng mai có kỳ thi quan trọng nên tối nay tôi bắt buộc phải thức đêm ôn tập."},{"type":"compound","zh":"虽然他非常喜欢这份工作，但是由于家庭原因，最后还是不得不辞职回国了。","pinyin":"Suīrán tā fēicháng xǐhuan zhè fèn gōngzuò, dànshì yóuyú jiātíng yuányīn, zuìhòu háishi bùdébù cízhí huíguó le.","vi":"Tuy anh ấy vô cùng yêu thích công việc này nhưng do nguyên nhân gia đình nên cuối cùng vẫn đành phải nghỉ việc về nước."}],"related":[{"hanzi":"必须","pinyin":"bìxū","vi":"Bắt buộc"},{"hanzi":"只好","pinyin":"zhǐhǎo","vi":"Đành phải"},{"hanzi":"得","pinyin":"děi","vi":"Phải"},{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"没办法","pinyin":"méibànfǎ","vi":"Hết cách"}]},{"id":"不管","hanzi":"不管","pinyin":"bùguǎn","meaning_vi":"bất kể, cho dù","explanation":"不 (không) + 管 (quản/xét đến). Thường đi với 都 / 也.","hsk_level":3,"tags":["lien-tu"],"image":"🔄","examples":[{"type":"basic","zh":"不管天气怎么样，我都要去。","pinyin":"Bùguǎn tiānqì zěnmeyàng, wǒ dōu yào qù.","vi":"Bất kể thời tiết thế nào, tôi cũng đều phải đi."},{"type":"simple","zh":"不管遇到什么困难，只要我们坚持努力就一定能找到解决办法。","pinyin":"Bùguǎn yùdào shénme kùnnan, zhǐyào wǒmen jiānchí nǔlì jiù yídìng néng zhǎodào jiějué bànfǎ.","vi":"Bất kể gặp khó khăn gì, chỉ cần chúng ta kiên trì nỗ lực thì nhất định sẽ tìm được cách giải quyết."},{"type":"compound","zh":"不管你将来选择留在国内工作还是出国留学，父母都会永远支持你的决定。","pinyin":"Bùguǎn nǐ jiānglái xuǎnzé liú zài guónèi gōngzuò háishi chūguó liúxué, fùmǔ dōuhuì yǒngyuǎn zhīchí nǐ de juédìng.","vi":"Bất kể tương lai bạn chọn ở lại trong nước làm việc hay ra nước ngoài du học, bố mẹ đều sẽ mãi ủng hộ quyết định của bạn."}],"related":[{"hanzi":"无论","pinyin":"wúlùn","vi":"Bất kể"},{"hanzi":"尽管","pinyin":"jǐnguǎn","vi":"Mặc dù"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"Quản lý"},{"hanzi":"都","pinyin":"dōu","vi":"Đều"},{"hanzi":"任何","pinyin":"rènhé","vi":"Bất kỳ"}]},{"id":"不仅","hanzi":"不仅","pinyin":"bùjǐn","meaning_vi":"không chỉ, không những","explanation":"不 + 仅 (chỉ). Đồng nghĩa với 不但, dùng với 而且 / 还.","hsk_level":3,"tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"他不仅会说汉语，还会写汉字。","pinyin":"Tā bùjǐn huì shuō Hànyǔ, hái huì xiě hànzì.","vi":"Anh ấy không chỉ biết nói tiếng Trung mà còn biết viết chữ Hán."},{"type":"simple","zh":"这家餐厅不仅环境干净优雅，而且菜的味道也非常正宗。","pinyin":"Zhè jiā cāntīng bùjǐn huánjìng gānjìng yōuyǎ, érqiě cài de wèidào yě fēicháng zhèngzōng.","vi":"Nhà hàng này không chỉ không gian sạch sẽ trang nhã mà hương vị món ăn cũng vô cùng chuẩn vị."},{"type":"compound","zh":"多阅读优秀的中文小说，不仅可以扩大词汇量，还能深入了解中国文化。","pinyin":"Duō yuèdú yōuxiù de Zhōngwén xiǎoshuō, bùjǐn kěyǐ kuòdà cíhuìliàng, hái néng shēnrù liǎojiě Zhōngguó wénhuà.","vi":"Đọc nhiều tiểu thuyết tiếng Trung hay không chỉ mở rộng vốn từ vựng mà còn giúp hiểu sâu sắc về văn hóa Trung Quốc."}],"related":[{"hanzi":"不但","pinyin":"búdàn","vi":"Không những"},{"hanzi":"而且","pinyin":"érqiě","vi":"Mà còn"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"Đồng thời"},{"hanzi":"尽管","pinyin":"jǐnguǎn","vi":"Mặc dù"},{"hanzi":"还","pinyin":"hái","vi":"Vẫn/Còn"}],"traditional":"不僅"},{"id":"部分","hanzi":"部分","pinyin":"bùfen","meaning_vi":"bộ phận, phần","explanation":"部 (nhóm/phần) + 分 (chia).","hsk_level":3,"tags":["danh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"这只是计划的一部分。","pinyin":"Zhè zhǐshì jìhuà de yíbùfen.","vi":"Đây chỉ là một phần của kế hoạch."},{"type":"simple","zh":"虽然这篇文章有点儿长，但是大部分内容我都看懂了。","pinyin":"Suīrán zhè piān wénzhāng yǒudiǎnr cháng, dànshì dàbùfen nèiróng wǒ dōu kàndǒng le.","vi":"Tuy bài văn này hơi dài một chút nhưng phần lớn nội dung tôi đều đọc hiểu rồi."},{"type":"compound","zh":"在团队合作中，每个成员都要认真负责地完成自己承担的那部分任务。","pinyin":"Zài tuánduì hézuò zhōng, měi ge chéngyuán dōu yào rènzhēn fùzé de wánchéng zìjǐ chéngdān de nà bùfen rènwu.","vi":"Trong làm việc nhóm, mỗi thành viên đều phải nghiêm túc có trách nhiệm hoàn thành phần nhiệm vụ mà mình đảm nhận."}],"related":[{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"其中","pinyin":"qízhōng","vi":"Trong đó"},{"hanzi":"分","pinyin":"fēn","vi":"Chia/Phần"},{"hanzi":"十分","pinyin":"shífēn","vi":"Vô cùng"},{"hanzi":"部门","pinyin":"bùmén","vi":"Phòng ban"}]},{"id":"擦","hanzi":"擦","pinyin":"cā","meaning_vi":"lau, chùi, xóa","explanation":"Bộ tài gảy 扌+ 察. Cụm: 擦黑板 (lau bảng).","hsk_level":3,"tags":["dong-tu","sinh-hoat"],"image":"🧽","examples":[{"type":"basic","zh":"请把黑板擦干净。","pinyin":"Qǐng bǎ hēi bǎncā gānjìng.","vi":"Xin hãy lau sạch bảng đen."},{"type":"simple","zh":"每天早上来到教室，值日生都会用湿布把桌子和黑板擦得干干净净。","pinyin":"Měitiān zǎoshang láidào jiàoshì, zhírìshēng dōuhuì yòng shī bù bǎ zhuōzi hé hēi bǎncā de gān gānjìng jìng.","vi":"Mỗi sáng đến lớp học, bạn trực nhật đều dùng khăn ẩm lau bàn ghế và bảng đen sạch bóng."},{"type":"compound","zh":"他刚打完篮球满头大汗，赶紧拿起毛巾擦了擦脸上的汗水。","pinyin":"Tā gāng dǎ wán lánqiú mǎn tóu dàhàn, gǎnjǐn náqǐ máojīn cāle cā liǎn shang de hànshuǐ.","vi":"Cậu ấy vừa chơi bóng rổ xong mồ hôi nhễ nhại, vội vàng cầm khăn mặt lau mồ hôi trên mặt."}],"related":[{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"毛巾","pinyin":"máojīn","vi":"Khăn mặt"},{"hanzi":"橡皮","pinyin":"xiàngpí","vi":"Cục tẩy"},{"hanzi":"洗","pinyin":"xǐ","vi":"Rửa/Lau"},{"hanzi":"收拾","pinyin":"shōushi","vi":"Dọn dẹp"}]},{"id":"猜","hanzi":"猜","pinyin":"cāi","meaning_vi":"đoán, phỏng đoán","explanation":"Bộ khuyển 犭+ 青.","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"你猜猜这是谁送的礼物？","pinyin":"Nǐ cāi cai zhè shì shéi sòng de lǐwù?","vi":"Bạn đoán thử xem đây là quà ai tặng?"},{"type":"simple","zh":"看到地上全都是湿漉漉的，我猜昨天晚上肯定下了一场大雨。","pinyin":"Kàndào dìshang quándōu shì shīlùlù de, wǒ cāi zuótiān wǎnshang kěndìng xiàle yì chǎng dàyǔ.","vi":"Thấy mặt đất ướt sũng hết cả, tôi đoán tối qua chắc chắn đã có một trận mưa lớn."},{"type":"compound","zh":"阅读文章时如果遇到不认识的生词，可以先根据上下文猜猜它的意思。","pinyin":"Yuèdú wénzhāng shí rúguǒ yùdào bú rènshi de shēngcí, kěyǐ xiān gēnjù shàngxiàwén cāi cai tā de yìsi.","vi":"Khi đọc bài văn nếu gặp từ mới không biết, có thể dựa vào ngữ cảnh đoán thử nghĩa của nó trước."}],"related":[{"hanzi":"估计","pinyin":"gūjì","vi":"Ước tính"},{"hanzi":"判断","pinyin":"pànduàn","vi":"Phán đoán"},{"hanzi":"以为","pinyin":"yǐwéi","vi":"Tưởng rằng"},{"hanzi":"也许","pinyin":"yěxǔ","vi":"Có lẽ"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có thể"}]},{"id":"材料","hanzi":"材料","pinyin":"cáiliào","meaning_vi":"tài liệu, nguyên liệu, vật liệu","explanation":"材 (gỗ/chất liệu) + 料 (vật liệu).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"📂","examples":[{"type":"basic","zh":"申请签证的材料已经准备好了。","pinyin":"Shēnqǐng qiānzhèng de cáiliào yǐjīng zhǔnbèihǎo le.","vi":"Hồ sơ xin thị thực đã chuẩn bị xong rồi."},{"type":"simple","zh":"在开始做蛋糕之前，妈妈先把鸡蛋、面粉和牛奶等材料摆在了桌子上。","pinyin":"Zài kāishǐ zuò dàngāo zhīqián, māma xiān bǎ jīdàn, miànfěn hé niúnǎi děng cáiliào bǎi zài le zhuōzi shang.","vi":"Trước khi bắt đầu làm bánh kem, mẹ bày sẵn các nguyên liệu như trứng gà, bột mì và sữa bò lên trên bàn."},{"type":"compound","zh":"因为这家工厂坚持使用环保材料生产家具，所以产品非常受消费者欢迎。","pinyin":"Yīnwèi zhè jiā gōngchǎng jiānchí shǐyòng huánbǎo cáiliào shēngchǎn jiājù, suǒyǐ chǎnpǐn fēicháng shòu xiāofèizhě huānyíng.","vi":"Vì nhà máy này kiên trì dùng vật liệu thân thiện môi trường để sản xuất nội thất nên sản phẩm rất được người tiêu dùng ưa chuộng."}],"related":[{"hanzi":"资料","pinyin":"zīliào","vi":"Tài liệu"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"Đồ uống"},{"hanzi":"家具","pinyin":"jiājù","vi":"Đồ nội thất"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"Chuẩn bị"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"Xin/Nộp đơn"}]},{"id":"餐厅","hanzi":"餐厅","pinyin":"cāntīng","meaning_vi":"nhà ăn, phòng ăn, nhà hàng","explanation":"餐 (bữa ăn) + 厅 (phòng lớn).","hsk_level":3,"tags":["danh-tu","dia-diem","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"中午我们在学校餐厅吃饭。","pinyin":"Zhōngwǔ wǒmen zài xuéxiào cāntīng chīfàn.","vi":"Buổi trưa chúng tôi ăn cơm ở nhà ăn trường học."},{"type":"simple","zh":"这家新开的中餐厅不仅装修漂亮，而且服务员的态度也特别热情。","pinyin":"Zhè jiā xīn kāi de zhōng cāntīng bùjǐn zhuāngxiū piàoliang, érqiě fúwùyuán de tàidu yě tèbié rèqíng.","vi":"Nhà hàng Trung Hoa mới mở này không chỉ trang trí đẹp mắt mà thái độ nhân viên phục vụ cũng đặc biệt niềm nở."},{"type":"compound","zh":"因为周末晚上去那家著名餐厅吃饭的人特别多，所以我们最好提前打电话预订座位。","pinyin":"Yīnwèi zhōumò wǎnshang qù nà jiā zhùmíng cāntīng chīfàn de rén tèbié duō, suǒyǐ wǒmen zuìhǎo tíqián dǎdiànhuà yùdìng zuòwèi.","vi":"Vì tối cuối tuần người đến nhà hàng nổi tiếng đó ăn cơm đặc biệt đông nên tốt nhất chúng ta gọi điện đặt bàn trước."}],"related":[{"hanzi":"饭店","pinyin":"fàndiàn","vi":"Nhà hàng"},{"hanzi":"客厅","pinyin":"kètīng","vi":"Phòng khách"},{"hanzi":"厨房","pinyin":"chúfáng","vi":"Nhà bếp"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"Ăn cơm"},{"hanzi":"菜单","pinyin":"càidān","vi":"Thực đơn"}],"traditional":"餐廳"},{"id":"厕所","hanzi":"厕所","pinyin":"cèsuǒ","meaning_vi":"nhà vệ sinh","explanation":"厕 + 所 (nơi chốn).","hsk_level":3,"tags":["danh-tu","dia-diem","nha-cua"],"image":"🚻","examples":[{"type":"basic","zh":"请问，厕所在哪儿？","pinyin":"Qǐngwèn, cèsuǒ zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu ạ?"},{"type":"simple","zh":"在公共场所使用完厕所以后，大家一定要记得冲水并把双手洗干净。","pinyin":"Zài gōnggòngchǎngsuǒ shǐyòng wán cèsuǒ yǐhòu, dàjiā yídìngyào jìde chōngshuǐ bìng bǎ shuāng shǒuxǐ gānjìng.","vi":"Sau khi sử dụng nhà vệ sinh ở nơi công cộng, mọi người nhất định phải nhớ xả nước và rửa sạch hai tay."},{"type":"compound","zh":"虽然这个公园的面积非常大，但是每个路口都有清晰的指示牌告诉你厕所在哪个方向。","pinyin":"Suīrán zhè ge gōngyuán de miànjī fēicháng dà, dànshì měi ge lùkǒu dōu yǒu qīngxī de zhǐshìpái gàosu nǐ cèsuǒ zài nǎ ge fāngxiàng.","vi":"Tuy diện tích công viên này rất rộng nhưng mỗi ngã rẽ đều có biển chỉ dẫn rõ ràng cho biết nhà vệ sinh ở hướng nào."}],"related":[{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"Nhà vệ sinh"},{"hanzi":"洗手间","pinyin":"xǐshǒujiān","vi":"Phòng vệ sinh"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"}],"traditional":"廁所"},{"id":"差不多","hanzi":"差不多","pinyin":"chàbuduō","meaning_vi":"xấp xỉ, gần như, tạm ổn","explanation":"差 (kém/thiếu) + 不 + 多 (nhiều).","hsk_level":3,"tags":["pho-tu","tinh-tu"],"image":"≈","examples":[{"type":"basic","zh":"我们俩的汉语水平差不多。","pinyin":"Wǒmen liǎ de Hànyǔ shuǐpíng chàbuduō.","vi":"Trình độ tiếng Trung của hai đứa mình xấp xỉ nhau."},{"type":"simple","zh":"从我家坐公共汽车到公司，路上差不多需要四十分钟左右。","pinyin":"Cóng wǒ jiā zuò gōnggòngqìchē dào gōngsī, lùshang chàbuduō xūyào sìshí fēnzhōng zuǒyòu.","vi":"Đi xe buýt từ nhà tôi đến công ty mất khoảng chừng 40 phút."},{"type":"compound","zh":"虽然这件衬衫和那件衬衫的款式差不多，但是这件的面料穿起来更舒服。","pinyin":"Suīrán zhè jiàn chènshān hé nà jiàn chènshān de kuǎnshì chàbuduō, dànshì zhè jiàn de miànliào chuān qǐlái gèng shūfu.","vi":"Tuy kiểu dáng chiếc áo sơ mi này và chiếc kia xấp xỉ nhau nhưng chất liệu chiếc này mặc lên thoải mái hơn."}],"related":[{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"大约","pinyin":"dàyuē","vi":"Ước chừng"},{"hanzi":"左右","pinyin":"zuǒyòu","vi":"Khoảng"},{"hanzi":"几乎","pinyin":"jīhū","vi":"Hầu như"},{"hanzi":"一样","pinyin":"yíyàng","vi":"Giống nhau"}]},{"id":"长城","hanzi":"长城","pinyin":"Chángchéng","meaning_vi":"Vạn Lý Trường Thành","explanation":"长 (dài) + 城 (thành lũy).","hsk_level":3,"tags":["danh-tu","dia-danh","du-lich"],"image":"🏯","examples":[{"type":"basic","zh":"不到长城非好汉。","pinyin":"Búdào Chángchéng fēi hǎohàn.","vi":"Chưa đến Trường Thành chưa phải hảo hán."},{"type":"simple","zh":"万里长城是世界著名的历史文化遗产，每年吸引着无数中外游客。","pinyin":"Wànlǐchángchéng shì shìjiè zhùmíng de lìshǐ wénhuà yíchǎn, měinián xīyǐnzhe wúshù zhōngwài yóukè.","vi":"Vạn Lý Trường Thành là di sản văn hóa lịch sử nổi tiếng thế giới, hằng năm thu hút vô số du khách trong và ngoài nước."},{"type":"compound","zh":"虽然爬长城的时候台阶又高又陡让人很累，但是站在烽火台上看到的风景壮观极了。","pinyin":"Suīrán pá Chángchéng de shíhou táijiē yòu gāo yòu dǒu ràng rén hěn lèi, dànshì zhàn zài fēnghuǒ tái shang kàndào de fēngjǐng zhuàngguān jíle.","vi":"Tuy lúc leo Trường Thành bậc thang vừa cao vừa dốc khiến người ta rất mệt nhưng đứng trên đài phong hỏa ngắm phong cảnh thì hùng vĩ vô cùng."}],"related":[{"hanzi":"北京","pinyin":"Běijīng","vi":"Bắc Kinh"},{"hanzi":"长江","pinyin":"Chángjiāng","vi":"Sông Trường Giang"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"Nổi tiếng"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"}],"traditional":"長城"},{"id":"长江","hanzi":"长江","pinyin":"Chángjiāng","meaning_vi":"sông Trường Giang (Dương Tử)","explanation":"长 (dài) + 江 (sông lớn).","hsk_level":3,"tags":["danh-tu","dia-danh","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"长江是中国第一大河。","pinyin":"Chángjiāng shì Zhōngguó dìyī dàhé.","vi":"Trường Giang là con sông lớn nhất Trung Quốc."},{"type":"simple","zh":"长江和黄河是中华民族的两条母亲河，孕育了灿烂的中华文明。","pinyin":"Chángjiāng hé Huánghé shì Zhōnghuámínzú de liǎng tiáo mǔqīnhé, yùnyùle cànlàn de zhōnghuáwénmíng.","vi":"Trường Giang và Hoàng Hà là hai dòng sông mẹ của dân tộc Trung Hoa, nuôi dưỡng nền văn minh Trung Hoa rực rỡ."},{"type":"compound","zh":"长江全长六千三百多公里，流经中国多个省市，最后在上海注入东海。","pinyin":"Chángjiāng quáncháng liù qiān sān bǎi duō gōnglǐ, liújīng Zhōngguó duōge shěngshì, zuìhòu zài Shànghǎi zhùrù Dōnghǎi.","vi":"Sông Trường Giang dài hơn 6.300 km, chảy qua nhiều tỉnh thành Trung Quốc và cuối cùng đổ ra biển Đông Hải tại Thượng Hải."}],"related":[{"hanzi":"长城","pinyin":"Chángchéng","vi":"Vạn Lý Trường Thành"},{"hanzi":"河","pinyin":"hé","vi":"Sông"},{"hanzi":"海","pinyin":"hǎi","vi":"Biển"},{"hanzi":"公里","pinyin":"gōnglǐ","vi":"Ki-lô-mét"},{"hanzi":"省","pinyin":"shěng","vi":"Tỉnh"}],"traditional":"長江"},{"id":"场","hanzi":"场","pinyin":"chǎng","meaning_vi":"trận, buổi, suất (lượng từ)","explanation":"Lượng từ cho trận đấu, buổi biểu diễn, bộ phim (一场雨, 一场比赛).","hsk_level":3,"tags":["luong-tu"],"image":"🏟️","examples":[{"type":"basic","zh":"昨天下午下了一场大雨。","pinyin":"Zuótiān xiàwǔ xiàle yì chǎng dàyǔ.","vi":"Chiều hôm qua đã đổ một trận mưa lớn."},{"type":"simple","zh":"我们明天晚上去看一场电影吧。","pinyin":"Wǒmen míngtiān wǎnshang qù kàn yì chǎng diànyǐng ba.","vi":"Tối mai chúng ta đi xem một suất phim nhé."},{"type":"compound","zh":"虽然昨晚这场足球比赛的结果让我们队输了，但是全场比赛踢得非常精彩。","pinyin":"Suīrán zuówǎn zhè chǎng zúqiú bǐsài de jiéguǒ ràng wǒmen duì shū le, dànshì quánchǎng bǐsài tī de fēicháng jīngcǎi.","vi":"Tuy kết quả trận bóng đá tối qua đội chúng tôi thua nhưng cả trận đấu diễn ra vô cùng đặc sắc."}],"related":[{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"Biểu diễn"},{"hanzi":"遍","pinyin":"biàn","vi":"Lượt"},{"hanzi":"趟","pinyin":"tàng","vi":"Chuyến"}],"traditional":"場"},{"id":"吵","hanzi":"吵","pinyin":"chǎo","meaning_vi":"ồn ào, cãi nhau","explanation":"Bộ khẩu 口 + 少.","hsk_level":3,"tags":["tinh-tu","dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"外面太吵了，我睡不着觉。","pinyin":"Wàimiàn tài chǎo le, wǒ shuìbùzháo jiào.","vi":"Bên ngoài ồn ào quá, tôi không ngủ được."},{"type":"simple","zh":"图书馆里大家都在安静地看书，请不要在这里大声吵闹。","pinyin":"Túshūguǎn lǐ dàjiā dōu zài ānjìng de kànshū, qǐng bú yào zài zhèlǐ dàshēng chǎonào.","vi":"Trong thư viện mọi người đều đang yên lặng đọc sách, xin đừng làm ồn lớn tiếng ở đây."},{"type":"compound","zh":"好朋友之间遇到意见不合时应该冷静商量，千万不要因为一点儿小事就吵架。","pinyin":"Hǎopéngyou zhījiān yùdào yìjiàn bù héshí yīnggāi lěngjìng shāngliang, qiānwàn bú yào yīnwèi yìdiǎnr xiǎoshì jiù chǎojià.","vi":"Giữa bạn thân với nhau khi bất đồng ý kiến nên bình tĩnh bàn bạc, đừng bao giờ cãi nhau chỉ vì chút chuyện nhỏ."}],"related":[{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"热闹","pinyin":"rènao","vi":"Náo nhiệt"},{"hanzi":"响","pinyin":"xiǎng","vi":"Vang/Kêu"},{"hanzi":"醒","pinyin":"xǐng","vi":"Tỉnh giấc"},{"hanzi":"脾气","pinyin":"píqi","vi":"Tính khí"}]},{"id":"衬衫","hanzi":"衬衫","pinyin":"chènshān","meaning_vi":"áo sơ mi","explanation":"Cả hai chữ đều có bộ y 衤(quần áo).","hsk_level":3,"tags":["danh-tu","trang-phuc"],"image":"👔","examples":[{"type":"basic","zh":"爸爸穿了一件白色的衬衫。","pinyin":"Bàba chuānle yí jiàn báisè de chènshān.","vi":"Bố mặc một chiếc áo sơ mi màu trắng."},{"type":"simple","zh":"这件纯棉衬衫不仅款式简单大方，而且穿在身上非常透气舒服。","pinyin":"Zhè jiàn chúnmián chènshān bùjǐn kuǎnshì jiǎndān dàfāng, érqiě chuān zài shēnshang fēicháng tòuqì shūfu.","vi":"Chiếc áo sơ mi cotton này không chỉ kiểu dáng đơn giản thanh lịch mà mặc lên người còn rất thoáng khí dễ chịu."},{"type":"compound","zh":"因为明天要去一家大公司参加正式面试，所以我今晚提前把衬衫熨烫整齐。","pinyin":"Yīnwèi míngtiān yào qù yìjiā dàgōngsī cānjiā zhèngshì miànshì, suǒyǐ wǒ jīnwǎn tíqián bǎ chènshān yùntàng zhěngqí.","vi":"Vì ngày mai phải đến một công ty lớn phỏng vấn chính thức nên tối nay tôi đã là phẳng phiu áo sơ mi trước."}],"related":[{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"袜子","pinyin":"wàzi","vi":"Tất"},{"hanzi":"穿","pinyin":"chuān","vi":"Mặc"},{"hanzi":"正式","pinyin":"zhèngshì","vi":"Chính thức"},{"hanzi":"合适","pinyin":"héshì","vi":"Thích hợp"}],"traditional":"襯衫"},{"id":"成熟","hanzi":"成熟","pinyin":"chéngshú","meaning_vi":"chín (quả); chín chắn, trưởng thành; chín muồi (điều kiện)","explanation":"成 (thành) + 熟 (chín).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🌾","examples":[{"type":"basic","zh":"秋天到了，苹果都成熟了。","pinyin":"Qiūtiān dào le, píngguǒ dōu chéngshú le.","vi":"Mùa thu đến rồi, táo đều chín rộ hết rồi."},{"type":"simple","zh":"经过几年在外的独立生活，弟弟比以前懂事和成熟了很多。","pinyin":"Jīngguò jǐ nián zài wài de dúlì shēnghuó, dìdi bǐ yǐqián dǒngshì hé chéngshúle hěn duō.","vi":"Trải qua mấy năm sống tự lập bên ngoài, em trai hiểu chuyện và chín chắn hơn trước đây nhiều."},{"type":"compound","zh":"虽然这个新产品的想法很有创意，但是目前技术条件还不够成熟，需要继续研究。","pinyin":"Suīrán zhè ge xīnchǎnpǐn de xiǎngfǎ hěn yǒu chuàngyì, dànshì mùqián jìshù tiáojiàn hái búgòu chéngshú, xūyào jìxù yánjiū.","vi":"Tuy ý tưởng của sản phẩm mới này rất sáng tạo nhưng hiện tại điều kiện kỹ thuật vẫn chưa đủ chín muồi, cần tiếp tục nghiên cứu."}],"related":[{"hanzi":"熟悉","pinyin":"shúxī","vi":"Quen thuộc"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"Trẻ tuổi"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"苹果","pinyin":"píngguǒ","vi":"Quả táo"}]},{"id":"诚实","hanzi":"诚实","pinyin":"chéngshí","meaning_vi":"thành thật, trung thực","explanation":"诚 (chân thành) + 实 (thật thà).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🤝","examples":[{"type":"basic","zh":"他是一个非常诚实的孩子。","pinyin":"Tā shì yí ge fēicháng chéngshí de háizi.","vi":"Cậu bé là một đứa trẻ vô cùng trung thực."},{"type":"simple","zh":"在考试的时候必须诚实守信，绝对不能抄袭别人的答案。","pinyin":"Zài kǎoshì de shíhou bìxū chéngshí shǒuxìn, juéduì bù néng chāoxí biérén de dá'àn.","vi":"Trong lúc thi cử bắt buộc phải trung thực giữ chữ tín, tuyệt đối không được chép đáp án của người khác."},{"type":"compound","zh":"虽然承认自己的错误需要很大的勇气，但是诚实的人永远最值得别人信赖。","pinyin":"Suīrán chéngrèn zìjǐ de cuòwù xūyào hěn dà de yǒngqì, dànshì chéngshí de rén yǒngyuǎn zuì zhíde biérén xìnlài.","vi":"Tuy thừa nhận sai lầm của bản thân cần lòng dũng cảm lớn nhưng người trung thực luôn đáng tin cậy nhất."}],"related":[{"hanzi":"骗","pinyin":"piàn","vi":"Lừa dối"},{"hanzi":"实际","pinyin":"shíjì","vi":"Thực tế"},{"hanzi":"实在","pinyin":"shízài","vi":"Chân thật"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"Dũng cảm"}],"traditional":"誠實"},{"id":"重新","hanzi":"重新","pinyin":"chóngxīn","meaning_vi":"lại, làm lại (từ đầu)","explanation":"重 (đọc chóng - lặp lại) + 新 (mới).","hsk_level":3,"tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"写错了没关系，我们重新写一遍。","pinyin":"Xiě cuòle méiguānxi, wǒmen chóngxīn xiě yíbiàn.","vi":"Viết sai không sao đâu, chúng ta viết lại một lượt nhé."},{"type":"simple","zh":"电脑突然死机了，刚才写的报告没保存，只好打开文档重新写。","pinyin":"Diànnǎo tūrán sǐjī le, gāngcái xiě de bàogào méi bǎocún, zhǐhǎo dǎkāi wéndàng chóngxīn xiě.","vi":"Máy tính đột nhiên bị treo, bản báo cáo vừa viết chưa kịp lưu nên đành mở file ra viết lại từ đầu."},{"type":"compound","zh":"因为原定的火车票卖光了，所以我们不得不重新安排这次旅游的出发时间。","pinyin":"Yīnwèi yuándìng de huǒchēpiào màiguāngle, suǒyǐ wǒmen bùdébù chóngxīn ānpái zhè cì lǚyóu de chūfā shíjiān.","vi":"Vì vé tàu dự kiến ban đầu đã bán hết sạch nên chúng tôi đành phải sắp xếp lại thời gian khởi hành của chuyến du lịch này."}],"related":[{"hanzi":"重","pinyin":"zhòng","vi":"Nặng/Trọng"},{"hanzi":"新","pinyin":"xīn","vi":"Mới"},{"hanzi":"遍","pinyin":"biàn","vi":"Lượt"},{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"},{"hanzi":"改变","pinyin":"gǎibiàn","vi":"Thay đổi"}]},{"id":"抽烟","hanzi":"抽烟","pinyin":"chōuyān","meaning_vi":"hút thuốc lá","explanation":"抽 (hút/rút) + 烟 (khói/thuốc lá). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","suc-khoe"],"image":"🚬","examples":[{"type":"basic","zh":"公共场所禁止抽烟。","pinyin":"Gōnggòngchǎngsuǒ jìnzhǐ chōuyān.","vi":"Nơi công cộng cấm hút thuốc lá."},{"type":"simple","zh":"抽烟不仅危害自己的肺部健康，还会让周围的人吸进二手烟。","pinyin":"Chōuyān bùjǐn wēihài zìjǐ de fèi bù jiànkāng, hái huì ràng zhōuwéi de rén xījìn èrshǒuyān.","vi":"Hút thuốc lá không những gây hại cho sức khỏe phổi của bản thân mà còn khiến người xung quanh hít phải khói thuốc thụ động."},{"type":"compound","zh":"为了家人和自己的身体健康，爸爸今年下定决心把抽了二十年的烟戒掉了。","pinyin":"Wèile jiārén hé zìjǐ de shēntǐ jiànkāng, bàba jīnnián xiàdìng juéxīn bǎ chōule èrshí nián de yān jièdiào le.","vi":"Vì sức khỏe của gia đình và bản thân, năm nay bố đã hạ quyết tâm bỏ hẳn thuốc lá sau 20 năm hút thuốc."}],"related":[{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"Cấm"},{"hanzi":"咳嗽","pinyin":"késou","vi":"Ho"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"},{"hanzi":"空气","pinyin":"kōngqì","vi":"Không khí"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"Cho phép"}],"traditional":"抽煙"},{"id":"出差","hanzi":"出差","pinyin":"chūchāi","meaning_vi":"đi công tác","explanation":"出 (ra ngoài) + 差 (đọc chāi - công vụ). Động từ ly hợp.","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"🧳","examples":[{"type":"basic","zh":"爸爸下周要去上海出差。","pinyin":"Bàba xiàzhōu yào qù Shànghǎi chūchāi.","vi":"Tuần sau bố phải đi Thượng Hải công tác."},{"type":"simple","zh":"因为公司业务需要，王经理每个月都要坐飞机去全国各地出差。","pinyin":"Yīnwèi gōngsī yèwù xūyào, Wáng jīnglǐ měi geyuè dōu yào zuòfēijī qù quánguó gèdì chūchāi.","vi":"Vì nhu cầu công việc của công ty, giám đốc Vương mỗi tháng đều phải đi máy bay tới khắp các tỉnh thành công tác."},{"type":"compound","zh":"虽然经常出差很辛苦，但是每次出差回来爸爸都会给我们带各地的特色小吃。","pinyin":"Suīrán jīngcháng chūchāi hěn xīnkǔ, dànshì měi cì chūchāi huílái bàba dōuhuì gěi wǒmen dài gèdì de tèsè xiǎochī.","vi":"Tuy thường xuyên đi công tác rất vất vả nhưng mỗi lần đi công tác về bố đều mang đặc sản các vùng miền cho chúng tôi."}],"related":[{"hanzi":"出发","pinyin":"chūfā","vi":"Xuất phát"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"航班","pinyin":"hángbān","vi":"Chuyến bay"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"}]},{"id":"厨房","hanzi":"厨房","pinyin":"chúfáng","meaning_vi":"nhà bếp, phòng bếp","explanation":"厨 (bếp) + 房 (phòng).","hsk_level":3,"tags":["danh-tu","dia-diem","nha-cua"],"image":"🍳","examples":[{"type":"basic","zh":"妈妈正在厨房里做晚饭。","pinyin":"Māma zhèngzài chúfáng lǐ zuò wǎnfàn.","vi":"Mẹ đang nấu bữa tối trong nhà bếp."},{"type":"simple","zh":"我们家的厨房虽然面积不大，但是各种锅碗瓢盆摆放得非常整齐。","pinyin":"Wǒmen jiā de chúfáng suīrán miànjī búdà, dànshì gèzhǒng guō wǎn piáo pén bǎifàng de fēicháng zhěngqí.","vi":"Nhà bếp nhà tôi tuy diện tích không lớn nhưng các loại xoong nồi bát đĩa được sắp xếp vô cùng ngăn nắp."},{"type":"compound","zh":"每次做完饭以后，爸爸都会主动把厨房的灶台和地板擦得干干净净。","pinyin":"Měi cì zuòwán fàn yǐhòu, bàba dōuhuì zhǔdòng bǎ chúfáng de zàotái hé dì bǎncā de gān gānjìng jìng.","vi":"Mỗi lần nấu cơm xong, bố đều chủ động lau sạch bếp nấu và sàn nhà bếp tinh tươm."}],"related":[{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"},{"hanzi":"客厅","pinyin":"kètīng","vi":"Phòng khách"},{"hanzi":"做饭","pinyin":"zuòfàn","vi":"Nấu cơm"},{"hanzi":"碗","pinyin":"wǎn","vi":"Cái bát"},{"hanzi":"勺子","pinyin":"sháozi","vi":"Cái thìa"}],"traditional":"廚房"},{"id":"传真","hanzi":"传真","pinyin":"chuánzhēn","meaning_vi":"bản fax; gửi fax","explanation":"传 (truyền) + 真 (bản thật).","hsk_level":3,"tags":["danh-tu","cong-nghe","cong-viec"],"image":"📠","examples":[{"type":"basic","zh":"请把这份合同传真给我。","pinyin":"Qǐng bǎ zhè fèn hétong chuánzhēn gěi wǒ.","vi":"Xin hãy fax bản hợp đồng này cho tôi."},{"type":"simple","zh":"虽然现在大家都习惯用电子邮件发文件，但是有些机构仍然需要传真件。","pinyin":"Suīrán xiànzài dàjiā dōu xí guànyòng diànzǐ yóujiàn fā wénjiàn, dànshì yǒuxiē jīgòu réngrán xūyào chuánzhēn jiàn.","vi":"Tuy hiện nay mọi người đều quen gửi tài liệu qua email nhưng một số cơ quan vẫn yêu cầu bản fax."},{"type":"compound","zh":"我已经把签好字的确认表格通过传真发过去了，请你查收一下。","pinyin":"Wǒ yǐjīng bǎ qiān hǎo zì de quèrèn biǎogé tōngguò chuánzhēn fā guòqù le, qǐng nǐ cháshōu yíxià.","vi":"Tôi đã gửi biểu mẫu xác nhận đã ký tên qua máy fax rồi, xin bạn kiểm tra nhận giúp nhé."}],"related":[{"hanzi":"传播","pinyin":"chuánbō","vi":"Truyền bá"},{"hanzi":"真正","pinyin":"zhēnzhèng","vi":"Chân chính"},{"hanzi":"打印","pinyin":"dǎyìn","vi":"In ấn"},{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"Văn phòng"},{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"}],"traditional":"傳真"},{"id":"词语","hanzi":"词语","pinyin":"cíyǔ","meaning_vi":"từ ngữ","explanation":"词 (từ – từ) + 语 (ngữ – lời nói, ngôn ngữ) → từ ngữ nói chung, gồm cả từ và cụm từ.","hsk_level":3,"tags":["danh-tu","hoc-tap","ngon-ngu"],"image":"🔤","examples":[{"type":"basic","zh":"请用这些新词语造句。","pinyin":"Qǐng yòng zhèxiē xīn cíyǔ zàojù.","vi":"Xin hãy dùng những từ ngữ mới này để đặt câu."},{"type":"simple","zh":"学习汉语的时候，不仅要记住单个汉字的意思，更要掌握常用词语的搭配。","pinyin":"Xuéxí Hànyǔ de shíhou, bùjǐn yào jìzhu dānge hànzì de yìsi, gèng yào zhǎngwò chángyòng cíyǔ de dāpèi.","vi":"Khi học tiếng Trung, không chỉ cần nhớ nghĩa từng chữ Hán đơn lẻ mà còn phải nắm vững cách kết hợp các từ ngữ thông dụng."},{"type":"compound","zh":"每次读完一篇中文文章，我都会把里面优美的词语摘抄到笔记本上。","pinyin":"Měi cì dú wán yì piān Zhōngwén wénzhāng, wǒ dōuhuì bǎ lǐmiàn yōuměi de cíyǔ zhāichāo dào bǐjìběn shang.","vi":"Mỗi lần đọc xong một bài văn tiếng Trung, tôi đều chép lại những từ ngữ hay bên trong vào cuốn sổ tay."}],"related":[{"hanzi":"词典","pinyin":"cídiǎn","vi":"Từ điển"},{"hanzi":"语言","pinyin":"yǔyán","vi":"Ngôn ngữ"},{"hanzi":"语法","pinyin":"yǔfǎ","vi":"Ngữ pháp"},{"hanzi":"汉语","pinyin":"Hànyǔ","vi":"Tiếng Trung"},{"hanzi":"句子","pinyin":"jùzi","vi":"Câu"}],"traditional":"詞語"},{"id":"从来","hanzi":"从来","pinyin":"cónglái","meaning_vi":"từ trước tới nay","explanation":"从 (từ) + 来 (đến). Thường dùng trong câu phủ định (从来不 / 从来没).","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"♾️","examples":[{"type":"basic","zh":"他从来不迟到。","pinyin":"Tā cóngláibù chídào.","vi":"Anh ấy từ trước tới nay không bao giờ đến muộn."},{"type":"simple","zh":"我以前从来没有吃过这么正宗的北京烤鸭，味道真是太棒了！","pinyin":"Wǒ yǐqián cónglái méiyǒu chīguo zhème zhèngzōng de Běijīngkǎoyā, wèidào zhēn shì tài bàng le!","vi":"Trước đây tôi chưa bao giờ được ăn vịt quay Bắc Kinh chuẩn vị như thế này, hương vị thật tuyệt vời!"},{"type":"compound","zh":"虽然学习汉语的道路上有很多困难，但是他从来没有产生过放弃的念头。","pinyin":"Suīrán xuéxí Hànyǔ de dào lùshang yǒu hěn duō kùnnan, dànshì tā cónglái méiyǒu chǎnshēngguo fàngqì de niàntou.","vi":"Tuy trên con đường học tiếng Trung có nhiều khó khăn nhưng anh ấy chưa bao giờ nảy sinh ý định bỏ cuộc."}],"related":[{"hanzi":"从","pinyin":"cóng","vi":"Từ"},{"hanzi":"永远","pinyin":"yǒngyuǎn","vi":"Mãi mãi"},{"hanzi":"一直","pinyin":"yìzhí","vi":"Luôn luôn"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"Lúc nào cũng"},{"hanzi":"原来","pinyin":"yuánlái","vi":"Vốn dĩ"}],"traditional":"從來"},{"id":"粗心","hanzi":"粗心","pinyin":"cūxīn","meaning_vi":"bất cẩn, cẩu thả","explanation":"粗 (thô/sơ sài) + 心 (tâm trí). Đối nghĩa với 细心 (cẩn thận).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🙈","examples":[{"type":"basic","zh":"他做题太粗心了。","pinyin":"Tā zuò tí tài cūxīn le.","vi":"Cậu ấy làm bài bất cẩn quá."},{"type":"simple","zh":"这次考试他因为粗心大意，漏看了一道阅读理解题，非常可惜。","pinyin":"Zhè cì kǎoshì tā yīnwèi cūxīndàyì, lòu kànle yídào yuèdú lǐjiě tí, fēicháng kěxī.","vi":"Kỳ thi lần này vì bất cẩn lơ đễnh, cậu ấy đã nhìn sót một câu đọc hiểu, vô cùng đáng tiếc."},{"type":"compound","zh":"在银行或者财务部门工作必须非常细心，如果粗心弄错一个数字就会造成大麻烦。","pinyin":"Zài yínháng huòzhě cáiwù bùmén gōngzuò bìxū fēicháng xìxīn, rúguǒ cūxīn nòngcuò yí ge shùzì jiù huì zào Chéngdà máfan.","vi":"Làm việc ở ngân hàng hoặc phòng tài chính bắt buộc phải cực kỳ tỉ mỉ, nếu bất cẩn làm sai một con số sẽ gây ra rắc rối lớn."}],"related":[{"hanzi":"马虎","pinyin":"mǎhu","vi":"Qua loa"},{"hanzi":"仔细","pinyin":"zǐxì","vi":"Cẩn thận"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"错误","pinyin":"cuòwù","vi":"Sai lầm"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"Cẩn thận"}]},{"id":"存","hanzi":"存","pinyin":"cún","meaning_vi":"gửi (tiền), lưu giữ, tồn tại","explanation":"Cụm: 存钱 (gửi tiền tiết kiệm), 保存 (lưu giữ).","hsk_level":3,"tags":["dong-tu","tien-te"],"image":"🏦","examples":[{"type":"basic","zh":"我去银行存点儿钱。","pinyin":"Wǒqù yínháng cún diǎnr qián.","vi":"Tôi đi ngân hàng gửi một ít tiền."},{"type":"simple","zh":"爸爸每个月都会把一部分工资存进银行，为将来买房子做准备。","pinyin":"Bàba měi geyuè dōuhuì bǎ yíbùfen gōngzī cún jìn yínháng, wéi jiānglái mǎi fángzi zuò zhǔnbèi.","vi":"Bố mỗi tháng đều gửi một phần tiền lương vào ngân hàng để chuẩn bị cho việc mua nhà sau này."},{"type":"compound","zh":"用电脑写完重要文章以后，一定要记得及时保存文件，以免突然停电丢失数据。","pinyin":"Yòng diànnǎo xiěwán zhòngyào wénzhāng yǐhòu, yídìngyào jìde jíshí bǎocún wénjiàn, yǐmiǎn tūrán tíngdiàn diūshī shùjù.","vi":"Sau khi viết xong bài văn quan trọng trên máy tính, nhất định phải nhớ lưu file kịp thời để tránh mất điện đột ngột làm mất dữ liệu."}],"related":[{"hanzi":"取","pinyin":"qǔ","vi":"Rút (tiền)"},{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"工资","pinyin":"gōngzī","vi":"Tiền lương"},{"hanzi":"保存","pinyin":"bǎocún","vi":"Bảo tồn/Lưu giữ"}]},{"id":"错误","hanzi":"错误","pinyin":"cuòwù","meaning_vi":"sai lầm, lỗi sai","explanation":"错 (sai) + 误 (nhầm lẫn). Vừa là danh từ vừa là tính từ.","hsk_level":3,"tags":["danh-tu","tinh-tu"],"image":"❌","examples":[{"type":"basic","zh":"发现错误要及时改正。","pinyin":"Fāxiàn cuòwù yào jíshí gǎizhèng.","vi":"Phát hiện sai lầm phải sửa chữa kịp thời."},{"type":"simple","zh":"学习外语的过程中犯语法错误是很正常的，关键是要从错误中吸取教训。","pinyin":"Xuéxí wàiyǔ de guòchéng zhōng fàn yǔfǎ cuòwù shì hěn zhèngcháng de, guānjiàn shì yào cóng cuòwù zhōng xīqǔ jiàoxun.","vi":"Trong quá trình học ngoại ngữ, mắc lỗi ngữ pháp là điều rất bình thường, mấu chốt là phải rút ra bài học từ sai lầm."},{"type":"compound","zh":"老师用红笔把我作文里的几个错误词语改了过来，并在旁边写了详细的解释。","pinyin":"Lǎoshī yòng hóng bǐ bǎ wǒ zuòwén lǐ de jǐ ge cuòwù cíyǔ gǎile guòlái, bìng zài pángbiān xiěle xiángxì de jiěshì.","vi":"Thầy giáo dùng bút đỏ sửa lại mấy từ ngữ sai trong bài văn của tôi và viết giải thích chi tiết bên cạnh."}],"related":[{"hanzi":"错","pinyin":"cuò","vi":"Sai"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Đúng đắn"},{"hanzi":"误会","pinyin":"wùhuì","vi":"Hiểu lầm"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"},{"hanzi":"改正","pinyin":"gǎizhèng","vi":"Sửa chữa"}],"traditional":"錯誤"},{"id":"答案","hanzi":"答案","pinyin":"dá'àn","meaning_vi":"đáp án, câu trả lời","explanation":"答 (trả lời) + 案 (phương án).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"✅","examples":[{"type":"basic","zh":"这道题的答案是什么？","pinyin":"Zhè dào tí de dá'àn shì shénme?","vi":"Đáp án của câu hỏi này là gì?"},{"type":"simple","zh":"做完练习题以后，我们可以翻到课本最后几页核对一下正确答案。","pinyin":"Zuòwán liànxí tí yǐhòu, wǒmen kěyǐ fān dào kèběn zuìhòu jǐ yè héduì yíxià zhèngquè dá'àn.","vi":"Sau khi làm xong bài tập luyện tập, chúng ta có thể lật ra mấy trang cuối sách giáo khoa để đối chiếu đáp án đúng."},{"type":"compound","zh":"虽然这道数学题看起来非常复杂，但是只要找对了思路，很快就能算出答案。","pinyin":"Suīrán zhè dào shùxué tí kànqǐlái fēicháng fùzá, dànshì zhǐyào zhǎo duìle sīlù, hěn kuài jiù néng suànchū dá'àn.","vi":"Tuy bài toán này trông rất phức tạp nhưng chỉ cần tìm đúng hướng giải thì chẳng mấy chốc sẽ tính ra đáp án."}],"related":[{"hanzi":"回答","pinyin":"huídá","vi":"Trả lời"},{"hanzi":"问题","pinyin":"wèntí","vi":"Câu hỏi"},{"hanzi":"正确","pinyin":"zhèngquè","vi":"Chính xác"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"填空","pinyin":"tiánkòng","vi":"Điền vào chỗ trống"}]},{"id":"大约","hanzi":"大约","pinyin":"dàyuē","meaning_vi":"khoảng chừng, ước chừng","explanation":"大 + 约 (ước lượng). Đồng nghĩa với 大概.","hsk_level":3,"tags":["pho-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"他大约三十岁左右。","pinyin":"Tā dàyuē sānshí suì zuǒyòu.","vi":"Anh ấy khoảng chừng 30 tuổi."},{"type":"simple","zh":"从河内坐飞机到北京，飞行时间大约需要三个半小时。","pinyin":"Cóng Hénèi zuòfēijī dào Běijīng, fēixíng shíjiān dàyuē xūyào sān ge bànxiǎoshí.","vi":"Đi máy bay từ Hà Nội đến Bắc Kinh, thời gian bay mất khoảng ba tiếng rưỡi."},{"type":"compound","zh":"虽然我记不清具体是哪一天了，但是这件事大约发生在去年秋天的时候。","pinyin":"Suīrán wǒ jì bùqīng jùtǐ shì nǎ yì tiān le, dànshì zhè jiàn shì dàyuē fāshēng zài qùnián qiūtiān de shíhou.","vi":"Tuy tôi không nhớ rõ cụ thể là ngày nào nhưng việc này xảy ra vào khoảng mùa thu năm ngoái."}],"related":[{"hanzi":"大概","pinyin":"dàgài","vi":"Đại khái"},{"hanzi":"左右","pinyin":"zuǒyòu","vi":"Khoảng chừng"},{"hanzi":"差不多","pinyin":"chàbuduō","vi":"Xấp xỉ"},{"hanzi":"约会","pinyin":"yuēhuì","vi":"Hẹn hò"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"}],"traditional":"大約"},{"id":"戴","hanzi":"戴","pinyin":"dài","meaning_vi":"đeo, đội (mũ/kính/đồng hồ)","explanation":"Dùng cho phụ kiện trên người (戴眼镜, 戴帽子, 戴手表).","hsk_level":3,"tags":["dong-tu","trang-phuc"],"image":"👓","examples":[{"type":"basic","zh":"他戴着一副黑框眼镜。","pinyin":"Tā dàizhe yí fù hēikuàng yǎnjìng.","vi":"Anh ấy đang đeo một cặp kính gọng đen."},{"type":"simple","zh":"冬天骑自行车出门时，戴上手套和帽子可以防止耳朵和手冻伤。","pinyin":"Dōngtiān qí zìxíngchē chūmén shí, dàishàng shǒutào hé màozi kěyǐ fángzhǐ ěrduo hé shǒu dòngshāng.","vi":"Mùa đông khi đạp xe ra ngoài, đeo găng tay và đội mũ có thể tránh cho tai và tay bị cóng lạnh."},{"type":"compound","zh":"因为在电脑前工作久了眼睛容易疲劳，所以我现在看屏幕时都会戴防蓝光眼镜。","pinyin":"Yīnwèi zài diànnǎo qián gōngzuò jiǔle yǎnjing róngyì píláo, suǒyǐ wǒ xiànzài kàn píngmù shí dōuhuì dài fáng Lánguāng yǎnjìng.","vi":"Vì làm việc lâu trước máy tính mắt dễ bị mỏi nên hiện giờ lúc nhìn màn hình tôi đều đeo kính chống ánh sáng xanh."}],"related":[{"hanzi":"穿","pinyin":"chuān","vi":"Mặc"},{"hanzi":"脱","pinyin":"tuō","vi":"Cởi"},{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"Kính mắt"},{"hanzi":"手表","pinyin":"shǒubiǎo","vi":"Đồng hồ"},{"hanzi":"带","pinyin":"dài","vi":"Mang theo"}]},{"id":"刀","hanzi":"刀","pinyin":"dāo","meaning_vi":"con dao","explanation":"Chữ tượng hình lưỡi dao.","hsk_level":3,"tags":["danh-tu","do-vat","an-uong"],"image":"🔪","examples":[{"type":"basic","zh":"这把刀很好用。","pinyin":"Zhè bǎ dāo hěn hǎoyòng.","vi":"Con dao này rất dễ dùng."},{"type":"simple","zh":"厨房里的这把菜刀非常锋利，用完以后要放在小孩子够不到的地方。","pinyin":"Chúfáng lǐ de zhè bǎ càidāo fēicháng fēnglì, yòngwán yǐhòu yào fàng zài xiǎoháizi gòu búdào de dìfang.","vi":"Con dao thái trong bếp này rất sắc bén, dùng xong phải để ở chỗ trẻ nhỏ không với tới được."},{"type":"compound","zh":"乘坐飞机或者高铁过安检时，水果刀和剪刀等危险物品是禁止随身携带的。","pinyin":"Chéngzuò fēijī huòzhě gāotiěguò ānjiǎn shí, shuǐguǒdāo hé jiǎndāo děng wēixiǎn wùpǐn shì jìnzhǐ suíshēn xiédài de.","vi":"Khi đi máy bay hoặc tàu cao tốc qua cửa kiểm tra an ninh, dao gọt hoa quả và kéo là những vật dụng nguy hiểm bị cấm mang theo người."}],"related":[{"hanzi":"勺子","pinyin":"sháozi","vi":"Cái thìa"},{"hanzi":"筷子","pinyin":"kuàizi","vi":"Đôi đũa"},{"hanzi":"厨房","pinyin":"chúfáng","vi":"Nhà bếp"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"Nguy hiểm"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"Cấm"}]},{"id":"导游","hanzi":"导游","pinyin":"dǎoyóu","meaning_vi":"hướng dẫn viên du lịch","explanation":"导 (dẫn đường) + 游 (du lịch).","hsk_level":3,"tags":["danh-tu","nghe-nghiep","du-lich"],"image":"🚩","examples":[{"type":"basic","zh":"我们的导游非常热情幽默。","pinyin":"Wǒmen de dǎoyóu fēicháng rèqíng yōumò.","vi":"Hướng dẫn viên du lịch của chúng tôi vô cùng nhiệt tình hài hước."},{"type":"simple","zh":"在导游的详细讲解下，我们了解了许多关于北京故宫的历史故事。","pinyin":"Zài dǎoyóu de xiángxì jiǎngjiě xià, wǒmen liǎojiěle xǔduō guānyú Běijīng gùgōng de lìshǐ gùshi.","vi":"Dưới sự thuyết minh chi tiết của hướng dẫn viên, chúng tôi đã hiểu thêm nhiều câu chuyện lịch sử về Cố Cung Bắc Kinh."},{"type":"compound","zh":"因为她不仅精通汉语和英语，而且非常喜欢旅游，所以毕业后当了一名国际导游。","pinyin":"Yīnwèi tā bùjǐn jīngtōng Hànyǔ hé Yīngyǔ, érqiě fēicháng xǐhuan lǚyóu, suǒyǐ bìyè hòu dāngle yì míng Guójì dǎoyóu.","vi":"Vì cô ấy không chỉ thông thạo tiếng Trung và tiếng Anh mà còn vô cùng thích du lịch nên sau khi tốt nghiệp đã làm hướng dẫn viên quốc tế."}],"related":[{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"旅行","pinyin":"lǚxíng","vi":"Chuyến đi"},{"hanzi":"游客","pinyin":"yóukè","vi":"Du khách"},{"hanzi":"介绍","pinyin":"jièshào","vi":"Giới thiệu"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"}],"traditional":"導遊"},{"id":"到处","hanzi":"到处","pinyin":"dàochù","meaning_vi":"khắp nơi, mọi chỗ","explanation":"到 (tới) + 处 (nơi chốn).","hsk_level":3,"tags":["pho-tu","dia-diem"],"image":"🗺️","examples":[{"type":"basic","zh":"春天来了，公园里到处都是鲜花。","pinyin":"Chūntiān lái le, gōngyuán lǐ dàochù dōu shì xiānhuā.","vi":"Mùa xuân đến rồi, trong công viên khắp nơi đều là hoa tươi."},{"type":"simple","zh":"过春节的时候，大街小巷到处挂满了红灯笼，充满了节日的喜庆气氛。","pinyin":"Guò Chūnjié de shíhou, dàjiēxiǎoxiàng dàochù guà mǎnle hóngdēnglong, chōngmǎnle jiérì de xǐqìng qìfēn.","vi":"Dịp Tết Nguyên đán, khắp các ngõ lớn phố nhỏ đều treo đầy đèn lồng đỏ, tràn ngập không khí vui mừng ngày lễ."},{"type":"compound","zh":"刚才他把房间里到处都找遍了，结果还是没有找到那把丢失的钥匙。","pinyin":"Gāngcái tā bǎ fángjiān lǐ dàochù dōu zhǎobiàn le, jiéguǒ háishi méiyǒu zhǎodào nà bǎ diūshī de yàoshi.","vi":"Vừa nãy anh ấy đã tìm khắp mọi ngóc ngách trong phòng nhưng kết quả vẫn không tìm thấy chiếc chìa khóa bị mất."}],"related":[{"hanzi":"处","pinyin":"chù","vi":"Nơi chốn"},{"hanzi":"好处","pinyin":"hǎochu","vi":"Lợi ích"},{"hanzi":"地方","pinyin":"dìfang","vi":"Địa phương"},{"hanzi":"到","pinyin":"dào","vi":"Đến"},{"hanzi":"周围","pinyin":"zhōuwéi","vi":"Xung quanh"}],"traditional":"到處"},{"id":"到底","hanzi":"到底","pinyin":"dàodǐ","meaning_vi":"rốt cuộc, đến cùng","explanation":"到 (tới) + 底 (đáy/cuối cùng).","hsk_level":3,"tags":["pho-tu","nghi-van"],"image":"❓","examples":[{"type":"basic","zh":"这件事到底是怎么回事？","pinyin":"Zhè jiàn shì dàodǐ shì zěnme huíshì?","vi":"Chuyện này rốt cuộc là thế nào vậy?"},{"type":"simple","zh":"只要我们坚持不懈地努力到底，就一定能够实现自己的理想。","pinyin":"Zhǐyào wǒmen jiānchíbúxiè de nǔlì dàodǐ, jiù yídìng nénggòu shíxiàn zìjǐ de lǐxiǎng.","vi":"Chỉ cần chúng ta kiên trì nỗ lực đến cùng thì nhất định sẽ thực hiện được lý tưởng của mình."},{"type":"compound","zh":"我已经给她打了十几个电话了，可是都没人接，真不知道她到底去哪儿了。","pinyin":"Wǒ yǐjīng gěi tā dǎle shíjǐ ge diànhuà le, kěshì dōu méi rén jiē, zhēn bù zhīdao tā dàodǐ qùnǎr le.","vi":"Tôi đã gọi cho cô ấy mười mấy cuộc điện thoại rồi mà không ai nghe máy, thật không biết rốt cuộc cô ấy đã đi đâu."}],"related":[{"hanzi":"究竟","pinyin":"jiūjìng","vi":"Rốt cuộc"},{"hanzi":"底","pinyin":"dǐ","vi":"Đáy/Cuối"},{"hanzi":"到达","pinyin":"dàodá","vi":"Đến nơi"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"Kiên trì"},{"hanzi":"难道","pinyin":"nándào","vi":"Chẳng lẽ"}]},{"id":"倒","hanzi":"倒","pinyin":"dǎo","meaning_vi":"ngã, đổ, sập","explanation":"Đọc dǎo khi nghĩa là ngã/đổ; đọc dào khi nghĩa là rót (倒水).","hsk_level":3,"tags":["dong-tu"],"image":"🫗","examples":[{"type":"basic","zh":"刮大风了，路边的小树被吹倒了。","pinyin":"Guā dàfēng le, lùbiān de xiǎoshù bèi chuī dǎo le.","vi":"Gió lớn thổi rồi, cây nhỏ bên đường bị thổi đổ rồi."},{"type":"simple","zh":"他走路的时候不小心摔倒了。","pinyin":"Tā zǒulù de shíhou bù xiǎoxīn shuāidǎo le.","vi":"Lúc đi đường anh ấy không cẩn thận bị ngã."},{"type":"compound","zh":"因为昨天晚上不小心把水杯碰倒洒了一桌子水，所以我赶紧拿毛巾擦干净。","pinyin":"Yīnwèi zuótiān wǎnshang bù xiǎoxīn bǎ shuǐbēi pèngdǎo sǎle yì zhuōzi shuǐ, suǒyǐ wǒ gǎnjǐn ná máojīn cā gānjìng.","vi":"Vì tối qua vô tình làm đổ cốc nước làm nước tràn ra đầy bàn nên tôi vội lấy khăn lau sạch."}],"related":[{"hanzi":"掉","pinyin":"diào","vi":"Rơi"},{"hanzi":"擦","pinyin":"cā","vi":"Lau"},{"hanzi":"杯子","pinyin":"bēizi","vi":"Cái cốc"},{"hanzi":"茶","pinyin":"chá","vi":"Trà"},{"hanzi":"风","pinyin":"fēng","vi":"Gió"}]},{"id":"得","hanzi":"得","pinyin":"děi","meaning_vi":"phải, cần phải","explanation":"Đọc děi khi là động từ năng nguyện nghĩa là 'phải' (我得走了).","hsk_level":3,"tags":["dong-tu"],"image":"❗","examples":[{"type":"basic","zh":"时间不早了，我得回家了。","pinyin":"Shíjiān bù zǎo le, wǒ děi huíjiā le.","vi":"Thời gian không còn sớm nữa, tôi phải về nhà rồi."},{"type":"simple","zh":"从我家坐公共汽车到机场太慢了，我得打一辆出租车才来得及。","pinyin":"Cóng wǒ jiā zuò gōnggòngqìchē dào jīchǎng tài màn le, wǒ děi dǎ yí liàng chūzūchē cái láidejí.","vi":"Đi xe buýt từ nhà tôi ra sân bay chậm quá, tôi phải bắt một chiếc taxi mới kịp giờ."},{"type":"compound","zh":"为了通过下个月的HSK考试，我每天晚上都得花两个小时复习生词和语法。","pinyin":"Wèi le tōng guò xià ge yuè de HSK kǎo shì, wǒ měi tiān wǎn shang dōu děi huā liǎng ge xiǎo shí fù xí shēng cí hé yǔ fǎ.","vi":"Để thi đỗ kỳ thi HSK tháng sau, tối nào tôi cũng phải dành hai tiếng đồng hồ ôn tập từ mới và ngữ pháp."}],"related":[{"hanzi":"必须","pinyin":"bìxū","vi":"Bắt buộc"},{"hanzi":"不得不","pinyin":"bùdébù","vi":"Không thể không"},{"hanzi":"需要","pinyin":"xūyào","vi":"Cần"},{"hanzi":"应该","pinyin":"yīnggāi","vi":"Nên"},{"hanzi":"获得","pinyin":"huòdé","vi":"Giành được"}]},{"id":"灯","hanzi":"灯","pinyin":"dēng","meaning_vi":"cái đèn","explanation":"Bộ hỏa 火 (lửa) + 丁.","hsk_level":3,"tags":["danh-tu","do-vat","nha-cua"],"image":"💡","examples":[{"type":"basic","zh":"离开房间请随手关灯。","pinyin":"Líkāi fángjiān qǐng suíshǒu guān dēng.","vi":"Rời khỏi phòng xin hãy tiện tay tắt đèn."},{"type":"simple","zh":"过马路的时候一定要看清红绿灯，红灯停，绿灯行。","pinyin":"Guòmǎlù de shíhou yídìngyào kànqīng hónglǜdēng, hóngdēng tíng, lǜdēng xíng.","vi":"Khi sang đường nhất định phải nhìn rõ đèn giao thông, đèn đỏ dừng lại, đèn xanh được đi."},{"type":"compound","zh":"虽然已经深夜十一点多了，但是王老师书房里的台灯依然亮着，他还在备课。","pinyin":"Suīrán yǐjīng shēnyè shí yīdiǎn duō le, dànshì Wáng lǎoshī shūfáng lǐ de táidēng yīrán liàng zhe, tā hái zài bèikè.","vi":"Tuy đã hơn 11 giờ đêm khuya rồi nhưng đèn bàn trong phòng đọc sách của thầy Vương vẫn sáng, thầy vẫn đang soạn bài."}],"related":[{"hanzi":"关","pinyin":"guān","vi":"Tắt/Đóng"},{"hanzi":"开","pinyin":"kāi","vi":"Bật/Mở"},{"hanzi":"光","pinyin":"guāng","vi":"Ánh sáng"},{"hanzi":"亮","pinyin":"liàng","vi":"Sáng"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"Tiết kiệm"}],"traditional":"燈"},{"id":"低","hanzi":"低","pinyin":"dī","meaning_vi":"thấp (mức độ/nhiệt độ/giá cả)","explanation":"Đối nghĩa với 高 (cao về mức độ).","hsk_level":3,"tags":["tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"今天的气温比昨天低得多。","pinyin":"Jīntiān de qìwēn bǐ zuótiān dī de duō.","vi":"Nhiệt độ hôm nay thấp hơn hôm qua nhiều."},{"type":"simple","zh":"走路的时候不要总是低着头看手机，那样既不安全又对眼睛不好。","pinyin":"Zǒulù de shíhou bú yào zǒngshì dīzhe tóu kàn shǒujī, nàyàng jì bù ānquán yòu duì yǎnjing bù hǎo.","vi":"Lúc đi bộ đừng cứ cúi đầu nhìn điện thoại mãi, như vậy vừa không an toàn lại hại mắt."},{"type":"compound","zh":"虽然这家超市的商品价格很低，但是质量却非常有保证，所以顾客很多。","pinyin":"Suīrán zhè jiā chāoshì de shāngpǐn jiàgé hěn dī, dànshì zhìliàng què fēicháng yǒu bǎozhèng, suǒyǐ gùkè hěn duō.","vi":"Tuy giá hàng hóa của siêu thị này rất thấp nhưng chất lượng lại vô cùng đảm bảo nên khách hàng rất đông."}],"related":[{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"降低","pinyin":"jiàngdī","vi":"Hạ thấp"},{"hanzi":"矮","pinyin":"ǎi","vi":"Thấp/Lùn"},{"hanzi":"温度","pinyin":"wēndù","vi":"Nhiệt độ"},{"hanzi":"价格","pinyin":"jiàgé","vi":"Giá cả"}]},{"id":"底","hanzi":"底","pinyin":"dǐ","meaning_vi":"đáy, cuối (tháng/năm)","explanation":"Ví dụ: 年底 (cuối năm), 月底 (cuối tháng).","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"⬇️","examples":[{"type":"basic","zh":"今年年底我们公司要搬家。","pinyin":"Jīnnián niándǐ wǒmen gōngsī yào bānjiā.","vi":"Cuối năm nay công ty chúng tôi sẽ chuyển địa điểm."},{"type":"simple","zh":"这个月底我们学校就要举行期末考试了，大家都在认真复习。","pinyin":"Zhè ge yuèdǐ wǒmen xuéxiào jiùyào jǔxíng qīmò kǎoshì le, dàjiā dōu zài rènzhēn fùxí.","vi":"Cuối tháng này trường chúng tôi sẽ tổ chức thi cuối kỳ rồi, mọi người đều đang chăm chỉ ôn tập."},{"type":"compound","zh":"这条小河的水非常清澈，站在桥上甚至能一眼看到河底的小石头和游鱼。","pinyin":"Zhè tiáo xiǎohé de shuǐ fēicháng qīngchè, zhàn zài qiáo shang shènzhì néng yìyǎn kàndào hé dǐ de xiǎo shítou hé yóuyú.","vi":"Nước của con sông nhỏ này rất trong vắt, đứng trên cầu thậm chí có thể nhìn thấy tận đáy sông có sỏi nhỏ và cá bơi."}],"related":[{"hanzi":"到底","pinyin":"dàodǐ","vi":"Rốt cuộc"},{"hanzi":"年底","pinyin":"niándǐ","vi":"Cuối năm"},{"hanzi":"月底","pinyin":"yuèdǐ","vi":"Cuối tháng"},{"hanzi":"深","pinyin":"shēn","vi":"Sâu"},{"hanzi":"河","pinyin":"hé","vi":"Sông"}]},{"id":"地点","hanzi":"地点","pinyin":"dìdiǎn","meaning_vi":"địa điểm","explanation":"地 (đất) + 点 (điểm).","hsk_level":3,"tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"请通知大家开会的时间和地点。","pinyin":"Qǐng tōngzhī dàjiā kāihuì de shíjiān hé dìdiǎn.","vi":"Xin hãy thông báo cho mọi người thời gian và địa điểm họp."},{"type":"simple","zh":"这次同学聚会的地点定在了学校对面那家著名的中国餐厅。","pinyin":"Zhè cì tóngxué jùhuì de dìdiǎn dìng zài le xuéxiào duìmiàn nà jiā zhùmíng de Zhōngguó cāntīng.","vi":"Địa điểm buổi họp lớp lần này được chọn tại nhà hàng Trung Quốc nổi tiếng đối diện trường học."},{"type":"compound","zh":"虽然出发前我们已经查好了见面地点，但是因为出口太多还是差点儿找错了。","pinyin":"Suīrán chūfā qián wǒmen yǐjīng chá hǎole jiànmiàn dìdiǎn, dànshì yīnwèi chūkǒu tài duō háishi chàdiǎnr zhǎo cuò le.","vi":"Tuy trước khi xuất phát chúng tôi đã tra kỹ địa điểm gặp mặt nhưng vì có quá nhiều lối ra nên vẫn suýt tìm nhầm."}],"related":[{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"},{"hanzi":"地址","pinyin":"dìzhǐ","vi":"Địa chỉ"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"Tụ họp"}],"traditional":"地點"},{"id":"地球","hanzi":"地球","pinyin":"dìqiú","meaning_vi":"Trái Đất","explanation":"地 (đất) + 球 (quả cầu).","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🌍","examples":[{"type":"basic","zh":"地球是我们共同的家园。","pinyin":"Dìqiú shì wǒmen gòngtóng de jiāyuán.","vi":"Trái Đất là ngôi nhà chung của chúng ta."},{"type":"simple","zh":"地球围绕着太阳旋转，同时也在不停地进行自转。","pinyin":"Dìqiú wéiràozhe tàiyáng xuánzhuǎn, tóngshí yě zài bùtíng de jìnxíng zìzhuǎn.","vi":"Trái Đất quay xung quanh Mặt Trời, đồng thời cũng không ngừng tự quay quanh trục."},{"type":"compound","zh":"地球是人类唯一的家园，因此保护环境是每个人的责任。","pinyin":"Dìqiú shì rénlèi wéiyī de jiāyuán, yīncǐ bǎohù huánjìng shì měigerén de zérèn.","vi":"Trái Đất là ngôi nhà duy nhất của loài người, vì vậy bảo vệ môi trường là trách nhiệm của mỗi người."}],"related":[{"hanzi":"亚洲","pinyin":"Yàzhōu","vi":"Châu Á"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"太阳","pinyin":"tàiyáng","vi":"Mặt trời"},{"hanzi":"自然","pinyin":"zìrán","vi":"Tự nhiên"}]},{"id":"地址","hanzi":"地址","pinyin":"dìzhǐ","meaning_vi":"địa chỉ","explanation":"地 (đất) + 址 (nền móng/nơi ở).","hsk_level":3,"tags":["danh-tu","dia-diem"],"image":"🏠","examples":[{"type":"basic","zh":"请把你的家庭地址写下来。","pinyin":"Qǐng bǎ nǐ de jiātíng dìzhǐ xiě xiàlái.","vi":"Xin hãy viết địa chỉ nhà của bạn ra."},{"type":"simple","zh":"在网上买东西付款之前，一定要仔细核对收货人的姓名、电话和地址。","pinyin":"Zài wǎngshang mǎidōngxi fùkuǎn zhīqián, yídìngyào zǐxì héduì shōuhuòrén de xìngmíng, diànhuà hé dìzhǐ.","vi":"Trước khi thanh toán mua hàng trên mạng, nhất định phải đối chiếu kỹ họ tên, số điện thoại và địa chỉ người nhận."},{"type":"compound","zh":"因为我上个月刚刚搬了新家，所以昨天专门去银行更新了我的联系地址。","pinyin":"Yīnwèi wǒ shànggeyuè gānggāng bānle xīn jiā, suǒyǐ zuótiān zhuānmén qù yínháng gēngxīnle wǒ de liánxì dìzhǐ.","vi":"Vì tháng trước tôi vừa mới chuyển sang nhà mới nên hôm qua đã đặc biệt ra ngân hàng cập nhật lại địa chỉ liên hệ."}],"related":[{"hanzi":"地点","pinyin":"dìdiǎn","vi":"Địa điểm"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"信封","pinyin":"xìnfēng","vi":"Phong bì thư"},{"hanzi":"搬","pinyin":"bān","vi":"Chuyển nhà"}]},{"id":"调查","hanzi":"调查","pinyin":"diàochá","meaning_vi":"điều tra, khảo sát","explanation":"调 (đọc diào) + 查 (kiểm tra).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"我们正在做一项市场调查。","pinyin":"Wǒmen zhèngzài zuò yí xiàng shìchǎng diàochá.","vi":"Chúng tôi đang làm một cuộc khảo sát thị trường."},{"type":"simple","zh":"根据最新的问卷调查结果显示，超过百分之八十的年轻人喜欢网上购物。","pinyin":"Gēnjù zuì xīn de wènjuàndiàochá jiéguǒ xiǎnshì, chāoguò bǎifēnzhī bāshí de niánqīngrén xǐhuan wǎngshang gòuwù.","vi":"Theo kết quả khảo sát mới nhất cho thấy, hơn 80% giới trẻ thích mua sắm trực tuyến."},{"type":"compound","zh":"公司决定在推出新产品之前，先派专业团队去各大城市进行深入的市场调查。","pinyin":"Gōngsī juédìng zài tuīchū xīnchǎnpǐn zhīqián, xiān pài zhuānyè tuánduì qù gè dàchéngshì jìnxíng shēnrù de shìchǎng diàochá.","vi":"Công ty quyết định trước khi tung ra sản phẩm mới sẽ cử đội ngũ chuyên nghiệp đi khảo sát thị trường chuyên sâu tại các thành phố lớn."}],"related":[{"hanzi":"查","pinyin":"chá","vi":"Tra cứu"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"Kiểm tra"},{"hanzi":"研究","pinyin":"yánjiū","vi":"Nghiên cứu"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"Tình huống"}],"traditional":"調查"},{"id":"动作","hanzi":"动作","pinyin":"dòngzuò","meaning_vi":"động tác","explanation":"动 (chuyển động) + 作 (làm).","hsk_level":3,"tags":["danh-tu","the-thao"],"image":"🤸","examples":[{"type":"basic","zh":"老师做了一个标准的太极拳动作。","pinyin":"Lǎoshī zuòle yí ge biāozhǔn de tàijíquán dòngzuò.","vi":"Thầy giáo đã làm một động tác Thái Cực Quyền chuẩn xác."},{"type":"simple","zh":"学跳舞的时候，要先跟着教练把每一个基本动作练习标准。","pinyin":"Xué tiàowǔ de shíhou, yào xiān gēnzhe jiàoliàn bǎ měi yí ge jīběn dòngzuò liànxí biāozhǔn.","vi":"Khi học nhảy múa, trước tiên phải tập theo huấn luyện viên từng động tác cơ bản cho chuẩn."},{"type":"compound","zh":"虽然这部动作电影的打斗场面非常精彩，但是故事情节稍微有点儿简单。","pinyin":"Suīrán zhè bù dòngzuò diànyǐng de dǎdòu chǎngmiàn fēicháng jīngcǎi, dànshì gùshi qíngjié shāowēi yǒudiǎnr jiǎndān.","vi":"Tuy cảnh hành động của bộ phim này vô cùng đặc sắc nhưng tình tiết câu chuyện hơi đơn giản một chút."}],"related":[{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"},{"hanzi":"激动","pinyin":"jīdòng","vi":"Xúc động"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"}],"traditional":"動作"},{"id":"肚子","hanzi":"肚子","pinyin":"dùzi","meaning_vi":"cái bụng","explanation":"Bộ nguyệt ⺼(cơ thể) + 土 + 子.","hsk_level":3,"tags":["danh-tu","co-the"],"image":"🤰","examples":[{"type":"basic","zh":"我今天早上肚子有点儿疼。","pinyin":"Wǒ jīntiān zǎoshang dùzi yǒudiǎnr téng.","vi":"Sáng nay bụng tôi hơi đau một chút."},{"type":"simple","zh":"因为中午吃了太多冰西瓜和冷饮，弟弟下午回来以后一直喊肚子疼。","pinyin":"Yīnwèi zhōngwǔ chīle tài duō bīng xīguā hé lěngyǐn, dìdi xiàwǔ huílái yǐhòu yìzhí hǎn dùziténg.","vi":"Vì buổi trưa ăn quá nhiều dưa hấu lạnh và đồ uống đá nên chiều về em trai cứ kêu đau bụng mãi."},{"type":"compound","zh":"虽然我已经吃饱了，但是看到妈妈端上来的红烧肉，肚子好像又有空间了。","pinyin":"Suīrán wǒ yǐjīng chībǎo le, dànshì kàndào māma duān shànglái de hóngshāoròu, dùzi hǎoxiàng yòu yǒu kōngjiān le.","vi":"Tuy tôi đã ăn no rồi nhưng nhìn thấy món thịt kho tàu mẹ bưng lên, cái bụng dường như lại có thêm chỗ trống."}],"related":[{"hanzi":"饱","pinyin":"bǎo","vi":"No"},{"hanzi":"饿","pinyin":"è","vi":"Đói"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"Cơ thể"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"Ăn cơm"}]},{"id":"短信","hanzi":"短信","pinyin":"duǎnxìn","meaning_vi":"tin nhắn (SMS)","explanation":"短 (ngắn) + 信 (thư tín).","hsk_level":3,"tags":["danh-tu","cong-nghe"],"image":"💬","examples":[{"type":"basic","zh":"我给你发了一条短信。","pinyin":"Wǒ gěi nǐ fāle yì tiáo duǎnxìn.","vi":"Tôi đã gửi cho bạn một tin nhắn."},{"type":"simple","zh":"昨天收到银行发来的短信通知，我才知道上个月的奖金已经到账了。","pinyin":"Zuótiān shōudào yínháng fā lái de duǎnxìn tōngzhī, wǒ cái zhīdao shànggeyuè de jiǎngjīn yǐjīng dàozhàng le.","vi":"Hôm qua nhận được tin nhắn thông báo từ ngân hàng tôi mới biết tiền thưởng tháng trước đã về tài khoản rồi."},{"type":"compound","zh":"虽然现在大家都习惯用微信聊天，但是很多重要的验证码仍然是通过手机短信发送的。","pinyin":"Suīrán xiànzài dàjiā dōu xí guànyòng Wēixìn liáotiān, dànshì hěn duō zhòngyào de yànzhèngmǎ réngrán shì tōngguò shǒujī duǎnxìn fāsòng de.","vi":"Tuy hiện nay mọi người đều quen dùng WeChat trò chuyện nhưng nhiều mã xác nhận quan trọng vẫn được gửi qua tin nhắn điện thoại."}],"related":[{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"信封","pinyin":"xìnfēng","vi":"Phong bì thư"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"手机","pinyin":"shǒujī","vi":"Điện thoại"},{"hanzi":"通知","pinyin":"tōngzhī","vi":"Thông báo"}]},{"id":"段","hanzi":"段","pinyin":"duàn","meaning_vi":"đoạn, quãng (lượng từ)","explanation":"Lượng từ cho đoạn văn, quãng đường, quãng thời gian (一段时间).","hsk_level":3,"tags":["luong-tu"],"image":"📏","examples":[{"type":"basic","zh":"这段时间工作特别忙。","pinyin":"Zhè duàn shíjiān gōngzuò tèbié máng.","vi":"Khoảng thời gian này công việc đặc biệt bận."},{"type":"simple","zh":"老师让我们把课文里的第三段大声朗读两遍，并背诵下来。","pinyin":"Lǎoshī ràng wǒmen bǎ kèwén lǐ de dì sān duàn dàshēng lǎngdú liǎng biàn, bìng bèisòng xiàlái.","vi":"Thầy giáo bảo chúng tôi đọc to đoạn thứ ba trong bài khóa hai lượt và học thuộc lòng."},{"type":"compound","zh":"虽然我们在北京一起学习生活的时间只有短短半年，但是这段友谊我会永远珍惜。","pinyin":"Suīrán wǒmen zài Běijīng yìqǐ xuéxí shēnghuó de shíjiān zhǐyǒu duǎn duǎn bàn nián, dànshì zhè duàn yǒuyì wǒ huì yǒngyuǎn zhēnxī.","vi":"Tuy thời gian chúng tôi cùng học tập và sinh hoạt ở Bắc Kinh chỉ vỏn vẹn nửa năm nhưng tình bạn này tôi sẽ mãi trân trọng."}],"related":[{"hanzi":"篇","pinyin":"piān","vi":"Bài"},{"hanzi":"页","pinyin":"yè","vi":"Trang"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"回忆","pinyin":"huíyì","vi":"Hồi ức"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"Bài văn"}]},{"id":"对话","hanzi":"对话","pinyin":"duìhuà","meaning_vi":"đối thoại, hội thoại","explanation":"对 (đối đáp) + 话 (lời nói).","hsk_level":3,"tags":["danh-tu","giao-tiep","hoc-tap"],"image":"🗨️","examples":[{"type":"basic","zh":"请大家两人一组练习对话。","pinyin":"Qǐng dàjiā liǎng rén yì zǔ liànxí duìhuà.","vi":"Xin mời mọi người chia nhóm hai người luyện tập hội thoại."},{"type":"simple","zh":"这本汉语教材里的每一课都有两段非常实用的日常交际对话。","pinyin":"Zhè běn Hànyǔ jiàocái lǐ de měi yí kè dōu yǒu liǎng duàn fēicháng shíyòng de rìcháng jiāojì duìhuà.","vi":"Mỗi bài trong cuốn giáo trình tiếng Trung này đều có hai đoạn hội thoại giao tiếp hằng ngày vô cùng thiết thực."},{"type":"compound","zh":"多听多模仿课本里的录音对话，可以帮助我们很快提高口语表达的自然度。","pinyin":"Duō tīng duō mófǎng kèběn lǐ de lùyīn duìhuà, kěyǐ bāngzhù wǒmen hěn kuài tígāo kǒuyǔ biǎodá de zìrán dù.","vi":"Nghe nhiều và bắt chước nhiều các đoạn hội thoại ghi âm trong sách giáo khoa giúp chúng ta nhanh chóng nâng cao độ tự nhiên khi nói."}],"related":[{"hanzi":"说话","pinyin":"shuōhuà","vi":"Nói chuyện"},{"hanzi":"普通话","pinyin":"pǔtōnghuà","vi":"Tiếng phổ thông"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"谈","pinyin":"tán","vi":"Nói chuyện"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"}],"traditional":"對話"},{"id":"对于","hanzi":"对于","pinyin":"duìyú","meaning_vi":"đối với (giới từ)","explanation":"对 + 于. Dùng đầu câu hoặc trước động từ chỉ đối tượng liên quan.","hsk_level":3,"tags":["gioi-tu"],"image":"🎯","examples":[{"type":"basic","zh":"对于这个问题，我也有同感。","pinyin":"Duìyú zhè ge wèntí, wǒ yě yǒu tónggǎn.","vi":"Đối với vấn đề này, tôi cũng có chung cảm nhận."},{"type":"simple","zh":"对于刚来中国的外国留学生来说，适应当地的饮食习惯需要一个过程。","pinyin":"Duìyú gāng lái Zhōngguó de wàiguó liúxué shenglái shuō, shìyìng dāngdì de yǐnshí xíguàn xūyào yí ge guòchéng.","vi":"Đối với du học sinh nước ngoài mới sang Trung Quốc, việc thích nghi với thói quen ăn uống địa phương cần có một quá trình."},{"type":"compound","zh":"虽然很多人觉得学写汉字很难，但是对于喜欢画画的我来说却觉得特别有趣。","pinyin":"Suīrán hěn duō rén juéde xué xiě hànzì hěn nán, dànshì duìyú xǐhuan huàhuà de wǒ lái shuō què juéde tèbié yǒuqù.","vi":"Tuy nhiều người thấy học viết chữ Hán rất khó nhưng đối với một người thích vẽ như tôi lại thấy đặc biệt thú vị."}],"related":[{"hanzi":"对","pinyin":"duì","vi":"Đối với"},{"hanzi":"关于","pinyin":"guānyú","vi":"Về"},{"hanzi":"于是","pinyin":"yúshì","vi":"Thế là"},{"hanzi":"由于","pinyin":"yóuyú","vi":"Do/Bởi vì"},{"hanzi":"看法","pinyin":"kànfǎ","vi":"Cách nhìn"}],"traditional":"對於"},{"id":"儿童","hanzi":"儿童","pinyin":"értóng","meaning_vi":"trẻ em, nhi đồng","explanation":"儿 (trẻ nhỏ) + 童 (trẻ con).","hsk_level":3,"tags":["danh-tu","con-nguoi"],"image":"🧒","examples":[{"type":"basic","zh":"六月一日是国际儿童节。","pinyin":"Liùyuè yī rì shì Guójì'értóngjié.","vi":"Ngày 1 tháng 6 là Ngày Quốc tế Thiếu nhi."},{"type":"simple","zh":"周末的时候，爸爸妈妈经常带着小妹妹去市中心的儿童公园玩。","pinyin":"Zhōumò de shíhou, bàba māma jīngcháng dàizhe xiǎomèimei qù shìzhōngxīn de értóng gōngyuán wán.","vi":"Vào cuối tuần, bố mẹ thường dẫn em gái nhỏ đến công viên thiếu nhi ở trung tâm thành phố chơi."},{"type":"compound","zh":"这本图画书用简单可爱的语言讲了许多小动物的故事，非常适合儿童阅读。","pinyin":"Zhè běn túhuà shū yòng jiǎndān kě'ài de yǔyán jiǎngle xǔduō xiǎo dòngwù de gùshi, fēicháng shìhé értóng yuèdú.","vi":"Cuốn sách tranh này dùng ngôn ngữ đơn giản đáng yêu kể nhiều câu chuyện về các loài động vật nhỏ, rất thích hợp cho trẻ em đọc."}],"related":[{"hanzi":"孩子","pinyin":"háizi","vi":"Trẻ em"},{"hanzi":"儿子","pinyin":"érzi","vi":"Con trai"},{"hanzi":"女儿","pinyin":"nǚ'ér","vi":"Con gái"},{"hanzi":"男孩","pinyin":"nánhái","vi":"Bé trai"},{"hanzi":"女孩","pinyin":"nǚhái","vi":"Bé gái"}],"traditional":"兒童"},{"id":"而","hanzi":"而","pinyin":"ér","meaning_vi":"mà, nhưng, và","explanation":"Liên từ nối hai vế câu mang quan hệ bổ sung hoặc chuyển ngoặt.","hsk_level":3,"tags":["lien-tu"],"image":"🔗","examples":[{"type":"basic","zh":"南方的冬天很暖和，而北方的冬天很冷。","pinyin":"Nánfāng de dōngtiān hěn nuǎnhuo, ér běifāng de dōngtiān hěn lěng.","vi":"Mùa đông miền Nam rất ấm áp, còn mùa đông miền Bắc thì rất lạnh."},{"type":"simple","zh":"他学习汉语不是为了应付考试，而是因为真正喜欢中国文化。","pinyin":"Tā xuéxí Hànyǔ bú shì wèile yìngfu kǎoshì, érshì yīnwèi zhēnzhèng xǐhuan Zhōngguó wénhuà.","vi":"Anh ấy học tiếng Trung không phải để đối phó thi cử, mà là vì thực sự yêu thích văn hóa Trung Quốc."},{"type":"compound","zh":"虽然这篇文章很短，然而内容却丰富而深刻，读完让人受益匪浅。","pinyin":"Suīrán zhè piān wénzhāng hěn duǎn, rán'ér nèiróng què fēngfù ér shēnkè, dú wán ràng rén shòuyì fěi qiǎn.","vi":"Tuy bài văn này rất ngắn, tuy nhiên nội dung lại phong phú và sâu sắc, đọc xong khiến người ta thu hoạch được nhiều điều bổ ích."}],"related":[{"hanzi":"而且","pinyin":"érqiě","vi":"Mà còn"},{"hanzi":"然而","pinyin":"rán'ér","vi":"Tuy nhiên"},{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"Đồng thời"},{"hanzi":"却","pinyin":"què","vi":"Lại"}]},{"id":"法律","hanzi":"法律","pinyin":"fǎlǜ","meaning_vi":"pháp luật","explanation":"法 (phép tắc) + 律 (luật lệ).","hsk_level":3,"tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"每个人都必须遵守国家法律。","pinyin":"Měigerén dōu bìxū zūnshǒu guójiā fǎlǜ.","vi":"Mỗi người đều bắt buộc phải tuân thủ pháp luật nhà nước."},{"type":"simple","zh":"我哥哥大学学的是法律专业，毕业以后在一家著名律师事务所工作。","pinyin":"Wǒ gēge dàxué xué de shì fǎlǜ zhuānyè, bìyè yǐhòu zài yìjiā zhùmíng lǜshī shìwùsuǒ gōngzuò.","vi":"Anh trai tôi ở đại học học chuyên ngành luật, sau khi tốt nghiệp làm việc tại một văn phòng luật sư nổi tiếng."},{"type":"compound","zh":"在现代法治社会中，了解基本的法律知识有助于我们更好地保护自己的合法权益。","pinyin":"Zài xiàndài fǎzhì shèhuì zhōng, liǎojiě jīběn de fǎlǜ zhīshi yǒuzhùyú wǒmen gèng hǎo de bǎohù zìjǐ de héfǎquányì.","vi":"Trong xã hội pháp quyền hiện đại, hiểu biết kiến thức pháp luật cơ bản giúp chúng ta bảo vệ tốt hơn quyền lợi hợp pháp của mình."}],"related":[{"hanzi":"律师","pinyin":"lǜshī","vi":"Luật sư"},{"hanzi":"规定","pinyin":"guīdìng","vi":"Quy định"},{"hanzi":"社会","pinyin":"shèhuì","vi":"Xã hội"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"任何","pinyin":"rènhé","vi":"Bất kỳ"}]},{"id":"方面","hanzi":"方面","pinyin":"fāngmiàn","meaning_vi":"phương diện, mặt","explanation":"方 (phương) + 面 (mặt).","hsk_level":3,"tags":["danh-tu"],"image":"📐","examples":[{"type":"basic","zh":"他在语言学习方面很有天赋。","pinyin":"Tā zài yǔyán xuéxí fāngmiàn hěn yǒu tiānfù.","vi":"Anh ấy có năng khiếu rất tốt về mặt học ngôn ngữ."},{"type":"simple","zh":"来中国留学一年以后，我在听力和口语方面都有了很大的进步。","pinyin":"Lái Zhōngguó liúxué yì nián yǐhòu, wǒ zài tīnglì hé kǒuyǔ fāngmiàn dōu yǒule hěn dà de jìnbù.","vi":"Sau khi đến Trung Quốc du học một năm, tôi đã có tiến bộ lớn về cả hai mặt nghe và nói."},{"type":"compound","zh":"选择租房子的时候，我们需要综合考虑交通、环境、安全以及价格等各个方面。","pinyin":"Xuǎnzé zū fángzi de shíhou, wǒmen xūyào zōnghé kǎolǜ jiāotōng, huánjìng, ānquán yǐjí jiàgé děng gège fāngmiàn.","vi":"Khi chọn thuê nhà, chúng ta cần cân nhắc tổng hợp mọi phương diện như giao thông, môi trường, an toàn và giá cả."}],"related":[{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"},{"hanzi":"对面","pinyin":"duìmiàn","vi":"Đối diện"},{"hanzi":"外面","pinyin":"wàimiàn","vi":"Bên ngoài"},{"hanzi":"里面","pinyin":"lǐmiàn","vi":"Bên trong"}]},{"id":"方向","hanzi":"方向","pinyin":"fāngxiàng","meaning_vi":"phương hướng","explanation":"方 + 向 (hướng về).","hsk_level":3,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"🧭","examples":[{"type":"basic","zh":"请问去火车站是这个方向吗？","pinyin":"Qǐngwèn qùhuǒ chēzhàn shì zhè ge fāngxiàng ma?","vi":"Xin hỏi đi ga tàu hỏa có phải hướng này không ạ?"},{"type":"simple","zh":"因为我方向感不太好，所以每次出门去陌生的地方都要提前看地图。","pinyin":"Yīnwèi wǒ fāngxiànggǎn bú tài hǎo, suǒyǐ měi cì chūmén qù mòshēng de dìfang dōu yào tíqián kàn dìtú.","vi":"Vì khả năng xác định phương hướng của tôi không tốt lắm nên mỗi lần đi tới nơi xa lạ đều phải xem bản đồ trước."},{"type":"compound","zh":"只要找准了人生的奋斗方向并坚持不懈地努力，就一定能到达成功的彼岸。","pinyin":"Zhǐyào zhǎo zhǔnle rénshēng de fèndòu fāngxiàng bìng jiānchíbúxiè de nǔlì, jiù yídìng néng dàodá chénggōng de bǐ'àn.","vi":"Chỉ cần xác định đúng phương hướng phấn đấu của cuộc đời và nỗ lực không ngừng thì nhất định sẽ cập bến thành công."}],"related":[{"hanzi":"方面","pinyin":"fāngmiàn","vi":"Phương diện"},{"hanzi":"向","pinyin":"xiàng","vi":"Hướng về"},{"hanzi":"迷路","pinyin":"mílù","vi":"Lạc đường"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"往","pinyin":"wǎng","vi":"Về phía"}]},{"id":"房东","hanzi":"房东","pinyin":"fángdōng","meaning_vi":"chủ nhà (cho thuê)","explanation":"房 (nhà) + 东 (chủ nhân).","hsk_level":3,"tags":["danh-tu","con-nguoi","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"我的房东是一位热情的老奶奶。","pinyin":"Wǒ de fángdōng shì yí wèi rèqíng de lǎonǎinai.","vi":"Chủ nhà của tôi là một bà cụ rất nhiệt tình."},{"type":"simple","zh":"昨天房间里的空调突然坏了，我打电话告诉房东以后，她马上请师傅来修好了。","pinyin":"Zuótiān fángjiān lǐ de kōngtiáo tūrán huàile, wǒ dǎdiànhuà gàosu fángdōng yǐhòu, tā mǎshàng qǐng shīfu lái xiūhǎo le.","vi":"Hôm qua điều hòa trong phòng đột nhiên hỏng, sau khi tôi gọi điện báo cho chủ nhà, bà đã gọi ngay thợ đến sửa xong."},{"type":"compound","zh":"因为我们平时把房子收拾得非常干净整齐，所以房东对我们这些租客特别满意。","pinyin":"Yīnwèi wǒmen píngshí bǎ fángzi shōushi de fēicháng gānjìng zhěngqí, suǒyǐ fángdōng duì wǒmen zhèxiē zūkè tèbié mǎnyì.","vi":"Vì ngày thường chúng tôi dọn dẹp nhà cửa rất sạch sẽ ngăn nắp nên chủ nhà đặc biệt hài lòng với những người thuê nhà như chúng tôi."}],"related":[{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"},{"hanzi":"租","pinyin":"zū","vi":"Thuê"},{"hanzi":"东","pinyin":"dōng","vi":"Đông/Chủ"},{"hanzi":"邻居","pinyin":"línjū","vi":"Hàng xóm"},{"hanzi":"房子","pinyin":"fángzi","vi":"Ngôi nhà"}],"traditional":"房東"},{"id":"放暑假","hanzi":"放暑假","pinyin":"fàngshǔjià","meaning_vi":"nghỉ hè","explanation":"放 (nghỉ) + 暑假 (kỳ nghỉ hè).","hsk_level":3,"tags":["dong-tu","thoi-gian","hoc-tap"],"image":"🏖️","examples":[{"type":"basic","zh":"下个月我们学校就要放暑假了。","pinyin":"Xiàgeyuè wǒmen xuéxiào jiùyào fàngshǔjià le.","vi":"Tháng sau trường chúng tôi sẽ được nghỉ hè rồi."},{"type":"simple","zh":"每年放暑假的时候，很多大学生都会选择去旅游或者做兼职积累经验。","pinyin":"Měinián fàngshǔjià de shíhou, hěn duōdà xuésheng dōuhuì xuǎnzé qù lǚyóu huòzhě zuò jiānzhí jīlěi jīngyàn.","vi":"Mỗi năm vào kỳ nghỉ hè, nhiều sinh viên đại học đều chọn đi du lịch hoặc làm thêm để tích lũy kinh nghiệm."},{"type":"compound","zh":"虽然放暑假有将近两个月的休息时间，但是我还是打算每天坚持阅读和练习汉语。","pinyin":"Suīrán fàngshǔjià yǒu jiāngjìn liǎng geyuè de xiūxi shíjiān, dànshì wǒ háishi dǎsuàn měitiān jiānchí yuèdú hé liànxí Hànyǔ.","vi":"Tuy kỳ nghỉ hè có gần hai tháng nghỉ ngơi nhưng tôi vẫn dự định mỗi ngày kiên trì đọc sách và luyện tiếng Trung."}],"related":[{"hanzi":"寒假","pinyin":"hánjià","vi":"Kỳ nghỉ đông"},{"hanzi":"放","pinyin":"fàng","vi":"Nghỉ/Thả"},{"hanzi":"夏天","pinyin":"xiàtiān","vi":"Mùa hè"},{"hanzi":"学期","pinyin":"xuéqī","vi":"Học kỳ"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"Trường học"}]},{"id":"丰富","hanzi":"丰富","pinyin":"fēngfù","meaning_vi":"phong phú, dồi dào","explanation":"丰 (tươi tốt/nhiều) + 富 (giàu có).","hsk_level":3,"tags":["tinh-tu"],"image":"🌈","examples":[{"type":"basic","zh":"大学生活非常丰富多彩。","pinyin":"Dàxué shēnghuó fēicháng fēngfùduōcǎi.","vi":"Cuộc sống đại học vô cùng phong phú đa sắc màu."},{"type":"simple","zh":"王老师不仅专业知识非常丰富，而且有着二十多年的对外汉语教学经验。","pinyin":"Wáng lǎoshī bùjǐn zhuānyè zhīshi fēicháng fēngfù, érqiě yǒuzhe èrshí duōnián de duìwài Hànyǔ jiāoxué jīngyàn.","vi":"Thầy Vương không chỉ có kiến thức chuyên môn vô cùng phong phú mà còn có hơn 20 năm kinh nghiệm dạy tiếng Trung cho người nước ngoài."},{"type":"compound","zh":"多阅读不同领域的书籍，不仅可以丰富我们的精神世界，还能开阔视野。","pinyin":"Duō yuèdú bùtóng lǐngyù de shūjí, bùjǐn kěyǐ fēngfù wǒmen de jīngshén shìjiè, hái néng kāikuò shìyě.","vi":"Đọc nhiều sách ở các lĩnh vực khác nhau không chỉ làm phong phú thế giới tinh thần của chúng ta mà còn mở mang tầm mắt."}],"related":[{"hanzi":"富","pinyin":"fù","vi":"Giàu có"},{"hanzi":"内容","pinyin":"nèiróng","vi":"Nội dung"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"Kinh nghiệm"},{"hanzi":"知识","pinyin":"zhīshi","vi":"Kiến thức"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"}],"traditional":"豐富"},{"id":"风景","hanzi":"风景","pinyin":"fēngjǐng","meaning_vi":"phong cảnh","explanation":"风 (gió/cảnh) + 景 (cảnh vật).","hsk_level":3,"tags":["danh-tu","thien-nhien","du-lich"],"image":"🏞️","examples":[{"type":"basic","zh":"这里的自然风景美极了！","pinyin":"Zhèlǐ de zìrán fēngjǐng měi jíle!","vi":"Phong cảnh thiên nhiên ở đây đẹp tuyệt vời!"},{"type":"simple","zh":"秋天香山上的红叶漫山遍野，风景如画，吸引着无数游客前来拍照。","pinyin":"Qiūtiān xiāng shān shang de hóngyè màn shān biàn yě, fēngjǐng rúhuà, xīyǐnzhe wúshù yóukè qiánlái pāizhào.","vi":"Mùa thu lá đỏ trên Hương Sơn phủ kín khắp núi đồi, phong cảnh đẹp như tranh vẽ, thu hút vô số du khách tới chụp ảnh."},{"type":"compound","zh":"虽然爬山的过程让人觉得有点儿累，但是看到山顶壮丽的风景时一切疲劳都消失了。","pinyin":"Suīrán páshān de guòchéng ràng rén juéde yǒudiǎnr lèi, dànshì kàndào shāndǐng zhuànglì de fēngjǐng shí yíqiè píláo dōu xiāoshī le.","vi":"Tuy quá trình leo núi khiến người ta hơi mệt nhưng khi ngắm nhìn phong cảnh hùng vĩ trên đỉnh núi thì mọi mệt mỏi đều tan biến."}],"related":[{"hanzi":"景色","pinyin":"jǐngsè","vi":"Cảnh sắc"},{"hanzi":"风","pinyin":"fēng","vi":"Gió"},{"hanzi":"自然","pinyin":"zìrán","vi":"Tự nhiên"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"漂亮","pinyin":"piàoliang","vi":"Đẹp"}],"traditional":"風景"},{"id":"否则","hanzi":"否则","pinyin":"fǒuzé","meaning_vi":"nếu không thì","explanation":"否 (không phải) + 则 (thì).","hsk_level":3,"tags":["lien-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"快点儿走，否则要迟到了。","pinyin":"Kuàidiǎnr zǒu, fǒuzé yào chídào le.","vi":"Đi nhanh lên một chút, nếu không sẽ bị muộn giờ đấy."},{"type":"simple","zh":"开车的时候一定要集中注意力，否则在车多的马路上很容易发生危险。","pinyin":"Kāichē de shíhou yídìngyào jízhōng zhùyìlì, fǒuzé zài chē duō de mǎ lùshang hěn róngyì fāshēng wēixiǎn.","vi":"Khi lái xe nhất định phải tập trung chú ý, nếu không trên đường đông xe cộ rất dễ xảy ra nguy hiểm."},{"type":"compound","zh":"平时学习必须每天坚持复习，否则学过的生词很快就会忘记。","pinyin":"Píngshí xuéxí bìxū měitiān jiānchí fùxí, fǒuzé xuéguo de shēngcí hěn kuài jiù huì wàngjì.","vi":"Ngày thường học tập bắt buộc phải kiên trì ôn tập mỗi ngày, nếu không từ mới đã học sẽ rất nhanh bị quên mất."}],"related":[{"hanzi":"是否","pinyin":"shìfǒu","vi":"Có phải không"},{"hanzi":"不然","pinyin":"bùrán","vi":"Nếu không thì"},{"hanzi":"迟到","pinyin":"chídào","vi":"Đến muộn"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"Nguy hiểm"},{"hanzi":"忘记","pinyin":"wàngjì","vi":"Quên"}],"traditional":"否則"},{"id":"复杂","hanzi":"复杂","pinyin":"fùzá","meaning_vi":"phức tạp","explanation":"复 (trùng lặp) + 杂 (lẫn lộn). Đối nghĩa với 简单 (đơn giản).","hsk_level":3,"tags":["tinh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"这个问题比我想象的复杂。","pinyin":"Zhè ge wèntí bǐ wǒ xiǎngxiàng de fùzá.","vi":"Vấn đề này phức tạp hơn tôi tưởng."},{"type":"simple","zh":"有些汉字的笔画虽然看起来很复杂，但是拆开偏旁部首以后就很容易记住了。","pinyin":"Yǒuxiē hànzì de bǐhuà suīrán kànqǐlái hěn fùzá, dànshì chāikāi piānpángbùshǒu yǐhòu jiù hěn róngyì jìzhu le.","vi":"Một số chữ Hán tuy nét bút trông rất phức tạp nhưng sau khi tách các bộ thủ ra thì lại rất dễ ghi nhớ."},{"type":"compound","zh":"遇到复杂的工作任务时不要着急，只要把大任务分成几个小步骤就能顺利解决。","pinyin":"Yùdào fùzá de gōngzuò rènwu shí bú yào zháojí, zhǐyào bǎ dà rènwu fēnchéng jǐ ge xiǎo bùzhòu jiù néng shùnlì jiějué.","vi":"Khi gặp nhiệm vụ công việc phức tạp đừng nóng vội, chỉ cần chia nhiệm vụ lớn thành vài bước nhỏ là có thể giải quyết suôn sẻ."}],"related":[{"hanzi":"简单","pinyin":"jiǎndān","vi":"Đơn giản"},{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"},{"hanzi":"杂志","pinyin":"zázhì","vi":"Tạp chí"},{"hanzi":"难","pinyin":"nán","vi":"Khó"},{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"}],"traditional":"複雜"},{"id":"干燥","hanzi":"干燥","pinyin":"gānzào","meaning_vi":"khô hanh, khô ráo","explanation":"干 (khô) + 燥 (khô nóng). Đối nghĩa với 湿润 (ẩm ướt).","hsk_level":3,"tags":["tinh-tu","thoi-tiet"],"image":"🏜️","examples":[{"type":"basic","zh":"北方的冬天天气非常干燥。","pinyin":"Běifāng de dōngtiān tiānqì fēicháng gānzào.","vi":"Thời tiết mùa đông miền Bắc vô cùng hanh khô."},{"type":"simple","zh":"因为秋天空气比较干燥，所以每天多喝水、多吃梨和苹果对嗓子很好。","pinyin":"Yīnwèi qiūtiān kōngqì bǐjiào gānzào, suǒyǐ měitiān duō hēshuǐ, duō chī lí hé píngguǒ duì sǎngzi hěn hǎo.","vi":"Vì mùa thu không khí khá hanh khô nên mỗi ngày uống nhiều nước, ăn nhiều lê và táo rất tốt cho cổ họng."},{"type":"compound","zh":"虽然北方的冬天室内有暖气很暖和，但是因为太干燥，很多人在房间里放了加湿器。","pinyin":"Suīrán běifāng de dōngtiān shìnèi yǒu nuǎnqì hěn nuǎnhuo, dànshì yīnwèi tài gānzào, hěn duō rén zài fángjiān lǐ fàngle jiāshīqì.","vi":"Tuy mùa đông miền Bắc trong nhà có lò sưởi rất ấm nhưng vì quá hanh khô nên nhiều người đặt máy tạo độ ẩm trong phòng."}],"related":[{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"饼干","pinyin":"bǐnggān","vi":"Bánh quy"},{"hanzi":"气候","pinyin":"qìhòu","vi":"Khí hậu"},{"hanzi":"暖气","pinyin":"nuǎnqì","vi":"Hệ thống sưởi"},{"hanzi":"皮肤","pinyin":"pífū","vi":"Da"}],"traditional":"乾燥"},{"id":"钢铁","hanzi":"钢铁","pinyin":"gāngtiě","meaning_vi":"gang thép","explanation":"钢 (thép) + 铁 (sắt).","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"这座大桥是用优质钢铁建造的。","pinyin":"Zhè zuò Dàqiáo shì yòng yōuzhì gāngtiě jiànzào de.","vi":"Cây cầu lớn này được xây dựng bằng gang thép chất lượng cao."},{"type":"simple","zh":"钢铁工业是现代工业的重要基础，在建筑和交通领域起着关键作用。","pinyin":"Gāngtiě gōngyè shì xiàndài gōngyè de zhòngyào jīchǔ, zài jiànzhù hé jiāotōng lǐngyù qǐzhe guānjiàn zuòyòng.","vi":"Công nghiệp gang thép là nền tảng quan trọng của công nghiệp hiện đại, đóng vai trò then chốt trong lĩnh vực xây dựng và giao thông."},{"type":"compound","zh":"只要大家拥有钢铁般的坚强意志，无论遇到多大的困难都能勇敢克服。","pinyin":"Zhǐyào dàjiā yōngyǒu gāngtiě bān de jiānqiáng yìzhì, wúlùn yùdào duōdà de kùnnan dōu néng yǒnggǎn kèfú.","vi":"Chỉ cần mọi người có ý chí kiên cường như gang thép thì dù gặp khó khăn lớn đến đâu cũng dũng cảm vượt qua."}],"related":[{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"桥","pinyin":"qiáo","vi":"Cây cầu"},{"hanzi":"基础","pinyin":"jīchǔ","vi":"Cơ sở"},{"hanzi":"材料","pinyin":"cáiliào","vi":"Vật liệu"},{"hanzi":"重","pinyin":"zhòng","vi":"Nặng"}],"traditional":"鋼鐵"},{"id":"高级","hanzi":"高级","pinyin":"gāojí","meaning_vi":"cao cấp","explanation":"高 (cao) + 级 (cấp bậc).","hsk_level":3,"tags":["tinh-tu"],"image":"⭐","examples":[{"type":"basic","zh":"这是一家非常高级的餐厅。","pinyin":"Zhè shì yìjiā fēicháng gāojí de cāntīng.","vi":"Đây là một nhà hàng vô cùng cao cấp."},{"type":"simple","zh":"他通过了HSK六级考试，现在正在大学里选修高级汉语写作课程。","pinyin":"Tā tōng guò le HSK liù jí kǎo shì, xiàn zài zhèng zài dà xué lǐ xuǎn xiū gāo jí hàn yǔ xiě zuò kè chéng.","vi":"Anh ấy đã thi đỗ HSK cấp 6, hiện đang học tự chọn môn viết tiếng Trung cao cấp tại trường đại học."},{"type":"compound","zh":"虽然这家宾馆的房间价格比较高，但是里面的设施非常高级，服务也很周到。","pinyin":"Suīrán zhè jiā bīnguǎn de fángjiān jiàgé bǐjiào gāo, dànshì lǐmiàn de shèshī fēicháng gāojí, fúwù yě hěn zhōudào.","vi":"Tuy giá phòng của khách sạn này tương đối cao nhưng trang thiết bị bên trong vô cùng cao cấp và dịch vụ cũng rất chu đáo."}],"related":[{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"提高","pinyin":"tígāo","vi":"Nâng cao"},{"hanzi":"等级","pinyin":"děngjí","vi":"Đẳng cấp"},{"hanzi":"餐厅","pinyin":"cāntīng","vi":"Nhà hàng"},{"hanzi":"宾馆","pinyin":"bīnguǎn","vi":"Khách sạn"}],"traditional":"高級"},{"id":"高速公路","hanzi":"高速公路","pinyin":"gāosùgōnglù","meaning_vi":"đường cao tốc","explanation":"高速 (tốc độ cao) + 公路 (đường lớn).","hsk_level":3,"tags":["danh-tu","giao-thong","dia-diem"],"image":"🛣️","examples":[{"type":"basic","zh":"汽车正在高速公路上行驶。","pinyin":"Qìchē zhèngzài gāosùgōnglù shangxíng shǐ.","vi":"Xe ô tô đang chạy trên đường cao tốc."},{"type":"simple","zh":"自从家乡通了高速公路以后，开车去省城的时间缩短了一半。","pinyin":"Zìcóng jiāxiāng tōngle gāosùgōnglù yǐhòu, kāichē qù shěngchéng de shíjiān suōduǎnle yíbàn.","vi":"Kể từ khi quê hương thông đường cao tốc, thời gian lái xe lên thành phố tỉnh lỵ đã rút ngắn đi một nửa."},{"type":"compound","zh":"在高速公路上开车时，绝对不能随便停车，而且必须严格遵守最高速度规定。","pinyin":"Zài gāosùgōnglù shang kāichē shí, juéduì bù néng suíbiàn tíngchē, érqiě bìxū yángé zūnshǒu zuì gāo sùdù guīdìng.","vi":"Khi lái xe trên đường cao tốc, tuyệt đối không được dừng đỗ tùy tiện và bắt buộc phải tuân thủ nghiêm ngặt quy định tốc độ tối đa."}],"related":[{"hanzi":"速度","pinyin":"sùdù","vi":"Tốc độ"},{"hanzi":"公里","pinyin":"gōnglǐ","vi":"Ki-lô-mét"},{"hanzi":"路","pinyin":"lù","vi":"Con đường"},{"hanzi":"汽车","pinyin":"qìchē","vi":"Xe ô tô"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"Giao thông"}]},{"id":"各","hanzi":"各","pinyin":"gè","meaning_vi":"các, mỗi","explanation":"Đại từ chỉ từng cá thể trong một nhóm (各国 - các nước, 各种 - các loại).","hsk_level":3,"tags":["dai-tu"],"image":"🔢","examples":[{"type":"basic","zh":"各国留学生聚在一起庆祝新年。","pinyin":"Gèguó liúxuésheng jù zài yìqǐ qìngzhù xīnnián.","vi":"Du học sinh các nước tụ họp bên nhau chào đón năm mới."},{"type":"simple","zh":"这家大型超市里有来自全国各地的特色小吃和新鲜水果。","pinyin":"Zhè jiā dàxíng chāoshì lǐ yǒu láizì quánguó gèdì de tèsè xiǎochī hé xīnxiān shuǐguǒ.","vi":"Trong siêu thị lớn này có các món ăn vặt đặc sản và trái cây tươi ngon đến từ khắp mọi miền đất nước."},{"type":"compound","zh":"虽然大家各自的性格和专业不同，但是在共同相处的过程中互相学习到了很多优点。","pinyin":"Suīrán dàjiā gèzì de xìnggé hé zhuānyè bùtóng, dànshì zài gòngtóng xiāngchǔ de guòchéng zhōng hùxiāng xuéxí dàole hěn duō yōudiǎn.","vi":"Tuy tính cách và chuyên ngành của mỗi người khác nhau nhưng trong quá trình chung sống đã học hỏi được nhiều ưu điểm của nhau."}],"related":[{"hanzi":"各个","pinyin":"gègè","vi":"Từng cái"},{"hanzi":"各地","pinyin":"gèdì","vi":"Khắp nơi"},{"hanzi":"各种","pinyin":"gèzhǒng","vi":"Đủ loại"},{"hanzi":"每","pinyin":"měi","vi":"Mỗi"},{"hanzi":"所有","pinyin":"suǒyǒu","vi":"Tất cả"}]},{"id":"工资","hanzi":"工资","pinyin":"gōngzī","meaning_vi":"tiền lương","explanation":"工 (công việc) + 资 (tiền bạc).","hsk_level":3,"tags":["danh-tu","cong-viec","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"他每个月的工资都很高。","pinyin":"Tā měi geyuè de gōngzī dōu hěn gāo.","vi":"Tiền lương mỗi tháng của anh ấy đều rất cao."},{"type":"simple","zh":"公司规定每个月十号准时把上个月的工资发到员工的银行卡里。","pinyin":"Gōngsī guīdìng měi geyuè shí hào zhǔnshí bǎ shànggeyuè de gōngzī fā dào yuángōng de yínhángkǎ lǐ.","vi":"Công ty quy định ngày mùng 10 hằng tháng sẽ chuyển đúng hẹn tiền lương tháng trước vào thẻ ngân hàng của nhân viên."},{"type":"compound","zh":"虽然刚毕业时起薪工资不算太高，但是只要努力工作积累经验，将来一定会涨工资的。","pinyin":"Suīrán gāng bìyè shí qǐxīn gōngzī búsuàn tài gāo, dànshì zhǐyào nǔlì gōngzuò jīlěi jīngyàn, jiānglái yídìng huì zhǎng gōngzī de.","vi":"Tuy lương khởi điểm lúc mới tốt nghiệp không tính là quá cao nhưng chỉ cần chăm chỉ làm việc tích lũy kinh nghiệm thì tương lai nhất định sẽ được tăng lương."}],"related":[{"hanzi":"收入","pinyin":"shōurù","vi":"Thu nhập"},{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"Tiền thưởng"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"赚钱","pinyin":"zhuànqián","vi":"Kiếm tiền"}],"traditional":"工資"},{"id":"公里","hanzi":"公里","pinyin":"gōnglǐ","meaning_vi":"ki-lô-mét (km)","explanation":"公 (hệ mét) + 里 (dặm).","hsk_level":3,"tags":["luong-tu","so-luong"],"image":"📏","examples":[{"type":"basic","zh":"我家离学校有五公里远。","pinyin":"Wǒ jiā lí xuéxiào yǒu wǔ gōnglǐ yuǎn.","vi":"Nhà tôi cách trường học 5 ki-lô-mét."},{"type":"simple","zh":"爸爸每天早上都会沿着河边跑五公里，已经坚持好几年了。","pinyin":"Bàba měitiān zǎoshang dōuhuì yánzhe hébiān pǎo wǔ gōnglǐ, yǐjīng jiānchí hǎojǐnián le.","vi":"Bố mỗi sáng đều chạy bộ 5 ki-lô-mét dọc bờ sông, đã kiên trì mấy năm liền rồi."},{"type":"compound","zh":"中国的高速铁路非常发达，高铁每小时的运行速度可以达到三百五十公里。","pinyin":"Zhōngguó de gāosùtiělù fēicháng fādá, gāotiě měi xiǎoshí de yùnxíng sùdù kěyǐ dádào sān bǎi wǔshí gōnglǐ.","vi":"Đường sắt cao tốc Trung Quốc vô cùng phát triển, tốc độ vận hành mỗi giờ của tàu cao tốc có thể đạt tới 350 ki-lô-mét."}],"related":[{"hanzi":"距离","pinyin":"jùlí","vi":"Khoảng cách"},{"hanzi":"高速公路","pinyin":"gāosùgōnglù","vi":"Đường cao tốc"},{"hanzi":"里","pinyin":"lǐ","vi":"Dặm/Trong"},{"hanzi":"远","pinyin":"yuǎn","vi":"Xa"},{"hanzi":"速度","pinyin":"sùdù","vi":"Tốc độ"}]},{"id":"功夫","hanzi":"功夫","pinyin":"gōngfu","meaning_vi":"võ thuật, kung fu; công phu, công sức; thời gian","explanation":"功 (công sức) + 夫.","hsk_level":3,"tags":["danh-tu","van-hoa","the-thao"],"image":"🥋","examples":[{"type":"basic","zh":"很多外国人都喜欢中国功夫。","pinyin":"Hěn duō wàiguórén dōu xǐhuan Zhōngguó gōngfu.","vi":"Rất nhiều người nước ngoài đều thích võ thuật Trung Quốc."},{"type":"simple","zh":"要想写出一手漂亮的毛笔字，必须下苦功夫每天坚持练习。","pinyin":"Yào xiǎng xiě chū yìshǒu piàoliang de máobǐ zì, bìxū xià kǔ gōngfu měitiān jiānchí liànxí.","vi":"Muốn viết được chữ thư pháp đẹp, bắt buộc phải bỏ công sức khổ luyện mỗi ngày."},{"type":"compound","zh":"因为今天下午我正好有空儿，所以就抽功夫去图书馆把借的书还了。","pinyin":"Yīnwèi jīntiān xiàwǔ wǒ zhènghǎo yǒukòngr, suǒyǐ jiù chōu gōngfu qù túshūguǎn bǎ jiè de shū huán le.","vi":"Vì chiều nay tôi vừa hay rảnh rỗi nên đã tranh thủ thời gian tới thư viện trả sách đã mượn."}],"related":[{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"Chồng"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"}]},{"id":"共同","hanzi":"共同","pinyin":"gòngtóng","meaning_vi":"chung, cùng nhau","explanation":"共 (cộng lại) + 同 (cùng).","hsk_level":3,"tags":["tinh-tu","pho-tu"],"image":"🤝","examples":[{"type":"basic","zh":"保护环境是我们共同的责任。","pinyin":"Bǎohù huánjìng shì wǒmen gòngtóng de zérèn.","vi":"Bảo vệ môi trường là trách nhiệm chung của chúng ta."},{"type":"simple","zh":"我们两个人因为有着共同的音乐爱好，所以很快就成了好朋友。","pinyin":"Wǒmen liǎng ge rén yīnwèi yǒuzhe gòngtóng de yīnyuè àihào, suǒyǐ hěn kuài jiù chéngle hǎopéngyou.","vi":"Hai chúng tôi vì có chung sở thích âm nhạc nên chẳng mấy chốc đã trở thành bạn thân."},{"type":"compound","zh":"经过全班同学和老师的共同努力，我们班在这次文艺演出中获得了一等奖。","pinyin":"Jīngguò quánbān tóngxué hé lǎoshī de gòngtóng nǔlì, wǒmen bān zài zhè cì wényì yǎnchū zhōng huòdéle yìděngjiǎng.","vi":"Nhờ sự nỗ lực chung của cả lớp và thầy giáo, lớp chúng tôi đã giành giải nhất trong buổi biểu diễn văn nghệ lần này."}],"related":[{"hanzi":"公共汽车","pinyin":"gōnggòngqìchē","vi":"Xe buýt"},{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Giống nhau"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"合作","pinyin":"hézuò","vi":"Hợp tác"},{"hanzi":"一起","pinyin":"yìqǐ","vi":"Cùng nhau"}]},{"id":"购物","hanzi":"购物","pinyin":"gòuwù","meaning_vi":"mua sắm","explanation":"购 (mua) + 物 (đồ vật).","hsk_level":3,"tags":["dong-tu","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"周末我喜欢去商场购物。","pinyin":"Zhōumò wǒ xǐhuan qù shāngchǎng gòuwù.","vi":"Cuối tuần tôi thích đi trung tâm thương mại mua sắm."},{"type":"simple","zh":"现在网上购物非常方便，足不出户就能买到世界各地的商品。","pinyin":"Xiànzài wǎngshang gòuwù fēicháng fāngbiàn, zú bù chū hù jiù néng mǎi dào shìjiè gèdì de shāngpǐn.","vi":"Hiện nay mua sắm trực tuyến vô cùng tiện lợi, không cần bước chân ra khỏi nhà cũng mua được hàng hóa khắp nơi trên thế giới."},{"type":"compound","zh":"虽然打折的时候购物很划算，但是我们也要理性消费，不要买用不着的东西。","pinyin":"Suīrán dǎzhé de shíhou gòuwù hěn huásuàn, dànshì wǒmen yě yào lǐxìngxiāofèi, bú yào mǎi yòngbùzháo de dōngxi.","vi":"Tuy mua sắm lúc giảm giá rất hời nhưng chúng ta cũng cần tiêu dùng lý trí, đừng mua những thứ không dùng tới."}],"related":[{"hanzi":"逛","pinyin":"guàng","vi":"Dạo phố"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"付款","pinyin":"fùkuǎn","vi":"Thanh toán"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"},{"hanzi":"礼物","pinyin":"lǐwù","vi":"Quà tặng"}],"traditional":"購物"},{"id":"够","hanzi":"够","pinyin":"gòu","meaning_vi":"đủ","explanation":"Vừa là tính từ (钱不够 - không đủ tiền) vừa là phó từ.","hsk_level":3,"tags":["tinh-tu","pho-tu"],"image":"👌","examples":[{"type":"basic","zh":"我带的现金已经够了。","pinyin":"Wǒ dài de xiànjīn yǐjīng gòu le.","vi":"Tiền mặt tôi mang theo đã đủ rồi."},{"type":"simple","zh":"今天妈妈做的饭菜分量非常足，完全够我们全家人吃了。","pinyin":"Jīntiān māma zuò de fàncài fènliàng fēicháng zú, wánquán gòu wǒmen quán jiārén chī le.","vi":"Hôm nay lượng cơm canh mẹ nấu rất đầy đặn, hoàn toàn đủ cho cả nhà tôi ăn."},{"type":"compound","zh":"虽然我现在的汉语水平还不够流利，但是我相信只要坚持练习一定会越来越好。","pinyin":"Suīrán wǒ xiànzài de Hànyǔ shuǐpíng hái búgòu liúlì, dànshì wǒ xiāngxìn zhǐyào jiānchí liànxí yídìng huì yuèláiyuè hǎo.","vi":"Tuy trình độ tiếng Trung hiện tại của tôi vẫn chưa đủ trôi chảy nhưng tôi tin chỉ cần kiên trì luyện tập nhất định sẽ ngày càng tốt hơn."}],"related":[{"hanzi":"满足","pinyin":"mǎnzú","vi":"Thỏa mãn"},{"hanzi":"满","pinyin":"mǎn","vi":"Đầy"},{"hanzi":"多","pinyin":"duō","vi":"Nhiều"},{"hanzi":"少","pinyin":"shǎo","vi":"Ít"},{"hanzi":"数量","pinyin":"shùliàng","vi":"Số lượng"}],"traditional":"夠"},{"id":"估计","hanzi":"估计","pinyin":"gūjì","meaning_vi":"ước tính, phỏng đoán","explanation":"估 (ước lượng) + 计 (tính toán).","hsk_level":3,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"我估计他今天不会来了。","pinyin":"Wǒ gūjì tā jīntiān bú huì lái le.","vi":"Tôi ước chừng hôm nay anh ấy sẽ không đến đâu."},{"type":"simple","zh":"看外面天阴沉沉的样子，我估计再过半个小时肯定要下大雨了。","pinyin":"Kàn wàimiàn tiān yīnchénchén de yàngzi, wǒ gūjì zài guòbàn ge xiǎoshí kěndìng yào xià dàyǔ le.","vi":"Nhìn vẻ ngoài trời âm u mây mù thế kia, tôi đoán chừng nửa tiếng nữa chắc chắn trời sẽ mưa to."},{"type":"compound","zh":"由于早高峰路上堵车非常严重，我估计到达机场的时间要比原计划晚二十分钟。","pinyin":"Yóuyú zǎogāofēng lùshang dǔchē fēicháng yánzhòng, wǒ gūjì dàodá jīchǎng de shíjiān yào bǐ yuán jìhuà wǎn èrshí fēnzhōng.","vi":"Do giờ cao điểm buổi sáng trên đường tắc xe rất nghiêm trọng, tôi ước tính thời gian tới sân bay sẽ muộn hơn dự kiến 20 phút."}],"related":[{"hanzi":"猜","pinyin":"cāi","vi":"Đoán"},{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"大约","pinyin":"dàyuē","vi":"Ước chừng"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có thể"},{"hanzi":"判断","pinyin":"pànduàn","vi":"Phán đoán"}],"traditional":"估計"},{"id":"鼓励","hanzi":"鼓励","pinyin":"gǔlì","meaning_vi":"khích lệ, động viên","explanation":"鼓 (đánh trống cổ vũ) + 励 (khuyến khích).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"老师经常鼓励我们多说汉语。","pinyin":"Lǎoshī jīngcháng gǔlì wǒmen duō shuō Hànyǔ.","vi":"Thầy giáo thường xuyên khích lệ chúng tôi nói tiếng Trung nhiều hơn."},{"type":"simple","zh":"在父母和朋友的鼓励下，她终于鼓起勇气报名参加了歌唱比赛。","pinyin":"Zài fùmǔ hé péngyou de gǔlì xià, tā zhōngyú gǔqǐ yǒngqì bàomíng cānjiāle gēchàng bǐsài.","vi":"Dưới sự động viên của bố mẹ và bạn bè, cô ấy cuối cùng đã lấy hết dũng khí đăng ký tham gia cuộc thi hát."},{"type":"compound","zh":"当孩子遇到挫折感到失望的时候，一句温暖的鼓励往往能带给他们无穷的力量。","pinyin":"Dāng háizi yùdào cuòzhé gǎndào shīwàng de shíhou, yíjù wēnnuǎn de gǔlì wǎngwǎng néng dàigěi tāmen wúqióng de lìliàng.","vi":"Khi trẻ gặp trắc trở và cảm thấy thất vọng, một lời khích lệ ấm áp thường mang lại cho trẻ sức mạnh vô cùng."}],"related":[{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"},{"hanzi":"支持","pinyin":"zhīchí","vi":"Ủng hộ"},{"hanzi":"信心","pinyin":"xìnxīn","vi":"Lòng tin"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"Dũng cảm"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"}],"traditional":"鼓勵"},{"id":"故意","hanzi":"故意","pinyin":"gùyì","meaning_vi":"cố ý, cố tình","explanation":"故 (có chủ đích) + 意 (ý muốn).","hsk_level":3,"tags":["pho-tu"],"image":"😏","examples":[{"type":"basic","zh":"对不起，我不是故意的。","pinyin":"Duìbuqǐ, wǒ bú shì gùyì de.","vi":"Xin lỗi, tôi không cố ý đâu."},{"type":"simple","zh":"他刚才是不小心才把你的杯子碰倒的，并不是故意要弄坏它的。","pinyin":"Tā gāngcái shì bù xiǎoxīn cái bǎ nǐ de bēizi pèngdǎo de, bìngbú shì gùyì yào nònghuài tā de.","vi":"Vừa nãy anh ấy chỉ vô tình làm đổ cốc của bạn thôi chứ hoàn toàn không cố ý làm hỏng nó."},{"type":"compound","zh":"既然他已经解释清楚自己不是故意的，而且真诚地向你道歉了，你就原谅他吧。","pinyin":"Jìrán tā yǐjīng jiěshì qīngchu zìjǐ bú shì gùyì de, érqiě zhēnchéng de xiàng nǐ dàoqiàn le, nǐ jiù yuánliàng tā ba.","vi":"Vì anh ấy đã giải thích rõ bản thân không cố ý và chân thành xin lỗi bạn rồi, bạn hãy tha thứ cho anh ấy đi."}],"related":[{"hanzi":"故事","pinyin":"gùshi","vi":"Câu chuyện"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"Ý kiến"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"误会","pinyin":"wùhuì","vi":"Hiểu lầm"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"Tha thứ"}]},{"id":"顾客","hanzi":"顾客","pinyin":"gùkè","meaning_vi":"khách hàng","explanation":"顾 (ghé thăm) + 客 (khách).","hsk_level":3,"tags":["danh-tu","mua-sam","con-nguoi"],"image":"🛍️","examples":[{"type":"basic","zh":"这家超市的顾客非常多。","pinyin":"Zhè jiā chāoshì de gùkè fēichángduō.","vi":"Khách hàng của siêu thị này vô cùng đông."},{"type":"simple","zh":"为了吸引更多顾客，这家商场周末推出了全场商品打八折的活动。","pinyin":"Wèile xīyǐn gèng duō gùkè, zhè jiā shāngchǎng zhōumò tuīchūle quánchǎng shāngpǐn dǎ bā zhé de huódòng.","vi":"Để thu hút thêm nhiều khách hàng, trung tâm thương mại này cuối tuần đã tung ra chương trình giảm giá 20% toàn bộ sản phẩm."},{"type":"compound","zh":"无论对什么样的顾客，售货员都应该保持微笑、耐心解答他们提出的问题。","pinyin":"Wúlùn duì shénmeyàng de gùkè, shòuhuòyuán dōu yīnggāi bǎochí wēixiào, nàixīn jiědá tāmen tíchū de wèntí.","vi":"Bất kể đối với khách hàng nào, nhân viên bán hàng cũng nên giữ nụ cười và kiên nhẫn giải đáp các câu hỏi họ đưa ra."}],"related":[{"hanzi":"客人","pinyin":"kèrén","vi":"Khách"},{"hanzi":"售货员","pinyin":"shòuhuòyuán","vi":"Nhân viên bán hàng"},{"hanzi":"照顾","pinyin":"zhàogu","vi":"Chăm sóc"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"购物","pinyin":"gòuwù","vi":"Mua sắm"}],"traditional":"顧客"},{"id":"关键","hanzi":"关键","pinyin":"guānjiàn","meaning_vi":"mấu chốt, then chốt","explanation":"关 (cửa ải) + 键 (chốt khóa).","hsk_level":3,"tags":["danh-tu","tinh-tu"],"image":"🔑","examples":[{"type":"basic","zh":"学好汉语的关键是多说多练。","pinyin":"Xuéhǎo Hànyǔ de guānjiàn shì duō shuō duō liàn.","vi":"Chìa khóa để học giỏi tiếng Trung là nói nhiều luyện nhiều."},{"type":"simple","zh":"现在正是复习准备期末考试的关键时期，大家一定要抓紧时间。","pinyin":"Xiànzài zhèngshì fùxí zhǔnbèi qīmò kǎoshì de guānjiàn shíqī, dàjiā yídìngyào zhuājǐn shíjiān.","vi":"Hiện tại chính là giai đoạn then chốt để ôn tập chuẩn bị thi cuối kỳ, mọi người nhất định phải tranh thủ thời gian."},{"type":"compound","zh":"在比赛中，虽然全队的配合很重要，但是在关键时刻保持冷静心态同样不可或缺。","pinyin":"Zài bǐsài zhōng, suīrán quán duì de pèihé hěn zhòngyào, dànshì zài guānjiànshíkè bǎochí lěngjìng xīntài tóngyàng bùkě huòquē.","vi":"Trong thi đấu, tuy sự phối hợp toàn đội rất quan trọng nhưng việc giữ tâm lý bình tĩnh vào thời khắc then chốt cũng không thể thiếu."}],"related":[{"hanzi":"重要","pinyin":"zhòngyào","vi":"Quan trọng"},{"hanzi":"重点","pinyin":"zhòngdiǎn","vi":"Trọng điểm"},{"hanzi":"关系","pinyin":"guānxi","vi":"Quan hệ"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"方法","pinyin":"fāngfǎ","vi":"Phương pháp"}],"traditional":"關鍵"},{"id":"观众","hanzi":"观众","pinyin":"guānzhòng","meaning_vi":"khán giả","explanation":"观 (xem) + 众 (đám đông).","hsk_level":3,"tags":["danh-tu","giai-tri","con-nguoi"],"image":"👥","examples":[{"type":"basic","zh":"台下的观众热烈鼓掌。","pinyin":"Táixià de guānzhòng rèliè gǔzhǎng.","vi":"Khán giả dưới khán đài vỗ tay nhiệt liệt."},{"type":"simple","zh":"这部新上映的喜剧电影非常幽默，逗得电影院里的观众哈哈大笑。","pinyin":"Zhè bù xīn shàngyìng de xǐjù diànyǐng fēicháng yōumò, dòu de diànyǐngyuàn lǐ de guānzhòng hāhā dàxiào.","vi":"Bộ phim hài mới công chiếu này vô cùng hài hước, làm khán giả trong rạp cười nghiêng ngả."},{"type":"compound","zh":"演员们在舞台上卖力地表演京剧，赢得了现场所有观众的高度赞扬。","pinyin":"Yǎnyuánmen zài wǔtái shang màilì de biǎoyǎn Jīngjù, yíng déle xiànchǎng suǒyǒu guānzhòng de gāodù zànyáng.","vi":"Các diễn viên biểu diễn Kinh kịch hết mình trên sân khấu, nhận được sự khen ngợi nhiệt liệt của toàn thể khán giả có mặt."}],"related":[{"hanzi":"参观","pinyin":"cānguān","vi":"Tham quan"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"Diễn viên"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"Biểu diễn"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"Buổi diễn"},{"hanzi":"电影院","pinyin":"diànyǐngyuàn","vi":"Rạp chiếu phim"}],"traditional":"觀眾"},{"id":"光","hanzi":"光","pinyin":"guāng","meaning_vi":"ánh sáng; chỉ, chỉ có; hết sạch","explanation":"Vừa là danh từ (阳光 - ánh nắng) vừa là phó từ nghĩa là 'chỉ'.","hsk_level":3,"tags":["danh-tu","pho-tu"],"image":"✨","examples":[{"type":"basic","zh":"房间里的灯光很明亮。","pinyin":"Fángjiān lǐ de dēngguāng hěn míngliàng.","vi":"Ánh đèn trong phòng rất sáng sủa."},{"type":"simple","zh":"学习外语不能光靠背单词，还必须在日常生活和对话中多加练习。","pinyin":"Xuéxí wàiyǔ bù néng guāng kàobèi dāncí, hái bìxū zài rìcháng shēnghuó hé duìhuà zhōng duō jiā liànxí.","vi":"Học ngoại ngữ không thể chỉ dựa vào học thuộc từ vựng mà còn phải luyện tập nhiều trong sinh hoạt và hội thoại hằng ngày."},{"type":"compound","zh":"因为妈妈做的红烧鱼太好吃了，所以没过十分钟就被大家吃光了。","pinyin":"Yīnwèi māma zuò de hóngshāo yú tài hǎochī le, suǒyǐ méi guò shí fēnzhōng jiù bèi dàjiā chī guāng le.","vi":"Vì món cá kho mẹ nấu ngon quá nên chưa đầy 10 phút đã bị mọi người ăn sạch hết."}],"related":[{"hanzi":"阳光","pinyin":"yángguāng","vi":"Ánh nắng"},{"hanzi":"灯","pinyin":"dēng","vi":"Đèn"},{"hanzi":"只","pinyin":"zhǐ","vi":"Chỉ"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"亮","pinyin":"liàng","vi":"Sáng"}]},{"id":"国际","hanzi":"国际","pinyin":"Guójì","meaning_vi":"quốc tế","explanation":"国 (quốc gia) + 际 (giao tiếp giữa các bên).","hsk_level":3,"tags":["tinh-tu","dia-danh"],"image":"🌐","examples":[{"type":"basic","zh":"北京是一座国际化大都市。","pinyin":"Běijīng shì yí zuò guójìhuà dàdūshì.","vi":"Bắc Kinh là một đại đô thị quốc tế hóa."},{"type":"simple","zh":"明天下午我们要去首都国际机场迎接来自世界各地的参赛选手。","pinyin":"Míngtiān xiàwǔ wǒmen yào qù Shǒudūguójìjīchǎng yíngjiē láizì shìjiè gèdì de cānsài xuǎnshǒu.","vi":"Chiều mai chúng tôi phải ra Sân bay Quốc tế Thủ đô đón các thí sinh tham dự cuộc thi đến từ khắp nơi trên thế giới."},{"type":"compound","zh":"随着国际交流的日益频繁，掌握汉语和英语双语能力的人才越来越受企业欢迎。","pinyin":"Suízhe Guójì jiāoliú de rìyì pínfán, zhǎngwò Hànyǔ hé Yīngyǔ shuāngyǔ nénglì de réncái yuèláiyuè shòu qǐyè huānyíng.","vi":"Cùng với sự giao lưu quốc tế ngày càng thường xuyên, nhân tài thông thạo song ngữ Trung - Anh ngày càng được doanh nghiệp săn đón."}],"related":[{"hanzi":"国家","pinyin":"guójiā","vi":"Quốc gia"},{"hanzi":"实际","pinyin":"shíjì","vi":"Thực tế"},{"hanzi":"亚洲","pinyin":"Yàzhōu","vi":"Châu Á"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"}],"traditional":"國際"},{"id":"果然","hanzi":"果然","pinyin":"guǒrán","meaning_vi":"quả nhiên, đúng như dự đoán","explanation":"果 (kết quả) + 然.","hsk_level":3,"tags":["pho-tu"],"image":"💡","examples":[{"type":"basic","zh":"天气预报说有雨，下午果然下雨了。","pinyin":"Tiānqì yùbào shuō yǒu yǔ, xiàwǔ guǒrán xiàyǔ le.","vi":"Dự báo thời tiết nói có mưa, buổi chiều quả nhiên trời đổ mưa rồi."},{"type":"simple","zh":"大家都说这家老字号饭店的烤鸭正宗，今天来品尝以后果然名不虚传。","pinyin":"Dàjiā dōu shuō zhè jiālǎo zìhào fàndiàn de kǎoyā zhèngzōng, jīntiān lái pǐncháng yǐhòu guǒrán míngbùxūchuán.","vi":"Mọi người đều nói vịt quay của nhà hàng lâu đời này chuẩn vị, hôm nay đến thưởng thức quả nhiên danh bất hư truyền."},{"type":"compound","zh":"我昨天估计他肯定会准时到达机场，今天早上他果然提前十分钟就到了。","pinyin":"Wǒ zuótiān gūjì tā kěndìng huì zhǔnshí dàodá jīchǎng, jīntiān zǎoshang tā guǒrán tíqián shí fēnzhōng jiù dào le.","vi":"Hôm qua tôi đoán chắc chắn anh ấy sẽ tới sân bay đúng giờ, sáng nay quả nhiên anh ấy đã có mặt sớm trước 10 phút."}],"related":[{"hanzi":"果真","pinyin":"guǒzhēn","vi":"quả thật"},{"hanzi":"竟然","pinyin":"jìngrán","vi":"vậy mà"},{"hanzi":"突然","pinyin":"tūrán","vi":"đột nhiên"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"kết quả"}]},{"id":"过程","hanzi":"过程","pinyin":"guòchéng","meaning_vi":"quá trình","explanation":"过 (trải qua) + 程 (chặng đường).","hsk_level":3,"tags":["danh-tu"],"image":"🔄","examples":[{"type":"basic","zh":"学习是一个不断积累的过程。","pinyin":"Xuéxí shì yí ge búduàn jīlěi de guòchéng.","vi":"Học tập là một quá trình tích lũy không ngừng."},{"type":"simple","zh":"在准备这次汉语演讲比赛的过程中，我的口语表达能力得到了很大锻炼。","pinyin":"Zài zhǔnbèi zhè cì Hànyǔ yǎnjiǎng bǐsài de guòchéng zhōng, wǒ de kǒuyǔ biǎodá nénglì dédàole hěn dà duànliàn.","vi":"Trong quá trình chuẩn bị cho cuộc thi hùng biện tiếng Trung lần này, khả năng diễn đạt khẩu ngữ của tôi đã được rèn luyện rất nhiều."},{"type":"compound","zh":"无论是比赛还是工作，有时候享受奋斗的过程比最终的结果更加重要。","pinyin":"Wúlùn shì bǐsài háishi gōngzuò, yǒushíhou xiǎngshòu fèndòu de guòchéng bǐ zuìzhōng de jiéguǒ gèngjiā zhòngyào.","vi":"Dù là thi đấu hay làm việc, đôi khi tận hưởng quá trình phấn đấu còn quan trọng hơn cả kết quả cuối cùng."}],"related":[{"hanzi":"经过","pinyin":"jīngguò","vi":"Trải qua"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"过","pinyin":"guo","vi":"Qua/Từng"},{"hanzi":"积累","pinyin":"jīlěi","vi":"Tích lũy"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"}],"traditional":"過程"},{"id":"按时","hanzi":"按时","pinyin":"ànshí","meaning_vi":"đúng giờ, đúng hạn","explanation":"按 (theo) + 时 (giờ) → làm theo đúng thời gian đã định. Gần nghĩa 准时, nhưng 按时 hay dùng cho việc phải làm theo lịch: 按时吃药, 按时完成.","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"你要按时吃药。","pinyin":"Nǐ yào ànshí chī yào.","vi":"Bạn phải uống thuốc đúng giờ."},{"type":"simple","zh":"老师说这次的作业一定要按时交。","pinyin":"Lǎoshī shuō zhè cì de zuòyè yídìng yào ànshí jiāo.","vi":"Cô giáo nói bài tập lần này nhất định phải nộp đúng hạn."},{"type":"compound","zh":"如果你每天按时睡觉、按时起床，身体就会越来越好。","pinyin":"Rúguǒ nǐ měitiān ànshí shuìjiào, ànshí qǐchuáng, shēntǐ jiù huì yuè lái yuè hǎo.","vi":"Nếu mỗi ngày bạn đi ngủ đúng giờ, thức dậy đúng giờ thì sức khỏe sẽ ngày càng tốt."}],"related":[{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"及时","pinyin":"jíshí","vi":"Kịp thời"},{"hanzi":"按照","pinyin":"ànzhào","vi":"Theo"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"迟到","pinyin":"chídào","vi":"Đến muộn"}],"traditional":"按時"},{"id":"按照","hanzi":"按照","pinyin":"ànzhào","meaning_vi":"theo, dựa theo","explanation":"Giới từ, đứng trước danh từ chỉ quy định, kế hoạch: 按照计划, 按照要求. Gần nghĩa 根据 (căn cứ vào), nhưng 按照 nhấn mạnh làm đúng theo.","hsk_level":3,"tags":["gioi-tu"],"image":"📋","examples":[{"type":"basic","zh":"请按照顺序排队。","pinyin":"Qǐng ànzhào shùnxù páiduì.","vi":"Xin hãy xếp hàng theo thứ tự."},{"type":"simple","zh":"我们按照老师的要求，每天写一篇日记。","pinyin":"Wǒmen ànzhào lǎoshī de yāoqiú, měitiān xiě yì piān rìjì.","vi":"Theo yêu cầu của thầy giáo, mỗi ngày chúng tôi viết một bài nhật ký."},{"type":"compound","zh":"如果大家都按照规定做，这件事就不会出问题了。","pinyin":"Rúguǒ dàjiā dōu ànzhào guīdìng zuò, zhè jiàn shì jiù bú huì chū wèntí le.","vi":"Nếu mọi người đều làm theo quy định thì việc này sẽ không có vấn đề gì."}],"related":[{"hanzi":"按时","pinyin":"ànshí","vi":"Đúng giờ"},{"hanzi":"根据","pinyin":"gēnjù","vi":"Căn cứ vào"},{"hanzi":"照","pinyin":"zhào","vi":"Theo, chiếu"},{"hanzi":"规定","pinyin":"guīdìng","vi":"Quy định"},{"hanzi":"计划","pinyin":"jìhuà","vi":"Kế hoạch"}]},{"id":"报名","hanzi":"报名","pinyin":"bàomíng","meaning_vi":"đăng ký, ghi danh","explanation":"报 (báo) + 名 (tên) → báo tên để đăng ký tham gia. Là động từ ly hợp: 报了名; hay đi với 参加: 报名参加比赛.","hsk_level":3,"tags":["dong-tu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"我想报名参加比赛。","pinyin":"Wǒ xiǎng bàomíng cānjiā bǐsài.","vi":"Tôi muốn đăng ký tham gia cuộc thi."},{"type":"simple","zh":"小王昨天已经在网上报名了，下个月就去考试。","pinyin":"Xiǎo Wáng zuótiān yǐjīng zài wǎngshang bàomíng le, xià gè yuè jiù qù kǎoshì.","vi":"Hôm qua Tiểu Vương đã đăng ký trên mạng, tháng sau sẽ đi thi."},{"type":"compound","zh":"因为报名的人太多了，所以学校决定再开一个汉语班。","pinyin":"Yīnwèi bàomíng de rén tài duō le, suǒyǐ xuéxiào juédìng zài kāi yí gè Hànyǔ bān.","vi":"Vì người đăng ký quá đông nên nhà trường quyết định mở thêm một lớp tiếng Trung."}],"related":[{"hanzi":"名字","pinyin":"míngzi","vi":"Tên"},{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"Nộp đơn xin"},{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"Báo"},{"hanzi":"有名","pinyin":"yǒumíng","vi":"Nổi tiếng"}],"traditional":"報名"},{"id":"出生","hanzi":"出生","pinyin":"chūshēng","meaning_vi":"sinh ra, ra đời","explanation":"出 (ra) + 生 (sinh) → sinh ra. Hay dùng: 出生在 + nơi chốn, hoặc 是 + thời gian + 出生的.","hsk_level":3,"tags":["dong-tu","con-nguoi"],"image":"👶","examples":[{"type":"basic","zh":"我出生在北京。","pinyin":"Wǒ chūshēng zài Běijīng.","vi":"Tôi sinh ra ở Bắc Kinh."},{"type":"simple","zh":"我妹妹是二零一五年春天出生的。","pinyin":"Wǒ mèimei shì èr líng yī wǔ nián chūntiān chūshēng de.","vi":"Em gái tôi sinh vào mùa xuân năm 2015."},{"type":"compound","zh":"虽然他出生在中国，但是从小在越南长大，所以越南语说得很好。","pinyin":"Suīrán tā chūshēng zài Zhōngguó, dànshì cóngxiǎo zài Yuènán zhǎngdà, suǒyǐ Yuènányǔ shuō de hěn hǎo.","vi":"Tuy anh ấy sinh ra ở Trung Quốc nhưng lớn lên ở Việt Nam từ nhỏ, nên nói tiếng Việt rất giỏi."}],"related":[{"hanzi":"生日","pinyin":"shēngrì","vi":"Sinh nhật"},{"hanzi":"出现","pinyin":"chūxiàn","vi":"Xuất hiện"},{"hanzi":"年龄","pinyin":"niánlíng","vi":"Tuổi tác"},{"hanzi":"孩子","pinyin":"háizi","vi":"Đứa trẻ"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"Cuộc sống"}]},{"id":"大夫","hanzi":"大夫","pinyin":"dàifu","meaning_vi":"bác sĩ","explanation":"Đọc dàifu khi nghĩa là bác sĩ (khẩu ngữ, giống 医生), hay dùng kèm họ: 李大夫. Đọc dàfū là chức quan thời xưa.","hsk_level":3,"tags":["danh-tu","nghe-nghiep","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"李大夫今天不在医院。","pinyin":"Lǐ dàifu jīntiān bú zài yīyuàn.","vi":"Hôm nay bác sĩ Lý không có ở bệnh viện."},{"type":"simple","zh":"我发烧了，妈妈马上带我去医院看大夫。","pinyin":"Wǒ fāshāo le, māma mǎshàng dài wǒ qù yīyuàn kàn dàifu.","vi":"Tôi bị sốt, mẹ lập tức đưa tôi đến bệnh viện khám bác sĩ."},{"type":"compound","zh":"大夫说，如果我每天按时吃药，一个星期以后就能好了。","pinyin":"Dàifu shuō, rúguǒ wǒ měitiān ànshí chī yào, yí gè xīngqī yǐhòu jiù néng hǎo le.","vi":"Bác sĩ nói, nếu ngày nào tôi cũng uống thuốc đúng giờ thì một tuần sau là có thể khỏi."}],"related":[{"hanzi":"医生","pinyin":"yīshēng","vi":"Bác sĩ"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"},{"hanzi":"护士","pinyin":"hùshi","vi":"Y tá"},{"hanzi":"病人","pinyin":"bìngrén","vi":"Bệnh nhân"},{"hanzi":"看病","pinyin":"kànbìng","vi":"Khám bệnh"}]},{"id":"弹","hanzi":"弹","pinyin":"tán","meaning_vi":"gảy, đánh (đàn)","explanation":"Đọc tán khi là gảy, chơi đàn: 弹钢琴, 弹吉他. Đọc dàn nghĩa là viên đạn: 子弹.","hsk_level":3,"tags":["dong-tu","giai-tri"],"image":"🎹","examples":[{"type":"basic","zh":"她会弹钢琴。","pinyin":"Tā huì tán gāngqín.","vi":"Cô ấy biết chơi đàn piano."},{"type":"simple","zh":"我哥哥每天晚上都在房间里弹一个小时吉他。","pinyin":"Wǒ gēge měitiān wǎnshang dōu zài fángjiān li tán yí gè xiǎoshí jítā.","vi":"Tối nào anh trai tôi cũng chơi đàn ghi-ta một tiếng trong phòng."},{"type":"compound","zh":"虽然她学弹钢琴才一年，但是已经弹得非常好了。","pinyin":"Suīrán tā xué tán gāngqín cái yì nián, dànshì yǐjīng tán de fēicháng hǎo le.","vi":"Tuy cô ấy mới học đàn piano được một năm nhưng đã chơi rất hay rồi."}],"related":[{"hanzi":"钢琴","pinyin":"gāngqín","vi":"Đàn piano"},{"hanzi":"吉他","pinyin":"jítā","vi":"Đàn ghi-ta"},{"hanzi":"音乐","pinyin":"yīnyuè","vi":"Âm nhạc"},{"hanzi":"唱歌","pinyin":"chànggē","vi":"Hát"},{"hanzi":"子弹","pinyin":"zǐdàn","vi":"Viên đạn"}],"traditional":"彈"},{"id":"当","hanzi":"当","pinyin":"dāng","meaning_vi":"làm, đảm nhận (vai trò); khi, lúc","explanation":"当 + nghề nghiệp/chức vụ: 当老师 (làm giáo viên). Cấu trúc 当…的时候 = khi…. Đọc dàng trong 上当 (mắc lừa).","hsk_level":3,"tags":["dong-tu","nghe-nghiep"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"我想当老师。","pinyin":"Wǒ xiǎng dāng lǎoshī.","vi":"Tôi muốn làm giáo viên."},{"type":"simple","zh":"他在我们班当了两年班长，同学们都很喜欢他。","pinyin":"Tā zài wǒmen bān dāngle liǎng nián bānzhǎng, tóngxuémen dōu hěn xǐhuan tā.","vi":"Anh ấy đã làm lớp trưởng ở lớp chúng tôi hai năm, các bạn trong lớp đều rất quý anh ấy."},{"type":"compound","zh":"当我在国外遇到困难的时候，朋友们总是马上来帮助我。","pinyin":"Dāng wǒ zài guówài yùdào kùnnan de shíhou, péngyoumen zǒngshì mǎshàng lái bāngzhù wǒ.","vi":"Khi tôi gặp khó khăn ở nước ngoài, bạn bè luôn lập tức đến giúp đỡ tôi."}],"related":[{"hanzi":"当时","pinyin":"dāngshí","vi":"Lúc đó"},{"hanzi":"当然","pinyin":"dāngrán","vi":"Đương nhiên"},{"hanzi":"应当","pinyin":"yīngdāng","vi":"Nên"},{"hanzi":"上当","pinyin":"shàngdàng","vi":"Mắc lừa"},{"hanzi":"当地","pinyin":"dāngdì","vi":"Địa phương"}],"traditional":"當"},{"id":"当时","hanzi":"当时","pinyin":"dāngshí","meaning_vi":"lúc đó, khi ấy","explanation":"当 (đúng vào) + 时 (lúc) → chính lúc đó, chỉ một thời điểm trong quá khứ. Đọc dàngshí thì nghĩa là ngay lập tức (ít dùng).","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"当时我很害怕。","pinyin":"Dāngshí wǒ hěn hàipà.","vi":"Lúc đó tôi rất sợ."},{"type":"simple","zh":"我们第一次见面是在机场，当时他穿着一件红衣服。","pinyin":"Wǒmen dìyī cì jiànmiàn shì zài jīchǎng, dāngshí tā chuānzhe yí jiàn hóng yīfu.","vi":"Lần đầu chúng tôi gặp nhau là ở sân bay, lúc đó anh ấy mặc một chiếc áo đỏ."},{"type":"compound","zh":"虽然当时我觉得这个决定很难，但是现在我一点也不后悔。","pinyin":"Suīrán dāngshí wǒ juéde zhège juédìng hěn nán, dànshì xiànzài wǒ yìdiǎn yě bù hòuhuǐ.","vi":"Tuy lúc đó tôi thấy quyết định này rất khó, nhưng bây giờ tôi không hối hận chút nào."}],"related":[{"hanzi":"当","pinyin":"dāng","vi":"Khi"},{"hanzi":"那时候","pinyin":"nà shíhou","vi":"Lúc đó"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"后来","pinyin":"hòulái","vi":"Sau đó"}],"traditional":"當時"},{"id":"发","hanzi":"发","pinyin":"fā","meaning_vi":"gửi, phát (ra); nảy sinh, bị (sốt…)","explanation":"Hay gặp: 发短信 (gửi tin nhắn), 发邮件, 发奖金 (phát thưởng), 发烧 (bị sốt). Đọc fà khi nghĩa là tóc: 头发.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"📤","examples":[{"type":"basic","zh":"我给妈妈发了短信。","pinyin":"Wǒ gěi māma fāle duǎnxìn.","vi":"Tôi đã gửi tin nhắn cho mẹ."},{"type":"simple","zh":"公司下个月要给每个人发两千块钱奖金。","pinyin":"Gōngsī xià gè yuè yào gěi měi gè rén fā liǎngqiān kuài qián jiǎngjīn.","vi":"Tháng sau công ty sẽ phát cho mỗi người hai nghìn tệ tiền thưởng."},{"type":"compound","zh":"我昨天给你发了邮件，如果你收到了，就给我回个电话吧。","pinyin":"Wǒ zuótiān gěi nǐ fāle yóujiàn, rúguǒ nǐ shōudào le, jiù gěi wǒ huí gè diànhuà ba.","vi":"Hôm qua tôi đã gửi email cho bạn, nếu bạn nhận được thì gọi lại cho tôi nhé."}],"related":[{"hanzi":"发烧","pinyin":"fāshāo","vi":"Sốt"},{"hanzi":"发现","pinyin":"fāxiàn","vi":"Phát hiện"},{"hanzi":"发生","pinyin":"fāshēng","vi":"Xảy ra"},{"hanzi":"出发","pinyin":"chūfā","vi":"Xuất phát"},{"hanzi":"头发","pinyin":"tóufa","vi":"Tóc"}],"traditional":"發"},{"id":"方法","hanzi":"方法","pinyin":"fāngfǎ","meaning_vi":"phương pháp, cách","explanation":"方 (cách thức) + 法 (phép) → phương pháp. Gần nghĩa 办法 (cách giải quyết một việc), còn 方法 thiên về cách làm có hệ thống: 学习方法.","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🔑","examples":[{"type":"basic","zh":"这个方法很好。","pinyin":"Zhège fāngfǎ hěn hǎo.","vi":"Cách này rất hay."},{"type":"simple","zh":"老师教了我们一个记汉字的好方法。","pinyin":"Lǎoshī jiāole wǒmen yí gè jì Hànzì de hǎo fāngfǎ.","vi":"Thầy giáo đã dạy chúng tôi một phương pháp hay để nhớ chữ Hán."},{"type":"compound","zh":"如果你找到了适合自己的学习方法，就会觉得学汉语不那么难了。","pinyin":"Rúguǒ nǐ zhǎodàole shìhé zìjǐ de xuéxí fāngfǎ, jiù huì juéde xué Hànyǔ bú nàme nán le.","vi":"Nếu bạn tìm được phương pháp học phù hợp với bản thân thì sẽ thấy học tiếng Trung không khó đến thế nữa."}],"related":[{"hanzi":"办法","pinyin":"bànfǎ","vi":"Cách, biện pháp"},{"hanzi":"方式","pinyin":"fāngshì","vi":"Phương thức"},{"hanzi":"方面","pinyin":"fāngmiàn","vi":"Phương diện"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"Pháp luật"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"}]},{"id":"访问","hanzi":"访问","pinyin":"fǎngwèn","meaning_vi":"thăm, viếng thăm; phỏng vấn","explanation":"Dùng cho chuyến thăm mang tính chính thức (访问中国) hoặc phỏng vấn ai đó; thăm bạn bè, người thân thường dùng 看望. Còn có nghĩa truy cập (访问网站).","hsk_level":3,"tags":["dong-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"记者访问了那位老人。","pinyin":"Jìzhě fǎngwènle nà wèi lǎorén.","vi":"Phóng viên đã phỏng vấn cụ già đó."},{"type":"simple","zh":"下个星期，我们学校的校长要去中国访问三天。","pinyin":"Xià gè xīngqī, wǒmen xuéxiào de xiàozhǎng yào qù Zhōngguó fǎngwèn sān tiān.","vi":"Tuần sau, hiệu trưởng trường chúng tôi sẽ có chuyến thăm Trung Quốc ba ngày."},{"type":"compound","zh":"因为这次访问很成功，所以两个学校决定以后经常交流。","pinyin":"Yīnwèi zhè cì fǎngwèn hěn chénggōng, suǒyǐ liǎng gè xuéxiào juédìng yǐhòu jīngcháng jiāoliú.","vi":"Vì chuyến thăm lần này rất thành công nên hai trường quyết định sau này sẽ thường xuyên giao lưu."}],"related":[{"hanzi":"采访","pinyin":"cǎifǎng","vi":"Phỏng vấn (báo chí)"},{"hanzi":"拜访","pinyin":"bàifǎng","vi":"Đến thăm"},{"hanzi":"参观","pinyin":"cānguān","vi":"Tham quan"},{"hanzi":"问","pinyin":"wèn","vi":"Hỏi"},{"hanzi":"记者","pinyin":"jìzhě","vi":"Phóng viên"}],"traditional":"訪問"},{"id":"百分之","hanzi":"百分之","pinyin":"bǎifēnzhī","meaning_vi":"phần trăm","explanation":"百分之 + số = phần trăm: 百分之五十 (50%). Số đứng sau, ngược với tiếng Việt. Tương tự: 三分之一 (một phần ba).","hsk_level":3,"tags":["so-dem","so-luong"],"image":"💯","examples":[{"type":"basic","zh":"我们班百分之六十是女同学。","pinyin":"Wǒmen bān bǎifēnzhī liùshí shì nǚ tóngxué.","vi":"Lớp chúng tôi có 60% là bạn nữ."},{"type":"simple","zh":"这次考试，百分之九十的同学都通过了。","pinyin":"Zhè cì kǎoshì, bǎifēnzhī jiǔshí de tóngxué dōu tōngguò le.","vi":"Kỳ thi lần này, 90% học sinh đều đã thi đậu."},{"type":"compound","zh":"虽然我只有百分之五十的把握，但是我还是想试一试。","pinyin":"Suīrán wǒ zhǐ yǒu bǎifēnzhī wǔshí de bǎwò, dànshì wǒ háishi xiǎng shì yi shì.","vi":"Tuy tôi chỉ nắm chắc 50% nhưng tôi vẫn muốn thử xem."}],"related":[{"hanzi":"百","pinyin":"bǎi","vi":"Trăm"},{"hanzi":"分数","pinyin":"fēnshù","vi":"Điểm số, phân số"},{"hanzi":"打折","pinyin":"dǎzhé","vi":"Giảm giá"},{"hanzi":"一半","pinyin":"yíbàn","vi":"Một nửa"},{"hanzi":"数字","pinyin":"shùzì","vi":"Con số"}]},{"id":"份","hanzi":"份","pinyin":"fèn","meaning_vi":"phần, suất; bản, tờ (lượng từ cho đồ ăn, báo, tài liệu, công việc)","explanation":"Lượng từ cho phần ăn (一份饭), quà (一份礼物), báo, tài liệu (一份报纸) và công việc (一份工作). Còn gặp trong 身份 (thân phận), 月份 (tháng).","hsk_level":3,"tags":["luong-tu"],"image":"📄","examples":[{"type":"basic","zh":"我要一份炒饭。","pinyin":"Wǒ yào yí fèn chǎofàn.","vi":"Tôi muốn một suất cơm rang."},{"type":"simple","zh":"他大学毕业以后，找到了一份很好的工作。","pinyin":"Tā dàxué bìyè yǐhòu, zhǎodàole yí fèn hěn hǎo de gōngzuò.","vi":"Sau khi tốt nghiệp đại học, anh ấy đã tìm được một công việc rất tốt."},{"type":"compound","zh":"请你把这份材料复印三份，然后送到王经理的办公室。","pinyin":"Qǐng nǐ bǎ zhè fèn cáiliào fùyìn sān fèn, ránhòu sòngdào Wáng jīnglǐ de bàngōngshì.","vi":"Bạn hãy photo tài liệu này thành ba bản, sau đó mang đến văn phòng giám đốc Vương."}],"related":[{"hanzi":"部分","pinyin":"bùfen","vi":"Phần, bộ phận"},{"hanzi":"身份","pinyin":"shēnfèn","vi":"Thân phận"},{"hanzi":"月份","pinyin":"yuèfèn","vi":"Tháng"},{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"Báo"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"}]},{"id":"复印","hanzi":"复印","pinyin":"fùyìn","meaning_vi":"photo, sao chụp (tài liệu)","explanation":"复 (lặp lại) + 印 (in) → in ra bản sao. Máy photo là 复印机; khác 打印 (in từ máy tính).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"🖨️","examples":[{"type":"basic","zh":"请帮我复印一下。","pinyin":"Qǐng bāng wǒ fùyìn yíxià.","vi":"Làm ơn photo giúp tôi một chút."},{"type":"simple","zh":"办签证的时候，你要带上护照和护照的复印件。","pinyin":"Bàn qiānzhèng de shíhou, nǐ yào dàishang hùzhào hé hùzhào de fùyìnjiàn.","vi":"Khi làm thị thực, bạn phải mang theo hộ chiếu và bản photo hộ chiếu."},{"type":"compound","zh":"因为办公室的复印机坏了，所以我只好去外面的商店复印。","pinyin":"Yīnwèi bàngōngshì de fùyìnjī huài le, suǒyǐ wǒ zhǐhǎo qù wàimiàn de shāngdiàn fùyìn.","vi":"Vì máy photo ở văn phòng bị hỏng nên tôi đành phải ra cửa hàng bên ngoài để photo."}],"related":[{"hanzi":"打印","pinyin":"dǎyìn","vi":"In"},{"hanzi":"复印机","pinyin":"fùyìnjī","vi":"Máy photo"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"Ấn tượng"},{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"},{"hanzi":"材料","pinyin":"cáiliào","vi":"Tài liệu"}],"traditional":"複印"},{"id":"感觉","hanzi":"感觉","pinyin":"gǎnjué","meaning_vi":"cảm giác; cảm thấy","explanation":"Vừa là danh từ (cảm giác) vừa là động từ (cảm thấy, gần nghĩa 觉得). 觉 ở đây đọc jué, khác jiào trong 睡觉.","hsk_level":3,"tags":["danh-tu","cam-xuc"],"image":"🤔","examples":[{"type":"basic","zh":"我感觉很舒服。","pinyin":"Wǒ gǎnjué hěn shūfu.","vi":"Tôi cảm thấy rất dễ chịu."},{"type":"simple","zh":"第一次在国外过春节，那种感觉很特别。","pinyin":"Dìyī cì zài guówài guò Chūnjié, nà zhǒng gǎnjué hěn tèbié.","vi":"Lần đầu tiên đón Tết ở nước ngoài, cảm giác đó rất đặc biệt."},{"type":"compound","zh":"虽然我们才认识一天，但是我感觉他是一个很热情的人。","pinyin":"Suīrán wǒmen cái rènshi yì tiān, dànshì wǒ gǎnjué tā shì yí gè hěn rèqíng de rén.","vi":"Tuy chúng tôi mới quen nhau một ngày nhưng tôi cảm thấy anh ấy là một người rất nhiệt tình."}],"related":[{"hanzi":"觉得","pinyin":"juéde","vi":"Cảm thấy"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"Tình cảm"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"Cảm động"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Đi ngủ"},{"hanzi":"感冒","pinyin":"gǎnmào","vi":"Cảm cúm"}],"traditional":"感覺"},{"id":"感情","hanzi":"感情","pinyin":"gǎnqíng","meaning_vi":"tình cảm","explanation":"感 (cảm) + 情 (tình) → tình cảm giữa người với người hoặc với nơi chốn: 感情很好, 对…有感情.","hsk_level":3,"tags":["danh-tu","cam-xuc"],"image":"💞","examples":[{"type":"basic","zh":"他们俩的感情很好。","pinyin":"Tāmen liǎ de gǎnqíng hěn hǎo.","vi":"Tình cảm của hai người họ rất tốt."},{"type":"simple","zh":"我在这个城市住了十年，对这里有很深的感情。","pinyin":"Wǒ zài zhège chéngshì zhùle shí nián, duì zhèlǐ yǒu hěn shēn de gǎnqíng.","vi":"Tôi đã sống ở thành phố này mười năm, có tình cảm rất sâu đậm với nơi đây."},{"type":"compound","zh":"虽然我们不常见面，但是我们之间的感情一直没有变。","pinyin":"Suīrán wǒmen bù cháng jiànmiàn, dànshì wǒmen zhījiān de gǎnqíng yìzhí méiyǒu biàn.","vi":"Tuy chúng tôi không thường gặp nhau nhưng tình cảm giữa chúng tôi vẫn luôn không thay đổi."}],"related":[{"hanzi":"感觉","pinyin":"gǎnjué","vi":"Cảm giác"},{"hanzi":"爱情","pinyin":"àiqíng","vi":"Tình yêu"},{"hanzi":"友谊","pinyin":"yǒuyì","vi":"Tình bạn"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"Tâm trạng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}]},{"id":"干","hanzi":"干","pinyin":"gàn","meaning_vi":"làm","explanation":"Đọc gàn nghĩa là làm (khẩu ngữ, gần 做): 你在干什么? Đọc gān nghĩa là khô: 干净 (sạch sẽ), 干燥 (khô hanh).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"你在干什么？","pinyin":"Nǐ zài gàn shénme?","vi":"Bạn đang làm gì thế?"},{"type":"simple","zh":"你大学毕业以后想干什么工作？","pinyin":"Nǐ dàxué bìyè yǐhòu xiǎng gàn shénme gōngzuò?","vi":"Sau khi tốt nghiệp đại học, bạn muốn làm công việc gì?"},{"type":"compound","zh":"这件事你一个人干不完，所以我们大家一起帮你吧。","pinyin":"Zhè jiàn shì nǐ yí gè rén gàn bu wán, suǒyǐ wǒmen dàjiā yìqǐ bāng nǐ ba.","vi":"Việc này một mình bạn làm không xong, nên mọi người chúng tôi cùng giúp bạn nhé."}],"related":[{"hanzi":"做","pinyin":"zuò","vi":"Làm"},{"hanzi":"干活","pinyin":"gànhuó","vi":"Làm việc (chân tay)"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"干杯","pinyin":"gānbēi","vi":"Cạn ly"},{"hanzi":"干燥","pinyin":"gānzào","vi":"Khô hanh"}],"traditional":"幹"},{"id":"刚刚","hanzi":"刚刚","pinyin":"gānggāng","meaning_vi":"vừa mới","explanation":"Dạng lặp của 刚, chỉ việc vừa mới xảy ra, thường đứng ngay trước động từ: 我刚刚到. Gần nghĩa với 刚才 (vừa nãy).","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"我刚刚到家。","pinyin":"Wǒ gānggāng dào jiā.","vi":"Tôi vừa mới về đến nhà."},{"type":"simple","zh":"电影刚刚开始，你快进来坐吧。","pinyin":"Diànyǐng gānggāng kāishǐ, nǐ kuài jìnlái zuò ba.","vi":"Phim vừa mới bắt đầu, bạn mau vào ngồi đi."},{"type":"compound","zh":"我刚刚走出家门，天就下起了大雨，所以我只好回去拿伞。","pinyin":"Wǒ gānggāng zǒuchū jiāmén, tiān jiù xiàqǐle dàyǔ, suǒyǐ wǒ zhǐhǎo huíqù ná sǎn.","vi":"Tôi vừa mới bước ra khỏi nhà thì trời đổ mưa to, nên tôi đành phải quay về lấy ô."}],"related":[{"hanzi":"刚才","pinyin":"gāngcái","vi":"Vừa nãy"},{"hanzi":"刚","pinyin":"gāng","vi":"Vừa"},{"hanzi":"已经","pinyin":"yǐjīng","vi":"Đã"},{"hanzi":"马上","pinyin":"mǎshàng","vi":"Ngay lập tức"},{"hanzi":"正好","pinyin":"zhènghǎo","vi":"Vừa đúng lúc"}],"traditional":"剛剛"},{"id":"个子","hanzi":"个子","pinyin":"gèzi","meaning_vi":"vóc người, chiều cao","explanation":"Chỉ chiều cao, vóc dáng của người, thường đi với 高/矮: 个子很高 (người cao). 子 ở đây đọc nhẹ.","hsk_level":3,"tags":["danh-tu","co-the"],"image":"📏","examples":[{"type":"basic","zh":"他个子很高。","pinyin":"Tā gèzi hěn gāo.","vi":"Anh ấy vóc người rất cao."},{"type":"simple","zh":"我弟弟今年十二岁，个子已经比爸爸还高了。","pinyin":"Wǒ dìdi jīnnián shí'èr suì, gèzi yǐjīng bǐ bàba hái gāo le.","vi":"Em trai tôi năm nay mười hai tuổi mà đã cao hơn cả bố rồi."},{"type":"compound","zh":"虽然小王个子不高，但是他篮球打得比我们班所有人都好。","pinyin":"Suīrán Xiǎo Wáng gèzi bù gāo, dànshì tā lánqiú dǎ de bǐ wǒmen bān suǒyǒu rén dōu hǎo.","vi":"Tuy Tiểu Vương không cao nhưng cậu ấy chơi bóng rổ giỏi hơn tất cả mọi người trong lớp chúng tôi."}],"related":[{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"矮","pinyin":"ǎi","vi":"Thấp"},{"hanzi":"身材","pinyin":"shēncái","vi":"Vóc dáng"},{"hanzi":"身高","pinyin":"shēngāo","vi":"Chiều cao"},{"hanzi":"胖","pinyin":"pàng","vi":"Béo"}],"traditional":"個子"},{"id":"广告","hanzi":"广告","pinyin":"guǎnggào","meaning_vi":"quảng cáo","explanation":"广 (rộng) + 告 (báo cho biết) → báo cho nhiều người biết. Hay gặp: 做广告 (làm quảng cáo), 电视广告.","hsk_level":3,"tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"这个广告很有意思。","pinyin":"Zhège guǎnggào hěn yǒu yìsi.","vi":"Quảng cáo này rất thú vị."},{"type":"simple","zh":"现在看电视的时候，广告比节目还多。","pinyin":"Xiànzài kàn diànshì de shíhou, guǎnggào bǐ jiémù hái duō.","vi":"Bây giờ khi xem ti vi, quảng cáo còn nhiều hơn cả chương trình."},{"type":"compound","zh":"因为这家饭馆在网上做了很多广告，所以来吃饭的人越来越多。","pinyin":"Yīnwèi zhè jiā fànguǎn zài wǎngshang zuòle hěn duō guǎnggào, suǒyǐ lái chīfàn de rén yuè lái yuè duō.","vi":"Vì quán ăn này đã quảng cáo rất nhiều trên mạng nên người đến ăn ngày càng đông."}],"related":[{"hanzi":"广播","pinyin":"guǎngbō","vi":"Phát thanh"},{"hanzi":"告诉","pinyin":"gàosu","vi":"Nói cho biết"},{"hanzi":"报告","pinyin":"bàogào","vi":"Báo cáo"},{"hanzi":"电视","pinyin":"diànshì","vi":"Ti vi"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"Tin tức"}],"traditional":"廣告"},{"id":"海洋","hanzi":"海洋","pinyin":"hǎiyáng","meaning_vi":"biển cả, đại dương","explanation":"海 (biển) + 洋 (đại dương) → biển cả nói chung. 海 thường là vùng biển gần đất liền, 洋 là đại dương rộng lớn như 太平洋.","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"我喜欢蓝色的海洋。","pinyin":"Wǒ xǐhuan lánsè de hǎiyáng.","vi":"Tôi thích đại dương màu xanh."},{"type":"simple","zh":"地球上的海洋比陆地大得多。","pinyin":"Dìqiú shang de hǎiyáng bǐ lùdì dà de duō.","vi":"Đại dương trên Trái Đất lớn hơn đất liền nhiều."},{"type":"compound","zh":"如果大家都往海里扔塑料袋，海洋就会被污染得越来越严重。","pinyin":"Rúguǒ dàjiā dōu wǎng hǎi li rēng sùliàodài, hǎiyáng jiù huì bèi wūrǎn de yuè lái yuè yánzhòng.","vi":"Nếu ai cũng vứt túi ni-lông xuống biển thì đại dương sẽ bị ô nhiễm ngày càng nghiêm trọng."}],"related":[{"hanzi":"海","pinyin":"hǎi","vi":"Biển"},{"hanzi":"太平洋","pinyin":"Tàipíngyáng","vi":"Thái Bình Dương"},{"hanzi":"海边","pinyin":"hǎibiān","vi":"Bờ biển"},{"hanzi":"陆地","pinyin":"lùdì","vi":"Đất liền"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"Hải sản"}]},{"id":"汗","hanzi":"汗","pinyin":"hàn","meaning_vi":"mồ hôi","explanation":"Bộ 氵 (nước) + 干 (gợi âm) → nước tiết ra từ da. Hay dùng: 出汗 (ra mồ hôi), 一身汗 (ướt đẫm mồ hôi).","hsk_level":3,"tags":["danh-tu","co-the"],"image":"💦","examples":[{"type":"basic","zh":"我出了很多汗。","pinyin":"Wǒ chūle hěn duō hàn.","vi":"Tôi ra rất nhiều mồ hôi."},{"type":"simple","zh":"今天天气太热了，我只走了十分钟就出了一身汗。","pinyin":"Jīntiān tiānqì tài rè le, wǒ zhǐ zǒule shí fēnzhōng jiù chūle yì shēn hàn.","vi":"Hôm nay trời nóng quá, tôi mới đi bộ mười phút đã ướt đẫm mồ hôi."},{"type":"compound","zh":"每次跑完步，他都出很多汗，所以要马上洗澡、换衣服。","pinyin":"Měi cì pǎowán bù, tā dōu chū hěn duō hàn, suǒyǐ yào mǎshàng xǐzǎo, huàn yīfu.","vi":"Mỗi lần chạy bộ xong anh ấy đều ra rất nhiều mồ hôi, nên phải tắm và thay quần áo ngay."}],"related":[{"hanzi":"出汗","pinyin":"chūhàn","vi":"Ra mồ hôi"},{"hanzi":"汗水","pinyin":"hànshuǐ","vi":"Mồ hôi"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"Tắm"}]},{"id":"航班","hanzi":"航班","pinyin":"hángbān","meaning_vi":"chuyến bay","explanation":"航 (đi biển, bay) + 班 (chuyến theo lịch) → chuyến bay theo lịch cố định. Hay gặp: 航班号 (số hiệu chuyến bay), 航班取消 (chuyến bay bị hủy).","hsk_level":3,"tags":["danh-tu","giao-thong","du-lich"],"image":"✈️","examples":[{"type":"basic","zh":"我的航班晚点了。","pinyin":"Wǒ de hángbān wǎndiǎn le.","vi":"Chuyến bay của tôi bị trễ."},{"type":"simple","zh":"去上海的航班每天早上八点从这个机场起飞。","pinyin":"Qù Shànghǎi de hángbān měitiān zǎoshang bā diǎn cóng zhège jīchǎng qǐfēi.","vi":"Chuyến bay đi Thượng Hải cất cánh từ sân bay này lúc tám giờ sáng hằng ngày."},{"type":"compound","zh":"因为今天的天气很不好，所以很多航班都被取消了。","pinyin":"Yīnwèi jīntiān de tiānqì hěn bù hǎo, suǒyǐ hěn duō hángbān dōu bèi qǔxiāo le.","vi":"Vì thời tiết hôm nay rất xấu nên nhiều chuyến bay đều bị hủy."}],"related":[{"hanzi":"飞机","pinyin":"fēijī","vi":"Máy bay"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"起飞","pinyin":"qǐfēi","vi":"Cất cánh"},{"hanzi":"登机","pinyin":"dēngjī","vi":"Lên máy bay"},{"hanzi":"机票","pinyin":"jīpiào","vi":"Vé máy bay"}]},{"id":"好处","hanzi":"好处","pinyin":"hǎochu","meaning_vi":"lợi ích, cái lợi","explanation":"好 (tốt) + 处 (chỗ) → chỗ tốt, cái lợi; trái nghĩa 坏处 (tác hại). Cấu trúc: 对…有好处 (có lợi cho…).","hsk_level":3,"tags":["danh-tu"],"image":"👍","examples":[{"type":"basic","zh":"运动对身体有好处。","pinyin":"Yùndòng duì shēntǐ yǒu hǎochu.","vi":"Vận động có lợi cho sức khỏe."},{"type":"simple","zh":"每天早上读半个小时书，对学习有很多好处。","pinyin":"Měitiān zǎoshang dú bàn gè xiǎoshí shū, duì xuéxí yǒu hěn duō hǎochu.","vi":"Mỗi sáng đọc sách nửa tiếng có rất nhiều lợi ích cho việc học."},{"type":"compound","zh":"虽然住在城市里有很多好处，但是我还是更喜欢安静的农村生活。","pinyin":"Suīrán zhù zài chéngshì li yǒu hěn duō hǎochu, dànshì wǒ háishi gèng xǐhuan ānjìng de nóngcūn shēnghuó.","vi":"Tuy sống ở thành phố có nhiều lợi ích nhưng tôi vẫn thích cuộc sống yên tĩnh ở nông thôn hơn."}],"related":[{"hanzi":"坏处","pinyin":"huàichu","vi":"Tác hại"},{"hanzi":"优点","pinyin":"yōudiǎn","vi":"Ưu điểm"},{"hanzi":"用处","pinyin":"yòngchu","vi":"Công dụng"},{"hanzi":"到处","pinyin":"dàochù","vi":"Khắp nơi"},{"hanzi":"好","pinyin":"hǎo","vi":"Tốt"}],"traditional":"好處"},{"id":"好像","hanzi":"好像","pinyin":"hǎoxiàng","meaning_vi":"hình như, dường như; giống như","explanation":"Dùng khi đoán chừng, không chắc chắn: 他好像病了. Cũng dùng để so sánh như 像: 好像…一样 (giống như…).","hsk_level":3,"tags":["pho-tu","nhan-thuc"],"image":"🤨","examples":[{"type":"basic","zh":"外面好像下雨了。","pinyin":"Wàimiàn hǎoxiàng xiàyǔ le.","vi":"Bên ngoài hình như mưa rồi."},{"type":"simple","zh":"我好像在哪里见过他，可是想不起来他的名字了。","pinyin":"Wǒ hǎoxiàng zài nǎlǐ jiànguo tā, kěshì xiǎng bu qǐlái tā de míngzi le.","vi":"Hình như tôi đã gặp anh ấy ở đâu đó, nhưng không nhớ ra tên anh ấy nữa."},{"type":"compound","zh":"他们俩一见面就聊个不停，好像认识了很多年的老朋友一样。","pinyin":"Tāmen liǎ yí jiànmiàn jiù liáo gè bù tíng, hǎoxiàng rènshile hěn duō nián de lǎo péngyou yíyàng.","vi":"Hai người họ vừa gặp nhau đã trò chuyện không ngớt, giống như những người bạn cũ đã quen nhau nhiều năm."}],"related":[{"hanzi":"像","pinyin":"xiàng","vi":"Giống"},{"hanzi":"似乎","pinyin":"sìhū","vi":"Dường như"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có thể"},{"hanzi":"也许","pinyin":"yěxǔ","vi":"Có lẽ"},{"hanzi":"一样","pinyin":"yíyàng","vi":"Giống nhau"}]},{"id":"号码","hanzi":"号码","pinyin":"hàomǎ","meaning_vi":"số, mã số","explanation":"号 (số thứ tự) + 码 (mã, chữ số). Hay gặp: 电话号码 (số điện thoại), 房间号码 (số phòng).","hsk_level":3,"tags":["danh-tu","giao-tiep"],"image":"🔢","examples":[{"type":"basic","zh":"你的电话号码是多少？","pinyin":"Nǐ de diànhuà hàomǎ shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?"},{"type":"simple","zh":"我换了新手机号码，以后你打这个号码找我吧。","pinyin":"Wǒ huànle xīn shǒujī hàomǎ, yǐhòu nǐ dǎ zhège hàomǎ zhǎo wǒ ba.","vi":"Tôi đã đổi số điện thoại di động mới, sau này bạn gọi số này để tìm tôi nhé."},{"type":"compound","zh":"如果你忘了他的房间号码，就去前台问一下服务员。","pinyin":"Rúguǒ nǐ wàngle tā de fángjiān hàomǎ, jiù qù qiántái wèn yíxià fúwùyuán.","vi":"Nếu bạn quên số phòng của anh ấy thì hãy ra quầy lễ tân hỏi nhân viên phục vụ."}],"related":[{"hanzi":"号","pinyin":"hào","vi":"Số"},{"hanzi":"电话","pinyin":"diànhuà","vi":"Điện thoại"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"Mật khẩu"},{"hanzi":"数字","pinyin":"shùzì","vi":"Con số"},{"hanzi":"手机","pinyin":"shǒujī","vi":"Điện thoại di động"}],"traditional":"號碼"},{"id":"盒子","hanzi":"盒子","pinyin":"hézi","meaning_vi":"cái hộp","explanation":"盒 gồm 合 (đóng lại, cũng gợi âm hé) + 皿 (đồ đựng) → đồ đựng có nắp. 子 là hậu tố danh từ, đọc nhẹ.","hsk_level":3,"tags":["danh-tu","do-vat"],"image":"📦","examples":[{"type":"basic","zh":"盒子里有什么？","pinyin":"Hézi li yǒu shénme?","vi":"Trong hộp có gì?"},{"type":"simple","zh":"我把妈妈送我的生日礼物放在一个小盒子里了。","pinyin":"Wǒ bǎ māma sòng wǒ de shēngrì lǐwù fàng zài yí gè xiǎo hézi li le.","vi":"Tôi đã cất món quà sinh nhật mẹ tặng vào một chiếc hộp nhỏ."},{"type":"compound","zh":"这个盒子虽然很好看，但是太小了，放不下这么多东西。","pinyin":"Zhège hézi suīrán hěn hǎokàn, dànshì tài xiǎo le, fàng bu xià zhème duō dōngxi.","vi":"Cái hộp này tuy rất đẹp nhưng nhỏ quá, không để vừa nhiều đồ như vậy."}],"related":[{"hanzi":"盒","pinyin":"hé","vi":"Hộp"},{"hanzi":"饭盒","pinyin":"fànhé","vi":"Hộp cơm"},{"hanzi":"箱子","pinyin":"xiāngzi","vi":"Cái rương, va li"},{"hanzi":"袋子","pinyin":"dàizi","vi":"Cái túi"},{"hanzi":"礼物","pinyin":"lǐwù","vi":"Quà"}]},{"id":"后来","hanzi":"后来","pinyin":"hòulái","meaning_vi":"sau đó, về sau","explanation":"Danh từ thời gian, chỉ khoảng thời gian sau một việc trong quá khứ. Khác 以后: 以后 dùng được cho tương lai, 后来 chỉ dùng cho quá khứ.","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"⏭️","examples":[{"type":"basic","zh":"后来他去了北京。","pinyin":"Hòulái tā qùle Běijīng.","vi":"Sau đó anh ấy đã đi Bắc Kinh."},{"type":"simple","zh":"我们以前是同学，后来他搬家了，就很少见面了。","pinyin":"Wǒmen yǐqián shì tóngxué, hòulái tā bānjiā le, jiù hěn shǎo jiànmiàn le.","vi":"Trước đây chúng tôi là bạn học, sau đó cậu ấy chuyển nhà nên rất ít gặp nhau."},{"type":"compound","zh":"刚开始我不喜欢吃辣的，后来在四川住了两年，就慢慢习惯了。","pinyin":"Gāng kāishǐ wǒ bù xǐhuan chī là de, hòulái zài Sìchuān zhùle liǎng nián, jiù mànmàn xíguàn le.","vi":"Lúc đầu tôi không thích ăn cay, về sau sống ở Tứ Xuyên hai năm thì dần dần quen."}],"related":[{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau này"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"最后","pinyin":"zuìhòu","vi":"Cuối cùng"},{"hanzi":"当时","pinyin":"dāngshí","vi":"Lúc đó"}],"traditional":"後來"},{"id":"厚","hanzi":"厚","pinyin":"hòu","meaning_vi":"dày","explanation":"Trái nghĩa là 薄 (mỏng). Hay gặp: 厚衣服 (áo dày), 这本书很厚 (quyển sách này rất dày).","hsk_level":3,"tags":["tinh-tu","do-vat"],"image":"📚","examples":[{"type":"basic","zh":"这本书很厚。","pinyin":"Zhè běn shū hěn hòu.","vi":"Quyển sách này rất dày."},{"type":"simple","zh":"冬天到了，妈妈给我买了一件很厚的衣服。","pinyin":"Dōngtiān dào le, māma gěi wǒ mǎile yí jiàn hěn hòu de yīfu.","vi":"Mùa đông đến rồi, mẹ đã mua cho tôi một chiếc áo rất dày."},{"type":"compound","zh":"外面下着大雪，如果你不穿厚一点的衣服，就会感冒的。","pinyin":"Wàimiàn xiàzhe dàxuě, rúguǒ nǐ bù chuān hòu yìdiǎn de yīfu, jiù huì gǎnmào de.","vi":"Bên ngoài tuyết đang rơi nhiều, nếu bạn không mặc áo dày hơn một chút thì sẽ bị cảm đấy."}],"related":[{"hanzi":"薄","pinyin":"báo","vi":"Mỏng"},{"hanzi":"厚度","pinyin":"hòudù","vi":"Độ dày"},{"hanzi":"被子","pinyin":"bèizi","vi":"Chăn"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"深厚","pinyin":"shēnhòu","vi":"Sâu đậm"}]},{"id":"互相","hanzi":"互相","pinyin":"hùxiāng","meaning_vi":"lẫn nhau","explanation":"Đứng trước động từ: 互相帮助 (giúp đỡ lẫn nhau). Khác tiếng Việt, 互相 đứng trước động từ chứ không đứng cuối câu.","hsk_level":3,"tags":["pho-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"我们要互相帮助。","pinyin":"Wǒmen yào hùxiāng bāngzhù.","vi":"Chúng ta phải giúp đỡ lẫn nhau."},{"type":"simple","zh":"我和同屋常常互相学习，他教我汉语，我教他越南语。","pinyin":"Wǒ hé tóngwū chángcháng hùxiāng xuéxí, tā jiāo wǒ Hànyǔ, wǒ jiāo tā Yuènányǔ.","vi":"Tôi và bạn cùng phòng thường học hỏi lẫn nhau, cậu ấy dạy tôi tiếng Trung, tôi dạy cậu ấy tiếng Việt."},{"type":"compound","zh":"如果夫妻之间能互相理解，生活中就会少很多问题。","pinyin":"Rúguǒ fūqī zhījiān néng hùxiāng lǐjiě, shēnghuó zhōng jiù huì shǎo hěn duō wèntí.","vi":"Nếu vợ chồng có thể thấu hiểu lẫn nhau thì trong cuộc sống sẽ bớt đi rất nhiều vấn đề."}],"related":[{"hanzi":"相互","pinyin":"xiānghù","vi":"Tương hỗ"},{"hanzi":"彼此","pinyin":"bǐcǐ","vi":"Lẫn nhau"},{"hanzi":"一起","pinyin":"yìqǐ","vi":"Cùng nhau"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"互联网","pinyin":"hùliánwǎng","vi":"Internet"}]},{"id":"活泼","hanzi":"活泼","pinyin":"huópō","meaning_vi":"hoạt bát, sôi nổi","explanation":"Tả tính cách nhanh nhẹn, vui vẻ, thường nói về trẻ em hoặc người trẻ: 活泼可爱. Trái nghĩa gần: 安静 (trầm lặng).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"😄","examples":[{"type":"basic","zh":"这个孩子很活泼。","pinyin":"Zhège háizi hěn huópō.","vi":"Đứa trẻ này rất hoạt bát."},{"type":"simple","zh":"我妹妹性格活泼，在学校里有很多好朋友。","pinyin":"Wǒ mèimei xìnggé huópō, zài xuéxiào li yǒu hěn duō hǎo péngyou.","vi":"Em gái tôi tính cách hoạt bát, ở trường có rất nhiều bạn thân."},{"type":"compound","zh":"他小时候很活泼，可是上了大学以后，就变得越来越安静了。","pinyin":"Tā xiǎo shíhou hěn huópō, kěshì shàngle dàxué yǐhòu, jiù biàn de yuè lái yuè ānjìng le.","vi":"Hồi nhỏ cậu ấy rất hoạt bát, nhưng sau khi vào đại học thì ngày càng trầm lặng."}],"related":[{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"Đáng yêu"},{"hanzi":"性格","pinyin":"xìnggé","vi":"Tính cách"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"活潑"},{"id":"火","hanzi":"火","pinyin":"huǒ","meaning_vi":"lửa","explanation":"Chữ tượng hình ngọn lửa. Làm bộ thủ thường viết 火 bên trái (灯, 炒) hoặc 灬 bên dưới (热, 照).","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🔥","examples":[{"type":"basic","zh":"小心，那里有火！","pinyin":"Xiǎoxīn, nàlǐ yǒu huǒ!","vi":"Cẩn thận, chỗ kia có lửa!"},{"type":"simple","zh":"做饭的时候，火不要开得太大。","pinyin":"Zuò fàn de shíhou, huǒ bú yào kāi de tài dà.","vi":"Khi nấu ăn, đừng để lửa to quá."},{"type":"compound","zh":"如果离开家的时候忘了关火，就可能会发生危险。","pinyin":"Rúguǒ líkāi jiā de shíhou wàngle guān huǒ, jiù kěnéng huì fāshēng wēixiǎn.","vi":"Nếu lúc ra khỏi nhà quên tắt lửa thì có thể sẽ xảy ra nguy hiểm."}],"related":[{"hanzi":"火车","pinyin":"huǒchē","vi":"Tàu hỏa"},{"hanzi":"火柴","pinyin":"huǒchái","vi":"Que diêm"},{"hanzi":"着火","pinyin":"zháohuǒ","vi":"Cháy"},{"hanzi":"灯","pinyin":"dēng","vi":"Đèn"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"}]},{"id":"积极","hanzi":"积极","pinyin":"jījí","meaning_vi":"tích cực, hăng hái","explanation":"积 (tích) + 极 (cực) → tích cực; trái nghĩa 消极 (tiêu cực). Hay dùng: 积极参加 (hăng hái tham gia), 积极的态度 (thái độ tích cực).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🙋","examples":[{"type":"basic","zh":"他工作很积极。","pinyin":"Tā gōngzuò hěn jījí.","vi":"Anh ấy làm việc rất tích cực."},{"type":"simple","zh":"小明上课的时候总是积极回答老师的问题。","pinyin":"Xiǎo Míng shàngkè de shíhou zǒngshì jījí huídá lǎoshī de wèntí.","vi":"Trong giờ học, Tiểu Minh luôn hăng hái trả lời câu hỏi của thầy giáo."},{"type":"compound","zh":"虽然遇到了很多困难，但是他一直用积极的态度面对生活。","pinyin":"Suīrán yùdàole hěn duō kùnnan, dànshì tā yìzhí yòng jījí de tàidu miànduì shēnghuó.","vi":"Tuy gặp rất nhiều khó khăn nhưng anh ấy vẫn luôn đối mặt với cuộc sống bằng thái độ tích cực."}],"related":[{"hanzi":"消极","pinyin":"xiāojí","vi":"Tiêu cực"},{"hanzi":"积极性","pinyin":"jījíxìng","vi":"Tính tích cực"},{"hanzi":"主动","pinyin":"zhǔdòng","vi":"Chủ động"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Cố gắng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"積極"},{"id":"基础","hanzi":"基础","pinyin":"jīchǔ","meaning_vi":"nền tảng, cơ sở","explanation":"基 (nền) + 础 (đá kê chân cột) → nền móng. Hay gặp: 打基础 (xây nền tảng), 基础很好 (nền tảng vững).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🧱","examples":[{"type":"basic","zh":"他的汉语基础很好。","pinyin":"Tā de Hànyǔ jīchǔ hěn hǎo.","vi":"Nền tảng tiếng Trung của anh ấy rất tốt."},{"type":"simple","zh":"学外语的时候，第一年最重要的是打好基础。","pinyin":"Xué wàiyǔ de shíhou, dìyī nián zuì zhòngyào de shì dǎhǎo jīchǔ.","vi":"Khi học ngoại ngữ, năm đầu tiên quan trọng nhất là xây nền tảng cho vững."},{"type":"compound","zh":"因为他的数学基础不好，所以上大学以后学得很辛苦。","pinyin":"Yīnwèi tā de shùxué jīchǔ bù hǎo, suǒyǐ shàng dàxué yǐhòu xué de hěn xīnkǔ.","vi":"Vì nền tảng toán của cậu ấy không tốt nên sau khi vào đại học học rất vất vả."}],"related":[{"hanzi":"基本","pinyin":"jīběn","vi":"Cơ bản"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"Trình độ"},{"hanzi":"知识","pinyin":"zhīshi","vi":"Kiến thức"},{"hanzi":"条件","pinyin":"tiáojiàn","vi":"Điều kiện"},{"hanzi":"基金","pinyin":"jījīn","vi":"Quỹ"}],"traditional":"基礎"},{"id":"激动","hanzi":"激动","pinyin":"jīdòng","meaning_vi":"xúc động, phấn khích","explanation":"激 (khích, dâng lên) + 动 (động) → cảm xúc dâng trào, có thể do vui mừng hay tức giận. Khác 感动 (cảm động trước việc tốt của người khác).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"🤩","examples":[{"type":"basic","zh":"他激动得哭了。","pinyin":"Tā jīdòng de kū le.","vi":"Anh ấy xúc động đến bật khóc."},{"type":"simple","zh":"听到自己考上大学的消息，她激动得一晚上没睡着。","pinyin":"Tīngdào zìjǐ kǎoshàng dàxué de xiāoxi, tā jīdòng de yì wǎnshang méi shuìzháo.","vi":"Nghe tin mình đỗ đại học, cô ấy phấn khích đến mức cả đêm không ngủ được."},{"type":"compound","zh":"当他在机场看到十年没见的父母时，激动得一句话也说不出。","pinyin":"Dāng tā zài jīchǎng kàndào shí nián méi jiàn de fùmǔ shí, jīdòng de yí jù huà yě shuō bu chū.","vi":"Khi nhìn thấy bố mẹ mười năm không gặp ở sân bay, anh ấy xúc động đến mức không nói được câu nào."}],"related":[{"hanzi":"感动","pinyin":"gǎndòng","vi":"Cảm động"},{"hanzi":"兴奋","pinyin":"xīngfèn","vi":"Phấn khởi"},{"hanzi":"激烈","pinyin":"jīliè","vi":"Kịch liệt"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"Bình tĩnh"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"Căng thẳng"}],"traditional":"激動"},{"id":"及时","hanzi":"及时","pinyin":"jíshí","meaning_vi":"kịp thời","explanation":"及 (kịp) + 时 (thời) → kịp thời. Khác 按时 (đúng giờ đã định): 及时 là đúng lúc cần, không chậm trễ.","hsk_level":3,"tags":["tinh-tu","thoi-gian"],"image":"🚑","examples":[{"type":"basic","zh":"你来得很及时。","pinyin":"Nǐ lái de hěn jíshí.","vi":"Bạn đến thật kịp thời."},{"type":"simple","zh":"学习上有问题的话，请及时告诉老师。","pinyin":"Xuéxí shang yǒu wèntí dehuà, qǐng jíshí gàosu lǎoshī.","vi":"Nếu có vấn đề trong học tập, hãy báo ngay cho thầy cô."},{"type":"compound","zh":"因为救护车来得很及时，所以那位老人没有危险了。","pinyin":"Yīnwèi jiùhùchē lái de hěn jíshí, suǒyǐ nà wèi lǎorén méiyǒu wēixiǎn le.","vi":"Vì xe cứu thương đến rất kịp thời nên cụ già đó đã qua cơn nguy hiểm."}],"related":[{"hanzi":"按时","pinyin":"ànshí","vi":"Đúng giờ"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"来得及","pinyin":"láidejí","vi":"Kịp"},{"hanzi":"马上","pinyin":"mǎshàng","vi":"Ngay lập tức"},{"hanzi":"立刻","pinyin":"lìkè","vi":"Lập tức"}],"traditional":"及時"},{"id":"即使","hanzi":"即使","pinyin":"jíshǐ","meaning_vi":"cho dù, dù cho","explanation":"Thường dùng 即使…也… (dù… cũng…): nêu một giả thiết rồi khẳng định kết quả không đổi. Khác 虽然 (nói về việc có thật).","hsk_level":3,"tags":["lien-tu"],"image":"☔","examples":[{"type":"basic","zh":"即使下雨，我也去。","pinyin":"Jíshǐ xiàyǔ, wǒ yě qù.","vi":"Dù trời mưa tôi cũng đi."},{"type":"simple","zh":"即使工作很忙，他每天也会给妈妈打电话。","pinyin":"Jíshǐ gōngzuò hěn máng, tā měitiān yě huì gěi māma dǎ diànhuà.","vi":"Cho dù công việc rất bận, ngày nào anh ấy cũng gọi điện cho mẹ."},{"type":"compound","zh":"即使这次考试没通过，你也不要放弃，下次再努力就行了。","pinyin":"Jíshǐ zhè cì kǎoshì méi tōngguò, nǐ yě bú yào fàngqì, xià cì zài nǔlì jiù xíng le.","vi":"Cho dù lần thi này không đậu, bạn cũng đừng bỏ cuộc, lần sau cố gắng thêm là được."}],"related":[{"hanzi":"虽然","pinyin":"suīrán","vi":"Tuy rằng"},{"hanzi":"尽管","pinyin":"jǐnguǎn","vi":"Mặc dù"},{"hanzi":"哪怕","pinyin":"nǎpà","vi":"Dù cho"},{"hanzi":"如果","pinyin":"rúguǒ","vi":"Nếu"},{"hanzi":"也","pinyin":"yě","vi":"Cũng"}]},{"id":"计划","hanzi":"计划","pinyin":"jìhuà","meaning_vi":"kế hoạch; lên kế hoạch, dự định","explanation":"Vừa là danh từ (kế hoạch) vừa là động từ (dự định): 我计划明年去中国. Hay gặp: 做计划, 按照计划.","hsk_level":3,"tags":["danh-tu","cong-viec"],"image":"📅","examples":[{"type":"basic","zh":"你有什么计划？","pinyin":"Nǐ yǒu shénme jìhuà?","vi":"Bạn có kế hoạch gì?"},{"type":"simple","zh":"我们计划今年夏天去云南旅游一个星期。","pinyin":"Wǒmen jìhuà jīnnián xiàtiān qù Yúnnán lǚyóu yí gè xīngqī.","vi":"Chúng tôi dự định mùa hè năm nay đi du lịch Vân Nam một tuần."},{"type":"compound","zh":"如果你每天按照计划学习，三个月以后就能通过考试。","pinyin":"Rúguǒ nǐ měitiān ànzhào jìhuà xuéxí, sān gè yuè yǐhòu jiù néng tōngguò kǎoshì.","vi":"Nếu mỗi ngày bạn học theo kế hoạch thì ba tháng sau sẽ có thể thi đậu."}],"related":[{"hanzi":"打算","pinyin":"dǎsuàn","vi":"Dự định"},{"hanzi":"安排","pinyin":"ānpái","vi":"Sắp xếp"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"Chuẩn bị"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"Mục tiêu"},{"hanzi":"计算","pinyin":"jìsuàn","vi":"Tính toán"}],"traditional":"計劃"},{"id":"记者","hanzi":"记者","pinyin":"jìzhě","meaning_vi":"phóng viên, nhà báo","explanation":"记 (ghi chép) + 者 (người) → người ghi chép, đưa tin. 者 là hậu tố chỉ người, như 作者 (tác giả).","hsk_level":3,"tags":["danh-tu","nghe-nghiep"],"image":"🎤","examples":[{"type":"basic","zh":"我哥哥是记者。","pinyin":"Wǒ gēge shì jìzhě.","vi":"Anh trai tôi là phóng viên."},{"type":"simple","zh":"很多记者在机场等着采访那位有名的演员。","pinyin":"Hěn duō jìzhě zài jīchǎng děngzhe cǎifǎng nà wèi yǒumíng de yǎnyuán.","vi":"Rất nhiều phóng viên đang chờ ở sân bay để phỏng vấn diễn viên nổi tiếng đó."},{"type":"compound","zh":"我从小就想当记者，因为我觉得这个工作能让我去很多地方。","pinyin":"Wǒ cóngxiǎo jiù xiǎng dāng jìzhě, yīnwèi wǒ juéde zhège gōngzuò néng ràng wǒ qù hěn duō dìfang.","vi":"Từ nhỏ tôi đã muốn làm phóng viên, vì tôi thấy công việc này có thể cho tôi đi nhiều nơi."}],"related":[{"hanzi":"新闻","pinyin":"xīnwén","vi":"Tin tức"},{"hanzi":"采访","pinyin":"cǎifǎng","vi":"Phỏng vấn"},{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"Báo"},{"hanzi":"作者","pinyin":"zuòzhě","vi":"Tác giả"},{"hanzi":"记录","pinyin":"jìlù","vi":"Ghi chép"}],"traditional":"記者"},{"id":"技术","hanzi":"技术","pinyin":"jìshù","meaning_vi":"kỹ thuật, công nghệ","explanation":"技 (kỹ năng) + 术 (thuật) → kỹ thuật. Dùng cho cả tay nghề của một người (他的技术很好) lẫn công nghệ (新技术).","hsk_level":3,"tags":["danh-tu","cong-nghe"],"image":"⚙️","examples":[{"type":"basic","zh":"他的开车技术很好。","pinyin":"Tā de kāichē jìshù hěn hǎo.","vi":"Kỹ thuật lái xe của anh ấy rất tốt."},{"type":"simple","zh":"这几年，手机技术发展得非常快。","pinyin":"Zhè jǐ nián, shǒujī jìshù fāzhǎn de fēicháng kuài.","vi":"Mấy năm nay, công nghệ điện thoại phát triển rất nhanh."},{"type":"compound","zh":"虽然这家公司不大，但是他们的技术在国内是最好的。","pinyin":"Suīrán zhè jiā gōngsī bú dà, dànshì tāmen de jìshù zài guónèi shì zuì hǎo de.","vi":"Tuy công ty này không lớn nhưng công nghệ của họ là tốt nhất trong nước."}],"related":[{"hanzi":"科学","pinyin":"kēxué","vi":"Khoa học"},{"hanzi":"科技","pinyin":"kējì","vi":"Khoa học công nghệ"},{"hanzi":"艺术","pinyin":"yìshù","vi":"Nghệ thuật"},{"hanzi":"技能","pinyin":"jìnéng","vi":"Kỹ năng"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"}],"traditional":"技術"},{"id":"既然","hanzi":"既然","pinyin":"jìrán","meaning_vi":"đã… thì, một khi đã","explanation":"Dùng 既然…就/也…: nêu một sự thật đã có rồi rút ra kết luận, thường là lời khuyên hay đề nghị: 既然你来了，就坐一会儿吧.","hsk_level":3,"tags":["lien-tu"],"image":"✅","examples":[{"type":"basic","zh":"既然你累了，就休息吧。","pinyin":"Jìrán nǐ lèi le, jiù xiūxi ba.","vi":"Bạn đã mệt rồi thì nghỉ đi."},{"type":"simple","zh":"既然大家都同意，我们就按照这个计划做吧。","pinyin":"Jìrán dàjiā dōu tóngyì, wǒmen jiù ànzhào zhège jìhuà zuò ba.","vi":"Mọi người đã đồng ý cả thì chúng ta làm theo kế hoạch này nhé."},{"type":"compound","zh":"既然你已经决定去中国留学了，那就从现在开始好好学习汉语吧。","pinyin":"Jìrán nǐ yǐjīng juédìng qù Zhōngguó liúxué le, nà jiù cóng xiànzài kāishǐ hǎohǎo xuéxí Hànyǔ ba.","vi":"Bạn đã quyết định sang Trung Quốc du học rồi thì từ bây giờ hãy học tiếng Trung thật chăm chỉ đi."}],"related":[{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"由于","pinyin":"yóuyú","vi":"Do, bởi vì"},{"hanzi":"所以","pinyin":"suǒyǐ","vi":"Cho nên"},{"hanzi":"就","pinyin":"jiù","vi":"Thì"},{"hanzi":"即使","pinyin":"jíshǐ","vi":"Cho dù"}]},{"id":"继续","hanzi":"继续","pinyin":"jìxù","meaning_vi":"tiếp tục","explanation":"继 và 续 đều có bộ 纟 (sợi tơ), đều mang nghĩa nối tiếp → tiếp tục. Dùng: 继续 + động từ (继续工作).","hsk_level":3,"tags":["dong-tu"],"image":"▶️","examples":[{"type":"basic","zh":"我们继续上课吧。","pinyin":"Wǒmen jìxù shàngkè ba.","vi":"Chúng ta tiếp tục học nhé."},{"type":"simple","zh":"休息了十分钟以后，大家又继续开会。","pinyin":"Xiūxile shí fēnzhōng yǐhòu, dàjiā yòu jìxù kāihuì.","vi":"Sau khi nghỉ mười phút, mọi người lại tiếp tục họp."},{"type":"compound","zh":"虽然我已经很累了，但是为了明天的考试，我还得继续复习。","pinyin":"Suīrán wǒ yǐjīng hěn lèi le, dànshì wèile míngtiān de kǎoshì, wǒ hái děi jìxù fùxí.","vi":"Tuy tôi đã rất mệt nhưng vì kỳ thi ngày mai, tôi vẫn phải tiếp tục ôn bài."}],"related":[{"hanzi":"持续","pinyin":"chíxù","vi":"Liên tục"},{"hanzi":"连续","pinyin":"liánxù","vi":"Liên tiếp"},{"hanzi":"继承","pinyin":"jìchéng","vi":"Kế thừa"},{"hanzi":"手续","pinyin":"shǒuxù","vi":"Thủ tục"},{"hanzi":"停止","pinyin":"tíngzhǐ","vi":"Dừng lại"}],"traditional":"繼續"},{"id":"加油站","hanzi":"加油站","pinyin":"jiāyóuzhàn","meaning_vi":"trạm xăng, cây xăng","explanation":"加 (thêm) + 油 (dầu, xăng) + 站 (trạm) → trạm đổ xăng. 加油 còn có nghĩa là cố lên.","hsk_level":3,"tags":["danh-tu","giao-thong","dia-diem"],"image":"⛽","examples":[{"type":"basic","zh":"前面有一个加油站。","pinyin":"Qiánmiàn yǒu yí gè jiāyóuzhàn.","vi":"Phía trước có một trạm xăng."},{"type":"simple","zh":"车快没油了，我们找个加油站加油吧。","pinyin":"Chē kuài méi yóu le, wǒmen zhǎo gè jiāyóuzhàn jiāyóu ba.","vi":"Xe sắp hết xăng rồi, chúng ta tìm một trạm xăng để đổ xăng nhé."},{"type":"compound","zh":"因为高速公路上的加油站很少，所以出发以前最好把油加满。","pinyin":"Yīnwèi gāosù gōnglù shang de jiāyóuzhàn hěn shǎo, suǒyǐ chūfā yǐqián zuìhǎo bǎ yóu jiāmǎn.","vi":"Vì trên đường cao tốc rất ít trạm xăng nên trước khi xuất phát tốt nhất nên đổ đầy xăng."}],"related":[{"hanzi":"加油","pinyin":"jiāyóu","vi":"Đổ xăng, cố lên"},{"hanzi":"汽油","pinyin":"qìyóu","vi":"Xăng"},{"hanzi":"汽车","pinyin":"qìchē","vi":"Ô tô"},{"hanzi":"车站","pinyin":"chēzhàn","vi":"Bến xe"},{"hanzi":"停车场","pinyin":"tíngchēchǎng","vi":"Bãi đỗ xe"}]},{"id":"家具","hanzi":"家具","pinyin":"jiājù","meaning_vi":"đồ nội thất, đồ đạc trong nhà","explanation":"家 (nhà) + 具 (đồ dùng) → đồ đạc trong nhà như bàn, ghế, giường, tủ. Lượng từ thường dùng: 件, 套.","hsk_level":3,"tags":["danh-tu","nha-cua"],"image":"🛋️","examples":[{"type":"basic","zh":"这些家具都是新的。","pinyin":"Zhèxiē jiājù dōu shì xīn de.","vi":"Những đồ nội thất này đều là đồ mới."},{"type":"simple","zh":"我们搬进新家以前，买了一套很漂亮的家具。","pinyin":"Wǒmen bānjìn xīn jiā yǐqián, mǎile yí tào hěn piàoliang de jiājù.","vi":"Trước khi dọn vào nhà mới, chúng tôi đã mua một bộ nội thất rất đẹp."},{"type":"compound","zh":"虽然这套房子有点旧，但是里面的家具都很新，住着很舒服。","pinyin":"Suīrán zhè tào fángzi yǒudiǎn jiù, dànshì lǐmiàn de jiājù dōu hěn xīn, zhùzhe hěn shūfu.","vi":"Tuy căn nhà này hơi cũ nhưng đồ nội thất bên trong đều rất mới, ở rất thoải mái."}],"related":[{"hanzi":"桌子","pinyin":"zhuōzi","vi":"Cái bàn"},{"hanzi":"椅子","pinyin":"yǐzi","vi":"Cái ghế"},{"hanzi":"沙发","pinyin":"shāfā","vi":"Ghế sofa"},{"hanzi":"床","pinyin":"chuáng","vi":"Giường"},{"hanzi":"工具","pinyin":"gōngjù","vi":"Công cụ"}]},{"id":"假","hanzi":"假","pinyin":"jiǎ","meaning_vi":"giả","explanation":"Đọc jiǎ nghĩa là giả, không thật (trái nghĩa 真). Đọc jià nghĩa là kỳ nghỉ: 放假 (được nghỉ), 请假 (xin nghỉ).","hsk_level":3,"tags":["tinh-tu"],"image":"🎭","examples":[{"type":"basic","zh":"这张钱是假的。","pinyin":"Zhè zhāng qián shì jiǎ de.","vi":"Tờ tiền này là tiền giả."},{"type":"simple","zh":"你别相信他的话，他说的都是假的。","pinyin":"Nǐ bié xiāngxìn tā de huà, tā shuō de dōu shì jiǎ de.","vi":"Bạn đừng tin lời anh ta, những gì anh ta nói đều là giả."},{"type":"compound","zh":"这个包虽然很便宜，可是它是假的，所以我没有买。","pinyin":"Zhège bāo suīrán hěn piányi, kěshì tā shì jiǎ de, suǒyǐ wǒ méiyǒu mǎi.","vi":"Cái túi này tuy rất rẻ nhưng là hàng giả, nên tôi đã không mua."}],"related":[{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"假话","pinyin":"jiǎhuà","vi":"Lời nói dối"},{"hanzi":"放假","pinyin":"fàngjià","vi":"Được nghỉ"},{"hanzi":"请假","pinyin":"qǐngjià","vi":"Xin nghỉ"},{"hanzi":"假期","pinyin":"jiàqī","vi":"Kỳ nghỉ"}]},{"id":"价格","hanzi":"价格","pinyin":"jiàgé","meaning_vi":"giá cả, giá","explanation":"价 (giá) + 格 (mức) → mức giá. Trang trọng hơn 价钱 (giá tiền, khẩu ngữ). Hay gặp: 价格很高/很低.","hsk_level":3,"tags":["danh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这里的价格很低。","pinyin":"Zhèlǐ de jiàgé hěn dī.","vi":"Giá cả ở đây rất thấp."},{"type":"simple","zh":"这两个手机的价格差不多，可是质量很不一样。","pinyin":"Zhè liǎng gè shǒujī de jiàgé chàbuduō, kěshì zhìliàng hěn bù yíyàng.","vi":"Giá của hai chiếc điện thoại này gần như nhau, nhưng chất lượng rất khác nhau."},{"type":"compound","zh":"因为最近水果的价格越来越高，所以妈妈买得比以前少了。","pinyin":"Yīnwèi zuìjìn shuǐguǒ de jiàgé yuè lái yuè gāo, suǒyǐ māma mǎi de bǐ yǐqián shǎo le.","vi":"Vì gần đây giá trái cây ngày càng cao nên mẹ mua ít hơn trước."}],"related":[{"hanzi":"价钱","pinyin":"jiàqian","vi":"Giá tiền"},{"hanzi":"价值","pinyin":"jiàzhí","vi":"Giá trị"},{"hanzi":"打折","pinyin":"dǎzhé","vi":"Giảm giá"},{"hanzi":"便宜","pinyin":"piányi","vi":"Rẻ"},{"hanzi":"贵","pinyin":"guì","vi":"Đắt"}],"traditional":"價格"},{"id":"奖金","hanzi":"奖金","pinyin":"jiǎngjīn","meaning_vi":"tiền thưởng","explanation":"奖 (thưởng) + 金 (tiền, vàng) → tiền thưởng, trong công việc hoặc cuộc thi. Khác 工资 (tiền lương hằng tháng).","hsk_level":3,"tags":["danh-tu","tien-te","cong-viec"],"image":"💰","examples":[{"type":"basic","zh":"他拿到了很多奖金。","pinyin":"Tā nádàole hěn duō jiǎngjīn.","vi":"Anh ấy đã nhận được rất nhiều tiền thưởng."},{"type":"simple","zh":"这次比赛的第一名可以得到一万块奖金。","pinyin":"Zhè cì bǐsài de dìyī míng kěyǐ dédào yíwàn kuài jiǎngjīn.","vi":"Người đứng nhất cuộc thi lần này có thể nhận được mười nghìn tệ tiền thưởng."},{"type":"compound","zh":"因为今年公司的生意很好，所以每个人都拿到了不少奖金。","pinyin":"Yīnwèi jīnnián gōngsī de shēngyi hěn hǎo, suǒyǐ měi gè rén dōu nádàole bù shǎo jiǎngjīn.","vi":"Vì năm nay công ty làm ăn rất tốt nên mỗi người đều nhận được khá nhiều tiền thưởng."}],"related":[{"hanzi":"工资","pinyin":"gōngzī","vi":"Tiền lương"},{"hanzi":"收入","pinyin":"shōurù","vi":"Thu nhập"},{"hanzi":"奖励","pinyin":"jiǎnglì","vi":"Khen thưởng"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"Khen ngợi"},{"hanzi":"现金","pinyin":"xiànjīn","vi":"Tiền mặt"}],"traditional":"獎金"},{"id":"降低","hanzi":"降低","pinyin":"jiàngdī","meaning_vi":"hạ thấp, giảm","explanation":"降 (xuống) + 低 (thấp); trái nghĩa 提高. Dùng với giá cả, nhiệt độ, yêu cầu…: 降低价格. 降 còn đọc xiáng (đầu hàng).","hsk_level":3,"tags":["dong-tu","so-luong"],"image":"📉","examples":[{"type":"basic","zh":"商店降低了价格。","pinyin":"Shāngdiàn jiàngdīle jiàgé.","vi":"Cửa hàng đã hạ giá."},{"type":"simple","zh":"晚上的温度降低了很多，你出门要多穿点衣服。","pinyin":"Wǎnshang de wēndù jiàngdīle hěn duō, nǐ chūmén yào duō chuān diǎn yīfu.","vi":"Buổi tối nhiệt độ đã giảm nhiều, bạn ra ngoài nhớ mặc thêm áo."},{"type":"compound","zh":"如果你每天都睡得很晚，学习的效果就会降低，所以还是早点睡吧。","pinyin":"Rúguǒ nǐ měitiān dōu shuì de hěn wǎn, xuéxí de xiàoguǒ jiù huì jiàngdī, suǒyǐ háishi zǎo diǎn shuì ba.","vi":"Nếu ngày nào bạn cũng ngủ rất muộn thì hiệu quả học tập sẽ giảm, nên tốt nhất là ngủ sớm một chút đi."}],"related":[{"hanzi":"提高","pinyin":"tígāo","vi":"Nâng cao"},{"hanzi":"低","pinyin":"dī","vi":"Thấp"},{"hanzi":"下降","pinyin":"xiàjiàng","vi":"Giảm xuống"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"Giảm bớt"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"Tăng thêm"}]},{"id":"交通","hanzi":"交通","pinyin":"jiāotōng","meaning_vi":"giao thông","explanation":"交 (qua lại) + 通 (thông suốt) → giao thông. Hay gặp: 交通方便 (giao thông thuận tiện), 交通工具 (phương tiện giao thông).","hsk_level":3,"tags":["danh-tu","giao-thong"],"image":"🚦","examples":[{"type":"basic","zh":"这里交通很方便。","pinyin":"Zhèlǐ jiāotōng hěn fāngbiàn.","vi":"Giao thông ở đây rất thuận tiện."},{"type":"simple","zh":"每天早上八点左右，这条路的交通都很乱。","pinyin":"Měitiān zǎoshang bā diǎn zuǒyòu, zhè tiáo lù de jiāotōng dōu hěn luàn.","vi":"Mỗi sáng khoảng tám giờ, giao thông trên con đường này đều rất hỗn loạn."},{"type":"compound","zh":"虽然这里的房子很便宜，但是交通不方便，所以很少有人来租。","pinyin":"Suīrán zhèlǐ de fángzi hěn piányi, dànshì jiāotōng bù fāngbiàn, suǒyǐ hěn shǎo yǒu rén lái zū.","vi":"Tuy nhà ở đây rất rẻ nhưng giao thông không thuận tiện, nên rất ít người đến thuê."}],"related":[{"hanzi":"堵车","pinyin":"dǔchē","vi":"Tắc đường"},{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","vi":"Xe buýt"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"通过","pinyin":"tōngguò","vi":"Thông qua"}]},{"id":"教授","hanzi":"教授","pinyin":"jiàoshòu","meaning_vi":"giáo sư","explanation":"教 (dạy, đọc jiào) + 授 (trao) → người truyền thụ kiến thức. Chức danh ở đại học, đặt sau họ: 王教授. Khi là động từ dạy, 教 đọc jiāo: 教书.","hsk_level":3,"tags":["danh-tu","nghe-nghiep","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"王教授在上课。","pinyin":"Wáng jiàoshòu zài shàngkè.","vi":"Giáo sư Vương đang lên lớp."},{"type":"simple","zh":"李教授在北京大学教了二十多年历史。","pinyin":"Lǐ jiàoshòu zài Běijīng Dàxué jiāole èrshí duō nián lìshǐ.","vi":"Giáo sư Lý đã dạy lịch sử ở Đại học Bắc Kinh hơn hai mươi năm."},{"type":"compound","zh":"虽然张教授已经七十岁了，但是他每天还坚持来学校做研究。","pinyin":"Suīrán Zhāng jiàoshòu yǐjīng qīshí suì le, dànshì tā měitiān hái jiānchí lái xuéxiào zuò yánjiū.","vi":"Tuy giáo sư Trương đã bảy mươi tuổi nhưng ông vẫn kiên trì đến trường làm nghiên cứu mỗi ngày."}],"related":[{"hanzi":"老师","pinyin":"lǎoshī","vi":"Giáo viên"},{"hanzi":"教育","pinyin":"jiàoyù","vi":"Giáo dục"},{"hanzi":"博士","pinyin":"bóshì","vi":"Tiến sĩ"},{"hanzi":"大学","pinyin":"dàxué","vi":"Đại học"},{"hanzi":"教室","pinyin":"jiàoshì","vi":"Phòng học"}]},{"id":"教育","hanzi":"教育","pinyin":"jiàoyù","meaning_vi":"giáo dục, dạy dỗ","explanation":"教 (dạy, đọc jiào) + 育 (nuôi dưỡng) → giáo dục. Vừa là danh từ (教育很重要) vừa là động từ (教育孩子: dạy dỗ con cái).","hsk_level":3,"tags":["danh-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"教育非常重要。","pinyin":"Jiàoyù fēicháng zhòngyào.","vi":"Giáo dục rất quan trọng."},{"type":"simple","zh":"父母应该用正确的方法教育孩子。","pinyin":"Fùmǔ yīnggāi yòng zhèngquè de fāngfǎ jiàoyù háizi.","vi":"Cha mẹ nên dùng phương pháp đúng đắn để dạy dỗ con cái."},{"type":"compound","zh":"因为她从小就受到了很好的教育，所以对人总是很有礼貌。","pinyin":"Yīnwèi tā cóngxiǎo jiù shòudàole hěn hǎo de jiàoyù, suǒyǐ duì rén zǒngshì hěn yǒu lǐmào.","vi":"Vì từ nhỏ cô ấy đã được giáo dục rất tốt nên luôn cư xử rất lễ phép với mọi người."}],"related":[{"hanzi":"教授","pinyin":"jiàoshòu","vi":"Giáo sư"},{"hanzi":"体育","pinyin":"tǐyù","vi":"Thể dục"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"Trường học"},{"hanzi":"培养","pinyin":"péiyǎng","vi":"Bồi dưỡng"},{"hanzi":"教室","pinyin":"jiàoshì","vi":"Phòng học"}]},{"id":"结果","hanzi":"结果","pinyin":"jiéguǒ","meaning_vi":"kết quả; rốt cuộc, kết cục là","explanation":"结 (kết) + 果 (quả) → kết quả. Còn đứng đầu vế sau với nghĩa rốt cuộc: 我等了他一个小时，结果他没来. Đọc jiēguǒ khi nghĩa là ra quả.","hsk_level":3,"tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"比赛的结果怎么样？","pinyin":"Bǐsài de jiéguǒ zěnmeyàng?","vi":"Kết quả trận đấu thế nào?"},{"type":"simple","zh":"医生看了检查结果以后，说我的身体没有问题。","pinyin":"Yīshēng kànle jiǎnchá jiéguǒ yǐhòu, shuō wǒ de shēntǐ méiyǒu wèntí.","vi":"Sau khi xem kết quả kiểm tra, bác sĩ nói sức khỏe của tôi không có vấn đề gì."},{"type":"compound","zh":"我在门口等了他一个小时，结果他根本没来，我只好一个人回家了。","pinyin":"Wǒ zài ménkǒu děngle tā yí gè xiǎoshí, jiéguǒ tā gēnběn méi lái, wǒ zhǐhǎo yí gè rén huí jiā le.","vi":"Tôi đợi anh ấy ở cửa một tiếng, rốt cuộc anh ấy hoàn toàn không đến, tôi đành một mình về nhà."}],"related":[{"hanzi":"结束","pinyin":"jiéshù","vi":"Kết thúc"},{"hanzi":"原因","pinyin":"yuányīn","vi":"Nguyên nhân"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"Hiệu quả"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"Trái cây"}],"traditional":"結果"},{"id":"紧张","hanzi":"紧张","pinyin":"jǐnzhāng","meaning_vi":"căng thẳng, hồi hộp; khẩn trương, gấp gáp","explanation":"Dùng cho tâm trạng (考试前很紧张: hồi hộp trước kỳ thi) và cho tình hình, công việc gấp gáp (工作很紧张). Trái nghĩa: 放松, 轻松.","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"我现在很紧张。","pinyin":"Wǒ xiànzài hěn jǐnzhāng.","vi":"Bây giờ tôi rất hồi hộp."},{"type":"simple","zh":"第一次跟中国人说汉语的时候，我紧张得脸都红了。","pinyin":"Dìyī cì gēn Zhōngguórén shuō Hànyǔ de shíhou, wǒ jǐnzhāng de liǎn dōu hóng le.","vi":"Lần đầu tiên nói tiếng Trung với người Trung Quốc, tôi hồi hộp đến đỏ cả mặt."},{"type":"compound","zh":"因为最近工作非常紧张，所以我已经两个星期没休息了。","pinyin":"Yīnwèi zuìjìn gōngzuò fēicháng jǐnzhāng, suǒyǐ wǒ yǐjīng liǎng gè xīngqī méi xiūxi le.","vi":"Vì gần đây công việc rất căng thẳng nên tôi đã hai tuần chưa được nghỉ."}],"related":[{"hanzi":"放松","pinyin":"fàngsōng","vi":"Thả lỏng"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"Nhẹ nhõm"},{"hanzi":"着急","pinyin":"zháojí","vi":"Sốt ruột"},{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"},{"hanzi":"激动","pinyin":"jīdòng","vi":"Xúc động"}],"traditional":"緊張"},{"id":"经济","hanzi":"经济","pinyin":"jīngjì","meaning_vi":"kinh tế","explanation":"经 (kinh) + 济 (tế) → kinh tế. Còn làm tính từ nghĩa tiết kiệm, rẻ, như 经济舱 (khoang phổ thông trên máy bay).","hsk_level":3,"tags":["danh-tu","xa-hoi"],"image":"📈","examples":[{"type":"basic","zh":"这几年经济发展很快。","pinyin":"Zhè jǐ nián jīngjì fāzhǎn hěn kuài.","vi":"Mấy năm nay kinh tế phát triển rất nhanh."},{"type":"simple","zh":"我哥哥在大学学的是经济，现在在银行工作。","pinyin":"Wǒ gēge zài dàxué xué de shì jīngjì, xiànzài zài yínháng gōngzuò.","vi":"Anh trai tôi học ngành kinh tế ở đại học, hiện đang làm việc ở ngân hàng."},{"type":"compound","zh":"因为这个城市的经济越来越好，所以很多年轻人都来这里找工作。","pinyin":"Yīnwèi zhège chéngshì de jīngjì yuè lái yuè hǎo, suǒyǐ hěn duō niánqīngrén dōu lái zhèlǐ zhǎo gōngzuò.","vi":"Vì kinh tế của thành phố này ngày càng tốt nên nhiều người trẻ đến đây tìm việc."}],"related":[{"hanzi":"经理","pinyin":"jīnglǐ","vi":"Giám đốc"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"Kinh nghiệm"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"},{"hanzi":"贸易","pinyin":"màoyì","vi":"Thương mại"},{"hanzi":"社会","pinyin":"shèhuì","vi":"Xã hội"}],"traditional":"經濟"},{"id":"竞争","hanzi":"竞争","pinyin":"jìngzhēng","meaning_vi":"cạnh tranh","explanation":"竞 (đua) + 争 (giành) → đua tranh. Hay gặp: 竞争很激烈 (cạnh tranh gay gắt), 竞争对手 (đối thủ cạnh tranh).","hsk_level":3,"tags":["dong-tu","xa-hoi"],"image":"🏆","examples":[{"type":"basic","zh":"现在找工作竞争很大。","pinyin":"Xiànzài zhǎo gōngzuò jìngzhēng hěn dà.","vi":"Bây giờ tìm việc làm có sự cạnh tranh rất lớn."},{"type":"simple","zh":"为了吸引更多顾客，这两家公司互相竞争，都降低了价格。","pinyin":"Wèile xīyǐn gèng duō gùkè, zhè liǎng jiā gōngsī hùxiāng jìngzhēng, dōu jiàngdīle jiàgé.","vi":"Để thu hút thêm khách hàng, hai công ty này cạnh tranh lẫn nhau và đều đã hạ giá."},{"type":"compound","zh":"虽然这次比赛的竞争非常激烈，但是他还是得了第一名。","pinyin":"Suīrán zhè cì bǐsài de jìngzhēng fēicháng jīliè, dànshì tā háishi déle dìyī míng.","vi":"Tuy cuộc thi lần này cạnh tranh rất gay gắt nhưng anh ấy vẫn giành giải nhất."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"Cuộc thi"},{"hanzi":"竞赛","pinyin":"jìngsài","vi":"Thi đua"},{"hanzi":"对手","pinyin":"duìshǒu","vi":"Đối thủ"},{"hanzi":"合作","pinyin":"hézuò","vi":"Hợp tác"},{"hanzi":"战争","pinyin":"zhànzhēng","vi":"Chiến tranh"}],"traditional":"競爭"},{"id":"竟然","hanzi":"竟然","pinyin":"jìngrán","meaning_vi":"vậy mà, không ngờ lại","explanation":"Phó từ diễn tả sự bất ngờ, ngoài dự đoán, đứng trước động từ: 他竟然忘了 (vậy mà anh ấy lại quên). Gần nghĩa với 居然.","hsk_level":3,"tags":["pho-tu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"他竟然忘了我的生日。","pinyin":"Tā jìngrán wàngle wǒ de shēngrì.","vi":"Vậy mà anh ấy lại quên sinh nhật tôi."},{"type":"simple","zh":"这么简单的问题，你竟然回答错了。","pinyin":"Zhème jiǎndān de wèntí, nǐ jìngrán huídá cuò le.","vi":"Câu hỏi đơn giản như vậy mà bạn lại trả lời sai."},{"type":"compound","zh":"虽然他只学了半年汉语，但是竟然已经能看懂中文报纸了。","pinyin":"Suīrán tā zhǐ xuéle bàn nián Hànyǔ, dànshì jìngrán yǐjīng néng kàndǒng Zhōngwén bàozhǐ le.","vi":"Tuy anh ấy mới học tiếng Trung được nửa năm, vậy mà đã đọc hiểu được báo tiếng Trung rồi."}],"related":[{"hanzi":"居然","pinyin":"jūrán","vi":"Vậy mà, lại"},{"hanzi":"没想到","pinyin":"méi xiǎngdào","vi":"Không ngờ"},{"hanzi":"突然","pinyin":"tūrán","vi":"Đột nhiên"},{"hanzi":"果然","pinyin":"guǒrán","vi":"Quả nhiên"},{"hanzi":"当然","pinyin":"dāngrán","vi":"Đương nhiên"}]},{"id":"镜子","hanzi":"镜子","pinyin":"jìngzi","meaning_vi":"cái gương","explanation":"镜 (kính, gương) + 子 (hậu tố danh từ). Phân biệt với 眼镜 (kính đeo mắt).","hsk_level":3,"tags":["danh-tu","do-vat"],"image":"🪞","examples":[{"type":"basic","zh":"她在照镜子。","pinyin":"Tā zài zhào jìngzi.","vi":"Cô ấy đang soi gương."},{"type":"simple","zh":"我每天出门以前都会照一下镜子。","pinyin":"Wǒ měitiān chūmén yǐqián dōu huì zhào yíxià jìngzi.","vi":"Mỗi ngày trước khi ra ngoài tôi đều soi gương một chút."},{"type":"compound","zh":"因为卫生间的镜子太小了，所以妈妈又买了一个更大的。","pinyin":"Yīnwèi wèishēngjiān de jìngzi tài xiǎo le, suǒyǐ māma yòu mǎile yí gè gèng dà de.","vi":"Vì cái gương trong nhà vệ sinh nhỏ quá nên mẹ lại mua một cái to hơn."}],"related":[{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"Kính mắt"},{"hanzi":"镜头","pinyin":"jìngtóu","vi":"Ống kính"},{"hanzi":"照","pinyin":"zhào","vi":"Soi, chiếu"},{"hanzi":"梳子","pinyin":"shūzi","vi":"Cái lược"},{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"Nhà vệ sinh"}],"traditional":"鏡子"},{"id":"究竟","hanzi":"究竟","pinyin":"jiūjìng","meaning_vi":"rốt cuộc","explanation":"Phó từ dùng trong câu hỏi để truy hỏi đến cùng, gần nghĩa 到底. Câu có 究竟 không dùng 吗 ở cuối.","hsk_level":3,"tags":["pho-tu","nghi-van"],"image":"🤔","examples":[{"type":"basic","zh":"你究竟去不去？","pinyin":"Nǐ jiūjìng qù bu qù?","vi":"Rốt cuộc bạn có đi hay không?"},{"type":"simple","zh":"他究竟为什么没来参加今天的会议？","pinyin":"Tā jiūjìng wèishénme méi lái cānjiā jīntiān de huìyì?","vi":"Rốt cuộc tại sao anh ấy không đến dự cuộc họp hôm nay?"},{"type":"compound","zh":"大家讨论了一个下午，可是究竟应该怎么解决这个问题，还是没有人知道。","pinyin":"Dàjiā tǎolùnle yí gè xiàwǔ, kěshì jiūjìng yīnggāi zěnme jiějué zhège wèntí, háishi méiyǒu rén zhīdào.","vi":"Mọi người thảo luận cả buổi chiều, nhưng rốt cuộc nên giải quyết vấn đề này thế nào thì vẫn chưa ai biết."}],"related":[{"hanzi":"到底","pinyin":"dàodǐ","vi":"Rốt cuộc"},{"hanzi":"研究","pinyin":"yánjiū","vi":"Nghiên cứu"},{"hanzi":"毕竟","pinyin":"bìjìng","vi":"Dù sao thì"},{"hanzi":"终于","pinyin":"zhōngyú","vi":"Cuối cùng"},{"hanzi":"为什么","pinyin":"wèishénme","vi":"Tại sao"}]},{"id":"距离","hanzi":"距离","pinyin":"jùlí","meaning_vi":"khoảng cách; cách (xa)","explanation":"Làm danh từ: khoảng cách. Làm động từ: A 距离 B + khoảng cách (A cách B bao xa), gần nghĩa 离.","hsk_level":3,"tags":["danh-tu","dia-diem"],"image":"📏","examples":[{"type":"basic","zh":"我家和学校的距离很近。","pinyin":"Wǒ jiā hé xuéxiào de jùlí hěn jìn.","vi":"Khoảng cách giữa nhà tôi và trường học rất gần."},{"type":"simple","zh":"这里距离机场大概有三十公里。","pinyin":"Zhèlǐ jùlí jīchǎng dàgài yǒu sānshí gōnglǐ.","vi":"Từ đây cách sân bay khoảng ba mươi ki-lô-mét."},{"type":"compound","zh":"虽然我家距离公司比较远，但是坐地铁去很方便。","pinyin":"Suīrán wǒ jiā jùlí gōngsī bǐjiào yuǎn, dànshì zuò dìtiě qù hěn fāngbiàn.","vi":"Tuy nhà tôi cách công ty khá xa nhưng đi tàu điện ngầm thì rất tiện."}],"related":[{"hanzi":"离","pinyin":"lí","vi":"Cách"},{"hanzi":"远","pinyin":"yuǎn","vi":"Xa"},{"hanzi":"近","pinyin":"jìn","vi":"Gần"},{"hanzi":"公里","pinyin":"gōnglǐ","vi":"Ki-lô-mét"},{"hanzi":"差距","pinyin":"chājù","vi":"Chênh lệch"}],"traditional":"距離"},{"id":"棵","hanzi":"棵","pinyin":"kē","meaning_vi":"cây (lượng từ cho cây cối)","explanation":"Có bộ 木 (cây), là lượng từ cho cây cối, cỏ, rau: 一棵树 (một cái cây), 一棵白菜 (một cây cải thảo).","hsk_level":3,"tags":["luong-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"门口有一棵树。","pinyin":"Ménkǒu yǒu yì kē shù.","vi":"Trước cửa có một cái cây."},{"type":"simple","zh":"爷爷在院子里种了三棵苹果树。","pinyin":"Yéye zài yuànzi li zhòngle sān kē píngguǒshù.","vi":"Ông nội đã trồng ba cây táo trong sân."},{"type":"compound","zh":"这棵树已经一百多岁了，夏天的时候，很多人都喜欢在树下休息。","pinyin":"Zhè kē shù yǐjīng yìbǎi duō suì le, xiàtiān de shíhou, hěn duō rén dōu xǐhuan zài shù xià xiūxi.","vi":"Cái cây này đã hơn một trăm tuổi rồi, vào mùa hè rất nhiều người thích nghỉ ngơi dưới gốc cây."}],"related":[{"hanzi":"树","pinyin":"shù","vi":"Cây"},{"hanzi":"草","pinyin":"cǎo","vi":"Cỏ"},{"hanzi":"花","pinyin":"huā","vi":"Hoa"},{"hanzi":"颗","pinyin":"kē","vi":"Hạt, viên (lượng từ)"},{"hanzi":"森林","pinyin":"sēnlín","vi":"Rừng"}]},{"id":"可惜","hanzi":"可惜","pinyin":"kěxī","meaning_vi":"đáng tiếc, tiếc","explanation":"可 (đáng) + 惜 (tiếc). Dùng như tính từ (真可惜 = tiếc thật) hoặc đứng đầu vế câu với nghĩa 'tiếc là…' (可惜他没来).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"真可惜，你没来！","pinyin":"Zhēn kěxī, nǐ méi lái!","vi":"Tiếc thật, bạn đã không đến!"},{"type":"simple","zh":"这么好吃的菜，没吃完就扔了，太可惜了。","pinyin":"Zhème hǎochī de cài, méi chīwán jiù rēng le, tài kěxī le.","vi":"Món ăn ngon thế này, chưa ăn hết đã vứt đi, thật quá đáng tiếc."},{"type":"compound","zh":"昨天的电影非常精彩，可惜你因为加班没能跟我们一起去看。","pinyin":"Zuótiān de diànyǐng fēicháng jīngcǎi, kěxī nǐ yīnwèi jiābān méi néng gēn wǒmen yìqǐ qù kàn.","vi":"Bộ phim hôm qua rất hay, tiếc là bạn vì tăng ca nên không thể đi xem cùng chúng tôi."}],"related":[{"hanzi":"遗憾","pinyin":"yíhàn","vi":"Đáng tiếc"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"Trân trọng"},{"hanzi":"爱惜","pinyin":"àixī","vi":"Quý trọng"},{"hanzi":"可怜","pinyin":"kělián","vi":"Đáng thương"},{"hanzi":"舍不得","pinyin":"shěbude","vi":"Không nỡ"}]},{"id":"空气","hanzi":"空气","pinyin":"kōngqì","meaning_vi":"không khí","explanation":"空 (không trung) + 气 (khí). 空 ở đây đọc kōng; khi đọc kòng nghĩa là rảnh, chỗ trống (有空 = có thời gian rảnh).","hsk_level":3,"tags":["danh-tu","thien-nhien"],"image":"🌬️","examples":[{"type":"basic","zh":"这里的空气很好。","pinyin":"Zhèlǐ de kōngqì hěn hǎo.","vi":"Không khí ở đây rất tốt."},{"type":"simple","zh":"早上起床以后，我喜欢打开窗户换换新鲜空气。","pinyin":"Zǎoshang qǐchuáng yǐhòu, wǒ xǐhuan dǎkāi chuānghu huànhuan xīnxiān kōngqì.","vi":"Sáng dậy, tôi thích mở cửa sổ để thay không khí trong lành."},{"type":"compound","zh":"因为城市里的车越来越多，所以空气污染也越来越严重了。","pinyin":"Yīnwèi chéngshì li de chē yuèláiyuè duō, suǒyǐ kōngqì wūrǎn yě yuèláiyuè yánzhòng le.","vi":"Vì xe cộ trong thành phố ngày càng nhiều nên ô nhiễm không khí cũng ngày càng nghiêm trọng."}],"related":[{"hanzi":"天气","pinyin":"tiānqì","vi":"Thời tiết"},{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"Tươi, trong lành"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"Ô nhiễm"},{"hanzi":"空调","pinyin":"kōngtiáo","vi":"Điều hòa"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"Hít thở"}],"traditional":"空氣"},{"id":"困","hanzi":"困","pinyin":"kùn","meaning_vi":"buồn ngủ; vây hãm, khốn đốn","explanation":"Chữ 木 (cây) bị vây trong khung 囗 → bị vây khốn. Trong khẩu ngữ hay dùng nghĩa 'buồn ngủ'; trong 困难 mang nghĩa khó khăn.","hsk_level":3,"tags":["tinh-tu","sinh-hoat"],"image":"😪","examples":[{"type":"basic","zh":"我太困了，想睡觉。","pinyin":"Wǒ tài kùn le, xiǎng shuìjiào.","vi":"Tôi buồn ngủ quá, muốn đi ngủ."},{"type":"simple","zh":"他昨天晚上没睡好，今天上课一直很困。","pinyin":"Tā zuótiān wǎnshang méi shuìhǎo, jīntiān shàngkè yìzhí hěn kùn.","vi":"Tối qua anh ấy ngủ không ngon, hôm nay trong giờ học cứ buồn ngủ mãi."},{"type":"compound","zh":"如果开车的时候觉得困，就一定要停下来休息，不然很危险。","pinyin":"Rúguǒ kāichē de shíhou juéde kùn, jiù yídìng yào tíng xiàlai xiūxi, bùrán hěn wēixiǎn.","vi":"Nếu khi lái xe thấy buồn ngủ thì nhất định phải dừng lại nghỉ, nếu không sẽ rất nguy hiểm."}],"related":[{"hanzi":"困难","pinyin":"kùnnan","vi":"Khó khăn"},{"hanzi":"累","pinyin":"lèi","vi":"Mệt"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Đi ngủ"},{"hanzi":"休息","pinyin":"xiūxi","vi":"Nghỉ ngơi"},{"hanzi":"失眠","pinyin":"shīmián","vi":"Mất ngủ"}]},{"id":"困难","hanzi":"困难","pinyin":"kùnnan","meaning_vi":"khó khăn","explanation":"困 (vây khốn) + 难 (khó). Chủ yếu dùng như danh từ (遇到困难 = gặp khó khăn, 克服困难 = khắc phục khó khăn); cũng làm tính từ (很困难).","hsk_level":3,"tags":["danh-tu"],"image":"🧗","examples":[{"type":"basic","zh":"学汉语不太困难。","pinyin":"Xué Hànyǔ bú tài kùnnan.","vi":"Học tiếng Trung không khó lắm."},{"type":"simple","zh":"遇到困难的时候，你可以找朋友帮忙。","pinyin":"Yùdào kùnnan de shíhou, nǐ kěyǐ zhǎo péngyou bāngmáng.","vi":"Khi gặp khó khăn, bạn có thể nhờ bạn bè giúp đỡ."},{"type":"compound","zh":"虽然刚来中国的时候生活上有很多困难，但是他很快就适应了。","pinyin":"Suīrán gāng lái Zhōngguó de shíhou shēnghuó shang yǒu hěn duō kùnnan, dànshì tā hěn kuài jiù shìyìng le.","vi":"Tuy lúc mới đến Trung Quốc gặp nhiều khó khăn trong cuộc sống, nhưng anh ấy đã nhanh chóng thích nghi."}],"related":[{"hanzi":"困","pinyin":"kùn","vi":"Buồn ngủ"},{"hanzi":"难","pinyin":"nán","vi":"Khó"},{"hanzi":"容易","pinyin":"róngyì","vi":"Dễ"},{"hanzi":"问题","pinyin":"wèntí","vi":"Vấn đề"},{"hanzi":"克服","pinyin":"kèfú","vi":"Khắc phục"}],"traditional":"困難"},{"id":"垃圾桶","hanzi":"垃圾桶","pinyin":"lājītǒng","meaning_vi":"thùng rác","explanation":"垃圾 (rác) + 桶 (thùng). 垃圾 đọc lājī; ở một số nơi (như Đài Loan) còn đọc lèsè.","hsk_level":3,"tags":["danh-tu","do-vat"],"image":"🗑️","examples":[{"type":"basic","zh":"请把垃圾扔进垃圾桶。","pinyin":"Qǐng bǎ lājī rēngjìn lājītǒng.","vi":"Xin hãy vứt rác vào thùng rác."},{"type":"simple","zh":"厨房里的垃圾桶已经满了，你去倒一下吧。","pinyin":"Chúfáng li de lājītǒng yǐjīng mǎn le, nǐ qù dào yíxià ba.","vi":"Thùng rác trong bếp đã đầy rồi, bạn đi đổ đi."},{"type":"compound","zh":"因为公园里到处都有垃圾桶，所以大家都不会把垃圾扔在地上。","pinyin":"Yīnwèi gōngyuán li dàochù dōu yǒu lājītǒng, suǒyǐ dàjiā dōu bú huì bǎ lājī rēng zài dìshang.","vi":"Vì trong công viên chỗ nào cũng có thùng rác nên mọi người đều không vứt rác xuống đất."}],"related":[{"hanzi":"垃圾","pinyin":"lājī","vi":"Rác"},{"hanzi":"扔","pinyin":"rēng","vi":"Vứt"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"脏","pinyin":"zāng","vi":"Bẩn"},{"hanzi":"塑料袋","pinyin":"sùliàodài","vi":"Túi ni lông"}]},{"id":"浪漫","hanzi":"浪漫","pinyin":"làngmàn","meaning_vi":"lãng mạn","explanation":"Hán-Việt là 'lãng mạn', nghĩa giống tiếng Việt. Hay gặp: 很浪漫, 浪漫的晚上.","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"🌹","examples":[{"type":"basic","zh":"这个地方很浪漫。","pinyin":"Zhège dìfang hěn làngmàn.","vi":"Nơi này rất lãng mạn."},{"type":"simple","zh":"他在女朋友生日那天送了她九十九朵花，非常浪漫。","pinyin":"Tā zài nǚpéngyou shēngrì nà tiān sòngle tā jiǔshíjiǔ duǒ huā, fēicháng làngmàn.","vi":"Vào ngày sinh nhật bạn gái, anh ấy đã tặng cô chín mươi chín bông hoa, vô cùng lãng mạn."},{"type":"compound","zh":"虽然他不太浪漫，但是他很关心我，每天都会给我做早饭。","pinyin":"Suīrán tā bú tài làngmàn, dànshì tā hěn guānxīn wǒ, měitiān dōu huì gěi wǒ zuò zǎofàn.","vi":"Tuy anh ấy không lãng mạn lắm nhưng rất quan tâm tôi, ngày nào cũng làm bữa sáng cho tôi."}],"related":[{"hanzi":"爱情","pinyin":"àiqíng","vi":"Tình yêu"},{"hanzi":"约会","pinyin":"yuēhuì","vi":"Hẹn hò"},{"hanzi":"鲜花","pinyin":"xiānhuā","vi":"Hoa tươi"},{"hanzi":"温柔","pinyin":"wēnróu","vi":"Dịu dàng"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"Kết hôn"}]},{"id":"老虎","hanzi":"老虎","pinyin":"lǎohǔ","meaning_vi":"con hổ","explanation":"老 ở đây là tiền tố, không mang nghĩa 'già' (giống 老鼠 = con chuột); 虎 là hổ.","hsk_level":3,"tags":["danh-tu","dong-vat"],"image":"🐯","examples":[{"type":"basic","zh":"老虎很可怕。","pinyin":"Lǎohǔ hěn kěpà.","vi":"Hổ rất đáng sợ."},{"type":"simple","zh":"孩子们最喜欢看动物园里那只大老虎。","pinyin":"Háizimen zuì xǐhuan kàn dòngwùyuán li nà zhī dà lǎohǔ.","vi":"Bọn trẻ thích nhất là xem con hổ lớn trong sở thú."},{"type":"compound","zh":"虽然老虎看起来很可爱，但是它是很危险的动物，我们不能离它太近。","pinyin":"Suīrán lǎohǔ kàn qǐlai hěn kě'ài, dànshì tā shì hěn wēixiǎn de dòngwù, wǒmen bù néng lí tā tài jìn.","vi":"Tuy hổ trông có vẻ đáng yêu nhưng nó là loài động vật rất nguy hiểm, chúng ta không được đến quá gần nó."}],"related":[{"hanzi":"狮子","pinyin":"shīzi","vi":"Sư tử"},{"hanzi":"老鼠","pinyin":"lǎoshǔ","vi":"Con chuột"},{"hanzi":"动物","pinyin":"dòngwù","vi":"Động vật"},{"hanzi":"动物园","pinyin":"dòngwùyuán","vi":"Sở thú"},{"hanzi":"熊猫","pinyin":"xióngmāo","vi":"Gấu trúc"}]},{"id":"冷静","hanzi":"冷静","pinyin":"lěngjìng","meaning_vi":"bình tĩnh, điềm tĩnh","explanation":"冷 (lạnh) + 静 (tĩnh) → đầu óc 'lạnh và tĩnh', không nóng vội. Cũng dùng như động từ: 冷静一下 (bình tĩnh lại).","hsk_level":3,"tags":["tinh-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"你先冷静一下。","pinyin":"Nǐ xiān lěngjìng yíxià.","vi":"Bạn bình tĩnh lại một chút đã."},{"type":"simple","zh":"遇到问题的时候，他总是很冷静。","pinyin":"Yùdào wèntí de shíhou, tā zǒngshì hěn lěngjìng.","vi":"Khi gặp vấn đề, anh ấy luôn rất bình tĩnh."},{"type":"compound","zh":"生气的时候说话很容易说错，所以最好先冷静下来再说。","pinyin":"Shēngqì de shíhou shuōhuà hěn róngyì shuōcuò, suǒyǐ zuìhǎo xiān lěngjìng xiàlai zài shuō.","vi":"Lúc tức giận mà nói thì rất dễ nói sai, vì vậy tốt nhất hãy bình tĩnh lại rồi hẵng nói."}],"related":[{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"着急","pinyin":"zháojí","vi":"Sốt ruột"},{"hanzi":"生气","pinyin":"shēngqì","vi":"Tức giận"},{"hanzi":"激动","pinyin":"jīdòng","vi":"Kích động"}],"traditional":"冷靜"},{"id":"礼貌","hanzi":"礼貌","pinyin":"lǐmào","meaning_vi":"lễ phép, lịch sự","explanation":"礼 (lễ) + 貌 (dáng vẻ). Chủ yếu dùng như danh từ: 有礼貌 (lễ phép), 没礼貌 (vô lễ); 不礼貌 dùng như tính từ (bất lịch sự).","hsk_level":3,"tags":["danh-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"这个孩子很有礼貌。","pinyin":"Zhège háizi hěn yǒu lǐmào.","vi":"Đứa trẻ này rất lễ phép."},{"type":"simple","zh":"吃饭的时候一直看手机，是很不礼貌的。","pinyin":"Chīfàn de shíhou yìzhí kàn shǒujī, shì hěn bù lǐmào de.","vi":"Lúc ăn cơm mà cứ xem điện thoại là rất bất lịch sự."},{"type":"compound","zh":"妈妈从小就告诉我，见到老人要主动打招呼，这样才有礼貌。","pinyin":"Māma cóngxiǎo jiù gàosu wǒ, jiàndào lǎorén yào zhǔdòng dǎ zhāohu, zhèyàng cái yǒu lǐmào.","vi":"Từ nhỏ mẹ đã dặn tôi, gặp người già phải chủ động chào hỏi, như vậy mới là lễ phép."}],"related":[{"hanzi":"礼物","pinyin":"lǐwù","vi":"Quà"},{"hanzi":"客气","pinyin":"kèqi","vi":"Khách sáo"},{"hanzi":"打招呼","pinyin":"dǎzhāohu","vi":"Chào hỏi"},{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"Tôn trọng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"禮貌"},{"id":"力气","hanzi":"力气","pinyin":"lìqi","meaning_vi":"sức lực, sức","explanation":"力 (lực) + 气 (khí, đọc nhẹ). Hay nói 有力气, 没力气, 花力气. Phân biệt với 力量 (sức mạnh, nghĩa rộng và trừu tượng hơn).","hsk_level":3,"tags":["danh-tu","co-the"],"image":"💪","examples":[{"type":"basic","zh":"他的力气很大。","pinyin":"Tā de lìqi hěn dà.","vi":"Sức lực của anh ấy rất lớn."},{"type":"simple","zh":"我今天没吃早饭，现在一点力气也没有了。","pinyin":"Wǒ jīntiān méi chī zǎofàn, xiànzài yìdiǎn lìqi yě méiyǒu le.","vi":"Hôm nay tôi chưa ăn sáng, bây giờ chẳng còn chút sức nào."},{"type":"compound","zh":"这个箱子太重了，我们俩花了很大力气，才把它搬到楼上。","pinyin":"Zhège xiāngzi tài zhòng le, wǒmen liǎ huāle hěn dà lìqi, cái bǎ tā bāndào lóushang.","vi":"Cái thùng này nặng quá, hai chúng tôi phải tốn rất nhiều sức mới chuyển được nó lên tầng trên."}],"related":[{"hanzi":"力量","pinyin":"lìliàng","vi":"Sức mạnh"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"使劲儿","pinyin":"shǐjìnr","vi":"Dùng sức"},{"hanzi":"能力","pinyin":"nénglì","vi":"Năng lực"},{"hanzi":"累","pinyin":"lèi","vi":"Mệt"}],"traditional":"力氣"},{"id":"厉害","hanzi":"厉害","pinyin":"lìhai","meaning_vi":"ghê gớm, dữ dội; giỏi, lợi hại","explanation":"Có hai sắc thái: chỉ mức độ dữ dội (疼得厉害 = đau dữ dội) và khen ai đó giỏi (你真厉害！). Hay làm bổ ngữ sau 得.","hsk_level":3,"tags":["tinh-tu"],"image":"💥","examples":[{"type":"basic","zh":"外面风刮得很厉害。","pinyin":"Wàimiàn fēng guā de hěn lìhai.","vi":"Bên ngoài gió thổi rất mạnh."},{"type":"simple","zh":"我昨天晚上牙疼得很厉害，一夜都没睡好。","pinyin":"Wǒ zuótiān wǎnshang yá téng de hěn lìhai, yí yè dōu méi shuìhǎo.","vi":"Tối qua tôi đau răng dữ dội, cả đêm ngủ không ngon."},{"type":"compound","zh":"虽然她只有十岁，但是已经会说三种语言了，真厉害！","pinyin":"Suīrán tā zhǐ yǒu shí suì, dànshì yǐjīng huì shuō sān zhǒng yǔyán le, zhēn lìhai!","vi":"Tuy cô bé mới mười tuổi nhưng đã biết nói ba thứ tiếng rồi, giỏi thật!"}],"related":[{"hanzi":"了不起","pinyin":"liǎobuqǐ","vi":"Phi thường, giỏi giang"},{"hanzi":"严重","pinyin":"yánzhòng","vi":"Nghiêm trọng"},{"hanzi":"害怕","pinyin":"hàipà","vi":"Sợ hãi"},{"hanzi":"棒","pinyin":"bàng","vi":"Giỏi, tuyệt"},{"hanzi":"聪明","pinyin":"cōngming","vi":"Thông minh"}],"traditional":"厲害"},{"id":"例如","hanzi":"例如","pinyin":"lìrú","meaning_vi":"ví dụ như, chẳng hạn","explanation":"例 (ví dụ) + 如 (như). Dùng để nêu ví dụ, nghĩa như 比如 nhưng trang trọng hơn.","hsk_level":3,"tags":["dong-tu","ngon-ngu"],"image":"📝","examples":[{"type":"basic","zh":"我喜欢水果，例如苹果和西瓜。","pinyin":"Wǒ xǐhuan shuǐguǒ, lìrú píngguǒ hé xīguā.","vi":"Tôi thích trái cây, ví dụ như táo và dưa hấu."},{"type":"simple","zh":"中国有很多有名的城市，例如北京、上海和西安。","pinyin":"Zhōngguó yǒu hěn duō yǒumíng de chéngshì, lìrú Běijīng, Shànghǎi hé Xī'ān.","vi":"Trung Quốc có rất nhiều thành phố nổi tiếng, ví dụ như Bắc Kinh, Thượng Hải và Tây An."},{"type":"compound","zh":"如果你想提高汉语水平，可以多做一些练习，例如每天看中文电影或者跟中国朋友聊天。","pinyin":"Rúguǒ nǐ xiǎng tígāo Hànyǔ shuǐpíng, kěyǐ duō zuò yìxiē liànxí, lìrú měitiān kàn Zhōngwén diànyǐng huòzhě gēn Zhōngguó péngyou liáotiān.","vi":"Nếu bạn muốn nâng cao trình độ tiếng Trung thì có thể luyện tập nhiều hơn, ví dụ như mỗi ngày xem phim tiếng Trung hoặc trò chuyện với bạn bè người Trung Quốc."}],"related":[{"hanzi":"比如","pinyin":"bǐrú","vi":"Ví dụ như"},{"hanzi":"例子","pinyin":"lìzi","vi":"Ví dụ"},{"hanzi":"举例","pinyin":"jǔlì","vi":"Nêu ví dụ"},{"hanzi":"比方","pinyin":"bǐfang","vi":"Ví như"},{"hanzi":"如果","pinyin":"rúguǒ","vi":"Nếu"}]},{"id":"俩","hanzi":"俩","pinyin":"liǎ","meaning_vi":"hai, hai người (khẩu ngữ, = 两个)","explanation":"亻(người) + 两 (hai) → hai người. 俩 đã bằng 两个 nên sau 俩 không thêm 个: nói 我们俩, không nói 俩个.","hsk_level":3,"tags":["so-dem","so-luong"],"image":"👫","examples":[{"type":"basic","zh":"我们俩是好朋友。","pinyin":"Wǒmen liǎ shì hǎo péngyou.","vi":"Hai chúng tôi là bạn tốt."},{"type":"simple","zh":"他们俩每天早上都一起去公园跑步。","pinyin":"Tāmen liǎ měitiān zǎoshang dōu yìqǐ qù gōngyuán pǎobù.","vi":"Hai người họ sáng nào cũng cùng nhau ra công viên chạy bộ."},{"type":"compound","zh":"虽然姐妹俩长得很像，但是她们的性格完全不一样。","pinyin":"Suīrán jiěmèi liǎ zhǎng de hěn xiàng, dànshì tāmen de xìnggé wánquán bù yíyàng.","vi":"Tuy hai chị em trông rất giống nhau nhưng tính cách của họ hoàn toàn khác nhau."}],"related":[{"hanzi":"两","pinyin":"liǎng","vi":"Hai"},{"hanzi":"仨","pinyin":"sā","vi":"Ba (khẩu ngữ)"},{"hanzi":"双","pinyin":"shuāng","vi":"Đôi"},{"hanzi":"我们","pinyin":"wǒmen","vi":"Chúng tôi"},{"hanzi":"一起","pinyin":"yìqǐ","vi":"Cùng nhau"}],"traditional":"倆"},{"id":"连","hanzi":"连","pinyin":"lián","meaning_vi":"ngay cả, đến cả; nối liền, liên tiếp","explanation":"Cấu trúc 连…都/也… = 'ngay cả… cũng…', dùng để nhấn mạnh. Làm động từ nghĩa là nối liền; 连着 = liên tiếp, liền.","hsk_level":3,"tags":["gioi-tu"],"image":"🔗","examples":[{"type":"basic","zh":"他连饭都没吃。","pinyin":"Tā lián fàn dōu méi chī.","vi":"Anh ấy ngay cả cơm cũng chưa ăn."},{"type":"simple","zh":"这个问题太简单了，连我的小妹妹都会回答。","pinyin":"Zhège wèntí tài jiǎndān le, lián wǒ de xiǎo mèimei dōu huì huídá.","vi":"Câu hỏi này đơn giản quá, ngay cả em gái nhỏ của tôi cũng trả lời được."},{"type":"compound","zh":"他连着三个晚上都在准备考试，所以今天上课的时候特别困。","pinyin":"Tā liánzhe sān gè wǎnshang dōu zài zhǔnbèi kǎoshì, suǒyǐ jīntiān shàngkè de shíhou tèbié kùn.","vi":"Anh ấy liền ba buổi tối đều ôn thi, vì vậy hôm nay lúc lên lớp đặc biệt buồn ngủ."}],"related":[{"hanzi":"连续","pinyin":"liánxù","vi":"Liên tục"},{"hanzi":"连忙","pinyin":"liánmáng","vi":"Vội vàng"},{"hanzi":"接连","pinyin":"jiēlián","vi":"Liên tiếp"},{"hanzi":"甚至","pinyin":"shènzhì","vi":"Thậm chí"},{"hanzi":"联系","pinyin":"liánxì","vi":"Liên lạc"}],"traditional":"連"},{"id":"聊天","hanzi":"聊天","pinyin":"liáotiān","meaning_vi":"trò chuyện, tán gẫu","explanation":"Động từ ly hợp: 聊 (trò chuyện) + 天 (chuyện trời đất). Có thể tách ra: 聊了一会儿天, 聊什么天.","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"我和妈妈在聊天。","pinyin":"Wǒ hé māma zài liáotiān.","vi":"Tôi và mẹ đang trò chuyện."},{"type":"simple","zh":"下课以后，同学们喜欢在教室里聊天。","pinyin":"Xiàkè yǐhòu, tóngxuémen xǐhuan zài jiàoshì li liáotiān.","vi":"Sau giờ học, các bạn học thích tán gẫu trong lớp."},{"type":"compound","zh":"因为很久没见面了，所以我们俩一边吃饭一边聊天，一直聊到饭店关门。","pinyin":"Yīnwèi hěn jiǔ méi jiànmiàn le, suǒyǐ wǒmen liǎ yìbiān chīfàn yìbiān liáotiān, yìzhí liáodào fàndiàn guānmén.","vi":"Vì lâu rồi không gặp nhau nên hai chúng tôi vừa ăn vừa trò chuyện, nói mãi đến khi nhà hàng đóng cửa."}],"related":[{"hanzi":"聊","pinyin":"liáo","vi":"Tán gẫu"},{"hanzi":"说话","pinyin":"shuōhuà","vi":"Nói chuyện"},{"hanzi":"谈","pinyin":"tán","vi":"Bàn, nói chuyện"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"Giao lưu"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"Thảo luận"}]},{"id":"另外","hanzi":"另外","pinyin":"lìngwài","meaning_vi":"ngoài ra; khác","explanation":"Đầu câu nghĩa là 'ngoài ra' (bổ sung ý); trước danh từ nghĩa là 'khác' (另外一件); trước động từ nghĩa là 'riêng, thêm' (另外买一个).","hsk_level":3,"tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"另外，我还想买一本书。","pinyin":"Lìngwài, wǒ hái xiǎng mǎi yì běn shū.","vi":"Ngoài ra, tôi còn muốn mua một quyển sách."},{"type":"simple","zh":"这件衣服太小了，请给我拿另外一件看看。","pinyin":"Zhè jiàn yīfu tài xiǎo le, qǐng gěi wǒ ná lìngwài yí jiàn kànkan.","vi":"Chiếc áo này nhỏ quá, làm ơn lấy cho tôi chiếc khác xem thử."},{"type":"compound","zh":"明天的会议很重要，大家一定要准时到。另外，请每个人都带上自己的笔记本。","pinyin":"Míngtiān de huìyì hěn zhòngyào, dàjiā yídìng yào zhǔnshí dào. Lìngwài, qǐng měi gè rén dōu dàishang zìjǐ de bǐjìběn.","vi":"Cuộc họp ngày mai rất quan trọng, mọi người nhất định phải đến đúng giờ. Ngoài ra, mỗi người hãy mang theo sổ ghi chép của mình."}],"related":[{"hanzi":"此外","pinyin":"cǐwài","vi":"Ngoài ra"},{"hanzi":"其他","pinyin":"qítā","vi":"Khác"},{"hanzi":"别的","pinyin":"biéde","vi":"Cái khác"},{"hanzi":"而且","pinyin":"érqiě","vi":"Hơn nữa"},{"hanzi":"除了","pinyin":"chúle","vi":"Ngoài… ra"}]},{"id":"满","hanzi":"满","pinyin":"mǎn","meaning_vi":"đầy; hài lòng","explanation":"Bộ 氵(nước) → nước đầy. Hay gặp trong 满意 (hài lòng), 充满 (tràn đầy), 不满 (bất mãn).","hsk_level":3,"tags":["tinh-tu","so-luong"],"image":"🈵","examples":[{"type":"basic","zh":"杯子里的水满了。","pinyin":"Bēizi li de shuǐ mǎn le.","vi":"Nước trong cốc đầy rồi."},{"type":"simple","zh":"他的书包里放满了书和本子。","pinyin":"Tā de shūbāo li fàngmǎnle shū hé běnzi.","vi":"Trong cặp sách của cậu ấy để đầy sách và vở."},{"type":"compound","zh":"因为周末的电影院坐满了人，所以我们只好买了下一场的票。","pinyin":"Yīnwèi zhōumò de diànyǐngyuàn zuòmǎnle rén, suǒyǐ wǒmen zhǐhǎo mǎile xià yì chǎng de piào.","vi":"Vì cuối tuần rạp chiếu phim kín chỗ nên chúng tôi đành mua vé suất sau."}],"related":[{"hanzi":"满意","pinyin":"mǎnyì","vi":"Hài lòng"},{"hanzi":"充满","pinyin":"chōngmǎn","vi":"Tràn đầy"},{"hanzi":"满足","pinyin":"mǎnzú","vi":"Thỏa mãn"},{"hanzi":"不满","pinyin":"bùmǎn","vi":"Bất mãn"},{"hanzi":"空","pinyin":"kōng","vi":"Trống rỗng"}],"traditional":"滿"},{"id":"毛巾","hanzi":"毛巾","pinyin":"máojīn","meaning_vi":"khăn mặt, khăn bông","explanation":"毛 (lông, sợi) + 巾 (khăn) → khăn dệt bằng sợi bông. Khăn tắm là 浴巾, khăn quàng cổ là 围巾.","hsk_level":3,"tags":["danh-tu","sinh-hoat"],"image":"🛁","examples":[{"type":"basic","zh":"这是我的毛巾。","pinyin":"Zhè shì wǒ de máojīn.","vi":"Đây là khăn mặt của tôi."},{"type":"simple","zh":"洗完澡以后，他用毛巾擦了擦头发。","pinyin":"Xǐwán zǎo yǐhòu, tā yòng máojīn cāle cā tóufa.","vi":"Tắm xong, anh ấy lấy khăn lau tóc."},{"type":"compound","zh":"出去旅游的时候，虽然酒店里有毛巾，但是我还是习惯带自己的。","pinyin":"Chūqù lǚyóu de shíhou, suīrán jiǔdiàn li yǒu máojīn, dànshì wǒ háishi xíguàn dài zìjǐ de.","vi":"Khi đi du lịch, tuy khách sạn có khăn nhưng tôi vẫn quen mang khăn của mình."}],"related":[{"hanzi":"围巾","pinyin":"wéijīn","vi":"Khăn quàng cổ"},{"hanzi":"浴巾","pinyin":"yùjīn","vi":"Khăn tắm"},{"hanzi":"牙膏","pinyin":"yágāo","vi":"Kem đánh răng"},{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"Tắm"},{"hanzi":"擦","pinyin":"cā","vi":"Lau"}]},{"id":"美丽","hanzi":"美丽","pinyin":"měilì","meaning_vi":"xinh đẹp, đẹp","explanation":"美 (đẹp) + 丽 (đẹp đẽ). Trang trọng hơn 漂亮, hay dùng trong văn viết để tả phong cảnh, con người: 美丽的城市.","hsk_level":3,"tags":["tinh-tu"],"image":"🌸","examples":[{"type":"basic","zh":"这里的风景很美丽。","pinyin":"Zhèlǐ de fēngjǐng hěn měilì.","vi":"Phong cảnh ở đây rất đẹp."},{"type":"simple","zh":"杭州是一个非常美丽的城市，每年都有很多人去旅游。","pinyin":"Hángzhōu shì yí gè fēicháng měilì de chéngshì, měi nián dōu yǒu hěn duō rén qù lǚyóu.","vi":"Hàng Châu là một thành phố vô cùng xinh đẹp, năm nào cũng có rất nhiều người đến du lịch."},{"type":"compound","zh":"她不但美丽，而且很善良，所以大家都喜欢跟她做朋友。","pinyin":"Tā búdàn měilì, érqiě hěn shànliáng, suǒyǐ dàjiā dōu xǐhuan gēn tā zuò péngyou.","vi":"Cô ấy không những xinh đẹp mà còn rất hiền lành, vì vậy mọi người đều thích kết bạn với cô ấy."}],"related":[{"hanzi":"美","pinyin":"měi","vi":"Đẹp"},{"hanzi":"漂亮","pinyin":"piàoliang","vi":"Xinh đẹp"},{"hanzi":"好看","pinyin":"hǎokàn","vi":"Đẹp, dễ nhìn"},{"hanzi":"丑","pinyin":"chǒu","vi":"Xấu"},{"hanzi":"风景","pinyin":"fēngjǐng","vi":"Phong cảnh"}],"traditional":"美麗"},{"id":"梦","hanzi":"梦","pinyin":"mèng","meaning_vi":"giấc mơ; mơ","explanation":"Làm danh từ: 做梦 (nằm mơ), 一个梦 (một giấc mơ); làm động từ: 梦见 (mơ thấy). 梦想 là ước mơ.","hsk_level":3,"tags":["danh-tu","sinh-hoat"],"image":"💭","examples":[{"type":"basic","zh":"祝你做个好梦！","pinyin":"Zhù nǐ zuò ge hǎo mèng!","vi":"Chúc bạn có một giấc mơ đẹp!"},{"type":"simple","zh":"我常常梦见自己回到小时候的家。","pinyin":"Wǒ chángcháng mèngjiàn zìjǐ huídào xiǎoshíhou de jiā.","vi":"Tôi thường mơ thấy mình trở về ngôi nhà hồi nhỏ."},{"type":"compound","zh":"因为昨天晚上做了一个很可怕的梦，所以我醒了以后再也不敢睡了。","pinyin":"Yīnwèi zuótiān wǎnshang zuòle yí gè hěn kěpà de mèng, suǒyǐ wǒ xǐngle yǐhòu zài yě bù gǎn shuì le.","vi":"Vì tối qua mơ một giấc mơ rất đáng sợ nên sau khi tỉnh dậy tôi không dám ngủ lại nữa."}],"related":[{"hanzi":"做梦","pinyin":"zuòmèng","vi":"Nằm mơ"},{"hanzi":"梦想","pinyin":"mèngxiǎng","vi":"Ước mơ"},{"hanzi":"梦见","pinyin":"mèngjiàn","vi":"Mơ thấy"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Ngủ"},{"hanzi":"醒","pinyin":"xǐng","vi":"Tỉnh dậy"}],"traditional":"夢"},{"id":"密码","hanzi":"密码","pinyin":"mìmǎ","meaning_vi":"mật khẩu, mật mã","explanation":"密 (bí mật) + 码 (mã số) → mã bí mật. Dùng cho mật khẩu tài khoản, mã PIN thẻ ngân hàng.","hsk_level":3,"tags":["danh-tu","cong-nghe"],"image":"🔐","examples":[{"type":"basic","zh":"我忘记密码了。","pinyin":"Wǒ wàngjì mìmǎ le.","vi":"Tôi quên mật khẩu rồi."},{"type":"simple","zh":"你的密码太简单了，最好换一个复杂一点的。","pinyin":"Nǐ de mìmǎ tài jiǎndān le, zuìhǎo huàn yí gè fùzá yìdiǎn de.","vi":"Mật khẩu của bạn đơn giản quá, tốt nhất nên đổi cái phức tạp hơn một chút."},{"type":"compound","zh":"如果你连续三次输错密码，银行卡就会被锁上。","pinyin":"Rúguǒ nǐ liánxù sān cì shūcuò mìmǎ, yínhángkǎ jiù huì bèi suǒshang.","vi":"Nếu bạn nhập sai mật khẩu ba lần liên tiếp thì thẻ ngân hàng sẽ bị khóa."}],"related":[{"hanzi":"秘密","pinyin":"mìmì","vi":"Bí mật"},{"hanzi":"号码","pinyin":"hàomǎ","vi":"Số"},{"hanzi":"输入","pinyin":"shūrù","vi":"Nhập"},{"hanzi":"手机","pinyin":"shǒujī","vi":"Điện thoại"},{"hanzi":"网站","pinyin":"wǎngzhàn","vi":"Trang web"}],"traditional":"密碼"},{"id":"难受","hanzi":"难受","pinyin":"nánshòu","meaning_vi":"khó chịu; buồn","explanation":"难 (khó) + 受 (chịu) → khó chịu. Dùng cho cả cơ thể (胃很难受) lẫn tâm trạng (心里难受 = trong lòng buồn).","hsk_level":3,"tags":["tinh-tu","suc-khoe"],"image":"😣","examples":[{"type":"basic","zh":"我肚子很难受。","pinyin":"Wǒ dùzi hěn nánshòu.","vi":"Bụng tôi rất khó chịu."},{"type":"simple","zh":"听到这个消息以后，她心里非常难受。","pinyin":"Tīngdào zhège xiāoxi yǐhòu, tā xīnli fēicháng nánshòu.","vi":"Sau khi nghe tin này, trong lòng cô ấy vô cùng buồn."},{"type":"compound","zh":"因为昨天晚上吃了太多辣的东西，所以他今天胃一直很难受。","pinyin":"Yīnwèi zuótiān wǎnshang chīle tài duō là de dōngxi, suǒyǐ tā jīntiān wèi yìzhí hěn nánshòu.","vi":"Vì tối qua ăn quá nhiều đồ cay nên hôm nay dạ dày anh ấy cứ khó chịu mãi."}],"related":[{"hanzi":"难过","pinyin":"nánguò","vi":"Buồn"},{"hanzi":"舒服","pinyin":"shūfu","vi":"Dễ chịu"},{"hanzi":"疼","pinyin":"téng","vi":"Đau"},{"hanzi":"受不了","pinyin":"shòubuliǎo","vi":"Không chịu nổi"},{"hanzi":"伤心","pinyin":"shāngxīn","vi":"Đau lòng"}],"traditional":"難受"},{"id":"内","hanzi":"内","pinyin":"nèi","meaning_vi":"trong, bên trong","explanation":"Mang sắc thái văn viết, nghĩa như 里: 室内 (trong phòng), 国内 (trong nước), 三天内 (trong vòng ba ngày). Trái nghĩa với 外.","hsk_level":3,"tags":["danh-tu","phuong-huong"],"image":"📦","examples":[{"type":"basic","zh":"室内不能抽烟。","pinyin":"Shìnèi bù néng chōuyān.","vi":"Trong phòng không được hút thuốc."},{"type":"simple","zh":"这个工作需要在三天内完成。","pinyin":"Zhège gōngzuò xūyào zài sān tiān nèi wánchéng.","vi":"Công việc này cần hoàn thành trong vòng ba ngày."},{"type":"compound","zh":"虽然这次只在国内旅游，但是我们一共去了五个城市。","pinyin":"Suīrán zhè cì zhǐ zài guónèi lǚyóu, dànshì wǒmen yígòng qùle wǔ gè chéngshì.","vi":"Tuy lần này chỉ du lịch trong nước nhưng chúng tôi đã đi tổng cộng năm thành phố."}],"related":[{"hanzi":"外","pinyin":"wài","vi":"Ngoài"},{"hanzi":"里","pinyin":"lǐ","vi":"Trong"},{"hanzi":"国内","pinyin":"guónèi","vi":"Trong nước"},{"hanzi":"内容","pinyin":"nèiróng","vi":"Nội dung"},{"hanzi":"室内","pinyin":"shìnèi","vi":"Trong nhà"}],"traditional":"內"},{"id":"瓶子","hanzi":"瓶子","pinyin":"píngzi","meaning_vi":"cái chai, cái lọ","explanation":"瓶 (bình, chai) + 子 (hậu tố). Khi đếm thì 瓶 làm lượng từ: 一瓶水 (một chai nước).","hsk_level":3,"tags":["danh-tu","do-vat"],"image":"🧴","examples":[{"type":"basic","zh":"瓶子里没有水了。","pinyin":"Píngzi li méiyǒu shuǐ le.","vi":"Trong chai hết nước rồi."},{"type":"simple","zh":"请把这些空瓶子放到门口的垃圾桶里。","pinyin":"Qǐng bǎ zhèxiē kōng píngzi fàngdào ménkǒu de lājītǒng li.","vi":"Làm ơn bỏ những cái chai rỗng này vào thùng rác ở cửa."},{"type":"compound","zh":"这个瓶子的盖子太紧了，我用了很大力气都打不开，你帮我试试吧。","pinyin":"Zhège píngzi de gàizi tài jǐn le, wǒ yòngle hěn dà lìqi dōu dǎ bu kāi, nǐ bāng wǒ shìshi ba.","vi":"Nắp cái chai này chặt quá, tôi dùng rất nhiều sức mà vẫn không mở được, bạn giúp tôi thử xem."}],"related":[{"hanzi":"瓶","pinyin":"píng","vi":"Chai (lượng từ)"},{"hanzi":"杯子","pinyin":"bēizi","vi":"Cái cốc"},{"hanzi":"盒子","pinyin":"hézi","vi":"Cái hộp"},{"hanzi":"塑料","pinyin":"sùliào","vi":"Nhựa"},{"hanzi":"啤酒","pinyin":"píjiǔ","vi":"Bia"}]},{"id":"请假","hanzi":"请假","pinyin":"qǐngjià","meaning_vi":"xin nghỉ, xin phép nghỉ","explanation":"Động từ ly hợp: 请 (xin) + 假 (kỳ nghỉ), có thể tách: 请了三天假. 假 ở đây đọc jià (nghỉ), khác với jiǎ (giả).","hsk_level":3,"tags":["dong-tu","cong-viec"],"image":"📝","examples":[{"type":"basic","zh":"我明天想请假。","pinyin":"Wǒ míngtiān xiǎng qǐngjià.","vi":"Ngày mai tôi muốn xin nghỉ."},{"type":"simple","zh":"小王生病了，今天没来上班，已经跟经理请假了。","pinyin":"Xiǎo Wáng shēngbìng le, jīntiān méi lái shàngbān, yǐjīng gēn jīnglǐ qǐngjià le.","vi":"Tiểu Vương bị ốm, hôm nay không đi làm, đã xin nghỉ với giám đốc rồi."},{"type":"compound","zh":"如果你明天不能来上课，就要提前跟老师请假。","pinyin":"Rúguǒ nǐ míngtiān bù néng lái shàngkè, jiù yào tíqián gēn lǎoshī qǐngjià.","vi":"Nếu ngày mai bạn không thể đến lớp thì phải xin phép nghỉ với thầy cô trước."}],"related":[{"hanzi":"放假","pinyin":"fàngjià","vi":"Được nghỉ"},{"hanzi":"休假","pinyin":"xiūjià","vi":"Nghỉ phép"},{"hanzi":"假期","pinyin":"jiàqī","vi":"Kỳ nghỉ"},{"hanzi":"上班","pinyin":"shàngbān","vi":"Đi làm"},{"hanzi":"请客","pinyin":"qǐngkè","vi":"Mời khách"}],"traditional":"請假"},{"id":"请客","hanzi":"请客","pinyin":"qǐngkè","meaning_vi":"mời khách, bao (ăn uống)","explanation":"Động từ ly hợp: 请 (mời) + 客 (khách). Hay dùng với nghĩa 'bao, trả tiền mời người khác': 今天我请客 (hôm nay tôi bao).","hsk_level":3,"tags":["dong-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"今天我请客！","pinyin":"Jīntiān wǒ qǐngkè!","vi":"Hôm nay tôi bao!"},{"type":"simple","zh":"他找到了新工作，晚上要请客吃饭。","pinyin":"Tā zhǎodàole xīn gōngzuò, wǎnshang yào qǐngkè chīfàn.","vi":"Anh ấy tìm được việc mới, tối nay sẽ đãi mọi người một bữa."},{"type":"compound","zh":"上次是你请客的，所以这次应该我来付钱。","pinyin":"Shàng cì shì nǐ qǐngkè de, suǒyǐ zhè cì yīnggāi wǒ lái fùqián.","vi":"Lần trước là bạn mời rồi, vì vậy lần này nên để tôi trả tiền."}],"related":[{"hanzi":"客人","pinyin":"kèrén","vi":"Khách"},{"hanzi":"请","pinyin":"qǐng","vi":"Mời"},{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"Mời"},{"hanzi":"付钱","pinyin":"fùqián","vi":"Trả tiền"},{"hanzi":"请假","pinyin":"qǐngjià","vi":"Xin nghỉ"}],"traditional":"請客"},{"id":"缺少","hanzi":"缺少","pinyin":"quēshǎo","meaning_vi":"thiếu","explanation":"缺 (khuyết) + 少 (ít) → thiếu; 少 đọc shǎo. Gần nghĩa 缺乏, nhưng 缺乏 hay đi với danh từ trừu tượng (经验, 信心).","hsk_level":3,"tags":["dong-tu","so-luong"],"image":"🧩","examples":[{"type":"basic","zh":"这里缺少一个字。","pinyin":"Zhèlǐ quēshǎo yí gè zì.","vi":"Chỗ này thiếu một chữ."},{"type":"simple","zh":"植物的生长不能缺少阳光和水。","pinyin":"Zhíwù de shēngzhǎng bù néng quēshǎo yángguāng hé shuǐ.","vi":"Sự sinh trưởng của thực vật không thể thiếu ánh nắng và nước."},{"type":"compound","zh":"他虽然很聪明，但是缺少工作经验，所以找工作不太容易。","pinyin":"Tā suīrán hěn cōngming, dànshì quēshǎo gōngzuò jīngyàn, suǒyǐ zhǎo gōngzuò bú tài róngyì.","vi":"Anh ấy tuy rất thông minh nhưng thiếu kinh nghiệm làm việc, vì vậy tìm việc không dễ lắm."}],"related":[{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"Khuyết điểm"},{"hanzi":"缺乏","pinyin":"quēfá","vi":"Thiếu hụt"},{"hanzi":"需要","pinyin":"xūyào","vi":"Cần"},{"hanzi":"够","pinyin":"gòu","vi":"Đủ"},{"hanzi":"少","pinyin":"shǎo","vi":"Ít"}]},{"id":"软","hanzi":"软","pinyin":"ruǎn","meaning_vi":"mềm","explanation":"Trái nghĩa với 硬 (cứng). Hay gặp: 软件 (phần mềm), 心软 (mềm lòng).","hsk_level":3,"tags":["tinh-tu"],"image":"🧸","examples":[{"type":"basic","zh":"这个面包很软。","pinyin":"Zhège miànbāo hěn ruǎn.","vi":"Cái bánh mì này rất mềm."},{"type":"simple","zh":"奶奶年纪大了，只能吃比较软的东西。","pinyin":"Nǎinai niánjì dà le, zhǐ néng chī bǐjiào ruǎn de dōngxi.","vi":"Bà đã lớn tuổi, chỉ có thể ăn những đồ tương đối mềm."},{"type":"compound","zh":"这个沙发又软又舒服，所以我一回家就喜欢躺在上面。","pinyin":"Zhège shāfā yòu ruǎn yòu shūfu, suǒyǐ wǒ yì huí jiā jiù xǐhuan tǎng zài shàngmiàn.","vi":"Cái ghế sofa này vừa mềm vừa thoải mái, nên hễ về nhà là tôi thích nằm lên đó."}],"related":[{"hanzi":"硬","pinyin":"yìng","vi":"Cứng"},{"hanzi":"软件","pinyin":"ruǎnjiàn","vi":"Phần mềm"},{"hanzi":"柔软","pinyin":"róuruǎn","vi":"Mềm mại"},{"hanzi":"心软","pinyin":"xīnruǎn","vi":"Mềm lòng"},{"hanzi":"沙发","pinyin":"shāfā","vi":"Ghế sofa"}],"traditional":"軟"},{"id":"食品","hanzi":"食品","pinyin":"shípǐn","meaning_vi":"thực phẩm","explanation":"食 (ăn) + 品 (sản phẩm) → thực phẩm, thường là đồ ăn chế biến, đóng gói để bán. Phân biệt với 食物 (thức ăn nói chung).","hsk_level":3,"tags":["danh-tu","an-uong"],"image":"🥫","examples":[{"type":"basic","zh":"超市里的食品很多。","pinyin":"Chāoshì li de shípǐn hěn duō.","vi":"Thực phẩm trong siêu thị rất nhiều."},{"type":"simple","zh":"买食品的时候，一定要看清楚生产日期。","pinyin":"Mǎi shípǐn de shíhou, yídìng yào kàn qīngchu shēngchǎn rìqī.","vi":"Khi mua thực phẩm, nhất định phải xem kỹ ngày sản xuất."},{"type":"compound","zh":"如果想保持健康，就要少吃甜的东西，多吃新鲜的食品。","pinyin":"Rúguǒ xiǎng bǎochí jiànkāng, jiù yào shǎo chī tián de dōngxi, duō chī xīnxiān de shípǐn.","vi":"Nếu muốn giữ gìn sức khỏe thì phải ăn ít đồ ngọt, ăn nhiều thực phẩm tươi."}],"related":[{"hanzi":"食物","pinyin":"shíwù","vi":"Thức ăn"},{"hanzi":"商品","pinyin":"shāngpǐn","vi":"Hàng hóa"},{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"Sản phẩm"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"Đồ uống"},{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"}]},{"id":"算","hanzi":"算","pinyin":"suàn","meaning_vi":"tính, tính toán; coi như, được xem là","explanation":"Nghĩa gốc là tính toán (算钱, 计算). Còn có nghĩa 'coi như, được xem là' (不算冷 = không tính là lạnh); 算了 nghĩa là 'thôi, bỏ đi'.","hsk_level":3,"tags":["dong-tu","so-luong"],"image":"🧮","examples":[{"type":"basic","zh":"你算一下多少钱。","pinyin":"Nǐ suàn yíxià duōshao qián.","vi":"Bạn tính xem bao nhiêu tiền."},{"type":"simple","zh":"今天的天气不算太冷，你不用穿那么多衣服。","pinyin":"Jīntiān de tiānqì bú suàn tài lěng, nǐ búyòng chuān nàme duō yīfu.","vi":"Thời tiết hôm nay không tính là quá lạnh, bạn không cần mặc nhiều áo như vậy."},{"type":"compound","zh":"如果他不想去就算了，我们俩自己去也可以。","pinyin":"Rúguǒ tā bù xiǎng qù jiù suànle, wǒmen liǎ zìjǐ qù yě kěyǐ.","vi":"Nếu anh ấy không muốn đi thì thôi, hai chúng ta tự đi cũng được."}],"related":[{"hanzi":"计算","pinyin":"jìsuàn","vi":"Tính toán"},{"hanzi":"打算","pinyin":"dǎsuàn","vi":"Dự định"},{"hanzi":"算了","pinyin":"suànle","vi":"Thôi, bỏ đi"},{"hanzi":"就算","pinyin":"jiùsuàn","vi":"Cho dù"},{"hanzi":"数","pinyin":"shǔ","vi":"Đếm"}]},{"id":"停止","hanzi":"停止","pinyin":"tíngzhǐ","meaning_vi":"dừng lại, ngừng","explanation":"停 (dừng) + 止 (ngừng). Trang trọng hơn 停, thường dùng với hành động đang diễn ra: 停止工作, 停止抽烟.","hsk_level":3,"tags":["dong-tu"],"image":"⏹️","examples":[{"type":"basic","zh":"请停止说话。","pinyin":"Qǐng tíngzhǐ shuōhuà.","vi":"Xin hãy ngừng nói chuyện."},{"type":"simple","zh":"下大雨了，足球比赛只好停止。","pinyin":"Xià dàyǔ le, zúqiú bǐsài zhǐhǎo tíngzhǐ.","vi":"Trời mưa to, trận bóng đá đành phải dừng lại."},{"type":"compound","zh":"虽然医生让他停止抽烟，但是他还是每天抽好几支。","pinyin":"Suīrán yīshēng ràng tā tíngzhǐ chōuyān, dànshì tā háishi měitiān chōu hǎojǐ zhī.","vi":"Tuy bác sĩ bảo anh ấy ngừng hút thuốc nhưng ngày nào anh ấy vẫn hút mấy điếu."}],"related":[{"hanzi":"停","pinyin":"tíng","vi":"Dừng"},{"hanzi":"开始","pinyin":"kāishǐ","vi":"Bắt đầu"},{"hanzi":"继续","pinyin":"jìxù","vi":"Tiếp tục"},{"hanzi":"结束","pinyin":"jiéshù","vi":"Kết thúc"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"Cấm"}]},{"id":"洗衣机","hanzi":"洗衣机","pinyin":"xǐyījī","meaning_vi":"máy giặt","explanation":"洗 (giặt) + 衣 (quần áo) + 机 (máy) → máy giặt quần áo. Cách ghép giống 照相机 (máy ảnh).","hsk_level":3,"tags":["danh-tu","nha-cua"],"image":"🧺","examples":[{"type":"basic","zh":"我家有一台洗衣机。","pinyin":"Wǒ jiā yǒu yì tái xǐyījī.","vi":"Nhà tôi có một chiếc máy giặt."},{"type":"simple","zh":"你把脏衣服放进洗衣机里吧。","pinyin":"Nǐ bǎ zāng yīfu fàngjìn xǐyījī li ba.","vi":"Bạn bỏ quần áo bẩn vào máy giặt đi."},{"type":"compound","zh":"因为宿舍的洗衣机坏了，所以这几天我们只能自己用手洗衣服。","pinyin":"Yīnwèi sùshè de xǐyījī huài le, suǒyǐ zhè jǐ tiān wǒmen zhǐ néng zìjǐ yòng shǒu xǐ yīfu.","vi":"Vì máy giặt ở ký túc xá bị hỏng nên mấy hôm nay chúng tôi chỉ có thể tự giặt quần áo bằng tay."}],"related":[{"hanzi":"洗","pinyin":"xǐ","vi":"Giặt, rửa"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"冰箱","pinyin":"bīngxiāng","vi":"Tủ lạnh"},{"hanzi":"空调","pinyin":"kōngtiáo","vi":"Điều hòa"},{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"Tắm"}],"traditional":"洗衣機"},{"id":"现代","hanzi":"现代","pinyin":"xiàndài","meaning_vi":"hiện đại, thời hiện đại","explanation":"现 (hiện tại) + 代 (thời đại). Hay đứng trước danh từ: 现代社会, 现代音乐; 现代化 là hiện đại hóa. Đối lập với 古代 (cổ đại).","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"🏙️","examples":[{"type":"basic","zh":"我喜欢现代音乐。","pinyin":"Wǒ xǐhuan xiàndài yīnyuè.","vi":"Tôi thích âm nhạc hiện đại."},{"type":"simple","zh":"现代人的生活越来越离不开手机了。","pinyin":"Xiàndài rén de shēnghuó yuèláiyuè lí bu kāi shǒujī le.","vi":"Cuộc sống của người hiện đại ngày càng không thể thiếu điện thoại."},{"type":"compound","zh":"这个城市虽然有很多现代的建筑，但是也有不少历史很长的老房子。","pinyin":"Zhège chéngshì suīrán yǒu hěn duō xiàndài de jiànzhù, dànshì yě yǒu bù shǎo lìshǐ hěn cháng de lǎo fángzi.","vi":"Thành phố này tuy có nhiều công trình hiện đại nhưng cũng có không ít ngôi nhà cũ có lịch sử lâu đời."}],"related":[{"hanzi":"古代","pinyin":"gǔdài","vi":"Cổ đại"},{"hanzi":"近代","pinyin":"jìndài","vi":"Cận đại"},{"hanzi":"时代","pinyin":"shídài","vi":"Thời đại"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"现代化","pinyin":"xiàndàihuà","vi":"Hiện đại hóa"}],"traditional":"現代"},{"id":"限制","hanzi":"限制","pinyin":"xiànzhì","meaning_vi":"hạn chế, giới hạn","explanation":"限 (giới hạn) + 制 (khống chế). Vừa là động từ (限制时间 = giới hạn thời gian) vừa là danh từ (有很多限制 = có nhiều hạn chế).","hsk_level":3,"tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"这次考试有时间限制。","pinyin":"Zhè cì kǎoshì yǒu shíjiān xiànzhì.","vi":"Bài thi lần này có giới hạn thời gian."},{"type":"simple","zh":"妈妈限制我每天只能玩一个小时手机。","pinyin":"Māma xiànzhì wǒ měitiān zhǐ néng wán yí gè xiǎoshí shǒujī.","vi":"Mẹ hạn chế tôi mỗi ngày chỉ được chơi điện thoại một tiếng."},{"type":"compound","zh":"因为这条路旁边有一所小学，所以这里限制开车的速度，每小时不能超过三十公里。","pinyin":"Yīnwèi zhè tiáo lù pángbiān yǒu yì suǒ xiǎoxué, suǒyǐ zhèlǐ xiànzhì kāichē de sùdù, měi xiǎoshí bù néng chāoguò sānshí gōnglǐ.","vi":"Vì bên cạnh con đường này có một trường tiểu học nên ở đây hạn chế tốc độ lái xe, mỗi giờ không được vượt quá ba mươi ki-lô-mét."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"Kiểm soát"},{"hanzi":"规定","pinyin":"guīdìng","vi":"Quy định"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"Cấm"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"Cho phép"},{"hanzi":"自由","pinyin":"zìyóu","vi":"Tự do"}]},{"id":"信任","hanzi":"信任","pinyin":"xìnrèn","meaning_vi":"tin tưởng, tín nhiệm","explanation":"信 (tin) + 任 (giao phó). Mạnh hơn 相信: không chỉ tin lời mà còn tin cậy để giao việc. Cũng làm danh từ: 得到信任 (được tin tưởng).","hsk_level":3,"tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"我很信任他。","pinyin":"Wǒ hěn xìnrèn tā.","vi":"Tôi rất tin tưởng anh ấy."},{"type":"simple","zh":"经理很信任小李，把重要的工作都交给他做。","pinyin":"Jīnglǐ hěn xìnrèn Xiǎo Lǐ, bǎ zhòngyào de gōngzuò dōu jiāogěi tā zuò.","vi":"Giám đốc rất tin tưởng Tiểu Lý, giao những việc quan trọng cho anh ấy làm."},{"type":"compound","zh":"朋友之间如果没有信任，就很难长时间做朋友。","pinyin":"Péngyou zhījiān rúguǒ méiyǒu xìnrèn, jiù hěn nán cháng shíjiān zuò péngyou.","vi":"Giữa bạn bè nếu không có sự tin tưởng thì rất khó làm bạn lâu dài."}],"related":[{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin"},{"hanzi":"信心","pinyin":"xìnxīn","vi":"Lòng tin"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"Nghi ngờ"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"Thành thật"},{"hanzi":"信用","pinyin":"xìnyòng","vi":"Uy tín"}]},{"id":"信用卡","hanzi":"信用卡","pinyin":"xìnyòngkǎ","meaning_vi":"thẻ tín dụng","explanation":"信用 (tín dụng, uy tín) + 卡 (thẻ). Phân biệt với 银行卡 (thẻ ngân hàng nói chung).","hsk_level":3,"tags":["danh-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"可以用信用卡吗？","pinyin":"Kěyǐ yòng xìnyòngkǎ ma?","vi":"Có thể dùng thẻ tín dụng không?"},{"type":"simple","zh":"我出国旅游的时候一般用信用卡付钱。","pinyin":"Wǒ chūguó lǚyóu de shíhou yìbān yòng xìnyòngkǎ fùqián.","vi":"Khi đi du lịch nước ngoài tôi thường dùng thẻ tín dụng để trả tiền."},{"type":"compound","zh":"如果你的信用卡丢了，就要马上给银行打电话。","pinyin":"Rúguǒ nǐ de xìnyòngkǎ diū le, jiù yào mǎshàng gěi yínháng dǎ diànhuà.","vi":"Nếu thẻ tín dụng của bạn bị mất thì phải gọi điện cho ngân hàng ngay."}],"related":[{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"},{"hanzi":"现金","pinyin":"xiànjīn","vi":"Tiền mặt"},{"hanzi":"付款","pinyin":"fùkuǎn","vi":"Thanh toán"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"Mật khẩu"},{"hanzi":"信用","pinyin":"xìnyòng","vi":"Tín dụng, uy tín"}]},{"id":"修","hanzi":"修","pinyin":"xiū","meaning_vi":"sửa, sửa chữa; xây (đường, cầu)","explanation":"Nghĩa thường gặp là sửa (修电脑, 修车), giống 修理. Còn có nghĩa xây dựng: 修路 (làm đường), 修桥 (xây cầu).","hsk_level":3,"tags":["dong-tu"],"image":"🔧","examples":[{"type":"basic","zh":"他会修电脑。","pinyin":"Tā huì xiū diànnǎo.","vi":"Anh ấy biết sửa máy tính."},{"type":"simple","zh":"我的自行车坏了，明天要拿去修一下。","pinyin":"Wǒ de zìxíngchē huài le, míngtiān yào ná qù xiū yíxià.","vi":"Xe đạp của tôi hỏng rồi, ngày mai phải mang đi sửa."},{"type":"compound","zh":"因为这条路正在修，所以我们只好从另外一条路走。","pinyin":"Yīnwèi zhè tiáo lù zhèngzài xiū, suǒyǐ wǒmen zhǐhǎo cóng lìngwài yì tiáo lù zǒu.","vi":"Vì con đường này đang sửa nên chúng tôi đành đi đường khác."}],"related":[{"hanzi":"修理","pinyin":"xiūlǐ","vi":"Sửa chữa"},{"hanzi":"维修","pinyin":"wéixiū","vi":"Bảo trì, sửa chữa"},{"hanzi":"修改","pinyin":"xiūgǎi","vi":"Sửa đổi"},{"hanzi":"坏","pinyin":"huài","vi":"Hỏng"},{"hanzi":"工具","pinyin":"gōngjù","vi":"Dụng cụ"}]},{"id":"血","hanzi":"血","pinyin":"xuè","meaning_vi":"máu","explanation":"Đọc xuè trong từ ghép và văn viết (血液, 流血); trong khẩu ngữ hằng ngày cũng hay đọc xiě (出血了).","hsk_level":3,"tags":["danh-tu","co-the"],"image":"🩸","examples":[{"type":"basic","zh":"他的鼻子流血了。","pinyin":"Tā de bízi liúxuè le.","vi":"Mũi anh ấy chảy máu rồi."},{"type":"simple","zh":"早上去医院检查身体的时候，医生给我抽了一点血。","pinyin":"Zǎoshang qù yīyuàn jiǎnchá shēntǐ de shíhou, yīshēng gěi wǒ chōule yìdiǎn xuè.","vi":"Sáng nay khi đến bệnh viện kiểm tra sức khỏe, bác sĩ đã lấy của tôi một ít máu."},{"type":"compound","zh":"如果你的手出血了，就应该先用干净的水洗一洗，然后再去看医生。","pinyin":"Rúguǒ nǐ de shǒu chūxuè le, jiù yīnggāi xiān yòng gānjìng de shuǐ xǐ yi xǐ, ránhòu zài qù kàn yīshēng.","vi":"Nếu tay bạn bị chảy máu thì nên rửa bằng nước sạch trước rồi mới đi khám bác sĩ."}],"related":[{"hanzi":"流血","pinyin":"liúxuè","vi":"Chảy máu"},{"hanzi":"血液","pinyin":"xuèyè","vi":"Máu (văn viết)"},{"hanzi":"心脏","pinyin":"xīnzàng","vi":"Tim"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"Bị thương"},{"hanzi":"医生","pinyin":"yīshēng","vi":"Bác sĩ"}]},{"id":"亿","hanzi":"亿","pinyin":"yì","meaning_vi":"trăm triệu","explanation":"1 亿 = 10.000 万 = 100.000.000. Người Trung Quốc đếm số lớn theo 万 (vạn) và 亿 (ức): 十亿 = một tỷ.","hsk_level":3,"tags":["so-dem","so-luong"],"image":"🔢","examples":[{"type":"basic","zh":"中国有十四亿人。","pinyin":"Zhōngguó yǒu shísì yì rén.","vi":"Trung Quốc có một tỷ bốn trăm triệu người."},{"type":"simple","zh":"这家公司去年一共赚了两亿多元。","pinyin":"Zhè jiā gōngsī qùnián yígòng zhuànle liǎng yì duō yuán.","vi":"Năm ngoái công ty này kiếm được tổng cộng hơn hai trăm triệu tệ."},{"type":"compound","zh":"虽然地球上有八十多亿人，但是找到一个真正懂你的朋友并不容易。","pinyin":"Suīrán dìqiú shang yǒu bāshí duō yì rén, dànshì zhǎodào yí gè zhēnzhèng dǒng nǐ de péngyou bìng bù róngyì.","vi":"Tuy trên Trái Đất có hơn tám tỷ người, nhưng tìm được một người bạn thật sự hiểu mình không hề dễ."}],"related":[{"hanzi":"万","pinyin":"wàn","vi":"Vạn, mười nghìn"},{"hanzi":"千","pinyin":"qiān","vi":"Nghìn"},{"hanzi":"百","pinyin":"bǎi","vi":"Trăm"},{"hanzi":"数字","pinyin":"shùzì","vi":"Chữ số"},{"hanzi":"人口","pinyin":"rénkǒu","vi":"Dân số"}],"traditional":"億"},{"id":"硬","hanzi":"硬","pinyin":"yìng","meaning_vi":"cứng","explanation":"Bộ 石 (đá) → cứng như đá. Trái nghĩa với 软 (mềm). Hay gặp: 硬币 (đồng xu), 硬盘 (ổ cứng).","hsk_level":3,"tags":["tinh-tu"],"image":"🪨","examples":[{"type":"basic","zh":"这个面包太硬了。","pinyin":"Zhège miànbāo tài yìng le.","vi":"Cái bánh mì này cứng quá."},{"type":"simple","zh":"这张床太硬了，我昨天晚上一直睡不着。","pinyin":"Zhè zhāng chuáng tài yìng le, wǒ zuótiān wǎnshang yìzhí shuì bu zháo.","vi":"Cái giường này cứng quá, tối qua tôi mãi không ngủ được."},{"type":"compound","zh":"牙不好的老人最好别吃太硬的东西，因为很容易把牙弄坏。","pinyin":"Yá bù hǎo de lǎorén zuìhǎo bié chī tài yìng de dōngxi, yīnwèi hěn róngyì bǎ yá nònghuài.","vi":"Người già răng yếu tốt nhất đừng ăn đồ quá cứng, vì rất dễ làm hỏng răng."}],"related":[{"hanzi":"软","pinyin":"ruǎn","vi":"Mềm"},{"hanzi":"硬币","pinyin":"yìngbì","vi":"Đồng xu"},{"hanzi":"石头","pinyin":"shítou","vi":"Hòn đá"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"Kiên cường"},{"hanzi":"结实","pinyin":"jiēshi","vi":"Chắc chắn"}]},{"id":"圆","hanzi":"圆","pinyin":"yuán","meaning_vi":"tròn; hình tròn","explanation":"Khung 囗 bao quanh 员 (gợi âm yuán) → hình tròn. Hay gặp: 圆形 (hình tròn), 团圆 (đoàn viên).","hsk_level":3,"tags":["tinh-tu"],"image":"⭕","examples":[{"type":"basic","zh":"这个盘子是圆的。","pinyin":"Zhège pánzi shì yuán de.","vi":"Cái đĩa này hình tròn."},{"type":"simple","zh":"我们家吃饭用的是一张圆桌子。","pinyin":"Wǒmen jiā chīfàn yòng de shì yì zhāng yuán zhuōzi.","vi":"Nhà chúng tôi ăn cơm bằng một cái bàn tròn."},{"type":"compound","zh":"中秋节的晚上，月亮又大又圆，一家人一边吃月饼，一边看月亮。","pinyin":"Zhōngqiūjié de wǎnshang, yuèliang yòu dà yòu yuán, yì jiā rén yìbiān chī yuèbǐng, yìbiān kàn yuèliang.","vi":"Đêm Trung thu, trăng vừa to vừa tròn, cả nhà vừa ăn bánh trung thu vừa ngắm trăng."}],"related":[{"hanzi":"圆形","pinyin":"yuánxíng","vi":"Hình tròn"},{"hanzi":"方","pinyin":"fāng","vi":"Vuông"},{"hanzi":"团圆","pinyin":"tuányuán","vi":"Đoàn viên"},{"hanzi":"圆珠笔","pinyin":"yuánzhūbǐ","vi":"Bút bi"},{"hanzi":"月亮","pinyin":"yuèliang","vi":"Mặt trăng"}],"traditional":"圓"},{"id":"增长","hanzi":"增长","pinyin":"zēngzhǎng","meaning_vi":"tăng trưởng, tăng lên","explanation":"增 (tăng) + 长 (lớn lên). 长 ở đây đọc zhǎng (lớn), không phải cháng (dài). Hay dùng cho số liệu, kinh tế, kiến thức: 经济增长, 增长知识.","hsk_level":3,"tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"他的收入增长了很多。","pinyin":"Tā de shōurù zēngzhǎngle hěn duō.","vi":"Thu nhập của anh ấy đã tăng lên rất nhiều."},{"type":"simple","zh":"这几年，来这个城市旅游的人每年都在增长。","pinyin":"Zhè jǐ nián, lái zhège chéngshì lǚyóu de rén měi nián dōu zài zēngzhǎng.","vi":"Mấy năm nay, số người đến du lịch thành phố này năm nào cũng tăng."},{"type":"compound","zh":"多读书不但能增长知识，而且能让人变得更有耐心。","pinyin":"Duō dú shū búdàn néng zēngzhǎng zhīshi, érqiě néng ràng rén biàn de gèng yǒu nàixīn.","vi":"Đọc nhiều sách không những có thể tăng thêm kiến thức mà còn khiến người ta trở nên kiên nhẫn hơn."}],"related":[{"hanzi":"增加","pinyin":"zēngjiā","vi":"Tăng thêm"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"Giảm bớt"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"},{"hanzi":"成长","pinyin":"chéngzhǎng","vi":"Trưởng thành"},{"hanzi":"经济","pinyin":"jīngjì","vi":"Kinh tế"}],"traditional":"增長"},{"id":"整齐","hanzi":"整齐","pinyin":"zhěngqí","meaning_vi":"ngăn nắp, gọn gàng, ngay ngắn","explanation":"整 (chỉnh tề) + 齐 (đều) → ngay ngắn, đều đặn. Có thể lặp thành 整整齐齐 để nhấn mạnh.","hsk_level":3,"tags":["tinh-tu","sinh-hoat"],"image":"📚","examples":[{"type":"basic","zh":"他的房间很整齐。","pinyin":"Tā de fángjiān hěn zhěngqí.","vi":"Phòng của anh ấy rất ngăn nắp."},{"type":"simple","zh":"妈妈每天都把桌子上的东西放得很整齐。","pinyin":"Māma měitiān dōu bǎ zhuōzi shang de dōngxi fàng de hěn zhěngqí.","vi":"Ngày nào mẹ cũng xếp đồ trên bàn rất gọn gàng."},{"type":"compound","zh":"因为教室里的桌子和椅子都摆得很整齐，所以看起来非常舒服。","pinyin":"Yīnwèi jiàoshì li de zhuōzi hé yǐzi dōu bǎi de hěn zhěngqí, suǒyǐ kàn qǐlai fēicháng shūfu.","vi":"Vì bàn ghế trong lớp đều được kê rất ngay ngắn nên nhìn rất dễ chịu."}],"related":[{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"乱","pinyin":"luàn","vi":"Lộn xộn"},{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"Sắp xếp"},{"hanzi":"收拾","pinyin":"shōushi","vi":"Dọn dẹp"},{"hanzi":"齐","pinyin":"qí","vi":"Đều, đủ"}],"traditional":"整齊"},{"id":"制造","hanzi":"制造","pinyin":"zhìzào","meaning_vi":"chế tạo, sản xuất; gây ra","explanation":"制 (chế) + 造 (tạo). Ngoài nghĩa sản xuất (制造汽车, 中国制造), còn có nghĩa 'gây ra' điều không tốt: 制造麻烦 (gây phiền phức).","hsk_level":3,"tags":["dong-tu","cong-nghe"],"image":"🏭","examples":[{"type":"basic","zh":"这些手机是中国制造的。","pinyin":"Zhèxiē shǒujī shì Zhōngguó zhìzào de.","vi":"Những chiếc điện thoại này được sản xuất tại Trung Quốc."},{"type":"simple","zh":"这家工厂主要制造汽车和自行车。","pinyin":"Zhè jiā gōngchǎng zhǔyào zhìzào qìchē hé zìxíngchē.","vi":"Nhà máy này chủ yếu sản xuất ô tô và xe đạp."},{"type":"compound","zh":"他上课总是说话，不但影响了别人，而且给老师制造了很多麻烦。","pinyin":"Tā shàngkè zǒngshì shuōhuà, búdàn yǐngxiǎngle biérén, érqiě gěi lǎoshī zhìzàole hěn duō máfan.","vi":"Cậu ấy trong giờ học cứ nói chuyện, không những ảnh hưởng đến người khác mà còn gây ra nhiều phiền phức cho thầy cô."}],"related":[{"hanzi":"生产","pinyin":"shēngchǎn","vi":"Sản xuất"},{"hanzi":"创造","pinyin":"chuàngzào","vi":"Sáng tạo"},{"hanzi":"工厂","pinyin":"gōngchǎng","vi":"Nhà máy"},{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"Sản phẩm"},{"hanzi":"建造","pinyin":"jiànzào","vi":"Xây dựng"}],"traditional":"製造"},{"id":"猪","hanzi":"猪","pinyin":"zhū","meaning_vi":"con lợn, con heo","explanation":"Bộ 犭(thú) + 者 (gợi âm). Thịt lợn là 猪肉; khi đếm dùng 一头猪 hoặc 一只猪.","hsk_level":3,"tags":["danh-tu","dong-vat"],"image":"🐷","examples":[{"type":"basic","zh":"这只小猪很可爱。","pinyin":"Zhè zhī xiǎo zhū hěn kě'ài.","vi":"Chú lợn con này rất đáng yêu."},{"type":"simple","zh":"我爷爷在农村养了十几头猪。","pinyin":"Wǒ yéye zài nóngcūn yǎngle shí jǐ tóu zhū.","vi":"Ông nội tôi nuôi mười mấy con lợn ở quê."},{"type":"compound","zh":"我不喜欢吃牛肉，所以每次去饭馆都点猪肉做的菜。","pinyin":"Wǒ bù xǐhuan chī niúròu, suǒyǐ měi cì qù fànguǎn dōu diǎn zhūròu zuò de cài.","vi":"Tôi không thích ăn thịt bò, nên mỗi lần đi quán ăn đều gọi món làm từ thịt lợn."}],"related":[{"hanzi":"猪肉","pinyin":"zhūròu","vi":"Thịt lợn"},{"hanzi":"牛","pinyin":"niú","vi":"Con bò"},{"hanzi":"羊","pinyin":"yáng","vi":"Con cừu"},{"hanzi":"狗","pinyin":"gǒu","vi":"Con chó"},{"hanzi":"动物","pinyin":"dòngwù","vi":"Động vật"}],"traditional":"豬"},{"id":"逐渐","hanzi":"逐渐","pinyin":"zhújiàn","meaning_vi":"dần dần","explanation":"逐 (lần lượt) + 渐 (dần). Chỉ sự thay đổi diễn ra từ từ, tự nhiên; gần nghĩa 渐渐 nhưng trang trọng hơn.","hsk_level":3,"tags":["pho-tu","thoi-gian"],"image":"🌱","examples":[{"type":"basic","zh":"天气逐渐变冷了。","pinyin":"Tiānqì zhújiàn biàn lěng le.","vi":"Thời tiết dần dần trở lạnh."},{"type":"simple","zh":"来中国半年以后，我逐渐习惯了这里的生活。","pinyin":"Lái Zhōngguó bàn nián yǐhòu, wǒ zhújiàn xíguànle zhèlǐ de shēnghuó.","vi":"Sau nửa năm đến Trung Quốc, tôi dần dần quen với cuộc sống ở đây."},{"type":"compound","zh":"随着年龄的增长，他的脾气逐渐变好了，也不像以前那么容易生气了。","pinyin":"Suízhe niánlíng de zēngzhǎng, tā de píqi zhújiàn biàn hǎo le, yě bú xiàng yǐqián nàme róngyì shēngqì le.","vi":"Cùng với tuổi tác tăng lên, tính khí của anh ấy dần dần tốt hơn, cũng không dễ nổi giận như trước nữa."}],"related":[{"hanzi":"渐渐","pinyin":"jiànjiàn","vi":"Dần dần"},{"hanzi":"慢慢","pinyin":"mànmàn","vi":"Từ từ"},{"hanzi":"逐步","pinyin":"zhúbù","vi":"Từng bước"},{"hanzi":"突然","pinyin":"tūrán","vi":"Đột nhiên"},{"hanzi":"越来越","pinyin":"yuèláiyuè","vi":"Ngày càng"}],"traditional":"逐漸"},{"id":"主动","hanzi":"主动","pinyin":"zhǔdòng","meaning_vi":"chủ động","explanation":"主 (chủ) + 动 (động) → tự mình hành động, không đợi người khác bảo. Trái nghĩa với 被动 (bị động).","hsk_level":3,"tags":["tinh-tu","con-nguoi"],"image":"🙋","examples":[{"type":"basic","zh":"他主动帮我拿行李。","pinyin":"Tā zhǔdòng bāng wǒ ná xíngli.","vi":"Anh ấy chủ động giúp tôi xách hành lý."},{"type":"simple","zh":"在课上，老师希望大家多主动回答问题。","pinyin":"Zài kè shang, lǎoshī xīwàng dàjiā duō zhǔdòng huídá wèntí.","vi":"Trong giờ học, thầy cô mong mọi người chủ động trả lời câu hỏi nhiều hơn."},{"type":"compound","zh":"如果你喜欢她，就应该主动跟她说，不要总是等她先开口。","pinyin":"Rúguǒ nǐ xǐhuan tā, jiù yīnggāi zhǔdòng gēn tā shuō, búyào zǒngshì děng tā xiān kāikǒu.","vi":"Nếu bạn thích cô ấy thì nên chủ động nói với cô ấy, đừng lúc nào cũng đợi cô ấy mở lời trước."}],"related":[{"hanzi":"被动","pinyin":"bèidòng","vi":"Bị động"},{"hanzi":"积极","pinyin":"jījí","vi":"Tích cực"},{"hanzi":"主要","pinyin":"zhǔyào","vi":"Chủ yếu"},{"hanzi":"自觉","pinyin":"zìjué","vi":"Tự giác"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"主動"},{"id":"撞","hanzi":"撞","pinyin":"zhuàng","meaning_vi":"đâm, va, đụng","explanation":"Bộ 扌(tay) + 童 (gợi âm). Chỉ va chạm mạnh: 撞车 (đâm xe), 撞到 (va vào); thường mạnh hơn 碰 (chạm, va).","hsk_level":3,"tags":["dong-tu","giao-thong"],"image":"💥","examples":[{"type":"basic","zh":"小心，别撞到门！","pinyin":"Xiǎoxīn, bié zhuàngdào mén!","vi":"Cẩn thận, đừng va vào cửa!"},{"type":"simple","zh":"昨天早上，一辆汽车在路口撞到了一棵树。","pinyin":"Zuótiān zǎoshang, yí liàng qìchē zài lùkǒu zhuàngdàole yì kē shù.","vi":"Sáng hôm qua, một chiếc ô tô đã đâm vào một cái cây ở ngã tư."},{"type":"compound","zh":"他一边走路一边看手机，结果撞到了前面的人。","pinyin":"Tā yìbiān zǒulù yìbiān kàn shǒujī, jiéguǒ zhuàngdàole qiánmiàn de rén.","vi":"Anh ấy vừa đi vừa xem điện thoại, kết quả là va phải người phía trước."}],"related":[{"hanzi":"碰","pinyin":"pèng","vi":"Chạm, va"},{"hanzi":"撞车","pinyin":"zhuàngchē","vi":"Đâm xe"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"Cẩn thận"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"Bị thương"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"Giao thông"}]},{"id":"组成","hanzi":"组成","pinyin":"zǔchéng","meaning_vi":"tạo thành, cấu thành","explanation":"组 (tổ, nhóm) + 成 (thành). Cấu trúc hay gặp: A 由 B 组成 (A do B tạo thành); 组成 + nhóm/đội (组成一个小组).","hsk_level":3,"tags":["dong-tu"],"image":"🧩","examples":[{"type":"basic","zh":"我们组成了一个小组。","pinyin":"Wǒmen zǔchéngle yí gè xiǎozǔ.","vi":"Chúng tôi lập thành một nhóm nhỏ."},{"type":"simple","zh":"我们班的足球队是由十一个同学组成的。","pinyin":"Wǒmen bān de zúqiúduì shì yóu shíyī gè tóngxué zǔchéng de.","vi":"Đội bóng đá của lớp chúng tôi do mười một bạn học tạo thành."},{"type":"compound","zh":"汉字一般是由几个部分组成的，如果知道每个部分的意思，就更容易记住。","pinyin":"Hànzì yìbān shì yóu jǐ gè bùfen zǔchéng de, rúguǒ zhīdào měi gè bùfen de yìsi, jiù gèng róngyì jìzhù.","vi":"Chữ Hán thường do vài bộ phận tạo thành, nếu biết ý nghĩa của từng bộ phận thì sẽ dễ nhớ hơn."}],"related":[{"hanzi":"组织","pinyin":"zǔzhī","vi":"Tổ chức"},{"hanzi":"构成","pinyin":"gòuchéng","vi":"Cấu thành"},{"hanzi":"小组","pinyin":"xiǎozǔ","vi":"Nhóm nhỏ"},{"hanzi":"成为","pinyin":"chéngwéi","vi":"Trở thành"},{"hanzi":"部分","pinyin":"bùfen","vi":"Bộ phận"}],"traditional":"組成"},{"id":"组织","hanzi":"组织","pinyin":"zǔzhī","meaning_vi":"tổ chức","explanation":"Vừa là động từ (组织活动 = tổ chức hoạt động) vừa là danh từ (一个组织 = một tổ chức). Phân biệt với 举行 (tiến hành, diễn ra một sự kiện).","hsk_level":3,"tags":["dong-tu","xa-hoi"],"image":"👥","examples":[{"type":"basic","zh":"学校组织了一次比赛。","pinyin":"Xuéxiào zǔzhīle yí cì bǐsài.","vi":"Nhà trường đã tổ chức một cuộc thi."},{"type":"simple","zh":"这个周末，公司组织大家去爬山。","pinyin":"Zhège zhōumò, gōngsī zǔzhī dàjiā qù páshān.","vi":"Cuối tuần này, công ty tổ chức cho mọi người đi leo núi."},{"type":"compound","zh":"他不但学习好，而且很会组织活动，所以同学们都选他当班长。","pinyin":"Tā búdàn xuéxí hǎo, érqiě hěn huì zǔzhī huódòng, suǒyǐ tóngxuémen dōu xuǎn tā dāng bānzhǎng.","vi":"Cậu ấy không những học giỏi mà còn rất giỏi tổ chức hoạt động, vì vậy các bạn đều bầu cậu ấy làm lớp trưởng."}],"related":[{"hanzi":"组成","pinyin":"zǔchéng","vi":"Tạo thành"},{"hanzi":"安排","pinyin":"ānpái","vi":"Sắp xếp"},{"hanzi":"举行","pinyin":"jǔxíng","vi":"Tiến hành"},{"hanzi":"活动","pinyin":"huódòng","vi":"Hoạt động"},{"hanzi":"参加","pinyin":"cānjiā","vi":"Tham gia"}],"traditional":"組織"},{"id":"嘴","hanzi":"嘴","pinyin":"zuǐ","meaning_vi":"miệng, mồm","explanation":"Bộ 口 (miệng). Trong khẩu ngữ 嘴 dùng nhiều hơn 口: 张嘴 (há miệng), 嘴甜 (ngọt miệng, khéo nói).","hsk_level":3,"tags":["danh-tu","co-the"],"image":"👄","examples":[{"type":"basic","zh":"张开嘴，我看看。","pinyin":"Zhāngkāi zuǐ, wǒ kànkan.","vi":"Há miệng ra, để tôi xem nào."},{"type":"simple","zh":"这个孩子的嘴很甜，见到谁都打招呼。","pinyin":"Zhège háizi de zuǐ hěn tián, jiàndào shéi dōu dǎ zhāohu.","vi":"Đứa bé này rất ngọt miệng, gặp ai cũng chào."},{"type":"compound","zh":"吃饭的时候最好闭上嘴慢慢吃，因为张着嘴吃东西很不礼貌。","pinyin":"Chīfàn de shíhou zuìhǎo bìshang zuǐ mànmàn chī, yīnwèi zhāngzhe zuǐ chī dōngxi hěn bù lǐmào.","vi":"Khi ăn tốt nhất nên ngậm miệng ăn từ từ, vì há miệng khi ăn là rất bất lịch sự."}],"related":[{"hanzi":"口","pinyin":"kǒu","vi":"Miệng"},{"hanzi":"嘴巴","pinyin":"zuǐba","vi":"Cái miệng"},{"hanzi":"牙","pinyin":"yá","vi":"Răng"},{"hanzi":"鼻子","pinyin":"bízi","vi":"Mũi"},{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"Mắt"}]},{"id":"最后","hanzi":"最后","pinyin":"zuìhòu","meaning_vi":"cuối cùng, sau cùng","explanation":"最 (nhất) + 后 (sau) → sau cùng, chỉ thứ tự cuối. Phân biệt với 终于 (cuối cùng thì…, nhấn mạnh kết quả mong đợi đã đến sau thời gian dài).","hsk_level":3,"tags":["danh-tu","thoi-gian"],"image":"🏁","examples":[{"type":"basic","zh":"他是最后一个来的。","pinyin":"Tā shì zuìhòu yí gè lái de.","vi":"Anh ấy là người đến cuối cùng."},{"type":"simple","zh":"这本书的最后一页写着作者的名字。","pinyin":"Zhè běn shū de zuìhòu yí yè xiězhe zuòzhě de míngzi.","vi":"Trang cuối của cuốn sách này có ghi tên tác giả."},{"type":"compound","zh":"我们先去了北京，然后去了上海，最后才回到河内。","pinyin":"Wǒmen xiān qùle Běijīng, ránhòu qùle Shànghǎi, zuìhòu cái huídào Hénèi.","vi":"Chúng tôi đi Bắc Kinh trước, sau đó đi Thượng Hải, cuối cùng mới về Hà Nội."}],"related":[{"hanzi":"最初","pinyin":"zuìchū","vi":"Ban đầu"},{"hanzi":"最近","pinyin":"zuìjìn","vi":"Gần đây"},{"hanzi":"终于","pinyin":"zhōngyú","vi":"Cuối cùng"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"首先","pinyin":"shǒuxiān","vi":"Trước tiên"}],"traditional":"最後"}];
